fruitcrates.code:
/**
 * Fruit crates: three slatted market crates in a row, apples in the first,
 * oranges in the second, pears in the third, six to a crate. The pointer is a
 * field: the fruit near it bounce up on their springs, the one under it
 * highest and bright, the lift falling off with distance. At rest a few sit
 * proud of the heap, one orange bright. The slider is the field's reach.
 *
 * The pattern: a field of springs (terrain); the hit unprojects onto each
 * fruit's own rest top, so a raised one never hides the one behind it.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, ringAt, run, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const CW = 42, CD = 30, CH = 13, PITCH = 48, YOFF = [0, 7, -2], R = 6.2, LIFT = 17, HIT = 8;
const REST = [[1, 0, 2.5, 0, 0.5, 0], [0, 3, 1, 0, 6, 0.5], [0.5, 0, 0, 2, 0, 1]], FAV = [1, 4];
const disc = (x, y, r, n = 20) => circ(Math.max(r, 0.05), n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.15);
  const X1 = 2 * PITCH + CW;
  fit(C, [[0, -2, 0], [X1, -2, 0], [0, CD + 7, 0], [X1, CD + 7, 0], [7, 6, CH + R * 2 + LIFT], [X1 - 7, 6, CH + R * 2 + LIFT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const fruit = [];
  for (let c = 0; c < 3; c++) {
    const x0 = c * PITCH, y0 = YOFF[c];
    const [o, i] = rings(x0, y0, x0 + CW, y0 + CD, 2.5, 1.6);
    const box = solid(g);
    put(box, prism(P, front, o, i, 0, CH));
    mk("path", { class: "nf lo", d: poly(ringAt(P, i, CH)) }, box.g);
    const mine = [];
    for (let k = 0; k < 6; k++) {
      const col = k % 3, row = Math.floor(k / 3);
      const f = { c, k, x: x0 + 7.5 + col * 13.5, y: y0 + 8 + row * 14, sp: spring(REST[c][k]), last: NaN };
      mine.push(f); fruit.push(f);
    }
    mine.sort((a, b) => a.x + a.y - (b.x + b.y)).forEach((f) => {
      const grp = mk("g", {}, g);
      f.sil = mk("path", { class: "sil" }, grp);
      f.mk = mk("path", { class: "nf lo" }, grp);
    });
    // the near walls again, over the fruit's feet, with their slat gaps
    const nr = run(o, front), lip = ringAt(P, nr, 0).concat(ringAt(P, nr, CH).reverse());
    const wall = mk("g", {}, g);
    mk("path", { class: "fo", d: poly(lip) }, wall);
    const slat = (z) => open(ringAt(P, nr, z));
    mk("path", { class: "nf lo", d: slat(CH) + slat(CH * 0.55) + slat(CH * 0.45) }, wall);
    mk("path", { class: "nf sil", d: open(ringAt(P, nr, 0)) }, wall);
  }

  function ball(x, y, z, r, rz) {
    const pts = [];
    for (let i = 0; i <= 6; i++) { const a = (i / 6) * Math.PI - Math.PI / 2; pts.push(...ringAt(P, disc(x, y, r * Math.cos(a)), z + rz + rz * Math.sin(a))); }
    return pts;
  }
  function draw(f) {
    const lift = f.sp.x;
    if (Math.abs(lift - f.last) < 1e-3) return;
    f.last = lift;
    const z = CH - 4 + lift, { x, y } = f;
    if (f.c === 0) { // apple: a squat ball, a stem in its dimple
      f.sil.setAttribute("d", poly(hull(ball(x, y, z, R, R * 0.9))));
      f.mk.setAttribute("d", seg(P(x, y, z + R * 1.6), P(x + 1, y - 1, z + R * 1.8 + 2.4)) + open(ringAt(P, run(disc(x, y, 2), front), z + R * 1.7)));
    } else if (f.c === 1) { // orange: a full ball, a navel on top
      f.sil.setAttribute("d", poly(hull(ball(x, y, z, R, R))));
      f.mk.setAttribute("d", poly(ringAt(P, disc(x, y, 1, 10), z + R * 2)));
    } else { // pear: a body and a neck, a stem
      f.sil.setAttribute("d", poly(hull(ball(x, y, z, R * 0.95, R * 0.85).concat(ball(x - 0.6, y - 0.6, z + R * 1.2, R * 0.55, R * 0.6)))));
      f.mk.setAttribute("d", seg(P(x - 0.6, y - 0.6, z + R * 2.4), P(x - 1.6, y - 1.6, z + R * 2.4 + 3)));
    }
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const f of fruit) { if (stepS(f.sp, dt)) m = true; draw(f); }
    return m;
  });
  bag.add(B.unregister);

  // the hit: each fruit tests the pointer on its own rest top, the nearest middle wins
  let pt = null;
  function retarget() {
    const ds = fruit.map((f) => {
      if (!pt) return Infinity;
      const [wx, wy] = unproj(C, pt[0], pt[1], CH - 4 + REST[f.c][f.k] + R * 2);
      return Math.hypot(wx - f.x, wy - f.y);
    });
    let a = -1;
    ds.forEach((d, k) => { if (d < HIT && (a < 0 || d < ds[a])) a = k; });
    fruit.forEach((f, k) => {
      const w = a < 0 ? 0 : k === a ? 1 : clamp(0.65 * Math.exp(-((ds[k] / reach) ** 2)), 0.06, 0.65);
      f.sp.t = a < 0 ? REST[f.c][f.k] : LIFT * w;
      f.sil.classList.toggle("hi", a < 0 ? f.c === FAV[0] && f.k === FAV[1] : k === a);
    });
    read.textContent = a < 0 ? "rest" : "crate " + (fruit[a].c + 1);
    B.wake();
  }
  retarget();
  bag.add(pointer(stage, { move: (p) => { pt = p; retarget(); }, leave: () => { pt = null; retarget(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "fruitcrates",
  means: "Three market crates of apples, oranges and pears: the fruit near the pointer bounce up, the one under it highest.",
  rules: [1, 3, 5, 6],
  range: [10, 20, 34],
  tour: [[121, 109], [183, 158], [251, 177], null],
  mount,
});

cheeseboard.code:
/**
 * Cheese board: a wooden board holding five cheeses in a row, wedges with a
 * rind line and blocks with holes, a knife and a bunch of grapes behind
 * them. The pointer picks a cheese by where it stands: it slides out toward
 * the reader and lifts, and the cheeses beside it ease out a little,
 * staggered from it. At rest one wedge is half out, bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single row (bookshelf); the pick is the
 * cheese whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, fillet, facing, fit, open, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const S = 2.05, BX = 136, BY = 58, BZ = 4, Y0 = 24, OUT = 16, LIFT = 6, FAV = 2;
const CH = [{ x: 16, w: "wedge", h: 9 }, { x: 42, w: "block", h: 11 }, { x: 68, w: "wedge", h: 8 }, { x: 94, w: "block", h: 9 }, { x: 120, w: "wedge", h: 10 }];
// a ring of samples with outward normals, from a closed polygon
const toRing = (pts) => {
  const n = pts.length; let a = 0;
  for (let i = 0; i < n; i++) { const p = pts[i], q = pts[(i + 1) % n]; a += p[0] * q[1] - q[0] * p[1]; }
  const sg = a > 0 ? 1 : -1;
  return pts.map((p, i) => {
    const b = pts[(i - 1 + n) % n], c = pts[(i + 1) % n], tx = c[0] - b[0], ty = c[1] - b[1], l = Math.hypot(tx, ty) || 1;
    return { u: p[0], v: p[1], nu: (sg * ty) / l, nv: (-sg * tx) / l };
  });
};
const tri = (cx, y, d) => toRing(fillet([[cx - 9 + d, y + 18 - d], [cx + d * 0.2, y + d * 1.6], [cx + 9 - d, y + 18 - d]], [1.6 - d * 0.3, 1.2, 1.6 - d * 0.3], 4));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, S);
  fit(C, [[0, 0, 0], [BX, BY + 6, 0], [BX, 0, 0], [0, BY + 6, 0], [16, Y0 + OUT, BZ + 16], [120, Y0, BZ + 16]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, BX, BY, 7, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  mk("path", { class: "nf lo", d: open([P(10, BY - 6, BZ), P(BX - 10, BY - 6, BZ)]) }, g);

  // behind the row: grapes on the left, a knife on the right
  const GR = [[14, 9, 2], [20, 7, 2], [26, 10, 2], [17, 13, 2], [23, 14, 2], [29, 15, 2], [20, 10, 5.6], [25, 12, 5.4]];
  mk("path", { class: "nf lo", d: open([P(12, 6, BZ + 6), P(17, 9, BZ + 7), P(20, 10, BZ + 8)]) }, g);
  GR.slice().sort((p, q) => p[0] + p[1] - q[0] - q[1] + (p[2] - q[2]) * 2).forEach(([x, y, z]) => {
    const [sx, sy] = P(x, y, BZ + z + 1.6);
    mk("ellipse", { cx: sx, cy: sy, rx: 3.3 * S, ry: 3.3 * S, class: "sil" }, g);
  });
  { const [r, i] = rings(54, 8, 100, 13, 2.4, 0.8); put(solid(g), prism(P, front, r, i, BZ, BZ + 0.8)); }
  { const [r, i] = rings(100, 8.6, 124, 12.4, 1.6, 0.6); put(solid(g), prism(P, front, r, i, BZ, BZ + 3.4)); }

  const items = CH.map((c, k) => {
    const el = solid(g), rind = mk("path", { class: "nf lo" }, el.g);
    const holes = c.w === "block" ? [0, 1, 2].map(() => flatDot(el.g, C, 1.1, "dot off")) : [];
    return { k, ...c, el, rind, holes, y: tween(k === FAV ? OUT * 0.55 : 0), z: tween(0), last: "" };
  });

  function draw(it, y, z) {
    const key = y.toFixed(2) + "," + z.toFixed(2);
    if (key === it.last) return;
    it.last = key;
    const yy = Y0 + y, z0 = BZ + z, z1 = z0 + it.h;
    if (it.w === "wedge") {
      put(it.el, prism(P, front, tri(it.x, yy, 0), tri(it.x, yy, 1.4), z0, z1));
      it.rind.setAttribute("d", seg(P(it.x - 7.6, yy + 18, z1 - 2), P(it.x + 7.6, yy + 18, z1 - 2)));
    } else {
      const [r, i] = rings(it.x - 8, yy + 1, it.x + 8, yy + 17, 2.4, 1.2);
      put(it.el, prism(P, front, r, i, z0, z1));
      [[-3, 6], [3, 9], [-1, 13]].forEach(([dx, dy], j) => place(it.holes[j], P(it.x + dx, yy + dy, z1)));
    }
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.y, now), tval(it.z, now)); if (!tdone(it.y, now) || !tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, Y0 + 9, BZ + it.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 20 && Math.abs(mids[best][1] - sy) < 45 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a);
      const y = a < 0 ? (k === FAV ? OUT * 0.55 : 0) : d === 0 ? OUT : d === 1 ? 3.5 : 0;
      const delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(it.y, y, now, delay); tset(it.z, a === k ? LIFT : d === 1 ? 1 : 0, now, delay);
      it.el.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "cheese " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "cheeseboard",
  means: "Five cheeses on a wooden board: the one under the pointer slides out and lifts, and its neighbours ease out a little.",
  rules: [1, 2, 5, 8],
