barstools.code:
/**
 * Bar stools: five round stools in front of a bar counter, each a floor
 * disc, a column, a round seat and a low back on a short post. The pointer
 * is what the bar turns to: every seat swivels on its own spring to face it,
 * and the stool nearest it is bright and rises a little. At rest the seats
 * face the counter, each a little askew, one bright. The slider is how
 * quickly the seats follow (a stiffer or softer spring).
 *
 * The pattern: a continuous aim (officechairs); the hit is on the plane of
 * the seats' rest tops, which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, unproj, spring, stepS, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 34, SY = 18, SEAT = 30, RISE = 8, FAV = 3;
const SKEW = [-20, 14, -6, 24, -14];
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const turn = (ring, a, cx, cy) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.62);
  fit(C, [[-10, -30, 0], [150, 30, 0], [150, -30, 0], [-10, 30, 0], [-10, -30, 48], [150, -30, 48], [0, SY, SEAT + RISE + 16]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the counter: a body under an overhanging top, a foot rail line along its front
  { const [r, i] = rings(-6, -26, 146, -8, 3, 1.2); put(solid(g), prism(P, front, r, i, 0, 42)); }
  { const [r, i] = rings(-10, -30, 150, -3, 3, 1.4); put(solid(g), prism(P, front, r, i, 42, 46)); }
  { const [r, i] = rings(-4, -6.5, 144, -4.5, 1, 0.4); put(solid(g), prism(P, front, r, i, 8, 9.6)); }

  const SEATR = [disc(0, 0, 10, 40), disc(0, 0, 8.6, 40)];
  const POST = rings(-9.6, -1.4, -7.4, 1.4, 0.7, 0.3), BACK = rings(-11, -7.5, -8.4, 7.5, 1.2, 0.6);
  const stools = [];
  for (let k = 0; k < N; k++) {
    const cx = 6 + k * STEP, cy = SY, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(cx, cy, 8, 36), disc(cx, cy, 6.8, 36), 0, 1.6));
    put(solid(grp), prism(P, front, disc(cx, cy, 1.8, 16), null, 1.6, SEAT));
    put(solid(grp), prism(P, front, disc(cx, cy, 6.5, 32), null, 12, 13.2));
    const rest = -Math.PI / 2 + SKEW[k] * (Math.PI / 180);
    const st = { k, cx, cy, rest, sp: spring(rest, { k: 100 * value, c: 18 * Math.sqrt(value) }), up: tween(0), drawn: "" };
    st.col = solid(grp); st.seat = solid(grp); st.back = mk("g", {}, grp); st.post = solid(st.back); st.plate = solid(st.back); st.backFirst = null;
    stools.push(st);
  }

  function draw(st, now) {
    const a = st.sp.x, u = tval(st.up, now), key = a.toFixed(4) + "," + u.toFixed(2);
    if (key === st.drawn) return;
    st.drawn = key;
    const T = (r) => turn(r, a, st.cx, st.cy), z = SEAT + u;
    put(st.col, prism(P, front, disc(st.cx, st.cy, 1.8, 16), null, SEAT - 1, z));
    put(st.seat, prism(P, front, T(SEATR[0]), T(SEATR[1]), z, z + 4));
    put(st.post, prism(P, front, T(POST[0]), null, z + 1, z + 9));
    put(st.plate, prism(P, front, T(BACK[0]), T(BACK[1]), z + 8, z + 15));
    const backFirst = Math.cos(a) + Math.sin(a) > 0;
    if (backFirst !== st.backFirst) {
      st.backFirst = backFirst;
      if (backFirst) st.back.after(st.col.g); else st.seat.g.after(st.back);
    }
  }

  const B = register(stage, (dt, now) => {
    let m = false;
    for (const st of stools) { if (stepS(st.sp, dt) || !tdone(st.up, now)) m = true; draw(st, now); }
    return m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    const now = performance.now();
    let near = null, bd = Infinity;
    for (const st of stools) {
      if (over) {
        const d = Math.hypot(over[0] - st.cx, over[1] - st.cy);
        if (d < bd) { bd = d; near = st; }
        const aim = d < 4 ? st.sp.t : Math.atan2(over[1] - st.cy, over[0] - st.cx);
        st.sp.t = st.sp.t + wrap(aim - st.sp.t);
      } else st.sp.t = st.sp.t + wrap(st.rest - st.sp.t);
    }
    for (const st of stools) {
      const on = over ? st === near : st.k === FAV;
      tset(st.up, over && st === near ? RISE : 0, now, 0);
      st.plate.sil.classList.toggle("hi", on);
      st.seat.sil.classList.toggle("hi", on);
    }
    read.textContent = near ? "stool " + (near.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], SEAT + 4);
      over = x < -24 || x > 166 || y < -16 || y > 52 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const st of stools) { st.sp.k = 100 * v; st.sp.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "barstools",
  means: "Five bar stools at a counter: every seat swivels to face the pointer, and the nearest one is bright and rises a little.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[106, 128], [184, 167], [262, 206], null],
  mount,
});

cocktails.code:
/**
 * Cocktails: five glasses in a row on a bar top, a martini, a coupe, a
 * highball, a tumbler and a flute, each with its rim and the line of the
 * drink inside. The pointer picks a glass by where it stands: it lifts and
 * its drink rises toward the rim, and the glasses beside it lift a little,
 * staggered from it. At rest one glass is raised, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (cloches); the pick is the glass
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, circ, facing, fit, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const STEP = 34, X0 = 18, GY = 20, TZ = 5, LIFT = 13, FAV = 2;
const coupe = []; for (let i = 0; i <= 6; i++) { const t = (i / 6) * (Math.PI / 2); coupe.push([0.8 + 10.5 * Math.sin(t), 7 * (1 - Math.cos(t))]); }
// each glass: a stem height (0 for none), a foot radius, and the bowl's profile [r, z] from its bottom up
const GL = [
  { stem: 12, foot: 6.5, prof: [[0.8, 0], [13, 11]] },
  { stem: 11, foot: 6.5, prof: coupe },
  { stem: 0, foot: 0, prof: [[6.5, 0], [6.5, 1.5], [7, 31]] },
  { stem: 0, foot: 0, prof: [[8.5, 0], [8.5, 1.5], [9, 15]] },
  { stem: 10, foot: 5.5, prof: [[1.4, 0], [4.4, 6], [5, 24]] },
];
const X1 = X0 * 2 + STEP * 4;
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const rAt = (prof, z) => { for (let i = 1; i < prof.length; i++) { const [r0, z0] = prof[i - 1], [r1, z1] = prof[i]; if (z <= z1) return r0 + ((r1 - r0) * (z - z0)) / (z1 - z0 || 1); } return prof[prof.length - 1][0]; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, 0, 0], [X1, 40, 0], [X1, 0, 0], [0, 40, 0], [X0 + 2 * STEP, GY, TZ + 32 + LIFT], [X0, GY, TZ + 24 + LIFT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, X1, 40, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, TZ));

  const items = GL.map((gl, k) => {
    const grp = mk("g", {}, g), it = { k, ...gl, x: X0 + k * STEP, top: gl.prof[gl.prof.length - 1][1] };
    if (gl.stem) { it.footS = solid(grp); it.stemS = solid(grp); }
    it.bowl = mk("path", { class: "sil" }, grp);
    it.rim = mk("path", { class: "nf lo" }, grp);
    it.drink = mk("path", { class: "nf lo" }, grp);
    it.z = tween(k === FAV ? LIFT * 0.6 : 0); it.f = tween(0.5); it.last = "";
    return it;
  });

  function draw(it, lift, f) {
    const key = lift.toFixed(2) + "," + f.toFixed(3);
    if (key === it.last) return;
    it.last = key;
    const x = it.x, z0 = TZ + lift;
    if (it.stem) {
      put(it.footS, prism(P, front, disc(x, GY, it.foot, 36), null, z0, z0 + 0.8));
      put(it.stemS, prism(P, front, disc(x, GY, 0.8, 12), null, z0 + 0.8, z0 + it.stem));
    }
    const b = z0 + it.stem, pts = [];
    for (const [r, z] of it.prof) pts.push(...ringAt(P, disc(x, GY, r, 36), b + z));
    it.bowl.setAttribute("d", poly(hull(pts)));
    it.rim.setAttribute("d", poly(ringAt(P, disc(x, GY, it.prof[it.prof.length - 1][0] - 0.6, 36), b + it.top)));
    const dz = it.top * f;
    it.drink.setAttribute("d", poly(ringAt(P, disc(x, GY, rAt(it.prof, dz) - 0.8, 36), b + dz)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now), tval(it.f, now)); if (!tdone(it.z, now) || !tdone(it.f, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, GY, TZ + (it.stem + it.top) / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 22 && Math.abs(mids[best][1] - sy) < 50 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : d === 0 ? LIFT : d === 1 ? 3 : 0;
      const delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(it.z, z, now, delay); tset(it.f, a === k ? 0.85 : 0.5, now, delay);
      it.bowl.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "glass " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "cocktails",
  means: "Five cocktail glasses on a bar top: the glass under the pointer lifts and its drink rises, and its neighbours lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[153, 140], [247, 178], [294, 201], null],
  mount,
});

sofacushions.code:
/**
 * Sofa cushions: a three-seat sofa with its arms, back panel, three seat
 * cushions and three back cushions. The pointer sits down near them: the
 * cushions near it puff up, each on its own spring, the one under it puffiest
 * and bright. At rest the cushions are left unevenly plumped, the middle one
 * bright. The slider is the reach, in cushion widths.
 *
 * The pattern: a continuous field (terrain) along one row; the hit is on the
 * plane of the seat cushions' resting tops, which never moves.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, W = 30, X1 = N * W, AR = 9, D = 40, BASE = 12, SEAT = 18, BACK = 33, PANEL = 36, ARM = 26;
const PMAX = 6, REST = [2.2, 4, 1.2], FAV = 1;
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value * W, over = null;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[-AR, 0, 0], [X1 + AR, D, 0], [-AR, D, 0], [X1 + AR, 0, PANEL], [-AR, 0, PANEL], [X1 + AR, D, ARM]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, o, i, z0, z1)); };

  block(-AR, 0, 0, D, 3.5, 1.2, 0, ARM);
  block(0, 0, X1, D, 2, 1, 0, BASE);
  block(0, 0, X1, 9, 3, 1.2, BASE, PANEL);
  const cush = [];
  for (let k = 0; k < N; k++) {
    const [o, i] = rings(k * W + 0.8, 9.5, (k + 1) * W - 0.8, 16, 3, 1);
    cush.push({ k, cx: (k + 0.5) * W, back: { el: solid(g), o, i }, sp: spring(REST[k], { eps: 0.02 }), drawn: NaN });
  }
  for (const c of cush) {
    const [o, i] = rings(c.k * W + 0.8, 16.5, (c.k + 1) * W - 0.8, D - 0.5, 4, 1.4);
    c.seat = { el: solid(g), o, i };
  }
  block(X1, 0, X1 + AR, D, 3.5, 1.2, 0, ARM);

  function draw(c) {
    const p = clamp(c.sp.x, 0, PMAX);
    if (p === c.drawn) return;
    c.drawn = p;
    put(c.back.el, prism(P, front, c.back.o, c.back.i, BASE, BACK + p * 0.8));
    put(c.seat.el, prism(P, front, c.seat.o, c.seat.i, BASE, SEAT + p));
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const c of cush) { if (stepS(c.sp, dt)) m = true; draw(c); }
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    const hit = over ? cush[clamp(Math.floor(over[0] / W), 0, N - 1)] : null;
    for (const c of cush) {
      c.sp.t = !over ? REST[c.k] : c === hit ? PMAX : PMAX * 0.8 * falloff(Math.abs(c.cx - over[0]) / RAD);
      const on = over ? c === hit : c.k === FAV;
      c.seat.el.sil.classList.toggle("hi", on);
      c.back.el.sil.classList.toggle("hi", on);
    }
    read.textContent = hit ? "cushion " + (hit.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], SEAT);
      over = x > -AR && x < X1 + AR && y > -30 && y < D + 8 ? [clamp(x, 0, X1 - 0.01), y] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v * W; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "sofacushions",
  means: "A three-seat sofa: the cushions near the pointer puff up, the one under it puffiest and bright.",
  rules: [1, 3, 5, 9],
  range: [0.5, 1, 1.6],
  tour: [[112, 139], [187, 177], [261, 214], null],
  mount,
});

floorlamps.code:
/**
 * Floor lamps: four lamps in a row, each its own kind: an arc lamp reaching
 * over, a tripod with a drum shade, a straight pole with a tall cone, and a
 * reading lamp on a bent arm. The pointer is what they light: every shade
 * tilts toward it on its own spring, and the lamp nearest it is bright. At
 * rest the shades hang a little askew, the third lamp bright. The slider is
 * how quickly the shades follow (a stiffer or softer spring).
 *
 * The pattern: a continuous aim (spotlights' can, on a tilt per lamp); the hit
 * is on the floor's plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const XS = [-66, -22, 22, 66], TMAX = 0.75, FAV = 2;
// per lamp: pivot height, shade length, top and bottom radius, rest tilt
const KIND = [
  { h: 70, len: 11, rb: 3, rf: 9, rest: [0.1, 0.25] },
  { h: 56, len: 13, rb: 9, rf: 10, rest: [-0.12, 0.05] },
  { h: 66, len: 16, rb: 4, rf: 10, rest: [0.2, -0.1] },
  { h: 52, len: 9, rb: 3, rf: 6, rest: [-0.3, 0.2] },
];
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-90, 24, 0], [-90, 24, 96], [80, 12, 0], [-80, 12, 0], [80, -12, 0], [-80, -16, 80], [70, 0, 70]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const opt = { k: 100 * value, c: 18 * Math.sqrt(value) };

  const lamps = XS.map((x, k) => {
    const K = KIND[k], piv = [x, 0, K.h], grp = mk("g", {}, g);
    if (k === 0) {
      const bx = x - 22, by = 22, pts = [];
      put(solid(grp), prism(P, front, disc(bx, by, 7), disc(bx, by, 5.8), 0, 2));
      for (let i = 0; i <= 16; i++) { const t = i / 16, a = t * Math.PI * 0.8; pts.push(P(lerpN(bx, x, t), lerpN(by, 0, t), 2 + Math.sin(a) * 76 + t * (K.h + 2 - 2 - Math.sin(Math.PI * 0.8) * 76))); }
      mk("path", { class: "nf sil", d: open(pts) }, grp);
    } else if (k === 1) {
      let d = "";
      for (let i = 0; i < 3; i++) { const a = 0.5 + (i / 3) * Math.PI * 2; d += seg(P(x, 0, 36), P(x + 13 * Math.cos(a), 13 * Math.sin(a), 0)); }
      mk("path", { class: "nf sil", d: d + seg(P(x, 0, 36), P(x, 0, K.h)) }, grp);
    } else if (k === 2) {
      put(solid(grp), prism(P, front, disc(x, 0, 8), disc(x, 0, 6.8), 0, 1.8));
      put(solid(grp), prism(P, front, disc(x, 0, 1.1, 12), null, 1.8, K.h));
    } else {
      put(solid(grp), prism(P, front, disc(x, 0, 6.5), disc(x, 0, 5.4), 0, 2));
      mk("path", { class: "nf sil", d: seg(P(x, 0, 2), P(x - 4, 0, 40)) + seg(P(x - 4, 0, 40), P(x, 0, K.h)) }, grp);
    }
    const body = mk("path", { class: "sil" }, grp), rim = mk("path", { class: "nf lo" }, grp);
    return { k, K, piv, body, rim, sx: spring(K.rest[0], opt), sy: spring(K.rest[1], opt), key: "" };
  });

  function lerpN(a, b, t) { return a + (b - a) * t; }

  function draw(l) {
    const key = l.sx.x.toFixed(3) + "," + l.sy.x.toFixed(3);
    if (key === l.key) return;
    l.key = key;
    const n = Math.hypot(l.sx.x, l.sy.x, 1), d = [l.sx.x / n, l.sy.x / n, -1 / n];
    let u = [d[1], -d[0], 0];
    const un = Math.hypot(...u);
    u = un < 1e-6 ? [1, 0, 0] : u.map((x) => x / un);
    const v = [u[1] * d[2] - u[2] * d[1], u[2] * d[0] - u[0] * d[2], u[0] * d[1] - u[1] * d[0]];
    const ring = (off, r) => Array.from({ length: 28 }, (_, i) => {
      const t = (i / 28) * Math.PI * 2, q = (j) => l.piv[j] + d[j] * off + r * (Math.cos(t) * u[j] + Math.sin(t) * v[j]);
      return P(q(0), q(1), q(2));
    });
    const top = ring(0, l.K.rb), bot = ring(l.K.len, l.K.rf);
    l.body.setAttribute("d", poly(hull(top.concat(bot))));
    l.rim.setAttribute("d", poly(ring(l.K.len - 1.2, l.K.rf - 0.4)));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const l of lamps) { const a = stepS(l.sx, dt), b = stepS(l.sy, dt); if (a || b) m = true; draw(l); }
    return m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = null, bd = Infinity;
    for (const l of lamps) {
      if (!over) { l.sx.t = l.K.rest[0]; l.sy.t = l.K.rest[1]; continue; }
      const dx = over[0] - l.piv[0], dy = over[1] - l.piv[1], dd = Math.hypot(dx, dy);
      if (dd < bd) { bd = dd; near = l; }
      const t = Math.min(TMAX, dd / l.K.h) / (dd || 1);
      l.sx.t = dx * t; l.sy.t = dy * t;
    }
    for (const l of lamps) l.body.classList.toggle("hi", over ? l === near : l.k === FAV);
    read.textContent = near ? "lamp " + (near.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      over = Math.abs(x) > 110 || Math.abs(y) > 70 ? null : [clamp(x, -90, 90), clamp(y, -40, 40)];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const l of lamps) for (const s of [l.sx, l.sy]) { s.k = 100 * v; s.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "floorlamps",
  means: "Four floor lamps of different kinds: every shade tilts toward the pointer, and the nearest lamp is bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[110, 190], [226, 252], [300, 270], null],
  mount,
});

curtains.code:
/**
 * Curtains: a window on a wall, four panes and a sill, under a rod with two
 * finials and two folded curtain panels. The pointer is where to look out:
 * the panels draw apart around its x, each leading edge on its own spring,
 * and the folds gather as a panel narrows. At rest the curtains stand a
 * little open, off centre, the right leading edge bright. The slider is how
 * wide the opening is.
 *
 * The pattern: a continuous gap (two springs); the hit is on the curtains'
 * hanging plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, open, poly, prism, proj, rings, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const WX = 40, Z0 = 22, Z1 = 92, XR = 60, YC = 7, ZT = 100, ZB = 14, NF = 7, CL = 120;
const REST = [-14, 4];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let HALF = value * 20, over = null;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-70, -4, 0], [70, -4, 0], [-70, 0, 112], [70, 0, 112], [-70, 12, 0], [70, 12, 0]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [wo, wi] = rings(-70, -4, 70, 0, 2, 0.8);
  put(solid(g), prism(P, front, wo, wi, 0, 112));
  const F = (x, z) => P(x, 0, z);
  mk("path", { class: "nf", d: poly([F(-WX, Z0), F(WX, Z0), F(WX, Z1), F(-WX, Z1)]) }, g);
  mk("path", { class: "nf lo", d: poly([F(-WX + 3, Z0 + 3), F(WX - 3, Z0 + 3), F(WX - 3, Z1 - 3), F(-WX + 3, Z1 - 3)]) + seg(F(0, Z0 + 3), F(0, Z1 - 3)) + seg(F(-WX + 3, 57), F(WX - 3, 57)) }, g);
  const [so, si] = rings(-WX - 4, 0, WX + 4, 5, 1.2, 0.5);
  put(solid(g), prism(P, front, so, si, Z0 - 3, Z0));

  const panels = [-1, 1].map((s) => ({ s, el: mk("path", { class: "sil" }, g), folds: mk("path", { class: "nf lo" }, g), lead: mk("path", { class: "nf" }, g) }));
  const [ro, ri] = rings(-XR - 2, YC - 1.2, XR + 2, YC + 1.2, 1.2, 0.4);
  put(solid(g), prism(P, front, ro, ri, ZT, ZT + 2.4));
  for (const x of [-XR - 4, XR + 4]) put(solid(g), prism(P, front, circ(2.6, 20).map((q) => ({ ...q, u: q.u + x, v: q.v + YC })), null, ZT - 1.4, ZT + 3.8));

  const eL = spring(REST[0]), eR = spring(REST[1]);
  let drawn = "";
  /** One panel from the outer end xo to its leading edge xe: a zigzag of NF folds, deeper as it gathers. */
  function panel(pn, xo, xe) {
    const w = Math.abs(xe - xo) / NF, amp = Math.min(6, Math.sqrt(Math.max(0, (CL / NF) ** 2 - w * w)) / 2);
    const xs = Array.from({ length: NF + 1 }, (_, i) => xo + (xe - xo) * (i / NF));
    const ys = xs.map((_, i) => YC + (i % 2 ? amp : -amp) * 0.9);
    const top = xs.map((x, i) => P(x, ys[i], ZT - 1)), bot = xs.map((x, i) => P(x, ys[i], ZB)).reverse();
    pn.el.setAttribute("d", poly(top.concat(bot)));
    pn.folds.setAttribute("d", xs.slice(1, -1).map((x, i) => (i % 2 ? "" : seg(P(x, ys[i + 1], ZT - 1), P(x, ys[i + 1], ZB)))).join(""));
    pn.lead.setAttribute("d", open([P(xe, ys[NF], ZT - 1), P(xe, ys[NF], ZB)]));
  }
  function draw() {
    const key = eL.x.toFixed(2) + "," + eR.x.toFixed(2);
    if (key === drawn) return;
    drawn = key;
    panel(panels[0], -XR, clamp(eL.x, -XR + 6, eR.x));
    panel(panels[1], XR, clamp(eR.x, eL.x, XR - 6));
  }
  const B = register(stage, (dt) => { const a = stepS(eL, dt), b = stepS(eR, dt); draw(); return a || b; });
  bag.add(B.unregister);

  function retarget() {
    if (over === null) { eL.t = REST[0]; eR.t = REST[1]; } else {
      const c = clamp(over, -XR + 6 + HALF, XR - 6 - HALF);
      eL.t = c - HALF; eR.t = c + HALF;
    }
    panels[0].lead.classList.toggle("hi", over !== null);
    panels[1].lead.classList.toggle("hi", true);
    const pct = (clamp(eR.t, -WX, WX) - clamp(eL.t, -WX, WX)) / (2 * WX);
    read.textContent = over === null ? "rest" : "open " + Math.round(pct * 100) + "%";
    B.wake();
  }

  // the hanging plane y = YC: P is linear there in x and z, so invert it
  const o = P(0, YC, 0), ex = P(1, YC, 0).map((v, i) => v - o[i]), ez = P(0, YC, 1).map((v, i) => v - o[i]);
  const det = ex[0] * ez[1] - ex[1] * ez[0];
  bag.add(pointer(stage, {
    move: (p) => {
      const dx = p[0] - o[0], dy = p[1] - o[1], x = (dx * ez[1] - dy * ez[0]) / det, z = (ex[0] * dy - ex[1] * dx) / det;
      over = Math.abs(x) < XR + 6 && z > ZB - 8 && z < ZT + 6 ? clamp(x, -XR, XR) : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { HALF = v * 20; if (over !== null) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "curtains",
  means: "A window with two folded curtains: the panels draw apart around the pointer, opening the window there.",
  rules: [1, 3, 5, 8],
  range: [0.6, 1, 1.5],
  tour: [[119, 126], [210, 172], [273, 203], null],
  mount,
});

candles.code:
/**
 * Candles: six pillar candles of different heights on a long tray, each with
 * a wick and a teardrop flame. The pointer is a warm hand: flames near it
 * grow taller, each on its own spring, falling off with screen distance, and
 * the flame over the candle under it is tallest and bright. At rest one flame
 * is bright. The slider is the reach of the field.
 *
 * The pattern: a continuous field (terrain) along one row; the pick is the
 * candle whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, circ, facing, fit, prism, proj, seg, rings, spring, stepS, r2,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, STEP = 19, H = [34, 48, 26, 40, 54, 30], R = [7, 7.5, 6.5, 8, 7, 6], Y = [2, -3, 4, -2, 3, -1];
const FR = [8, 10, 7, 9, 11, 8], GROW = 16, FAV = 3, TZ = 4, S = 2.05;
const X1 = (N - 1) * STEP + 12;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const falloff = (u) => (u <= 0 ? 1 : u <= 0.42 ? 1 - (u / 0.42) * 0.69 : u <= 1 ? 0.31 - ((u - 0.42) / 0.58) * 0.22 : 0.09);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, S);
  const pts = [[-12, -14, 0], [X1, 14, 0], [X1, -14, 0], [-12, 14, 0]];
  H.forEach((h, k) => pts.push([k * STEP, Y[k], TZ + h + 3 + FR[k] + GROW]));
  fit(C, pts, 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(-12, -14, X1, 14, 6, 2);
  put(solid(g), prism(P, front, tr, ti, 0, TZ));

  const cs = H.map((h, k) => {
    const x = k * STEP, y = Y[k], top = TZ + h, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, y, R[k]), disc(x, y, R[k] - 1.4), TZ, top));
    mk("path", { d: seg(P(x, y, top), P(x, y, top + 2.4)), class: "nf lo" }, grp);
    const flame = mk("path", { class: "sil" }, grp);
    return { k, x, y, top, flame, sp: spring(FR[k], { eps: 0.02 }), last: NaN, mid: P(x, y, TZ + h / 2) };
  });

  const rr = 2.2 * S;
  function draw(c) {
    const h = c.sp.x;
    if (h === c.last) return;
    c.last = h;
    const [bx, by] = P(c.x, c.y, c.top + 2.4), [tx, ty] = P(c.x, c.y, c.top + 2.4 + h);
    const cy = by - rr, mid = cy - (cy - ty) * 0.55;
    c.flame.setAttribute("d", `M${r2(tx)} ${r2(ty)}C${r2(tx + rr * 0.25)} ${r2(mid)} ${r2(bx + rr)} ${r2(cy - rr * 0.8)} ${r2(bx + rr)} ${r2(cy)}` +
      `A${r2(rr)} ${r2(rr)} 0 0 1 ${r2(bx - rr)} ${r2(cy)}C${r2(bx - rr)} ${r2(cy - rr * 0.8)} ${r2(tx - rr * 0.25)} ${r2(mid)} ${r2(tx)} ${r2(ty)}Z`);
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const c of cs) { if (stepS(c.sp, dt)) m = true; draw(c); }
    return m;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    cs.forEach((c, k) => { const d = Math.abs(c.mid[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 15 && Math.abs(cs[best].mid[1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function aim(p) {
    const a = p ? hit(p) : -1;
    cs.forEach((c) => {
      c.sp.t = a < 0 ? FR[c.k] : FR[c.k] + GROW * (c.k === a ? 1 : 0.85 * falloff(Math.abs(c.mid[0] - p[0]) / reach));
    });
    if (a !== act) {
      act = a;
      cs.forEach((c) => c.flame.classList.toggle("hi", c.k === (a < 0 ? FAV : a)));
      read.textContent = a < 0 ? "rest" : "candle " + (a + 1);
    }
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "candles",
  means: "Six pillar candles on a tray: flames near the pointer grow taller, the one under it tallest and bright.",
  rules: [1, 3, 4, 8],
  range: [30, 60, 110],
  tour: [[128, 126], [217, 147], [270, 200], null],
  mount,
});

petbowls.code:
/**
 * Pet bowls: a rounded mat holding three tapered bowls of different sizes,
 * food, water and treats, each with a level inside, and a scoop lying by
 * them. The pointer picks a bowl by where it stands: its level rises and it
 * lifts off the mat, and the bowls beside it lift a little, staggered from
 * it. At rest the water bowl is bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, facing, fit, hull, lerp, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BX = [24, 68, 110], BY = [26, 30, 25], RT = [16, 18, 12], RF = [11, 13, 8], BH = [10, 12, 8];
const LV = [0.35, 0.6, 0.2], LIFT = 8, FAV = 1, MZ = 1.6, MX = 136, MY = 56;
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[0, 0, 0], [MX, MY, 0], [MX, 0, 0], [0, MY, 0], [BX[1], BY[1], MZ + BH[1] + LIFT + 2]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [mr, mi] = rings(0, 0, MX, MY, 9, 2.2);
  put(solid(g), prism(P, front, mr, mi, 0, MZ));

  const bowls = BX.map((x, k) => {
    const el = solid(g), level = mk("path", { class: "nf lo" }, el.g);
    return { k, x, y: BY[k], el, level, z: tween(k === FAV ? 4 : 0), l: tween(LV[k]), last: "", mid: P(x, BY[k], MZ + BH[k] / 2) };
  });
  // the scoop: a small cup lying near the front corner, its handle running off to the right
  {
    const sx = 108, sy = 47;
    const [hr, hi] = rings(sx + 3, sy - 1.6, sx + 22, sy + 1.6, 1.6, 0.6);
    put(solid(g), prism(P, front, hr, hi, MZ, MZ + 1.6));
    put(solid(g), { sil: poly(hull(ringAt(P, disc(sx, sy, 3.5, 20), MZ).concat(ringAt(P, disc(sx, sy, 5.5, 20), MZ + 5)))), crease: poly(ringAt(P, disc(sx, sy, 4.4, 20), MZ + 5)) });
  }

  function draw(b, z, l) {
    const key = z.toFixed(2) + "," + l.toFixed(3);
    if (key === b.last) return;
    b.last = key;
    const k = b.k, z0 = MZ + z, z1 = z0 + BH[k];
    const foot = disc(b.x, b.y, RF[k]), top = disc(b.x, b.y, RT[k]);
    b.el.sil.setAttribute("d", poly(hull(ringAt(P, foot, z0).concat(ringAt(P, top, z1)))));
    b.el.cr.setAttribute("d", poly(ringAt(P, disc(b.x, b.y, RT[k] - 1.6), z1)));
    const lz = z0 + 1.5 + l * (BH[k] - 3), lr = lerp(RF[k] - 2, RT[k] - 2.2, (lz - z0) / BH[k]);
    b.level.setAttribute("d", open(ringAt(P, run(disc(b.x, b.y, lr), (s) => !front(s)), lz)));
  }

  const B = register(stage, (_dt, now) => {
    let m = false;
    for (const b of bowls) { draw(b, tval(b.z, now), tval(b.l, now)); if (!tdone(b.z, now) || !tdone(b.l, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    bowls.forEach((b, k) => { const d = Math.abs(b.mid[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 28 && Math.abs(bowls[best].mid[1] - sy) < 45 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    bowls.forEach((b, k) => {
      const d = Math.abs(k - a), delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(b.z, a < 0 ? (k === FAV ? 4 : 0) : d === 0 ? LIFT : d === 1 ? 2.5 : 0, now, delay);
      tset(b.l, a < 0 ? LV[k] : d === 0 ? 0.92 : Math.min(0.92, LV[k] + 0.12), now, delay);
      b.el.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bowl " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "petbowls",
  means: "Three pet bowls and a scoop on a mat: the bowl under the pointer fills and lifts, its neighbours lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[139, 114], [197, 145], [265, 179], null],
  mount,
});

monitors.code:
/**
 * Monitors: a desk with three monitors on round stands, a keyboard and a
 * mouse in front. The pointer is what the desk looks at: every screen swivels
 * on its own spring toward the pointer, and the nearest one is bright, a few
 * dim lines on its face. At rest the screens stand a little askew, the middle
 * one lit. The slider is how quickly the screens follow.
 *
 * The pattern: a continuous aim (officechairs); the hit is on the desk's
 * plane, which never moves, read along the row.
 */
const {
  Cam, circ, clamp, facing, fit, open, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const Q = -Math.PI / 4, cQ = Math.cos(Q), sQ = Math.sin(Q);
const W = (u, v) => [u * cQ - v * sQ, u * sQ + v * cQ];
const turn = (ring, a, cx, cy) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const N = 3, GAP = 42, MV = -12, TOP = 3, PZ0 = 15, PZ1 = 37, HW = 16, A0 = Math.PI / 4, REACH = 0.9;
const SKEW = [0.34, -0.06, -0.3], FAV = 1;
const LINES = [[31, 9], [27, 13], [23, 3], [19, 7]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.05);
  const ext = [];
  for (const [u, v] of [[-70, -34], [70, -34], [-70, 30], [70, 30]]) ext.push([...W(u, v), -28], [...W(u, v), TOP]);
  for (const u of [-GAP - HW, GAP + HW]) for (const v of [MV - HW, MV + HW]) ext.push([...W(u, v), PZ1]);
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const R = (r) => turn(r, Q, 0, 0);

  // the desk: four legs, then the top over them
  for (const [u, v] of [[-64, -28], [64, -28], [-64, 24], [64, 24]]) {
    const [x, y] = W(u, v), [r] = rings(x - 2, y - 2, x + 2, y + 2, 1.2, 0.5);
    put(solid(g), prism(P, front, r, null, -28, 0));
  }
  const [dr, di] = rings(-70, -34, 70, 30, 5, 1.6);
  put(solid(g), prism(P, front, R(dr), R(di), 0, TOP));

  const PANEL = rings(-1.6, -HW, 1.6, HW, 1.2, 0.6);
  const mons = [];
  for (let k = 0; k < N; k++) {
    const u = (k - 1) * GAP, [cx, cy] = W(u, MV), rest = A0 + SKEW[k];
    const grp = mk("g", {}, g);
    const base = circ(7, 32).map((q) => ({ ...q, u: q.u + cx, v: q.v + cy }));
    put(solid(grp), prism(P, front, base, circ(5.8, 32).map((q) => ({ ...q, u: q.u + cx, v: q.v + cy })), TOP, TOP + 1.6));
    put(solid(grp), prism(P, front, circ(1.7, 16).map((q) => ({ ...q, u: q.u + cx, v: q.v + cy })), null, TOP + 1.6, PZ0 + 4));
    const m = { k, u, cx, cy, rest, panel: solid(grp), drawn: NaN, lit: false };
    m.lines = mk("path", { class: "nf lo" }, grp);
    m.sp = spring(rest, { k: 100 * value, c: 18 * Math.sqrt(value) });
    mons.push(m);
  }
  // the keyboard and the mouse, nearest the viewer
  const [kr, ki] = rings(-25, 8, 25, 22, 2.4, 0.9);
  const kb = solid(g);
  put(kb, prism(P, front, R(kr), R(ki), TOP, TOP + 2));
  const rows = [12, 15, 18].map((v) => open([P(...W(-21, v), TOP + 2), P(...W(21, v), TOP + 2)])).join("");
  mk("path", { class: "nf lo", d: rows }, kb.g);
  const [mr, mi] = rings(33, 11, 40, 21, 3.4, 1);
  put(solid(g), prism(P, front, R(mr), R(mi), TOP, TOP + 2.6));

  function draw(m) {
    const a = m.sp.x;
    if (Math.abs(a - m.drawn) < 1e-4 && m.lit === m.panel.sil.classList.contains("hi")) return;
    m.drawn = a; m.lit = m.panel.sil.classList.contains("hi");
    put(m.panel, prism(P, front, turn(PANEL[0], a, m.cx, m.cy), turn(PANEL[1], a, m.cx, m.cy), PZ0, PZ1));
    const c = Math.cos(a), s = Math.sin(a), at = (v, z) => P(m.cx + 1.7 * c - v * s, m.cy + 1.7 * s + v * c, z);
    const show = m.lit && front({ u: 0, v: 0, nu: c, nv: s });
    m.lines.setAttribute("d", show ? LINES.map(([z, e]) => open([at(-12, z), at(e, z)])).join("") : "");
  }

  const B = register(stage, (dt) => {
    let mv = false;
    for (const m of mons) { if (stepS(m.sp, dt)) mv = true; draw(m); }
    return mv;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = null, bd = Infinity;
    for (const m of mons) {
      if (over === null) { m.sp.t = m.rest; continue; }
      const d = Math.abs(over - m.u);
      if (d < bd) { bd = d; near = m; }
      m.sp.t = clamp(Q + Math.atan2(46, over - m.u), A0 - REACH, A0 + REACH);
    }
    for (const m of mons) { m.panel.sil.classList.toggle("hi", near ? m === near : m.k === FAV); m.drawn = NaN; }
    read.textContent = near ? "screen " + (near.k + 1) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const [x, y] = unproj(C, sx, sy, TOP), u = x * cQ + y * sQ, v = -x * sQ + y * cQ;
      over = Math.abs(u) < 84 && v > -90 && v < 44 ? u : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const m of mons) { m.sp.k = 100 * v; m.sp.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "monitors",
  means: "Three monitors on a desk: every screen swivels toward the pointer, and the nearest one lights up with a few lines on it.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[114, 95], [200, 110], [286, 110], null],
  mount,
});

phonedock.code:
/**
 * Phone dock: a long charging dock with four phones standing in its slots,
 * each leaning back a little. The pointer picks a phone by where it is along
 * the row: that phone lifts out of its slot and tilts back, its neighbours
 * lift a little, staggered from it. At rest the phones sit at uneven depths,
 * the third one bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (toaster); the hit is the nearest
 * rest centre along the screen's x.
 */
const {
  Cam, clamp, facing, fillet, fit, hull, poly, prism, proj, rings, ringAt, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const Q = -Math.PI / 4, cQ = Math.cos(Q), sQ = Math.sin(Q);
const W = (u, v) => [u * cQ - v * sQ, u * sQ + v * cQ];
const turn = (ring) => ring.map((q) => ({ u: q.u * cQ - q.v * sQ, v: q.u * sQ + q.v * cQ, nu: q.nu * cQ - q.nv * sQ, nv: q.nu * sQ + q.nv * cQ }));
const N = 4, STEP = 18, U0 = -27, HW = 7, TH = 0.9, TOP = 7, VIS = 24, LIFT = 21, BUMP = 7;
const REST = [2, 0.5, 5, 1], FAV = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.6);
  const ext = [];
  for (const u of [-40, 40]) ext.push([...W(u, 8), 0], [...W(u, -8), 0], [...W(u, -15), TOP + VIS + LIFT]);
  fit(C, ext, 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the dock: one rounded bar, a slot per phone along its top
  const [br, bi] = rings(-40, -8, 40, 8, 6, 1.4);
  const dock = solid(g);
  put(dock, prism(P, front, turn(br), turn(bi), 0, TOP));
  const slots = [];
  for (let k = 0; k < N; k++) { const u = U0 + k * STEP; slots.push(poly(ringAt(P, turn(rrect(u - HW - 1, -1.6, u + HW + 1, 1.6, 1.4, 4)), TOP))); }
  mk("path", { class: "nf lo", d: slots.join("") }, dock.g);

  const phones = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    phones.push({ k, u: U0 + k * STEP, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), z: tween(REST[k]), last: NaN });
  }

  // a phone: a rounded profile in the u–h plane, leaning back by t, a thickness along v
  function face(u, h, d, t, inset) {
    const a = inset, pts = [[-HW + a, a + 1.4], [HW - a, a + 1.4], [HW - a, h - a], [-HW + a, h - a]];
    return fillet(pts, inset ? [1.2, 1.2, 2.4, 2.4] : [0.6, 0.6, 3.4, 3.4], 4)
      .map(([pu, ph]) => P(...W(u + pu, d - ph * Math.sin(t)), TOP + ph * Math.cos(t)));
  }
  function draw(p, lift) {
    if (lift === p.last) return;
    p.last = lift;
    const h = VIS + lift, t = 0.14 + lift * 0.012;
    const near = face(p.u, h, TH, t, 0), far = face(p.u, h, -TH, t, 0);
    p.sil.setAttribute("d", poly(hull(near.concat(far))));
    p.cr.setAttribute("d", poly(face(p.u, h, TH + 0.05, t, 1.3)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    phones.forEach((p) => { draw(p, tval(p.z, now)); if (!tdone(p.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: the rest centres along the screen's x, inside the row's band
  const cx = phones.map((p) => P(...W(p.u, 0), TOP + VIS / 2)[0]);
  const yTop = P(...W(0, -15), TOP + VIS + LIFT)[1] - 6, yBot = P(...W(0, 8), 0)[1] + 6, half = (cx[1] - cx[0]) / 2 + 4;
  function hit([sx, sy]) {
    if (sy < yTop || sy > yBot) return -1;
    let best = -1, bd = Infinity;
    cx.forEach((x, k) => { const d = Math.abs(sx - x); if (d < bd) { bd = d; best = k; } });
    return bd < half ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    phones.forEach((p, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : clamp(BUMP - 2 * Math.abs(k - a), 0, BUMP);
      tset(p.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      p.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "phone " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "phonedock",
  means: "A dock of four phones: the phone under the pointer lifts out of its slot and tilts back, its neighbours lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[101, 154], [231, 154], [296, 154], null],
  mount,
});

drone.code:
/**
 * Drone: a quadcopter hovering over its landing pad, a rounded body, four
 * arms out to four rotor rings, and two landing skids. The pointer is where
 * it wants to go: the drone drifts toward it on springs, up to a limit, and
 * tilts into the drift, its rotor rings bright. At rest it hangs a little off
 * the pad's centre, barely leaning, one rotor lit. The slider is how quickly
 * it follows.
 *
 * The pattern: a continuous aim (terrain's spring, on a position and a lean);
 * the hit is on the ground's plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, poly, prism, proj, rrect, seg, unproj, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const H = 34, BR = 6, ARM = 13, RR = 7, PAD = 30, MAXD = 30, TMAX = 0.3, FAV = 3;
const REST = [-6, 5], ROT = [[-1, -1], [1, -1], [-1, 1], [1, 1]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.85);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([PAD * Math.cos(a), PAD * Math.sin(a), 0], [48 * Math.cos(a), 48 * Math.sin(a), H + 9]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the pad: a low disc, an inner ring, four lights round its rim
  const pad = solid(g);
  put(pad, prism(P, front, circ(PAD, 64), circ(PAD - 1.6, 64), 0, 1.6));
  mk("path", { class: "nf lo", d: poly(circ(18, 48).map((q) => P(q.u, q.v, 1.6))) }, pad.g);
  for (let k = 0; k < 4; k++) { const a = Math.PI / 4 + (k * Math.PI) / 2; place(flatDot(g, C, 1.2, "dot off"), P(24 * Math.cos(a), 24 * Math.sin(a), 1.6)); }
  const mark = flatDot(g, C, 1.4, "dot m");

  // the drone, back to front: skids, arms, the far rotor, body, the side rotors, the near one
  const legs = mk("path", { class: "nf sil" }, g), arms = mk("path", { class: "nf sil" }, g);
  const rot = ROT.map(() => ({ sil: null, cr: null }));
  const mkRot = (i) => { const gr = mk("g", {}, g); rot[i].sil = mk("path", { class: "sil" }, gr); rot[i].cr = mk("path", { class: "nf lo" }, gr); };
  mkRot(0);
  const body = solid(g);
  mkRot(1); mkRot(2); mkRot(3);

  const sp = [spring(REST[0]), spring(REST[1]), spring(0), spring(0)];
  const BOT = rrect(-BR, -BR, BR, BR, 3, 6), TOPR = rrect(-BR + 1, -BR + 1, BR - 1, BR - 1, 2, 6);
  const ring = (r, n = 32) => circ(r, n);
  let last = "";

  function draw() {
    const [dx, dy, tx, ty] = sp.map((s) => s.x), key = sp.map((s) => s.x.toFixed(3)).join();
    if (key === last) return;
    last = key;
    // a lean of |t| toward (tx, ty): Rodrigues about the axis (-ty, tx, 0)
    const th = Math.hypot(tx, ty), kx = th ? -ty / th : 0, ky = th ? tx / th : 0, c = Math.cos(th), s = Math.sin(th);
    const T = ([x, y, z]) => {
      const kp = kx * x + ky * y, cx = ky * z, cy = -kx * z, cz = kx * y - ky * x;
      return P(dx + x * c + cx * s + kx * kp * (1 - c), dy + y * c + cy * s + ky * kp * (1 - c), H + z * c + cz * s);
    };
    const at = (r, z, ox = 0, oy = 0) => r.map((q) => T([q.u + ox, q.v + oy, z]));
    body.sil.setAttribute("d", poly(hull(at(BOT, 0).concat(at(BOT, 5)))));
    body.cr.setAttribute("d", poly(at(TOPR, 5)));
    let A = "", L = "";
    ROT.forEach(([sx, sy], i) => {
      const ox = sx * ARM, oy = sy * ARM;
      A += seg(T([sx * 4, sy * 4, 2.5]), T([ox, oy, 3]));
      rot[i].sil.setAttribute("d", poly(hull(at(ring(RR), 4.4, ox, oy).concat(at(ring(RR), 5.6, ox, oy)))));
      rot[i].cr.setAttribute("d", poly(at(ring(1.4, 12), 5.6, ox, oy)));
    });
    for (const sy of [-1, 1]) {
      L += seg(T([-3, sy * 4, 0]), T([-3, sy * 7, -8])) + seg(T([3, sy * 4, 0]), T([3, sy * 7, -8]));
      L += seg(T([-8, sy * 7, -8]), T([8, sy * 7, -8]));
    }
    arms.setAttribute("d", A);
    legs.setAttribute("d", L);
    place(mark, P(dx, dy, 0));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const s of sp) if (stepS(s, dt)) m = true;
    draw();
    return m;
  });
  bag.add(B.unregister);

  function aim(p) {
    let d = 0, ux = 0, uy = 0;
    if (p) { const r = Math.hypot(p[0], p[1]); d = clamp(r, 0, MAXD); if (r > 0) { ux = p[0] / r; uy = p[1] / r; } }
    const [gx, gy] = p ? [ux * d, uy * d] : REST, f = p ? (d / MAXD) * TMAX : 0.06;
    const n = Math.hypot(gx, gy) || 1;
    sp[0].t = gx; sp[1].t = gy; sp[2].t = (gx / n) * f; sp[3].t = (gy / n) * f;
    rot.forEach((r, i) => r.sil.classList.toggle("hi", p ? true : i === FAV));
    read.textContent = p ? "drift " + Math.round(d) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, 0); aim(Math.hypot(x, y) < 95 ? [x, y] : null); },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return {
    set: (v) => { for (const s of sp) { s.k = 100 * v; s.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "drone",
  means: "A quadcopter over its landing pad: it drifts and leans toward the pointer, up to a limit, its rotor rings bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[120, 200], [210, 120], [281, 272], null],
  mount,
});

smartspeakers.code:
/**
 * Smart speakers: four speakers of different shapes on a shelf, a cylinder,
 * a cube, a dome and an oval, each with a light ring on its top. The pointer
 * picks a speaker by where it is along the shelf: it lifts and its top ring
 * widens, its neighbours lift a little, staggered from it. At rest they sit
 * on the shelf, the cube's ring a little open and bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (toaster); the hit is the nearest
 * rest centre along the screen's x.
 */
const {
  Cam, circ, clamp, facing, fit, hull, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const Q = -Math.PI / 4, cQ = Math.cos(Q), sQ = Math.sin(Q);
const W = (u, v) => [u * cQ - v * sQ, u * sQ + v * cQ];
const turn = (ring, cx, cy, sx = 1, sy = 1) => ring.map((q) => {
  const u = q.u * sx, v = q.v * sy;
  return { u: cx + u * cQ - v * sQ, v: cy + u * sQ + v * cQ, nu: q.nu * cQ - q.nv * sQ, nv: q.nu * sQ + q.nv * cQ };
});
const N = 4, STEP = 27, U0 = -40, SH = 3, LIFT = 13, BUMP = 5, FAV = 1;
const ROPEN = [0.1, 0.45, 0, 0.2];
const dome = [];
for (let i = 0; i <= 6; i++) { const a = (i / 6) * (Math.PI / 2); dome.push([Math.max(10 * Math.cos(a), 1), 13 * Math.sin(a)]); }
// each shape: its levels [ring maker, z], and its top ring [radius at 0 and 1, z at radius]
const SHAPES = [
  { lv: [[() => circ(8, 32), 0], [() => circ(8, 32), 22]], ring: [3.5, 6.6], rz: () => 22 },
  { lv: [[() => rings(-8, -8, 8, 8, 3, 1)[0], 0], [() => rings(-8, -8, 8, 8, 3, 1)[0], 16]], ring: [3, 6], rz: () => 16 },
  { lv: dome.map(([r, z]) => [() => circ(r, 32), z]), ring: [3, 7], rz: (r) => 13 * Math.sqrt(1 - (r / 10) ** 2) },
  { lv: [[() => circ(9, 32), 0], [() => circ(9, 32), 15], [() => circ(7.4, 32), 18.4], [() => circ(4.6, 32), 20]], ring: [2.6, 5], rz: () => 20, sx: 1.25, sy: 0.75 },
];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.0);
  const ext = [];
  for (const u of [-56, 56]) ext.push([...W(u, -12), SH], [...W(u, 12), SH], [...W(u, 12), -14], [...W(u, 0), SH + 22 + LIFT]);
  fit(C, ext, 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the shelf: two brackets under a long plank
  for (const u of [-38, 38]) {
    const [r, i] = rings(u - 1, -10, u + 1, 10, 0.8, 0.4);
    put(solid(g), prism(P, front, turn(r, 0, 0), turn(i, 0, 0), -14, 0));
  }
  const [sr, si] = rings(-56, -12, 56, 12, 3, 1.2);
  put(solid(g), prism(P, front, turn(sr, 0, 0), turn(si, 0, 0), 0, SH));

  const sp = SHAPES.map((s, k) => {
    const u = U0 + k * STEP, [cx, cy] = W(u, 0), grp = mk("g", {}, g);
    const lv = s.lv.map(([f, z]) => [turn(f(), cx, cy, s.sx, s.sy), z]);
    return { k, s, cx, cy, lv, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), z: tween(0), o: tween(ROPEN[k]), last: "" };
  });

  function draw(p, lift, open) {
    const key = lift.toFixed(3) + open.toFixed(3);
    if (key === p.last) return;
    p.last = key;
    const z0 = SH + lift, pts = [];
    for (const [r, z] of p.lv) for (const q of r) pts.push(P(q.u, q.v, z0 + z));
    p.sil.setAttribute("d", poly(hull(pts)));
    const rr = p.s.ring[0] + (p.s.ring[1] - p.s.ring[0]) * open;
    p.cr.setAttribute("d", poly(turn(circ(rr, 32), p.cx, p.cy, p.s.sx, p.s.sy).map((q) => P(q.u, q.v, z0 + p.s.rz(rr)))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    sp.forEach((p) => { draw(p, tval(p.z, now), tval(p.o, now)); if (!tdone(p.z, now) || !tdone(p.o, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: the rest centres along the screen's x, inside the shelf's band
  const cx = sp.map((p) => P(p.cx, p.cy, SH + 10)[0]);
  const yTop = P(...W(0, -12), SH + 22 + LIFT)[1] - 6, yBot = P(...W(0, 12), 0)[1] + 6, half = (cx[1] - cx[0]) / 2 + 4;
  function hit([sx, sy]) {
    if (sy < yTop || sy > yBot) return -1;
    let best = -1, bd = Infinity;
    cx.forEach((x, k) => { const d = Math.abs(sx - x); if (d < bd) { bd = d; best = k; } });
    return bd < half ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    sp.forEach((p, k) => {
      const d = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(p.z, a < 0 ? 0 : k === a ? LIFT : clamp(BUMP - 2 * Math.abs(k - a), 0, BUMP), now, d);
      tset(p.o, a < 0 ? ROPEN[k] : k === a ? 1 : ROPEN[k], now, d);
      p.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "speaker " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "smartspeakers",
  means: "Four smart speakers on a shelf: the one under the pointer lifts and its top ring widens, its neighbours lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[81, 143], [162, 143], [243, 143], null],
  mount,
});

easels.code:
/**
 * Easels: an art studio with three easels in a row, each an A-frame of two
 * front legs and a back leg with a ledge, holding a canvas of its own size.
 * The pointer picks an easel by where it stands: its canvas lifts off the
 * ledge and tilts forward toward the painter, and the canvases beside it
 * stir a little, staggered from it. At rest the canvases lean back at
 * different angles, the middle one raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the pick is the easel
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rad, rings, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const EX = [0, 46, 92], CW = [26, 36, 20], CH = [34, 28, 24], LZ = 20, YB = 7, T = 2, FAV = 1;
const PHI = [13, 5, 16], LIFT0 = [0, 6, 0];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-14, -24, 0], [106, 12, 0], [-14, 12, 0], [106, -24, 0], [0, -12, 68], [46, 9, LZ + 14 + 30], [92, -12, 68]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const easels = EX.map((ex, k) => {
    const grp = mk("g", {}, g);
    const top = [ex, -12, 68];
    const leg = (a, b) => "M" + P(...a).join(",") + "L" + P(...b).join(",");
    mk("path", { class: "nf sil", d: leg([ex, -24, 0], [ex, -10, 64]) + leg([ex - 13, 6, 0], top) + leg([ex + 13, 6, 0], top) }, grp);
    const [r, i] = rings(ex - 16, 1, ex + 16, 10, 1.6, 0.6);
    put(solid(grp), prism(P, front, r, i, LZ - 2.2, LZ));
    return { k, ex, w: CW[k], h: CH[k], sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), phi: tween(PHI[k]), z: tween(LIFT0[k]), last: "" };
  });

  // the canvas: u across, v up its face, w through its depth; leaning back by phi from its foot
  function draw(e, phi, lift) {
    const key = phi.toFixed(2) + "," + lift.toFixed(2);
    if (key === e.last) return;
    e.last = key;
    const p = rad(phi), at = (s, w) => P(s.u, YB - s.v * Math.sin(p) + w * Math.cos(p), LZ + lift + s.v * Math.cos(p) + w * Math.sin(p));
    const ring = rrect(e.ex - e.w / 2, 0, e.ex + e.w / 2, e.h, 1.4, 4);
    e.sil.setAttribute("d", poly(hull(ring.map((s) => at(s, 0)).concat(ring.map((s) => at(s, T))))));
    const inner = rrect(e.ex - e.w / 2 + 2.2, 2.2, e.ex + e.w / 2 - 2.2, e.h - 2.2, 0.8, 4);
    e.cr.setAttribute("d", poly(inner.map((s) => at(s, T))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const e of easels) { draw(e, tval(e.phi, now), tval(e.z, now)); if (!tdone(e.phi, now) || !tdone(e.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = easels.map((e) => P(e.ex, YB, LZ + e.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    easels.forEach((e, k) => {
      const d = Math.abs(k - a), delay = from < 0 ? 0 : d * stag;
      tset(e.phi, a < 0 ? PHI[k] : d === 0 ? -8 : d === 1 ? 7 : 11, now, delay);
      tset(e.z, a < 0 ? LIFT0[k] : d === 0 ? 12 : d === 1 ? 3 : 0, now, delay);
      e.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "canvas " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "easels",
  means: "Three easels in a studio: the canvas under the pointer lifts off its ledge and tilts forward, its neighbours stir a little.",
  rules: [1, 2, 5, 6],
  range: [0, 50, 100],
  tour: [[114, 140], [181, 166], [248, 206], null],
  mount,
});

crayonbox.code:
/**
 * Crayonbox: an open box of eight crayons standing in a row, its lid flap
 * leaning back behind them. Each crayon is a round stick with a wrapper band
 * and a cone tip. The pointer picks a crayon by where it stands: it rises out
 * of the box, and its neighbours rise a little, staggered from it. At rest
 * the crayons stand at uneven heights, one pulled half out, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the pick is the crayon
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, circ, facing, fillet, fit, hull, open, poly, prism, proj, rings, ringAt, rrect, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 8, STEP = 6.4, CR = 2.6, BH = 30, L = 40, TIP = 6, LIFT = 20, FAV = 5;
const X1 = N * STEP + 2, Y0 = 0, Y1 = 9, CY = 4.5;
const REST = [3, 0, 5, 1, 2, 9, 0, 4];
const disc = (x, y, r, n = 18) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.3);
  fit(C, [[0, Y0, 0], [X1, Y1, 0], [0, Y1, 0], [X1, Y0, 0], [0, Y0 - 12, BH + 28], [STEP * 6, CY, LIFT + L + TIP]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the lid flap, leaning back from the box's back edge
  const flap = fillet([[0, Y0, BH], [X1, Y0, BH], [X1, Y0 - 12, BH + 24], [0, Y0 - 12, BH + 24]].map((p) => P(...p)), [0, 0, 3, 3], 4);
  mk("path", { class: "sil", d: poly(flap) }, g);
  const outer = rrect(0, Y0, X1, Y1, 2, 6), inner = rrect(1, Y0 + 1, X1 - 1, Y1 - 1, 1.2, 6);
  put(solid(g), prism(P, front, outer, inner, 0, BH));

  const crayons = [];
  for (let k = 0; k < N; k++) {
    const x = 1 + STEP / 2 + k * STEP, grp = mk("g", {}, g);
    crayons.push({ k, x, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), z: tween(REST[k]), last: NaN });
  }
  // the box's near faces, painted over the crayons' feet
  const nr = run(outer, front);
  mk("path", { class: "sil", d: poly(hull(ringAt(P, nr, 0).concat(ringAt(P, nr, BH)))) }, g);
  mk("path", { class: "nf lo", d: open(ringAt(P, nr, BH - 9)) }, g);

  function draw(c, z) {
    if (z === c.last) return;
    c.last = z;
    const ring = disc(c.x, CY, CR), top = z + L;
    const pts = ringAt(P, ring, z).concat(ringAt(P, ring, top), [P(c.x, CY, top + TIP)], ringAt(P, disc(c.x, CY, 0.8, 8), top + TIP - 0.6));
    c.sil.setAttribute("d", poly(hull(pts)));
    const fr = run(ring, front), band = (zz) => open(ringAt(P, fr, zz));
    c.cr.setAttribute("d", band(top) + band(top - 7) + band(z + 8));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const c of crayons) { draw(c, tval(c.z, now)); if (!tdone(c.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = crayons.map((c) => P(c.x, CY, BH + 6));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 12 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    crayons.forEach((c, k) => {
      const d = Math.abs(k - a), z = a < 0 ? REST[k] : d === 0 ? LIFT : d === 1 ? 7 : d === 2 ? 3 : 0;
      tset(c.z, z, now, from < 0 ? 0 : d * stag);
      c.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "crayon " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

