haybales.code:
/**
 * Hay bales: a mown field with six round bales lying on their sides, each face
 * a wound spiral, and a post-and-rail fence along the far edges. The pointer
 * nudges them: the bales near it roll a little toward the reader, each on its
 * own spring, the spiral turning as it goes, the one under it furthest and
 * bright. At rest they lie scattered, one bright. The slider is the reach.
 *
 * The pattern: a continuous field on the ground; the hit is each bale's rest
 * centre on the plane of its axle, which never moves.
 */
const {
  Cam, clamp, fit, open, poly, hull, proj, rings, prism, facing, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 10, HW = 7, ROLL = 10;
const BALES = [[-38, -26], [-2, -32], [34, -22], [-30, 4], [6, -2], [40, 10]];
const REST = [1, 3, 0, 2.5, 0.5, 4], FAV = 3;
const XA = -60, XB = 66, YA = -48, YB = 26;
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value * 30, over = null;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[XA, YA, -3], [XB, YB, -3], [XB, YA, -3], [XA, YB, -3], [XA, YA, 16]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [fo, fi] = rings(XA, YA, XB, YB, 5, 1.8);
  put(solid(g), prism(P, front, fo, fi, -3, 0));

  // the fence along the two far edges: posts, then two rails
  const fx = XA + 4, fy = YA + 4, posts = [];
  for (let y = YB - 6; y > fy; y -= 18) posts.push([fx, y]);
  for (let x = fx; x < XB - 2; x += 18) posts.push([x, fy]);
  posts.sort((a, b) => a[0] + a[1] - (b[0] + b[1]));
  let rails = "";
  const run1 = posts.filter((p) => p[0] === fx).sort((a, b) => a[1] - b[1]), run2 = posts.filter((p) => p[1] === fy).sort((a, b) => a[0] - b[0]);
  for (const line of [run1, run2]) for (const z of [7, 12]) rails += seg(P(line[0][0], line[0][1], z), P(line[line.length - 1][0], line[line.length - 1][1], z));
  mk("path", { class: "nf sil", d: rails }, g);
  for (const [x, y] of posts) { const [o, i] = rings(x - 1.2, y - 1.2, x + 1.2, y + 1.2, 0.6, 0.3); put(solid(g), prism(P, front, o, i, 0, 15)); }

  const layer = mk("g", {}, g);
  const bales = BALES.map(([cx, cy], k) => {
    const grp = mk("g", {}, layer), body = mk("path", { class: "sil" }, grp);
    const face = mk("path", { class: "nf lo", d: "" }, grp), spiral = mk("path", { class: "nf lo", d: "" }, grp);
    return { k, cx, cy, grp, body, face, spiral, sp: spring(REST[k]), drawn: NaN };
  });
  const circle = (x, y, r, n) => Array.from({ length: n }, (_, i) => { const t = (i / n) * Math.PI * 2; return P(x + r * Math.cos(t), y, R + r * Math.sin(t)); });

  let order = "";
  function draw(b) {
    const s = clamp(b.sp.x, 0, ROLL + 2);
    if (Math.abs(s - b.drawn) < 1e-3) return;
    b.drawn = s;
    const x = b.cx + s, a = -s / R;
    b.body.setAttribute("d", poly(hull(circle(x, b.cy - HW, R, 40).concat(circle(x, b.cy + HW, R, 40)))));
    b.face.setAttribute("d", poly(circle(x, b.cy + HW, R - 0.8, 40)));
    const sp = [];
    for (let i = 0; i <= 90; i++) { const t = i / 90, r = 1 + t * (R - 3), th = a + t * Math.PI * 2 * 2.6; sp.push(P(x + r * Math.cos(th), b.cy + HW, R + r * Math.sin(th))); }
    b.spiral.setAttribute("d", open(sp));
  }
  function reorder() {
    const s = [...bales].sort((p, q) => p.cx + p.sp.x + p.cy - (q.cx + q.sp.x + q.cy));
    const key = s.map((b) => b.k).join();
    if (key !== order) { order = key; for (const b of s) layer.append(b.grp); }
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const b of bales) { if (stepS(b.sp, dt)) m = true; draw(b); }
    reorder();
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    let hit = null, bd = Infinity;
    if (over) for (const b of bales) { const d = Math.hypot(over[0] - b.cx, over[1] - b.cy); if (d < bd) { bd = d; hit = b; } }
    if (bd > 16) hit = null;
    for (const b of bales) {
      if (!over) b.sp.t = REST[b.k];
      else if (b === hit) b.sp.t = ROLL;
      else b.sp.t = Math.max(REST[b.k], ROLL * 0.7 * falloff(Math.hypot(over[0] - b.cx, over[1] - b.cy) / RAD));
      b.body.classList.toggle("hi", over ? b === hit : b.k === FAV);
    }
    read.textContent = hit ? "bale " + (hit.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], R);
      over = x > XA - 10 && x < XB + 10 && y > YA - 10 && y < YB + 10 ? [x, y] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v * 30; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "haybales",
  means: "Six round hay bales in a fenced field: the bales near the pointer roll toward the reader, the one under it furthest.",
  rules: [1, 3, 5, 8],
  range: [0.6, 1, 1.8],
  tour: [[164, 123], [134, 150], [222, 202], null],
  mount,
});

punchingbags.code:
/**
 * Punching bags: a gym beam on two footed posts with three heavy bags hanging
 * from it, each on a chain that splits at a swivel into three straps. The
 * pointer is a punch: the bags near it swing away from it, each on its own
 * springs, and the one under it swings back hardest and bright. At rest the
 * bags hang a little askew, the middle one bright. The slider is the reach,
 * in bag spacings.
 *
 * The pattern: a continuous field along one row; the hit is the pointer's
 * screen x against the bags' resting centres, which never move.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, proj, rings, run, prism, seg, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const N = 3, GAP = 42, ZB = 104, CH = 16, BL = 46, R = 10, AMAX = 20;
const X0 = -34, X1 = (N - 1) * GAP + 34;
const REST = [[5, -3], [-3, 2], [7, 4]], FAV = 1, D = Math.PI / 180;
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value * GAP, over = null;
  const C = Cam(45, 0.5, 1.8);
  fit(C, [[X0 - 9, -14, 0], [X1 + 9, 14, 0], [X0 - 9, 14, 0], [X1 + 9, -14, 0], [X0, 0, ZB + 8], [X1, 0, ZB + 8]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, o, i, z0, z1)); };

  // the frame: feet, posts, then the chains behind the beam, the beam, the bags
  for (const x of [X0, X1]) block(x - 9, -14, x + 9, 14, 3, 1.2, 0, 3);
  for (const x of [X0, X1]) block(x - 4, -4, x + 4, 4, 2, 0.8, 3, ZB);
  const chains = mk("g", {}, g);
  block(X0 - 6, -5, X1 + 6, 5, 2.4, 1, ZB, ZB + 8);
  const [ring, inner] = [circ(R, 40), circ(R - 1.4, 40)];

  const bags = [];
  for (let i = 0; i < N; i++) {
    const bx = i * GAP;
    const b = { i, bx, rest: REST[i].map((a) => a * D), drawn: "" };
    b.ax = spring(b.rest[0], { eps: 0.002 });
    b.ay = spring(b.rest[1], { eps: 0.002 });
    b.chain = mk("path", { class: "nf sil", d: "" }, chains);
    b.el = solid(g);
    b.band = mk("path", { class: "nf lo", d: "" }, b.el.g);
    b.swivel = flatDot(chains, C, 1.4, "dot off");
    b.cx = P(bx, 0, ZB - CH - BL / 2)[0];
    bags.push(b);
  }

  function draw(b) {
    const ax = b.ax.x, ay = b.ay.x, key = ax.toFixed(4) + ay.toFixed(4);
    if (key === b.drawn) return;
    b.drawn = key;
    const at = (l) => [b.bx + l * Math.sin(ax), l * Math.sin(ay), ZB - l * Math.cos(ax) * Math.cos(ay)];
    const ringAt = (rg, l) => { const [x, y, z] = at(l); return rg.map((q) => P(q.u + x, q.v + y, z)); };
    const top = at(CH), sw = at(7), piv = P(b.bx, 0, ZB);
    let d = seg(piv, P(...sw));
    for (const a of [90, 210, 330]) d += seg(P(...sw), P(top[0] + R * 0.8 * Math.cos(a * D), top[1] + R * 0.8 * Math.sin(a * D), top[2]));
    b.chain.setAttribute("d", d);
    place(b.swivel, P(...sw));
    b.el.sil.setAttribute("d", poly(hull(ringAt(ring, CH).concat(ringAt(ring, CH + BL)))));
    b.el.cr.setAttribute("d", open(ringAt(run(inner, front), CH)));
    b.band.setAttribute("d", open(ringAt(run(ring, front), CH + BL - 9)) + open(ringAt(run(ring, front), CH + 8)));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const b of bags) { if (stepS(b.ax, dt)) m = true; if (stepS(b.ay, dt)) m = true; draw(b); }
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    let hit = null;
    if (over !== null) {
      const k = clamp(Math.round(over / GAP), 0, N - 1);
      if (Math.abs(over - k * GAP) < GAP / 2) hit = bags[k];
    }
    for (const b of bags) {
      if (over === null) { b.ax.t = b.rest[0]; b.ay.t = b.rest[1]; }
      else if (b === hit) { b.ax.t = clamp((b.bx - over) / GAP, -0.5, 0.5) * AMAX * D; b.ay.t = -AMAX * D; }
      else { b.ax.t = Math.sign(b.bx - over) * AMAX * 0.8 * D * falloff(Math.abs(b.bx - over) / RAD); b.ay.t = b.rest[1] * 0.5; }
      b.el.sil.classList.toggle("hi", over !== null ? b === hit : b.i === FAV);
    }
    read.textContent = hit ? "bag " + (hit.i + 1) : "rest";
    B.wake();
  }

  const yTop = P(0, 0, ZB + 12)[1], yBot = P(0, 0, 0)[1] + 12;
  bag.add(pointer(stage, {
    move: (p) => {
      const x = ((p[0] - bags[0].cx) / (bags[N - 1].cx - bags[0].cx)) * (N - 1) * GAP;
      over = p[1] > yTop && p[1] < yBot && x > X0 && x < X1 ? x : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v * GAP; if (over !== null) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "punchingbags",
  means: "Three punching bags on a gym beam: the bags near the pointer swing away from it, the one under it hardest.",
  rules: [1, 3, 5, 9],
  range: [1, 1.5, 3],
  tour: [[147, 126], [200, 152], [253, 179], null],
  mount,
});

golfgreen.code:
/**
 * Golf green: a putting green on its apron, a cup with the flagstick standing
 * in it and three golf balls lying out on the grass. The pointer is where the
 * putts are aimed: every ball rolls toward it on its own springs, the nearest
 * one bright, and the flag swings round to stream toward it. At rest the balls
 * lie scattered round the cup, one bright, the flag streaming off to the side.
 * The slider is how far a ball rolls.
 *
 * The pattern: a continuous pull per ball (terrain's spring, in x and y); the
 * hit is on the green's plane, which never moves, against the balls' rests.
 */
const {
  Cam, circ, clamp, facing, fillet, fit, open, poly, prism, proj, run, seg, unproj, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid, r2,
} = HL;

const GR = (a) => 62 + 7 * Math.sin(2 * a + 1) + 4 * Math.cos(3 * a);
const H = [18, -16], PH = 64, BR = 5.6, ZT = 3;
const RESTS = [[-36, 14], [-4, 30], [34, 18]], FAV = 1, FL0 = -40 * (Math.PI / 180);
const blob = (dr, n = 72) => Array.from({ length: n }, (_, k) => {
  const a = (k / n) * Math.PI * 2, r = GR(a) + dr;
  return { u: r * Math.cos(a), v: r * Math.sin(a), nu: Math.cos(a), nv: Math.sin(a) };
});
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let ROLL = 30 * value, over = null;
  const C = Cam(45, 0.5, 2.05);
  const ext = blob(9, 24).map((q) => [q.u, q.v, -4]).concat([[H[0], H[1], PH + 2]]);
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // apron, green, the cup with its far inner wall
  put(solid(g), prism(P, front, blob(9), blob(7.6), -4, 0));
  put(solid(g), prism(P, front, blob(0), blob(-1.6), 0, ZT));
  const cup = circ(3.6, 32).map((q) => ({ ...q, u: q.u + H[0], v: q.v + H[1] }));
  mk("path", { class: "nf", d: poly(cup.map((q) => P(q.u, q.v, ZT))) }, g);
  mk("path", { class: "nf lo", d: open(run(cup, (q) => !front(q)).map((q) => P(q.u, q.v, ZT - 2.5))) }, g);

  const items = [];
  const flag = { key: H[0] + H[1], g: mk("g", {}, g), sp: spring(FL0), drawn: NaN };
  mk("path", { class: "nf sil", d: seg(P(H[0], H[1], ZT - 1), P(H[0], H[1], PH)) }, flag.g);
  flag.cloth = mk("path", { class: "", d: "" }, flag.g);
  items.push(flag);
  const balls = RESTS.map(([x, y], i) => {
    const b = { i, rx: x, ry: y, sx: spring(x), sy: spring(y), g: mk("g", {}, g), drawn: "" };
    b.body = mk("ellipse", { class: "sil", rx: r2(BR * C.S), ry: r2(BR * C.S) }, b.g);
    b.dim = [[-0.4, -0.1], [0.05, 0.35], [0.38, -0.25], [-0.05, -0.45]].map((o) => ({ o, el: flatDot(b.g, C, 0.45, "dot off") }));
    items.push(b);
    return b;
  });
  let orderKey = "";

  function draw() {
    const a = flag.sp.x;
    if (!(Math.abs(a - flag.drawn) < 1e-4)) {
      flag.drawn = a;
      const c = Math.cos(a), s = Math.sin(a), at = (l, z) => P(H[0] + l * c, H[1] + l * s, z);
      const pts = [P(H[0], H[1], PH), at(13, PH - 1.6), at(26, PH - 8), at(13, PH - 15), P(H[0], H[1], PH - 16)];
      flag.cloth.setAttribute("d", poly(fillet(pts, [0.6, 3, 1.2, 3, 0.6], 4)));
    }
    for (const b of balls) {
      const x = b.sx.x, y = b.sy.x, key = x.toFixed(2) + "," + y.toFixed(2);
      if (key === b.drawn) continue;
      b.drawn = key;
      b.key = x + y;
      const [cx, cy] = P(x, y, ZT + BR);
      b.body.setAttribute("cx", r2(cx)); b.body.setAttribute("cy", r2(cy));
      for (const d of b.dim) place(d.el, [cx + d.o[0] * BR * C.S, cy + d.o[1] * BR * C.S]);
    }
    const sorted = items.slice().sort((p, q) => p.key - q.key), k = sorted.map((it) => items.indexOf(it)).join();
    if (k !== orderKey) { orderKey = k; for (const it of sorted) g.appendChild(it.g); }
  }

  const B = register(stage, (dt) => {
    let m = stepS(flag.sp, dt);
    for (const b of balls) { if (stepS(b.sx, dt)) m = true; if (stepS(b.sy, dt)) m = true; }
    draw();
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    let near = null, bd = Infinity;
    for (const b of balls) {
      if (!over) { b.sx.t = b.rx; b.sy.t = b.ry; continue; }
      const vx = over[0] - b.rx, vy = over[1] - b.ry, d = Math.hypot(vx, vy);
      if (d < bd) { bd = d; near = b; }
      const m = d < 0.01 ? 0 : Math.min(Math.max(d - BR * 2.2, 0) * 0.7, ROLL) / d;
      let tx = b.rx + vx * m, ty = b.ry + vy * m;
      const r = Math.hypot(tx, ty), lim = GR(Math.atan2(ty, tx)) - BR - 3;
      if (r > lim) { tx *= lim / r; ty *= lim / r; }
      b.sx.t = tx; b.sy.t = ty;
    }
    for (const b of balls) b.body.classList.toggle("hi", over ? b === near : b.i === FAV);
    const aim = over && Math.hypot(over[0] - H[0], over[1] - H[1]) > 5 ? Math.atan2(over[1] - H[1], over[0] - H[0]) : over ? flag.sp.t : FL0;
    flag.sp.t = flag.sp.t + wrap(aim - flag.sp.t);
    read.textContent = near ? "ball " + (near.i + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], ZT);
      over = Math.hypot(x, y) < GR(Math.atan2(y, x)) + 12 ? [x, y] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  draw();
  return { set: (v) => { ROLL = 30 * v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "golfgreen",
  means: "A putting green with a flag and three balls: the balls roll toward the pointer, the nearest bright, and the flag swings to it.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.5],
  tour: [[129, 150], [153, 185], [225, 204], null],
  mount,
});

basketballs.code:
/**
 * Basketballs: a two-tier ball cart on casters, six balls with their seams
 * resting on pairs of rails, three high at the back and three low at the
 * front. The pointer dribbles: the balls near it bounce up, each on its own
 * spring, the one under it highest and bright. At rest one front ball sits a
 * little raised and bright. The slider is the reach, in ball widths.
 *
 * The pattern: a continuous field over stepped parts; the hit is the pointer
 * against each ball's resting screen centre, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, open, prism, proj, rings, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid, r2,
} = HL;

const R = 11, XS = [0, 25, 50], X0 = -15, X1 = 65, YB = -14, YF = 14, Y0 = -24, Y1 = 26;
const ZF = 22, ZK = 50, CF = ZF + 2.4 + 8.5, CK = ZK + 2.4 + 8.5, LMAX = 24;
const REST = [2, 0, 4, 7, 1, 3], FAV = 3, V = [0.6124, 0.6124, 0.5];
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value * 2 * R, over = null;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[X0, Y0, 0], [X1, Y1, 0], [X0, Y1, 0], [X1, Y0, 0], [X0, Y0, CK + R + LMAX], [X1, Y0, CK + R + LMAX]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, o, i, z0, z1)); };
  const post = (x, y, z1) => {
    put(solid(g), prism(P, front, circ(3, 16).map((q) => ({ ...q, u: q.u + x, v: q.v + y })), null, 0, 6));
    put(solid(g), prism(P, front, circ(1.8, 16).map((q) => ({ ...q, u: q.u + x, v: q.v + y })), null, 6, z1));
  };
  const railX = (y, z) => block(X0, y - 1.3, X1, y + 1.3, 1.2, 0.5, z, z + 2.4);
  const railY = (x, z) => block(x - 1.3, Y0, x + 1.3, Y1, 1.2, 0.5, z, z + 2.4);

  // seams: two great circles and two side curves, in each ball's own turn
  const seamPts = (b) => {
    const s = Math.sin(b), c = Math.cos(b), out = [];
    const ax = [c, s, 0], ay = [-s, c, 0], az = [0, 0, 1];
    const curve = (o, u, v, r) => {
      const pts = [];
      for (let a = 0; a <= 48; a++) { const t = (a / 48) * Math.PI * 2; pts.push([0, 1, 2].map((k) => o[k] + r * (u[k] * Math.cos(t) + v[k] * Math.sin(t)))); }
      return pts;
    };
    out.push(curve([0, 0, 0], ay, az, 1), curve([0, 0, 0], ax, ay, 1));
    for (const sg of [-1, 1]) out.push(curve(ax.map((k) => k * sg * 0.62), ay, az, 0.78));
    return out;
  };
  const seamPath = (ball, z) => {
    let d = "";
    for (const pts of ball.seams) {
      let runp = [];
      for (const p of pts) {
        if (p[0] * V[0] + p[1] * V[1] + p[2] * V[2] > 0.05) runp.push(P(ball.x + p[0] * R, ball.y + p[1] * R, z + p[2] * R));
        else { if (runp.length > 1) d += open(runp); runp = []; }
      }
      if (runp.length > 1) d += open(runp);
    }
    return d;
  };

  const balls = [];
  const addBall = (i, x, y, z) => {
    const grp = mk("g", {}, g);
    const b = { i, x, y, z, sp: spring(REST[i], { eps: 0.02 }), drawn: NaN, seams: seamPts(0.4 + i * 1.1) };
    b.body = mk("ellipse", { class: "sil", rx: r2(R * C.S), ry: r2(R * C.S) }, grp);
    b.seam = mk("path", { class: "nf lo", d: "" }, grp);
    b.c = P(x, y, z);
    balls[i] = b;
  };

  // back to front: casters and back posts, far side, back tier, front tier, near side
  for (const [x, y] of [[X0, Y0], [X1, Y0], [X0, Y1], [X1, Y1]]) place(flatDot(g, C, 2.2, "dot off"), P(x, y, 0));
  post(X0, Y0, ZK + 18); post(X1, Y0, ZK + 18);
  railX(Y0, 10); railX(Y0, ZK + 16);
  railY(X0, 10); railY(X0, ZF); railX(YB - 7, ZK); railX(YB + 7, ZK);
  block(X0, Y0, X0 + 2.6, YB + 8, 1.2, 0.5, ZK, ZK + 2.4);
  XS.forEach((x, k) => addBall(k, x, YB, CK));
  railX(YF - 7, ZF); railX(YF + 7, ZF);
  XS.forEach((x, k) => addBall(3 + k, x, YF, CF));
  post(X0, Y1, ZF + 10);
  railX(Y1, 10);
  block(X1 - 2.6, Y0, X1, YB + 8, 1.2, 0.5, ZK, ZK + 2.4);
  railY(X1, 10); railY(X1, ZF);
  post(X1, Y1, ZF + 10);

  function draw(b) {
    const l = clamp(b.sp.x, -1, LMAX * 1.5);
    if (Math.abs(l - b.drawn) < 0.01) return;
    b.drawn = l;
    const [sx, sy] = P(b.x, b.y, b.z + l);
    b.body.setAttribute("cx", r2(sx)); b.body.setAttribute("cy", r2(sy));
    b.seam.setAttribute("d", seamPath(b, b.z + l));
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const b of balls) { if (stepS(b.sp, dt)) m = true; draw(b); }
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    let hit = null, bd = R * C.S * 1.15;
    if (over) for (const b of balls) { const d = Math.hypot(over[0] - b.c[0], over[1] - b.c[1]); if (d < bd) { bd = d; hit = b; } }
    for (const b of balls) {
      if (!over) b.sp.t = REST[b.i];
      else b.sp.t = b === hit ? LMAX : LMAX * 0.7 * falloff(Math.hypot(over[0] - b.c[0], over[1] - b.c[1]) / (RAD * C.S));
      b.body.classList.toggle("hi", over ? b === hit : b.i === FAV);
    }
    read.textContent = hit ? "ball " + (hit.i + 1) : "rest";
    B.wake();
  }

  const box = [P(X0, Y1, 0)[0] - 10, P(X1, Y0, 0)[0] + 10, P(X0, Y0, CK + R + 6)[1], P(X1, Y1, 0)[1] + 8];
  bag.add(pointer(stage, {
    move: (p) => { over = p[0] > box[0] && p[0] < box[1] && p[1] > box[2] && p[1] < box[3] ? p : null; retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v * 2 * R; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "basketballs",
  means: "A two-tier cart of basketballs: the balls near the pointer bounce up, the one under it highest and bright.",
  rules: [1, 3, 5, 9],
  range: [1, 1.6, 3],
  tour: [[141, 158], [167, 95], [236, 227], null],
  mount,
});

guitars.code:
/**
 * Guitars: an acoustic, an electric and a bass, each standing on its own
 * floor stand with a back post and a yoke. A body is two bouts joined at the
 * waist, drawn as a thin plate (a front outline and its thickness), with a
 * neck and a headstock. The pointer picks a guitar by where it stands: it
 * lifts off its stand and tilts, and the guitars beside it lift a little,
 * staggered from it. At rest each leans its own way and the electric sits a
 * touch high, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (bookshelf); the pick is the
 * guitar whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, fillet, fit, open, poly, prism, proj, facing, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const KIND = [
  { lo: [0, 14, 14], up: [0, 31, 10.5], neck: [40, 74, 1.8], head: [74, 84, 2.8], T: 5, hole: [0, 26, 4.2] },
  { lo: [0, 12, 12], up: [2.5, 25, 8.5], neck: [30, 68, 1.6], head: [68, 77, 2.5], T: 3, pick: [9, 17] },
  { lo: [0, 12, 12.5], up: [-2, 25, 9], neck: [30, 88, 1.7], head: [88, 96, 2.6], T: 3.5, pick: [14] },
];
const GX = [0, 46, 92], Y = 10, FAV = 1, REST_T = [-3, 2, -4];
const ring2 = (c, n = 44) => Array.from({ length: n }, (_, i) => { const t = (i / n) * Math.PI * 2; return [c[0] + c[2] * Math.cos(t), c[1] + c[2] * Math.sin(t)]; });
function outside(pts, c) {
  const k = pts.map((p) => Math.hypot(p[0] - c[0], p[1] - c[1]) > c[2]), n = pts.length, out = [];
  let i = k.findIndex((v, j) => v && !k[(j + n - 1) % n]);
  while (k[i % n] && out.length < n) out.push(pts[i++ % n]);
  return out;
}
const rect = (w, a, b, r) => fillet([[-w, a], [w, a], [w, b], [-w, b]], [r, r, r, r], 3);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-16, Y - 8, 0], [108, Y + 14, 0], [-20, Y, 112], [110, Y, 112], [-16, Y + 14, 0]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const gs = KIND.map((K, k) => {
    const gx = GX[k], grp = mk("g", {}, g);
    const [br, bi] = rings(gx - 15, Y - 9, gx + 15, Y + 13, 4, 1.2);
    put(solid(grp), prism(P, front, br, bi, 0, 2));
    put(solid(grp), prism(P, front, rings(gx - 1.2, Y - 7, gx + 1.2, Y - 4.6, 0.6, 0.3)[0], null, 2, 56));
    const [yr, yi] = rings(gx - 6, Y - 7.4, gx + 6, Y - 3.4, 1.4, 0.6);
    put(solid(grp), prism(P, front, yr, yi, 54, 57));
    const body = fillet(outside(ring2(K.lo), K.up).concat(outside(ring2(K.up), K.lo)), Array(80).fill(2.5), 3);
    const shapes = [rect(K.neck[2], K.neck[0], K.neck[1], 0.6), rect(K.head[2], K.head[0], K.head[1], 1.4), body];
    const parts = shapes.map((s) => ({ s, back: mk("path", { class: "lo" }, grp), face: mk("path", { class: "sil" }, grp) }));
    const marks = mk("path", { class: "nf lo" }, grp);
    return { k, K, gx, parts, marks, L: tween(k === FAV ? 3 : 0), A: tween(REST_T[k]), last: "" };
  });

  function draw(G, L, a) {
    const key = L.toFixed(2) + "," + a.toFixed(2);
    if (key === G.last) return false;
    G.last = key;
    const c = Math.cos((a * Math.PI) / 180), s = Math.sin((a * Math.PI) / 180), K = G.K;
    const W = (u, w, y) => P(G.gx + u * c + w * s, y, 2 + L + w * c - u * s);
    for (const p of G.parts) {
      p.back.setAttribute("d", poly(p.s.map(([u, w]) => W(u, w, Y))));
      p.face.setAttribute("d", poly(p.s.map(([u, w]) => W(u, w, Y + K.T))));
    }
    let d = "";
    if (K.hole) d += poly(ring2(K.hole, 24).map(([u, w]) => W(u, w, Y + K.T)));
    for (const w of K.pick || []) d += poly(rect(5.5, w - 1.2, w + 1.2, 0.8).map(([u, ww]) => W(u, ww, Y + K.T)));
    d += open([W(0, 5, Y + K.T), W(0, K.neck[1], Y + K.T)]);
    G.marks.setAttribute("d", d);
    return true;
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const G of gs) { draw(G, tval(G.L, now), tval(G.A, now)); if (!tdone(G.L, now) || !tdone(G.A, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = gs.map((G) => P(G.gx, Y, 40));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 110 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    gs.forEach((G, k) => {
      const d = Math.abs(k - a), delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(G.L, a < 0 ? (k === FAV ? 3 : 0) : d === 0 ? 14 : d === 1 ? 4 : 1, now, delay);
      tset(G.A, a < 0 ? REST_T[k] : d === 0 ? (k === 2 ? -9 : 9) : REST_T[k] * 1.6, now, delay);
      for (const p of G.parts) p.face.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "guitar " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "guitars",
  means: "Three guitars on stands: the one under the pointer lifts off its stand and tilts, and its neighbours lift a little.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[150, 160], [200, 170], [250, 190], null],
  mount,
});

turntables.code:
/**
 * Turntables: a DJ desk with two decks and a mixer between them. Each deck is
 * a plinth with a platter, a record (label and one groove mark), and a tone
 * arm on its pivot. The pointer picks the deck nearer it: that record spins
 * up on a spring on its rate, and only while the pointer moves, and its tone
 * arm swings onto the record, bright. At rest deck 2's arm is down, bright,
 * and both records are still. The slider is how fast the record spins.
 *
 * The pattern: one of two in a row (bookshelf's pick by rest centre x); a
 * spring on a rate, decaying to rest so the loop sleeps when the pointer does.
 */
const {
  Cam, circ, fit, open, prism, proj, facing, rings, seg, spring, stepS, tdone, tset, tval, tween,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const DX = [30, 104], CY = 30, R = 17.5, OFF = 88, ON = 113, ARM = 24, FAV = 1;
const disc = (x, y, r, n = 48) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let speed = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-2, -2, 0], [136, 62, 0], [136, -2, 0], [-2, 62, 0], [0, 0, 22], [136, 0, 22]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [dr, di] = rings(-2, -2, 136, 62, 4, 1.4);
  put(solid(g), prism(P, front, dr, di, 0, 6));

  const decks = DX.map((cx, k) => {
    const grp = mk("g", {}, g);
    if (k === 1) {
      const [mr, mi] = rings(58, 8, 76, 52, 2.5, 1);
      const mx = solid(g); put(mx, prism(P, front, mr, mi, 6, 13));
      g.insertBefore(mx.g, grp);
      const f = (x) => seg(P(x, 30, 13), P(x, 46, 13));
      mk("path", { class: "nf lo", d: f(62) + f(67) + f(72) + seg(P(61, 49.5, 13), P(73, 49.5, 13)) }, g).after(mx.g);
      [[62, 14], [67, 14], [72, 14], [62, 20], [67, 20], [72, 20]].forEach(([x, y]) => place(flatDot(g, C, 1.1, "dot off"), P(x, y, 13)));
    }
    const [pr, pi] = rings(cx - 26, 4, cx + 26, 56, 3.5, 1.2);
    put(solid(grp), prism(P, front, pr, pi, 6, 12));
    put(solid(grp), prism(P, front, disc(cx, CY, R + 1.5), disc(cx, CY, R + 0.6), 12, 14.5));
    const rec = solid(grp);
    put(rec, prism(P, front, disc(cx, CY, R), disc(cx, CY, 5.5, 32), 14.5, 15.5));
    const mark = mk("path", { class: "nf lo" }, grp);
    place(flatDot(grp, C, 0.9, "dot m"), P(cx, CY, 15.5));
    const px = cx + 20, py = CY - 20;
    put(solid(grp), prism(P, front, disc(px, py, 2.6, 24), disc(px, py, 1.8, 24), 12, 18));
    const arm = mk("path", { class: "nf sil" }, grp);
    const head = flatDot(grp, C, 1.4, "dot off");
    return { k, cx, px, py, rec, mark, arm, head, ang: (k * 1.3) + 0.4, rate: spring(0), sw: tween(k === FAV ? ON : OFF), last: "" };
  });

  function draw(D, now) {
    const a = tval(D.sw, now), key = D.ang.toFixed(3) + "," + a.toFixed(2);
    if (key === D.last) return;
    D.last = key;
    const c = Math.cos(D.ang), s = Math.sin(D.ang);
    D.mark.setAttribute("d", seg(P(D.cx + 7 * c, CY + 7 * s, 15.5), P(D.cx + 15.5 * c, CY + 15.5 * s, 15.5)));
    const r = (a * Math.PI) / 180, hx = D.px + ARM * Math.cos(r), hy = D.py + ARM * Math.sin(r);
    const bx = D.px + ARM * 0.82 * Math.cos(r + 0.06), by = D.py + ARM * 0.82 * Math.sin(r + 0.06);
    D.arm.setAttribute("d", open([P(D.px, D.py, 18), P(bx, by, 18), P(hx, hy, 17)]));
    place(D.head, P(hx, hy, 16.6));
  }

  const B = register(stage, (dt, now) => {
    let moving = false;
    for (const D of decks) {
      D.rate.t *= Math.exp(-dt * 2.5);
      if (D.rate.t < 0.02) D.rate.t = 0;
      if (stepS(D.rate, dt) || D.rate.t) moving = true;
      D.ang += D.rate.x * dt;
      draw(D, now);
      if (!tdone(D.sw, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  const mids = decks.map((D) => P(D.cx, CY, 15));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.hypot(m[0] - sx, (m[1] - sy) * 1.6); if (d < bd) { bd = d; best = k; } });
    return bd < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a, move) {
    const now = performance.now();
    if (a >= 0 && move) decks[a].rate.t = 9 * speed;
    if (a !== act) {
      act = a;
      decks.forEach((D, k) => {
        tset(D.sw, k === (a < 0 ? FAV : a) ? ON : OFF, now, 0);
        D.rec.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
      });
      read.textContent = a < 0 ? "rest" : "deck " + (a + 1);
    }
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p), true), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { speed = v; }, destroy: bag.dispose };
}

hairline({
  name: "turntables",
  means: "Two turntables and a mixer: the record nearer the pointer spins up while it moves, and its tone arm swings on.",
  rules: [1, 4, 5, 8],
  range: [0.3, 1, 1.6],
  tour: [[150, 170], [250, 200], [200, 180], null],
  mount,
});

loudspeakers.code:
/**
 * Loudspeakers: a stack of four speaker cabinets, two by two on a riser, each
 * with a woofer and a tweeter on its front: a surround, a cone and a dust
 * cap. The cones near the pointer push out, each on its own spring, by a
 * falloff of their distance from it; the cabinet under the pointer is bright.
 * At rest the cones sit a little out, unevenly, and cab 3 is bright. The
 * slider is how far the cones throw.
 *
 * The pattern: a field (terrain's falloff to a floor) on the cones; the pick
 * is the cabinet whose resting face centre is nearest the pointer on screen.
 */
const {
  Cam, clamp, fit, poly, prism, proj, facing, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 42, D = 30, H = 40, FAV = 2, REST = [1.2, 0.4, 2.2, 0.8, 0.6, 1.6, 0.3, 1];
const CABS = [[0, 0], [1, 0], [0, 1], [1, 1]].map(([c, r]) => ({ x0: c * (W + 1), z0: r * H }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let throw_ = value;
  const C = Cam(45, 0.5, 1.95);
  const X1 = 2 * W + 1;
  fit(C, [[-4, -4, -5], [X1 + 4, D + 14, -5], [X1 + 4, -4, -5], [-4, D + 14, -5], [0, 0, 2 * H], [X1, 0, 2 * H], [0, D + 8, 2 * H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [rr, ri] = rings(-4, -4, X1 + 4, D + 4, 3, 1.2);
  put(solid(g), prism(P, front, rr, ri, -5, 0));

  const vring = (cx, cz, y, r, n = 28) => Array.from({ length: n }, (_, i) => {
    const t = (i / n) * Math.PI * 2; return P(cx + r * Math.cos(t), y, cz + r * Math.sin(t));
  });
  const cones = [];
  const cabs = CABS.map((cb, k) => {
    const el = solid(g), [r, i] = rings(cb.x0, 0, cb.x0 + W, D, 3, 1.2);
    put(el, prism(P, front, r, i, cb.z0 + 0.4, cb.z0 + H));
    const cx = cb.x0 + W / 2;
    for (const [cz, R] of [[cb.z0 + 16, 12.5], [cb.z0 + 33, 4.2]]) {
      mk("path", { class: "lo", d: poly(vring(cx, cz, D, R)) }, el.g);
      const cone = mk("path", { class: "nf lo" }, el.g), cap = mk("path", {}, el.g);
      const j = cones.length;
      cones.push({ cx, cz, R, cone, cap, sp: spring(REST[j]), rest: REST[j], at: P(cx, D, cz), drawn: NaN });
    }
    return { k, el, mid: P(cx, D, cb.z0 + H / 2) };
  });

  function draw(q) {
    const p = q.sp.x;
    if (Math.abs(p - q.drawn) < 0.01) return;
    q.drawn = p;
    q.cone.setAttribute("d", poly(vring(q.cx, q.cz, D + p * 0.45, q.R * 0.72)));
    q.cap.setAttribute("d", poly(vring(q.cx, q.cz, D + p, q.R * 0.32, 20)));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const q of cones) { if (stepS(q.sp, dt)) m = true; draw(q); }
    return m;
  });
  bag.add(B.unregister);

  let pt = null;
  function retarget() {
    let best = -1, bd = Infinity;
    if (pt) cabs.forEach((c, k) => { const d = Math.hypot(c.mid[0] - pt[0], c.mid[1] - pt[1]); if (d < bd) { bd = d; best = k; } });
    if (bd > 70) best = -1;
    for (const q of cones) {
      if (best < 0) { q.sp.t = q.rest; continue; }
      const d = Math.hypot(q.at[0] - pt[0], q.at[1] - pt[1]) / 110;
      const f = d < 0.42 ? 1 - (d / 0.42) * 0.69 : Math.max(0.09, 0.31 - (d - 0.42) * 0.6);
      q.sp.t = clamp(f * 7 * throw_, 0, 9);
    }
    cabs.forEach((c, k) => c.el.sil.classList.toggle("hi", k === (best < 0 ? FAV : best)));
    read.textContent = best < 0 ? "rest" : "cab " + (best + 1);
    B.wake();
  }
  retarget();
  bag.add(pointer(stage, { move: (p) => { pt = p; retarget(); }, leave: () => { pt = null; retarget(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { throw_ = v; if (pt) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "loudspeakers",
  means: "A stack of four speaker cabinets: the cones near the pointer push out, and the cabinet under it is bright.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1.25],
  tour: [[160, 150], [230, 200], [200, 120], null],
  mount,
});

filmreels.code:
/**
 * Film reels: an editing bench with three reels on spindles and a strip of
 * film running between them along their front rims. Each reel is a flat disc
 * with a hub and three windows. The pointer picks a reel by where it stands:
 * it lifts on its spindle and turns, the strips on either side of it pull
 * tight, and its neighbours turn a little, staggered from it. At rest the
 * strips hang slack, unevenly, and reel 2 is bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (bookshelf); the pick is the reel
 * whose resting centre is nearest the pointer's x on screen.
 */
const {
  Cam, circ, fit, poly, prism, proj, facing, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const RX = [22, 76, 130], RR = [18, 13, 17], CY = 26, Z0 = 11, T = 3, FAV = 1;
const REST_A = [0.3, 1.1, 2.0], SLACK = [3.5, 2];
const disc = (x, y, r, n = 48) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-2, 2, 0], [152, 52, 0], [152, 2, 0], [-2, 52, 0], [0, 0, Z0 + 14], [150, 0, Z0 + 14]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-2, 2, 152, 52, 4, 1.4);
  put(solid(g), prism(P, front, br, bi, 0, 6));

  const reels = RX.map((cx, k) => {
    put(solid(g), prism(P, front, disc(cx, CY, 2, 20), null, 6, Z0 + 6));
    const el = solid(g), hub = mk("path", { class: "nf lo" }, el.g);
    return { k, cx, R: RR[k], el, hub, z: tween(k === FAV ? 2 : 0), a: tween(REST_A[k]), last: "" };
  });
  const strips = [0, 1].map((j) => ({ j, el: mk("path", { class: "lo" }, g), s: tween(SLACK[j]), last: "" }));

  function drawReel(r, z, a) {
    const key = z.toFixed(2) + "," + a.toFixed(3);
    if (key === r.last) return;
    r.last = key;
    put(r.el, prism(P, front, disc(r.cx, CY, r.R), disc(r.cx, CY, r.R - 1.2), Z0 + z, Z0 + z + T));
    const top = Z0 + z + T, w = (rad, x, y, n = 18) => poly(circ(rad, n).map((q) => P(x + q.u, y + q.v, top)));
    let d = w(3, r.cx, CY);
    for (let i = 0; i < 3; i++) {
      const b = a + (i * Math.PI * 2) / 3, m = r.R * 0.56;
      d += w(r.R * 0.24, r.cx + m * Math.cos(b), CY + m * Math.sin(b));
    }
    r.hub.setAttribute("d", d);
  }
  function drawStrip(st, now) {
    const A = reels[st.j], Bq = reels[st.j + 1];
    const za = tval(A.z, now), zb = tval(Bq.z, now), s = tval(st.s, now);
    const key = [za, zb, s].map((v) => v.toFixed(2)).join();
    if (key === st.last) return;
    st.last = key;
    const up = [], dn = [];
    for (let i = 0; i <= 10; i++) {
      const t = i / 10, x = A.cx + (Bq.cx - A.cx) * t, y = CY + A.R + (Bq.R - A.R) * t + 0.2;
      const z = Z0 + za + (zb - za) * t - s * 4 * t * (1 - t) + 0.2;
      up.push(P(x, y, z + T - 0.4)); dn.unshift(P(x, y, z));
    }
    st.el.setAttribute("d", poly(up.concat(dn)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const r of reels) { drawReel(r, tval(r.z, now), tval(r.a, now)); if (!tdone(r.z, now) || !tdone(r.a, now)) moving = true; }
    for (const st of strips) { drawStrip(st, now); if (!tdone(st.s, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = reels.map((r) => P(r.cx, CY, Z0 + T));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 42 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    reels.forEach((r, k) => {
      const d = Math.abs(k - a), delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(r.z, a < 0 ? (k === FAV ? 2 : 0) : d === 0 ? 9 : 1.5, now, delay);
      tset(r.a, REST_A[k] + (a < 0 ? 0 : d === 0 ? 2.4 : 0.6), now, delay);
      r.el.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    strips.forEach((st) => tset(st.s, a < 0 ? SLACK[st.j] : st.j === a || st.j + 1 === a ? 0 : 1.5, now, 0));
    read.textContent = a < 0 ? "rest" : "reel " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "filmreels",
  means: "Three film reels on a bench: the reel under the pointer lifts and turns, the film pulls tight, and its neighbours turn a little.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[150, 170], [200, 180], [250, 190], null],
  mount,
});

shoppingbags.code:
/**
 * Shopping bags: five paper bags of different sizes standing on the floor,
 * each with an open top and two rope handles. The pointer picks a bag by
 * where it stands: it lifts by its handles, which pull taut, and the bags
 * beside it lift a little, staggered from it. At rest one bag is just picked
 * up, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (bookshelf); the pick is the bag
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, facing, fit, open, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = [16, 11, 20, 10, 14], H = [24, 18, 30, 15, 21], D = [8, 6, 10, 6, 8], Y = [2, 7, 0, 9, 3];
const GAP = 4, LIFT = 16, FAV = 2, REST = [0, 0, 3, 0, 0];
const xs = []; { let x = 0; for (const w of W) { xs.push(x); x += w + GAP; } }
const X1 = xs[4] + W[4];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-6, -6, -3], [X1 + 6, 25, -3], [X1 + 6, -6, -3], [-6, 25, -3], [xs[2], 0, 30 + LIFT + 10], [xs[0], 0, 24 + LIFT + 10]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  { const [r, i] = rings(-6, -6, X1 + 6, 25, 4, 1.4); put(solid(g), prism(P, front, r, i, -3, 0)); }

  const bags = W.map((w, k) => ({ k, w, h: H[k], d: D[k], x0: xs[k], y0: Y[k], z: tween(REST[k]), last: NaN }));
  bags.slice().sort((a, b) => a.x0 + a.y0 - (b.x0 + b.y0)).forEach((b) => {
    b.el = solid(g);
    b.ropes = mk("path", { class: "nf sil" }, b.el.g);
  });

  function arc(b, y, z, hh) {
    const a = b.x0 + b.w * 0.3, c = b.x0 + b.w * 0.7, pts = [];
    for (let i = 0; i <= 12; i++) { const t = i / 12; pts.push(P(a + (c - a) * t, y, z + hh * Math.sin(Math.PI * t))); }
    return open(pts);
  }
  function draw(b, z) {
    if (z === b.last) return;
    b.last = z;
    const [r, i] = rings(b.x0, b.y0, b.x0 + b.w, b.y0 + b.d, 1.2, 0.7);
    put(b.el, prism(P, front, r, i, z, z + b.h));
    const hh = 5 + Math.min(z, LIFT) * 0.25, zt = z + b.h;
    b.ropes.setAttribute("d", arc(b, b.y0 + 1.6, zt, hh) + arc(b, b.y0 + b.d - 1.6, zt, hh));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of bags) { draw(b, tval(b.z, now)); if (!tdone(b.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = bags.map((b) => P(b.x0 + b.w / 2, b.y0 + b.d, b.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    bags.forEach((b, k) => {
      const d = Math.abs(k - a);
      const z = a < 0 ? REST[k] : d === 0 ? LIFT : d === 1 ? 4 : d === 2 ? 1.5 : 0;
      tset(b.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      b.el.sil.classList.toggle("hi", on);
      b.ropes.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "bag " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

