  tour: [[137, 113], [213, 146], [285, 193], null],
  mount,
});

mannequins.code:
/**
 * Mannequins: three dress forms in a shop window, each a shaped torso with a
 * neck cap on a pole and a round base, with a seam down its front. The
 * pointer is what the window turns to: every form swivels on its own spring
 * to face it, and the nearest one is bright. At rest the forms face the
 * street, each a little askew, one bright. The slider is how quickly they
 * follow.
 *
 * The pattern: a continuous aim (officechairs); the hit is on the floor's
 * plane, which never moves.
 */
const {
  Cam, circ, facing, fit, hull, open, poly, prism, proj, rings, ringAt, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const XS = [0, 34, 68], YS = [10, 0, 12], SKEW = [-28, 10, 34], FAV = 1, Z0 = 30;
const LV = [[0, 9, 7], [8, 7.6, 5.6], [13, 7, 5.2], [20, 9.6, 7], [27, 10, 6], [30, 6.5, 4]];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const ell = (rx, ry, a, cx, cy, n = 28) => {
  const c = Math.cos(a), s = Math.sin(a);
  return circ(1, n).map((q) => {
    const u = q.u * rx, v = q.v * ry, nu0 = q.u / rx, nv0 = q.v / ry, l = Math.hypot(nu0, nv0);
    return { u: cx + u * c - v * s, v: cy + u * s + v * c, nu: (nu0 * c - nv0 * s) / l, nv: (nu0 * s + nv0 * c) / l };
  });
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-16, -14, -3], [84, 26, -3], [84, -14, -3], [-16, 26, -3], [0, 10, Z0 + 36], [68, 12, Z0 + 36]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  { const [r, i] = rings(-16, -14, 84, 26, 6, 1.6); put(solid(g), prism(P, front, r, i, -3, 0)); }

  const forms = XS.map((cx, k) => {
    const cy = YS[k], rest = Math.PI / 4 + SKEW[k] * (Math.PI / 180);
    return { k, cx, cy, rest, sp: spring(rest, { k: 100 * value, c: 18 * Math.sqrt(value) }), drawn: NaN };
  });
  forms.slice().sort((p, q) => p.cx + p.cy - (q.cx + q.cy)).forEach((f) => {
    const grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(f.cx, f.cy, 7, 32), disc(f.cx, f.cy, 5.8, 32), 0, 2));
    put(solid(grp), prism(P, front, disc(f.cx, f.cy, 0.9, 12), null, 2, Z0 + 1));
    f.hips = solid(grp);
    f.torso = solid(grp);
    f.seam = mk("path", { class: "nf lo" }, f.torso.g);
    f.neck = solid(grp);
  });

  function draw(f) {
    const a = f.sp.x;
    if (Math.abs(a - f.drawn) < 1e-4) return;
    f.drawn = a;
    const R = LV.map(([z, rx, ry]) => ringAt(P, ell(ry, rx, a, f.cx, f.cy), Z0 + z));
    f.hips.sil.setAttribute("d", poly(hull([].concat(R[0], R[1], R[2]))));
    const pts = [].concat(R[2], R[3], R[4], R[5]);
    const top = ell(LV[5][2] - 0.9, LV[5][1] - 0.9, a, f.cx, f.cy);
    put(f.torso, { sil: poly(hull(pts)), crease: open(ringAt(P, top, Z0 + 30)) });
    const c = Math.cos(a), s = Math.sin(a);
    f.seam.setAttribute("d", c + s > -0.2 ? open(LV.slice(0, 5).map(([z, , ry]) => P(f.cx + c * ry, f.cy + s * ry, Z0 + z))) : "");
    put(f.neck, prism(P, front, disc(f.cx, f.cy, 2.4, 16), disc(f.cx, f.cy, 1.6, 16), Z0 + 30, Z0 + 35));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const f of forms) { if (stepS(f.sp, dt)) m = true; draw(f); }
    return m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = null, bd = Infinity;
    for (const f of forms) {
      if (over) {
        const d = Math.hypot(over[0] - f.cx, over[1] - f.cy);
        if (d < bd) { bd = d; near = f; }
        const aim = d < 4 ? f.sp.t : Math.atan2(over[1] - f.cy, over[0] - f.cx);
        f.sp.t = f.sp.t + wrap(aim - f.sp.t);
      } else f.sp.t = f.sp.t + wrap(f.rest - f.sp.t);
    }
    for (const f of forms) { const on = over ? f === near : f.k === FAV; f.torso.sil.classList.toggle("hi", on); f.hips.sil.classList.toggle("hi", on); }
    read.textContent = near ? "form " + (near.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      over = x < -40 || x > 110 || y < -50 || y > 60 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const f of forms) { f.sp.k = 100 * v; f.sp.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "mannequins",
  means: "Three dress forms in a shop window: every form turns to face the pointer, and the nearest one is bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[76, 190], [211, 225], [324, 243], null],
  mount,
});

vendingmachine.code:
/**
 * Vending machine: a tall cabinet with a glass front, three columns by four
 * rows of spiral slots each holding a pack, a keypad panel beside the glass
 * and a drop tray below. The pointer picks a slot on the glass: its pack
 * slides forward off its spiral and dips, and the packs around it nudge
 * forward, staggered from it. At rest one pack sits forward, bright. The
 * slider is the stagger.
 *
 * The pattern: a grid on a face plane (depositboxes); the pick is the pack
 * whose resting centre is nearest the pointer on screen.
 */
const {
  Cam, facing, fit, open, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const W = 40, D = 26, H = 92, COLS = [8, 17, 26], ROWS = [72, 58, 44, 30], PW = 6, PH = 9, PD = 6;
const OUT = 6, FAV = 7, REST = (k) => (k === FAV ? 2.5 : (k * 7) % 3 === 0 ? 0.6 : 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.8);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, 0, H], [W, 0, H], [0, D + 2, H]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, D, 3, 1.4);
  const body = solid(g);
  put(body, prism(P, front, br, bi, 0, H));
  const face = (u0, z0, u1, z1, r) => poly(rrect(u0, z0, u1, z1, r, 4).map((q) => P(q.u, D, q.v)));
  mk("path", { class: "nf lo", d: face(3, 24, 31, 86, 2) + face(5, 6, 29, 17, 2) + face(33, 50, 38, 80, 1.2) + face(33, 30, 38, 34, 0.8) + seg(P(7, D, 12), P(27, D, 12)) }, body.g);
  for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) place(flatDot(body.g, C, 0.55, "dot off"), P(34.2 + i * 1.8, D, 74 - j * 3));

  const packs = [];
  ROWS.forEach((z, r) => COLS.forEach((x, c) => {
    const k = r * 3 + c, grp = mk("g", {}, g), coil = [];
    for (let i = 0; i <= 48; i++) { const t = (i / 48) * Math.PI * 2 * 4; coil.push(P(x + 3.6 * Math.cos(t), D - 14 + (i / 48) * 12, z + 3.2 + 3.6 * Math.sin(t))); }
    mk("path", { class: "nf lo", d: open(coil) }, grp);
    packs.push({ k, r, c, x, z, el: solid(grp), y: tween(REST(k)), last: NaN });
  }));

  function draw(p, y) {
    if (y === p.last) return;
    p.last = y;
    const y0 = D - 10 + y, dip = Math.max(0, y - 4) * 0.6;
    const [ri, ii] = rings(p.x - PW / 2, y0, p.x + PW / 2, y0 + PD, 1, 0.6);
    put(p.el, prism(P, front, ri, ii, p.z + 1 - dip, p.z + 1 + PH - dip));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const p of packs) { draw(p, tval(p.y, now)); if (!tdone(p.y, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = packs.map((p) => P(p.x, D - 4, p.z + 1 + PH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.hypot(m[0] - sx, m[1] - sy); if (d < bd) { bd = d; best = k; } });
    return bd < 18 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), A = packs[a >= 0 ? a : act >= 0 ? act : FAV];
    act = a;
    packs.forEach((p) => {
      const d = Math.max(Math.abs(p.r - A.r), Math.abs(p.c - A.c));
      const y = a < 0 ? REST(p.k) : d === 0 ? OUT : d === 1 ? 1.6 : 0.4;
      tset(p.y, y, now, Math.hypot(p.r - A.r, p.c - A.c) * stag);
      p.el.sil.classList.toggle("hi", p.k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "slot " + "ABCD"[packs[a].r] + (packs[a].c + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "vendingmachine",
  means: "A vending machine: the pack in the slot under the pointer slides forward off its spiral, the packs around it nudge.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[160, 86], [196, 147], [196, 206], null],
  mount,
});

towercrane.code:
/**
 * Tower crane: a lattice mast on a footing, a jib and a counter-jib with its
 * counterweight, a trolley running on the jib and a hook block on its cable,
 * beside a stack of steel beams. The pointer is where the load should go: the
 * jib slews to face it and the trolley runs out to its distance, both on
 * springs. The hook is the bright mark, at rest and answering. The slider is
 * how quickly the crane follows.
 *
 * The pattern: a continuous aim (spotlights); the hit is on the ground plane,
 * which never moves.
 */
const {
  Cam, clamp, facing, fit, open, poly, prism, proj, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const MH = 88, MW = 3.5, JL = 68, CJ = 24, JW = 1.6, JT = 4, HZ = 24, REST = [-35, 46];
const rot = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.85);
  const pts = [];
  for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; pts.push([JL * Math.cos(a), JL * Math.sin(a), MH + JT], [56 * Math.cos(a), 56 * Math.sin(a), HZ - 4]); }
  fit(C, pts.concat([[-16, -16, -4], [16, 16, -4], [0, 0, MH + 16]]), 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const box = (parent, x0, y0, x1, y1, z0, z1, r = 1, b = 0.6) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(parent); put(s, prism(P, front, o, i, z0, z1)); return s; };
  box(g, -16, -16, 16, 16, -4, 0, 3, 1.2);
  const hookG = mk("g", {}, g);
  // the mast, with bracing on its two visible faces and the slewing cab at its head
  const mastG = mk("g", {}, g);
  box(mastG, -MW, -MW, MW, MW, 0, MH - 6, 0.8, 0.5);
  let br = "";
  for (let z = 0; z < MH - 10; z += 8) {
    br += seg(P(-MW + 0.6, MW, z), P(MW - 0.6, MW, z + 8)) + seg(P(MW, MW - 0.6, z), P(MW, -MW + 0.6, z + 8));
  }
  mk("path", { d: br, class: "nf lo" }, mastG);
  box(mastG, -MW - 1, -MW - 1, MW + 1, MW + 1, MH - 6, MH, 1.2, 0.6);
  // the beams, steel on the ground in front of the mast
  const stack = mk("g", {}, g);
  for (const [y0, z0, x0, x1] of [[18, 0, 26, 56], [23, 0, 26, 56], [28, 0, 26, 56], [20.5, 3, 29, 53], [25.5, 3, 29, 53]]) box(stack, x0, y0, x1, y0 + 4, z0, z0 + 3, 0.8, 0.5);
  const jibG = mk("g", {}, g);
  const cw = solid(jibG), trol = solid(jibG), jib = solid(jibG), apex = mk("path", { class: "nf" }, jibG), ties = mk("path", { class: "nf lo" }, jibG);
  const cable = mk("path", { class: "nf lo" }, hookG), hook = solid(hookG), curl = mk("path", { class: "nf hi" }, hookG);
  hook.sil.classList.add("hi");

  const ang = spring((REST[0] * Math.PI) / 180, { k: 100 * value, c: 18 * Math.sqrt(value) });
  const dist = spring(REST[1], { k: 100 * value, c: 18 * Math.sqrt(value) });
  let last = "", inFront = null;

  function draw() {
    const key = ang.x.toFixed(4) + "," + dist.x.toFixed(2);
    if (key === last) return;
    last = key;
    const a = ang.x, d = dist.x, c = Math.cos(a), s = Math.sin(a);
    const R = (x0, y0, x1, y1, r, b) => rings(x0, y0, x1, y1, r, b).map((ring) => rot(ring, a));
    const [cr, ci] = R(-CJ, -3, -CJ + 9, 3, 1, 0.6); put(cw, prism(P, front, cr, ci, MH - 5, MH));
    const [tr, ti] = R(d - 3, -2.2, d + 3, 2.2, 0.8, 0.5); put(trol, prism(P, front, tr, ti, MH - 3, MH));
    const [jr, ji] = R(-CJ, -JW, JL, JW, 1, 0.5); put(jib, prism(P, front, jr, ji, MH, MH + JT));
    const W = (u, z) => P(u * c, u * s, z);
    apex.setAttribute("d", seg(P(0, 0, MH + JT), P(0, 0, MH + 16)));
    ties.setAttribute("d", seg(P(0, 0, MH + 16), W(JL - 4, MH + JT)) + seg(P(0, 0, MH + 16), W(-CJ + 2, MH + JT)));
    const hx = d * c, hy = d * s;
    cable.setAttribute("d", seg(P(hx, hy, MH - 3), P(hx, hy, HZ + 4)));
    const [hr, hi] = rings(hx - 2, hy - 2, hx + 2, hy + 2, 1, 0.5); put(hook, prism(P, front, hr, hi, HZ, HZ + 4));
    curl.setAttribute("d", open([P(hx, hy, HZ), P(hx, hy, HZ - 3), P(hx + 1.6, hy + 1.6, HZ - 4.4), P(hx + 2.4, hy + 2.4, HZ - 2.6)]));
    // the hook is behind the mast when its ground point is farther than the mast's
    const f = hx + hy > 0;
    if (f !== inFront) { inFront = f; if (f) stack.after(hookG); else mastG.before(hookG); }
  }

  const B = register(stage, (dt) => { const m1 = stepS(ang, dt), m2 = stepS(dist, dt); draw(); return m1 || m2; });
  bag.add(B.unregister);

  function aim(p) {
    let ta = (REST[0] * Math.PI) / 180, td = REST[1];
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      if (r < JL + 30 && r > 4) { ta = Math.atan2(y, x); td = clamp(r, 12, JL - 6); } else p = null;
    }
    ta = ang.t + ((((ta - ang.t) % (2 * Math.PI)) + 3 * Math.PI) % (2 * Math.PI)) - Math.PI;
    ang.t = ta; dist.t = td;
    const deg = Math.round((((ta * 180) / Math.PI) % 360 + 360) % 360);
    read.textContent = p ? `slew ${deg}°` : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return {
    set: (v) => { ang.k = dist.k = 100 * v; ang.c = dist.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "towercrane",
  means: "A tower crane beside a stack of beams: the jib slews toward the pointer and the trolley runs out to its distance.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[292, 260], [102, 263], [230, 290], null],
  mount,
});

garagedoors.code:
/**
 * Garage doors: a block of three garages under one roof slab, on an apron,
 * each opening fitted with a slatted roll-up door under its drum housing. The
 * pointer picks a garage by where it stands: its door rolls up, and the doors
 * beside it roll up partly, staggered from it. At rest one door stands half
 * up, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (bookshelf); the pick is the door
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, DW = 26, GAP = 9, H = 30, DH = 22, D = 34, FAV = 2, REST = [0.08, 0, 0.45];
const W = GAP + N * (DW + GAP);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[0, 0, 0], [W, 0, H + 4], [0, D + 22, -3], [W, D + 22, -3], [0, 0, H + 4], [W + 2, D + 3, H + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const onFace = (y) => (q) => P(q.u, y, q.v);
  const g = mk("g", {}, svg);

  const [ar, ai] = rings(-4, D - 6, W + 4, D + 22, 3, 1.4);
  put(solid(g), prism(P, front, ar, ai, -3, 0));
  const [br, bi] = rings(0, 0, W, D, 2, 1);
  put(solid(g), prism(P, front, br, bi, 0, H));
  const [rr, ri] = rings(-2, -2, W + 2, D + 3, 2, 1);
  put(solid(g), prism(P, front, rr, ri, H, H + 4));

  const doors = [];
  for (let k = 0; k < N; k++) {
    const x0 = GAP + k * (DW + GAP), x1 = x0 + DW;
    // the opening, its back wall line, and the drum housing above it
    mk("path", { d: poly(rrect(x0, 0, x1, DH, 0.8, 2).map(onFace(D))), class: "nf lo" }, g);
    mk("path", { d: seg(P(x0 + 1, D - 0.2, DH - 1), P(x0 + 1, D - 0.2, 1)) + seg(P(x0 + 1, D - 0.2, 1), P(x1 - 1, D - 0.2, 1)), class: "nf lo" }, g);
    const [hr, hi] = rings(x0 - 1, D, x1 + 1, D + 3, 1.2, 0.6);
    const door = mk("path", { class: "sil" }, g), slats = mk("path", { class: "nf lo" }, g);
    put(solid(g), prism(P, front, hr, hi, DH, DH + 4));
    doors.push({ k, x0, x1, door, slats, s: tween(REST[k]), last: NaN });
  }

  function draw(d, s) {
    const zb = s * (DH - 1.5), y = D - 0.6;
    d.door.setAttribute("d", poly(rrect(d.x0 + 0.6, zb, d.x1 - 0.6, DH, 0.6, 2).map(onFace(y))));
    let sl = "";
    for (let z = DH - 2.6; z > zb + 0.8; z -= 2.6) sl += seg(P(d.x0 + 1.4, y, z), P(d.x1 - 1.4, y, z));
    sl += seg(P(d.x0 + DW / 2 - 2, y, zb + 1), P(d.x0 + DW / 2 + 2, y, zb + 1));
    d.slats.setAttribute("d", sl);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const d of doors) {
      const s = tval(d.s, now);
      if (s !== d.last) { draw(d, s); d.last = s; }
      if (!tdone(d.s, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  /** The door whose resting middle is nearest the pointer's x on screen; -1 off the block. */
  const mids = doors.map((d) => P((d.x0 + d.x1) / 2, D, DH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    doors.forEach((d, k) => {
      const dist = Math.abs(k - a);
      const s = a < 0 ? REST[k] : dist === 0 ? 0.82 : dist === 1 ? 0.3 : 0.1;
      tset(d.s, s, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      d.door.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : `garage ${a + 1}`;
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "garagedoors",
  means: "A row of three garages: the door under the pointer rolls up, and the doors beside it roll up partly.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[136, 152], [205, 186], [273, 220], null],
  mount,
});

justicescales.code:
/**
 * Scales of justice: a round pillar on a stepped plinth, a beam on a pivot at
 * its head, and two shallow pans hung from the beam's ends on three chains
 * each. The pointer's side of the pillar is the heavier one: the beam tips
 * toward it on a spring, by how far the pointer stands from the middle, and
 * the lower pan is bright. At rest the beam leans slightly to one side.
 * The slider is how quickly the beam follows.
 *
 * The pattern: a continuous lean (spring on an angle); the hit is on the
 * ground plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, run, ringAt, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PH = 70, L = 34, HANG = 30, PR = 11, MAX = 14, REST = 7, R2 = Math.SQRT1_2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-L * R2 - PR, L * R2 - PR, PH - HANG - 12], [L * R2 + PR, -L * R2 + PR, PH - HANG - 12], [-20, 20, -6], [20, -20, -6], [0, 0, PH + 8], [-L * R2, L * R2, PH + 10], [L * R2, -L * R2, PH + 10]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [r0, i0] = rings(-20, -20, 20, 20, 3, 1.2); put(solid(g), prism(P, front, r0, i0, -6, -2));
  const [r1, i1] = rings(-14, -14, 14, 14, 3, 1.2); put(solid(g), prism(P, front, r1, i1, -2, 2));
  const far = mk("g", {}, g);
  put(solid(g), prism(P, front, circ(3, 32), circ(2.2, 32), 2, PH));
  put(solid(g), prism(P, front, circ(4.5, 32), circ(3.6, 32), PH - 3, PH));
  const beam = mk("path", { class: "sil" }, g), knob = solid(g);
  put(knob, prism(P, front, circ(2, 20), circ(1.4, 20), PH, PH + 8));
  const near = mk("g", {}, g);
  const pans = [far, near].map((parent) => {
    const chains = mk("path", { class: "nf lo" }, parent), dish = solid(parent);
    return { chains, dish };
  });

  const foot = circ(PR * 0.55, 32), top = circ(PR, 40), inner = circ(PR - 1, 40);
  const tilt = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let last = NaN;

  function draw() {
    const t = tilt.x;
    if (t === last) return;
    last = t;
    const a = (t * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a);
    // the beam: a bar through the pivot, a positive tilt drops its +x end
    const ring = (x, z) => Array.from({ length: 16 }, (_, i) => {
      const q = (i / 16) * Math.PI * 2, rr = 1.4;
      const b = x - rr * Math.cos(q) * s, w = rr * Math.sin(q);
      return P(b * R2 + w * R2, -b * R2 + w * R2, z + rr * Math.cos(q) * c);
    });
    const e0 = [-L * c, PH + 4 + L * s], e1 = [L * c, PH + 4 - L * s];
    beam.setAttribute("d", poly(hull(ring(e0[0], e0[1]).concat(ring(e1[0], e1[1])))));
    [e0, e1].forEach(([x, z], k) => {
      const zb = z - HANG, p = pans[k];
      const X = x * R2, Y = -x * R2, shift = (rg) => rg.map((q) => ({ ...q, u: q.u + X, v: q.v + Y }));
      const ft = shift(foot), tp = shift(top), inn = shift(inner);
      put(p.dish, { sil: poly(hull(ringAt(P, ft, zb).concat(ringAt(P, tp, zb + 3)))), crease: open(ringAt(P, run(inn, front), zb + 3)) });
      let ch = "";
      for (let j = 0; j < 3; j++) { const q = (j / 3) * Math.PI * 2 + 0.5; ch += seg(P(X, Y, z - 1.4), P(X + (PR - 1) * Math.cos(q), Y + (PR - 1) * Math.sin(q), zb + 3)); }
      p.chains.setAttribute("d", ch);
    });
  }

  const B = register(stage, (dt) => { const m = stepS(tilt, dt); draw(); return m; });
  bag.add(B.unregister);

  function lean(p) {
    let tt = REST, on = false;
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], 0), d = (x - y) / Math.SQRT2;
      if (Math.abs(d) < 90 && Math.abs(x + y) < 120) { on = true; tt = clamp(Math.round(d * 0.4), -MAX, MAX); }
    }
    tilt.t = tt;
    pans[0].dish.sil.classList.toggle("hi", tt < 0);
    pans[1].dish.sil.classList.toggle("hi", tt >= 0);
    read.textContent = on ? `tilt ${Math.abs(tt)}°` : "rest";
    B.wake();
  }
  lean(null);
  bag.add(pointer(stage, { move: lean, leave: () => lean(null) }));
  bag.add(() => svg.replaceChildren());
  return {
    set: (v) => { tilt.k = 100 * v; tilt.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "justicescales",
  means: "A balance scale on a pillar: the beam tips toward the side the pointer is on, and the lower pan is bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[283, 160], [117, 160], [330, 200], null],
  mount,
});

flagpoles.code:
/**
 * Flagpoles: a plaza slab with four poles of one height, each on a small
 * plinth with a ball finial, and a plain flag on each, a rectangle with one
 * fold line. The pointer picks a pole by where it stands: its flag runs up
 * to the top, and the flags beside it rise partway, staggered from it. At
 * rest the flags fly at uneven heights, one bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (bookshelf); the pick is the pole
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, fillet, fit, facing, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, SP = 26, H = 80, FW = 26, FH = 16, R = 1.3, TOPZ = H - FH - 3;
const REST = [30, 50, 20, 38], FAV = 1;
const ys = Array.from({ length: N }, (_, k) => (N - 1 - k) * SP);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  const Y1 = (N - 1) * SP;
  fit(C, [[-12, -12, -4], [FW + 12, Y1 + 12, -4], [FW + 12, -12, -4], [-12, Y1 + 12, -4], [0, 0, H + 3], [0, Y1, H + 3], [FW, 0, H]], 200, 166);
  const P = proj(C), front = facing(C);

  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-12, -12, FW + 12, Y1 + 12, 5, 1.6);
  put(solid(g), prism(P, front, pr, pi, -4, 0));
  mk("path", { class: "nf lo", d: seg(P(-12, Y1 / 2 - SP / 2, 0), P(FW + 12, Y1 / 2 - SP / 2, 0)) + seg(P(-12, Y1 / 2 + SP / 2, 0), P(FW + 12, Y1 / 2 + SP / 2, 0)) }, g);

  // far to near: the pole with the smallest y first, each pole before its own flag
  const order = ys.map((y, k) => k).sort((a, b) => ys[a] - ys[b]);
  const flags = [];
  for (const k of order) {
    const y = ys[k];
    const box = (h, r, z0, z1, b) => { const [a, i] = rings(-h, y - h, h, y + h, r, b); put(solid(g), prism(P, front, a, i, z0, z1)); };
    box(4, 1.8, 0, 3, 0.8);
    box(R, R, 3, H, 0.4);
    box(2.2, 2.2, H, H + 3, 0.7);
    const grp = mk("g", {}, g);
    flags[k] = { k, y, sil: mk("path", { class: "sil" }, grp), fold: mk("path", { class: "nf lo" }, grp), z: tween(REST[k]), last: NaN };
  }

  function draw(f, z) {
    if (z === f.last) return;
    f.last = z;
    const x0 = R + 0.3, x1 = R + FW, sag = 1.6;
    const pts = fillet([[x0, z], [x1, z - sag], [x1, z + FH - sag], [x0, z + FH]], [0.6, 1.2, 1.2, 0.6], 3);
    f.sil.setAttribute("d", poly(pts.map(([x, zz]) => P(x, f.y, zz))));
    const xm = (x0 + x1) / 2;
    f.fold.setAttribute("d", seg(P(xm, f.y, z - sag / 2 + 1), P(xm, f.y, z + FH - sag / 2 - 1)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const f of flags) { draw(f, tval(f.z, now)); if (!tdone(f.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  /** The pole whose resting middle is nearest the pointer's x on screen; -1 off the plaza. */
  const mids = ys.map((y) => P(FW / 2, y, H / 2));
  const top = P(0, 0, H + 6)[1], foot = P(FW + 12, Y1 + 12, 0)[1];
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 26 && sy > top && sy < foot ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    flags.forEach((f, k) => {
      const d = Math.abs(k - a);
      const z = a < 0 ? REST[k] : d === 0 ? TOPZ : Math.max(REST[k], TOPZ - 8 - 10 * d);
      tset(f.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      f.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "flag " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "flagpoles",
  means: "Four flagpoles on a plaza: the flag under the pointer runs up to the top, and the flags beside it rise partway.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[146, 184], [218, 118], [254, 130], null],
  mount,
});

atms.code:
/**
 * ATMs: a bank wall with three cash machines set in it, each a fascia with a
 * screen, a keypad, a card slot and a cash slot. The pointer picks a machine
 * on the wall's face: its cash slot pushes out a stack of notes, and the
 * machines beside it push a little, staggered from it. At rest one machine
 * holds its notes half out, bright. The slider is the stagger.
 *
 * The pattern: one of many on a face (depositboxes); the hit is read on the
 * fascias' face plane, which never moves.
 */
const {
  Cam, clamp, facing, fit, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, AW = 30, GAP = 10, M = 10, D = 14, FD = 3, H = 76, Z0 = 12, Z1 = 64, OUT = 22;
const W = 2 * M + N * AW + (N - 1) * GAP, FAV = 1, REST = [2.5, 11, 1.2];
const CZ0 = 21, CZ1 = 24.4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D + FD + OUT, CZ0], [0, 0, H], [W, 0, H], [0, D, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const onFace = (y) => (q) => P(q.u, y, q.v);
  const Y = D + FD;

  const g = mk("g", {}, svg);
  const [wr, wi] = rings(0, 0, W, D, 3, 1.4);
  put(solid(g), prism(P, front, wr, wi, 0, H));
  mk("path", { class: "nf lo", d: seg(P(1.5, D, 6), P(W - 1.5, D, 6)) }, g);

  const atms = [];
  for (let c = 0; c < N; c++) {
    const x0 = M + c * (AW + GAP), x1 = x0 + AW, xm = (x0 + x1) / 2;
    const [fr, fi] = rings(x0, D - 1, x1, Y, 1.6, 0.8);
    const fas = solid(g);
    put(fas, prism(P, front, fr, fi, Z0, Z1));
    let d = poly(rrect(x0 + 4, Z1 - 20, x1 - 4, Z1 - 5, 1.6, 3).map(onFace(Y)));
    // keypad: a pad of twelve keys, three by four
    const kx0 = x0 + 4, kz0 = 31, kw = 3.2, kh = 2.4;
    for (let i = 0; i < 3; i++) for (let j = 0; j < 4; j++)
      d += poly(rrect(kx0 + i * (kw + 1), kz0 + j * (kh + 0.9), kx0 + i * (kw + 1) + kw, kz0 + j * (kh + 0.9) + kh, 0.6, 2).map(onFace(Y)));
    // card slot beside the keypad, cash slot below
    d += poly(rrect(x1 - 11, 38, x1 - 4, 40.4, 0.8, 2).map(onFace(Y)));
    d += poly(rrect(xm - 9, CZ0 - 0.8, xm + 9, CZ1 + 0.8, 1, 3).map(onFace(Y)));
    mk("path", { class: "nf lo", d }, fas.g);
    atms.push({ c, xm, x0, x1 });
  }
  // the notes, after every fascia: they only ever come out over the machines below and beside them
  for (const a of atms) {
    a.el = solid(g);
    a.edge = mk("path", { class: "nf lo" }, a.el.g);
    a.s = tween(REST[a.c]);
    a.last = NaN;
  }

  function draw(a, s) {
    const [r, i] = rings(a.xm - 7.5, Y - 1, a.xm + 7.5, Y + s, 0.8, Math.min(0.6, s * 0.3));
    put(a.el, prism(P, front, r, i, CZ0, CZ1));
    const yf = Y + s;
    a.edge.setAttribute("d", seg(P(a.xm - 7, yf, CZ0 + 1.1), P(a.xm + 7, yf, CZ0 + 1.1)) + seg(P(a.xm - 7, yf, CZ0 + 2.3), P(a.xm + 7, yf, CZ0 + 2.3)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const a of atms) {
      const s = tval(a.s, now);
      if (s !== a.last) { draw(a, s); a.last = s; }
      if (!tdone(a.s, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  /** The machine under the point, read on the fascias' face plane (y = D + FD), which never moves. */
  function hit([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + Y * s) / c, YY = x * s + Y * c, z = (YY * C.k - (sy - C.oy) / C.S) / zf;
    if (x < M - GAP / 2 || x > W - M + GAP / 2 || z < Z0 - 8 || z > Z1 + 4) return -1;
    return clamp(Math.floor((x - M + GAP / 2) / (AW + GAP)), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    atms.forEach((m, k) => {
      const d = Math.abs(k - a);
      const s = a < 0 ? REST[k] : d === 0 ? OUT : d === 1 ? 6 : 2.4;
      tset(m.s, s, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      m.el.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "atm " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "atms",
  means: "A bank wall with three cash machines: the one under the pointer pushes a stack of notes out of its slot, its neighbours a little.",
  rules: [1, 2, 5, 6],
  range: [0, 60, 120],
  tour: [[139, 138], [204, 170], [269, 203], null],
  mount,
});

goldbars.code:
/**
 * Gold bars: a pyramid of ten ingots, four, three, two and one, on a vault
 * shelf, each bar a trapezoid, its top narrower than its foot. The pointer
 * picks a bar: it slides out of the stack toward the reader, lifts and tilts
 * up at its front, and the bars around it lift slightly, staggered from it.
 * At rest one bar sits half drawn, bright, the rest a little uneven. The
 * slider is the stagger.
 *
 * The pattern: stepped parts; the hit unprojects onto each bar's own rest
 * top, highest row first.
 */
const {
  Cam, facing, fit, hull, open, poly, prism, proj, rings, rrect, run, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BW = 12, BL = 28, BH = 6, GP = 1, IN = 1.6, OUT = 16, LIFT = 12, TILT = 0.22, FAV = 5;
const bars = [];
for (let r = 0; r < 4; r++) for (let i = 0; i < 4 - r; i++) bars.push({ r, x: r * (BW + GP) / 2 + i * (BW + GP), z: r * BH });
const REST = [0.6, -0.4, 1.2, 0, 1, 7, -0.6, 0.4, 1.4, 0.2];
const XW = 4 * BW + 3 * GP;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.45);
  fit(C, [[-6, -6, -4], [XW + 6, BL + 8, -4], [XW + 6, -6, -4], [-6, BL + 8, -4], [XW / 2, 0, 4 * BH], [0, BL + OUT, LIFT + BH + 6], [XW, BL + OUT, LIFT + BH + 6]], 200, 166);
  const P = proj(C), front = facing(C);

  const g = mk("g", {}, svg);
  const [sr, si] = rings(-6, -6, XW + 6, BL + 8, 2.4, 1.2);
  put(solid(g), prism(P, front, sr, si, -4, 0));
  const foot = rrect(-BW / 2, -BL / 2, BW / 2, BL / 2, 1.2, 3), top = rrect(-BW / 2 + IN, -BL / 2 + IN, BW / 2 - IN, BL / 2 - IN, 1, 3);
  const inner = rrect(-BW / 2 + IN + 0.7, -BL / 2 + IN + 0.7, BW / 2 - IN - 0.7, BL / 2 - IN - 0.7, 0.6, 3);
  const innerF = run(inner, front);
  bars.forEach((b, k) => { b.k = k; b.el = solid(g); b.y = tween(REST[k]); b.l = tween(k === FAV ? 2 : 0); b.last = ""; });

  function draw(b, y, l) {
    const key = y.toFixed(2) + "," + l.toFixed(2);
    if (key === b.last) return;
    b.last = key;
    const a = TILT * Math.max(0, (y - 2) / OUT) + 0.04 * l / LIFT, ca = Math.cos(a), sa = Math.sin(a);
    const cx = b.x + BW / 2, cy = BL / 2 + y, z0 = b.z + l;
    // tilt about the bar's back foot edge: the front comes up
    const W3 = (q, h) => { const v = q.v + BL / 2; return P(cx + q.u, cy - BL / 2 + v * ca - h * sa, z0 + v * sa + h * ca); };
    b.el.sil.setAttribute("d", poly(hull(foot.map((q) => W3(q, 0)).concat(top.map((q) => W3(q, BH))))));
    b.el.cr.setAttribute("d", open(innerF.map((q) => W3(q, BH))));
  }

  let painted = "";
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of bars) { draw(b, tval(b.y, now), tval(b.l, now)); if (!tdone(b.y, now) || !tdone(b.l, now)) moving = true; }
    const order = bars.slice().sort((a, c) => (a.z + tval(a.l, now)) * 30 + a.x + tval(a.y, now) - ((c.z + tval(c.l, now)) * 30 + c.x + tval(c.y, now)));
    const k = order.map((b) => b.k).join();
    if (k !== painted) { painted = k; for (const b of order) g.appendChild(b.el.g); }
    return moving;
  });
  bag.add(B.unregister);

  /** Each bar's own rest top, highest row first: the first whose top holds the pointer. */
  const byHeight = bars.slice().sort((a, c) => c.z - a.z);
  function hit([sx, sy]) {
    for (const b of byHeight) {
      const [x, y] = unproj(C, sx, sy, b.z + BH), y0 = REST[b.k];
      if (x > b.x - 0.5 && x < b.x + BW + 0.5 && y > y0 - 1 && y < y0 + BL + 5) return b.k;
    }
    return -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const dd = (p, q) => Math.hypot((bars[p].x - bars[q].x) / (BW + GP), bars[p].r - bars[q].r);
    bars.forEach((b, k) => {
      const d = a < 0 ? 0 : dd(k, a);
      const y = a < 0 ? REST[k] : d === 0 ? OUT : REST[k];
      const l = a < 0 ? (k === FAV ? 2 : 0) : d === 0 ? LIFT : d < 1.2 ? 2.4 : d < 2.2 ? 1 : 0;
      const delay = from < 0 ? 0 : dd(k, from) * stag;
      tset(b.y, y, now, delay); tset(b.l, l, now, delay);
      b.el.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bar " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "goldbars",
  means: "A pyramid of ten gold bars on a vault shelf: the bar under the pointer slides out, lifts and tilts, the bars around it lift slightly.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[121, 136], [206, 101], [254, 178], null],
  mount,
});

sortingcubbies.code:
/**
 * Sorting cubbies: a mail rack of twelve open cubbies, four across and three
 * high, each holding a letter or a parcel whose front stands proud of the
 * rack. The pointer picks a cubby on the rack's face: its piece slides out
 * toward the reader, and the pieces around it come out a little, staggered
 * from it. At rest the pieces stand unevenly out, one letter half pulled,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many on a face (depositboxes); the hit is read on the
 * rack's face plane, which never moves.
 */
const {
  Cam, clamp, facing, fit, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NC = 4, NR = 3, CW = 24, CH = 18, M = 3, D = 18, OUT = 22;
const W = 2 * M + NC * CW, H = 2 * M + NR * CH + 4, FAV = [1, 1];
const PARCEL = [[0, 2], [2, 0], [3, 1]];
const PROUD = [[1.6, 3, 1.2], [2.2, 10, 1.4], [1.2, 1.6, 3.4], [2.8, 1.2, 1.8]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D + OUT, M], [0, 0, H], [W, 0, H], [0, D, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const onFace = (y) => (q) => P(q.u, y, q.v);

  const g = mk("g", {}, svg);
  const [wr, wi] = rings(0, 0, W, D, 2.4, 1.2);
  put(solid(g), prism(P, front, wr, wi, 0, H));
  const items = [];
  let mouths = "";
  for (let c = 0; c < NC; c++) for (let r = 0; r < NR; r++) {
    const x0 = M + c * CW + 1, x1 = M + (c + 1) * CW - 1, z0 = M + 4 + r * CH, z1 = z0 + CH - 2;
    mouths += poly(rrect(x0, z0, x1, z1, 1.2, 3).map(onFace(D)));
    const parcel = PARCEL.some(([pc, pr]) => pc === c && pr === r);
    items.push({ c, r, x0: x0 + (parcel ? 3 : 2), x1: x1 - (parcel ? 3 : 2), z0: z0 + 0.6, z1: z0 + (parcel ? 10 : 2.2), parcel, rest: PROUD[c][r] });
  }
  mk("path", { class: "nf lo", d: mouths + seg(P(1.4, D, M + 1.6), P(W - 1.4, D, M + 1.6)) }, g);
  // left to right, bottom to top: a piece is only ever hidden by one to its right or above it
  for (const it of items) {
    it.el = solid(g);
    it.mark = mk("path", { class: "nf lo" }, it.el.g);
    it.s = tween(it.rest);
    it.last = NaN;
  }

  function draw(it, s) {
    const yf = D + s, xm = (it.x0 + it.x1) / 2;
    const [r, i] = rings(it.x0, D, it.x1, yf, 0.8, Math.min(0.6, s * 0.3));
    put(it.el, prism(P, front, r, i, it.z0, it.z1));
    let d;
    if (it.parcel) d = seg(P(xm, D, it.z1), P(xm, yf, it.z1)) + seg(P(xm, yf, it.z0), P(xm, yf, it.z1));
    else { const v = Math.min(6, s * 0.6); d = seg(P(it.x0 + 0.8, yf, it.z1), P(xm, yf - v, it.z1)) + seg(P(xm, yf - v, it.z1), P(it.x1 - 0.8, yf, it.z1)); }
    it.mark.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) {
      const s = tval(it.s, now);
      if (s !== it.last) { draw(it, s); it.last = s; }
      if (!tdone(it.s, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  /** The cubby under the point, read on the rack's face plane (y = D), which never moves. */
  function hit([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + D * s) / c, Y = x * s + D * c, z = (Y * C.k - (sy - C.oy) / C.S) / zf;
    if (x < M || x > W - M || z < M + 2 || z > M + 4 + NR * CH) return -1;
    return clamp(Math.floor((x - M) / CW), 0, NC - 1) * NR + clamp(Math.floor((z - M - 4) / CH), 0, NR - 1);
  }

  let act = -2;
  const favI = FAV[0] * NR + FAV[1];
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const ac = a >= 0 ? items[a] : null, fc = from >= 0 ? items[from] : null;
    items.forEach((it, i) => {
      const dist = ac ? Math.abs(it.c - ac.c) + Math.abs(it.r - ac.r) : 0;
      const s = a < 0 ? it.rest : dist === 0 ? OUT : dist === 1 ? 7 : dist === 2 ? 3 : 1.2;
      tset(it.s, s, now, fc ? (Math.abs(it.c - fc.c) + Math.abs(it.r - fc.r)) * stag : 0);
      it.el.sil.classList.toggle("hi", i === (a < 0 ? favI : a));
    });
    read.textContent = a < 0 ? "rest" : `cubby ${ac.c + 1}·${NR - ac.r}`;
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "sortingcubbies",
  means: "A mail sorting rack of twelve cubbies: the letter in the cubby under the pointer slides out toward you, its neighbours a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[135, 184], [183, 157], [268, 159], null],
  mount,
});

chickencoop.code:
/**
 * Chicken coop: a house on four short legs under a gabled roof, a ramp down
 * from its door, and a nesting box along its side with a row of four hinged
 * hatches, an egg in each nest. The pointer picks a hatch by where it stands:
 * that hatch swings up to show its egg, and the hatches beside it lift a
 * little, staggered from it. At rest one hatch is propped open, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), hinged lids.
 */
const {
  Cam, circ, fillet, fit, facing, hull, open, poly, prism, proj, rad, rings, ringAt, run, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, W = 13, X0 = 6, HY = 50.5, HZ = 32, D = 14.5, OPEN = 66, FAV = 1, REST = [4, 40, 0, 9];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const rnd = (pts, r = 1.2) => poly(fillet(pts, pts.map(() => r), 3));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[0, 0, 0], [60, 50, 0], [88, 32, 0], [-4, -4, 43], [-4, 54, 43], [-4, 25, 58], [64, 25, 58], [5, 66, 18], [59, 66, 18]], 200, 166);
  const P = proj(C), front = facing(C), g = mk("g", {}, svg);
  const Pv = (p) => P(p[0], p[1], p[2]);

  for (const [x, y] of [[3, 3], [57, 3], [3, 47], [57, 47]]) put(solid(g), prism(P, front, disc(x, y, 1.8, 16), null, 0, 11));
  const [br, bi] = rings(0, 0, 60, 50, 3, 1.5);
  put(solid(g), prism(P, front, br, bi, 10, 44));
  mk("path", { d: rnd([P(60, 20, 12.5), P(60, 32, 12.5), P(60, 32, 27), P(60, 20, 27)], 2), class: "nf lo" }, g);
  // the ramp: a plank from the door sill to the ground, with cleats
  const rp = [[60.5, 21, 12], [60.5, 31, 12], [88, 31, 0], [88, 21, 0]];
  const ramp = rp.map(Pv).concat(rp.map((p) => P(p[0], p[1], p[2] - 1.4)));
  mk("path", { d: rnd(hull(ramp), 0.8), class: "sil" }, g);
  let cleats = "";
  for (let i = 1; i < 6; i++) { const t = i / 6, x = 60.5 + 27.5 * t, z = 12 * (1 - t) + 0.3; cleats += seg(P(x, 22, z), P(x, 30, z)); }
  mk("path", { d: cleats, class: "nf lo" }, g);
  // the roof: eaves and a ridge, its gable end facing the ramp
  const roof = [[-4, -4, 43], [64, -4, 43], [64, 54, 43], [-4, 54, 43], [-4, 25, 58], [64, 25, 58]].map(Pv);
  mk("path", { d: rnd(hull(roof), 1.5), class: "sil" }, g);
  mk("path", { d: seg(roof[4], roof[5]) + seg(roof[1], roof[5]) + seg(roof[5], roof[2]), class: "nf lo" }, g);

  // the nesting box, its eggs, then its walls again in front of them
  const [nr, ni] = rings(X0 - 1, 50, X0 + N * W + 1, 64.5, 2, 1);
  const box = prism(P, front, nr, ni, 18, HZ);
  put(solid(g), box);
  const egg = [];
  for (let k = 0; k < N; k++) {
    const pts = [], x = X0 + k * W + W / 2 + (k % 2 ? 0.8 : -0.6);
    for (const [r, z] of [[2.6, 26], [3.3, 28], [3, 30], [1.6, 31.6]]) pts.push(...ringAt(P, disc(x, 57.5, r, 16), z));
    egg.push(mk("path", { d: poly(hull(pts)) }, g));
  }
  const fr = run(nr, front);
  mk("path", { d: poly(ringAt(P, fr, HZ).concat(ringAt(P, fr, 18).reverse())), class: "fo" }, g);
  mk("path", { d: box.sil, class: "nf sil" }, g);
  mk("path", { d: box.crease, class: "nf lo" }, g);

  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    items.push({ k, sil: mk("path", { class: "sil" }, grp), edge: mk("path", { class: "nf lo" }, grp), a: tween(REST[k]), last: NaN });
  }
  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const t = rad(deg), c = Math.cos(t), s = Math.sin(t), x0 = X0 + it.k * W + 0.7, x1 = x0 + W - 1.4;
    const q = (x, d, h) => P(x, HY + d * c - h * s, HZ + d * s + h * c);
    const pts = [q(x0, 0, 0), q(x1, 0, 0), q(x1, D, 0), q(x0, D, 0), q(x0, 0, 1.4), q(x1, 0, 1.4), q(x1, D, 1.4), q(x0, D, 1.4)];
    it.sil.setAttribute("d", rnd(hull(pts), 1));
    it.edge.setAttribute("d", open([q(x0 + 0.8, D, 1.4), q(x1 - 0.8, D, 1.4)]) + seg(q(x0 + 4, D - 0.2, 1.4), q(x1 - 4, D - 0.2, 1.4)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(X0 + it.k * W + W / 2, 57, HZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 13 && Math.abs(mids[best][1] - sy) < 30 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? REST[k] : dd === 0 ? OPEN : dd === 1 ? 14 : 0;
      tset(it.a, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "nest " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "chickencoop",
  means: "A chicken coop with a row of nest hatches: the hatch under the pointer swings up to show its egg, its neighbours lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[140, 160], [197, 188], [178, 179], null],
  mount,
});

windsocks.code:
/**
 * Windsocks: three striped socks on tall poles along the grass at the edge of
 * a runway, its edge lights in a row. The pointer is the wind: every sock
 * swings on its own spring to stream toward it, and fills out straight the
 * nearer it is, hanging slack when far. The nearest sock is bright. At rest
 * the socks drift each their own way, half full, one bright. The slider is
 * how quickly they follow (a stiffer or softer spring).
 *
 * The pattern: a continuous aim (terrain's spring, an angle and a fill per
 * sock); the hit is on the plane of the sock mouths, which never moves.
 */
const {
  Cam, circ, clamp, fit, facing, flatDot, hull, open, place, poly, prism, proj, rad, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const POLES = [[0, 0], [50, 16], [100, -6]], H = 44, L = 27, R0 = 5, R1 = 2.4, FAV = 1;
const REST = [[150, 0.45], [205, 0.7], [120, 0.35]];
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));
const disc = (x, y, r, n = 16) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.75);
  const ext = [[-20, 34, 0], [130, 34, 0], [-20, 66, 0], [130, 66, 0]];
  for (const [x, y] of POLES) ext.push([x - L, y - L, H], [x + L, y + L, H], [x - L, y + L, H], [x + L, y - L, H], [x, y, 0]);
  fit(C, ext, 200, 160);
  const P = proj(C), front = facing(C), g = mk("g", {}, svg);
  const O = P(0, 0, 0), ax = [0, 1, 2].map((i) => { const q = P(i === 0, i === 1, i === 2); return [q[0] - O[0], q[1] - O[1]]; });
  let view = cross(ax.map((a) => a[0]), ax.map((a) => a[1]));
  if (view[2] < 0) view = view.map((v) => -v);

  // the runway's edge, with its lights
  const [rr, ri] = rings(-20, 34, 130, 66, 4, 2);
  put(solid(g), prism(P, front, rr, ri, 0, 1.2));
  for (let x = -10; x <= 120; x += 26) place(flatDot(g, C, 1.3, "dot off"), P(x, 37, 1.2));

  const socks = POLES.map(([px, py], k) => {
    const grp = mk("g", {}, g), pole = mk("g", {}, grp);
    put(solid(pole), prism(P, front, rings(px - 4, py - 4, px + 4, py + 4, 2, 1)[0], null, 0, 1.6));
    put(solid(pole), prism(P, front, disc(px, py, 1.1), null, 1.6, H + 2.5));
    const sock = mk("g", {}, grp);
    const s = {
      k, px, py, grp, pole, sock, after: null, drawn: "",
      sil: mk("path", { class: "sil" }, sock), mouth: mk("path", { class: "nf lo" }, sock), bands: mk("path", { class: "nf lo" }, sock),
      th: spring(rad(REST[k][0]), { k: 100 * value, c: 18 * Math.sqrt(value) }), f: spring(REST[k][1], { k: 100 * value, c: 18 * Math.sqrt(value) }),
    };
    return s;
  });

  function draw(s) {
    const th = s.th.x, f = clamp(s.f.x, 0, 1), key = th.toFixed(4) + f.toFixed(4);
    if (key === s.drawn) return;
    s.drawn = key;
    const dr = (1 - f) * rad(62), d = [Math.cos(th) * Math.cos(dr), Math.sin(th) * Math.cos(dr), -Math.sin(dr)];
    const e1 = [-Math.sin(th), Math.cos(th), 0], e2 = cross(d, e1);
    const top = [s.px, s.py, H + 1.5], len = L * (0.82 + 0.18 * f);
    const ring = (t, r, a0 = 0, span = Math.PI * 2, n = 24) => {
      const c = top.map((v, i) => v + d[i] * (1.5 + t * len)), out = [];
      for (let i = 0; i <= n; i++) { const a = a0 + (i / n) * span, ca = Math.cos(a), sa = Math.sin(a); out.push(P(...c.map((v, j) => v + r * (ca * e1[j] + sa * e2[j])))); }
      return out;
    };
    const rad0 = R0, rad1 = R1 * (0.7 + 0.3 * f);
    s.sil.setAttribute("d", poly(hull(ring(0, rad0).concat(ring(1, rad1)))));
    const a0 = Math.atan2(dot(e2, view), dot(e1, view)) - Math.PI / 2;
    s.mouth.setAttribute("d", dot(d, view) < 0 ? poly(ring(0, rad0)) : open(ring(0, rad0, a0, Math.PI)));
    s.bands.setAttribute("d", [1 / 3, 2 / 3].map((t) => open(ring(t, rad0 + (rad1 - rad0) * t, a0, Math.PI, 14))).join(""));
    const after = d[0] + d[1] > 0;
    if (after !== s.after) { s.after = after; if (after) s.pole.after(s.sock); else s.sock.after(s.pole); }
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const s of socks) { if (stepS(s.th, dt)) m = true; if (stepS(s.f, dt)) m = true; draw(s); }
    return m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = null, bd = Infinity;
    for (const s of socks) {
      let aim = rad(REST[s.k][0]), fill = REST[s.k][1];
      if (over) {
        const dd = Math.hypot(over[0] - s.px, over[1] - s.py);
        if (dd < bd) { bd = dd; near = s; }
        if (dd > 3) aim = Math.atan2(over[1] - s.py, over[0] - s.px); else aim = s.th.t;
        fill = 0.3 + 0.7 * clamp(1 - dd / 110, 0, 1);
      }
      s.th.t = s.th.t + wrap(aim - s.th.t);
      s.f.t = fill;
    }
    for (const s of socks) s.sil.classList.toggle("hi", over ? s === near : s.k === FAV);
    if (near) { const deg = Math.round((((Math.atan2(over[1] - near.py, over[0] - near.px) * 180) / Math.PI + 135 + 360) % 360) / 10) * 10; read.textContent = "wind " + deg + "°"; }
    else read.textContent = "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], H), dx = x - 50, dy = y - 3;
      over = Math.hypot(dx, dy) > 120 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const s of socks) for (const sp of [s.th, s.f]) { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "windsocks",
  means: "Three windsocks at a runway's edge: every sock swings to stream toward the pointer like wind, and fills out straight when it is near.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[160, 100], [204, 145], [266, 188], null],
  mount,
});

beachumbrellas.code:
/**
 * Beach umbrellas: four umbrellas on a strip of sand, each on its pole beside
 * a sun lounger with a raised backrest, the water's edge running along the
 * near side. The pointer is the sun: every canopy tilts on its own spring to
 * face it, leaning further the nearer it is, and the nearest is bright. At
 * rest the canopies lean each their own way, one bright. The slider is how
 * quickly they follow (a stiffer or softer spring).
 *
 * The pattern: a continuous aim (terrain's spring, two tilt components per
 * canopy); the hit is on the plane of the canopy hubs, which never moves.
 */
const {
  Cam, clamp, fillet, fit, facing, hull, open, poly, prism, proj, rad, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SPOTS = [[0, 0], [48, -10], [96, 4], [144, -6]], HT = 38, RC = 20, NS = 8, MAXT = rad(28), FAV = 2;
const REST = [[-0.25, 0.2], [0.15, 0.3], [0.3, -0.1], [-0.1, -0.3]];
const rnd = (pts, r) => poly(fillet(pts, pts.map(() => r), 3));
const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.5);
  const ext = [[-26, -30, 0], [170, -30, 0], [-26, 48, 0], [170, 48, 0]];
  for (const [x, y] of SPOTS) ext.push([x - RC - 6, y - RC - 6, HT + 4], [x + RC + 6, y + RC + 6, HT - 8]);
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C), g = mk("g", {}, svg);
  const O = P(0, 0, 0), ax = [0, 1, 2].map((i) => { const q = P(i === 0, i === 1, i === 2); return [q[0] - O[0], q[1] - O[1]]; });
  let view = cross(ax.map((a) => a[0]), ax.map((a) => a[1]));
  if (view[2] < 0) view = view.map((v) => -v);

  const [sr, si] = rings(-26, -30, 170, 48, 6, 2);
  put(solid(g), prism(P, front, sr, si, 0, 2));
  const shore = [];
  for (let x = -18; x <= 162; x += 6) shore.push(P(x, 38 + 2.2 * Math.sin(x / 9), 2));
  mk("path", { d: open(shore), class: "nf lo" }, g);

  const ums = SPOTS.map(([cx, cy], k) => {
    const grp = mk("g", {}, g);
    // the lounger: a low frame, its backrest raised at the head
    const [lr, li] = rings(cx - 6, cy - 4, cx + 6, cy + 24, 2, 1);
    put(solid(grp), prism(P, front, lr, li, 0, 5));
    const bk = [[cx - 5.5, cy + 4, 5], [cx + 5.5, cy + 4, 5], [cx + 5.5, cy - 4, 15], [cx - 5.5, cy - 4, 15]];
    const bp = bk.map((p) => P(...p)).concat(bk.map((p) => P(p[0], p[1] - 1.2, p[2] - 0.6)));
    mk("path", { d: rnd(hull(bp), 1), class: "sil" }, grp);
    mk("path", { d: seg(P(cx - 4.5, cy + 3.4, 5.6), P(cx + 4.5, cy + 3.4, 5.6)), class: "nf lo" }, grp);
    const hub = [cx + 10, cy - 2, HT];
    put(solid(grp), prism(P, front, rings(hub[0] - 1, hub[1] - 1, hub[0] + 1, hub[1] + 1, 1, 0.4)[0], null, 0, HT));
    const r0 = REST[k];
    return {
      k, hub, grp,
      sil: mk("path", { class: "sil" }, grp), ribs: mk("path", { class: "nf lo" }, grp),
      tx: spring(r0[0], { k: 100 * value, c: 18 * Math.sqrt(value) }), ty: spring(r0[1], { k: 100 * value, c: 18 * Math.sqrt(value) }), drawn: "",
    };
  });

  function draw(u) {
    const tx = u.tx.x, ty = u.ty.x, key = tx.toFixed(4) + ty.toFixed(4);
    if (key === u.drawn) return;
    u.drawn = key;
    const a = Math.min(Math.hypot(tx, ty), MAXT), kx = a ? -ty / Math.hypot(tx, ty) : 1, ky = a ? tx / Math.hypot(tx, ty) : 0;
    const ca = Math.cos(a), sa = Math.sin(a), K = [kx, ky, 0];
    const R = (v) => { const kv = cross(K, v), d = dot(K, v); return v.map((c, i) => c * ca + kv[i] * sa + K[i] * d * (1 - ca) + u.hub[i]); };
    const apex = R([0, 0, 3]), rim = [];
    for (let i = 0; i < NS; i++) { const b = (i / NS) * Math.PI * 2 + 0.2; rim.push(R([RC * Math.cos(b), RC * Math.sin(b), -6])); }
    const sp = [apex, ...rim].map((p) => P(...p));
    u.sil.setAttribute("d", rnd(hull(sp), 1.5));
    const sub = (p, q) => p.map((v, i) => v - q[i]);
    const vis = rim.map((v, i) => dot(cross(sub(v, apex), sub(rim[(i + 1) % NS], apex)), view) > 0);
    let d = "";
    for (let i = 0; i < NS; i++) if (vis[i] || vis[(i + NS - 1) % NS]) d += seg(sp[0], sp[i + 1]);
    u.ribs.setAttribute("d", d);
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const u of ums) { if (stepS(u.tx, dt)) m = true; if (stepS(u.ty, dt)) m = true; draw(u); }
    return m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = null, bd = Infinity;
    for (const u of ums) {
      let t = REST[u.k];
      if (over) {
        const dx = over[0] - u.hub[0], dy = over[1] - u.hub[1], dd = Math.hypot(dx, dy);
        if (dd < bd) { bd = dd; near = u; }
        const m = MAXT * (0.45 + 0.55 * clamp(1 - dd / 120, 0, 1));
        t = dd > 2 ? [(dx / dd) * m, (dy / dd) * m] : [u.tx.t, u.ty.t];
      }
      u.tx.t = t[0]; u.ty.t = t[1];
    }
    for (const u of ums) u.sil.classList.toggle("hi", over ? u === near : u.k === FAV);
    read.textContent = near ? "umbrella " + (near.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], HT);
      over = Math.hypot(x - 82, y + 3) > 150 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const u of ums) for (const sp of [u.tx, u.ty]) { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "beachumbrellas",
  means: "Four beach umbrellas over sun loungers: every canopy tilts on a spring to face the pointer like the sun, and the nearest is bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[150, 110], [243, 157], [292, 201], null],
  mount,
});

dnamodel.code:
/**
 * DNA model: a double helix on a stand, two backbones wound round one axis
 * with a ladder of rungs between them. The pointer's height sets the twist:
 * the helix winds on its spring to follow it, and the rung nearest the
 * pointer is bright. At rest the helix holds a turn and a half, one rung lit.
 * The slider is how far the twist can go, in half turns.
 *
 * The pattern: one value on a spring; the hit is the rungs' resting centres
 * on the axis, which never move.
 */
const { Cam, circ, clamp, facing, fit, open, prism, proj, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const R = 22, Z0 = 14, H = 104, N = 12, TW0 = 3 * Math.PI, FAV = 4, STEPS = 96;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-32, -32, 0], [32, 32, 0], [-32, 32, 0], [32, -32, 0], [-R, R, Z0 + H + 2], [R, -R, Z0 + H + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const ring = (r) => circ(r, 32);
  put(solid(g), prism(P, front, ring(32), ring(30.6), 0, 5));
  put(solid(g), prism(P, front, ring(3.2), ring(2.2), 5, Z0));
  const back = mk("path", { class: "nf lo" }, g);
  const rungs = Array.from({ length: N }, (_, k) => ({ k, z: Z0 + ((k + 0.5) / N) * H, el: mk("path", { class: "nf" }, g) }));
  const frontP = mk("path", { class: "nf sil" }, g);
  const tw = spring(TW0, { eps: 0.002 });
  let drawn = NaN;

  const pt = (th, z) => [R * Math.cos(th), R * Math.sin(th), z];
  const isFront = (th) => Math.cos(th) + Math.sin(th) > 0;
  function draw() {
    const t = tw.x;
    if (Math.abs(t - drawn) < 1e-4) return;
    drawn = t;
    let fd = "", bd = "";
    for (const off of [0, Math.PI]) {
      let run = [], side = null;
      const flush = () => { if (run.length > 1) { if (side) fd += open(run); else bd += open(run); } };
      for (let i = 0; i <= STEPS; i++) {
        const z = Z0 + (i / STEPS) * H, th = off + t * (i / STEPS), f = isFront(th);
        const p = P(...pt(th, z));
        if (side !== null && f !== side) { run.push(p); flush(); run = [p]; } else run.push(p);
        side = f;
      }
      flush();
    }
    frontP.setAttribute("d", fd); back.setAttribute("d", bd);
    for (const r of rungs) { const th = t * ((r.z - Z0) / H); r.el.setAttribute("d", seg(P(...pt(th, r.z)), P(...pt(th + Math.PI, r.z)))); }
  }
  const B = register(stage, (dt) => { const m = stepS(tw, dt); draw(); return m; });
  bag.add(B.unregister);

  const mids = rungs.map((r) => P(0, 0, r.z)), top = mids[N - 1][1], bot = mids[0][1];
  let act = -2;
  function setActive(a, sy) {
    tw.t = a < 0 ? TW0 : TW0 + amt * Math.PI * clamp((bot + top - 2 * sy) / (bot - top), -1, 1);
    if (a !== act) {
      act = a;
      rungs.forEach((r) => r.el.classList.toggle("hi", r.k === (a < 0 ? FAV : a)));
      read.textContent = a < 0 ? "rest" : "rung " + (a + 1);
    }
    B.wake();
  }
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[1] - sy); if (d < bd) { bd = d; best = k; } });
    return Math.abs(sx - mids[0][0]) < 46 && bd < 12 ? best : -1;
  }
  setActive(-1, 0);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p), p[1]), leave: () => setActive(-1, 0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; if (act >= 0) B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "dnamodel",
  means: "A DNA double helix on a stand: it twists to follow the pointer's height, the rung nearest the pointer bright.",
  rules: [1, 4, 5, 8],
  range: [0.25, 0.75, 1],
  tour: [[200, 190], [200, 98], [200, 140], null],
  mount,
});

pendulums.code:
/**
 * Pendulums: a frame with eight pendulums of increasing length, each a ball
 * on a string from the top bar. The pointer is a field along the row: the
 * pendulums near it swing out toward the reader, each on its own spring, the
 * one under it furthest and bright. At rest a few hang swung out in a wave,
 * one lit. The slider is the reach, in pendulums.
 *
 * The pattern: a continuous field (terrain) along one row; the hit is each
 * bob's resting screen x, which never moves.
 */
const { Cam, circ, clamp, facing, fit, prism, proj, rad, rings, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const N = 8, STEP = 14, HB = 96, BR = 4.6, MAXA = 42, FAV = 3;
const LEN = Array.from({ length: N }, (_, k) => 34 + k * 7.5);
const RESTA = [6, 12, 20, 26, 18, 9, 4, 0];
const X1 = (N + 1) * STEP;
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value;
  const C = Cam(45, 0.5, 1.75);
  const swung = LEN.map((L, k) => [(k + 1) * STEP, L * Math.sin(rad(MAXA)) + BR, HB - L * Math.cos(rad(MAXA)) - BR]);
  fit(C, [[-6, -10, -4], [X1 + 6, 22, -4], [X1 + 6, -10, -4], [-6, 22, -4], [-4, 0, HB + 3], [X1 + 4, 0, HB + 3], ...swung], 200, 166);
  const P = proj(C), front = facing(C);
  const sc = Math.hypot(...[0, 1].map((i) => P(BR / Math.SQRT2, -BR / Math.SQRT2, 0)[i] - P(0, 0, 0)[i]));
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1, el = solid(g)) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(el, prism(P, front, o, i, z0, z1)); return el; };
  block(-6, -10, X1 + 6, 22, 3, 1.2, -4, 0);
  block(-3, -2, 1, 2, 1.2, 0.5, 0, HB + 3);
  block(-3, -1.6, X1 + 3, 1.6, 1.2, 0.5, HB, HB + 3);
  const right = { key: X1 + 1, g: mk("g", {}, g) };
  block(X1 - 1, -2, X1 + 3, 2, 1.2, 0.5, 0, HB + 3, solid(right.g));

  const bobs = LEN.map((L, k) => {
    const grp = mk("g", {}, g);
    return { k, L, x: (k + 1) * STEP, g: grp, str: mk("path", { class: "nf" }, grp), ball: mk("ellipse", { class: "sil", rx: sc, ry: sc }, grp), sp: spring(RESTA[k], { eps: 0.02 }), drawn: NaN, key: 0 };
  });
  function draw(b) {
    const a = clamp(b.sp.x, 0, MAXA);
    b.key = b.x + b.L * Math.sin(rad(a));
    if (a === b.drawn) return false;
    b.drawn = a;
    const c = P(b.x, (b.L + BR) * Math.sin(rad(a)), HB - (b.L + BR) * Math.cos(rad(a)));
    b.str.setAttribute("d", seg(P(b.x, 0, HB), P(b.x, b.L * Math.sin(rad(a)), HB - b.L * Math.cos(rad(a)))));
    b.ball.setAttribute("cx", c[0].toFixed(2)); b.ball.setAttribute("cy", c[1].toFixed(2));
    return true;
  }
  let painted = "";
  const B = register(stage, (dt) => {
    let m = false;
    for (const b of bobs) { if (stepS(b.sp, dt)) m = true; draw(b); }
    const order = [...bobs, right].sort((a, c) => a.key - c.key), key = order.map((o) => o.k ?? "r").join();
    if (key !== painted) { painted = key; for (const o of order) g.appendChild(o.g); }
    return m;
  });
  bag.add(B.unregister);

  const mids = bobs.map((b) => P(b.x, 0, HB - b.L - BR)), span = mids[1][0] - mids[0][0];
  let over = null;
  function retarget() {
    let hit = -1, bd = Infinity;
    if (over) mids.forEach((m, k) => { const d = Math.abs(m[0] - over[0]); if (d < bd) { bd = d; hit = k; } });
    if (over && (bd > span * 0.7 || over[1] < P(bobs[hit].x, 0, HB)[1] - 4 || over[1] > mids[hit][1] + 26)) hit = -1;
    for (const b of bobs) {
      b.sp.t = hit < 0 ? RESTA[b.k] : b.k === hit ? MAXA : MAXA * 0.8 * falloff(Math.abs(mids[b.k][0] - over[0]) / (RAD * span));
      b.ball.classList.toggle("hi", b.k === (hit < 0 ? FAV : hit));
    }
    read.textContent = hit < 0 ? "rest" : "bob " + (hit + 1);
    B.wake();
  }
  bag.add(pointer(stage, { move: (p) => { over = p; retarget(); }, leave: () => { over = null; retarget(); } }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "pendulums",
  means: "A frame of eight pendulums of rising length: those near the pointer swing out, the one under it furthest.",
  rules: [1, 3, 5, 8],
  range: [1, 2.5, 4],
  tour: [[160, 140], [199, 181], [250, 230], null],
  mount,
});

newtonscradle.code:
/**
 * Newton's cradle: a frame of two top bars on four posts, five steel balls
 * hung in a row, each on a V of two strings. The pointer chooses the end
 * nearer it: that ball lifts out along the row on its strings, on a spring,
 * higher the closer the pointer comes to it, and is bright. At rest the first
 * ball is held a little out, lit. The slider is the full lift, in degrees.
 *
 * The pattern: one value on a spring; the hit is the balls' resting screen x.
 */
const { Cam, clamp, facing, fit, prism, proj, rad, rings, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const N = 5, BR = 6, D = 18, H = 74, LV = 50, XO = 34, REST = 16;
const X4 = (N - 1) * 2 * BR, ZB = H - LV;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let MAXA = value;
  const C = Cam(45, 0.5, 1.95);
  const far = (s, a) => [s * LV * Math.sin(rad(a)) + (s < 0 ? -BR : X4 + BR), 0, H - LV * Math.cos(rad(a)) + BR];
  fit(C, [[-XO - 4, -D - 6, -4], [X4 + XO + 4, D + 6, -4], [X4 + XO + 4, -D - 6, -4], [-XO - 4, D + 6, -4], [-XO, -D, H + 3], [X4 + XO, D, H + 3], far(-1, 55), far(1, 55)], 200, 166);
  const P = proj(C), front = facing(C);
  const sc = Math.hypot(...[0, 1].map((i) => P(BR / Math.SQRT2, -BR / Math.SQRT2, 0)[i] - P(0, 0, 0)[i]));
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, o, i, z0, z1)); };
  const side = (y) => { block(-XO - 1.5, y - 1.5, -XO + 1.5, y + 1.5, 1, 0.4, 0, H + 3); block(-XO - 1.5, y - 1.4, X4 + XO + 1.5, y + 1.4, 1, 0.4, H, H + 3); };
  const post = (y) => block(X4 + XO - 1.5, y - 1.5, X4 + XO + 1.5, y + 1.5, 1, 0.4, 0, H + 3);
  block(-XO - 6, -D - 6, X4 + XO + 6, D + 6, 3, 1.2, -4, 0);
  side(-D); post(-D);
  const balls = Array.from({ length: N }, (_, k) => {
    const x = k * 2 * BR, s = k === 0 ? -1 : k === N - 1 ? 1 : 0;
    const b = { k, x, s, farS: mk("path", { class: "nf" }, g), ball: mk("ellipse", { class: "sil", rx: sc, ry: sc }, g), nearS: mk("path", { class: "nf" }, g), sp: spring(k === 0 ? REST : 0, { eps: 0.02 }), drawn: NaN };
    return b;
  });
  side(D); post(D);

  function draw(b) {
    const a = clamp(b.sp.x, 0, 60);
    if (a === b.drawn) return;
    b.drawn = a;
    const sa = Math.sin(rad(a)) * b.s, ca = Math.cos(rad(a));
    const c = [b.x + LV * sa, 0, H - LV * ca], pc = P(...c);
    b.ball.setAttribute("cx", pc[0].toFixed(2)); b.ball.setAttribute("cy", pc[1].toFixed(2));
    b.farS.setAttribute("d", seg(P(b.x, -D, H), pc));
    const L = Math.hypot(LV, D), att = [c[0] - (sa * LV / L) * BR, (D / L) * BR, c[2] + (ca * LV / L) * BR];
    b.nearS.setAttribute("d", seg(P(b.x, D, H), P(...att)));
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const b of balls) { if (stepS(b.sp, dt)) m = true; draw(b); }
    return m;
  });
  bag.add(B.unregister);

  const e0 = P(0, 0, ZB), e4 = P(X4, 0, ZB), half = (e4[0] - e0[0]) / 2 + 40;
  let act = -2;
  function update(p) {
    let a = -1, near = 0;
    if (p && Math.abs(p[1] - (e0[1] + e4[1]) / 2) < 70 && p[0] > e0[0] - 40 && p[0] < e4[0] + 40) {
      a = p[0] < (e0[0] + e4[0]) / 2 ? 0 : N - 1;
      near = 1 - clamp(Math.abs(p[0] - (a ? e4 : e0)[0]) / half, 0, 1);
    }
    for (const b of balls) {
      b.sp.t = a < 0 ? (b.k === 0 ? REST : 0) : b.k === a ? MAXA * (0.4 + 0.6 * near) : 0;
      if (a !== act) b.ball.classList.toggle("hi", b.k === (a < 0 ? 0 : a));
    }
    if (a !== act) { act = a; read.textContent = a < 0 ? "rest" : "ball " + (a + 1); }
    B.wake();
  }
  let last = null;
  bag.add(pointer(stage, { move: (p) => { last = p; update(p); }, leave: () => { last = null; update(null); } }));
  bag.add(() => svg.replaceChildren());
  update(null);
  return { set: (v) => { MAXA = v; update(last); }, destroy: bag.dispose };
}

hairline({
  name: "newtonscradle",
  means: "A Newton's cradle of five steel balls on V-strings: the end ball nearer the pointer lifts out, higher as it nears.",
  rules: [1, 3, 5, 8],
  range: [20, 40, 55],
  tour: [[167, 167], [233, 200], [215, 185], null],
  mount,
});

apothecary.code:
/**
 * Apothecary cabinet: a chest of sixteen small drawers, four across and four
 * high, each front with a label plate and a round knob. The pointer moves
 * over the cabinet's face: the drawers near it slide open on their own
 * springs, the one under it furthest and bright, the rest less the farther
 * they are. At rest a few drawers stand ajar, one half out and bright. The
 * slider is the reach of the field.
 *
 * The pattern: a field over a grid on a face plane; the hit is read on the
 * cabinet's face (y = D), which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, poly, prism, proj, rings, rrect, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NC = 4, NR = 4, CW = 22, CH = 14, M = 5, BASE = 7, D = 26, IN = 1, OUT = 20;
const W = 2 * M + NC * CW, H = BASE + NR * CH + M, FAV = [2, 2];
const REST = [[0.6, 1.4, 0.6, 3], [2.2, 0.6, 0.6, 0.6], [0.6, 0.6, 10, 1.6], [1.2, 3.4, 0.6, 0.6]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D + OUT, 0], [0, 0, H + 3], [W, 0, H + 3], [0, D + OUT, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const onFace = (y) => (q) => P(q.u, y, q.v);
  const g = mk("g", {}, svg);

  // the carcass: a cabinet on a plinth, a cornice line on top, the drawer field framed on its face
  const [cr, ci] = rings(0, 0, W, D, 3, 1.4);
  put(solid(g), prism(P, front, cr, ci, 0, H));
  const [tr, ti] = rings(-1.5, -1.5, W + 1.5, D + 1.5, 3.5, 1.2);
  put(solid(g), prism(P, front, tr, ti, H, H + 3));
  mk("path", { d: seg(P(1.5, D, BASE - 3), P(W - 1.5, D, BASE - 3)), class: "nf lo" }, g);

  const dr = [];
  for (let c = 0; c < NC; c++) for (let r = 0; r < NR; r++) {
    const x0 = M + c * CW + IN, x1 = M + (c + 1) * CW - IN, z0 = BASE + r * CH + IN, z1 = BASE + (r + 1) * CH - IN;
    mk("path", { d: poly(rrect(x0 - 0.4, z0 - 0.4, x1 + 0.4, z1 + 0.4, 0.8, 2).map(onFace(D))), class: "nf lo" }, g);
    dr.push({ c, r, x0, x1, z0, z1, cx: (x0 + x1) / 2, cz: (z0 + z1) / 2, rest: REST[c][NR - 1 - r] });
  }
  // left to right, bottom to top: a drawer is only hidden by one to its right or above it
  for (const d of dr) {
    d.el = solid(g);
    d.plate = mk("path", { class: "nf lo" }, d.el.g);
    d.knob = mk("path", { class: "nf" }, d.el.g);
    d.sp = spring(d.rest, { eps: 0.02 });
    d.last = NaN;
  }

  const knob = circ(1.5, 12);
  function draw(d) {
    const s = clamp(d.sp.x, 0.3, OUT);
    if (s === d.last) return;
    d.last = s;
    const y = D + s;
    const [r, i] = rings(d.x0, D, d.x1, y, 1.2, Math.min(0.8, s * 0.35));
    put(d.el, prism(P, front, r, i, d.z0, d.z1));
    d.plate.setAttribute("d", poly(rrect(d.cx - 4.5, d.z1 - 4.2, d.cx + 4.5, d.z1 - 1.6, 0.6, 2).map(onFace(y))));
    d.knob.setAttribute("d", poly(knob.map((q) => P(d.cx + q.u, y + 0.2, d.cz - 1.6 + q.v))));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const d of dr) { if (stepS(d.sp, dt)) m = true; draw(d); }
    return m;
  });
  bag.add(B.unregister);

  /** The pointer on the face plane (y = D), which never moves: [x, z] or null. */
  function onFacePt([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + D * s) / c, Y = x * s + D * c, z = (Y * C.k - (sy - C.oy) / C.S) / zf;
    return x < M - 2 || x > W - M + 2 || z < BASE - 2 || z > BASE + NR * CH + 2 ? null : [x, z];
  }

  let over = null;
  function retarget() {
    let hit = null;
    if (over) {
      const c = clamp(Math.floor((over[0] - M) / CW), 0, NC - 1), r = clamp(Math.floor((over[1] - BASE) / CH), 0, NR - 1);
      hit = dr[c * NR + r];
    }
    for (const d of dr) {
      if (!hit) d.sp.t = d.rest;
      else {
        const dist = Math.hypot(d.cx - over[0], d.cz - over[1]);
        d.sp.t = d === hit ? OUT : clamp(OUT * 0.6 * Math.max(0.08, Math.exp(-((dist / reach) ** 2))), 0.6, OUT * 0.6);
      }
      d.el.sil.classList.toggle("hi", hit ? d === hit : d.c === FAV[0] && NR - 1 - d.r === FAV[1]);
    }
    read.textContent = hit ? `drawer ${hit.c + 1}·${NR - hit.r}` : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { over = onFacePt(p); retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "apothecary",
  means: "An apothecary cabinet of sixteen drawers: the drawers near the pointer slide open, the one under it furthest.",
  rules: [1, 3, 5, 6],
  range: [12, 24, 40],
  tour: [[195, 148], [145, 185], [262, 180], null],
  mount,
});

bpmonitor.code:
/**
 * Blood pressure monitor: a cuff lying flat, its hose running to a round dial
 * gauge with a needle and to a squeeze bulb with its valve. As the pointer
 * nears the bulb the pressure rises: the cuff swells on a spring and the
 * gauge's needle swings round. At rest the cuff is slack and the needle,
 * bright, sits a little off its stop. The slider is the bulb's reach.
 *
 * The pattern: one continuous value from the pointer's distance to a fixed
 * point (the bulb at rest), read through a spring.
 */
const {
  Cam, circ, clamp, facing, fit, hull, lerp, open, poly, prism, proj, rad, rings, ringAt, rrect, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const CX1 = 46, CY1 = 30, H0 = 4, HMAX = 13, GX = 74, GY = 8, GR = 13, GZ = 5, BX = 66, BY = 50;
const BULB = [[0, 3.5], [1.5, 6.5], [5, 8.5], [10, 8.4], [14, 6], [17, 3]];
const A0 = rad(-215), A1 = rad(35), REST = 0.12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.6);
  fit(C, [[0, 0, 0], [0, CY1, 0], [CX1, 0, 0], [CX1, CY1, HMAX], [GX + GR, GY, 0], [GX, GY - GR, GZ], [BX + 9, BY + 9, 0], [BX, BY, 22]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the hose, lying on the ground: from the cuff's port to the gauge, and on to the bulb's valve
  const curve = (pts) => { const out = []; for (let i = 0; i <= 24; i++) { const t = i / 24, u = 1 - t; out.push(P(...[0, 1, 2].map((k) => u * u * u * pts[0][k] + 3 * u * u * t * pts[1][k] + 3 * u * t * t * pts[2][k] + t * t * t * pts[3][k]))); } return out; };
  mk("path", { class: "nf", d: open(curve([[CX1 - 4, 12, 2], [58, 12, 1], [56, 26, 1], [GX - 9, GY + 10, 2]])) + open(curve([[CX1 - 4, 18, 2], [52, 40, 1], [BX - 14, BY - 4, 1], [BX - 3, BY - 2, 20]])) }, g);

  // the cuff: a fabric sleeve laid flat, its seam and hook-and-loop patch on top
  const cuff = solid(g), seam = mk("path", { class: "nf lo" }, cuff.g);
  const [cr, ci] = rings(0, 0, CX1, CY1, 8, 1.6);
  const seamR = rrect(4, 4, CX1 - 4, CY1 - 4, 5, 4), patch = rrect(8, 8, 22, CY1 - 8, 2, 3);

  // the gauge: a squat round case, its face ring, ticks round the dial and the needle
  const gr = circ(GR, 32), gi = circ(GR - 1.4, 32);
  const gauge = solid(g);
  put(gauge, prism(P, front, gr.map((q) => ({ ...q, u: q.u + GX, v: q.v + GY })), gi.map((q) => ({ ...q, u: q.u + GX, v: q.v + GY })), 0, GZ));
  let ticks = poly(ringAt(P, circ(10, 32).map((q) => ({ ...q, u: q.u + GX, v: q.v + GY })), GZ));
  for (let i = 0; i <= 10; i++) {
    const a = lerp(A0, A1, i / 10), r0 = i % 5 === 0 ? 7 : 8.2;
    ticks += seg(P(GX + r0 * Math.cos(a), GY + r0 * Math.sin(a), GZ), P(GX + 9.4 * Math.cos(a), GY + 9.4 * Math.sin(a), GZ));
  }
  mk("path", { class: "nf lo", d: ticks }, gauge.g);
  const needle = mk("path", { class: "nf" }, gauge.g);
  const hub = mk("path", { class: "", d: poly(ringAt(P, circ(1.2, 12).map((q) => ({ ...q, u: q.u + GX, v: q.v + GY })), GZ)) }, gauge.g);

  // the bulb: a lathe of rings, then its valve on top
  const bulb = solid(g);
  const lathe = [];
  for (const [z, r] of BULB) lathe.push(...ringAt(P, circ(r, 24).map((q) => ({ ...q, u: q.u + BX, v: q.v + BY })), z));
  bulb.sil.setAttribute("d", poly(hull(lathe)));
  bulb.cr.setAttribute("d", open(ringAt(P, circ(7.6, 24).map((q) => ({ ...q, u: q.u + BX, v: q.v + BY })), 12).filter((_, i) => i <= 12)));
  const [vr, vi] = rings(BX - 2, BY - 2, BX + 2, BY + 2, 2, 0.5);
  put(solid(g), prism(P, front, vr, vi, 16.5, 21));

  const pr = spring(REST, { eps: 0.002 });
  let last = NaN;
  function draw(p) {
    if (p === last) return;
    last = p;
    const h = lerp(H0, HMAX, clamp(p, 0, 1));
    put(cuff, prism(P, front, cr, ci, 0, h));
    seam.setAttribute("d", poly(ringAt(P, seamR, h)) + poly(ringAt(P, patch, h)));
    const a = lerp(A0, A1, clamp(p, 0, 1.04));
    needle.setAttribute("d", seg(P(GX - 2 * Math.cos(a), GY - 2 * Math.sin(a), GZ + 0.3), P(GX + 8.6 * Math.cos(a), GY + 8.6 * Math.sin(a), GZ + 0.3)));
  }
  cuff.g.after(g.firstChild);
  hub.before(needle);

  const B = register(stage, (dt) => { const m = stepS(pr, dt); draw(pr.x); return m; });
  bag.add(B.unregister);

  const bulbAt = P(BX, BY, 9);
  function set(p) {
    pr.t = p < 0 ? REST : p;
    needle.classList.toggle("hi", p < 0);
    bulb.sil.classList.toggle("hi", p >= 0);
    read.textContent = p < 0 ? "rest" : String(Math.round(40 + 160 * p));
    B.wake();
  }
  bag.add(pointer(stage, {
    move: ([sx, sy]) => set(clamp(1 - Math.hypot(sx - bulbAt[0], sy - bulbAt[1]) / reach, 0, 1)),
    leave: () => set(-1),
  }));
  bag.add(() => svg.replaceChildren());
  set(-1);
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "bpmonitor",
  means: "A blood pressure monitor: as the pointer nears the bulb the cuff swells and the gauge's needle swings round.",
  rules: [1, 3, 5, 8],
  range: [160, 240, 340],
  tour: [[290, 175], [230, 190], [178, 197], null],
  mount,
});

bbqgrill.code:
/**
 * BBQ grill: a kettle barbecue on three legs, its lid hinged open at the
 * back, a grate across the bowl and four skewers lying on it, each with four
 * chunks on its rod and a loop at its end. As the pointer nears, the lid
 * swings wider open (a spring); the skewer under the pointer rises and turns
 * over, the ones beside it a little, staggered from it. At rest one skewer is
 * turned half over, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row, picked on a fixed plane through
 * the grate; the lid follows the pointer's distance on the same plane.
 */
const {
  Cam, circ, clamp, fit, hull, lerp, open, poly, proj, seg, spring, stepS, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, register,
} = HL;

const R = 28, TOPZ = 44, H = 15, N = 4, YS = [-15, -5, 5, 15], FAV = 1, RISE = 9, TH0 = 0.95, TH1 = 1.45;
const REST = [[0, 0.2], [3, 1.1], [0, 0.6], [0, 0.1]];
const SQ = Math.SQRT1_2, HG = [-R * SQ, -R * SQ, TOPZ];
const ring3 = (r, z, n = 40) => circ(r, n).map((q) => [q.u, q.v, z]);

/** a point of the closed lid, swung open by th about the hinge at the back of the rim */
function hinge(p, th) {
  const q = [p[0] - HG[0], p[1] - HG[1], p[2] - HG[2]];
  const u = -(q[0] + q[1]) * SQ, w = (q[0] - q[1]) * SQ, c = Math.cos(th), s = Math.sin(th);
  const u2 = u * c + q[2] * s, z2 = -u * s + q[2] * c;
  return [HG[0] - u2 * SQ + w * SQ, HG[1] - u2 * SQ - w * SQ, HG[2] + z2];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.5);
  const dome = [], rim = ring3(R, TOPZ), handle = [];
  for (let i = 0; i <= 6; i++) { const t = (i / 6) * (Math.PI / 2); dome.push(...ring3(R * Math.cos(t) + 0.01, TOPZ + H * Math.sin(t), 32)); }
  for (const x of [-6, 6]) for (const y of [-1.5, 1.5]) for (const z of [0, 3.5]) handle.push([x, y, TOPZ + H + z]);
  const far = dome.concat(handle).map((p) => hinge(p, TH1));
  fit(C, far.concat([[29, 0, 0], [0, 29, 0], [-29, 0, 0], [0, -29, 0], [R + 9, 15, TOPZ + RISE + 6]]), 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);

  // the lid, swung open behind the bowl: its handle, its dome, its rim
  const lidH = mk("path", { class: "nf" }, g), lidS = mk("path", { class: "sil" }, g), lidR = mk("path", { class: "nf lo" }, g);
  // the legs, the ash pan between them, then the bowl over their tops
  const legs = [45, 165, 285].map((a) => [Math.cos((a * Math.PI) / 180), Math.sin((a * Math.PI) / 180)]);
  const leg = (c) => seg(P(16 * c[0], 16 * c[1], TOPZ - 16), P(27 * c[0], 27 * c[1], 0));
  mk("path", { class: "nf", d: leg(legs[1]) + leg(legs[2]) }, g);
  mk("path", { d: poly(hull(ring3(9, 13).concat(ring3(10, 17)).map((p) => P(...p)))) }, g);
  mk("path", { class: "nf", d: leg(legs[0]) }, g);
  const bowl = [];
  for (const [r, z] of [[R, TOPZ], [R * 0.94, TOPZ - 6], [R * 0.8, TOPZ - 12], [R * 0.55, TOPZ - 17], [R * 0.25, TOPZ - 19]]) bowl.push(...ring3(r, z).map((p) => P(...p)));
  mk("path", { class: "sil", d: poly(hull(bowl)) }, g);
  let grate = poly(ring3(R - 1.5, TOPZ).map((p) => P(...p)));
  for (let x = -20; x <= 20; x += 5) { const h = Math.sqrt((R - 3) ** 2 - x * x); grate += seg(P(x, -h, TOPZ), P(x, h, TOPZ)); }
  mk("path", { class: "nf lo", d: grate }, g);

  const sk = YS.map((y, k) => {
    const grp = mk("g", {}, g), rod = mk("path", { class: "nf" }, grp);
    const chunks = [-15, -5, 5, 15].map(() => mk("path", { class: "sil" }, grp));
    const loop = mk("path", { class: "nf" }, grp);
    return { k, y, rod, chunks, loop, z: tween(REST[k][0]), a: tween(REST[k][1]), last: "" };
  });

  function drawSk(s, z, a) {
    const key = z.toFixed(2) + "," + a.toFixed(3);
    if (key === s.last) return;
    s.last = key;
    const z0 = TOPZ + 2.8 + z, c = Math.cos(a), sn = Math.sin(a);
    const at = (x, yy, zz) => P(x, s.y + yy * c - zz * sn, z0 + yy * sn + zz * c);
    s.rod.setAttribute("d", seg(at(-22, 0, 0), at(R + 4, 0, 0)));
    [-15, -5, 5, 15].forEach((x, i) => {
      const pts = [];
      for (const dx of [-3, 3]) for (const yy of [-2.6, 2.6]) for (const zz of [-2.6, 2.6]) pts.push(at(x + dx, yy, zz));
      s.chunks[i].setAttribute("d", poly(hull(pts)));
    });
    const lp = [];
    for (let i = 0; i <= 16; i++) { const t = (i / 16) * Math.PI * 2; lp.push(at(R + 6.5 + 2.5 * Math.cos(t), 0, 2.5 * Math.sin(t))); }
    s.loop.setAttribute("d", open(lp));
  }

  const th = spring(TH0);
  let thLast = NaN;
  function drawLid(t) {
    if (t === thLast) return;
    thLast = t;
    const f = (p) => P(...hinge(p, t));
    lidH.setAttribute("d", poly(hull(handle.map(f))));
    lidS.setAttribute("d", poly(hull(dome.map(f))));
    lidR.setAttribute("d", poly(rim.map(f)));
  }

  const B = register(stage, (dt, now) => {
    const m = stepS(th, dt);
    drawLid(th.x);
    let moving = m;
    for (const s of sk) { drawSk(s, tval(s.z, now), tval(s.a, now)); if (!tdone(s.z, now) || !tdone(s.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  // the hit: the pointer on a fixed plane through the grate; nearest skewer by y, lid by distance
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TOPZ + 3), d = Math.hypot(x, y);
    th.t = lerp(TH0, TH1, clamp(1 - (d - R * 0.3) / (R * 1.6), 0, 1));
    return d > R + 6 ? -1 : clamp(Math.round((y - YS[0]) / 10), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    B.wake();
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    sk.forEach((s, k) => {
      const dd = Math.abs(k - a), delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(s.z, a < 0 ? REST[k][0] : dd === 0 ? RISE : dd === 1 ? 2.5 : 0, now, delay);
      tset(s.a, a < 0 ? REST[k][1] : dd === 0 ? 1.8 : dd === 1 ? 0.7 : REST[k][1], now, delay);
      const on = k === (a < 0 ? FAV : a);
      for (const el of [s.rod, s.loop, ...s.chunks]) el.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "skewer " + (a + 1);
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => { th.t = TH0; setActive(-1); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "bbqgrill",
  means: "A kettle grill with four skewers: the lid swings open as the pointer nears, and the skewer under it rises and turns.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[227, 161], [192, 179], [174, 187], null],
  mount,
});

popcorn.code:
/**
 * Popcorn: a cinema popcorn machine, a glass cabinet on a cart base with a
 * kettle hanging from its top, a heap of popped kernels on its floor and a
 * scoop on the ledge in front. The kernels near the pointer pop up, each on
 * its own spring, falling off with distance, and the kettle tips toward the
 * pointer. At rest a few kernels are mid-pop, one bright, and the kettle
 * leans toward it. The slider is how high they pop.
 *
 * The pattern: a field answering a point (terrain); each kernel is tested on
 * the plane of its own resting height.
 */
const {
  Cam, circ, clamp, facing, fit, hull, poly, proj, prism, put, rings, ringAt, rrect, run, seg, spring, stepS, unproj,
  disposer, mk, pointer, register, solid,
} = HL;

const W = 44, D = 36, BZ = 16, TZ = 64, KR = 2.4, FAV = 13, PZ = TZ - 12;
const ring3 = (r, z, n = 28) => circ(r, n).map((q) => [q.u, q.v, z]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let pop = value;
  const S = 2.55, C = Cam(45, 0.5, S);
  fit(C, [[-4, -4, 0], [W + 4, D + 12, 0], [W + 4, -4, 0], [-4, D + 12, 0], [0, 0, TZ + 2], [W, 0, TZ + 2], [0, D, TZ + 2]], 200, 166);
  const P = proj(C), front = facing(C), g = mk("g", {}, svg);
  const [br, bi] = rings(-4, -4, W + 4, D + 12, 4, 1.4);
  put(solid(g), prism(P, front, br, bi, 0, BZ));

  // the glass: its back edges before what is inside, its front edges after
  const gl = rrect(0, 0, W, D, 2, 4), back = (s) => !front(s);
  const post = (x, y, cls, par) => mk("path", { class: cls, d: seg(P(x, y, BZ), P(x, y, TZ)) }, par);
  post(0.6, 0.6, "nf lo", g);
  mk("path", { class: "nf lo", d: poly(ringAt(P, run(gl, back), BZ)).replace(/Z$/, "") }, g);
  mk("path", { class: "nf sil", d: poly(ringAt(P, run(gl, back), TZ)).replace(/Z$/, "") }, g);

  // the kernels: a heap, higher toward the back-left, a few mid-pop at rest
  const ks = [], kgB = mk("g", {}, g);
  for (let j = 0; j < 5; j++) for (let i = 0; i < 6; i++) {
    const x = 6 + i * 6.4 + (j % 2) * 2, y = 5 + j * 6.4 + (i % 3) * 0.8;
    const z = BZ + 2.4 + 9 * Math.exp(-((x - W * 0.45) ** 2 + (y - D * 0.42) ** 2) / (2 * 12 * 12));
    ks.push({ x, y, z, rest: [3, 7, 22, 16].includes(ks.length) ? 2.5 : ks.length === FAV ? 5 : 0, s: null, last: NaN, el: null });
  }
  ks.forEach((k) => { k.s = spring(k.rest); });

  // the kettle, hung from the top on its rod, tipping about an axle at its middle
  const KC = [W / 2, D / 2];
  mk("path", { class: "nf", d: seg(P(KC[0], KC[1], TZ), P(KC[0], KC[1], PZ)) }, g);
  const body = [[8, 5], [8.4, 1], [7, -4], [4.5, -6.5]].flatMap(([r, z]) => ring3(r, z)), mouth = ring3(7.2, 5);
  const kS = mk("path", { class: "sil" }, g), kR = mk("path", { class: "nf lo" }, g);
  const tx = spring(0.2), ty = spring(0.12);
  let kLast = "";
  function drawKettle(ax, ay) {
    const key = ax.toFixed(4) + "," + ay.toFixed(4);
    if (key === kLast) return;
    kLast = key;
    const th = Math.hypot(ax, ay), dx = th ? ax / th : 1, dy = th ? ay / th : 0, c = Math.cos(th), s = Math.sin(th);
    const f = ([x, y, z]) => {
      const u = x * dx + y * dy, w = -x * dy + y * dx, u2 = u * c + z * s, z2 = -u * s + z * c;
      return P(KC[0] + u2 * dx - w * dy, KC[1] + u2 * dy + w * dx, PZ + z2);
    };
    kS.setAttribute("d", poly(hull(body.map(f))));
    kR.setAttribute("d", poly(mouth.map(f)));
  }

  const kgF = mk("g", {}, g);
  ks.slice().sort((a, b) => a.x + a.y - (b.x + b.y)).forEach((k) => { k.el = mk("ellipse", { rx: KR * S, ry: KR * S }, k.x + k.y < KC[0] + KC[1] ? kgB : kgF); });

  // the front of the glass, then the scoop on the ledge
  const fr = mk("g", {}, g);
  post(W - 0.6, D - 0.6, "nf lo", fr);
  mk("path", { class: "nf", d: poly(ringAt(P, run(gl, front), BZ)).replace(/Z$/, "") + poly(ringAt(P, run(gl, front), TZ)).replace(/Z$/, "") }, fr);
  post(0.6, D - 0.6, "nf sil", fr); post(W - 0.6, 0.6, "nf sil", fr);
  const [sr, si] = rings(10, D + 3, 19, D + 9, 2, 0.7);
  mk("path", { class: "nf", d: seg(P(19, D + 6, BZ + 2.5), P(28, D + 6, BZ + 1)) }, fr);
  put(solid(fr), prism(P, front, sr, si, BZ, BZ + 3));

  function drawK(k, z) {
    if (z === k.last) return;
    k.last = z;
    const [sx, sy] = P(k.x, k.y, k.z + KR + z);
    k.el.setAttribute("cx", sx.toFixed(2)); k.el.setAttribute("cy", sy.toFixed(2));
  }

  const B = register(stage, (dt) => {
    let moving = false;
    for (const k of ks) { if (stepS(k.s, dt)) moving = true; drawK(k, k.s.x); }
    if (stepS(tx, dt)) moving = true;
    if (stepS(ty, dt)) moving = true;
    drawKettle(tx.x, ty.x);
    return moving;
  });
  bag.add(B.unregister);

  // the hit: each kernel on the plane of its own resting height; the nearest names the pop
  let act = -2;
  function move([sx, sy]) {
    let best = -1, bd = Infinity;
    ks.forEach((k, i) => {
      const [x, y] = unproj(C, sx, sy, k.z + KR), d = Math.hypot(x - k.x, y - k.y);
      k.s.t = pop * Math.max(0, 1 - d / 18) ** 1.4;
      if (d < bd) { bd = d; best = i; }
    });
    const [x, y] = unproj(C, sx, sy, BZ + 6), vx = x - KC[0], vy = y - KC[1], m = Math.hypot(vx, vy) || 1;
    const amt = 0.5 * clamp(m / 24, 0, 1);
    tx.t = (vx / m) * amt; ty.t = (vy / m) * amt;
    setActive(bd < 4.5 ? best : -1);
    B.wake();
  }
  function leave() {
    ks.forEach((k) => { k.s.t = k.rest; });
    tx.t = 0.2; ty.t = 0.12;
    setActive(-1);
    B.wake();
  }
  function setActive(a) {
    if (a === act) return;
    act = a;
    ks.forEach((k, i) => k.el.classList.toggle("hi", i === (a < 0 ? FAV : a)));
    read.textContent = a < 0 ? "rest" : "pop " + (a + 1);
  }
  setActive(-1);
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { pop = v; }, destroy: bag.dispose };
}

hairline({
  name: "popcorn",
  means: "A popcorn machine: kernels near the pointer pop up on springs, and the kettle at the top tips toward it.",
  rules: [1, 3, 5, 8],
  range: [8, 16, 24],
  tour: [[160, 179], [198, 192], [250, 184], null],
  mount,
});

coathooks.code:
/**
 * Coat hooks: a hallway rail with five hooks, four coats of different
 * lengths and a bag hanging from them. The pointer picks a coat by where it
 * hangs: it swings out on its hook toward the reader, and its neighbours swing
 * a little, staggered from it. At rest the coats hang a little askew and one
 * is swung out, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (bookshelf); the pick is the coat
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, fillet, fit, hull, open, poly, prism, proj, rings, seg, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const XS = [-52, -26, 0, 26, 52], LEN = [46, 40, 50, 0, 43], REST = [3, 11, 2, 5, 1], FAV = 1, BAG = 3;
const PY = 4, PZ = 72;
const COAT = (L) => [[-3, 0], [3, 0], [10, -5], [12, -L], [-12, -L], [-10, -5]];
const BAGP = [[-9, -14], [9, -14], [10, -31], [-10, -31]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-66, -4, 82], [66, -4, 82], [-66, 34, 22], [66, 34, 22], [66, 0, 20], [-66, 0, 20]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const [rr, ri] = rings(-66, -4, 66, 0, 1.4, 0.6);
  put(solid(g), prism(P, () => true, rr, ri, 68, 80));
  mk("path", { class: "nf lo", d: XS.map((x) => seg(P(x - 2, 0, 76), P(x + 2, 0, 76))).join("") }, g);

  // a point of a hanging item, local (u along x, w out from the wall, h down from the hook), swung by a
  const W = (x, a) => (u, w, h) => P(x + u, PY + w * Math.cos(a) - h * Math.sin(a), PZ + w * Math.sin(a) + h * Math.cos(a));
  const items = XS.map((x, k) => {
    const grp = mk("g", {}, g), el = solid(grp), marks = mk("path", { class: "nf lo" }, grp), hook = mk("path", { class: "nf sil" }, grp);
    hook.setAttribute("d", open([P(x, 0, 75), P(x, 7, 73), P(x, 9.5, 76.5)]));
    return { k, x, grp, el, marks, a: tween(REST[k]), last: NaN };
  });

  function draw(it, deg) {
    if (Math.abs(deg - it.last) < 0.01) return;
    it.last = deg;
    const f = W(it.x, rad(deg)), pts = [];
    if (it.k === BAG) {
      for (const w of [-1, 7]) for (const [u, h] of BAGP) pts.push(f(u, w, h));
      it.el.sil.setAttribute("d", poly(fillet(hull(pts), hull(pts).map(() => 3), 3)));
      it.marks.setAttribute("d", open([f(-7, 3, -14), f(0, 3, 0), f(7, 3, -14)]) + seg(f(-9.4, 7, -20), f(9.4, 7, -20)));
    } else {
      const L = LEN[it.k];
      for (const w of [-2, 5]) for (const [u, h] of COAT(L)) pts.push(f(u, w, h));
      it.el.sil.setAttribute("d", poly(fillet(hull(pts), hull(pts).map(() => 3.5), 3)));
      it.marks.setAttribute("d", open([f(-3, 5, 0), f(0, 5, -8), f(3, 5, 0)]) + seg(f(0, 5, -8), f(0, 5, -L + 1.5)));
    }
  }

  // far to near: a coat swung toward the reader goes after its neighbours
  let painted = "";
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    const key0 = (it) => it.x + Math.sin(rad(tval(it.a, now))) * (LEN[it.k] || 30) * 0.9;
    const order = items.slice().sort((p, q) => key0(p) - key0(q)), key = order.map((it) => it.k).join();
    if (key !== painted) { painted = key; for (const it of order) g.appendChild(it.grp); }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, PY, PZ - (LEN[it.k] || 30) / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 22 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), deg = a < 0 ? REST[k] : d === 0 ? 34 : d === 1 ? 9 : d === 2 ? 4 : 1;
      tset(it.a, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.el.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : (a === BAG ? "bag " : "coat ") + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "coathooks",
  means: "Coats and a bag on a hallway rail: the coat under the pointer swings out toward you, its neighbours a little.",
  rules: [1, 2, 5, 8],
  range: [0, 40, 80],
  tour: [[133, 119], [218, 161], [302, 203], null],
  mount,
});

rockingchair.code:
/**
 * Rocking chair: a slatted rocking chair with a cushion on a porch deck, a
 * small round side table with a cup beside it. The pointer is the side the
 * chair should lean to: it rocks on its runners toward the pointer's side on
 * a spring, further the further out the pointer is, and its cushion is
 * bright. At rest the chair sits a little tipped back and the cup is the
 * bright mark. The slider is how quickly it follows.
 *
 * The pattern: a continuous angle (terrain's spring, on one number); the hit
 * is on the deck's plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fillet, fit, hull, open, poly, prism, proj, rad, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 70, MAX = 14, REST = -3, TX = 0, TY = -44;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-62, -62, -4], [56, 30, -4], [56, -62, -4], [-62, 30, -4], [-34, 0, 66], [30, 0, 66]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [dr, di] = rings(-62, -62, 56, 30, 3, 1.5);
  put(solid(g), prism(P, front, dr, di, -4, 0));
  mk("path", { class: "nf lo", d: [-44, -26, -8, 10].map((y) => seg(P(-60, y, 0), P(54, y, 0))).join("") }, g);
  // the side table and its cup, behind the chair
  const at = (r) => r.map((q) => ({ ...q, u: q.u + TX, v: q.v + TY }));
  put(solid(g), prism(P, front, at(circ(6, 32)), at(circ(5, 32)), 0, 1.5));
  put(solid(g), prism(P, front, at(circ(1.6, 16)), null, 1.5, 28));
  put(solid(g), prism(P, front, at(circ(12, 48)), at(circ(10.8, 48)), 28, 30));
  const cup = solid(g);
  put(cup, prism(P, front, at(circ(3, 24)).map((q) => ({ ...q, u: q.u + 3, v: q.v + 2 })), at(circ(2.3, 24)).map((q) => ({ ...q, u: q.u + 3, v: q.v + 2 })), 30, 35));

  const farL = mk("path", { class: "nf sil" }, g), back = solid(g), seat = solid(g), cush = solid(g), nearL = mk("path", { class: "nf sil" }, g);
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });

  function draw(deg) {
    const a = rad(deg), c = Math.cos(a), s = Math.sin(a);
    const T = (x, y, z) => { const dz = z - R; return P(R * a + x * c + dz * s, y, R - x * s + dz * c); };
    const lines = (y) => {
      const arc = (r) => open(Array.from({ length: 17 }, (_, i) => { const t = -0.5 + i / 16; return T(r * Math.sin(t), y, R - r * Math.cos(t)); }));
      const foot = (x) => R - Math.sqrt(R * R - x * x) + 2.5;
      return arc(R) + arc(R - 2.5) + seg(T(10, y, foot(10)), T(10, y, 38)) + seg(T(-12, y, foot(-12)), T(-12, y, 24))
        + seg(T(-13, y, 24), T(-21, y, 64)) + seg(T(-15, y, 39), T(13, y, 38));
    };
    farL.setAttribute("d", lines(-12));
    nearL.setAttribute("d", lines(12));
    const box = (el, x0, x1, y0, y1, z0, z1, r, lean = 0) => {
      const pts = [];
      for (const z of [z0, z1]) for (const [x, y] of [[x0, y0], [x1, y0], [x1, y1], [x0, y1]]) pts.push(T(x - lean * (z - z0), y, z));
      const h = hull(pts);
      el.sil.setAttribute("d", poly(fillet(h, h.map(() => r), 3)));
      return T;
    };
    box(back, -16, -13, -11, 11, 28, 62, 2, 0.2);
    back.cr.setAttribute("d", [40, 51].map((z) => seg(T(-13 - 0.2 * (z - 28), -10, z), T(-13 - 0.2 * (z - 28), 10, z))).join(""));
    box(seat, -14, 12, -13, 13, 21, 24, 2);
    box(cush, -12, 10, -11, 11, 24, 28, 4);
    cush.cr.setAttribute("d", open([T(10, -9, 28), T(10, 9, 28), T(-10, 9, 28)]));
  }

  let drawn = NaN;
  const B = register(stage, (dt) => {
    const m = stepS(sp, dt);
    if (!(Math.abs(sp.x - drawn) <= 0.01)) { drawn = sp.x; draw(sp.x); }
    return m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    sp.t = over == null ? REST : clamp(over / 40, -1, 1) * MAX;
    cush.sil.classList.toggle("hi", over != null);
    cup.sil.classList.toggle("hi", over == null);
    read.textContent = over == null ? "rest" : "rock " + Math.round(Math.abs(sp.t)) + "°";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      over = Math.hypot(x, y + 10) < 90 ? x : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "rockingchair",
  means: "A rocking chair on a porch beside a side table: it rocks toward the side the pointer is on.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[110, 165], [183, 200], [245, 230], null],
  mount,
});

ceilingfan.code:
/**
 * Ceiling fan: a canopy on the ceiling, a down-rod, a motor housing with five
 * long blades and a light bowl under it, seen from below and to the side.
 * The pointer is a hand on the switch: the nearer it comes to the fan, the
 * faster the blades turn, the rate easing on a spring, and the blade nearest
 * the pointer is bright. Away, the fan winds down and stops; at rest one
 * blade is bright. The slider is the top speed.
 *
 * The pattern: a continuous rate (terrain's spring, on one number); the hit is
 * on the blades' plane, which never moves. It turns only while the rate is up.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rad, ringAt, rrect, run, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, BZ = 41, RB = 62, REST = 17, FAV = 0;
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let top = value;
  const C = Cam(45, -0.4, 2.25);
  fit(C, [[RB, RB, BZ], [-RB, -RB, BZ], [RB, -RB, BZ], [-RB, RB, BZ], [0, 0, 80], [0, 0, 27]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // seen from below, the crease runs round each part's underside: prism gets z1 below z0
  put(solid(g), prism(P, front, circ(8, 32), circ(7, 32), 80, 75));
  put(solid(g), prism(P, front, circ(1.6, 16), null, 74, 47));
  const motor = solid(g);
  put(motor, prism(P, front, circ(11, 40), circ(10, 40), 47, 37));
  mk("path", { class: "nf lo", d: open(ringAt(P, run(circ(11, 40), front), 43)) }, motor.g);
  const bowl = solid(g), bfoot = circ(9, 40), btop = circ(4, 24), binner = circ(3.2, 24);
  put(bowl, { sil: poly(hull(ringAt(P, bfoot, 37).concat(ringAt(P, btop, 28)))), crease: open(ringAt(P, run(binner, front), 28)) });
  const blade = rrect(13, -7.5, RB, 7.5, 6, 6), bin = rrect(14, -6.5, RB - 1, 6.5, 5, 6);
  const blades = Array.from({ length: N }, (_, i) => ({ i, el: solid(g) }));

  let spin = rad(REST), drawn = NaN, order = "", hiB = -2;
  const rate = spring(0);
  function draw() {
    if (Math.abs(spin - drawn) < 1e-4) return;
    drawn = spin;
    const keys = [];
    for (const b of blades) {
      const a = spin + (b.i * 2 * Math.PI) / N;
      put(b.el, prism(P, front, turn(blade, a), turn(bin, a), BZ + 1.2, BZ));
      keys.push([b, Math.cos(a) + Math.sin(a)]);
    }
    keys.sort((p, q) => p[1] - q[1]);
    const key = keys.map((k) => k[0].i).join();
    if (key !== order) {
      order = key;
      for (const [b, d] of keys) if (d < 0) g.appendChild(b.el.g);
      g.appendChild(motor.g);
      for (const [b, d] of keys) if (d >= 0) g.appendChild(b.el.g);
      g.appendChild(bowl.g);
    }
  }

  let over = null;
  function bright() {
    let near = FAV;
    if (over) {
      const pa = Math.atan2(over[1], over[0]); let bd = Infinity;
      for (const b of blades) { const d = Math.abs(Math.atan2(Math.sin(pa - spin - (b.i * 2 * Math.PI) / N), Math.cos(pa - spin - (b.i * 2 * Math.PI) / N))); if (d < bd) { bd = d; near = b.i; } }
    }
    if (near !== hiB) { hiB = near; for (const b of blades) b.el.sil.classList.toggle("hi", b.i === near); }
  }

  const B = register(stage, (dt) => {
    const m = stepS(rate, dt);
    spin += rate.x * 2 * Math.PI * dt;
    draw(); bright();
    return m || Math.abs(rate.x) > 1e-3;
  });
  bag.add(B.unregister);

  function retarget() {
    const f = over ? clamp(1.15 - Math.hypot(over[0], over[1]) / 90, 0.2, 1) : 0;
    rate.t = f * 1.2 * top;
    read.textContent = over ? "speed " + Math.max(1, Math.ceil(f * 5)) : "rest";
    bright();
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], BZ); over = Math.hypot(x, y) < 100 ? [x, y] : null; retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw(); retarget();
  return { set: (v) => { top = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "ceilingfan",
  means: "A ceiling fan seen from below: its five blades spin faster the nearer the pointer comes, and wind down when it leaves.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[140, 175], [200, 141], [262, 160], null],
  mount,
});

stickynotes.code:
/**
 * Sticky notes: a framed cork board standing on two posts and feet, with a
 * 3×3 grid of square notes stuck to its face, two faint lines on each. The
 * pointer is a field on the board: notes near it lift their bottom edge and
 * curl out on springs, the one under it most, bright. At rest a few notes are
 * already curling, one bright. The slider is how far a note curls.
 *
 * The pattern: a field on springs (terrain); the hit is on the board's own
 * plane, which never moves.
 */
const {
  Cam, clamp, fillet, fit, hull, open, poly, prism, proj, rings, seg, spring, stepS, facing,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 84, ZB = 14, HB = 74, YF = 2, SQ = 18, PITCH = 24, LMAX = 11;
const REST = [0, 2, 0, 1, 0, 3, 0, 5, 0], FAV = 7;
const X0 = (W - (2 * PITCH + SQ)) / 2, ZT0 = ZB + HB - (HB - (2 * PITCH + SQ)) / 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, -14, 0], [W, 14, 0], [0, 14, 0], [W, -14, 0], [0, 0, ZB + HB], [W, 0, ZB + HB], [X0, YF + LMAX * 1.6, ZB]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the stand: two feet along y, two posts up into the board
  for (const x of [10, W - 10]) {
    const [fr, fi] = rings(x - 3, -14, x + 3, 14, 2.5, 0.8);
    put(solid(g), prism(P, front, fr, fi, 0, 3));
    const [pr] = rings(x - 1.8, -1.8, x + 1.8, 1.8, 1.6, 0.5);
    put(solid(g), prism(P, front, pr, null, 3, ZB + 4));
  }
  // the board: a rounded plate in the x–z plane, a thickness along y, the frame's inner edge as its crease
  const face = (y, ins) => fillet([[ins, ZB + ins], [W - ins, ZB + ins], [W - ins, ZB + HB - ins], [ins, ZB + HB - ins]], [4 - ins / 2, 4 - ins / 2, 4 - ins / 2, 4 - ins / 2], 4).map(([x, z]) => P(x, y, z));
  const board = solid(g);
  board.sil.setAttribute("d", poly(hull(face(YF, 0).concat(face(-YF, 0)))));
  board.cr.setAttribute("d", poly(face(YF, 4)));

  const notes = [];
  for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++) {
    const k = r * 3 + c, grp = mk("g", {}, g);
    notes.push({ k, r, c, grp, x0: X0 + c * PITCH, zt: ZT0 - r * PITCH, sp: spring(REST[k]), sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), last: NaN });
  }
  // a note: its top edge stuck to the board, its bottom curling out by L
  const pt = (n, x, t, L) => P(n.x0 + x, YF + 0.3 + L * t ** 2.4, n.zt - SQ * t + L * 0.35 * t ** 3);
  function draw(n) {
    const L = n.sp.x;
    if (Math.abs(L - n.last) < 1e-3) return;
    n.last = L;
    const left = [], right = [];
    for (let i = 0; i <= 8; i++) { left.push(pt(n, 0, i / 8, L)); right.unshift(pt(n, SQ, i / 8, L)); }
    n.sil.setAttribute("d", poly(left.concat(right)));
    n.cr.setAttribute("d", seg(pt(n, 3.5, 0.32, L), pt(n, SQ - 3.5, 0.32, L)) + seg(pt(n, 3.5, 0.52, L), pt(n, SQ - 7, 0.52, L)));
  }

  let order = "";
  const B = register(stage, (dt) => {
    let m = false;
    for (const n of notes) { if (stepS(n.sp, dt)) m = true; draw(n); }
    // a curled note is nearer than a flat one; on a tie the upper note's curl lies over the lower
    const sorted = notes.slice().sort((a, b) => a.sp.x - a.r * 0.01 - (b.sp.x - b.r * 0.01));
    const key = sorted.map((n) => n.k).join();
    if (key !== order) { order = key; for (const n of sorted) g.appendChild(n.grp); }
    return m;
  });
  bag.add(B.unregister);

  // the hit: the pointer on the board's face plane y = YF, solved from P's two axes
  const o = P(0, YF, 0), ex = P(1, YF, 0), ez = P(0, YF, 1);
  const ax = [ex[0] - o[0], ex[1] - o[1]], az = [ez[0] - o[0], ez[1] - o[1]], det = ax[0] * az[1] - ax[1] * az[0];
  function onBoard([sx, sy]) {
    const dx = sx - o[0], dy = sy - o[1];
    return [(dx * az[1] - dy * az[0]) / det, (ax[0] * dy - ax[1] * dx) / det];
  }

  let over = null;
  function retarget() {
    let near = -1, bd = PITCH * 0.75;
    for (const n of notes) {
      if (over) {
        const d = Math.hypot(over[0] - (n.x0 + SQ / 2), over[1] - (n.zt - SQ / 2));
        if (d < bd) { bd = d; near = n.k; }
        n.sp.t = clamp(Math.max(REST[n.k] * 0.4, LMAX * reach * Math.exp(-((d / 20) ** 2))), 0, LMAX * 1.6);
      } else n.sp.t = REST[n.k];
    }
    for (const n of notes) n.sil.classList.toggle("hi", n.k === (over ? near : FAV));
    if (over && near >= 0) notes[near].sp.t = LMAX * reach;
    read.textContent = over && near >= 0 ? "note " + (notes[near].r + 1) + "·" + (notes[near].c + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, z] = onBoard(p);
      over = x > -2 && x < W + 2 && z > ZB - 2 && z < ZB + HB + 2 ? [x, z] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "stickynotes",
  means: "A cork board of sticky notes: notes near the pointer lift their bottom edge and curl out, the one under it most.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[160, 110], [200, 150], [240, 190], null],
  mount,
});

folderbox.code:
/**
 * Folder box: an open archive box with a handle hole and a card holder on its
 * end, seven hanging file folders standing in it, each with a tab at its own
 * place along the top. The pointer picks a folder by where it is along the
 * box: that folder rises out high, its neighbours rise a little, staggered
 * from it. At rest the folders sit unevenly, one pulled up, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the hit is on a fixed
 * plane through the folders' resting tops.
 */
const {
  Cam, clamp, facing, fillet, fit, hull, open, poly, prism, proj, rrect, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 7, STEP = 8, XS0 = 6, TOP = 26, D = 36, SW = 1.6, VIS = 9, LIFT = 24;
const X1 = XS0 + (N - 1) * STEP + 6;
const REST = [1, 0, 3, 0, 7, 1, 0], FAV = 4, TAB = [4, 14, 24, 9, 19, 4, 14];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.85);
  fit(C, [[-2, 0, 0], [X1, D, 0], [X1, 0, 0], [-2, D, 0], [XS0, 2, TOP + VIS + LIFT + 5], [X1 - 6, D, TOP + VIS + LIFT + 5]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the box: one rounded solid, open on top (its crease is the rim)
  const box = solid(g);
  put(box, prism(P, front, rrect(-2, 0, X1, D, 5, 12), rrect(-0.8, 1.2, X1 - 1.2, D - 1.2, 3.8, 12), 0, TOP));
  // the end facing us: a handle hole and a card holder
  const onEnd = (r) => poly(r.map((q) => P(X1, q.u, q.v)));
  mk("path", { class: "nf lo", d: onEnd(rrect(12, TOP - 8, 24, TOP - 4, 2, 4)) + onEnd(rrect(10, 5, 26, 13, 1, 3)) }, box.g);

  const folders = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    folders.push({ k, x: XS0 + k * STEP, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), z: tween(REST[k]), last: NaN });
  }

  // a folder: a sheet in the y–z plane with a tab on its top edge, given a thickness along x
  function profile(x, k, h) {
    const zt = TOP + h, t = TAB[k];
    const pts = [[2, TOP], [D - 2, TOP], [D - 2, zt], [t + 10.5, zt], [t + 9, zt + 4], [t, zt + 4], [t - 1.5, zt], [2, zt]];
    return fillet(pts, [0, 0, 1.5, 1, 1.2, 1.2, 1, 1.5], 4).map(([y, z]) => [x, y, z]);
  }
  function draw(f, lift) {
    if (lift === f.last) return;
    f.last = lift;
    const h = VIS + lift, near = profile(f.x + SW / 2, f.k, h), far = profile(f.x - SW / 2, f.k, h);
    f.sil.setAttribute("d", poly(hull(near.concat(far).map((p) => P(...p)))));
    f.cr.setAttribute("d", open(near.filter((p) => p[2] > TOP + 0.5).map((p) => P(...p))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    folders.forEach((f) => { draw(f, tval(f.z, now)); if (!tdone(f.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: the pointer on a fixed plane through the resting folders, nearest folder along x
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TOP + VIS * 0.6);
    if (x < -4 || x > X1 + 2 || y < -4 || y > D + 2) return -1;
    return clamp(Math.round((x - XS0) / STEP), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    folders.forEach((f, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : Math.max(0, 7 - 3 * Math.abs(k - a));
      tset(f.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      f.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "folder " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "folderbox",
  means: "An archive box of hanging folders: the folder under the pointer rises out, its neighbours rise a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[160, 120], [200, 140], [240, 160], null],
  mount,
});

shredder.code:
/**
 * Shredder: a paper shredder on its bin, a head with a feed slot along its top
 * and a power dot, a window in the bin's front, and three sheets standing in
 * the slot, waiting. The pointer is a field along the slot: the sheet under it
 * feeds down into the slot on a spring, and its neighbours shift aside. At
 * rest the sheets wait at uneven depths, the middle one tall and bright. The
 * slider is how deep a sheet feeds.
 *
 * The pattern: a field on springs (terrain); the hit is on a fixed plane
 * through the sheets' resting middles.
 */
const {
  Cam, clamp, facing, fillet, fit, open, poly, prism, proj, rrect, seg, unproj, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const W = 64, D = 36, BH = 50, TOP = 60, YS = 17, H = 34, SWD = 15;
const CX = [15, 32, 49], REST = [6, 0, 11], FAV = 1, SHIFT = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let deep = 26 * value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, YS, TOP + H], [W, YS, TOP + H]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the bin, its window on the near face, and the head above it with the slot
  const bin = solid(g);
  put(bin, prism(P, front, rrect(0, 0, W, D, 5, 12), rrect(1.4, 1.4, W - 1.4, D - 1.4, 3.6, 12), 0, BH));
  mk("path", { class: "nf lo", d: poly(rrect(12, 10, W - 12, 34, 3, 4).map((q) => P(q.u, D, q.v))) }, bin.g);
  const head = solid(g);
  put(head, prism(P, front, rrect(-1.5, -1.5, W + 1.5, D + 1.5, 6, 12), rrect(-0.3, -0.3, W + 0.3, D + 0.3, 4.8, 12), BH, TOP));
  mk("path", { class: "nf lo", d: poly(rrect(5, YS - 2, W - 5, YS + 2, 1.5, 4).map((q) => P(q.u, q.v, TOP))) }, head.g);
  const power = flatDot(head.g, C, 1.6, "dot off");
  place(power, P(W - 7, D - 6, TOP));

  // a sheet: a flat page in the x–z plane, standing in the slot, two faint fold lines
  const sheets = CX.map((c, k) => {
    const grp = mk("g", {}, g);
    return { k, c, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp),
      z: spring(REST[k]), x: spring(0), last: "" };
  });
  function draw(s) {
    const key = s.z.x.toFixed(2) + "," + s.x.x.toFixed(2);
    if (key === s.last) return;
    s.last = key;
    const x0 = s.c + s.x.x - SWD / 2, x1 = x0 + SWD, zt = TOP + H - s.z.x;
    const pts = fillet([[x0, TOP], [x1, TOP], [x1, zt], [x0, zt]], [0, 0, 1.2, 1.2], 3);
    s.sil.setAttribute("d", poly(pts.map(([x, z]) => P(x, YS, z))));
    const ln = (dz, w) => (zt - dz > TOP + 1 ? seg(P(x0 + 3, YS, zt - dz), P(x0 + 3 + w, YS, zt - dz)) : "");
    s.cr.setAttribute("d", ln(9, 9) + ln(13, 6));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const s of sheets) { if (stepS(s.z, dt)) m = true; if (stepS(s.x, dt)) m = true; draw(s); }
    return m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = -1, bd = 10;
    sheets.forEach((s, k) => { if (over !== null && Math.abs(over - s.c) < bd) { bd = Math.abs(over - s.c); near = k; } });
    sheets.forEach((s, k) => {
      if (over === null) { s.z.t = REST[k]; s.x.t = 0; }
      else {
        const d = Math.abs(over - s.c), f = Math.exp(-((d / 11) ** 2));
        s.z.t = clamp(Math.max(REST[k] * 0.4, deep * f), 0, H - 6);
        s.x.t = k === near ? 0 : Math.sign(s.c - over) * SHIFT * Math.max(0.3, Math.exp(-((d / 22) ** 2)));
      }
      s.sil.classList.toggle("hi", k === (over === null ? FAV : near));
    });
    read.textContent = near < 0 ? "rest" : "sheet " + (near + 1);
    B.wake();
  }

  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const [x, y] = unproj(C, sx, sy, TOP + H / 2);
      over = x > 2 && x < W - 2 && Math.abs(y - YS) < 16 ? x : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { deep = 26 * v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "shredder",
  means: "A paper shredder with three sheets waiting: the sheet under the pointer feeds down into the slot, and its neighbours shift aside.",
  rules: [1, 3, 5, 8],
  range: [0.4, 0.75, 1],
  tour: [[150, 100], [200, 125], [250, 150], null],
  mount,
});

deskfan.code:
/**
 * Desk fan: a round base with a power dot, a stem, and a head that is a round
 * grille cage over three blades, a motor housing behind it. The pointer is
 * what the fan aims at: the head turns on a spring to face it, and the blades
 * spin while it turns, faster the nearer the pointer is, then coast to a
 * stop. At rest the fan looks a little aside and the power dot is bright. The
 * slider is how quickly the head follows (a stiffer or softer spring).
 *
 * The pattern: a continuous aim (officechairs); the hit is on the floor's
 * plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rad, unproj, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const H = 46, R = 21, FWD = rad(45), REST = rad(45 - 22), SPAN = rad(62);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.45);
  const ext = [[-17, -17, 0], [17, 17, 0], [17, -17, 0], [-17, 17, 0]];
  for (let k = -1; k <= 1; k++) {
    const a = FWD + k * SPAN, ux = -Math.sin(a), uy = Math.cos(a);
    ext.push([ux * R, uy * R, H + R], [-ux * R, -uy * R, H - R], [Math.cos(a) * 8, Math.sin(a) * 8, H + R]);
  }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const base = solid(g);
  put(base, prism(P, front, circ(17, 48), circ(15.6, 48), 0, 4));
  const knob = flatDot(base.g, C, 1.7, "dot");
  place(knob, P(8, 8, 4));
  put(solid(g), prism(P, front, circ(2.2, 20), null, 4, H - 4));
  const motor = solid(g), cage = solid(g);
  const blades = mk("path", { class: "nf lo" }, cage.g);

  const aim = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) }), spin = spring(0);
  let phase = 0.4, drawn = "";
  // a point in the head's frame: f along the aim, p across it, q up
  const at = (a, f, p, q) => {
    const c = Math.cos(a), s = Math.sin(a);
    return P(c * (f + 3) - s * p, s * (f + 3) + c * p, H + q);
  };
  const ring = (a, f, r, n = 40) => {
    const out = [];
    for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; out.push(at(a, f, r * Math.cos(t), r * Math.sin(t))); }
    return out;
  };
  function draw() {
    const a = aim.x, key = a.toFixed(4) + "," + phase.toFixed(3);
    if (key === drawn) return;
    drawn = key;
    motor.sil.setAttribute("d", poly(hull(ring(a, -3, 8, 24).concat(ring(a, -12, 6.5, 24)))));
    cage.sil.setAttribute("d", poly(hull(ring(a, 5, R).concat(ring(a, -4, R)))));
    cage.cr.setAttribute("d", poly(ring(a, 5, R - 1.4)) + poly(ring(a, 5, 3, 16)));
    let d = "";
    for (let b = 0; b < 3; b++) {
      const b0 = phase + (b / 3) * Math.PI * 2, side = [], back = [];
      for (let i = 0; i <= 8; i++) {
        const u = i / 8, r = 3 + 14.5 * u, w = Math.sin(Math.PI * u);
        side.push(at(a, 3, r * Math.cos(b0 + 0.5 * w), r * Math.sin(b0 + 0.5 * w)));
        back.unshift(at(a, 3, r * Math.cos(b0 - 0.2 * w), r * Math.sin(b0 - 0.2 * w)));
      }
      d += poly(side.concat(back));
    }
    blades.setAttribute("d", d);
  }

  const B = register(stage, (dt) => {
    const turning = stepS(aim, dt);
    if (!turning) spin.t = 0;
    const spinning = stepS(spin, dt);
    phase = (phase + spin.x * dt) % (Math.PI * 2);
    draw();
    return turning || spinning;
  });
  bag.add(B.unregister);

  let on = false;
  function retarget(target, near) {
    aim.t = target;
    if (on) spin.t = 5 + 20 * near;
    cage.sil.classList.toggle("hi", on);
    knob.setAttribute("class", on ? "dot off" : "dot");
    read.textContent = on ? "aim " + Math.round((target - FWD) * 36 / Math.PI) * 5 + "°" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const [x, y] = unproj(C, sx, sy, 0), r = Math.hypot(x, y);
      on = r > 8 && r < 120;
      if (!on) return retarget(REST, 0);
      const off = Math.atan2(y, x) - FWD, w = off - Math.PI * 2 * Math.round(off / (Math.PI * 2));
      retarget(FWD + clamp(w, -SPAN, SPAN), clamp(1 - (r - 20) / 70, 0, 1));
    },
    leave: () => { on = false; retarget(REST, 0); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget(REST, 0);
  return { set: (v) => { aim.k = 100 * v; aim.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "deskfan",
  means: "An oscillating desk fan: the head turns to face the pointer, and the blades spin while it turns, faster when the pointer is near.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[150, 230], [210, 270], [270, 220], null],
  mount,
});

printer3d.code:
/**
 * 3D printer: an open box frame on a base, a print bed with a half-printed
 * vase on it, a gantry riding two top rails and a nozzle head on the gantry.
 * The pointer is where the nozzle should go: the head runs to the pointer's
 * x/y over the bed on springs, the gantry carrying it. At rest the head is
 * parked over the print, bright. The slider is how quickly it follows.
 *
 * The pattern: a continuous aim (spotlights); the hit is on the bed's plane.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, ringAt, run, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 80, D = 80, H = 72, BZ = 12, M = 12, VR = 11, VH = 14, REST = [34, 38];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, 0, H + 4], [W, 0, H + 4], [0, D, H + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r = 1.2, b = 0.6, parent = g) => { const [a, i] = rings(x0, y0, x1, y1, r, b); const s = solid(parent); put(s, prism(P, front, a, i, z0, z1)); return s; };
  box(-2, -2, W + 2, D + 2, 0, 6, 3, 1.4);
  box(0, 0, 5, 5, 6, H);
  box(W - 5, 0, W, 5, 6, H); box(0, D - 5, 5, D, 6, H);
  box(M - 4, M - 4, W - M + 4, D - M + 4, 6, 9, 2, 1);
  box(M - 6, M - 6, W - M + 6, D - M + 6, 9, BZ, 2, 1);
  const vase = circ(VR, 40), cx = REST[0] + 6, cy = REST[1] + 4;
  put(solid(g), prism(P, front, vase.map((q) => ({ ...q, u: q.u + cx, v: q.v + cy })), null, BZ, BZ + VH));
  const vr = vase.map((q) => ({ ...q, u: q.u + cx, v: q.v + cy }));
  mk("path", { class: "nf lo", d: [3, 6, 9, 12].map((z) => open(ringAt(P, run(vr, front), BZ + z))).join("") + poly(ringAt(P, circ(VR - 1.6, 40).map((q) => ({ ...q, u: q.u + cx, v: q.v + cy })), BZ + VH)) }, g);
  box(0, 0, W, 5, H, H + 4); box(0, 0, 5, D, H, H + 4);
  const gantry = solid(g), head = solid(g), nozzle = mk("path", { class: "sil" }, g);
  box(W - 5, 0, W, D, H, H + 4); box(0, D - 5, W, D, H, H + 4);
  box(W - 5, D - 5, W, D, 6, H);
  const sx = spring(REST[0], { k: 100 * value, c: 18 * Math.sqrt(value) }), sy = spring(REST[1], { k: 100 * value, c: 18 * Math.sqrt(value) });
  let last = "";
  function draw() {
    const key = sx.x.toFixed(2) + "," + sy.x.toFixed(2);
    if (key === last) return;
    last = key;
    const x = M + sx.x, y = M + sy.x;
    { const [a, i] = rings(4, y - 3, W - 4, y + 3, 1.2, 0.6); put(gantry, prism(P, front, a, i, H - 1, H + 5)); }
    { const [a, i] = rings(x - 6, y - 5, x + 6, y + 5, 2, 0.8); put(head, prism(P, front, a, i, H - 16, H + 7)); }
    nozzle.setAttribute("d", poly(hull(ringAt(P, circ(2.6, 12).map((q) => ({ ...q, u: q.u + x, v: q.v + y })), H - 16).concat([P(x, y, H - 21)]))));
  }
  const B = register(stage, (dt) => { const a = stepS(sx, dt), b = stepS(sy, dt); draw(); return a || b; });
  bag.add(B.unregister);
  head.sil.classList.add("hi");
  let over = null;
  function retarget() {
    const [x, y] = over ?? REST;
    sx.t = x; sy.t = y;
    read.textContent = over ? `x ${Math.round(x)} y ${Math.round(y)}` : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], BZ), S = W - 2 * M;
      over = x < -10 || y < -10 || x > W + 10 || y > D + 10 ? null : [clamp(x - M, 0, S), clamp(y - M, 0, S)];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const s of [sx, sy]) { s.k = 100 * v; s.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

