cctvcameras.code:
/**
 * CCTV cameras: the inside corner of a building, two walls meeting over a
 * paved plot, with three box cameras on wall arms. The pointer is what they
 * watch: every camera turns on its own springs to face the point on the
 * ground under it, and the camera nearest it is bright. At rest each camera
 * looks at its own patch of ground, one bright. The slider is how quickly
 * they follow.
 *
 * The pattern: a continuous aim (spotlights); the hit is on the ground plane.
 */
const {
  Cam, clamp, facing, fit, hull, poly, prism, proj, rings, rrect, circ, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const G = 92, WH = 74, T = 6, LEN = 24;
const CAMS = [[22, 58, 58, 0, 58], [18, 18, 64, 0, 0], [58, 22, 58, 58, 0]];
const REST = [[30, 74], [46, 40], [74, 28]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-T, -T, 0], [G, G, -4], [G, -T, -4], [-T, G, -4], [-T, -T, WH], [G, -T, WH], [-T, G, WH]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  { const [r, i] = rings(-T, -T, G, G, 3, 1.4); put(solid(g), prism(P, front, r, i, -4, 0)); }
  { const [r, i] = rings(-T, -T, G, 0, 2, 1); put(solid(g), prism(P, front, r, i, 0, WH)); }
  { const [r, i] = rings(-T, 0, 0, G, 2, 1); put(solid(g), prism(P, front, r, i, 0, WH)); }
  mk("path", { class: "nf lo", d: seg(P(0, 1, 8), P(G - 2, 1, 8)) + seg(P(1, 0, 8), P(1, G - 2, 8)) }, g);
  const sec = rrect(-4.6, -3.6, 4.6, 3.6, 1.6, 3), lensR = circ(2.6, 16);
  const cams = CAMS.map(([x, y, z, wx, wy], k) => {
    const grp = mk("g", {}, g);
    mk("path", { class: "nf sil", d: seg(P(wx, wy, z + 4), P(x, y, z + 4)) + seg(P(x, y, z + 4), P(x, y, z + 2.4)) }, grp);
    const body = mk("path", { class: "sil" }, grp), lens = mk("path", { class: "nf" }, grp), hood = mk("path", { class: "nf lo" }, grp);
    const o = { k, c: [x, y, z], body, lens, hood, last: "" };
    o.sx = spring(REST[k][0], { k: 100 * value, c: 18 * Math.sqrt(value) });
    o.sy = spring(REST[k][1], { k: 100 * value, c: 18 * Math.sqrt(value) });
    return o;
  });

  function draw(o) {
    const key = o.sx.x.toFixed(2) + "," + o.sy.x.toFixed(2);
    if (key === o.last) return;
    o.last = key;
    const [cx, cy, cz] = o.c, d0 = [o.sx.x - cx, o.sy.x - cy, -cz], n = Math.hypot(...d0), d = d0.map((q) => q / n);
    const hn = Math.hypot(d[0], d[1]) || 1, u = [-d[1] / hn, d[0] / hn, 0];
    const v = [u[1] * d[2] - u[2] * d[1], u[2] * d[0] - u[0] * d[2], u[0] * d[1] - u[1] * d[0]];
    const at = (off, a, b) => P(cx + d[0] * off + a * u[0] + b * v[0], cy + d[1] * off + a * u[1] + b * v[1], cz + d[2] * off + a * u[2] + b * v[2]);
    const back = sec.map((q) => at(-LEN * 0.35, q.u, q.v)), fr = sec.map((q) => at(LEN * 0.65, q.u * 1.12, q.v * 1.12));
    o.body.setAttribute("d", poly(hull(back.concat(fr))));
    const sees = d[0] * 0.61 + d[1] * 0.61 + d[2] * 0.5 > 0;
    o.lens.setAttribute("d", sees ? poly(lensR.map((q) => at(LEN * 0.65, q.u, q.v))) : "");
    o.hood.setAttribute("d", seg(at(-LEN * 0.35, -4.4, 3.4), at(LEN * 0.65, -4.9, 3.8)) + seg(at(-LEN * 0.35, 4.4, 3.4), at(LEN * 0.65, 4.9, 3.8)));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const o of cams) { if (stepS(o.sx, dt)) m = true; if (stepS(o.sy, dt)) m = true; draw(o); }
    return m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = null, bd = Infinity;
    cams.forEach((o, k) => {
      const [x, y] = over ?? REST[k];
      o.sx.t = x; o.sy.t = y;
      if (over) { const dd = Math.hypot(o.c[0] - x, o.c[1] - y); if (dd < bd) { bd = dd; near = o; } }
    });
    cams.forEach((o) => o.body.classList.toggle("hi", over ? o === near : o.k === 1));
    read.textContent = near ? "cam " + (near.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      over = x < -4 || y < -4 || x > G + 20 || y > G + 20 ? null : [clamp(x, 6, G - 4), clamp(y, 6, G - 4)];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const o of cams) for (const s of [o.sx, o.sy]) { s.k = 100 * v; s.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "cctvcameras",
  means: "Three security cameras on a building corner: every camera turns to face the pointer, and the nearest one is bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[120, 215], [200, 240], [280, 215], null],
  mount,
});

lunchboxes.code:
/**
 * Lunchboxes: four kids' lunch boxes in a row on a bench, each a rounded
 * body with a latch on its front and a hinged lid with a carry handle. The
 * pointer picks a box by where it stands: its lid flips open on the back
 * hinge to show a sandwich wedge inside, and the lids beside it lift a
 * little, staggered from it. At rest one lid stands half open, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the pick is the box
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rad, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, BW = 30, D = 22, H = 16, STEP = 38, LT = 3, OPEN = 105, FAV = 2;
const REST = [6, 0, 62, 3], X1 = (N - 1) * STEP + BW;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.72);
  fit(C, [[-6, -6, -22], [X1 + 6, D + 6, -22], [X1 + 6, -6, -22], [-6, D + 6, -22], [0, -4, H + D + 8], [X1, -4, H + D + 8]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the bench: two legs and a plank
  for (const lx of [4, X1 - 10]) { const [r, i] = rings(lx, -2, lx + 6, D + 2, 1.5, 0.6); put(solid(g), prism(P, front, r, i, -22, -5)); }
  { const [r, i] = rings(-6, -6, X1 + 6, D + 6, 4, 1.5); put(solid(g), prism(P, front, r, i, -5, 0)); }

  const boxes = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * STEP, grp = mk("g", {}, g), body = solid(grp);
    const [r, i] = rings(x0, 0, x0 + BW, D, 4, 1.4);
    put(body, prism(P, front, r, i, 0, H));
    // the latch on the front face
    const latch = rrect(x0 + BW / 2 - 3, H - 7, x0 + BW / 2 + 3, H - 1, 1, 3).map((q) => P(q.u, D, q.v));
    mk("path", { class: "nf", d: poly(latch) + seg(P(x0 + BW / 2 - 1.5, D, H - 4), P(x0 + BW / 2 + 1.5, D, H - 4)) }, body.g);
    const sand = solid(grp), lid = solid(grp), handle = mk("path", { class: "nf" }, grp);
    boxes.push({ k, x0, grp, body, sand, lid, handle, a: tween(REST[k]), last: NaN, behind: null });
  }

  // a point on the lid: u along x, v from the hinge, w off its face, turned up by th about the back top edge
  const L = (th, x, v, w) => P(x, v * Math.cos(th) - w * Math.sin(th), H + v * Math.sin(th) + w * Math.cos(th));
  function draw(b, deg) {
    if (deg === b.last) return;
    b.last = deg;
    const th = rad(deg), x0 = b.x0, outer = rrect(x0, 0, x0 + BW, D, 4, 4), inner = rrect(x0 + 1.4, 1.4, x0 + BW - 1.4, D - 1.4, 2.6, 4);
    const pts = outer.map((q) => L(th, q.u, q.v, 0)).concat(outer.map((q) => L(th, q.u, q.v, LT)));
    const up = -0.61 * Math.sin(th) + 0.5 * Math.cos(th) > 0;
    b.lid.sil.setAttribute("d", poly(hull(pts)));
    b.lid.cr.setAttribute("d", poly(inner.map((q) => L(th, q.u, q.v, up ? LT : 0))));
    const arch = [];
    for (let i = 0; i <= 10; i++) { const t = i / 10; arch.push(L(th, x0 + BW / 2 - 7 + 14 * t, D / 2, LT + 5 * Math.sin(Math.PI * t))); }
    b.handle.setAttribute("d", up ? open(arch) : "");
    // the sandwich wedge rises into view as the lid opens
    const f = Math.min(1, deg / 70), h = 11 * f, xc = x0 + BW / 2 + 2;
    if (f < 0.08) { b.sand.sil.setAttribute("d", ""); b.sand.cr.setAttribute("d", ""); }
    else {
      const tri = (x) => [[x, 6, H], [x, D - 4, H], [x, 6, H + h]].map((p) => P(...p));
      b.sand.sil.setAttribute("d", poly(hull(tri(xc - 4).concat(tri(xc + 4)))));
      b.sand.cr.setAttribute("d", open([P(xc + 4, D - 4, H), P(xc + 4, 6, H + h)]));
    }
    const behind = deg > 40;
    if (behind !== b.behind) { b.behind = behind; if (behind) { b.grp.append(b.lid.g, b.handle, b.sand.g); } else { b.grp.append(b.sand.g, b.lid.g, b.handle); } }
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of boxes) { draw(b, tval(b.a, now)); if (!tdone(b.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = boxes.map((b) => P(b.x0 + BW / 2, D / 2, H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 55 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    boxes.forEach((b, k) => {
      const dd = Math.abs(k - a), deg = a < 0 ? REST[k] : dd === 0 ? OPEN : dd === 1 ? 16 : 5;
      tset(b.a, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      b.lid.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "box " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "lunchboxes",
  means: "Four lunch boxes on a bench: the lid under the pointer flips open on a sandwich, and its neighbours' lids lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[177, 158], [223, 181], [269, 204], null],
  mount,
});

toytrain.code:
/**
 * Toy train: an oval wooden track with two grooves, and an engine (body,
 * cab, chimney) pulling three carriages round it. The train runs while the
 * figure is on screen. Over the track the pointer brakes it on a spring to a
 * crawl, and the car nearest the pointer goes bright. At rest the engine is
 * bright. The slider is how hard the pointer brakes.
 *
 * The pattern: ambient motion with a spring on its speed; the pick is on a
 * fixed plane through the cars' middles.
 */
const {
  Cam, fit, facing, poly, prism, proj, ringAt, rrect, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const A = 34, R = 26, TW = 7, TZ = 3, V = 20, GAP = 19, PER = 4 * A + 2 * Math.PI * R;

// a stadium ring of radius r round the two curve centres
function stadium(r, n = 14) {
  const out = [];
  for (const [cx, a0] of [[A, -Math.PI / 2], [-A, Math.PI / 2]]) {
    for (let i = 0; i <= n; i++) { const a = a0 + (i / n) * Math.PI, nu = Math.cos(a), nv = Math.sin(a); out.push({ u: cx + r * nu, v: r * nv, nu, nv }); }
  }
  return out;
}
// the centre line at arc length s: [x, y, heading]
function at(s) {
  s = ((s % PER) + PER) % PER;
  if (s < 2 * A) return [-A + s, R, 0];
  s -= 2 * A;
  if (s < Math.PI * R) { const a = Math.PI / 2 - s / R; return [A + R * Math.cos(a), R * Math.sin(a), Math.atan2(-Math.cos(a), Math.sin(a))]; }
  s -= Math.PI * R;
  if (s < 2 * A) return [A - s, -R, Math.PI];
  s -= 2 * A;
  const a = -Math.PI / 2 - s / R;
  return [-A + R * Math.cos(a), R * Math.sin(a), Math.atan2(-Math.cos(a), Math.sin(a))];
}
// a rounded box ring in the car's own frame, turned to heading h at (cx, cy)
function boxRing(cx, cy, h, u0, v0, u1, v1, r) {
  const c = Math.cos(h), s = Math.sin(h);
  return rrect(u0, v0, u1, v1, r, 4).map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let brake = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-A - R - TW, -R - TW, 0], [A + R + TW, R + TW, 0], [A + R + TW, -R - TW, 18], [-A - R - TW, R + TW, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  put(solid(g), prism(P, front, stadium(R + TW), stadium(R + TW - 1.4), 0, TZ));
  mk("path", { class: "nf", d: poly(ringAt(P, stadium(R - TW), TZ)) }, g);
  mk("path", { class: "nf lo", d: poly(ringAt(P, stadium(R - 3.2), TZ)) + poly(ringAt(P, stadium(R + 3.2), TZ)) }, g);

  const cg = mk("g", {}, g);
  const cars = [0, 1, 2, 3].map((k) => {
    const grp = mk("g", {}, cg), body = solid(grp);
    return k === 0 ? { k, grp, body, cab: solid(grp), chim: solid(grp) } : { k, grp, body };
  });
  const prismOf = (cx, cy, h, u0, v0, u1, v1, z0, z1, r = 2) =>
    prism(P, front, boxRing(cx, cy, h, u0, v0, u1, v1, r), boxRing(cx, cy, h, u0 + 0.8, v0 + 0.8, u1 - 0.8, v1 - 0.8, Math.max(0.4, r - 0.8)), z0, z1);

  let s = 40, order = "", near = -1, ptr = null;
  const sp = spring(1);
  function draw() {
    const cen = [];
    cars.forEach((c) => {
      const [x, y, h] = at(s - c.k * GAP);
      cen.push([x, y]);
      if (c.k === 0) {
        put(c.body, prismOf(x, y, h, -8, -4.5, 8, 4.5, TZ, TZ + 7));
        put(c.cab, prismOf(x, y, h, -8, -4.5, -1.5, 4.5, TZ + 7, TZ + 14, 1.6));
        put(c.chim, prismOf(x, y, h, 3, -1.8, 6.6, 1.8, TZ + 7, TZ + 12, 1.8));
        const cabNear = Math.cos(h) + Math.sin(h) < 0;
        if (cabNear) c.grp.append(c.chim.g, c.cab.g); else c.grp.append(c.cab.g, c.chim.g);
      } else put(c.body, prismOf(x, y, h, -7, -4.5, 7, 4.5, TZ, TZ + 8 - c.k, 2.2));
    });
    const ord = cars.map((c, i) => [i, cen[i][0] + cen[i][1]]).sort((a, b) => a[1] - b[1]).map((e) => e[0]);
    if (ord.join() !== order) { order = ord.join(); for (const i of ord) cg.appendChild(cars[i].grp); }
    return cen;
  }

  function pick(cen) {
    if (!ptr) return -1;
    let best = -1, bd = 22;
    cen.forEach(([x, y], i) => { const d = Math.hypot(x - ptr[0], y - ptr[1]); if (d < bd) { bd = d; best = i; } });
    return best;
  }
  function mark(a) {
    if (a === near) return;
    near = a;
    cars.forEach((c, i) => {
      const on = i === (a < 0 ? 0 : a);
      for (const part of [c.body, c.cab, c.chim]) if (part) part.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : a === 0 ? "engine" : "car " + a;
  }

  const B = register(stage, (dt) => {
    stepS(sp, dt);
    s += V * sp.x * dt;
    mark(pick(draw()));
    return true;
  });
  bag.add(B.unregister);
  mark(-2); mark(-1);

  // the pointer on a fixed plane through the cars' middles; over the track it brakes the train
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TZ + 5);
    const over = Math.abs(y) < R + TW + 6 && Math.abs(x) < A + R + TW + 6;
    ptr = over ? [x, y] : null;
    sp.t = over ? 1 - 0.85 * brake : 1;
    B.wake();
  }
  bag.add(pointer(stage, { move, leave: () => { ptr = null; sp.t = 1; B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { brake = v; if (ptr) sp.t = 1 - 0.85 * v; }, destroy: bag.dispose };
}

hairline({
  name: "toytrain",
  means: "A toy train on an oval wooden track: over the track the pointer brakes it to a crawl, and the car nearest it goes bright.",
  rules: [1, 3, 7, 8],
  range: [0, 0.8, 1],
  tour: [[130, 150], [200, 190], [280, 180], null],
  mount,
});

cattree.code:
/**
 * Cat tree: a base plate, one sisal-wrapped post with rope bands, and three
 * platforms stepping up round it, a ball toy hanging on a cord from the top
 * one. The pointer picks a platform on its own resting top: it rises a
 * little, bright, and the ball swings toward the pointer on springs. At
 * rest the middle platform stands a touch high, bright. The slider is the
 * reach of the swing.
 *
 * The pattern: stepped parts (each tested on its own rest top) and a
 * pendulum on springs.
 */
const {
  Cam, circ, clamp, facing, fit, open, poly, prism, proj, rings, ringAt, run, spring, stepS, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PR = 5, TH = 4, RISE = 6, FAV = 1, CORD = 16, BR = 3.6;
// level: [x0, y0, x1, y1, z]; level 2 stands behind the post, level 1 in front, level 3 on top
const LV = [[-20, 4, 8, 28, 18], [-6, -30, 22, -5, 38], [-16, -14, 16, 14, 58]];
const REST = [0, 2, 0], ANCH = [12, 12];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-26, -32, 0], [26, 30, 0], [26, -32, 0], [-26, 30, 0], [-16, -14, 58 + TH + RISE], [16, 14, 58 + TH + RISE], [24, 24, 30]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  { const [r, i] = rings(-26, -32, 26, 30, 6, 1.6); put(solid(g), prism(P, front, r, i, 0, 4)); }

  const mkLevel = (k) => ({ k, el: solid(g), z: tween(REST[k]), last: NaN });
  const lv = [];
  lv[1] = mkLevel(1);
  const post = solid(g), bands = mk("path", { class: "nf lo" }, post.g);
  lv[0] = mkLevel(0);
  lv[2] = mkLevel(2);
  const cord = mk("path", { class: "nf lo" }, g), ball = mk("path", { class: "nf" }, g), seam = mk("path", { class: "nf lo" }, g);
  const sx = spring(4), sy = spring(-2);
  let postLast = NaN, ballLast = "";

  function drawLevel(L, lift) {
    if (lift === L.last) return;
    L.last = lift;
    const [x0, y0, x1, y1, z] = LV[L.k], [r, i] = rings(x0, y0, x1, y1, 5, 1.6);
    put(L.el, prism(P, front, r, i, z + lift, z + lift + TH));
  }
  function drawPost(top) {
    if (top === postLast) return;
    postLast = top;
    put(post, prism(P, front, disc(0, 0, PR), disc(0, 0, PR - 0.8), 4, top));
    let d = "";
    for (let z = 8; z < top - 2; z += 4.5) d += open(ringAt(P, run(disc(0, 0, PR), front), z));
    bands.setAttribute("d", d);
  }
  function drawBall(top) {
    const dx = sx.x, dy = sy.x, key = dx.toFixed(2) + dy.toFixed(2) + top.toFixed(2);
    if (key === ballLast) return;
    ballLast = key;
    const ax = ANCH[0], ay = ANCH[1], bz = top - Math.sqrt(Math.max(1, CORD * CORD - dx * dx - dy * dy));
    const c = P(ax + dx, ay + dy, bz), e = P(ax + dx + BR * 0.7071, ay + dy - BR * 0.7071, bz), rr = Math.hypot(e[0] - c[0], e[1] - c[1]);
    cord.setAttribute("d", open([P(ax, ay, top), P(ax + dx, ay + dy, bz + BR)]));
    const pts = [];
    for (let i = 0; i < 28; i++) { const a = (i / 28) * Math.PI * 2; pts.push([c[0] + rr * Math.cos(a), c[1] + rr * Math.sin(a)]); }
    ball.setAttribute("d", poly(pts));
    seam.setAttribute("d", open(pts.slice(0, 15).map(([px, py]) => [px, c[1] + (py - c[1]) * 0.35])));
  }

  const B = register(stage, (dt, now) => {
    let moving = false;
    for (const L of lv) { drawLevel(L, tval(L.z, now)); if (!tdone(L.z, now)) moving = true; }
    const top = LV[2][4] + tval(lv[2].z, now);
    drawPost(top);
    if (stepS(sx, dt)) moving = true;
    if (stepS(sy, dt)) moving = true;
    drawBall(top);
    return moving;
  });
  bag.add(B.unregister);

  // each level tested on its own resting top; the nearest middle among those the pointer falls inside
  function hit([px, py]) {
    let best = -1, bd = Infinity;
    LV.forEach(([x0, y0, x1, y1, z], k) => {
      const [x, y] = unproj(C, px, py, z + TH + REST[k]);
      if (x < x0 - 2 || x > x1 + 2 || y < y0 - 2 || y > y1 + 2) return;
      const d = Math.hypot(x - (x0 + x1) / 2, y - (y0 + y1) / 2);
      if (d < bd) { bd = d; best = k; }
    });
    return best;
  }
  function swing([px, py]) {
    const [x, y] = unproj(C, px, py, LV[2][4] - CORD);
    sx.t = clamp((x - ANCH[0]) * 0.25 * reach, -9, 9);
    sy.t = clamp((y - ANCH[1]) * 0.25 * reach, -9, 9);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    lv.forEach((L, k) => {
      tset(L.z, a < 0 ? REST[k] : k === a ? RISE : 0, now, 0);
      L.el.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "level " + (a + 1);
  }
  setActive(-1);
  bag.add(pointer(stage, {
    move: (p) => { setActive(hit(p)); swing(p); B.wake(); },
    leave: () => { setActive(-1); sx.t = 4; sy.t = -2; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "cattree",
  means: "A cat tree: the platform under the pointer rises a little, and the hanging ball toy swings toward the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1.6],
  tour: [[130, 180], [246, 127], [198, 91], null],
  mount,
});

escooters.code:
/**
 * E-scooters: four electric scooters parked side by side at a charging strip,
 * each a deck on two wheels with a stem and a handlebar. The pointer picks a
 * scooter by where it stands: it rolls out toward the reader and its stem
 * lifts upright, and the scooters beside it ease out a little, staggered from
 * it. At rest the stems lean back at different angles, one scooter bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (bookshelf); the pick is the
 * scooter whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, fit, poly, prism, proj, rings, seg, facing, tdone, tset, tval, tween,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const N = 4, GAPX = 17, L = 26, WR = 3.4, DZ = 4.6, STEM = 30, BAR = 7, OUT = 14, FAV = 2;
const LEAN = [24, 38, 30, 46];
const X = (k) => k * GAPX;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.3);
  const X1 = X(N - 1);
  fit(C, [[-10, -12, 0], [X1 + 10, -12, 0], [-10, L + OUT + 4, 0], [X1 + 10, L + OUT + 4, 0], [0, L + OUT, DZ + STEM + 2], [X1, -8, 14]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the charging strip behind the row, a port per bay
  const [sr, si] = rings(-10, -12, X1 + 10, -5, 2, 0.8);
  put(solid(g), prism(P, front, sr, si, 0, 12));
  const ports = [];
  for (let k = 0; k < N; k++) { const d = flatDot(g, C, 1.3, "dot off"); place(d, P(X(k), -5, 8)); ports.push(d); }

  const wheel = (x, y) => {
    const pts = [];
    for (let i = 0; i < 24; i++) { const a = (i / 24) * Math.PI * 2; pts.push(P(x, y + WR * Math.cos(a), WR + WR * Math.sin(a))); }
    return poly(pts);
  };
  const sc = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    const s = { k, grp, back: mk("path", { class: "sil" }, grp), deck: solid(grp), front: mk("path", { class: "sil" }, grp),
      stem: mk("path", { class: "nf sil" }, grp), bar: mk("path", { class: "nf sil" }, grp),
      y: tween(k === FAV ? 5 : 0), t: tween(LEAN[k]), last: "" };
    sc.push(s);
  }
  function draw(s, y, t) {
    const key = y.toFixed(2) + "," + t.toFixed(2);
    if (key === s.last) return;
    s.last = key;
    const x = X(s.k);
    s.back.setAttribute("d", wheel(x, y + WR));
    const [r, i] = rings(x - 3.2, y + 1, x + 3.2, y + L - 1, 2, 0.8);
    put(s.deck, prism(P, front, r, i, WR + 0.6, DZ + 0.8));
    s.front.setAttribute("d", wheel(x, y + L - WR));
    // the stem rises from the deck's front end, leaning back by t degrees
    const a = t * Math.PI / 180, fy = y + L - 2, top = [x, fy - STEM * Math.sin(a), DZ + STEM * Math.cos(a)];
    s.stem.setAttribute("d", seg(P(x - 0.7, fy, DZ), P(top[0] - 0.7, top[1], top[2])) + seg(P(x + 0.7, fy, DZ), P(top[0] + 0.7, top[1], top[2])));
    s.bar.setAttribute("d", seg(P(x - BAR, top[1], top[2]), P(x + BAR, top[1], top[2])) + seg(P(x - BAR, top[1] + 1.2, top[2]), P(x + BAR, top[1] + 1.2, top[2])));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const s of sc) { draw(s, tval(s.y, now), tval(s.t, now)); if (!tdone(s.y, now) || !tdone(s.t, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = sc.map((s) => P(X(s.k), L / 2, DZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 20 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    sc.forEach((s, k) => {
      const d = Math.abs(k - a);
      const y = a < 0 ? (k === FAV ? 5 : 0) : d === 0 ? OUT : d === 1 ? 4 : 0;
      const t = a < 0 ? LEAN[k] : d === 0 ? 0 : d === 1 ? LEAN[k] * 0.6 : LEAN[k];
      const delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(s.y, y, now, delay); tset(s.t, t, now, delay);
      const on = k === (a < 0 ? FAV : a);
      s.deck.sil.classList.toggle("hi", on);
      s.stem.classList.toggle("hi", on);
      s.bar.classList.toggle("hi", on);
      ports[k].setAttribute("class", on ? "dot m" : "dot off");
    });
    read.textContent = a < 0 ? "rest" : "scooter " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "escooters",
  means: "Four e-scooters at a charging strip: the one under the pointer rolls out and lifts its stem, its neighbours a little.",
  rules: [1, 2, 5, 8],
  range: [0, 40, 80],
  tour: [[150, 160], [200, 180], [250, 200], null],
  mount,
});

roadsigns.code:
/**
 * Road signs: a street corner, a kerbed pavement round a bend, with four sign
 * posts carrying plain plates of four shapes: a circle, a triangle, a square
 * and an octagon. The pointer is what the corner turns to: every plate turns
 * on its post, on its own spring, to face it, and the nearest is bright. At
 * rest the plates face the road at uneven angles, one bright. The slider is
 * how quickly they follow.
 *
 * The pattern: a continuous aim per part (officechairs); the pick is the
 * plate whose fixed centre on screen is nearest the pointer.
 */
const {
  Cam, fillet, fit, poly, prism, proj, rings, circ, facing, unproj, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const POSTS = [[-30, -6, 44], [-6, -26, 52], [18, -8, 40], [-8, 20, 48]];
const SHAPE = ["circle", "triangle", "square", "octagon"], REST = [40, 70, 20, 55], FAV = 1, PR = 9;
const outline = (s) => {
  const n = s === "circle" ? 24 : s === "triangle" ? 3 : s === "square" ? 4 : 8;
  const off = s === "triangle" ? Math.PI / 2 : s === "square" ? Math.PI / 4 : s === "octagon" ? Math.PI / 8 : 0;
  const R = s === "triangle" ? PR * 1.25 : s === "square" ? PR * 1.15 : PR;
  const pts = [];
  for (let i = 0; i < n; i++) { const a = off + (i / n) * Math.PI * 2; pts.push([R * Math.cos(a), R * Math.sin(a)]); }
  return s === "circle" ? pts : fillet(pts, pts.map(() => 1.2), 3);
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-44, -40, 0], [32, -40, 0], [-44, 34, 0], [32, 34, 0], [-6, -26, 52 + PR + 2], [-30, -6, 44 + PR + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the corner: a pavement slab with a kerb crease, the roads beyond it left open
  const [kr, ki] = rings(-44, -40, 32, 34, 14, 3);
  put(solid(g), prism(P, front, kr, ki, 0, 2.5));

  const signs = POSTS.map(([x, y, h], k) => ({ k, x, y, h, shape: outline(SHAPE[k]), rest: REST[k] * Math.PI / 180 }))
    .sort((a, b) => a.x + a.y - (b.x + b.y));
  for (const s of signs) {
    s.grp = mk("g", {}, g);
    place(flatDot(s.grp, C, 1.6, "dot off"), P(s.x, s.y, 2.5));
    s.post = solid(s.grp);
    put(s.post, prism(P, front, circ(0.9, 12).map((q) => ({ ...q, u: q.u + s.x, v: q.v + s.y })), null, 2.5, s.h + PR * 0.6));
    s.plate = mk("g", {}, s.grp);
    s.far = mk("path", { class: "lo" }, s.plate);
    s.near = mk("path", { class: "sil" }, s.plate);
    s.sp = spring(s.rest, { k: 100 * value, c: 18 * Math.sqrt(value) });
    s.drawn = NaN; s.postFirst = null;
    s.mid = P(s.x, s.y, s.h);
  }
  function draw(s) {
    const a = s.sp.x;
    if (Math.abs(a - s.drawn) < 1e-4) return;
    s.drawn = a;
    const dx = Math.cos(a), dy = Math.sin(a), tx = -dy, ty = dx;
    const face = (o) => poly(s.shape.map(([u, v]) => P(s.x + dx * o + tx * u, s.y + dy * o + ty * u, s.h + v)));
    const facesUs = dx + dy > 0;
    s.far.setAttribute("d", face(facesUs ? 1.2 : 2.4));
    s.near.setAttribute("d", face(facesUs ? 2.4 : 1.2));
    if (facesUs !== s.postFirst) { s.postFirst = facesUs; if (facesUs) s.post.g.after(s.plate); else s.plate.after(s.post.g); }
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const s of signs) { if (stepS(s.sp, dt)) m = true; draw(s); }
    return m;
  });
  bag.add(B.unregister);

  function aim(p) {
    let near = null, bd = Infinity;
    const w = p && unproj(C, p[0], p[1], 30);
    for (const s of signs) {
      if (p) {
        const d = Math.hypot(p[0] - s.mid[0], p[1] - s.mid[1]);
        if (d < bd) { bd = d; near = s; }
        const r = Math.hypot(w[0] - s.x, w[1] - s.y);
        const to = r < 3 ? s.sp.t : Math.atan2(w[1] - s.y, w[0] - s.x);
        s.sp.t = s.sp.t + wrap(to - s.sp.t);
      } else s.sp.t = s.sp.t + wrap(s.rest - s.sp.t);
    }
    if (bd > 60) near = null;
    for (const s of signs) s.near.classList.toggle("hi", p ? s === near : s.k === FAV);
    read.textContent = !p ? "rest" : near ? "sign " + (near.k + 1) : "turn";
    B.wake();
  }
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  for (const s of signs) draw(s);
  return {
    set: (v) => { for (const s of signs) { s.sp.k = 100 * v; s.sp.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "roadsigns",
  means: "Four sign posts on a street corner: every plain plate turns on its post to face the pointer, and the nearest is bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[150, 120], [250, 140], [200, 200], null],
  mount,
});

gears.code:
/**
 * Gears: a train of five meshing spur gears of different sizes on a base
 * plate, each on its axle boss. The pointer's angle around the big gear is
 * where the train turns to: the big gear follows it on a spring and every
 * other gear turns by its ratio, so the small ones spin fast. The gear under
 * the pointer is bright. At rest the train sits part turned, the big gear
 * bright. The slider is the spring's stiffness.
 *
 * The pattern: a continuous aim (one spring, an angle); the hit is on the
 * plate's plane, which never moves, against the gears' fixed centres.
 */
const {
  Cam, circ, facing, fit, open, poly, prism, proj, rings, unproj, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

// teeth, parent, direction from parent (deg); pitch radius = teeth
const SPEC = [[24, -1, 0], [12, 0, -20], [16, 1, 70], [10, 0, 135], [14, 3, 200]];
const Z0 = 4, Z1 = 7, REST = 0.35, FAV = 0;
const gears = [];
for (const [n, par, dir] of SPEC) {
  let cx = 0, cy = 0;
  const th = dir * Math.PI / 180;
  if (par >= 0) { const p = gears[par], d = p.n + n + 0.4; cx = p.cx + d * Math.cos(th); cy = p.cy + d * Math.sin(th); }
  gears.push({ n, par, th, cx, cy, k: gears.length });
}
function phases(a0) {
  const out = [a0];
  for (const g of gears.slice(1)) {
    const p = gears[g.par], pa = out[g.par], r = p.n / g.n;
    out.push(g.th + Math.PI - Math.PI / g.n - r * (pa - g.th));
  }
  return out;
}
function profile(g, a) {
  const pts = [], p = (2 * Math.PI) / g.n, R0 = g.n - 2, R1 = g.n + 1.8;
  for (let i = 0; i < g.n; i++) {
    const b = a + i * p;
    for (const [f, R] of [[-0.27, R0], [-0.13, R1], [0.13, R1], [0.27, R0]]) pts.push([g.cx + R * Math.cos(b + f * p), g.cy + R * Math.sin(b + f * p)]);
  }
  return pts;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.0);
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  for (const g of gears) { x0 = Math.min(x0, g.cx - g.n - 6); y0 = Math.min(y0, g.cy - g.n - 6); x1 = Math.max(x1, g.cx + g.n + 6); y1 = Math.max(y1, g.cy + g.n + 6); }
  fit(C, [[x0, y0, 0], [x1, y1, 0], [x0, y1, 0], [x1, y0, 0], [x0, y0, Z1], [x1, y1, Z1]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(x0, y0, x1, y1, 6, 1.6);
  put(solid(g), prism(P, front, pr, pi, 0, 3));
  const shift = (ring, x, y) => ring.map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

  const order = gears.slice().sort((a, b) => a.cx + a.cy - (b.cx + b.cy));
  for (const gr of order) {
    const grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, shift(circ(4, 24), gr.cx, gr.cy), null, 3, Z0));
    gr.under = mk("path", { class: "lo" }, grp);
    gr.top = mk("path", { class: "sil" }, grp);
    gr.hub = mk("path", { class: "nf lo", d: open(shift(circ(Math.max(4, gr.n * 0.45), 32), gr.cx, gr.cy).map((q) => P(q.u, q.v, Z1)).concat([P(gr.cx + Math.max(4, gr.n * 0.45), gr.cy, Z1)])) }, grp);
    place(flatDot(grp, C, 1.2, "dot m"), P(gr.cx, gr.cy, Z1));
  }

  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    if (Math.abs(sp.x - drawn) < 1e-4) return;
    drawn = sp.x;
    const ph = phases(sp.x);
    for (const gr of gears) {
      const pts = profile(gr, ph[gr.k]);
      gr.under.setAttribute("d", poly(pts.map(([x, y]) => P(x, y, Z0))));
      gr.top.setAttribute("d", poly(pts.map(([x, y]) => P(x, y, Z1))));
    }
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function setPointer(w) {
    let on = -1;
    if (w) {
      const a = Math.atan2(w[1], w[0]);
      sp.t = sp.t + (a - sp.t) - 2 * Math.PI * Math.round((a - sp.t) / (2 * Math.PI));
      for (const gr of gears) if (Math.hypot(w[0] - gr.cx, w[1] - gr.cy) < gr.n + 2) on = gr.k;
    } else sp.t = REST + 2 * Math.PI * Math.round((sp.t - REST) / (2 * Math.PI));
    for (const gr of gears) gr.top.classList.toggle("hi", gr.k === (w ? on : FAV));
    read.textContent = !w ? "rest" : on < 0 ? "turn" : "gear " + (on + 1);
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const w = unproj(C, p[0], p[1], Z1);
      setPointer(w[0] < x0 - 12 || w[0] > x1 + 12 || w[1] < y0 - 12 || w[1] > y1 + 12 ? null : w);
    },
    leave: () => setPointer(null),
  }));
  bag.add(() => svg.replaceChildren());
  setPointer(null);
  draw();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "gears",
  means: "Five meshing spur gears on a plate: the train turns with the pointer's angle round the big gear, each gear by its ratio.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[200, 120], [260, 200], [150, 210], null],
  mount,
});

robotarms.code:
/**
 * Robot arms: two industrial arms in a work cell, each a round base, a turret,
 * an upper arm and a forearm on pinned joints, a wrist and a two-finger
 * gripper, beside a table holding one part. The pointer is where the work is:
 * both arms reach toward it, every joint on its own spring, and the nearer
 * arm's gripper is bright. At rest arm 1 grips the part and arm 2 stands
 * folded. The slider is how quickly the joints follow.
 *
 * The pattern: a continuous aim (springs on joint angles from a two-link
 * reach); the hit is on the floor's plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, poly, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SH = 16, L1 = 34, L2 = 30, WR = 7, TZ = 18;
const BASES = [[-30, 6], [30, -6]], PART = [0, -40];
const FLOOR = [-68, -62, 60, 42];
const REST = [[PART[0], PART[1], TZ + 6 + WR + 7], [44, 20, 40]];
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

/** A round bar from a to b, radius r: the hull of its two end rings. */
function bar(P, a, b, r, n = 14) {
  const d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], L = Math.hypot(...d) || 1, e = d.map((x) => x / L);
  let u = Math.abs(e[2]) < 0.9 ? [e[1], -e[0], 0] : [0, e[2], -e[1]];
  const un = Math.hypot(...u); u = u.map((x) => x / un);
  const v = [e[1] * u[2] - e[2] * u[1], e[2] * u[0] - e[0] * u[2], e[0] * u[1] - e[1] * u[0]];
  const ring = (c) => Array.from({ length: n }, (_, i) => {
    const t = (i / n) * Math.PI * 2, co = Math.cos(t), si = Math.sin(t);
    return P(c[0] + r * (co * u[0] + si * v[0]), c[1] + r * (co * u[1] + si * v[1]), c[2] + r * (co * u[2] + si * v[2]));
  });
  return poly(hull(ring(a).concat(ring(b))));
}

function solve(base, W) {
  const dx = W[0] - base[0], dy = W[1] - base[1], h = Math.hypot(dx, dy), dz = W[2] - SH;
  const D = clamp(Math.hypot(h, dz), 16, L1 + L2 - 1);
  const a = Math.atan2(dz, h) + Math.acos(clamp((L1 * L1 + D * D - L2 * L2) / (2 * L1 * D), -1, 1));
  const e = Math.acos(clamp((L1 * L1 + L2 * L2 - D * D) / (2 * L1 * L2), -1, 1));
  return [Math.atan2(dy, dx), a, a - (Math.PI - e)];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.9);
  const [f0, f1, f2, f3] = FLOOR;
  fit(C, [[f0, f1, -3], [f2, f3, -3], [f2, f1, -3], [f0, f3, -3], ...BASES.map(([x, y]) => [x, y, 58])], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(f0, f1, f2, f3, 6, 2), -3, 0));
  // the table and its part, far side of the cell
  const [tx, ty] = PART;
  for (const [lx, ly] of [[-13, -9], [13, -9], [-13, 9], [13, 9]]) put(solid(g), prism(P, front, circ(1.4, 12).map((q) => ({ ...q, u: q.u + tx + lx, v: q.v + ty + ly })), null, 0, TZ - 2));
  put(solid(g), prism(P, front, ...rings(tx - 16, ty - 12, tx + 16, ty + 12, 3, 1.4), TZ - 2, TZ));
  put(solid(g), prism(P, front, ...rings(tx - 4.5, ty - 4.5, tx + 4.5, ty + 4.5, 1.2, 0.8), TZ, TZ + 6));

  const arms = BASES.map((b, k) => {
    const grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, ...rings(b[0] - 9, b[1] - 9, b[0] + 9, b[1] + 9, 9, 1.6), 0, 4));
    put(solid(grp), prism(P, front, circ(5.5, 24).map((q) => ({ ...q, u: q.u + b[0], v: q.v + b[1] })), null, 4, SH - 3));
    const el = {};
    for (const n of ["sj", "up", "ej", "fo", "wr", "fa", "fb"]) el[n] = mk("path", { class: "sil" }, grp);
    const [y, a, f] = solve(b, REST[k]), o = { k: 100 * value, c: 18 * Math.sqrt(value) };
    return { k, b, el, sy: spring(y, o), sa: spring(a, o), sf: spring(f, o), drawn: "" };
  });

  function draw(arm) {
    const y = arm.sy.x, a = arm.sa.x, f = arm.sf.x, key = [y, a, f].map((x) => x.toFixed(4)).join();
    if (key === arm.drawn) return;
    arm.drawn = key;
    const dir = (p) => [Math.cos(p) * Math.cos(y), Math.cos(p) * Math.sin(y), Math.sin(p)];
    const add = (p, d, s) => p.map((x, i) => x + d[i] * s);
    const S = [arm.b[0], arm.b[1], SH], E = add(S, dir(a), L1), W = add(E, dir(f), L2), G = [W[0], W[1], W[2] - WR];
    const n = [-Math.sin(y), Math.cos(y), 0], { el } = arm;
    el.sj.setAttribute("d", bar(P, add(S, n, -4), add(S, n, 4), 5));
    el.up.setAttribute("d", bar(P, S, E, 3.4));
    el.ej.setAttribute("d", bar(P, add(E, n, -3.4), add(E, n, 3.4), 3.8));
    el.fo.setAttribute("d", bar(P, E, W, 2.6));
    el.wr.setAttribute("d", bar(P, W, G, 2.2));
    el.fa.setAttribute("d", bar(P, add(G, n, -2.6), add(add(G, n, -2), [0, 0, 1], -6), 0.9, 8));
    el.fb.setAttribute("d", bar(P, add(G, n, 2.6), add(add(G, n, 2), [0, 0, 1], -6), 0.9, 8));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const arm of arms) { for (const s of [arm.sy, arm.sa, arm.sf]) if (stepS(s, dt)) m = true; draw(arm); }
    return m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = arms[0];
    if (over) near = arms.reduce((p, q) => (Math.hypot(over[0] - q.b[0], over[1] - q.b[1]) < Math.hypot(over[0] - p.b[0], over[1] - p.b[1]) ? q : p));
    const onTable = over && Math.abs(over[0] - tx) < 18 && Math.abs(over[1] - ty) < 14;
    for (const arm of arms) {
      const W = over ? [over[0], over[1], onTable ? TZ + 22 : 18] : REST[arm.k];
      const [y, a, f] = solve(arm.b, W);
      arm.sy.t = arm.sy.t + wrap(y - arm.sy.t); arm.sa.t = a; arm.sf.t = f;
      const on = arm === near;
      for (const n of ["wr", "fa", "fb"]) arm.el[n].classList.toggle("hi", on);
    }
    read.textContent = over ? "arm " + (near.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      const out = x < f0 - 20 || x > f2 + 20 || y < f1 - 20 || y > f3 + 20;
      over = out ? null : [clamp(x, f0 + 4, f2 - 4), clamp(y, f1 + 4, f3 - 4)];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const arm of arms) for (const s of [arm.sy, arm.sa, arm.sf]) { s.k = 100 * v; s.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "robotarms",
  means: "Two robot arms in a work cell: both reach toward the pointer, joint by joint, and the nearer arm's gripper is bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[240, 201], [190, 150], [160, 225], null],
  mount,
});

valves.code:
/**
 * Valves: a pipe manifold on a plinth, a flanged header on two saddles with
 * four risers, each capped by a valve bonnet, a threaded stem and a spoked
 * hand-wheel. The pointer is the hand on a wheel: the wheel under it turns on
 * a spring and its stem rises, the neighbours turn a little. At rest the
 * wheels sit at uneven turns and stem heights, valve 2 bright. The slider is
 * how quickly the wheels follow.
 *
 * The pattern: a single row picked by world x on the wheels' rest plane,
 * which never moves; springs on each wheel's angle and lift.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, ringAt, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const XS = [-48, -16, 16, 48], HZ = 9, WZ = 30, R = 11, FAV = 1;
const REST_A = [0.3, 1.1, -0.4, 0.7], REST_L = [1, 4, 0, 2], FALL = [1, 0.28, 0.1, 0.04];
const at = (ring, x, y) => ring.map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

/** A round bar from a to b along x, radius r: the hull of its two end rings. */
function xbar(P, x0, x1, y, z, r, n = 20) {
  const ring = (x) => Array.from({ length: n }, (_, i) => { const t = (i / n) * Math.PI * 2; return P(x, y + r * Math.cos(t), z + r * Math.sin(t)); });
  return poly(hull(ring(x0).concat(ring(x1))));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-74, -20, -3], [74, 20, -3], [74, -20, -3], [-74, 20, -3], [-60, -12, WZ + 10], [60, 12, WZ + 10]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(-74, -20, 74, 20, 5, 2), -3, 0));
  for (const x of [-34, 34]) put(solid(g), prism(P, front, ...rings(x - 4, -6, x + 4, 6, 1.6, 0.8), 0, HZ - 3));
  mk("path", { class: "sil", d: xbar(P, -66, 66, 0, HZ, 4.5) }, g);
  for (const x of [-66, 66]) mk("path", { class: "sil", d: xbar(P, x - 1.2 * Math.sign(x), x + 1.2 * Math.sign(x), 0, HZ, 6.5) }, g);

  const o = { k: 100 * value, c: 18 * Math.sqrt(value) };
  const valves = XS.map((x, i) => {
    const grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, at(circ(2.8, 20), x, 0), null, HZ, 18));
    put(solid(grp), prism(P, front, ...rings(x - 6, -6, x + 6, 6, 2.2, 1), 17, 20));
    put(solid(grp), prism(P, front, at(circ(4.2, 24), x, 0), at(circ(3.4, 24), x, 0), 20, 25));
    const stem = mk("path", { class: "sil" }, grp), rim = mk("path", { class: "nf sil" }, grp);
    const inner = mk("path", { class: "nf lo" }, grp), spokes = mk("path", { class: "nf" }, grp), hub = solid(grp);
    return { i, x, stem, rim, inner, spokes, hub, sa: spring(REST_A[i], o), sl: spring(REST_L[i], o), drawn: "" };
  });

  function draw(v) {
    const a = v.sa.x, l = v.sl.x, key = a.toFixed(4) + "," + l.toFixed(3);
    if (key === v.drawn) return;
    v.drawn = key;
    const z = WZ + l, x = v.x;
    v.stem.setAttribute("d", poly(hull(ringAt(P, at(circ(1.1, 12), x, 0), 25).concat(ringAt(P, at(circ(1.1, 12), x, 0), z + 4)))));
    v.rim.setAttribute("d", poly(hull(ringAt(P, at(circ(R, 48), x, 0), z).concat(ringAt(P, at(circ(R, 48), x, 0), z + 1.8)))));
    v.inner.setAttribute("d", poly(ringAt(P, at(circ(R - 1.8, 48), x, 0), z + 1.8)));
    let d = "";
    for (let k = 0; k < 3; k++) {
      const t = a + (k * Math.PI * 2) / 3, c = Math.cos(t), s = Math.sin(t);
      d += seg(P(x + 2 * c, 2 * s, z + 1.2), P(x + (R - 1.6) * c, (R - 1.6) * s, z + 1.2));
    }
    v.spokes.setAttribute("d", d);
    put(v.hub, prism(P, front, at(circ(2.2, 16), x, 0), null, z, z + 2.4));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const v of valves) { if (stepS(v.sa, dt)) m = true; if (stepS(v.sl, dt)) m = true; draw(v); }
    return m;
  });
  bag.add(B.unregister);

  let over = -1;
  function retarget() {
    for (const v of valves) {
      const f = over < 0 ? 0 : FALL[Math.abs(v.i - over)];
      v.sa.t = REST_A[v.i] + f * Math.PI * 1.6;
      v.sl.t = clamp(REST_L[v.i] + f * 7, 0, 10);
      v.rim.classList.toggle("hi", over < 0 ? v.i === FAV : v.i === over);
    }
    read.textContent = over < 0 ? "rest" : "valve " + (over + 1);
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], WZ);
      let k = -1;
      if (Math.abs(y) < 26 && x > -74 && x < 74) {
        let bd = Infinity;
        XS.forEach((xx, i) => { if (Math.abs(x - xx) < bd) { bd = Math.abs(x - xx); k = i; } });
      }
      if (k !== over) { over = k; retarget(); }
    },
    leave: () => { over = -1; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const w of valves) for (const s of [w.sa, w.sl]) { s.k = 100 * v; s.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "valves",
  means: "A pipe manifold with four hand-wheel valves: the wheel under the pointer turns and its stem rises, neighbours turn a little.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[223, 149], [130, 103], [270, 172], null],
  mount,
});

excavator.code:
/**
 * Excavator: a tracked digger beside a dirt mound, two track pods under a
 * turntable, a house with its cab, and a boom, stick and bucket on pins. The
 * pointer is a spot on the ground to dig: the house swings toward it and the
 * boom and stick reach for it, each on its own spring, bucket bright. At rest
 * the bucket sits in the mound. The slider is how quickly the arm follows.
 *
 * The pattern: a continuous aim (springs on swing, boom and stick angles from
 * a two-link reach); the hit is on the ground plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, poly, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PZ = 15, PX = 10, L1 = 36, L2 = 28, DMIN = 24, DMAX = 54, MOUND = [50, -36];
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};

function solve(x, y) {
  const yaw = Math.atan2(y, x), d = clamp(Math.hypot(x, y), DMIN, DMAX), h = d - PX - 6, dz = 6 - PZ;
  const D = clamp(Math.hypot(h, dz), 12, L1 + L2 - 1);
  const a = Math.atan2(dz, h) + Math.acos(clamp((L1 * L1 + D * D - L2 * L2) / (2 * L1 * D), -1, 1));
  const e = Math.acos(clamp((L1 * L1 + L2 * L2 - D * D) / (2 * L1 * L2), -1, 1));
  return [yaw, a, a - (Math.PI - e), d];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.2);
  const ext = [[-24, -18, 0], [24, 18, 0], [-24, 18, 0], [MOUND[0] + 22, MOUND[1] - 22, 0], [0, 0, 56]];
  for (let k = 0; k < 8; k++) { const t = (k / 8) * Math.PI * 2; ext.push([DMAX * Math.cos(t), DMAX * Math.sin(t), 0]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const foot = circ(24, 40).map((q) => ({ ...q, u: q.u + MOUND[0], v: q.v + MOUND[1] }));
  const top = circ(9, 32).map((q) => ({ ...q, u: q.u + MOUND[0] - 2, v: q.v + MOUND[1] + 2 }));
  const ms = solid(g);
  ms.sil.setAttribute("d", poly(hull(foot.map((q) => P(q.u, q.v, 0)).concat(top.map((q) => P(q.u, q.v, 9))))));
  ms.cr.setAttribute("d", poly(top.map((q) => P(q.u, q.v, 9))));
  for (const y0 of [-17, 7]) put(solid(g), prism(P, front, ...rings(-24, y0, 24, y0 + 10, 5, 1.4), 0, 8));
  put(solid(g), prism(P, front, circ(10, 32), circ(8.8, 32), 8, 10));
  const house = mk("g", {}, g), arm = mk("g", {}, g);
  const body = solid(house), cab = solid(house);
  const el = {};
  for (const n of ["boom", "stick", "bucket", "pin"]) el[n] = mk("path", { class: n === "bucket" ? "sil hi" : "sil" }, arm);
  const BODY = rings(-15, -13, 15, 13, 4, 1.4), CAB = rings(-4, -13, 11, -1, 2.6, 1.2);
  const [y0, a0, f0] = solve(MOUND[0] - 6, MOUND[1] + 6), o = { k: 100 * value, c: 18 * Math.sqrt(value) };
  const sy = spring(y0, o), sa = spring(a0, o), sf = spring(f0, o);
  let drawn = "", armFront = null;

  function bar(a, b, r, n = 14) {
    const d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], L = Math.hypot(...d) || 1, e = d.map((x) => x / L);
    let u = [e[1], -e[0], 0]; const un = Math.hypot(...u) || 1; u = u.map((x) => x / un);
    const v = [e[1] * u[2] - e[2] * u[1], e[2] * u[0] - e[0] * u[2], e[0] * u[1] - e[1] * u[0]];
    const ring = (c) => Array.from({ length: n }, (_, i) => {
      const t = (i / n) * Math.PI * 2, co = Math.cos(t), si = Math.sin(t);
      return P(c[0] + r * (co * u[0] + si * v[0]), c[1] + r * (co * u[1] + si * v[1]), c[2] + r * (co * u[2] + si * v[2]));
    });
    return poly(hull(ring(a).concat(ring(b))));
  }

  function draw() {
    const y = sy.x, a = sa.x, f = sf.x, key = [y, a, f].map((x) => x.toFixed(4)).join();
    if (key === drawn) return;
    drawn = key;
    put(body, prism(P, front, turn(BODY[0], y), turn(BODY[1], y), 10, 18));
    put(cab, prism(P, front, turn(CAB[0], y), turn(CAB[1], y), 18, 31));
    const c = Math.cos(y), s = Math.sin(y), dir = (p) => [Math.cos(p) * c, Math.cos(p) * s, Math.sin(p)];
    const add = (p, d, k) => p.map((x, i) => x + d[i] * k), n = [-s, c, 0];
    const S = [PX * c + 4 * -s, PX * s + 4 * c, PZ], E = add(S, dir(a), L1), W = add(E, dir(f), L2);
    el.pin.setAttribute("d", bar(add(S, n, -4), add(S, n, 4), 3.4));
    el.boom.setAttribute("d", bar(S, E, 3));
    el.stick.setAttribute("d", bar(E, W, 2.2));
    const fw = [c, s, 0], pts = [[0, 0], [6, -2], [7, -8], [1, -10], [-3, -5]], ring = [];
    for (const w of [-4, 4]) for (const [hh, zz] of pts) ring.push(P(...add(add(add(W, fw, hh), n, w), [0, 0, 1], zz)));
    el.bucket.setAttribute("d", poly(hull(ring)));
    const af = c + s > -0.2;
    if (af !== armFront) { armFront = af; if (af) house.after(arm); else arm.after(house); }
  }

  const B = register(stage, (dt) => { const m = [sy, sa, sf].map((x) => stepS(x, dt)).some(Boolean); draw(); return m; });
  bag.add(B.unregister);

  function aim(p) {
    const [y, a, f, d] = p ? solve(p[0], p[1]) : solve(MOUND[0] - 6, MOUND[1] + 6);
    sy.t = sy.t + wrap(y - sy.t); sa.t = a; sf.t = f;
    read.textContent = p ? "reach " + Math.round(((d - DMIN) / (DMAX - DMIN)) * 100) + "%" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (q) => {
      const [x, y] = unproj(C, q[0], q[1], 0), r = Math.hypot(x, y);
      aim(r > DMAX + 28 || r < 6 ? null : [x, y]);
    },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return {
    set: (v) => { for (const s of [sy, sa, sf]) { s.k = 100 * v; s.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "excavator",
  means: "A tracked excavator beside a dirt mound: it swings and reaches its boom and stick toward the pointer's spot on the ground.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[96, 221], [112, 135], [158, 246], null],
  mount,
});

flowerbeds.code:
/**
 * Flower beds: a raised garden bed of planks holding three rows of five
 * tulips, each a stem with two leaves and a cup bloom. The pointer is the
 * sun over the bed: tulips near it grow taller and open their blooms, each on
 * its own spring, falling off with distance, and the one under it grows
 * tallest and is bright. At rest the tulips stand at uneven heights, one
 * bright. The slider is the reach of the field.
 *
 * The pattern: a field (terrain); the hit is on the bed's soil plane, which
 * never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, ringAt, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const COLS = 5, ROWS = 3, SP = 22, BH = 12, GROW = 20, FAV = [1, 2];
const W = COLS * SP, D = ROWS * SP;
const H0 = [[22, 27, 24, 30, 21], [26, 23, 31, 25, 28], [24, 29, 22, 26, 23]];
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-3, -3, 0], [W + 3, D + 3, 0], [W + 3, -3, 0], [-3, D + 3, 0], [SP / 2, SP / 2, BH + 31 + GROW + 9], [W - SP / 2, SP / 2, BH + 31 + GROW + 9]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-3, -3, W + 3, D + 3, 3, 2.4);
  put(solid(g), prism(P, front, br, bi, 0, BH));
  // a plank seam along the two near walls
  mk("path", { class: "nf lo", d: open([P(-3, D + 3, BH / 2), P(W + 3, D + 3, BH / 2), P(W + 3, -3, BH / 2)]) }, g);

  const tulips = [];
  for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) {
    const x = SP / 2 + c * SP + (r % 2 ? 2 : -2), y = SP / 2 + r * SP, fav = r === FAV[0] - 1 && c === FAV[1] - 1;
    tulips.push({ r, c, x, y, h0: H0[r][c], sp: spring(fav ? 0.45 : 0), last: NaN });
  }
  tulips.sort((p, q) => p.x + p.y - (q.x + q.y));
  for (const t of tulips) {
    t.grp = mk("g", {}, g);
    const dir = (t.c + t.r) % 2 ? 1 : -1, z = BH;
    const leaf = (s, len, up) => poly([P(t.x, t.y, z), P(t.x + s * 2.4, t.y + s * 1.2, z + up * 0.45), P(t.x + s * len, t.y + s * 0.4, z + up), P(t.x + s * 0.8, t.y, z + up * 0.5)]);
    mk("path", { d: leaf(dir, 6.5, 13), class: "nf" }, t.grp);
    mk("path", { d: leaf(-dir, 5, 10), class: "nf" }, t.grp);
    t.stem = mk("path", { class: "nf" }, t.grp);
    t.bloom = solid(t.grp);
  }

  function draw(t) {
    const a = t.sp.x;
    if (Math.abs(a - t.last) < 1e-4) return;
    t.last = a;
    const top = BH + t.h0 + GROW * a, ro = 3.4 + 2.4 * a;
    t.stem.setAttribute("d", open([P(t.x, t.y, BH), P(t.x, t.y, top)]));
    const pts = ringAt(P, disc(t.x, t.y, 1.4), top).concat(ringAt(P, disc(t.x, t.y, 3.6), top + 3.5), ringAt(P, disc(t.x, t.y, ro), top + 8 + a));
    put(t.bloom, { sil: poly(hull(pts)), crease: poly(ringAt(P, disc(t.x, t.y, ro - 0.8, 24), top + 7.6 + a)) });
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const t of tulips) { if (stepS(t.sp, dt)) m = true; draw(t); }
    return m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = null, bd = Infinity;
    if (over) for (const t of tulips) { const d = Math.hypot(over[0] - t.x, over[1] - t.y); if (d < bd) { bd = d; near = t; } }
    if (bd > SP * 0.75) near = null;
    for (const t of tulips) {
      const fav = t.r === FAV[0] - 1 && t.c === FAV[1] - 1;
      if (over) {
        const d = Math.hypot(over[0] - t.x, over[1] - t.y), f = Math.exp(-(d * d) / (2 * reach * reach));
        t.sp.t = t === near ? 1 : clamp(0.08 + 0.72 * f, 0, 0.8);
      } else t.sp.t = fav ? 0.45 : 0;
      t.bloom.sil.classList.toggle("hi", near ? t === near : !over && fav);
    }
    read.textContent = near ? "tulip " + (near.r + 1) + "·" + (near.c + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], BH);
      over = x < -SP || y < -SP || x > W + SP || y > D + SP ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "flowerbeds",
  means: "A raised bed of tulips: tulips near the pointer grow and open their blooms, and the one under it grows tallest.",
  rules: [1, 3, 5, 8],
  range: [10, 20, 34],
  tour: [[172, 146], [203, 200], [236, 236], null],
  mount,
});

compostbins.code:
/**
 * Compost bins: three slatted bins in a row, each with a lid hinged at its
 * back edge and a grip near the front, and a garden fork leaning on the last
 * one. The pointer picks a bin by where it stands: its lid swings up on the
 * hinge, and the lids beside it lift a little, staggered from it. At rest one
 * lid stands ajar, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the pick is the bin
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, facing, fit, hull, open, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, BW = 34, BD = 34, BH = 30, GAP = 7, LT = 2.4, OV = 1.6, FAV = 1;
const OPEN = 64, AJAR = 20, NB = 16;
const X1 = N * BW + (N - 1) * GAP;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  const tallest = BH + (BD + OV) * Math.sin((OPEN * Math.PI) / 180) + 4;
  fit(C, [[0, 0, 0], [X1 + 16, BD, 0], [X1 + 16, 0, 0], [0, BD, 0], [0, -OV, tallest], [X1, -OV, tallest]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const bins = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * (BW + GAP), x1 = x0 + BW, grp = mk("g", {}, g);
    const [r, i] = rings(x0, 0, x1, BD, 3, 1.8);
    put(solid(grp), prism(P, front, r, i, 0, BH));
    // the slats: a gap line round the two near faces every few units
    let d = "";
    for (let z = 6; z < BH - 2; z += 6) d += open([P(x0 + 2, BD, z), P(x1, BD, z), P(x1, 2, z)]);
    mk("path", { class: "nf lo", d }, grp);
    const lid = solid(grp), grip = mk("path", { class: "nf" }, grp);
    const a0 = k === FAV ? AJAR : k === 2 ? 4 : 0;
    bins.push({ k, x0, x1, lid, grip, a: tween(a0), a0, ring: rrect(x0 - OV, 0, x1 + OV, BD + 2 * OV, 3, 4), last: NaN });
  }

  // the garden fork, leaning on the last bin's end
  const fx = X1 + 9, top = [X1 + 1.5, BD * 0.45, BH + 14], foot = [fx, BD * 0.55, 8];
  let fork = seg(P(...top), P(...foot));
  fork += poly([P(top[0], top[1] - 3, top[2] + 6), P(top[0], top[1] + 3, top[2] + 6), P(top[0], top[1] + 2, top[2]), P(top[0], top[1] - 2, top[2])]);
  fork += seg(P(fx, BD * 0.55 - 4.5, 8), P(fx, BD * 0.55 + 4.5, 8));
  for (let t = 0; t < 4; t++) { const y = BD * 0.55 - 4.5 + t * 3; fork += seg(P(fx, y, 8), P(fx + 1.2, y, 0)); }
  mk("path", { class: "nf sil", d: fork }, g);

  // a point of the lid, hinged at its back edge (y = -OV), tilted a degrees, w above its underside
  const lidPt = (q, a, w) => {
    const v = q.v + OV, s = Math.sin(a), c = Math.cos(a);
    return P(q.u, -OV + v * c - w * s, BH + v * s + w * c);
  };
  function draw(b, deg) {
    if (Math.abs(deg - b.last) < 1e-3) return;
    b.last = deg;
    const a = (deg * Math.PI) / 180, lo = b.ring.map((q) => lidPt(q, a, 0)), hiR = b.ring.map((q) => lidPt(q, a, LT));
    const inner = rrect(b.x0 - OV + 1.4, 1.4, b.x1 + OV - 1.4, BD + 2 * OV - 1.4, 2, 4).map((q) => lidPt(q, a, a > 0.68 ? 0 : LT));
    put(b.lid, { sil: poly(hull(lo.concat(hiR))), crease: poly(inner) });
    const m = (b.x0 + b.x1) / 2;
    b.grip.setAttribute("d", open([lidPt({ u: m - 6, v: BD - 3 }, a, LT), lidPt({ u: m - 5, v: BD - 3 }, a, LT + 2), lidPt({ u: m + 5, v: BD - 3 }, a, LT + 2), lidPt({ u: m + 6, v: BD - 3 }, a, LT)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of bins) { draw(b, tval(b.a, now)); if (!tdone(b.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = bins.map((b) => P((b.x0 + b.x1) / 2, BD / 2, BH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 44 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    bins.forEach((b, k) => {
      const dd = Math.abs(k - a), deg = a < 0 ? b.a0 : dd === 0 ? OPEN : dd === 1 ? NB : 0;
      tset(b.a, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      b.lid.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bin " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "compostbins",
  means: "Three slatted compost bins: the lid of the bin under the pointer swings up, and its neighbours lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[131, 167], [189, 196], [247, 225], null],
  mount,
});

gardengate.code:
/**
 * Garden gate: a picket fence on two rails, broken by a gate between two
 * capped posts, with a path of stepping stones leading through it toward the
 * reader. The gate is a frame of two rails, a brace and four pickets, hinged
 * on the left post. As the pointer nears it the gate swings open toward the
 * reader on a spring, and the gate is bright while it stands open. At rest it
 * hangs ajar, bright. The slider is how far off the gate starts to open.
 *
 * The pattern: a continuous aim (terrain's spring, on one angle); the hit is
 * on the ground plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fillet, fit, poly, prism, proj, rings, ringAt, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 136, G0 = 52, G1 = 84, GW = G1 - G0 - 1, PH = 46, FH = 34, AJAR = 18, MAX = 90;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v * 0.7 + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[0, -3, 0], [L, -3, 0], [0, 0, FH + 3], [L, 0, FH + 3], [G0, -3, PH + 3], [G1 + 4, 0, PH + 3], [G0, GW + 2, 0], [G0 + 20, 60, 0], [G0, GW, FH + 3]], 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const flat = (pts, cls) => mk("path", { d: poly(fillet(pts, pts.map(() => 0.7), 3)), class: cls || "" }, g);

  // the path: stepping stones from the gate toward the reader
  [[68, 9, 6], [70, 23, 6.5], [67, 37, 6], [71, 51, 5.5]].forEach(([x, y, r]) => mk("path", { d: poly(ringAt(P, disc(x, y, r), 0)) }, g));

  // the fence: two rails behind, pickets on their face
  for (const [a, b] of [[0, G0 - 4], [G1 + 4, L]]) {
    for (const z of [9, 25]) flat([P(a, -1.5, z), P(b, -1.5, z), P(b, -1.5, z + 3), P(a, -1.5, z + 3)]);
    for (let x = a + 1; x + 4 <= b; x += 7) {
      const h = FH - Math.abs(x + 2 - (a + b) / 2) * 0.06;
      flat([P(x, 0, 2), P(x + 4, 0, 2), P(x + 4, 0, h), P(x + 2, 0, h + 3), P(x, 0, h)]);
    }
  }
  for (const x of [G0 - 4, G1]) {
    const [r, i] = rings(x, -2, x + 4, 2, 1, 0.6);
    put(solid(g), prism(P, front, r, i, 0, PH));
    const [cr, ci] = rings(x - 0.8, -2.8, x + 4.8, 2.8, 1.2, 0.7);
    put(solid(g), prism(P, front, cr, ci, PH, PH + 2.5));
  }

  // the gate, hinged on the left post: pieces in its own (s along, z up) plane
  const pieces = [
    [[0, 8], [GW, 8], [GW, 11], [0, 11]],
    [[0, 25], [GW, 25], [GW, 28], [0, 28]],
    [[1, 10], [3.5, 10], [GW - 1, 25], [GW - 3.5, 25]],
  ];
  for (let k = 0; k < 4; k++) { const s = 2 + k * 7.6, h = FH - 1 + (k === 1 || k === 2 ? 1.5 : 0); pieces.push([[s, 3], [s + 4, 3], [s + 4, h], [s + 2, h + 3], [s, h]]); }
  const gate = mk("g", {}, svg), els = pieces.map(() => mk("path", { class: "sil" }, gate));
  const sp = spring(AJAR);
  let last = NaN;
  function draw() {
    if (Math.abs(sp.x - last) < 1e-3) return;
    last = sp.x;
    const a = (sp.x * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a);
    // pieces nearer the reader are painted last: when open, the far side of the gate is its face
    pieces.forEach((pc, k) => els[k].setAttribute("d", poly(fillet(pc.map(([u, z]) => P(G0 + 0.5 + u * c, 0.5 + u * s, z)), pc.map(() => 0.7), 3))));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    if (over) {
      const d = Math.hypot(over[0] - (G0 + G1) / 2, over[1] - 6);
      sp.t = MAX * clamp(1 - (d - 14) / reach, 0, 1);
    } else sp.t = AJAR;
    const on = sp.t >= 10;
    for (const el of els) el.classList.toggle("hi", on);
    read.textContent = over ? "gate " + Math.round(sp.t / 5) * 5 + "°" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      over = x < -10 || x > L + 10 || y < -40 || y > 70 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "gardengate",
  means: "A picket fence with a garden gate: the gate swings open toward the reader as the pointer nears it, bright while open.",
  rules: [1, 3, 5, 8],
  range: [30, 55, 90],
  tour: [[118, 168], [184, 209], [262, 236], null],
  mount,
});

birdfeeders.code:
/**
 * Bird feeders: a feeder pole on a ground plate with three arms at three
 * heights, each holding a feeder on a short cord: a seed tube, a little
 * house with a pitched roof, a hanging tray. Feeders near the pointer swing
 * away from it, each on its own spring, and the one under it swings most and
 * is bright. At rest one feeder hangs a little askew, bright. The slider is
 * how far the feeders swing.
 *
 * The pattern: a field of springs; the hit is each feeder's rest pose on
 * screen, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PH = 92, AR = 30, FAV = 1;
const ARMS = [[200, 84, "tube"], [-20, 72, "house"], [90, 60, "tray"]];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.4);
  const ext = [[-12, -12, 0], [12, 12, 0], [12, -12, 0], [-12, 12, 0], [0, 0, PH + 4]];
  for (const [deg, z] of ARMS) { const a = (deg * Math.PI) / 180; for (const s of [-1, 1]) ext.push([AR * Math.cos(a) + 13 * s, AR * Math.sin(a) + 13 * s, z - 26], [AR * Math.cos(a) - 13 * s, AR * Math.sin(a) + 13 * s, z]); }
  fit(C, ext, 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const fs = ARMS.map(([deg, z, kind], k) => {
    const a = (deg * Math.PI) / 180, x = AR * Math.cos(a), y = AR * Math.sin(a);
    return { k, kind, x, y, z, ox: spring(k === FAV ? 3 : 0), oy: spring(k === FAV ? -2 : 0), last: "" };
  });
  const draws = [...fs, null].sort((p, q) => (p ? p.x + p.y : 0) - (q ? q.x + q.y : 0));
  for (const f of draws) {
    if (!f) {
      const [pr, pi] = rings(-9, -9, 9, 9, 3, 1.4);
      put(solid(g), prism(P, front, pr, pi, 0, 2));
      put(solid(g), prism(P, front, circ(2, 20), null, 2, PH));
      put(solid(g), prism(P, front, circ(3.2, 20), circ(2.4, 20), PH, PH + 3));
      continue;
    }
    f.grp = mk("g", {}, g);
    mk("path", { class: "nf sil", d: open([P(0, 0, f.z + 4), P(f.x * 0.5, f.y * 0.5, f.z + 1), P(f.x, f.y, f.z)]) }, f.grp);
    f.cord = mk("path", { class: "nf" }, f.grp);
    f.body = solid(f.grp);
    f.parts = [solid(f.grp), solid(f.grp)];
    f.mark = mk("path", { class: "nf lo" }, f.grp);
  }

  function draw(f) {
    const ox = f.ox.x, oy = f.oy.x, key = ox.toFixed(3) + "," + oy.toFixed(3);
    if (key === f.last) return;
    f.last = key;
    const cx = f.x + ox, cy = f.y + oy, lift = (ox * ox + oy * oy) / 60, top = f.z - 6 + lift, D = (r) => disc(cx, cy, r);
    const hang = P(f.x, f.y, f.z);
    if (f.kind === "tube") {
      f.cord.setAttribute("d", seg(hang, P(cx, cy, top)));
      put(f.parts[0], prism(P, front, D(6), D(5), top - 3, top));
      put(f.body, prism(P, front, D(4.4), null, top - 22, top - 3));
      put(f.parts[1], prism(P, front, D(6.4), D(5.4), top - 25, top - 22));
      f.mark.setAttribute("d", seg(P(cx - 7, cy + 7, top - 18), P(cx + 7, cy - 7, top - 18)) + seg(P(cx - 3, cy + 3, top - 10), P(cx + 3, cy - 3, top - 10)));
    } else if (f.kind === "house") {
      f.cord.setAttribute("d", seg(hang, P(cx, cy, top)));
      const [r, i] = rings(cx - 6, cy - 6, cx + 6, cy + 6, 1.5, 1);
      put(f.parts[0], prism(P, front, r, i, top - 22, top - 20));
      put(f.body, prism(P, front, rings(cx - 5, cy - 5, cx + 5, cy + 5, 1.2, 0.8)[0], null, top - 20, top - 9));
      const eave = [P(cx - 8, cy - 8, top - 9), P(cx + 8, cy - 8, top - 9), P(cx + 8, cy + 8, top - 9), P(cx - 8, cy + 8, top - 9)];
      put(f.parts[1], { sil: poly(hull(eave.concat([P(cx - 8, cy, top), P(cx + 8, cy, top)]))), crease: open([P(cx - 7, cy, top - 0.6), P(cx + 7, cy, top - 0.6)]) });
      const hole = [];
      for (let j = 0; j < 14; j++) hole.push(P(cx + 5.05, cy + 2 * Math.cos((j / 14) * 6.283), top - 14.5 + 2 * Math.sin((j / 14) * 6.283)));
      f.mark.setAttribute("d", poly(hole));
    } else {
      let d = "";
      for (const [sx, sy] of [[-9, -9], [9, -9], [9, 9], [-9, 9]]) d += seg(P(cx, cy, top), P(cx + sx, cy + sy, top - 14));
      f.cord.setAttribute("d", seg(hang, P(cx, cy, top)) + d);
      const [r, i] = rings(cx - 11, cy - 11, cx + 11, cy + 11, 3, 1.4);
      put(f.body, prism(P, front, r, i, top - 17, top - 14));
      put(f.parts[0], { sil: "", crease: "" });
      put(f.parts[1], { sil: "", crease: "" });
      f.mark.setAttribute("d", seg(P(cx - 4, cy - 2, top - 14), P(cx - 2, cy - 2, top - 14)) + seg(P(cx + 2, cy + 3, top - 14), P(cx + 4, cy + 3, top - 14)));
    }
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const f of fs) { if (stepS(f.ox, dt)) m = true; if (stepS(f.oy, dt)) m = true; draw(f); }
    return m;
  });
  bag.add(B.unregister);

  const mids = fs.map((f) => P(f.x, f.y, f.z - 18));
  let over = null;
  function retarget() {
    let near = null, bd = Infinity;
    if (over) fs.forEach((f, k) => { const d = Math.hypot(over[0] - mids[k][0], over[1] - mids[k][1]); if (d < bd) { bd = d; near = f; } });
    if (bd > 34) near = null;
    fs.forEach((f, k) => {
      if (over) {
        const d = Math.hypot(over[0] - mids[k][0], over[1] - mids[k][1]), w = f === near ? 1 : clamp(0.1 + 0.6 * Math.exp(-(d * d) / 5000), 0, 0.7);
        const [px, py] = unproj(C, over[0], over[1], f.z - 18);
        let dx = f.x - px, dy = f.y - py; const n = Math.hypot(dx, dy) || 1;
        f.ox.t = (dx / n) * 10 * amp * w; f.oy.t = (dy / n) * 10 * amp * w;
      } else { f.ox.t = k === FAV ? 3 : 0; f.oy.t = k === FAV ? -2 : 0; }
      (f.kind === "house" ? f.parts[1] : f.body).sil.classList.toggle("hi", near ? f === near : !over && k === FAV);
    });
    read.textContent = near ? "feeder " + (near.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, { move: (p) => { over = p; retarget(); }, leave: () => { over = null; retarget(); } }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { amp = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "birdfeeders",
  means: "A feeder pole with three hanging bird feeders: feeders near the pointer swing away from it, the one under it most.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.4],
  tour: [[162, 88], [257, 160], [142, 196], null],
  mount,
});

fishingrods.code:
/**
 * Fishing rods: a stand on a lakeside bank holding four rods in tubes, each
 * with a reel under its butt and a line running down to a float on the
 * water. The pointer is the bite: each rod bends toward it on its own
 * springs, the one under it bends most and is bright. At rest the rods lean
 * a little apart, one bent, bright. The slider is how far the pull reaches.
 *
 * The pattern: a continuous aim (springs per rod); the pick is the rod whose
 * resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, circ, clamp, facing, fit, open, poly, prism, proj, rings, ringAt, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 22, X0 = 12, BY = 6, BZ = 9, L = 72, FAV = 1;
const X1 = 2 * X0 + (N - 1) * STEP;
const LAT0 = [-0.06, 0.03, -0.02, 0.07], DIP0 = [0.1, 0.45, 0.16, 0.05];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const rodPt = (x, lat, dip, t) => [x + lat * L * t * t, BY + 0.42 * L * t + dip * 14 * t * t, BZ + 0.86 * L * t - dip * 26 * t * t];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value, last = null;
  const C = Cam(45, 0.5, 2.15);
  const ext = [[-6, -8, -3], [X1 + 6, 24, -3], [X1 + 6, -8, -3], [-6, 24, -3]];
  for (const x of [X0, X1 - X0]) for (const [lat, dip] of [[-0.25, 1], [0.25, 1], [0, 0]]) { const p = rodPt(x, lat, dip, 1); ext.push(p, [p[0] + 4, p[1] + 20, 0]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-6, -8, X1 + 6, 24, 6, 2);
  put(solid(g), prism(P, front, br, bi, -3, 0));
  const water = mk("g", {}, g);
  const [sr, si] = rings(0, 0, X1, 12, 2.5, 1);
  put(solid(g), prism(P, front, sr, si, 0, 4));

  const rods = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP, grp = mk("g", {}, g);
    const ripple = mk("path", { class: "nf lo" }, water), line = mk("path", { class: "nf lo" }, water);
    const flo = flatDot(water, C, 1.3, "dot off");
    put(solid(grp), prism(P, front, disc(x, BY, 2.4, 20), disc(x, BY, 1.5, 20), 4, BZ + 3));
    const rod = mk("path", { class: "nf sil" }, grp), reel = solid(grp);
    rods.push({ k, x, ripple, line, flo, rod, reel, lat: spring(LAT0[k]), dip: spring(DIP0[k]), drawn: "" });
  }
  const mids = rods.map((r) => P(...rodPt(r.x, LAT0[r.k], DIP0[r.k], 0.5)));

  function draw(r) {
    const key = r.lat.x.toFixed(4) + "," + r.dip.x.toFixed(4);
    if (key === r.drawn) return;
    r.drawn = key;
    const pts = [];
    for (let i = 0; i <= 14; i++) pts.push(P(...rodPt(r.x, r.lat.x, r.dip.x, 0.06 + (i / 14) * 0.94)));
    r.rod.setAttribute("d", open(pts));
    const [rx, ry, rz] = rodPt(r.x, r.lat.x, r.dip.x, 0.17);
    const [rr, ri] = rings(rx - 1.3, ry - 2.8, rx + 1.3, ry + 2.8, 1.2, 0.5);
    put(r.reel, prism(P, front, rr, ri, rz - 6, rz - 1));
    const tip = rodPt(r.x, r.lat.x, r.dip.x, 1), fx = tip[0] + 2, fy = tip[1] + 16 - r.dip.x * 4;
    r.line.setAttribute("d", open([P(...tip), P(fx, fy, 0)]));
    r.ripple.setAttribute("d", poly(ringAt(P, disc(fx, fy, 3.5 + r.dip.x * 2), 0)));
    place(r.flo, P(fx, fy, 0));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const r of rods) { if (stepS(r.lat, dt)) m = true; if (stepS(r.dip, dt)) m = true; draw(r); }
    return m;
  });
  bag.add(B.unregister);

  function retarget(p) {
    last = p;
    let near = -1, bd = Infinity;
    if (p) mids.forEach((m, k) => { const d = Math.abs(m[0] - p[0]); if (d < bd) { bd = d; near = k; } });
    if (near >= 0 && bd > 34) near = -1;
    for (const r of rods) {
      if (near < 0) { r.lat.t = LAT0[r.k]; r.dip.t = DIP0[r.k]; continue; }
      const d = p[0] - mids[r.k][0], f = Math.max(Math.exp(-((d / reach) ** 2)), 0.06);
      r.lat.t = clamp(d / reach, -1, 1) * 0.24 * f;
      r.dip.t = f;
    }
    rods.forEach((r) => r.rod.classList.toggle("hi", r.k === (near < 0 ? FAV : near)));
    read.textContent = near < 0 ? "rest" : "rod " + (near + 1);
    B.wake();
  }
  retarget(null);
  bag.add(pointer(stage, { move: (p) => retarget(p), leave: () => retarget(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; retarget(last); }, destroy: bag.dispose };
}

hairline({
  name: "fishingrods",
  means: "Four fishing rods on a lakeside stand: the rods bend toward the pointer, the one under it most.",
  rules: [1, 3, 5, 8],
  range: [20, 40, 70],
  tour: [[155, 103], [188, 120], [255, 154], null],
  mount,
});

hammocks.code:
/**
 * Hammocks: two hammocks slung between three posts on a deck, each hung from
 * a fan of strings at both ends, sagging in the middle. The pointer picks a
 * hammock by where it hangs: it swings toward the reader, and the other
 * swings a little after it. At rest one hammock is swung out, bright. The
 * slider is how far the chosen one swings.
 *
 * The pattern: one of many in a single row (riffle); the pick is the hammock
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SPAN = 64, H = 31, PH = 38, SAG = 15, WID = 8, END = 7, FAV = 0, REST = [6, -5];
const PX = [0, SPAN, 2 * SPAN];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 1.8);
  fit(C, [[-14, -24, -4], [2 * SPAN + 14, 28, -4], [2 * SPAN + 14, -24, -4], [-14, 28, -4], [0, 0, PH], [2 * SPAN, 0, PH]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [dr, di] = rings(-14, -24, 2 * SPAN + 14, 28, 5, 2);
  put(solid(g), prism(P, front, dr, di, -4, 0));
  mk("path", { class: "nf lo", d: [-14, -5, 4, 13, 22].map((y) => seg(P(-12, y, 0), P(2 * SPAN + 12, y, 0))).join("") }, g);
  const post = (x) => { const [r, i] = rings(x - 2.6, -2.6, x + 2.6, 2.6, 1.2, 0.6); put(solid(g), prism(P, front, r, i, 0, PH)); };

  const hams = [];
  for (let k = 0; k < 2; k++) {
    post(PX[k]);
    const grp = mk("g", {}, g);
    const strings = mk("path", { class: "nf" }, grp), cloth = mk("path", { class: "sil" }, grp), mid = mk("path", { class: "nf lo" }, grp);
    hams.push({ k, a: PX[k], strings, cloth, mid, th: tween(REST[k]), last: NaN });
  }
  post(PX[2]);

  function pt(h, s, w, th) {
    const p = Math.sin(Math.PI * s), d = SAG * Math.pow(p, 0.8), ww = WID * Math.pow(p, 0.5) * w;
    const c = Math.cos(rad(th)), sn = Math.sin(rad(th));
    return P(h.a + END + s * (SPAN - 2 * END), ww * c + d * sn, H - d * c + ww * sn);
  }
  function draw(h, th) {
    if (th === h.last) return;
    h.last = th;
    const near = [], far = [], ctr = [];
    for (let i = 0; i <= 20; i++) { const s = 0.04 + (i / 20) * 0.92; near.push(pt(h, s, 1, th)); far.push(pt(h, s, -1, th)); ctr.push(pt(h, s, 0, th)); }
    h.cloth.setAttribute("d", poly(near.concat(far.reverse())));
    h.mid.setAttribute("d", open(ctr));
    let d = "";
    for (const [x, s] of [[h.a + 2.4, 0.04], [h.a + SPAN - 2.4, 0.96]]) for (const w of [-1, 0, 1]) d += seg(P(x, 0, H + 1.5), pt(h, s, w, th));
    h.strings.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let m = false;
    for (const h of hams) { draw(h, tval(h.th, now)); if (!tdone(h.th, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  const mids = hams.map((h) => P(h.a + SPAN / 2, 0, H - SAG / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 60 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a, force) {
    if (a === act && !force) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    hams.forEach((h, k) => {
      const th = a < 0 ? REST[k] : k === a ? swing : swing * 0.3;
      tset(h.th, th, now, from < 0 ? 0 : Math.abs(k - from) * 60);
      h.cloth.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "hammock " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; setActive(act, true); }, destroy: bag.dispose };
}

hairline({
  name: "hammocks",
  means: "Two hammocks slung between three posts on a deck: the one under the pointer swings toward you, the other a little.",
  rules: [1, 2, 5, 8],
  range: [25, 40, 55],
  tour: [[162, 130], [243, 170], [190, 140], null],
  mount,
});

backpacks.code:
/**
 * Backpacks: a wall rack with a rail of pegs and four hiking packs of
 * different sizes hung on them by their haul loops, each with a top pocket
 * and straps down its front, one with a sleeping mat rolled under it. The
 * pointer picks a pack by where it hangs: it lifts off its peg and tilts,
 * and the packs beside it stir a little, staggered from it. At rest one pack
 * is half lifted, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the pick is the pack
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = [22, 17, 26, 15], HH = [34, 27, 40, 23], GAP = 7, D = 12, PEG = 56, LIFT = 9, FWD = 5, FAV = 2, MAT = 2;
const TILT = [-9, 8, -7, 10], REST = [0.06, 0, 0.45, 0.12];
const xs = []; { let x = 6; for (const w of W) { xs.push(x); x += w + GAP; } }
const X1 = xs[3] + W[3] + 6, ZT = PEG - 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[-2, -4, 0], [X1 + 2, -4, 0], [X1 + 2, D + FWD + 4, 2], [-2, D + FWD + 4, 2], [-2, -4, PEG + 14], [X1 + 2, -4, PEG + 14], [X1 / 2, D + FWD, PEG + LIFT + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [wr, wi] = rings(-2, -4, X1 + 2, 0, 1.5, 0.7);
  put(solid(g), prism(P, front, wr, wi, 0, PEG + 14));
  const [rr, ri] = rings(1, 0, X1 - 1, 2.6, 1, 0.5);
  put(solid(g), prism(P, front, rr, ri, PEG - 2, PEG + 4));

  const packs = W.map((w, k) => {
    const x0 = xs[k], xc = x0 + w / 2;
    const [pr, pi] = rings(xc - 1.4, 0, xc + 1.4, 6.5, 0.7, 0.35);
    put(solid(g), prism(P, front, pr, pi, PEG - 0.4, PEG + 2.4));
    const grp = mk("g", {}, g), loop = mk("path", { class: "nf" }, grp);
    const body = solid(grp), pocket = solid(grp), straps = mk("path", { class: "nf lo" }, grp);
    const mat = k === MAT ? { sil: mk("path", { class: "sil" }, grp), end: mk("path", { class: "nf lo" }, grp) } : null;
    return { k, w, x0, xc, zb: ZT - HH[k], grp, loop, body, pocket, straps, mat, t: tween(REST[k]), last: NaN };
  });

  function draw(p, t) {
    if (t === p.last) return;
    p.last = t;
    const a = rad(TILT[p.k] * t), c = Math.cos(a), s = Math.sin(a);
    const Q = (x, y, z) => { const dx = x - p.xc, dz = z - ZT; return P(p.xc + dx * c - dz * s, y + FWD * t, ZT + dx * s + dz * c + LIFT * t); };
    const x1 = p.x0 + p.w;
    p.loop.setAttribute("d", open([Q(p.xc - 2.6, 4, ZT), Q(p.xc - 1.8, 4, PEG + 3.2), Q(p.xc + 1.8, 4, PEG + 3.2), Q(p.xc + 2.6, 4, ZT)]));
    const [br, bi] = rings(p.x0, 1, x1, D, 5, 1.2);
    put(p.body, prism(Q, front, br, bi, p.zb, ZT));
    const [tr, ti] = rings(p.x0 + 1.5, 1.8, x1 - 1.5, D + 1.4, 4, 1);
    put(p.pocket, prism(Q, front, tr, ti, ZT - 5, ZT + 1.5));
    let d = "";
    for (const f of [0.28, 0.72]) d += seg(Q(p.x0 + p.w * f, D, ZT - 6), Q(p.x0 + p.w * f, D, p.zb + 2));
    d += seg(Q(p.x0 + 1.5, D, (ZT + p.zb) / 2 - 3), Q(x1 - 1.5, D, (ZT + p.zb) / 2 - 3));
    p.straps.setAttribute("d", d);
    if (p.mat) {
      const ring = (x) => { const o = []; for (let i = 0; i < 20; i++) { const b = (i / 20) * Math.PI * 2; o.push(Q(x, D / 2 + 1 + 4.5 * Math.cos(b), p.zb - 3.6 + 4.5 * Math.sin(b))); } return o; };
      const e0 = ring(p.x0 - 2), e1 = ring(x1 + 2);
      p.mat.sil.setAttribute("d", poly(hull(e0.concat(e1))));
      p.mat.end.setAttribute("d", poly(e1));
    }
  }

  const B = register(stage, (_dt, now) => {
    let m = false;
    for (const p of packs) { draw(p, tval(p.t, now)); if (!tdone(p.t, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  const mids = packs.map((p) => P(p.xc, D, (ZT + p.zb) / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    packs.forEach((p, k) => {
      const d = Math.abs(k - a), t = a < 0 ? REST[k] : d === 0 ? 1 : d === 1 ? 0.22 : 0.06;
      tset(p.t, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      p.body.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "pack " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "backpacks",
  means: "Four hiking packs on a wall rack: the pack under the pointer lifts off its peg and tilts, its neighbours stir a little.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[122, 135], [219, 193], [268, 198], null],
  mount,
});

sunloungers.code:
/**
 * Sun loungers: four loungers along the edge of a pool deck, each a frame on
 * four legs with a seat pad and a hinged backrest, a towel folded over the
 * foot of one. The pointer picks a lounger by where it stands: its backrest
 * raises, and the backrests beside it raise a little, staggered from it. At
 * rest the backrests sit at different angles, one raised, bright. The slider
 * is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the pick is the lounger
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 30, LW = 18, SL = 30, BL = 20, LZ = 9, X0 = 4, FAV = 1, TOWEL = 2;
const X1 = 2 * X0 + (N - 1) * STEP + LW, REST = [4, 30, 12, 2], UP = 80;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.72);
  fit(C, [[-8, -BL - 10, -8], [X1 + 8, SL + 40, -8], [X1 + 8, -BL - 10, -8], [-8, SL + 40, -8], [X0, -BL * 0.31, LZ + BL + 4], [X1 - X0, -BL * 0.31, LZ + BL + 4]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [dr, di] = rings(-8, -BL - 10, X1 + 8, SL + 12, 4, 2);
  put(solid(g), prism(P, front, dr, di, -4, 0));
  const [wr, wi] = rings(-8, SL + 16, X1 + 8, SL + 40, 4, 2);
  put(solid(g), prism(P, front, wr, wi, -9, -6));
  mk("path", { class: "nf lo", d: [[10, 24, 0.3], [40, 70, 0.55], [80, 100, 0.8]].map(([a, b, f]) => seg(P(a, SL + 16 + 24 * f, -6), P(b, SL + 16 + 24 * f, -6))).join("") }, g);

  const lounge = [];
  for (let k = 0; k < N; k++) {
    const x0 = X0 + k * STEP, x1 = x0 + LW, grp = mk("g", {}, g);
    for (const y of [-BL + 2, SL - 4]) for (const x of [x0 + 1, x1 - 3]) { const [r, i] = rings(x, y, x + 2, y + 2, 0.8, 0.4); put(solid(grp), prism(P, front, r, i, 0, LZ - 2)); }
    const [fr, fi] = rings(x0, -BL, x1, SL, 2, 0.8);
    put(solid(grp), prism(P, front, fr, fi, LZ - 2, LZ));
    const back = solid(grp);
    const [sr, si] = rings(x0 + 0.6, 0.6, x1 - 0.6, SL - 0.6, 2.5, 1);
    put(solid(grp), prism(P, front, sr, si, LZ, LZ + 2.5));
    if (k === TOWEL) {
      const [tr, ti] = rings(x0 + 2.5, 10, x1 - 2.5, SL + 0.4, 1.4, 0.6);
      put(solid(grp), prism(P, front, tr, ti, LZ + 2.5, LZ + 3.1));
      mk("path", { d: poly([P(x0 + 2.5, SL + 0.4, LZ + 3.1), P(x1 - 2.5, SL + 0.4, LZ + 3.1), P(x1 - 2.5, SL + 0.9, LZ - 6), P(x0 + 2.5, SL + 0.9, LZ - 6)]) }, grp);
      mk("path", { class: "nf lo", d: seg(P(x0 + 2.5, 18, LZ + 3.1), P(x1 - 2.5, 18, LZ + 3.1)) }, grp);
    }
    lounge.push({ k, x0, x1, back, a: tween(REST[k]), last: NaN });
  }

  function draw(l, deg) {
    if (deg === l.last) return;
    l.last = deg;
    const c = Math.cos(rad(deg)), s = Math.sin(rad(deg));
    const Q = (x, y, z) => { const dz = z - LZ; return P(x, y * c + dz * s, LZ - y * s + dz * c); };
    const [br, bi] = rings(l.x0 + 0.6, -BL + 0.6, l.x1 - 0.6, -0.2, 2.5, 1);
    put(l.back, prism(Q, front, br, bi, LZ, LZ + 2.5));
  }

  const B = register(stage, (_dt, now) => {
    let m = false;
    for (const l of lounge) { draw(l, tval(l.a, now)); if (!tdone(l.a, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  const mids = lounge.map((l) => P((l.x0 + l.x1) / 2, 4, LZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 22 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    lounge.forEach((l, k) => {
      const d = Math.abs(k - a), deg = a < 0 ? REST[k] : Math.max(REST[k] * 0.5, [UP, 30, 12][d] || 0);
      tset(l.a, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      l.back.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "lounger " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "sunloungers",
  means: "Four sun loungers on a pool deck: the backrest under the pointer raises, and its neighbours raise a little in turn.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[165, 121], [201, 139], [274, 176], null],
  mount,
