tennisrackets.code:
/**
 * Tennis rackets: four rackets stand on a wall rack, leaning back against its
 * rail, each an oval head strung with a grid, an open throat and a grip; a
 * ball tube stands at the end. The racket under the pointer tilts out toward
 * the reader and lifts off the rack, and its neighbours tilt a little,
 * staggered from it. At rest one racket is half out, bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single row (bookshelf); the pick is the
 * racket whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, circ, fit, hull, poly, prism, proj, facing, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, XS = [0, 27, 54, 81], Y0 = 6, FAV = 1;
const REST = [-5, 3, -7, -4], OUT = 19, LIFT = 6, NB = [6, 2];
const HC = 50, HA = 11, HB = 15, T = 2.4;
const ell = (a, b, n) => circ(1, n).map((q) => [q.u * a, HC + q.v * b]);
const HEAD = ell(HA, HB, 40), RIM = ell(HA - 1.6, HB - 1.6, 40);
const GRIP = rrect(-2.7, 0, 2.7, 25, 1.2, 3).map((q) => [q.u, q.v]);
const THROAT = [[-7.5, 39], [7.5, 39], [2.4, 23], [-2.4, 23]];
const inset = (pts, d) => {
  const cu = pts.reduce((s, p) => s + p[0], 0) / pts.length, cv = pts.reduce((s, p) => s + p[1], 0) / pts.length;
  return pts.map(([u, v]) => { const l = Math.hypot(u - cu, v - cv) || 1; return [u - ((u - cu) / l) * d, v - ((v - cv) / l) * d]; });
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-14, -4, -4], [114, 14, -4], [-14, -4, 66], [114, -4, 66], [-12, 34, 80], [92, 34, 80]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the rail behind, then the ledge the rackets stand on
  { const [r, i] = rings(-14, -4, 96, -1, 1.2, 0.6); put(solid(g), prism(P, front, r, i, 54, 59)); }
  { const [r, i] = rings(-14, -4, 114, 13, 2, 1); put(solid(g), prism(P, front, r, i, -4, 0)); }

  const rk = XS.map((x, k) => {
    const grp = mk("g", {}, g);
    const grip = solid(grp), throat = solid(grp), head = solid(grp);
    const str = mk("path", { class: "nf lo" }, grp);
    return { k, x, grip, throat, head, str, th: tween(REST[k]), z: tween(0), last: "" };
  });
  { const [r] = rings(100, 1, 109, 10, 4.5, 1); put(solid(g), prism(P, front, r, rings(101.2, 2.2, 107.8, 8.8, 3.3, 0.5)[0], 0, 36)); }

  function draw(b, deg, lift) {
    const key = deg.toFixed(2) + "," + lift.toFixed(2);
    if (key === b.last) return false;
    b.last = key;
    const a = (deg * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a);
    const X = (u, v, w) => P(b.x + u, Y0 + w * c + v * s, lift + v * c - w * s);
    const slab = (el, pts, t, crease) => {
      const f = pts.map(([u, v]) => X(u, v, t / 2)), bk = pts.map(([u, v]) => X(u, v, -t / 2));
      el.sil.setAttribute("d", poly(hull(f.concat(bk))));
      el.cr.setAttribute("d", poly(crease.map(([u, v]) => X(u, v, t / 2))));
    };
    slab(b.grip, GRIP, 3.6, inset(GRIP, 0.9));
    slab(b.throat, THROAT, T, inset(THROAT, 1.1));
    slab(b.head, HEAD, T, RIM);
    let d = "";
    for (let u = -6; u <= 6; u += 3) { const h = (HB - 2.2) * Math.sqrt(1 - (u / (HA - 2.2)) ** 2); d += seg(X(u, HC - h, T / 2), X(u, HC + h, T / 2)); }
    for (let v = -9; v <= 9; v += 3) { const h = (HA - 2.2) * Math.sqrt(1 - (v / (HB - 2.2)) ** 2); d += seg(X(-h, HC + v, T / 2), X(h, HC + v, T / 2)); }
    b.str.setAttribute("d", d);
    return true;
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of rk) { draw(b, tval(b.th, now), tval(b.z, now)); if (!tdone(b.th, now) || !tdone(b.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  /** The racket whose resting middle is nearest the pointer's x on screen; -1 off the rack. */
  const mids = rk.map((b) => P(b.x, Y0, 34));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    rk.forEach((b, k) => {
      const d = Math.abs(k - a);
      const th = a < 0 ? REST[k] : d === 0 ? OUT : d <= 2 ? NB[d - 1] : REST[k];
      const delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(b.th, th, now, delay); tset(b.z, d === 0 ? LIFT : 0, now, delay);
      b.head.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "racket " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "tennisrackets",
  means: "Four tennis rackets on a wall rack: the one under the pointer tilts out and lifts off, its neighbours tilt a little.",
  rules: [1, 2, 5, 8],
  range: [0, 40, 80],
  tour: [[178, 101], [139, 81], [257, 140], null],
  mount,
});

harp.code:
/**
 * Harp: a concert harp on its pedestal, a column at the front, a soundboard
 * rising to a curved neck, and twelve strings between them. The pointer
 * plucks: the strings near it bow out and ring, each on its own spring, the
 * one under it most and bright. At rest three strings hang bowed, the middle
 * one bright. The slider is the reach, in strings.
 *
 * The pattern: a continuous field along one row; the hit is each string's
 * rest centre on screen, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, rrect, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 12, X0 = 14, SX = 6, BMAX = 9, FAV = 6, CHORD = { 5: 0.4, 6: 0.8, 7: 0.4 };
const SA = [2.3, 10.1], SB = [89.6, 125.7];
const NECK = [[-2, 148], [40, 136], [70, 142], [98, 128]];
const boardZ = (x) => SA[1] + ((x - SA[0]) * (SB[1] - SA[1])) / (SB[0] - SA[0]);
function neckZ(x) {
  for (let i = 0; i < NECK.length - 1; i++) { const [a, b] = [NECK[i], NECK[i + 1]]; if (x <= b[0]) return a[1] + ((x - a[0]) * (b[1] - a[1])) / (b[0] - a[0]); }
  return NECK[NECK.length - 1][1];
}
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);
const disc = (r, n = 24) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value, over = null;
  const C = Cam(45, 0.5, 1.62);
  fit(C, [[-14, -16, 0], [34, 16, 0], [-14, 16, 0], [34, -16, 0], [0, 0, 158], [98, 0, 132], [50, BMAX + 2, 80]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  /** A beam in the harp's plane from a to b ([x, z]), its rounded section ha × wa at a and hb × wb at b. */
  function beam(a, b, ha, wa, hb, wb, crease) {
    const dx = b[0] - a[0], dz = b[1] - a[1], L = Math.hypot(dx, dz), n = [-dz / L, dx / L];
    const sec = (p, h, w) => rrect(-w, -h, w, h, Math.min(w, h) * 0.6, 4).map((q) => P(p[0] + q.v * n[0], q.u, p[1] + q.v * n[1]));
    const el = solid(g);
    el.sil.setAttribute("d", poly(hull(sec(a, ha, wa).concat(sec(b, hb, wb)))));
    if (crease) el.cr.setAttribute("d", seg(P(a[0] + n[0] * ha, wa * 0.5, a[1] + n[1] * ha), P(b[0] + n[0] * hb, wb * 0.5, b[1] + n[1] * hb)));
    return el;
  }

  // pedestal with two feet, the column, the soundboard, the neck in three pieces, the capital
  const [pr, pi] = rings(-12, -14, 32, 14, 5, 1.6);
  put(solid(g), prism(P, front, pr, pi, 2, 9));
  for (const [x, y] of [[-6, -9], [26, -9], [-6, 9], [26, 9]]) put(solid(g), prism(P, front, circ(2.4, 16).map((q) => ({ ...q, u: q.u + x, v: q.v + y })), circ(1.6, 16).map((q) => ({ ...q, u: q.u + x, v: q.v + y })), 0, 2));
  put(solid(g), prism(P, front, disc(4.4), disc(3.2), 9, 146));
  beam([8, 8], [92, 124], 7, 9, 3, 4, true);
  for (let i = 0; i < NECK.length - 1; i++) beam(NECK[i], NECK[i + 1], 5, 3.6, 5, 3.6, false);
  put(solid(g), prism(P, front, disc(6.2), disc(5), 144, 156));

  const strings = [];
  for (let i = 0; i < N; i++) {
    const x = X0 + i * SX, z0 = boardZ(x), z1 = neckZ(x) - 4.6, rest = (CHORD[i] || 0) * BMAX * 0.5;
    const el = mk("path", { class: "nf" }, g);
    strings.push({ i, x, z0, z1, el, rest, sp: spring(rest, { c: 7, eps: 0.03 }), drawn: NaN, mid: P(x, 0, (z0 + z1) / 2), top: P(x, 0, z1)[1], bot: P(x, 0, z0)[1] });
  }
  // a string rings: its spring is underdamped (c 7) so the bow overshoots and settles, as a plucked string does
  function draw(s) {
    const d = clamp(s.sp.x, -BMAX, BMAX);
    if (d === s.drawn) return;
    s.drawn = d;
    const pts = [];
    for (let j = 0; j <= 10; j++) { const t = j / 10; pts.push(P(s.x, d * Math.sin(Math.PI * t), s.z0 + (s.z1 - s.z0) * t)); }
    s.el.setAttribute("d", open(pts));
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const s of strings) { if (stepS(s.sp, dt)) m = true; draw(s); }
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    for (const s of strings) {
      s.sp.t = over === null ? s.rest : s.i === over ? BMAX : BMAX * 0.8 * falloff(Math.abs(s.i - over) / RAD);
      s.el.classList.toggle("hi", s.i === (over === null ? FAV : over));
    }
    read.textContent = over === null ? "rest" : "string " + (over + 1);
    B.wake();
  }

  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      let best = null, bd = Infinity;
      for (const s of strings) { const d = Math.abs(s.mid[0] - sx); if (d < bd && sy > s.top - 6 && sy < s.bot + 6) { bd = d; best = s.i; } }
      over = bd < 8 ? best : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v; if (over !== null) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "harp",
  means: "A concert harp: the strings near the pointer bow out and ring, the one under it most.",
  rules: [1, 3, 5, 8],
  range: [1, 2.5, 4],
  tour: [[177, 142], [218, 145], [253, 135], null],
  mount,
});

xylophone.code:
/**
 * Xylophone: ten bars of falling length across two rails on a four-legged
 * stand, two mallets held over them. The pointer plays: the bars near it
 * press down, each on its own spring, the one under it deepest and bright,
 * and a mallet moves over it. At rest a chord is held, its middle bar bright.
 * The slider is the reach, in bars.
 *
 * The pattern: a continuous field (terrain) along one row; the hit is on the
 * plane of the bars' resting tops, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, poly, prism, proj, rings, ringAt, seg, unproj, spring, stepS,
  tween, tset, tval, tdone, disposer, mk, pointer, put, register, solid,
} = HL;

const N = 10, STEP = 11, BW = 9, BH = 4, DMAX = 6, RY = 12, LEGH = 34, X1 = N * STEP;
const len = (k) => 72 - k * 4.4, cx = (k) => k * STEP + 1 + BW / 2;
const FAV = 3, CHORD = { 2: 0.55, 3: 1, 4: 0.55 }, MZ = BH + 13;
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);
const disc = (x, y, r, n = 16) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value, over = null;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-4, -40, -LEGH], [X1 + 4, 40, -LEGH], [X1 + 4, -40, -LEGH], [-4, 40, -LEGH], [-4, -40, MZ + 26], [X1 + 14, 44, MZ + 26]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1, el = solid(g)) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(el, prism(P, front, o, i, z0, z1)); return el; };

  // the stand: far legs and stretcher, near legs and stretcher, then the two rails
  for (const s of [-1, 1]) {
    for (const x of [3, X1 - 3]) block(x - 1.6, s * RY - 1.6, x + 1.6, s * RY + 1.6, 1.2, 0.5, -LEGH, -4);
    block(3, s * RY - 1, X1 - 3, s * RY + 1, 0.9, 0.4, -LEGH + 7, -LEGH + 9.5);
  }
  block(-2, -RY - 2.2, X1 + 2, -RY + 2.2, 1.6, 0.7, -4, 0);
  block(-2, RY - 2.2, X1 + 2, RY + 2.2, 1.6, 0.7, -4, 0);

  const bars = [];
  for (let k = 0; k < N; k++) {
    const L = len(k), x0 = k * STEP + 1, [ring, inner] = rings(x0, -L / 2, x0 + BW, L / 2, 1.8, 0.8);
    const rest = (CHORD[k] || 0) * DMAX * 0.6;
    bars.push({ k, L, ring, inner, rest, el: solid(g), sp: spring(rest, { eps: 0.02 }), drawn: NaN });
  }

  // two mallets: a round head on a stick; the first follows the chosen bar
  const mallets = [0, 1].map((m) => ({ stick: mk("path", { class: "nf" }, g), head: mk("path", {}, g), at: tween(m ? FAV + 3 : FAV), z: m ? 6 : 0, last: NaN }));
  function drawMallet(ml, idx) {
    if (idx === ml.last) return;
    ml.last = idx;
    const x = idx * STEP + 1 + BW / 2, z = MZ + ml.z, pts = [];
    for (let i = -3; i <= 3; i++) { const t = (i / 3) * (Math.PI / 2); pts.push(...ringAt(P, disc(x, 2, 4.4 * Math.cos(t)), z + 4.4 * Math.sin(t))); }
    ml.head.setAttribute("d", poly(hull(pts)));
    ml.stick.setAttribute("d", seg(P(x, 2, z), P(x + 10, 42, z + 24)));
  }

  function draw(b) {
    const d = clamp(b.sp.x, 0, DMAX);
    if (d === b.drawn) return;
    b.drawn = d;
    put(b.el, prism(P, front, b.ring, b.inner, -d, BH - d));
  }
  const B = register(stage, (dt, now) => {
    let m = false;
    for (const b of bars) { if (stepS(b.sp, dt)) m = true; draw(b); }
    for (const ml of mallets) { drawMallet(ml, tval(ml.at, now)); if (!tdone(ml.at, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    const hit = over ? bars[clamp(Math.floor(over[0] / STEP), 0, N - 1)] : null, a = hit ? hit.k : FAV, now = performance.now();
    for (const b of bars) {
      b.sp.t = !over ? b.rest : b === hit ? DMAX : DMAX * 0.8 * falloff(Math.abs(cx(b.k) - over[0]) / (RAD * STEP));
      b.el.sil.classList.toggle("hi", b.k === a);
    }
    tset(mallets[0].at, a, now, 0);
    tset(mallets[1].at, a > 5 ? a - 3 : a + 3, now, 40);
    read.textContent = hit ? "bar " + (hit.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], BH);
      over = x > -3 && x < X1 + 3 && Math.abs(y) < 40 ? [clamp(x, 0, X1 - 0.01), y] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "xylophone",
  means: "A xylophone on its stand: the bars near the pointer press down, the one under it deepest, a mallet over it.",
  rules: [1, 3, 5, 9],
  range: [1, 2, 3.5],
  tour: [[166, 120], [177, 155], [230, 195], null],
  mount,
});

watchcase.code:
/**
 * Watch case: an open case, its lid standing behind, holding six wristwatches
 * on pillows, each a round case with a crystal and two hands, its strap looped
 * round the pillow. The pointer picks a watch by where it stands: it lifts off
 * its pillow and tilts toward the reader, its hands turn to the pointer, and
 * the watches beside it lift a little, staggered from it. At rest one watch
 * is raised, bright, and every watch shows its own time. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (riffle), plus a spring per watch
 * for the hands, which follow the pointer's place on the case floor.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, rrect, seg, unproj,
  spring, stepS, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, STEP = 24, YC = 22, CZ = 8, PH = 8, ZT = CZ + PH, FR = 6.5, LIFT = 12, TILT = 0.5, FAV = 2;
const X1 = N * STEP, REST = [0.6, 2.2, -1.0, 1.4, -2.4, 0.2];
const LOOP = rrect(-16.6, -PH, 16.6, 0.8, 4, 4), FACE = circ(FR, 32), GLASS = circ(FR - 1.4, 28);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, -5, 0], [X1, 44, 0], [X1, -5, 0], [0, 44, 0], [0, -5, 56], [X1, -5, 56], [STEP / 2, YC + 6, ZT + LIFT + 12]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the lid, open and standing behind, with its lining; then the case
  const [lr, li] = rings(0, -5, X1, 0, 2, 0.8);
  put(solid(g), prism(P, front, lr, li, 0, 56));
  mk("path", { class: "nf lo", d: poly([[5, 0, 6], [X1 - 5, 0, 6], [X1 - 5, 0, 50], [5, 0, 50]].map((p) => P(...p))) }, g);
  const [cr, ci] = rings(0, 0, X1, 44, 6, 2);
  put(solid(g), prism(P, front, cr, ci, 0, CZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = STEP / 2 + k * STEP;
    const [pr, pi] = rings(x - 9, YC - 16, x + 9, YC + 16, 5, 1.5);
    put(solid(g), prism(P, front, pr, pi, CZ, ZT));
    items.push({ k, x, z: tween(k === FAV ? LIFT * 0.6 : 0), ha: spring(REST[k]), last: "" });
  }
  for (const it of items) {
    it.grp = mk("g", {}, g);
    it.strap = mk("path", { class: "sil" }, it.grp);
    it.cas = mk("path", { class: "sil" }, it.grp);
    it.glass = mk("path", { class: "nf lo" }, it.grp);
    it.hands = mk("path", { class: "nf" }, it.grp);
  }

  function draw(it, lift) {
    const a = it.ha.x, key = lift.toFixed(2) + "," + a.toFixed(3);
    if (key === it.last) return;
    it.last = key;
    const th = TILT * lift / LIFT, c = Math.cos(th), s = Math.sin(th);
    const W = (x, y, z) => P(it.x + x, YC + y * c + z * s, ZT + lift - y * s + z * c);
    const loop = [];
    for (const q of LOOP) loop.push(W(-4, q.u, q.v), W(4, q.u, q.v));
    it.strap.setAttribute("d", poly(hull(loop)));
    const cas = [];
    for (const q of FACE) cas.push(W(q.u, q.v, 0.8), W(q.u, q.v, 3.6));
    it.cas.setAttribute("d", poly(hull(cas)));
    it.glass.setAttribute("d", poly(GLASS.map((q) => W(q.u, q.v, 3.6))));
    const o = W(0, 0, 3.7);
    it.hands.setAttribute("d", seg(o, W((FR - 2) * Math.cos(a), (FR - 2) * Math.sin(a), 3.7)) +
      seg(o, W((FR - 3.6) * Math.cos(a + 2.1), (FR - 3.6) * Math.sin(a + 2.1), 3.7)));
  }

  const B = register(stage, (dt, now) => {
    let moving = false;
    for (const it of items) {
      if (stepS(it.ha, dt)) moving = true;
      draw(it, tval(it.z, now));
      if (!tdone(it.z, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, YC, ZT));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 28 && Math.abs(mids[best][1] - sy) < 55 ? best : -1;
  }

  let act = -2, over = null;
  function setActive(a) {
    const now = performance.now();
    if (a !== act) {
      const from = a >= 0 ? a : act;
      act = a;
      items.forEach((it, k) => {
        const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 3.5 : 0;
        tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
        it.cas.classList.toggle("hi", k === (a < 0 ? FAV : a));
      });
      read.textContent = a < 0 ? "rest" : "watch " + (a + 1);
    }
    items.forEach((it, k) => {
      let t = REST[k];
      if (k === a && over) {
        const dx = over[0] - it.x, dy = over[1] - YC;
        t = Math.hypot(dx, dy) < 3 ? it.ha.t : Math.atan2(dy, dx);
      }
      it.ha.t = it.ha.t + clamp(t - it.ha.t - Math.PI * 2 * Math.round((t - it.ha.t) / (Math.PI * 2)), -Math.PI, Math.PI);
    });
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, {
    move: (p) => { over = unproj(C, p[0], p[1], ZT); setActive(hit(p)); },
    leave: () => { over = null; setActive(-1); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "watchcase",
  means: "Six watches on pillows in an open case: the watch under the pointer lifts, tilts and turns its hands to it.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[114, 149], [180, 182], [279, 231], null],
  mount,
});

giftwrap.code:
/**
 * Gift wrap: a wrapping station, a bench with two posts and a rail, four rolls
 * of gift paper of different girths hung on the rail, a sheet hanging from
 * the front of each, and a ribbon spool at the bench's corner with its tail
 * laid out. The pointer is where the paper is pulled: the roll under it
 * unrolls a sheet toward the reader, and the rolls beside it unroll a little,
 * each on its own spring. At rest one sheet is half out, its roll bright. The
 * slider is how far the reach spreads.
 *
 * The pattern: a continuous falloff along one row (terrain's spring, per
 * roll); the pick is the roll whose resting middle is nearest the pointer's x.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, seg, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 32, L = 26, YC = 14, ZA = 34, RR = [9, 8, 9.5, 7.5], SMAX = 38, FAV = 2;
const REST = [3, 5, 15, 2], A = 0.87, CA = Math.cos(A), SA = Math.sin(A);
const XE = N * STEP + 8;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-12, -4, 0], [XE + 14, 64, 0], [XE + 14, -4, 0], [-12, 64, 0], [0, YC, ZA + 10], [XE, YC, ZA + 10]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // a ring standing across x, round an axis along x
  const ringX = (x, y, z, r, n = 28) => circ(r, n).map((q) => P(x, y + q.u, z + q.v));
  const cylX = (x0, x1, y, z, r) => poly(hull(ringX(x0, y, z, r).concat(ringX(x1, y, z, r))));

  const [br, bi] = rings(-12, -4, XE + 14, 64, 5, 2);
  put(solid(g), prism(P, front, br, bi, 0, 4));
  const post = (x) => put(solid(g), prism(P, front, circ(2, 20).map((q) => ({ ...q, u: q.u + x, v: q.v + YC })), null, 4, ZA + 2));
  post(-2);
  mk("path", { class: "sil", d: cylX(-4, XE, YC, ZA, 1.6) }, g);

  const rolls = [];
  for (let k = 0; k < N; k++) {
    const x0 = 6 + k * STEP, x1 = x0 + L, r = RR[k], el = mk("g", {}, g);
    const body = mk("path", { class: "sil", d: cylX(x0, x1, YC, ZA, r) }, el);
    mk("path", { class: "nf lo", d: poly(ringX(x1, YC, ZA, r - 1.2)) + poly(ringX(x1, YC, ZA, 2.6, 16)) }, el);
    rolls.push({ k, x0, x1, r, body, sp: spring(REST[k]), last: NaN });
  }
  for (const it of rolls) {
    it.sheet = mk("path", {}, g);
    it.edge = mk("path", { class: "nf lo" }, g);
  }
  post(XE);
  // the ribbon spool and its tail, flat on the bench
  put(solid(g), prism(P, front, circ(7, 40).map((q) => ({ ...q, u: q.u + XE + 2, v: q.v + 50 })), circ(5.8, 40).map((q) => ({ ...q, u: q.u + XE + 2, v: q.v + 50 })), 4, 11));
  place(flatDot(g, C, 1.6, "dot off"), P(XE + 2, 50, 11));
  mk("path", { class: "nf", d: poly([[XE - 5, 49, 4.2], [XE - 30, 55, 4.2], [XE - 31, 58, 4.2], [XE - 5, 52, 4.2]].map((p) => P(...p))) }, g);

  function draw(it) {
    const s = it.sp.x;
    if (Math.abs(s - it.last) < 0.02) return;
    it.last = s;
    const y0 = YC + it.r, a = [it.x0 + 1, y0, ZA], b = [it.x1 - 1, y0, ZA];
    const end = (p) => [p[0], p[1] + s * CA, p[2] - s * SA];
    const c = end(b), d = end(a);
    it.sheet.setAttribute("d", poly([a, b, c, d].map((p) => P(...p))));
    it.edge.setAttribute("d", seg(P(d[0], d[1] - 0.6, d[2] - 1), P(c[0], c[1] - 0.6, c[2] - 1)));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const it of rolls) { if (stepS(it.sp, dt)) m = true; draw(it); }
    return m;
  });
  bag.add(B.unregister);

  const mids = rolls.map((it) => P((it.x0 + it.x1) / 2, YC, ZA));
  const span = Math.abs(mids[1][0] - mids[0][0]);
  function aim(p) {
    let best = -1, bd = Infinity;
    if (p) mids.forEach((m, k) => { const dd = Math.abs(m[0] - p[0]); if (dd < bd) { bd = dd; best = k; } });
    if (best >= 0 && (bd > span * 0.8 || Math.abs(mids[best][1] - p[1]) > 70)) best = -1;
    rolls.forEach((it, k) => {
      let t = REST[k];
      if (best >= 0) {
        const dn = Math.abs(mids[k][0] - p[0]) / span, f = Math.max(0.08, Math.exp(-(dn * dn) / (0.5 * reach * reach)));
        t = clamp(SMAX * f, 2, SMAX);
      }
      it.sp.t = t;
      it.body.classList.toggle("hi", k === (best < 0 ? FAV : best));
    });
    read.textContent = best < 0 ? "rest" : "roll " + (best + 1);
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

