  rules: [1, 3, 5, 8],
  range: [0.6, 1, 1.6],
  tour: [[153, 90], [197, 112], [285, 156], null],
  mount,
});

compassneedles.code:
/**
 * Compass needles: a lab bench with twelve small compasses in a grid, four
 * across and three deep, and a bar magnet lying beside them. The pointer is a
 * second magnet: every needle swings on its own spring to point at it, and the
 * compass under it is bright. At rest every needle points at the bar magnet,
 * each at its own angle, and the magnet is bright. The slider is how quickly
 * the needles follow (a stiffer or softer spring).
 *
 * The pattern: a continuous aim per part (officechairs); the hit is on the
 * compasses' top plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, poly, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NC = 4, NR = 3, GAP = 22, RC = 8, TOP = 3, X0 = -42, Y0 = -22, LN = 7, LS = 4.6, NW = 2;
const TB = [-58, -36, 64, 36], MAG = [42, 54, -17, 17];
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[TB[0], TB[1], -7], [TB[2], TB[3], -7], [TB[2], TB[1], -7], [TB[0], TB[3], -7], [TB[0], TB[1], 0], [TB[2], TB[1], 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(TB[0], TB[1], TB[2], TB[3], 4, 1.8);
  put(solid(g), prism(P, front, tr, ti, -7, 0));

  // the magnet's north end is the far one (smaller y); every needle points at it at rest
  const north = [(MAG[0] + MAG[1]) / 2, MAG[2] + 4];
  const items = [];
  for (let c = 0; c < NC; c++) for (let r = 0; r < NR; r++) {
    const cx = X0 + c * GAP, cy = Y0 + r * GAP, rest = Math.atan2(north[1] - cy, north[0] - cx);
    items.push({ c, r, cx, cy, rest, sp: spring(rest, { k: 100 * value, c: 18 * Math.sqrt(value) }), drawn: NaN });
  }
  const magnet = { mag: true, cx: (MAG[0] + MAG[1]) / 2, cy: 0 };
  let magEl = null;
  for (const it of [...items, magnet].sort((p, q) => p.cx + p.cy - (q.cx + q.cy))) {
    if (it.mag) {
      magEl = solid(g);
      const [mr, mi] = rings(MAG[0], MAG[2], MAG[1], MAG[3], 1.6, 0.8);
      put(magEl, prism(P, front, mr, mi, 0, 6));
      mk("path", { class: "nf lo", d: seg(P(MAG[0] + 0.8, 0, 6), P(MAG[1] - 0.8, 0, 6)) }, magEl.g);
      continue;
    }
    const grp = mk("g", {}, g);
    it.case = solid(grp);
    put(it.case, prism(P, front, disc(it.cx, it.cy, RC), disc(it.cx, it.cy, RC - 1.3), 0, TOP));
    it.needle = mk("path", { class: "sil" }, grp);
    it.mid = mk("path", { class: "nf lo" }, grp);
  }

  function draw(it) {
    const a = it.sp.x;
    if (Math.abs(a - it.drawn) < 1e-4) return;
    it.drawn = a;
    const c = Math.cos(a), s = Math.sin(a), at = (l, w) => P(it.cx + l * c - w * s, it.cy + l * s + w * c, TOP);
    it.needle.setAttribute("d", poly([at(LN, 0), at(0, NW), at(-LS, 0), at(0, -NW)]));
    it.mid.setAttribute("d", seg(at(0, NW), at(0, -NW)));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const it of items) { if (stepS(it.sp, dt)) m = true; draw(it); }
    return m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = null, bd = Infinity;
    for (const it of items) {
      if (over) {
        const d = Math.hypot(over[0] - it.cx, over[1] - it.cy);
        if (d < bd) { bd = d; near = it; }
        const aim = d < 2 ? it.sp.t : Math.atan2(over[1] - it.cy, over[0] - it.cx);
        it.sp.t = it.sp.t + wrap(aim - it.sp.t);
      } else it.sp.t = it.sp.t + wrap(it.rest - it.sp.t);
    }
    for (const it of items) {
      const on = it === near;
      it.case.sil.classList.toggle("hi", on);
      it.needle.classList.toggle("hi", on);
    }
    magEl.sil.classList.toggle("hi", !near);
    read.textContent = near ? `compass ${near.c + 1}·${near.r + 1}` : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], TOP);
      const out = x < TB[0] - 12 || x > TB[2] + 12 || y < TB[1] - 12 || y > TB[3] + 12;
      over = out ? null : [clamp(x, TB[0], TB[2]), clamp(y, TB[1], TB[3])];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const it of items) { it.sp.k = 100 * v; it.sp.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "compassneedles",
  means: "Twelve compasses on a lab bench beside a bar magnet: every needle swings to point at the pointer, and the compass under it is bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[165, 136], [238, 233], [162, 86], null],
  mount,
});

satellite.code:
/**
 * Satellite: a box bus with a dish on top and two solar wings on booms, each
 * wing three cells long. The pointer is the sun: both wings unfold and tilt on
 * springs to face it, the nearer one all the way open and bright. At rest one
 * wing is half stowed and the other open at a slant, and the dish is bright.
 * The slider is how quickly the wings follow (a stiffer or softer spring).
 *
 * The pattern: a continuous aim (spotlights); the hit is on the bus's
 * middle plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fillet, fit, hull, lerp, poly, prism, proj, ringAt, rings, seg, unproj, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const B0 = 10, BZ = 24, ZC = 12, HW = 9, BOOM = 5, LMIN = 12, LMAX = 42, BMAX = 0.95;
const REST = [{ u: 0.3, b: 0.5 }, { u: 0.85, b: -0.35 }];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.3);
  const R = B0 + BOOM + LMAX, hz = HW * Math.sin(BMAX);
  fit(C, [[-R, -HW, ZC - hz], [-R, HW, ZC + hz], [R, -HW, ZC + hz], [R, HW, ZC - hz], [0, 0, BZ + 15], [B0, B0, 0], [-B0, -B0, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const opt = { k: 100 * value, c: 18 * Math.sqrt(value) };
  const wing = (k) => {
    const grp = mk("g", {}, g);
    return {
      k, side: k ? 1 : -1, grp, u: spring(REST[k].u, opt), b: spring(REST[k].b, opt), drawn: "",
      boom: mk("path", { class: "nf sil" }, grp), panel: mk("path", { class: "sil" }, grp), cells: mk("path", { class: "nf lo" }, grp),
    };
  };
  const wings = [wing(0)];
  // the bus, then its dish on a short mast, the feed standing out of the bowl
  const [br, bi] = rings(-B0, -B0, B0, B0, 2.5, 1.2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  mk("path", { class: "nf lo", d: seg(P(B0, -B0 + 3, 6), P(B0, B0 - 3, 6)) }, g);
  put(solid(g), prism(P, front, circ(1.4, 16), null, BZ, BZ + 4));
  const bowl = mk("path", { class: "sil", d: poly(hull(ringAt(P, circ(3, 24), BZ + 4).concat(ringAt(P, circ(11, 48), BZ + 9)))) }, g);
  mk("path", { class: "nf lo", d: poly(ringAt(P, circ(10, 48), BZ + 9)) }, g);
  mk("path", { class: "nf sil", d: seg(P(0, 0, BZ + 5), P(0, 0, BZ + 14)) }, g);
  place(flatDot(g, C, 0.9, "dot m"), P(0, 0, BZ + 14));
  wings.push(wing(1));

  function draw(w) {
    const u = w.u.x, b = w.b.x, key = u.toFixed(4) + "," + b.toFixed(4);
    if (key === w.drawn) return;
    w.drawn = key;
    const L = lerp(LMIN, LMAX, u), x0 = w.side * (B0 + BOOM), x1 = w.side * (B0 + BOOM + L);
    const at = (x, v) => P(x, v * Math.cos(b), ZC + v * Math.sin(b));
    w.boom.setAttribute("d", seg(P(w.side * B0, 0, ZC), at(x0, 0)));
    w.panel.setAttribute("d", poly(fillet([at(x0, -HW), at(x1, -HW), at(x1, HW), at(x0, HW)], [1.5, 1.5, 1.5, 1.5])));
    let d = seg(at(x0 + w.side, 0), at(x1 - w.side, 0));
    for (const t of [1 / 3, 2 / 3]) { const x = lerp(x0, x1, t); d += seg(at(x, -HW + 1), at(x, HW - 1)); }
    w.cells.setAttribute("d", d);
  }

  const Bk = register(stage, (dt) => {
    let m = false;
    for (const w of wings) { if (stepS(w.u, dt)) m = true; if (stepS(w.b, dt)) m = true; draw(w); }
    return m;
  });
  bag.add(Bk.unregister);

  let over = null;
  function retarget() {
    const near = over ? (over[0] < 0 ? 0 : 1) : -1;
    for (const w of wings) {
      w.u.t = over ? (w.k === near ? 1 : 0.7) : REST[w.k].u;
      w.b.t = over ? clamp(Math.atan2(-over[1], 40), -BMAX, BMAX) : REST[w.k].b;
      w.panel.classList.toggle("hi", w.k === near);
    }
    bowl.classList.toggle("hi", near < 0);
    read.textContent = near < 0 ? "rest" : `wing ${near + 1}`;
    Bk.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], ZC);
      over = Math.abs(x) > R + 16 || Math.abs(y) > 70 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const w of wings) for (const s of [w.u, w.b]) { s.k = 100 * v; s.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "satellite",
  means: "A satellite with two folding solar wings: they unfold and tilt to face the pointer as the sun, the nearer wing bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[293, 202], [100, 110], [270, 261], null],
  mount,
});

moonrover.code:
/**
 * Moon rover: a six-wheeled rover on rockers, with a camera head on a mast
 * and a small dish on a post, standing on a cratered patch of ground. The
 * pointer is what the rover looks at: the camera and the dish each turn on a
 * spring to face it, and the camera is bright. At rest the camera looks off
 * to one side and the dish to another, and the dish is bright. The slider is
 * how quickly they follow (a stiffer or softer spring).
 *
 * The pattern: a continuous aim per part (officechairs, spotlights); the hit
 * is on the ground's plane, which never moves.
 */
const {
  Cam, circ, facing, fit, hull, poly, prism, proj, rad, ringAt, rings, seg, open, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const RG = 62, WX = [-15, 0, 15], WY = 16, WR = 5.5, WT = 2.4, CZ = [7, 14], MX = 12, MY = -5, DX = -12, DY = 3;
const CRATERS = [[-38, 24, 10], [24, 42, 7], [36, -34, 12], [-22, -42, 6]], REST = [rad(70), rad(150)], EL = rad(35);
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const turn = (ring, a, cx, cy) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-RG, 0, -5], [RG, 0, -5], [0, -RG, -5], [0, RG, -5], [0, -RG, 0], [MX, MY, 40]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(RG, 72), circ(RG - 2, 72), -5, 0));
  mk("path", { class: "nf lo", d: CRATERS.map(([x, y, r]) => poly(ringAt(P, disc(x, y, r, 32), 0)) + poly(ringAt(P, disc(x + r * 0.15, y + r * 0.15, r * 0.6, 24), 0))).join("") }, g);

  const wheel = (x, y) => {
    const side = (yy) => Array.from({ length: 24 }, (_, i) => { const t = (i / 24) * Math.PI * 2; return P(x + WR * Math.cos(t), yy, WR + WR * Math.sin(t)); });
    const face = (r) => Array.from({ length: 24 }, (_, i) => { const t = (i / 24) * Math.PI * 2; return P(x + r * Math.cos(t), y + WT, WR + r * Math.sin(t)); });
    mk("path", { class: "sil", d: poly(hull(side(y - WT).concat(side(y + WT)))) }, g);
    mk("path", { class: "nf lo", d: poly(face(WR - 1.3)) + poly(face(1.4)) }, g);
  };
  for (const x of WX) wheel(x, -WY);
  const [cr, ci] = rings(-21, -12, 21, 12, 3, 1.3);
  put(solid(g), prism(P, front, cr, ci, CZ[0], CZ[1]));
  for (const x of WX) wheel(x, WY);
  mk("path", { class: "nf sil", d: open([P(-15, WY + WT, WR), P(-7, WY + WT, 11), P(7, WY + WT, 11), P(15, WY + WT, WR)]) + seg(P(0, WY + WT, WR), P(0, WY + WT, 11)) }, g);

  // the dish on its post, then the mast and its camera head
  put(solid(g), prism(P, front, disc(DX, DY, 1.1, 16), null, CZ[1], 24));
  const bowl = mk("path", { class: "sil" }, g), rim = mk("path", { class: "nf lo" }, g), feed = mk("path", { class: "nf sil" }, g);
  put(solid(g), prism(P, front, disc(MX, MY, 1.3, 16), null, CZ[1], 33));
  const head = solid(g), lens = mk("path", { class: "nf" }, g);
  const HEAD = rings(-3, -5, 3, 5, 1.4, 0.7);
  const opt = { k: 100 * value, c: 18 * Math.sqrt(value) };
  const cam = spring(REST[0], opt), dish = spring(REST[1], opt);
  let drawn = "";
  const V = [Math.cos(rad(45)) * 0.87, Math.sin(rad(45)) * 0.87, 0.5];

  function draw() {
    const key = cam.x.toFixed(4) + "," + dish.x.toFixed(4);
    if (key === drawn) return;
    drawn = key;
    const a = cam.x, ca = Math.cos(a), sa = Math.sin(a);
    put(head, prism(P, front, turn(HEAD[0], a, MX, MY), turn(HEAD[1], a, MX, MY), 32, 38));
    const lc = [MX + 3 * ca, MY + 3 * sa, 35];
    lens.setAttribute("d", ca * V[0] + sa * V[1] > 0.05 ? poly(Array.from({ length: 20 }, (_, i) => {
      const t = (i / 20) * Math.PI * 2, r = 1.6;
      return P(lc[0] - r * Math.cos(t) * sa, lc[1] + r * Math.cos(t) * ca, lc[2] + r * Math.sin(t));
    })) : "");
    const b = dish.x, d = [Math.cos(b) * Math.cos(EL), Math.sin(b) * Math.cos(EL), Math.sin(EL)], c = [DX, DY, 26.5];
    let u = [-d[1], d[0], 0]; const un = Math.hypot(...u) || 1; u = u.map((x) => x / un);
    const v = [u[1] * d[2] - u[2] * d[1], u[2] * d[0] - u[0] * d[2], u[0] * d[1] - u[1] * d[0]];
    const ring = (off, r) => Array.from({ length: 28 }, (_, i) => {
      const t = (i / 28) * Math.PI * 2, q = (j) => c[j] + d[j] * off + r * (Math.cos(t) * u[j] + Math.sin(t) * v[j]);
      return P(q(0), q(1), q(2));
    });
    bowl.setAttribute("d", poly(hull(ring(-1.6, 1.8).concat(ring(1.4, 7)))));
    rim.setAttribute("d", d[0] * V[0] + d[1] * V[1] + d[2] * V[2] > 0 ? poly(ring(1.4, 6.2)) : "");
    feed.setAttribute("d", seg(P(c[0], c[1], c[2]), P(c[0] + d[0] * 6, c[1] + d[1] * 6, c[2] + d[2] * 6)));
  }

  const B = register(stage, (dt) => { const m1 = stepS(cam, dt), m2 = stepS(dish, dt); draw(); return m1 || m2; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    const aim = (s, x, y, rest) => { const t = over ? Math.atan2(over[1] - y, over[0] - x) : rest; s.t = s.t + wrap(t - s.t); };
    aim(cam, MX, MY, REST[0]); aim(dish, DX, DY, REST[1]);
    head.sil.classList.toggle("hi", !!over);
    bowl.classList.toggle("hi", !over);
    read.textContent = over ? `aim ${Math.round(((Math.atan2(over[1] - MY, over[0] - MX) * 180) / Math.PI + 360) % 360)}°` : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y), k = Math.min(1, RG / r);
      over = r > RG + 24 ? null : [x * k, y * k];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const s of [cam, dish]) { s.k = 100 * v; s.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "moonrover",
  means: "A six-wheeled lunar rover on a cratered patch: its mast camera and dish turn to face the pointer, the camera bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[258, 201], [110, 127], [110, 217], null],
  mount,
});

windowfacade.code:
/**
 * Window facade: a building's face with twelve casement windows, four across
 * and three high, each a sash hinged on its left jamb over a stone sill. The
 * pointer is a breeze across the face: the windows near it swing open on
 * their springs, falling off with distance, and the one under it opens wide
 * and is bright. At rest a few stand ajar, one half open and bright. The
 * slider is the breeze's reach.
 *
 * The pattern: a field on a face (depositboxes); springs per sash; the hit
 * is read on the facade's plane, which never moves.
 */
const {
  Cam, clamp, facing, fillet, fit, poly, prism, proj, rad, rings, rrect, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NC = 4, NR = 3, CW = 24, CH = 22, M = 8, BASE = 8, D = 10, WW = 14, WH = 15, MAXA = 80;
const W = 2 * M + NC * CW, H = BASE + NR * CH + 4, FAV = [1, 2];
const REST = [[6, 22, 3], [3, 4, 74], [28, 3, 9], [3, 14, 4]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D + WW, BASE], [0, 0, H], [W, 0, H], [0, D + WW, H - 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [wr, wi] = rings(0, 0, W, D, 3, 1.4);
  put(solid(g), prism(P, front, wr, wi, 0, H));
  mk("path", { d: seg(P(1.5, D, BASE - 3), P(W - 1.5, D, BASE - 3)) + seg(P(1.5, D, H - 3), P(W - 1.5, D, H - 3)), class: "nf lo" }, g);

  const wins = [];
  for (let c = 0; c < NC; c++) for (let r = 0; r < NR; r++) {
    const x0 = M + c * CW + (CW - WW) / 2, z0 = BASE + r * CH + 4;
    // the opening in the face, painted before any sash swings out over it
    mk("path", { d: poly(rrect(x0 - 0.6, z0, x0 + WW + 0.6, z0 + WH + 0.6, 0.8, 2).map((q) => P(q.u, D, q.v))), class: "nf lo" }, g);
    wins.push({ c, r, x0, z0, rest: rad(REST[c][r]) });
  }
  // left to right, bottom to top: a sash only ever swings out over a window to its left or below it
  for (const w of wins) {
    const [sr, si] = rings(w.x0 - 2, D - 1, w.x0 + WW + 2, D + 3, 0.8, 0.5);
    put(solid(g), prism(P, front, sr, si, w.z0 - 1.8, w.z0));
    w.sash = mk("path", { class: "sil" }, g);
    w.bars = mk("path", { class: "nf lo" }, g);
    w.sp = spring(w.rest);
    w.drawn = NaN;
  }

  function draw(w) {
    const a = w.sp.x;
    if (Math.abs(a - w.drawn) < 1e-4) return;
    w.drawn = a;
    const at = (s, z) => P(w.x0 + s * Math.cos(a), D + s * Math.sin(a), z), z1 = w.z0 + WH;
    w.sash.setAttribute("d", poly(fillet([at(0, w.z0), at(WW, w.z0), at(WW, z1), at(0, z1)], [1.2, 1.2, 1.2, 1.2])));
    const zm = w.z0 + WH / 2;
    w.bars.setAttribute("d", poly([at(1.8, w.z0 + 1.8), at(WW - 1.8, w.z0 + 1.8), at(WW - 1.8, z1 - 1.8), at(1.8, z1 - 1.8)]) + seg(at(1.8, zm), at(WW - 1.8, zm)));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const w of wins) { if (stepS(w.sp, dt)) m = true; draw(w); }
    return m;
  });
  bag.add(B.unregister);

  /** The window under the point, read on the facade's plane (y = D), which never moves. */
  function hit([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + D * s) / c, Y = x * s + D * c, z = (Y * C.k - (sy - C.oy) / C.S) / zf;
    if (x < M || x > W - M || z < BASE || z > BASE + NR * CH + 2) return -1;
    return clamp(Math.floor((x - M) / CW), 0, NC - 1) * NR + clamp(Math.floor((z - BASE) / CH), 0, NR - 1);
  }

  let act = -2;
  const favI = FAV[0] * NR + FAV[1];
  function setActive(a) {
    if (a === act) return;
    act = a;
    const ac = a >= 0 ? wins[a] : null;
    wins.forEach((w, i) => {
      const d = ac ? Math.hypot(w.c - ac.c, w.r - ac.r) : 0;
      w.sp.t = ac ? clamp(rad(MAXA) * Math.exp(-(d * d) / (2 * reach * reach)), rad(3), rad(MAXA)) : w.rest;
      w.sash.classList.toggle("hi", i === (a < 0 ? favI : a));
    });
    read.textContent = a < 0 ? "rest" : `window ${ac.c + 1}·${NR - ac.r}`;
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; const a = act; act = -2; setActive(a); }, destroy: bag.dispose };
}

hairline({
  name: "windowfacade",
  means: "A facade of twelve casement windows: the windows near the pointer swing open, and the one under it opens wide and bright.",
  rules: [1, 3, 5, 8],
  range: [0.6, 1, 1.6],
  tour: [[193, 163], [128, 186], [281, 143], null],
  mount,
});

xraybox.code:
/**
 * X-ray lightbox: a wall lightbox, a shallow rounded case, with four film
 * sheets clipped along its face. The pointer picks a film by where it is
 * along the box: that film slides up out of its clip and the panel behind it
 * shows, bright, while its neighbours slide a little after it. At rest the
 * films hang at uneven heights, one panel showing, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (riffle); the hit is each film's
 * rest centre on screen, which never moves.
 */
const {
  Cam, facing, fillet, fit, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, W = 22, GAP = 6, X0 = 7, D = 6, ZB = 4, ZT = 66, FZ = 13, FH = 44, LIFT = 26, BUMP = 6;
const X1 = X0 + N * W + (N - 1) * GAP + 7;
const REST = [3, 0, 9, 1], FAV = 2;
const fx = (k) => X0 + k * (W + GAP);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[0, 0, ZB], [X1, 0, ZB], [0, D + 3, ZB], [X1, D + 3, ZB], [0, 0, FZ + FH + LIFT], [X1, D + 3, FZ + FH + LIFT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // a flat rounded rectangle on a face of constant y
  const face = (y, x0, z0, x1, z1, r) => poly(fillet([[x0, z0], [x1, z0], [x1, z1], [x0, z1]], [r, r, r, r], 4).map(([x, z]) => P(x, y, z)));

  // the case, its glass panel's edge, and the cells the films cover
  const [r0, i0] = rings(0, 0, X1, D, 4, 1.4);
  put(solid(g), prism(P, front, r0, i0, ZB, ZT));
  mk("path", { class: "nf lo", d: face(D, 3, ZB + 4, X1 - 3, ZT - 4, 2.5) }, g);
  const films = [];
  for (let k = 0; k < N; k++) {
    const cell = mk("path", { class: "nf lo", d: face(D, fx(k) - 1.2, FZ - 1.5, fx(k) + W + 1.2, ZT - 6, 1.5) }, g);
    films.push({ k, x: fx(k), cell, z: tween(REST[k]), last: NaN });
  }
  for (const f of films) {
    f.s = solid(g);
    f.img = mk("path", { class: "nf lo" }, f.s.g);
  }
  // the clips that hold each film along the top
  for (const f of films) {
    const [rc, ic] = rings(f.x + W / 2 - 4, D + 1.3, f.x + W / 2 + 4, D + 3.4, 0.9, 0.4);
    put(solid(g), prism(P, front, rc, ic, ZT - 11, ZT - 6));
  }

  function draw(f, lift) {
    if (lift === f.last) return;
    f.last = lift;
    const z0 = FZ + lift, z1 = z0 + FH;
    const [rf, inf] = rings(f.x, D + 0.3, f.x + W, D + 1.3, 1.2, 0.3);
    put(f.s, prism(P, front, rf, inf, z0, z1));
    f.img.setAttribute("d", face(D + 1.3, f.x + 3, z0 + 4, f.x + W - 3, z1 - 9, 3));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    films.forEach((f) => { draw(f, tval(f.z, now)); if (!tdone(f.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: each film's rest centre on screen; the nearest along x, inside the case's height
  const cx = films.map((f) => P(f.x + W / 2, D, (FZ + ZT) / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    films.forEach((f, k) => {
      const top = P(f.x + W / 2, D, ZT + 6)[1], bot = P(f.x + W / 2, D, ZB - 4)[1], d = Math.abs(sx - cx[k][0]);
      if (sy > top && sy < bot && d < bd) { bd = d; best = k; }
    });
    return bd < 30 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    films.forEach((f, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : Math.max(1, BUMP - 2 * Math.abs(k - a));
      tset(f.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      f.s.sil.classList.toggle("hi", on);
      f.cell.setAttribute("class", on ? "nf hi" : "nf lo");
    });
    read.textContent = a < 0 ? "rest" : "film " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "xraybox",
  means: "An X-ray lightbox: the film under the pointer slides up out of its clip and its panel lights, the others slide a little after.",
  rules: [1, 2, 4, 5],
  range: [0, 45, 90],
  tour: [[132, 142], [175, 164], [218, 185], null],
  mount,
});

firstaidkit.code:
/**
 * First aid kit: an open case on a table, its lid standing up behind it, four
 * compartments along its top holding a bandage roll, a plaster box, a bottle
 * and a roll of tape. The pointer picks the compartment nearest it: that item
 * lifts clear out of its slot, the others lift less the farther they are,
 * staggered from it. At rest the items sit at uneven depths, the bottle
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the hit is on a fixed
 * plane through the case's top.
 */
const {
  Cam, circ, clamp, facing, fit, open, poly, prism, proj, rings, ringAt, rrect, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, SX = 25, X0 = 13, Y1 = 34, YC = 17, TOP = 18, CLEAR = 8;
const X1 = X0 + (N - 1) * SX + 13;
const FALL = [1, 0.5, 0.24, 0.12], FAV = 2;
// each item: its kind, height, and how much of it shows above the case at rest
const ITEMS = [{ kind: "roll", H: 20, vis: 6 }, { kind: "box", H: 18, vis: 3 }, { kind: "bottle", H: 15, vis: 7 }, { kind: "tape", H: 7, vis: 2 }];
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[-12, -8, -4], [X1 + 12, Y1 + 12, -4], [X1 + 12, -8, -4], [-12, Y1 + 12, -4], [0, -6, TOP + 32], [X1, -6, TOP + 32]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the table, the lid standing open behind, the case with its compartments and latch
  const [rt, it] = rings(-12, -8, X1 + 12, Y1 + 12, 7, 1.8);
  put(solid(g), prism(P, front, rt, it, -4, 0));
  const [rl, il] = rings(0, -6, X1, 0, 4, 1.4);
  const lid = solid(g);
  put(lid, prism(P, front, rl, il, TOP - 3, TOP + 30));
  mk("path", { class: "nf lo", d: seg(P(6, 0, TOP + 12), P(X1 - 6, 0, TOP + 12)) + seg(P(6, 0, TOP + 17), P(X1 - 6, 0, TOP + 17)) }, lid.g);
  const [rc, ic] = rings(0, 0, X1, Y1, 6, 1.6);
  const cs = solid(g);
  put(cs, prism(P, front, rc, ic, 0, TOP));
  const slots = [];
  for (let k = 0; k < N; k++) slots.push(poly(ringAt(P, rrect(X0 + k * SX - 11, 4, X0 + k * SX + 11, Y1 - 4, 3, 4), TOP)));
  mk("path", { class: "nf lo", d: slots.join("") }, cs.g);
  const [rk, ik] = rings(X1 / 2 - 6, Y1, X1 / 2 + 6, Y1 + 1.6, 0.7, 0.4);
  put(solid(g), prism(P, front, rk, ik, TOP - 7, TOP - 2));

  const items = ITEMS.map((it, k) => {
    const grp = mk("g", {}, g), parts = [solid(grp), solid(grp), solid(grp)];
    const hole = mk("path", { class: "nf lo" }, grp);
    return { ...it, k, x: X0 + k * SX, parts, hole, t: tween(0), last: NaN };
  });

  function piece(s, ring, inner, z0, z1) {
    const a = Math.max(TOP, z0);
    if (z1 <= a + 0.05) { s.sil.setAttribute("d", ""); s.cr.setAttribute("d", ""); return; }
    put(s, prism(P, front, ring, inner, a, z1));
  }
  function draw(it, t) {
    if (t === it.last) return;
    it.last = t;
    const zb = TOP - it.H + it.vis + t * (it.H - it.vis + CLEAR), zt = zb + it.H, [p0, p1, p2] = it.parts;
    let hole = "";
    if (it.kind === "roll" || it.kind === "tape") {
      const r = it.kind === "roll" ? 8.5 : 7.5;
      piece(p0, disc(it.x, YC, r), disc(it.x, YC, r - 1.2), zb, zt);
      hole = poly(ringAt(P, disc(it.x, YC, r * 0.38, 24), zt));
    } else if (it.kind === "box") {
      const [rb, ib] = rings(it.x - 6, YC - 11, it.x + 6, YC + 11, 2, 1);
      piece(p0, rb, ib, zb, zt);
      hole = open([P(it.x - 6, YC + 4, zt), P(it.x + 6, YC + 4, zt)]);
    } else {
      piece(p0, disc(it.x, YC, 7), disc(it.x, YC, 5.8), zb, zt);
      piece(p1, disc(it.x, YC, 2.8, 20), null, zt, zt + 3);
      piece(p2, disc(it.x, YC, 3.6, 24), disc(it.x, YC, 2.8, 24), zt + 3, zt + 7);
    }
    it.hole.setAttribute("d", zt > TOP ? hole : "");
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    items.forEach((it) => { draw(it, tval(it.t, now)); if (!tdone(it.t, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: the pointer on the plane through the case's top, nearest compartment along x
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TOP);
    if (x < -6 || x > X1 + 6 || y < -8 || y > Y1 + 6) return -1;
    return clamp(Math.round((x - X0) / SX), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      tset(it.t, a < 0 ? 0 : FALL[Math.abs(k - a)], now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      it.parts.forEach((p) => p.sil.classList.toggle("hi", on));
    });
    read.textContent = a < 0 ? "rest" : "slot " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

