jamjars.code:
/**
 * Jam jars: six jars of different sizes on a pantry shelf, a back board
 * behind them, each jar with a screw lid and a shoulder line. The pointer
 * picks a jar by where it stands: its lid unscrews, turning and lifting, and
 * the lids beside it loosen a little, staggered from it. At rest one lid is
 * half off, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the pick is the jar
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, ringAt, open, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = [8, 6.5, 9, 7, 8.5, 6.5], H = [22, 17, 27, 19, 24, 16], LH = 4, LIFT = 12, FAV = 3, Y = 12;
const xs = []; { let x = 4; for (const r of R) { xs.push(x + r); x += 2 * r + 4; } }
const X1 = xs[xs.length - 1] + R[R.length - 1] + 4;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-2, -6, -5], [X1 + 2, 28, -5], [X1 + 2, -6, 50], [-2, -6, 50], [-2, 28, -5]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  { const [r, i] = rings(-2, -6, X1 + 2, -3, 1, 0.5); put(solid(g), prism(P, front, r, i, -5, 50)); }
  { const [r, i] = rings(-2, -3, X1 + 2, 28, 2, 1); put(solid(g), prism(P, front, r, i, -5, 0)); }

  const jars = R.map((r, k) => {
    const x = xs[k], grp = mk("g", {}, g), body = solid(grp);
    put(body, prism(P, front, disc(x, Y, r), disc(x, Y, r - 1.2), 0, H[k]));
    mk("path", { class: "nf lo", d: open(ringAt(P, disc(x, Y, r, 32).filter(front), H[k] - 4)) }, body.g);
    const lid = solid(grp), mark = mk("path", { class: "nf lo" }, lid.g);
    return { k, x, r, h: H[k], lid, mark, z: tween(k === FAV ? LIFT * 0.55 : 0), last: NaN };
  });

  function draw(j, lift) {
    if (lift === j.last) return;
    j.last = lift;
    const z0 = j.h + lift * 0.9, rr = j.r + 0.6;
    put(j.lid, prism(P, front, disc(j.x, Y, rr), disc(j.x, Y, rr - 1), z0, z0 + LH));
    // the knurl marks turn with the lift: the lid unscrews as it rises
    let d = "";
    for (let m = 0; m < 6; m++) {
      const a = (m / 6) * Math.PI * 2 + lift * 0.22, c = Math.cos(a - Math.PI / 4);
      if (c < 0.25) continue;
      const px = j.x + rr * Math.cos(a), py = Y + rr * Math.sin(a);
      d += seg(P(px, py, z0 + 1), P(px, py, z0 + LH - 1));
    }
    j.mark.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const j of jars) { draw(j, tval(j.z, now)); if (!tdone(j.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = jars.map((j) => P(j.x, Y, j.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 18 && Math.abs(mids[best][1] - sy) < 55 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    jars.forEach((j, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.55 : 0) : dd === 0 ? LIFT : dd === 1 ? 3 : dd === 2 ? 1 : 0;
      tset(j.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      j.lid.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "jar " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "jamjars",
  means: "Six jam jars on a pantry shelf: the lid of the jar under the pointer unscrews and lifts, its neighbours loosen a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[160, 152], [212, 180], [259, 208], null],
  mount,
});

keyboards.code:
/**
 * Keyboard keys: one keyboard lying on the desk, a low case holding four
 * staggered rows of keycaps and a long space bar. The pointer presses the
 * keys: the key under it goes down the deepest and is bright, and the keys
 * around it give a little, falling off with distance. At rest a few keys
 * sit half pressed in a soft ripple, one bright. The slider is the reach.
 *
 * The pattern: a field answering a point (terrain's falloff, a spring per
 * key); the hit is on the keycaps' rest top, a plane that never moves.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NC = 10, KS = 9, G = 1.6, CASE = 4, KT = 11, DEEP = 5, FAV = [1, 4];
const OFF = [0, 2.5, 4.5, 7];
const W = NC * (KS + G) + 7 + 2 * G + 4, Dp = 5 * (KS + G) + 2 * G + 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[0, 0, 0], [W, Dp, 0], [W, 0, KT], [0, Dp, KT], [0, 0, KT], [W, Dp, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(0, 0, W, Dp, 4, 1.6);
  put(solid(g), prism(P, front, cr, ci, 0, CASE));

  const keys = [];
  for (let r = 0; r < 4; r++) for (let c = 0; c < NC - (r === 3 ? 1 : 0); c++) {
    const x0 = 2 + G + OFF[r] + c * (KS + G), y0 = 2 + G + r * (KS + G);
    keys.push({ r, c, x0, y0, x1: x0 + KS, y1: y0 + KS });
  }
  const sx0 = 2 + G + 3 * (KS + G) - 2, sy0 = 2 + G + 4 * (KS + G);
  keys.push({ r: 4, c: 0, x0: sx0, y0: sy0, x1: sx0 + 5 * (KS + G) - G + 4, y1: sy0 + KS });
  for (const k of keys) {
    k.cx = (k.x0 + k.x1) / 2; k.cy = (k.y0 + k.y1) / 2;
    // the rest ripple: a soft wave across the board, never flat
    k.rest = clamp(0.5 + 0.45 * Math.sin(k.cx * 0.09 + k.cy * 0.14), 0, 1) * 0.9;
    k.sp = spring(k.rest);
    k.ring = rings(k.x0, k.y0, k.x1, k.y1, 1.6, 0.9);
    k.drawn = NaN;
  }
  keys.sort((a, b) => a.cx + a.cy - (b.cx + b.cy));
  for (const k of keys) k.el = solid(g);

  function draw(k) {
    const d = k.sp.x;
    if (Math.abs(d - k.drawn) < 1e-3) return;
    k.drawn = d;
    put(k.el, prism(P, front, k.ring[0], k.ring[1], CASE - 0.5, KT - d));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const k of keys) { if (stepS(k.sp, dt)) m = true; draw(k); }
    return m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = null, bd = Infinity;
    if (over) for (const k of keys) {
      const dx = Math.max(k.x0 - over[0], 0, over[0] - k.x1), dy = Math.max(k.y0 - over[1], 0, over[1] - k.y1);
      const d = Math.hypot(dx, dy);
      if (d < bd) { bd = d; near = k; }
    }
    if (bd > 3) near = null;
    const R = 10 + 22 * reach;
    for (const k of keys) {
      let t = k.rest;
      if (near) {
        const d = Math.hypot(k.cx - near.cx, k.cy - near.cy) / R;
        t = k === near ? DEEP : d >= 1 ? 0.15 : DEEP * 0.62 * Math.pow(1 - d, 2) + 0.15;
      }
      k.sp.t = t;
      k.el.sil.classList.toggle("hi", near ? k === near : k.r === FAV[0] && k.c === FAV[1]);
    }
    read.textContent = near ? (near.r === 4 ? "space" : `key ${near.c + 1}·${near.r + 1}`) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { over = unproj(C, p[0], p[1], KT); retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

