rowingmachine.code:
/**
 * Rowing machine: a long rail on two feet, a round flywheel housing at the
 * front, footrests by it, a seat on the rail and a handle on its chain. The
 * pointer is the stroke: the seat slides along the rail to stand under it and
 * the handle comes back with it, the chain paying out from the housing. At
 * rest the seat sits near the catch and the handle is bright. The
 * slider is the length of the stroke.
 *
 * The pattern: one part follows the pointer along a line (a spring on where),
 * picked on the plane of the rail top, which never moves.
 */
const {
  Cam, clamp, facing, fit, hull, lerp, poly, prism, proj, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const RZ = 13, S0 = 38, REST = 0.1, DC = [10, 23], DR = 13;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let len = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-2, -16, 0], [124, 16, 0], [124, -16, 0], [-2, 16, 0], [10, 0, 37], [S0 + 80, 0, 20]], 200, 172);
  const P = proj(C), front = facing(C);

  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1, par = g) => { const [ri, ii] = rings(x0, y0, x1, y1, r, b); const s = solid(par); put(s, prism(P, front, ri, ii, z0, z1)); return s; };
  box(-2, -15, 24, 15, 3, 1.2, 0, 4);
  box(5, -4, 15, 4, 1.5, 0.6, 4, 12);
  // the housing: a drum on its side, the hull of its two faces
  const face = (y, r) => Array.from({ length: 40 }, (_v, i) => { const t = (i / 40) * Math.PI * 2; return P(DC[0] + r * Math.cos(t), y, DC[1] + r * Math.sin(t)); });
  const drum = solid(g);
  drum.sil.setAttribute("d", poly(hull(face(-9, DR).concat(face(9, DR)))));
  drum.cr.setAttribute("d", poly(face(9, DR - 1.4)) + poly(face(9, 3.5)));
  box(16, -3, 122, 3, 1.4, 0.6, RZ - 4, RZ);
  box(112, -14, 124, 14, 2.5, 1, 0, RZ - 4);
  box(26, -13, 32, -4, 1.2, 0.5, RZ, RZ + 7);
  box(26, 4, 32, 13, 1.2, 0.5, RZ, RZ + 7);

  const chain = mk("path", { class: "dash nf" }, g);
  const handle = solid(g), seat = solid(g);
  const sp = spring(REST);
  let last = NaN;
  function draw(t) {
    const key = t.toFixed(4) + "," + len;
    if (key === last) return;
    last = key;
    const s = S0 + t * len, h = lerp(30, S0 + len - 16, t), hz = 24;
    chain.setAttribute("d", seg(P(DC[0] + DR - 1, 0, hz), P(h, 0, hz)));
    const [hr, hi] = rings(h - 1.3, -11, h + 1.3, 11, 1.2, 0.5);
    put(handle, prism(P, front, hr, hi, hz - 1.3, hz + 1.3));
    const [sr, si] = rings(s - 7, -8, s + 7, 8, 3, 1.3);
    put(seat, prism(P, front, sr, si, RZ, RZ + 5));
  }

  const B = register(stage, (dt) => {
    const moving = stepS(sp, dt);
    draw(clamp(sp.x, -0.05, 1.05));
    return moving;
  });
  bag.add(B.unregister);

  let on;
  function setT(t) {
    sp.t = t === null ? REST : t;
    if ((t === null) !== (on === null) || t !== on) {
      seat.sil.classList.toggle("hi", t !== null);
      handle.sil.classList.toggle("hi", t === null);
      read.textContent = t === null ? "rest" : "stroke " + Math.round(t * 100) + "%";
    }
    on = t;
    B.wake();
  }
  /** The pointer on the rail's top plane: its x along the rail is the stroke. */
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, RZ);
    if (Math.abs(y) > 34 || x < S0 - 22 || x > S0 + len + 22) return null;
    return clamp((x - S0) / len, 0, 1);
  }
  setT(null);
  bag.add(pointer(stage, { move: (p) => setT(hit(p)), leave: () => setT(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { len = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "rowingmachine",
  means: "A rowing machine: the seat slides along the rail to follow the pointer and the handle comes back with it on its chain.",
  rules: [1, 3, 5, 8],
  range: [44, 62, 76],
  tour: [[167, 155], [222, 182], [276, 210], null],
  mount,
});

kettlebells.code:
/**
 * Kettlebells: a two-tier rack, the upper shelf set back and higher, holding
 * seven bells of different sizes, each a round body with an arched handle.
 * The pointer picks a bell by where it sits: it lifts off its shelf, and the
 * bells beside it rock up a little, staggered from it. At rest one bell is
 * half lifted, bright. The slider is the stagger.
 *
 * The pattern: stepped parts; each bell is tested on the plane through its
 * own resting middle, and the one nearest the pointer wins.
 */
const {
  Cam, circ, facing, fit, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const UP = [6, 7.5, 6.5], LO = [9, 7.5, 10.5, 8], FAV = 1, LIFT = 18, GAP = 4;
const ZU = 28, ZL = 4, YU = -17, YL = 6, W = 92;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
function row(rs, y, z) {
  const tot = rs.reduce((s, r) => s + 2 * r, 0) + GAP * (rs.length - 1);
  let x = (W - tot) / 2;
  return rs.map((r) => { const b = { r, x: x + r, y, z }; x += 2 * r + GAP; return b; });
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[-4, -28, 0], [W + 4, 18, 0], [W + 4, -28, 0], [-4, 18, 0], [W / 2, YU, ZU + 16 + LIFT], [10, YU, ZU + 30]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1) => { const [ri, ii] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, ri, ii, z0, z1)); };
  box(-4, -28, W + 4, 18, 3, 1.3, 0, ZL - 1);
  box(-2, -26, 4, -8, 1.5, 0.6, ZL - 1, ZU - 3);
  box(W - 4, -26, W + 2, -8, 1.5, 0.6, ZL - 1, ZU - 3);
  box(-4, -28, W + 4, -6, 2.5, 1.1, ZU - 3, ZU);

  const bells = row(UP, YU, ZU).concat(row(LO, YL, ZL)).map((b, k) => {
    const grp = mk("g", {}, g);
    if (k === UP.length) box(-4, -2, W + 4, 16, 2.5, 1.1, ZL - 1, ZL);
    g.appendChild(grp);
    const arch = mk("path", { class: "sil" }, grp), body = solid(grp);
    return { ...b, k, grp, arch, body, h: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN };
  });

  function draw(b, h) {
    if (h === b.last) return;
    b.last = h;
    const z0 = b.z + h, R = b.r, pts = [];
    for (let i = 0; i <= 8; i++) {
      const s = -0.78 + (i / 8) * 1.62, rr = R * Math.sqrt(Math.max(0.02, 1 - s * s));
      pts.push(...ringAt(P, disc(b.x, b.y, rr), z0 + R * (s + 0.78)));
    }
    b.body.sil.setAttribute("d", poly(hull(pts)));
    b.body.cr.setAttribute("d", poly(ringAt(P, disc(b.x, b.y, R * 0.62), z0 + 0.6)));
    const top = z0 + R * 1.5, out = [], inn = [];
    for (let i = 0; i <= 12; i++) {
      const t = (i / 12) * Math.PI, c = Math.cos(t), s = Math.sin(t);
      out.push(P(b.x + R * 0.72 * c, b.y, top + R * 1.0 * s));
      inn.unshift(P(b.x + R * 0.48 * c, b.y, top + R * 0.72 * s));
    }
    b.arch.setAttribute("d", poly(out.concat(inn)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of bells) { draw(b, tval(b.h, now)); if (!tdone(b.h, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  /** Each bell is tested on the plane through its resting middle; the nearest, in its own radii, wins. */
  function hit([sx, sy]) {
    let best = -1, bd = 1.5;
    for (const b of bells) {
      const [x, y] = unproj(C, sx, sy, b.z + b.r);
      const d = Math.hypot(x - b.x, y - b.y) / (b.r + 3);
      if (d < bd) { bd = d; best = b.k; }
    }
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    bells.forEach((b, k) => {
      const d = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : d === 0 ? LIFT : d === 1 ? 3 : 0;
      tset(b.h, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      b.body.sil.classList.toggle("hi", on); b.arch.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "bell " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "kettlebells",
  means: "Seven kettlebells on a two-tier rack: the bell under the pointer lifts off its shelf, and its neighbours rock up a little.",
  rules: [1, 2, 5, 8],
