metronome.code:
/**
 * Metronome: a pyramid case on a plinth, a scale of ticks up its front face,
 * a pendulum arm pivoting low on that face and a weight that slides along it.
 * The pointer conducts: the arm leans toward it, and the weight slides with
 * the pointer's height, higher for a slower beat. At rest the arm stands at
 * the end of a swing, the weight bright. The slider is how far the arm leans.
 *
 * The pattern: a continuous aim (a spring on the lean, one on the weight); the
 * pointer is read in screen space against the case, which never moves.
 */
const {
  Cam, clamp, facing, fit, hull, open, poly, prism, proj, rad, ringAt, rings, rrect, run, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BW = 20, BD = 15, PL = 5, TOPZ = 72, TW = 5, TD = 4, PIV = 14, ARM = 64, LEAN = 26;
const REST_A = -14, REST_W = 0.667;
const faceY = (z) => BD - ((BD - TD) * (z - PL)) / (TOPZ - PL);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.85);
  fit(C, [[-BW - 3, -BD - 3, 0], [BW + 3, BD + 3, 0], [-BW - 3, BD + 3, 0], [BW + 3, -BD - 3, 0], [0, 0, TOPZ + 4], [-30, 12, PIV + ARM], [30, 12, PIV + ARM]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // plinth, then the tapered case written from its foot and top rings
  const [pr, pi] = rings(-BW - 3, -BD - 3, BW + 3, BD + 3, 3, 1.2);
  put(solid(g), prism(P, front, pr, pi, 0, PL));
  const foot = rrect(-BW, -BD, BW, BD, 3, 6), top = rrect(-TW, -TD, TW, TD, 1.6, 6), inner = rrect(-TW + 1, -TD + 1, TW - 1, TD - 1, 0.8, 6);
  const caseEl = solid(g);
  put(caseEl, { sil: poly(hull(ringAt(P, foot, PL).concat(ringAt(P, top, TOPZ)))), crease: open(ringAt(P, run(inner, front), TOPZ)) });

  // the tempo scale: ticks up the front face, behind the arm
  let ticks = "";
  for (let k = 0; k < 9; k++) { const z = PIV + 18 + k * 5, y = faceY(z) + 0.2, w = k % 2 ? 1.6 : 3; ticks += seg(P(-w, y, z), P(w, y, z)); }
  mk("path", { class: "nf lo", d: ticks }, g);
  put(solid(g), prism(P, front, rings(-3, faceY(PIV) - 1, 3, faceY(PIV) + 2.5, 1.4, 0.5)[0], null, PIV - 3, PIV + 3));

  const arm = mk("path", { class: "nf sil", d: "" }, g);
  const wEl = solid(g);
  const [wr, wi] = rings(-4.5, -2.6, 4.5, 2.6, 1.4, 0.7);
  const sa = spring(REST_A), sw = spring(REST_W, { eps: 0.002 });
  let drawn = "";

  function draw() {
    const a = rad(sa.x), w = clamp(sw.x, 0, 1), key = a.toFixed(4) + w.toFixed(4);
    if (key === drawn) return;
    drawn = key;
    const at = (t) => { const z = PIV + Math.cos(a) * ARM * t; return [Math.sin(a) * ARM * t, faceY(z) + 2.2, z]; };
    const b = at(0), e = at(1);
    arm.setAttribute("d", seg(P(b[0] - 0.5, b[1], b[2]), P(e[0] - 0.5, e[1], e[2])) + seg(P(b[0] + 0.5, b[1], b[2]), P(e[0] + 0.5, e[1], e[2])));
    const m = at(0.38 + w * 0.5), sh = (r) => r.map((q) => ({ ...q, u: q.u + m[0], v: q.v + m[1] + 0.6 }));
    put(wEl, prism(P, front, sh(wr), sh(wi), m[2] - 3.5, m[2] + 3.5));
  }
  const B = register(stage, (dt) => { const m1 = stepS(sa, dt), m2 = stepS(sw, dt); draw(); return m1 || m2; });
  bag.add(B.unregister);

  const pv = P(0, faceY(PIV), PIV), tp = P(0, faceY(PIV + ARM), PIV + ARM);
  function set(p) {
    if (p) {
      sa.t = clamp(Math.atan2(p[0] - pv[0], pv[1] - p[1]) * (180 / Math.PI), -LEAN * reach, LEAN * reach);
      sw.t = clamp((pv[1] - 10 - p[1]) / (pv[1] - 10 - tp[1]), 0, 1);
    } else { sa.t = REST_A; sw.t = REST_W; }
    wEl.sil.classList.add("hi");
    read.textContent = p ? "tempo " + Math.round(208 - 168 * sw.t) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => set(Math.abs(p[0] - 200) < 130 && p[1] > 20 && p[1] < 300 ? p : null),
    leave: () => set(null),
  }));
  bag.add(() => svg.replaceChildren());
  set(null);
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "metronome",
  means: "A pyramid metronome: the arm leans toward the pointer and its weight slides with the pointer's height.",
  rules: [3, 5, 8, 9],
  range: [0.4, 1, 1.4],
  tour: [[160, 110], [231, 115], [250, 200], null],
  mount,
});

violins.code:
/**
 * Violins: three violins hung by their scrolls on a wall panel, each a carved
 * body with its waist, a neck, a fingerboard and strings. The pointer takes
 * one down to look at it: the violin under it tilts out off the wall on its
 * hook, bright, and the others settle back flat. At rest they hang a little
 * askew, the first bright. The slider is how far the chosen violin tilts.
 *
 * The pattern: a discrete choice (a tween per violin, staggered by distance);
 * the hit is the nearest rest centre on screen x, which never moves.
 */
const {
  Cam, clamp, fit, mk, poly, proj, rad, seg, solid, open, rings, prism, facing,
  tween, tset, tval, tdone, disposer, pointer, put, register,
} = HL;

const N = 3, GAP = 36, HOOK = 96, WL = -62, WR = 62, WH = 112, REST = [12, 4, 7], FAV = 0, LIFT = 30;
const KW = [27, 28.5, 31, 35, 39, 43, 47, 51, 56, 61, 64.5, 66], KH = [1.7, 6.5, 9, 9.6, 8.2, 6, 6.4, 10, 11.6, 11, 8, 3];
const bout = (w) => { let i = 0; while (KW[i + 1] < w) i++; const t = (w - KW[i]) / (KW[i + 1] - KW[i]); return KH[i] + (KH[i + 1] - KH[i]) * (0.5 - 0.5 * Math.cos(Math.PI * t)); };
// half-width down the violin, w measured from the hook
const half = (w) => w < 7 ? 2.8 * Math.sin(Math.PI * clamp(w / 7, 0.05, 0.95)) + 0.6
  : w < 27 ? 1.7
  : w < 66 ? bout(w)
  : 0;
const WS = []; for (let w = 0; w <= 66; w += 1.5) WS.push(w);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value * LIFT;
  const C = Cam(45, 0.5, 1.75);
  const tiltMax = rad(LIFT * 1.4);
  fit(C, [[WL, -4, 0], [WR, -4, 0], [WR, 0, 0], [WL, -4, WH], [WR, -4, WH], [WR, 66 * Math.sin(tiltMax) + 3, HOOK - 66 * Math.cos(tiltMax)]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [wr, wi] = rings(WL, -4, WR, 0, 2.5, 1.2);
  put(solid(g), prism(P, front, wr, wi, 0, WH));

  const vs = [];
  for (let k = 0; k < N; k++) {
    const cx = (k - 1) * GAP;
    const el = mk("g", {}, g), back = mk("path", { d: "" }, el), face = solid(el);
    mk("circle", { class: "dot off", r: 1.3, cx: P(cx, 0, HOOK + 2)[0], cy: P(cx, 0, HOOK + 2)[1] }, g).before(el);
    vs.push({ k, cx, back, face, tw: tween(REST[k]), drawn: NaN, sx: P(cx, 0, HOOK - 40)[0] });
  }

  function draw(v, now) {
    const t = rad(tval(v.tw, now));
    if (t === v.drawn) return;
    v.drawn = t;
    const at = (u, w, d) => P(v.cx + u, 0.6 + w * Math.sin(t) + d * Math.cos(t), HOOK - w * Math.cos(t) + d * Math.sin(t));
    const outline = (d) => WS.map((w) => at(half(w), w, d)).concat(WS.slice().reverse().map((w) => at(-half(w), w, d)));
    v.back.setAttribute("d", poly(outline(0)));
    v.face.sil.setAttribute("d", poly(outline(3.2)));
    v.face.cr.setAttribute("d", open([at(-1, 8, 3.6), at(-1.3, 46, 3.6), at(1.3, 46, 3.6), at(1, 8, 3.6)]) + seg(at(-0.5, 46, 3.6), at(-1.6, 62, 3.6)) + seg(at(0.5, 46, 3.6), at(1.6, 62, 3.6)) + seg(at(-4.5, 52, 3.6), at(4.5, 52, 3.6)));
  }
  const B = register(stage, (dt, now) => {
    let m = false;
    for (const v of vs) { draw(v, now); if (!tdone(v.tw, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  let hit = null;
  function retarget(now = performance.now()) {
    for (const v of vs) {
      tset(v.tw, hit ? (v === hit ? lift : 2) : REST[v.k], now, hit ? Math.abs(v.k - hit.k) * 45 : 0);
      v.face.sil.classList.toggle("hi", hit ? v === hit : v.k === FAV);
    }
    read.textContent = hit ? "violin " + (hit.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      let best = null, bd = Infinity;
      for (const v of vs) { const d = Math.abs(p[0] - v.sx); if (d < bd) { bd = d; best = v; } }
      const nh = bd < GAP && p[1] > 30 && p[1] < 290 ? best : null;
      if (nh !== hit) { hit = nh; retarget(); }
    },
    leave: () => { hit = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { lift = v * LIFT; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "violins",
  means: "Three violins hung by their scrolls on a wall: the one under the pointer tilts out off the wall on its hook.",
  rules: [1, 2, 4, 5],
  range: [0.5, 1, 1.4],
  tour: [[148, 140], [200, 130], [252, 120], null],
  mount,
});

mixingdesk.code:
/**
 * Mixing desk: an eight-channel audio console, a meter bridge at the back, two
 * gain knobs per channel and a long fader slot in each strip. The pointer is
 * the engineer's hand: the faders near it slide up their slots in a falloff,
 * the one under it furthest and bright. At rest the faders sit at a rough
 * mix, one bright. The slider is the reach, in channels.
 *
 * The pattern: a continuous field (terrain) along one row of strips; the hit is
 * on the plane of the desk's top, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 8, CW = 12, X1 = N * CW, Y1 = 66, TOP = 7, BR = -12, BH = 20;
const DOWN = 58, UP = 24, MIX = [0.3, 0.45, 0.2, 0.55, 0.35, 0.15, 0.5, 0.3], FAV = 3;
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value, over = null;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-3, BR, 0], [X1 + 3, BR, 0], [-3, Y1 + 3, 0], [X1 + 3, Y1 + 3, 0], [-3, BR, BH], [X1 + 3, BR, BH]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1, el = solid(g)) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(el, prism(P, front, o, i, z0, z1)); return el; };

  // the meter bridge, its row of meter windows, then the desk itself
  const bridge = block(-3, BR, X1 + 3, -1, 2.5, 1.2, 0, BH);
  let lines = "";
  for (let k = 0; k < N; k++) { const cx = (k + 0.5) * CW; lines += seg(P(cx, -1, BH - 4), P(cx, -1, 8)); }
  mk("path", { class: "nf lo", d: lines }, bridge.g);
  const desk = block(-3, -1, X1 + 3, Y1 + 3, 3, 1.4, 0, TOP);

  // slots and strip dividers, painted on the desk's top
  let slots = "";
  for (let k = 0; k < N; k++) {
    const cx = (k + 0.5) * CW;
    slots += seg(P(cx, UP - 3, TOP), P(cx, DOWN + 3, TOP));
    if (k) slots += seg(P(k * CW, 3, TOP), P(k * CW, Y1 - 1, TOP));
  }
  mk("path", { class: "nf lo", d: slots }, desk.g);

  const ch = [];
  for (let k = 0; k < N; k++) {
    const cx = (k + 0.5) * CW;
    for (const ky of [6, 14]) put(solid(g), prism(P, front, disc(cx, ky, 2.6), disc(cx, ky, 1.8), TOP, TOP + 2.6));
    const [ring, inner] = rings(-4.5, -3, 4.5, 3, 1.3, 0.8);
    ch.push({ k, cx, ring, inner, el: solid(g), sp: spring(MIX[k], { eps: 0.003 }), drawn: NaN });
  }

  function draw(c) {
    const v = clamp(c.sp.x, 0, 1);
    if (v === c.drawn) return;
    c.drawn = v;
    const y = DOWN - v * (DOWN - UP), sh = (r) => r.map((q) => ({ ...q, u: q.u + c.cx, v: q.v + y }));
    put(c.el, prism(P, front, sh(c.ring), sh(c.inner), TOP, TOP + 6));
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const c of ch) { if (stepS(c.sp, dt)) m = true; draw(c); }
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    const hit = over ? ch[clamp(Math.floor(over[0] / CW), 0, N - 1)] : null;
    for (const c of ch) {
      c.sp.t = over ? Math.max(c === hit ? 1 : 0, MIX[c.k] * 0.2 + falloff(Math.abs(c.cx - over[0]) / (RAD * CW)) * 0.95) : MIX[c.k];
      c.sp.t = clamp(c.sp.t, 0, 1);
      c.el.sil.classList.toggle("hi", over ? c === hit : c.k === FAV);
    }
    read.textContent = hit ? "ch " + (hit.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], TOP);
      over = x > -3 && x < X1 + 3 && y > -6 && y < Y1 + 8 ? [clamp(x, 0, X1 - 0.01), y] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "mixingdesk",
  means: "An eight-channel mixing desk: the faders near the pointer slide up their slots, the one under it furthest and bright.",
  rules: [1, 3, 5, 9],
  range: [1, 2, 3.5],
  tour: [[140, 176], [184, 181], [260, 170], null],
  mount,
});

jewelrydisplay.code:
/**
 * Jewellery display: a two-tier tray with ring cones standing on each tier,
 * each cone holding a ring with a stone. The pointer picks a ring by where it
 * rests: it lifts off its cone and turns its face to the reader, and the
 * rings near it rise a little, staggered by distance. At rest one ring is
 * half lifted, bright. The slider is the stagger.
 *
 * The pattern: one of many (riffle); the pick is the ring whose resting
 * centre on screen is nearest the pointer.
 */
const {
  Cam, circ, fit, hull, open, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X = 72, TB = 12, TF = 5, CH = 18, CR0 = 6, CR1 = 1.8, RR = 4.3, RZ = 8.5, LIFT = 15, FAV = 1;
const SPOTS = [[13, 10, TB], [36, 10, TB], [59, 10, TB], [24, 31, TF], [48, 31, TF]];
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const S2 = Math.SQRT1_2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.1);
  fit(C, [[0, 0, 0], [X, 42, 0], [X, 0, 0], [0, 42, 0], [13, 10, TB + RZ + LIFT + 6], [59, 10, TB + RZ + LIFT + 6]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);

  const tier = (y0, y1, z) => { const [r, i] = rings(0, y0, X, y1, 4, 1.4); put(solid(g), prism(P, () => true, r, i, 0, z)); };
  const items = SPOTS.map(([x, y, z0], k) => ({ k, x, y, z0, lift: tween(k === FAV ? LIFT * 0.6 : 0), turn: tween(k === FAV ? 0.6 : 0), last: "" }));
  function build(it) {
    const grp = mk("g", {}, g);
    it.back = mk("path", { class: "nf sil" }, grp);
    it.stone = mk("circle", { r: 1.6, class: "dot off" }, grp);
    const foot = ringAt(P, disc(it.x, it.y, CR0), it.z0), top = ringAt(P, disc(it.x, it.y, CR1, 16), it.z0 + CH);
    mk("path", { d: poly(hull(foot.concat(top))), class: "sil" }, grp);
    mk("path", { d: poly(top), class: "nf lo" }, grp);
    it.frontP = mk("path", { class: "nf sil" }, grp);
  }
  tier(0, 21, TB);
  items.slice(0, 3).forEach(build);
  tier(21, 42, TF);
  items.slice(3).forEach(build);

  /** A ring turned about the screen-level axis by th, its far side rising toward the reader. */
  function draw(it, lift, th) {
    const key = lift.toFixed(2) + "," + th.toFixed(3);
    if (key === it.last) return;
    it.last = key;
    const cz = it.z0 + RZ + lift, ct = Math.cos(th), st = Math.sin(th);
    const at = (r, t) => { const a = r * Math.cos(t), b = r * Math.sin(t);
      return P(it.x + a * S2 + b * ct * S2, it.y - a * S2 + b * ct * S2, cz - b * st); };
    const half = (r, s) => Array.from({ length: 15 }, (_, i) => at(r, s + (i / 14) * Math.PI));
    it.back.setAttribute("d", open(half(RR, Math.PI)) + open(half(RR - 1.3, Math.PI)));
    it.frontP.setAttribute("d", open(half(RR, 0)) + open(half(RR - 1.3, 0)));
    const s = at(RR + 0.6, -Math.PI / 2);
    it.stone.setAttribute("cx", s[0]); it.stone.setAttribute("cy", s[1]);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.lift, now), tval(it.turn, now)); if (!tdone(it.lift, now) || !tdone(it.turn, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, it.z0 + RZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.hypot(m[0] - sx, (m[1] - sy) * 1.4); if (d < bd) { bd = d; best = k; } });
    return bd < 34 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const lit = k === (a < 0 ? FAV : a);
      const near = a < 0 ? 0 : Math.hypot(it.x - items[a].x, it.y - items[a].y);
      const lift = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : k === a ? LIFT : near < 30 ? 3 : 0;
      const delay = from < 0 ? 0 : (Math.hypot(it.x - items[from].x, it.y - items[from].y) / 23) * stag;
      tset(it.lift, lift, now, delay); tset(it.turn, a < 0 ? (k === FAV ? 0.6 : 0) : k === a ? 1.05 : 0, now, delay);
      it.back.classList.toggle("hi", lit); it.frontP.classList.toggle("hi", lit);
      it.stone.setAttribute("class", lit ? "dot" : "dot off");
    });
    read.textContent = a < 0 ? "rest" : "ring " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "jewelrydisplay",
  means: "A two-tier jewellery tray of ring cones: the ring under the pointer lifts off its cone and turns its face to you.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[174, 118], [275, 167], [204, 198], null],
  mount,
});

sewingmachine.code:
/**
 * Sewing machine: a bed, a pillar with a handwheel, an arm and a head with
 * the needle bar, a spool on top, and a strip of fabric under the needle.
 * The pointer's x is how far the seam has run: the fabric slides through on
 * a spring, the needle bobs with it, and the stitches it has sewn stay on
 * the cloth. At rest the seam is 40% sewn. The slider is the spring's give.
 *
 * The pattern: a continuous input (terrain's spring) on one value.
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rings, ringAt, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BX = 92, BY = 32, BZ = 8, NX = 16, NY = 16, FW = 11, FL = 80, ST = 6, REST = 0.4;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, -30, 0], [BX + 4, BY + 30, 0], [BX, 0, 0], [0, BY + 30, 0], [NX, NY, 60], [BX, NY, 60]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r, b, par = g) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(par); put(s, prism(P, front, o, i, z0, z1)); return s; };

  box(0, 0, BX, BY, 0, BZ, 4, 1.4);
  mk("path", { d: poly(ringAt(P, disc(NX, NY, 2.2, 16), BZ)), class: "nf lo" }, g);
  const cloth = mk("g", {}, g);
  const fab = solid(cloth), stitches = mk("path", { class: "nf lo" }, cloth);
  // the pillar, then the arm and head over the bed, then the needle
  box(66, 6, 86, 26, BZ, 46, 4, 1.4);
  const wheel = (x) => { const pts = [];
    for (const dx of [0, 3]) for (let i = 0; i < 28; i++) { const t = (i / 28) * Math.PI * 2; pts.push(P(x + dx, 16 + 10 * Math.cos(t), 30 + 10 * Math.sin(t))); }
    return pts; };
  mk("path", { d: poly(hull(wheel(86))), class: "sil" }, g);
  const rim = Array.from({ length: 28 }, (_, i) => { const t = (i / 28) * Math.PI * 2; return P(89, 16 + 6 * Math.cos(t), 30 + 6 * Math.sin(t)); });
  mk("path", { d: poly(rim), class: "nf lo" }, g);
  box(8, 9, 82, 23, 38, 50, 5, 1.4);
  box(6, 7, 26, 25, 26, 50, 5, 1.4);
  const sp = disc(56, 16, 4.5);
  mk("path", { d: poly(hull(ringAt(P, sp, 50).concat(ringAt(P, sp, 58)))), class: "sil" }, g);
  mk("path", { d: poly(ringAt(P, disc(56, 16, 1.2, 12), 58)), class: "nf lo" }, g);
  const bar = mk("path", { class: "nf sil" }, g), foot = mk("path", { class: "nf" }, g), needle = mk("path", { class: "nf sil hi" }, g);
  const eye = mk("circle", { r: 1.7, class: "dot" }, g);

  const f = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let last = NaN;
  function draw(v) {
    if (v === last) return;
    last = v;
    const off = v * (FL - 24), y0 = -FL / 2 + 26 + off;
    const [o, i] = rings(NX - FW, y0 - FL / 2, NX + FW, y0 + FL / 2, 1.5, 0.6);
    put(fab, prism(P, front, o, i, BZ, BZ + 0.8));
    let d = "";
    for (let y = y0 - FL / 2 + 4; y < NY - 1; y += ST) if (y + ST * 0.6 < NY) d += seg(P(NX, y, BZ + 0.9), P(NX, y + ST * 0.6, BZ + 0.9));
    stitches.setAttribute("d", d);
    const zt = BZ + 1.5 + 9 * (0.5 - 0.5 * Math.cos((off / ST) * Math.PI * 2));
    bar.setAttribute("d", poly(hull(ringAt(P, disc(NX, NY, 1.6, 12), zt + 9).concat(ringAt(P, disc(NX, NY, 1.6, 12), 26)))));
    const [fo, fi] = rings(NX - 4, NY - 2, NX + 4, NY + 5, 1.5, 0.6);
    put({ sil: foot, cr: foot }, { sil: prism(P, front, fo, fi, BZ + 0.9, BZ + 2.2).sil, crease: "" });
    needle.setAttribute("d", seg(P(NX, NY, zt), P(NX, NY, zt + 9)));
    const e = P(NX, NY, zt + 2.5);
    eye.setAttribute("cx", e[0]); eye.setAttribute("cy", e[1]);
    read.textContent = "stitch " + Math.round(v * 100) + "%";
  }
  draw(REST);
  read.textContent = "rest";

  const B = register(stage, (dt) => { const m = stepS(f, dt); draw(f.x); if (!m && f.t === REST) read.textContent = "rest"; return m; });
  bag.add(B.unregister);
  const x0 = P(0, BY, 0)[0], x1 = P(BX, BY, 0)[0];
  bag.add(pointer(stage, {
    move: ([sx]) => { f.t = clamp((sx - x0) / (x1 - x0), 0, 1); B.wake(); },
    leave: () => { f.t = REST; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { f.k = 100 * v; f.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "sewingmachine",
  means: "A sewing machine: the pointer's x runs the seam, the fabric slides under the needle and the needle bobs as it stitches.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.6],
  tour: [[124, 177], [200, 215], [273, 251], null],
  mount,
});

handbags.code:
/**
 * Handbags: a boutique shelf holding a tote with two straps, a box bag with
 * a top handle and a clutch with a wrist loop. The pointer picks a bag by
 * where it stands: it lifts by its handle, and the bags beside it rise a
 * little, staggered from it. At rest the box bag is half lifted, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the pick is the bag
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, fit, facing, hull, open, poly, proj, rrect, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, rings, prism, put, register, solid,
} = HL;

// [x, half width foot, half width top, half depth, height, handle height, handle half span, kind]
const BAGS = [[22, 11, 15, 6, 26, 16, 6, "tote"], [62, 12, 12, 7, 19, 9, 5, "box"], [98, 13, 13, 3.2, 13, 7, 3.5, "clutch"]];
const X = 120, SZ = 5, LIFT = 16, FAV = 1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-4, -6, 0], [X + 4, 18, 0], [X + 4, -6, 0], [-4, 18, 0], [22, 0, SZ + 26 + 16 + LIFT], [98, 0, SZ + 30 + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-4, -12, X + 4, 18, 3, 1.2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));
  const [wr, wi] = rings(-4, -16, X + 4, -12, 1.5, 0.6);
  put(solid(g), prism(P, front, wr, wi, 0, 62));

  const items = BAGS.map(([x, wf, wt, hd, h, hh, hs, kind], k) => {
    const grp = mk("g", {}, g);
    const back = mk("path", { class: "nf lo" }, grp), body = mk("path", { class: "sil" }, grp), cr = mk("path", { class: "nf lo" }, grp), hand = mk("path", { class: "nf sil" }, grp);
    return { k, x, wf, wt, hd, h, hh, hs, kind, back, body, cr, hand, z: tween(k === FAV ? LIFT * 0.55 : 0), last: NaN };
  });

  const arc = (x, y, z, hs, hh) => Array.from({ length: 13 }, (_, i) => { const t = (i / 12) * Math.PI; return P(x - hs * Math.cos(t), y, z + hh * Math.sin(t)); });
  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = SZ + lift, z1 = z0 + it.h;
    const foot = rrect(it.x - it.wf, -it.hd, it.x + it.wf, it.hd, 2.5, 4), top = rrect(it.x - it.wt, -it.hd, it.x + it.wt, it.hd, 1.5, 4);
    const inner = rrect(it.x - it.wt + 1, -it.hd + 1, it.x + it.wt - 1, it.hd - 1, 0.8, 4);
    it.body.setAttribute("d", poly(hull(ringAt(P, foot, z0).concat(ringAt(P, top, z1)))));
    let cr = open(ringAt(P, run(inner, front), z1));
    if (it.kind === "box") cr += " " + open([P(it.x - it.wt, it.hd, z1 - 6), P(it.x + it.wt, it.hd, z1 - 6)]);
    if (it.kind === "clutch") cr += " " + open([P(it.x - it.wt, it.hd, z1), P(it.x, it.hd, z1 - 7), P(it.x + it.wt, it.hd, z1)]);
    it.cr.setAttribute("d", cr);
    if (it.kind === "tote") {
      it.back.setAttribute("d", open(arc(it.x, -it.hd + 1, z1, it.hs, it.hh)));
      it.hand.setAttribute("d", open(arc(it.x, it.hd - 1, z1, it.hs, it.hh)));
    } else if (it.kind === "box") {
      it.hand.setAttribute("d", open(arc(it.x, 0, z1, it.hs, it.hh)) + open(arc(it.x, 0, z1, it.hs - 1.5, it.hh - 1.5)));
    } else {
      it.hand.setAttribute("d", open(arc(it.x + it.wt - 3, 0, z1, it.hs, it.hh)));
    }
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 0, SZ + it.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 34 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.55 : 0) : d === 0 ? LIFT : d === 1 ? 3 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const lit = k === (a < 0 ? FAV : a);
      it.body.classList.toggle("hi", lit); it.hand.classList.toggle("hi", lit);
    });
    read.textContent = a < 0 ? "rest" : "bag " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "handbags",
  means: "A tote, a box bag and a clutch on a boutique shelf: the bag under the pointer lifts by its handle, its neighbours a little.",
  rules: [1, 2, 5, 6],
  range: [0, 50, 100],
  tour: [[154, 127], [210, 165], [264, 206], null],
  mount,
});

mortarboard.code:
/**
 * Lecture podium: a lectern on a low dais, a book on its desk and a gooseneck
 * microphone at the desk's far corner. The microphone swings on a spring to
 * face the pointer wherever it is over the floor. At rest it leans toward the
 * hall, its head bright. The slider is how quickly it follows.
 *
 * The pattern: a continuous aim (office chairs' spring, on one angle); the hit
 * is on the floor's plane, which never moves.
 */
const {
  Cam, circ, facing, fit, open, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const MX = 10, MY = -8, TOP = 50, REST = 2.1;
const turn = (ring, a, cx, cy) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-42, -32, -6], [42, 32, -6], [42, -32, -6], [-42, 32, -6], [MX, MY, TOP + 24], [MX - 16, MY, TOP + 22], [MX + 16, MY, TOP + 22]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(g); put(s, prism(P, front, o, i, z0, z1)); return s; };
  box(-42, -32, 42, 32, 4, 1.6, -6, 0);
  box(-16, -12, 16, 12, 3, 1.2, 0, 4);
  box(-12, -9, 12, 9, 2.5, 1, 4, TOP - 3);
  box(-17, -13, 17, 13, 2.5, 1.2, TOP - 3, TOP);
  box(-10, -3, 6, 9, 1, 0.5, TOP, TOP + 2.6);
  mk("path", { class: "nf lo", d: seg(P(-2, -3, TOP + 2.6), P(-2, 9, TOP + 2.6)) + seg(P(-10, 9, TOP + 1.3), P(6, 9, TOP + 1.3)) }, g);
  put(solid(g), prism(P, front, circ(2.8, 24).map((q) => ({ ...q, u: q.u + MX, v: q.v + MY })), null, TOP, TOP + 1.6));
  const neck = mk("path", { class: "nf sil" }, g);
  const head = solid(g);
  head.sil.classList.add("hi");
  const HEAD = rings(8, -1.7, 15, 1.7, 1.5, 0.6);

  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const pts = [P(MX, MY, TOP + 1.6)];
    for (let i = 0; i <= 10; i++) {
      const t = (i / 10) * Math.PI / 2, rr = 9 * (1 - Math.cos(t)), zz = TOP + 10 + 9 * Math.sin(t);
      pts.push(P(MX + rr * Math.cos(a), MY + rr * Math.sin(a), zz));
    }
    neck.setAttribute("d", open(pts));
    put(head, prism(P, front, turn(HEAD[0], a, MX, MY), turn(HEAD[1], a, MX, MY), TOP + 17.2, TOP + 20.8));
    // the head goes behind the neck when it points away
    if (Math.cos(a) + Math.sin(a) < 0) neck.after(head.g); else head.g.after(neck);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function aimAt(over) {
    const aim = over ? Math.atan2(over[1] - MY, over[0] - MX) : REST;
    sp.t = sp.t + wrap(aim - sp.t);
    if (over) { const d = Math.round((aim * 180) / Math.PI); read.textContent = "aim " + ((d % 360) + 360) % 360 + "°"; } else read.textContent = "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      aimAt(Math.hypot(x - MX, y - MY) < 4 || Math.hypot(x, y) > 110 ? null : [x, y]);
    },
    leave: () => aimAt(null),
  }));
  bag.add(() => svg.replaceChildren());
  aimAt(null);
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "mortarboard",
  means: "A lectern with a book and a gooseneck microphone: the microphone swings round to face the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[72, 201], [328, 219], [249, 93], null],
  mount,
});

chalkboard.code:
/**
 * Chalkboard: a classroom board on a frame of two posts on feet and a top
 * rail, with two panels, one behind the other, and a chalk tray. The front
 * panel slides along its track on a spring toward the pointer, carrying its
 * chalk lines. At rest it stands a third of the way along, bright.
 * The slider is how quickly it follows.
 *
 * The pattern: a continuous slide; the hit maps the pointer's screen x onto
 * the board's resting line, which never moves.
 */
const {
  Cam, clamp, facing, fit, open, prism, proj, rings, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 110, PW = 62, Z0 = 22, Z1 = 70, YF = 2.8, REST = 0.3;
const SPAN = W - 4 - PW;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-6, -16, 0], [W + 6, 20, 0], [W + 6, -16, 0], [-6, 20, 0], [-4, -2, 76], [W + 4, -2, 76]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1, parent = g) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(parent); put(s, prism(P, front, o, i, z0, z1)); return s; };
  box(-5, -16, 1, 20, 2, 0.8, 0, 3);
  box(-4, -1.5, 0, 6, 1.2, 0.5, 3, 72);
  box(W - PW - 2, 0, W - 2, 2.2, 1, 0.5, Z0, Z1);
  const fp = mk("g", {}, g);
  const panel = solid(fp), chalk = mk("path", { class: "nf lo" }, fp);
  panel.sil.classList.add("hi");
  box(0, 5.4, W, 10, 1, 0.5, 18, 20.2);
  mk("path", { class: "nf lo", d: seg(P(70, 7.5, 20.4), P(76, 7.5, 20.4)) }, g);
  box(W - 1, -16, W + 5, 20, 2, 0.8, 0, 3);
  box(W, -1.5, W + 4, 6, 1.2, 0.5, 3, 72);
  box(-4, -1.5, W + 4, 6, 1.5, 0.6, 72, 75.5);

  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    if (Math.abs(sp.x - drawn) < 1e-4) return;
    drawn = sp.x;
    const x0 = 2 + sp.x * SPAN, yf = YF + 2.2;
    const [o, i] = rings(x0, YF, x0 + PW, yf, 1, 0.5);
    put(panel, prism(P, front, o, i, Z0, Z1));
    const ring = [];
    for (let k = 0; k <= 24; k++) { const t = (k / 24) * Math.PI * 2; ring.push(P(x0 + 44 + 8 * Math.cos(t), yf, 48 + 8 * Math.sin(t))); }
    chalk.setAttribute("d", open([P(x0 + 9, yf, 34), P(x0 + 29, yf, 34), P(x0 + 19, yf, 54), P(x0 + 9, yf, 34)]) + open(ring) + seg(P(x0 + 10, yf, 62), P(x0 + 54, yf, 62)));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  const a0 = P(0, YF, 46)[0], a1 = P(1, YF, 46)[0] - a0;
  function slideTo(sx, sy) {
    let t = null;
    if (sx != null) {
      const x = (sx - a0) / a1;
      if (x > -12 && x < W + 12 && sy > P(x, YF, 80)[1] - 6 && sy < P(x, YF, 0)[1] + 6) t = clamp((x - 2 - PW / 2) / SPAN, 0, 1);
    }
    sp.t = t == null ? REST : t;
    read.textContent = t == null ? "rest" : "panel " + Math.round(t * 100) + "%";
    B.wake();
  }
  bag.add(pointer(stage, { move: (p) => slideTo(p[0], p[1]), leave: () => slideTo(null) }));
  bag.add(() => svg.replaceChildren());
  slideTo(null);
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "chalkboard",
  means: "A two-panel classroom chalkboard on a frame: the front panel slides along its track toward the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[109, 113], [250, 147], [180, 135], null],
  mount,
});

bookcart.code:
/**
 * Library cart: a two-shelf cart on casters with a push handle at one end,
 * books standing on both shelves. The book under the pointer lifts out: on
 * the top shelf it rises clear, on the lower shelf it slides out toward the
 * reader. At rest one top-shelf book stands a little raised, bright. The
 * slider is how far a book comes out.
 *
 * The pattern: one of many in two rows (bookshelf); the pick is the book whose
 * resting middle on screen is nearest the pointer.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 96, D = 26, LO = 15, HI = 45, FAV = 4;
const SPEC = [[9, 24], [7, 21], [11, 26], [8, 22], [10, 25], [7, 20], [12, 20], [9, 17], [10, 21], [8, 18], [11, 19]];
const books = [];
{ let x = 3; SPEC.forEach(([w, h], k) => { if (k === 6) x = 4; const top = k < 6; books.push({ k, w, h, x0: x, top, z0: top ? HI : LO }); x += w + (top ? 2.2 : 3.5); }); }

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-3, 0, 0], [L + 3, D + 16, 0], [L + 3, 0, 0], [-3, D + 16, 0], [0, 0, HI + 26 + 16], [L, 0, HI + 26]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, o, i, z0, z1)); };
  const wheel = (x, y) => put(solid(g), prism(P, front, circ(2.6, 20).map((q) => ({ ...q, u: q.u + x, v: q.v + y })), null, 0, 4));
  wheel(-1.5, 1.5); wheel(-1.5, D - 1.5);
  box(-3, 0, 0, 3, 0.8, 0.4, 4, 66); box(-3, D - 3, 0, D, 0.8, 0.4, 4, 66);
  box(-3, 0, 0, D, 1, 0.5, 63, 66);
  box(0, 0, L, D, 2.5, 1.2, LO - 3, LO);
  const lowG = mk("g", {}, g);
  box(0, 0, L, D, 2.5, 1.2, HI - 3, HI);
  const topG = mk("g", {}, g);
  wheel(L + 1.5, 1.5); wheel(L + 1.5, D - 1.5);
  box(L, 0, L + 3, 3, 0.8, 0.4, 4, HI); box(L, D - 3, L + 3, D, 0.8, 0.4, 4, HI);

  for (const b of books) {
    b.el = solid(b.top ? topG : lowG);
    b.band = mk("path", { class: "nf lo" }, b.el.g);
    b.y = tween(0); b.z = tween(b.k === FAV ? 5 : 0); b.last = "";
  }
  function draw(b, y, z) {
    const key = y.toFixed(2) + "," + z.toFixed(2);
    if (key === b.last) return;
    b.last = key;
    const y0 = 4 + y, y1 = 22 + y, zb = b.z0 + z;
    const [o, i] = rings(b.x0, y0, b.x0 + b.w, y1, 1.2, 0.6);
    put(b.el, prism(P, front, o, i, zb, zb + b.h));
    const f = (zz) => seg(P(b.x0 + 0.8, y1, zb + zz), P(b.x0 + b.w - 0.8, y1, zb + zz));
    b.band.setAttribute("d", f(b.h - 5) + f(4));
  }

  let painted = "";
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of books) { draw(b, tval(b.y, now), tval(b.z, now)); if (!tdone(b.y, now) || !tdone(b.z, now)) moving = true; }
    const order = books.filter((b) => !b.top).sort((a, c) => a.x0 + tval(a.y, now) * 1.4 - (c.x0 + tval(c.y, now) * 1.4));
    const key = order.map((b) => b.k).join();
    if (key !== painted) { painted = key; for (const b of order) lowG.appendChild(b.el.g); }
    return moving;
  });
  bag.add(B.unregister);

  const mids = books.map((b) => P(b.x0 + b.w / 2, 22, b.z0 + b.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.hypot((m[0] - sx) * 1.6, m[1] - sy); if (d < bd) { bd = d; best = k; } });
    return bd < 34 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    for (const b of books) {
      const on = b.k === a, mark = b.k === (a < 0 ? FAV : a);
      tset(b.y, on && !b.top ? 14 * reach : 0, now, 0);
      tset(b.z, on ? (b.top ? 16 * reach : 3) : a < 0 && b.k === FAV ? 5 : 0, now, 0);
      b.el.sil.classList.toggle("hi", mark);
    }
    read.textContent = a < 0 ? "rest" : "book " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

