  mount,
});

keyhandover.code:
/**
 * Key tags: an estate agent's key board with two rows of four hooks, a key
 * and a tag hanging from each ring. The pointer picks a key on the board's
 * face: it swings out on its hook and its tag turns over, so its punched hole
 * changes side; the keys beside it sway a little, staggered from it. At rest
 * the keys hang at uneven angles, one bright. The slider is the stagger.
 *
 * The pattern: one of many on a face (lockers), read on the board's face
 * plane, which never moves; tweens for the swing and the turn.
 */
const {
  Cam, circ, clamp, facing, fillet, fit, poly, prism, proj, rings, seg, tset, tval, tdone, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NC = 4, NR = 2, CW = 26, RH = 44, M = 8, W = 2 * M + NC * CW, H = NR * RH + 10, D = 6, Y = D + 1.5, FAV = 5;
const LEAN = [4, -3, 6, -2, -5, 3, 12, -4];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, 0], [W, D + 4, 0], [W, 0, 0], [0, D + 4, 0], [0, 0, H], [W, 0, H], [0, D + 4, H]], 200, 166);
  const P = proj(C), front = facing(C);

  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, D, 3, 1.3);
  put(solid(g), prism(P, front, br, bi, 0, H));
  const keys = [];
  for (let r = 0; r < NR; r++) for (let c = 0; c < NC; c++) {
    const i = r * NC + c, hx = M + CW * (c + 0.5), hz = H - 8 - r * RH;
    mk("path", { d: seg(P(hx, D, hz), P(hx, Y + 1, hz)), class: "nf" }, g);
    const kg = mk("g", {}, g);
    keys.push({ i, c, r, hx, hz, key: mk("path", {}, kg), tag: mk("path", {}, kg), hole: mk("path", { class: "nf lo" }, kg), sw: tween(LEAN[i]), fl: tween(0), last: "" });
  }
  const ring = circ(1, 10);
  const circle = (u, v, R) => poly(ring.map((q) => P(u + q.u * R, Y, v + q.v * R)));

  function draw(k, a, f) {
    const sig = a.toFixed(2) + "," + f.toFixed(3);
    if (sig === k.last) return;
    k.last = sig;
    const t = a * Math.PI / 180, s = Math.sin(t), co = Math.cos(t);
    const at = (du, dv) => [k.hx + du * co + dv * s, k.hz - du * s + dv * co];
    // the key: a bow on the ring, a shaft and two teeth, all swung about the hook
    const [bu, bv] = at(0, -6.5);
    let d = circle(bu, bv, 3.4) + circle(bu, bv, 1.3);
    const sh = [[-0.9, -9.6], [0.9, -9.6], [0.9, -24], [-0.9, -24]].map(([u, v]) => P(...at(u, v).slice(0, 1), Y, at(u, v)[1]));
    d += poly(fillet(sh, [0.4, 0.4, 0.4, 0.4], 2));
    const tooth = (v) => poly([[0.9, v], [3.6, v], [3.6, v - 2.2], [0.9, v - 2.2]].map(([u, w]) => { const q = at(u, w); return P(q[0], Y, q[1]); }));
    d += tooth(-17.5) + tooth(-21.8);
    k.key.setAttribute("d", d);
    // the tag: hangs beside the key from the same ring and turns about its own string
    const [tu, tv] = at(-7.5, -4), ph = f * Math.PI, cw = Math.cos(ph), sw = Math.sin(ph);
    const T = (u, v) => P(tu + u * cw, Y + 2 + u * sw, tv + v);
    k.tag.setAttribute("d", seg(P(...at(0, -3.1).slice(0, 1), Y, at(0, -3.1)[1]), T(0, 0)) + poly(fillet([T(-3.6, 0), T(3.6, 0), T(3.6, -15), T(-3.6, -15)], [1.2, 1.2, 1.2, 1.2], 3)));
    k.hole.setAttribute("d", poly(ring.map((q) => T(-1.6 + q.u * 0.9, -2.6 + q.v * 0.9))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const k of keys) { draw(k, tval(k.sw, now), tval(k.fl, now)); if (!tdone(k.sw, now) || !tdone(k.fl, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  /** The key under the point, read on the board's face plane (y = D), which never moves. */
  function hit([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + D * s) / c, Yw = x * s + D * c, z = (Yw * C.k - (sy - C.oy) / C.S) / zf;
    if (x < M || x > W - M || z < 4 || z > H - 4) return -1;
    return clamp(Math.floor((H - 4 - z) / RH), 0, NR - 1) * NC + clamp(Math.floor((x - M) / CW), 0, NC - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const ak = a >= 0 ? keys[a] : null, fk = from >= 0 ? keys[from] : null;
    keys.forEach((k) => {
      const d = ak ? Math.abs(k.c - ak.c) + Math.abs(k.r - ak.r) : 9;
      const sw = !ak ? LEAN[k.i] : d === 0 ? 24 : d === 1 ? (k.c < ak.c ? -7 : 7) : d === 2 ? (k.c < ak.c ? -3 : 3) : 0;
      const delay = fk ? (Math.abs(k.c - fk.c) + Math.abs(k.r - fk.r)) * stag : 0;
      tset(k.sw, clamp(sw, -26, 26), now, delay);
      tset(k.fl, d === 0 ? 1 : 0, now, delay);
      const on = k.i === (a < 0 ? FAV : a);
      k.key.classList.toggle("sil", true); k.key.classList.toggle("hi", on); k.tag.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "key " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "keyhandover",
  means: "A key board of eight hooks: the key under the pointer swings out and its tag turns over, the keys beside it sway.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[259, 146], [175, 140], [200, 215], null],
  mount,
});

blinds.code:
/**
 * Window blinds: a wall with a window opening, its sill and a headrail, and
 * eleven horizontal slats hung in front. The pointer's height on the wall's
 * face sets how far the slats tilt open, low closed, high open, and the slats
 * near it open a little further; the slat under the pointer is bright. Closed
 * slats hide the mullions behind them, open ones let them show. At rest the
 * slats stand a third open with a gentle swell, one slat bright. The slider is
 * the swell's reach.
 *
 * The pattern: a field of parts read on a fixed face plane (lockers), one
 * spring per slat for the continuous height.
 */
const {
  Cam, clamp, fit, fillet, poly, prism, proj, rings, rrect, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid, facing,
} = HL;

const W = 84, H = 104, D = 8, X0 = 12, X1 = W - 12, Z0 = 14, Z1 = H - 16, N = 11, HW = 4.6, FAV = 4;
const SP = (Z1 - 3 - Z0) / N, YM = D + 4;
const zc = (i) => Z1 - 4 - SP * (i + 0.5);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[0, 0, 0], [W, D + 10, 0], [W, 0, 0], [0, D + 10, 0], [0, 0, H], [W, 0, H], [0, D + 10, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const onFace = (y) => (q) => P(q.u, y, q.v);

  const g = mk("g", {}, svg);
  const [wr, wi] = rings(0, 0, W, D, 3, 1.4);
  put(solid(g), prism(P, front, wr, wi, 0, H));
  // the opening and its mullions, painted on the face before the slats
  mk("path", { d: poly(rrect(X0, Z0, X1, Z1, 1.6, 3).map(onFace(D))), class: "nf lo" }, g);
  mk("path", { d: seg(P(W / 2, D, Z0), P(W / 2, D, Z1)) + seg(P(X0, D, (Z0 + Z1) / 2), P(X1, D, (Z0 + Z1) / 2)), class: "nf lo" }, g);
  const [sr, si] = rings(X0 - 5, D - 1, X1 + 5, D + 9, 1.4, 0.8);
  put(solid(g), prism(P, front, sr, si, Z0 - 4, Z0 - 1));
  // slats bottom to top: a higher slat sits nearer the eye
  const slats = [];
  for (let i = N - 1; i >= 0; i--) slats[i] = { el: mk("path", {}, g), s: spring(0), last: NaN };
  slats.forEach((sl) => g.appendChild(sl.el));
  const [hr, hi] = rings(X0 - 3, D, X1 + 3, D + 8, 1.2, 0.7);
  put(solid(g), prism(P, front, hr, hi, Z1 - 3, Z1 + 3));
  const wand = mk("path", { class: "nf lo", d: seg(P(X1, YM, Z1 - 3), P(X1, YM, Z1 - 40)) }, g);

  function draw(sl, i, t) {
    const a = t * Math.PI / 2, dy = Math.sin(a) * HW, dz = Math.cos(a) * HW, z = zc(i);
    const pts = [[X0 + 1, YM - dy, z - dz], [X1 - 1, YM - dy, z - dz], [X1 - 1, YM + dy, z + dz], [X0 + 1, YM + dy, z + dz]].map((p) => P(...p));
    sl.el.setAttribute("d", poly(fillet(pts, [1, 1, 1, 1], 2)));
  }

  const B = register(stage, (dt) => {
    let moving = false;
    slats.forEach((sl, i) => {
      if (stepS(sl.s, dt)) moving = true;
      if (!(Math.abs(sl.s.x - sl.last) <= 1e-4)) { draw(sl, i, sl.s.x); sl.last = sl.s.x; }
    });
    return moving;
  });
  bag.add(B.unregister);

  /** The pointer on the wall's face plane (y = D), which never moves: [x, z]. */
  function onWall([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + D * s) / c, Y = x * s + D * c, z = (Y * C.k - (sy - C.oy) / C.S) / zf;
    return [x, z];
  }
  const fall = (d) => (d < 0.42 ? 1 - (d / 0.42) * 0.69 : Math.max(0.09, 0.31 - (d - 0.42) * 0.6));

  let act = -2, open = 0.34, hz = zc(FAV);
  function aim(a, o, z) {
    slats.forEach((sl, i) => {
      const d = Math.abs(zc(i) - z) / (SP * Math.max(1, reach));
      sl.s.t = clamp(o + (1 - o) * 0.45 * fall(d / 2), 0.05, 0.98);
      sl.el.classList.toggle("sil", true);
      sl.el.classList.toggle("hi", i === (a < 0 ? FAV : a));
    });
    B.wake();
  }
  function move(p) {
    const [x, z] = onWall(p);
    if (x < X0 - 6 || x > X1 + 6 || z < Z0 || z > Z1) return leave();
    const a = clamp(Math.floor((Z1 - 4 - z) / SP), 0, N - 1);
    open = clamp((z - Z0) / (Z1 - Z0), 0, 1);
    act = a;
    aim(a, open * 0.85, z);
    read.textContent = "open " + Math.round(clamp(open * 0.85 + 0.15 * fall(0) * 0.45, 0, 1) * 100) + "%";
  }
  function leave() { act = -1; aim(-1, 0.22, hz); read.textContent = "rest"; }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; aim(act, act < 0 ? 0.22 : open * 0.85, act < 0 ? hz : zc(act)); }, destroy: bag.dispose };
}

hairline({
  name: "blinds",
  means: "Slat blinds over a window: the slats tilt open as the pointer rises, those near it a little further, the one under it bright.",
  rules: [1, 3, 5, 8],
  range: [1, 2, 4],
  tour: [[200, 212], [197, 165], [195, 118], null],
  mount,
});

wheelchairs.code:
/**
 * Wheelchairs: three wheelchairs parked in a row, each a seat, a backrest,
 * a footrest, two large wheels and two casters. The pointer picks a chair by
 * where it stands: it rolls forward out of the row, its wheels turning, and
 * the chairs beside it ease forward a little, staggered from it. At rest the
 * middle chair stands half out, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 36, R = 11, ROLL = 18, FAV = 1, REST = [4, 11, 1];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.55);
  const X1 = (N - 1) * STEP;
  fit(C, [[-14, -16, 0], [X1 + 14, -16, 0], [-14, 16 + ROLL, 0], [X1 + 14, 16 + ROLL, 0], [0, -12, 30], [X1, -12, 30]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r = 1.5, b = 0.7) => { const [a, i] = rings(x0, y0, x1, y1, r, b); return prism(P, front, a, i, z0, z1); };

  function wheel(wx, cy, cz, rr, w) {
    const pts = [];
    for (const xx of [wx - w, wx + w]) for (let i = 0; i < 28; i++) { const t = (i / 28) * Math.PI * 2; pts.push(P(xx, cy + rr * Math.cos(t), cz + rr * Math.sin(t))); }
    return poly(hull(pts));
  }
  function ringYZ(wx, cy, cz, rr) {
    const pts = [];
    for (let i = 0; i < 28; i++) { const t = (i / 28) * Math.PI * 2; pts.push(P(wx, cy + rr * Math.cos(t), cz + rr * Math.sin(t))); }
    return poly(pts);
  }

  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g), x = k * STEP;
    const it = { k, x, grp, z: tween(REST[k]), last: NaN, sils: [] };
    it.farW = mk("path", { class: "sil" }, grp);
    it.farC = mk("path", { class: "sil" }, grp);
    it.back = solid(grp); it.seat = solid(grp); it.foot = solid(grp);
    it.nearC = mk("path", { class: "sil" }, grp);
    it.nearW = mk("path", { class: "sil" }, grp);
    it.tyre = mk("path", { class: "nf lo" }, grp);
    it.spoke = mk("path", { class: "lo" }, grp);
    it.sils = [it.farW, it.farC, it.back.sil, it.seat.sil, it.foot.sil, it.nearC, it.nearW];
    items.push(it);
  }

  function draw(it, d) {
    if (d === it.last) return;
    it.last = d;
    const x = it.x, y = d;
    it.farW.setAttribute("d", wheel(x - 11, y - 3, R, R, 1.1));
    it.farC.setAttribute("d", wheel(x - 7, y + 9, 2.6, 2.6, 0.8));
    put(it.back, box(x - 8, y - 11, x + 8, y - 9, 11, 28));
    put(it.seat, box(x - 8, y - 9, x + 8, y + 7, 11, 13));
    put(it.foot, box(x - 6, y + 9, x + 6, y + 13, 3, 4.5, 1, 0.5));
    it.nearC.setAttribute("d", wheel(x + 7, y + 9, 2.6, 2.6, 0.8));
    it.nearW.setAttribute("d", wheel(x + 11, y - 3, R, R, 1.1));
    it.tyre.setAttribute("d", ringYZ(x + 12.1, y - 3, R, R - 2.4));
    const a = d / R, c = Math.cos(a) * (R - 2.4), s = Math.sin(a) * (R - 2.4);
    it.spoke.setAttribute("d", seg(P(x + 12.1, y - 3 - c, R + s), P(x + 12.1, y - 3 + c, R - s)) + seg(P(x + 12.1, y - 3 + s, R + c), P(x + 12.1, y - 3 - s, R - c)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 0, 14));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), y = a < 0 ? REST[k] : dd === 0 ? ROLL : dd === 1 ? 5 : 0;
      tset(it.z, y, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      for (const s of it.sils) s.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "chair " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "wheelchairs",
  means: "Three wheelchairs in a row: the chair under the pointer rolls forward, wheels turning, and its neighbours ease out a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[151, 122], [216, 154], [281, 186], null],
  mount,
});

stethoscopes.code:
/**
 * Stethoscopes: three stethoscopes hung on hooks along a clinic wall, each a
 * pair of ear tubes, one long tube and a chest piece. The pointer picks one
 * by where it stands: it swings out on its hook, and the ones beside it sway
 * a little, staggered from it. At rest the middle one hangs aside, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rad, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 36, HZ = 64, SW = 30, FAV = 1, REST = [-5, 12, 3];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  const X1 = (N - 1) * STEP;
  fit(C, [[-18, -4, 0], [X1 + 18, -4, 0], [-18, 8, 0], [X1 + 18, 8, 0], [-18, -4, 72], [X1 + 18, 0, 72]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [wr, wi] = rings(-18, -4, X1 + 18, 0, 1.5, 0.7);
  put(solid(g), prism(P, front, wr, wi, 0, 72));

  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g), x = k * STEP;
    const [hr, hi] = rings(x - 1.6, 0, x + 1.6, 6, 1.2, 0.5);
    put(solid(grp), prism(P, front, hr, hi, HZ - 1.6, HZ + 1.6));
    const it = { x, grp, a: tween(REST[k]), last: NaN };
    it.ears = mk("path", { class: "sil nf" }, grp);
    it.tube = mk("path", { class: "sil nf" }, grp);
    it.chest = mk("path", { class: "sil" }, grp);
    it.bell = mk("path", { class: "nf lo" }, grp);
    it.sils = [it.ears, it.tube, it.chest];
    items.push(it);
  }

  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const t = rad(deg), c = Math.cos(t), s = Math.sin(t), y = 5;
    const W = (u, w) => P(it.x + u * c - w * s, y, HZ + u * s + w * c);
    const side = (m) => [W(m * 6, 3), W(m * 7, -2), W(m * 5.5, -12), W(m * 2, -18), W(0, -21)];
    it.ears.setAttribute("d", open(side(-1)) + " " + open(side(1)));
    const tube = [];
    for (let i = 0; i <= 12; i++) { const q = i / 12; tube.push(W(Math.sin(q * Math.PI) * 6, -21 - q * 26)); }
    it.tube.setAttribute("d", open(tube));
    const disc = (r) => { const pts = []; for (let i = 0; i < 24; i++) { const a = (i / 24) * Math.PI * 2; pts.push(W(r * Math.cos(a), -53 + r * Math.sin(a))); } return poly(pts); };
    it.chest.setAttribute("d", disc(6));
    it.bell.setAttribute("d", disc(3.6));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 5, HZ - 26));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 36 && Math.abs(mids[best][1] - sy) < 75 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), d = a < 0 ? REST[k] : dd === 0 ? SW : dd === 1 ? 7 * Math.sign(k - a) : 0;
      tset(it.a, d, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      for (const p of it.sils) p.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "hook " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "stethoscopes",
