waffleiron.code:
/**
 * Waffle iron: a square iron on a low base, its lid hinged along the back
 * edge, a grid of waffle pockets on the lower plate. The pointer opens the
 * lid: the higher it stands over the iron, the wider the lid swings up on its
 * hinge, on a spring. At rest the lid sits ajar, bright. The slider is how
 * far the lid may open.
 *
 * The pattern: one part following the pointer (aim).
 */
const {
  Cam, clamp, fit, facing, hull, lerp, open, poly, prism, proj, rad, rings, rrect, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 64, D = 58, H = 12, T = 7, REST = 16, G = 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-4, -4, 0], [W + 4, D + 4, 0], [W + 4, -4, 0], [-4, D + 4, 0], [0, -8, H + D + 4], [W, -8, H + D + 4]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the base and its lower plate
  const [br, bi] = rings(-4, -4, W + 4, D + 4, 10, 2);
  put(solid(g), prism(P, front, br, bi, 0, H));
  mk("path", { d: poly(rrect(4, 4, W - 4, D - 4, 6, 4).map((q) => P(q.u, q.v, H))), class: "nf lo" }, g);
  let gd = "";
  for (let i = 1; i < G; i++) {
    const x = 4 + ((W - 8) * i) / G, y = 4 + ((D - 8) * i) / G;
    gd += seg(P(x, 6, H), P(x, D - 6, H)) + seg(P(6, y, H), P(W - 6, y, H));
  }
  mk("path", { d: gd, class: "nf lo" }, g);
  // the hinge knuckles at the back
  for (const x of [10, W - 10]) {
    const [hr, hi] = rings(x - 5, -6, x + 5, 2, 3, 1);
    put(solid(g), prism(P, front, hr, hi, H - 2, H + 4));
  }
  // the lid: a thick plate turning on the hinge line y = 0, z = H
  const lid = mk("g", {}, g);
  const lsil = mk("path", { class: "sil hi" }, lid), lcr = mk("path", { class: "nf lo" }, lid), hdl = mk("path", {}, lid);
  const outer = rrect(-2, 0, W + 2, D + 2, 10, 4), inner = rrect(3, 5, W - 3, D - 3, 7, 4);
  const handle = rrect(W / 2 - 9, D + 1, W / 2 + 9, D + 9, 3, 3);
  const ang = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const L = (u, v, w) => P(u, v * c - w * s, H + 1 + v * s + w * c);
    const at = (ring, w) => ring.map((q) => L(q.u, q.v, w));
    lsil.setAttribute("d", poly(hull(at(outer, 0).concat(at(outer, T)))));
    lcr.setAttribute("d", poly(at(inner, a < 90 ? T : 0)));
    hdl.setAttribute("d", poly(hull(at(handle, T * 0.3).concat(at(handle, T * 0.8)))));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  const top = P(W / 2, D / 2, H)[1];
  function move([sx, sy]) {
    const t = clamp((top - sy + 40) / 120, 0, 1);
    ang.t = lerp(REST + 4, maxA, t);
    read.textContent = Math.round(ang.t) + "°";
    B.wake();
  }
  function leave() { ang.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "waffleiron",
  means: "A waffle iron on its base: the higher the pointer stands over it, the wider the lid swings up on its back hinge.",
  rules: [3, 5, 6, 8],
  range: [60, 95, 110],
  tour: [[200, 230], [200, 130], [200, 40], null],
  mount,
});

juicer.code:
/**
 * Juicer: a citrus press, a round cup with a ribbed cone on a base and a
 * lever arm hinged on a post at the back. The pointer presses: the lower it
 * stands over the press, the further the arm swings down onto the cone, on a
 * spring. At rest the arm stands raised, bright. The slider is how far the
 * arm comes down.
 *
 * The pattern: one part following the pointer (aim).
 */
const {
  Cam, circ, clamp, fit, facing, hull, lerp, poly, prism, proj, rad, rings, rrect, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const CX = 32, CY = 44, HZ = 52, REST = 42;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let low = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, 0], [64, 78, 0], [64, 0, 0], [0, 78, 0], [10, 6, HZ + 50], [54, 6, HZ + 50]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(CX - 7, 0, CX + 7, 12, 4, 1.5);
  put(solid(g), prism(P, front, pr, pi, 0, HZ + 2));
  put(solid(g), prism(P, front, disc(CX, CY, 32), disc(CX, CY, 30), 0, 8));
  put(solid(g), prism(P, front, disc(CX, CY, 24), disc(CX, CY, 21.5), 8, 24));
  // the cone, with ribs from its tip down
  const cone = mk("g", {}, g);
  mk("path", { d: poly(hull(disc(CX, CY, 15, 32).map((q) => P(q.u, q.v, 24)).concat([P(CX, CY, 38)]))) }, cone);
  let rib = "";
  for (let k = 0; k < 5; k++) { const t = rad(20 + k * 25); rib += seg(P(CX, CY, 37), P(CX + 14 * Math.cos(t), CY + 14 * Math.sin(t), 24.5)); }
  mk("path", { d: rib, class: "nf lo" }, cone);
  // the arm: a plate turning on the hinge at the post's top
  const arm = mk("g", {}, g);
  const asil = mk("path", { class: "sil hi" }, arm), acr = mk("path", { class: "nf lo" }, arm), cap = mk("path", {}, arm);
  const plate = rrect(CX - 18, 0, CX + 18, 70, 12, 4), inner = rrect(CX - 15, 3, CX + 15, 67, 9, 4);
  const capR = disc(CX, CY - 6, 16, 32);
  const ang = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const L = (u, v, w) => P(u, 6 + v * c - w * s, HZ + v * s + w * c);
    const at = (ring, w) => ring.map((q) => L(q.u, q.v, w));
    cap.setAttribute("d", poly(hull(at(capR, -9).concat(at(capR, 0)))));
    asil.setAttribute("d", poly(hull(at(plate, 0).concat(at(plate, 5)))));
    acr.setAttribute("d", poly(at(inner, 5)));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  const mid = P(CX, CY, 30)[1];
  function move([, sy]) {
    const t = clamp((sy - mid + 50) / 120, 0, 1);
    ang.t = lerp(REST - 4, low, t);
    read.textContent = Math.round(((REST - ang.t) / (REST - low)) * 100) + "%";
    B.wake();
  }
  function leave() { ang.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { low = v; }, destroy: bag.dispose };
}

hairline({
  name: "juicer",
  means: "A citrus press: the lower the pointer stands over it, the further the lever arm swings down onto the ribbed cone.",
  rules: [3, 5, 6, 8],
  range: [-4, 2, 10],
  tour: [[200, 120], [200, 200], [200, 260], null],
  mount,
});

bathtub.code:
/**
 * Bathtub: a rounded tub on four short feet with a tap on its back rim. The
 * pointer's position along the tub is how far the tap is turned: the handle
 * swings round and the water line climbs the inner wall to meet it. At rest
 * the tub stands half full, its water line bright. The slider is the ceiling.
 *
 * The pattern: one continuous value read from the pointer (spring).
 */
const {
  Cam, circ, clamp, fit, facing, lerp, open, poly, prism, proj, rings, ringAt, rrect, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 120, W = 56, H = 34, FZ = 5, REST = 0.45;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let cap = value / 100;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[0, 0, 0], [L, W, 0], [L, 0, 0], [0, W, 0], [14, W / 2, FZ + H + 22], [L, W, FZ + H]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // feet, far ones first
  for (const [x, y] of [[12, 10], [L - 12, 10], [12, W - 10], [L - 12, W - 10]]) put(solid(g), prism(P, front, disc(x, y, 4), disc(x, y, 3), 0, FZ + 1));
  const [or, oi] = rings(0, 0, L, W, 24, 2);
  put(solid(g), prism(P, front, or, oi, FZ, FZ + H));
  // the opening, then the water line on its far inner wall
  const open0 = rrect(7, 7, L - 7, W - 7, 18, 8);
  mk("path", { d: poly(ringAt(P, open0, FZ + H)), class: "nf lo" }, g);
  const water = mk("path", { class: "nf" }, g);
  const back = open0.filter((q) => !front(q));
  // tap: a post on the back rim, a spout, a turning handle
  const tx = 14, ty = W / 2, tz = FZ + H;
  put(solid(g), prism(P, front, disc(tx, ty, 3.5), disc(tx, ty, 2.5), tz, tz + 14));
  mk("path", { d: open([P(tx, ty, tz + 12), P(tx + 12, ty, tz + 12), P(tx + 12, ty, tz + 8)]), class: "nf" }, g);
  const handle = mk("path", { class: "nf" }, g);

  const lvl = spring(REST);
  let last = NaN;
  function draw(v) {
    if (v === last) return;
    last = v;
    const z = lerp(FZ + 6, FZ + H - 3, v);
    water.setAttribute("d", open(ringAt(P, back.length ? back : open0, z)));
    const a = lerp(-0.4, 2.2, v), hz = tz + 15;
    handle.setAttribute("d", open([P(tx - 7 * Math.cos(a), ty - 7 * Math.sin(a), hz), P(tx + 7 * Math.cos(a), ty + 7 * Math.sin(a), hz)]));
  }
  const B = register(stage, (dt) => { const m = stepS(lvl, dt); draw(clamp(lvl.x, 0, 1)); return m; });
  bag.add(B.unregister);

  let on = null;
  function setOn(t) {
    const now = t === null ? null : Math.round(t * 100);
    lvl.t = t === null ? REST : t;
    water.classList.toggle("hi", true);
    read.textContent = t === null ? "rest" : "fill " + now + "%";
    on = t;
    B.wake();
  }
  setOn(null);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const [x, y] = unproj(C, sx, sy, FZ);
      if (x < -10 || x > L + 10 || y < -10 || y > W + 10) return setOn(null);
      setOn(clamp(x / L, 0.05, 1) * cap);
    },
    leave: () => setOn(null),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { cap = v / 100; if (on !== null) setOn(Math.min(on, cap)); }, destroy: bag.dispose };
}

hairline({
  name: "bathtub",
  means: "A tub with a tap on its rim: the pointer along the tub turns the handle and the water line climbs the inner wall.",
  rules: [1, 3, 4, 5, 8],
  range: [40, 100, 100],
  tour: [[130, 163], [200, 198], [267, 231], null],
  mount,
});

bookends.code:
/**
 * Bookends: a run of books of mixed heights held between two L-shaped
 * bookends on a shelf. The pointer picks a book by where it stands: it slides
 * forward off the shelf's back, and the books beside it ease out a little,
 * staggered from it. At rest one book stands pulled out, bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = [9, 7, 11, 8, 6, 10, 8], H = [36, 30, 40, 33, 28, 38, 31], D = 24, GAP = 1, OUT = 16, FAV = 2, END = 3;
const XS = []; { let x = END + 1; for (const w of W) { XS.push(x); x += w + GAP; } }
const X1 = XS[XS.length - 1] + W[W.length - 1] + 1 + END;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-8, -6, -5], [X1 + 8, -6, -5], [X1 + 8, D + OUT + 4, -5], [-8, D + OUT + 4, -5], [0, 0, 42], [X1, 0, 42]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (parent, x0, y0, x1, y1, z0, z1, r = 1.2, b = 0.8) => { const [o, i] = rings(x0, y0, x1, y1, r, b); return prism(P, front, o, i, z0, z1); };
  put(solid(g), box(g, -8, -6, X1 + 8, D + 6, -5, 0, 3, 1.6));
  // the bookends: a foot under the books and an upright plate
  put(solid(g), box(g, 0, 2, 22, D - 2, 0, 1.2, 1, 0.6));
  put(solid(g), box(g, 0, 2, END, D - 2, 0, 30, 1, 0.6));
  put(solid(g), box(g, X1 - 22, 2, X1, D - 2, 0, 1.2, 1, 0.6));
  const row = mk("g", {}, g);
  const items = W.map((w, k) => {
    const grp = mk("g", {}, row), s = solid(grp);
    const band = mk("path", { class: "nf lo" }, grp);
    return { k, x: XS[k], w, h: H[k], s, band, y: tween(k === FAV ? OUT * 0.55 : k === 5 ? 2 : 0), last: NaN };
  });
  const rg = mk("g", {}, g);
  put(solid(rg), box(rg, X1 - END, 2, X1, D - 2, 0, 30, 1, 0.6));

  function draw(it, y) {
    if (y === it.last) return;
    it.last = y;
    put(it.s, box(null, it.x, y, it.x + it.w, y + D, 0, it.h, 1.4, 0.9));
    // a spine band near the top, on the face toward the viewer
    const yy = y + D, z = it.h - 6;
    it.band.setAttribute("d", "M" + P(it.x + 1, yy, z).join(",") + "L" + P(it.x + it.w - 1, yy, z).join(","));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.y, now)); if (!tdone(it.y, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + it.w / 2, D / 2, it.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 22 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), y = a < 0 ? (k === FAV ? OUT * 0.55 : k === 5 ? 2 : 0) : dd === 0 ? OUT : dd === 1 ? 3 : 0;
      tset(it.y, y, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "vol " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "bookends",
  means: "Books held between two bookends on a shelf: the book under the pointer slides forward, and its neighbours ease out a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[160, 128], [216, 160], [265, 187], null],
  mount,
});

circuitboard.code:
/**
 * Circuit board: a rounded board with copper traces on its top and a row of
 * four chips seated in their footprints. The pointer picks a chip by where it
 * is along the board: that chip lifts out of its footprint, its neighbours
 * rise a little after it, staggered by distance. At rest the chips sit at
 * uneven heights, one half-seated, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is on a fixed plane
 * through the chips' resting tops.
 */
const { Cam, clamp, facing, fit, open, poly, prism, proj, rings, ringAt, rrect, seg, unproj, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const N = 4, BX = 74, BY = 46, BT = 3, CW = 12, CY0 = 12, CY1 = 32, CH = 4, LIFT = 16, BUMP = 4;
const XS = [6, 23, 40, 57], REST = [0, 1.5, 4, 0.5], FAV = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.3);
  fit(C, [[0, 0, 0], [BX, BY, 0], [BX, 0, 0], [0, BY, 0], [XS[0], CY0, BT + CH + LIFT], [XS[3] + CW, CY0, BT + CH + LIFT]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [bo, bi] = rings(0, 0, BX, BY, 5, 1.4);
  const board = solid(g);
  put(board, prism(P, front, bo, bi, 0, BT));
  // the traces and the chips' footprints, printed on the board's top
  let tr = "";
  XS.forEach((x, k) => {
    tr += poly(ringAt(P, rrect(x - 1, CY0 - 1, x + CW + 1, CY1 + 1, 1, 3), BT));
    tr += open([P(x + CW / 2, CY1 + 1, BT), P(x + CW / 2, BY - 6, BT), P(x + CW / 2 + 4, BY - 3, BT)]);
    tr += open([P(x + 3, CY0 - 1, BT), P(x + 3, 6, BT), P(x + 7, 3, BT)]);
    if (k < N - 1) tr += seg(P(x + CW + 1, 22, BT), P(XS[k + 1] - 1, 22, BT));
  });
  mk("path", { class: "nf lo", d: tr }, board.g);

  const chips = XS.map((x, k) => {
    const s = solid(g), pins = mk("path", { class: "nf lo" }, s.g);
    return { k, x, s, pins, z: tween(REST[k]), last: NaN };
  });
  function draw(c, lift) {
    if (lift === c.last) return;
    c.last = lift;
    const z0 = BT + lift, [r, i] = rings(c.x, CY0, c.x + CW, CY1, 1.6, 0.8);
    put(c.s, prism(P, front, r, i, z0, z0 + CH));
    let d = "";
    for (let j = 0; j < 4; j++) { const y = CY0 + 3 + j * 4.6; d += seg(P(c.x + CW, y, z0 + 1), P(c.x + CW + 1.5, y, z0 - 0.5)); }
    c.pins.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    chips.forEach((c) => { draw(c, tval(c.z, now)); if (!tdone(c.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, BT + CH);
    if (x < -3 || x > BX + 3 || y < -3 || y > BY + 3) return -1;
    return clamp(Math.round((x - XS[0] - CW / 2) / (XS[1] - XS[0])), 0, N - 1);
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    chips.forEach((c, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : Math.max(0, BUMP - 2 * Math.abs(k - a));
      tset(c.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      c.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "U" + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "circuitboard",
  means: "A circuit board: the chip under the pointer lifts out of its footprint, its neighbours rise a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[144, 140], [184, 160], [263, 200], null],
  mount,
});

dartboard.code:
/**
 * Dartboard: a round board on a post, its face cut by rings and wires, the
 * bull at its centre. The board swings on its post to face the pointer, a
 * spring on the pointer's screen x. At rest it is turned a little aside and
 * the bull is the bright mark; while the pointer aims, the rim takes it.
 * The slider is how far the board may swing.
 *
 * The pattern: one part turning to face the pointer (aim).
 */
const {
  Cam, fit, hull, open, poly, prism, proj, facing, rings, clamp, spring, stepS, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 40, T = 5, Z = 62, REST = -18;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-R, -R, 0], [R, R, 0], [-R, R, Z + R], [R, -R, Z + R], [0, 0, Z - R]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [fr, fi] = rings(-22, -22, 22, 22, 10, 2);
  put(solid(g), prism(P, front, fr, fi, 0, 4));
  const [pr, pi] = rings(-4, -4, 4, 4, 3, 1);
  put(solid(g), prism(P, front, pr, pi, 4, Z - 10));
  const body = mk("path", { class: "sil" }, g);
  const face = mk("path", { class: "nf lo" }, g);
  const wires = mk("path", { class: "nf lo" }, g);
  const bull = mk("path", { class: "nf" }, g);
  const yaw = spring(REST);
  let last = NaN;

  function pt(phi, r, s, d) {
    const n = [Math.cos(phi), Math.sin(phi)], h = [-Math.sin(phi), Math.cos(phi)];
    return P(r * Math.cos(s) * h[0] + d * n[0], r * Math.cos(s) * h[1] + d * n[1], Z + r * Math.sin(s));
  }
  const ring = (phi, r, d, n = 48) => Array.from({ length: n }, (_, i) => pt(phi, r, (i / n) * 2 * Math.PI, d));

  function draw(a) {
    if (a === last) return;
    last = a;
    const phi = rad(45 + a);
    body.setAttribute("d", poly(hull(ring(phi, R, 0).concat(ring(phi, R, -T)))));
    face.setAttribute("d", poly(ring(phi, R, 0)));
    let w = "";
    for (const r of [R * 0.78, R * 0.7, R * 0.46, R * 0.38]) w += poly(ring(phi, r, 0.1, 40));
    for (let i = 0; i < 10; i++) { const s = (i / 10) * 2 * Math.PI + Math.PI / 20; w += open([pt(phi, R * 0.14, s, 0.1), pt(phi, R * 0.78, s, 0.1)]); }
    wires.setAttribute("d", w);
    bull.setAttribute("d", poly(ring(phi, R * 0.1, 0.2, 20)));
  }

  const B = register(stage, (dt) => { const m = stepS(yaw, dt); draw(yaw.x); return m; });
  bag.add(B.unregister);

  let on = null;
  function aim(p) {
    const act = !!p;
    const a = act ? clamp(((p[0] - 200) / 160) * reach, -reach, reach) : REST;
    yaw.t = a;
    if (on !== act) { on = act; body.classList.toggle("hi", act); bull.classList.toggle("hi", !act); }
    read.textContent = act ? (a >= 0 ? "+" : "") + Math.round(a) + "°" : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

