carlift.code:
/**
 * Car lift: a two-post garage lift with a car on its platform. The pointer's
 * height over the lift sets how high the platform rides, on a spring; the car
 * rises with it. At rest the car sits a little off the floor, the platform
 * bright. The slider is the lift's top.
 *
 * The pattern: one part following a continuous input (spring).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, ringAt, rrect, run, spring, stepS, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const REST = 12, TOP = 60;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let top = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-54, -40, 0], [54, 30, 0], [54, -40, 0], [-54, 30, 0], [-40, -34, 82], [0, 0, TOP + 36]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-54, -40, 54, 30, 7, 2);
  put(solid(g), prism(P, front, br, bi, 0, 3));
  for (const x of [-42, 42]) {
    const [r, i] = rings(x - 5, -38, x + 5, -28, 3, 1);
    put(solid(g), prism(P, front, r, i, 3, 82));
  }
  const arms = [-42, 42].map(() => solid(g));
  const plat = solid(g), body = solid(g), cab = solid(g);
  const wheels = [[-26, 20], [26, 20]].map(() => mk("path", { class: "nf" }, g));
  plat.sil.classList.add("hi");
  const [pr, pi] = rings(-48, -24, 48, 24, 4, 1.4);
  const [cr, ci] = rings(-42, -18, 42, 18, 9, 2);
  const [ar, ai] = rings(-4, -30, 4, -22, 1.5, 0.8);
  const foot = rrect(-24, -16, 18, 16, 6, 4), cTop = rrect(-16, -14, 10, 14, 5, 4), cIn = rrect(-15, -13, 9, 13, 4, 4);

  const h = spring(REST);
  let last = NaN;
  function draw(z) {
    if (z === last) return;
    last = z;
    arms.forEach((s, k) => { const x = k ? 42 : -42; put(s, prism(P, front, ar.map((q) => ({ ...q, u: q.u + x })), ai.map((q) => ({ ...q, u: q.u + x })), 3 + z, 6 + z)); });
    put(plat, prism(P, front, pr, pi, 3 + z, 6 + z));
    put(body, prism(P, front, cr, ci, 9 + z, 21 + z));
    put(cab, { sil: poly(hull(ringAt(P, foot, 21 + z).concat(ringAt(P, cTop, 32 + z)))), crease: open(ringAt(P, run(cIn, front), 32 + z)) });
    wheels.forEach((w, k) => {
      const x = k ? 26 : -26, pts = [];
      for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; pts.push(P(x + 6 * Math.cos(a), 18.5, 12 + z + 6 * Math.sin(a))); }
      w.setAttribute("d", poly(pts));
    });
  }

  const B = register(stage, (dt) => { const m = stepS(h, dt); draw(h.x); return m; });
  bag.add(B.unregister);

  const yLo = P(0, 0, 0)[1], yHi = P(0, 0, top + 30)[1];
  function move([sx, sy]) {
    if (Math.abs(sx - 200) > 120) return leave();
    h.t = clamp(((yLo - sy) / (yLo - yHi)) * top, 0, top);
    read.textContent = "lift " + Math.round((h.t / top) * 100) + "%";
    B.wake();
  }
  function leave() { h.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { top = v; }, destroy: bag.dispose };
}

hairline({
  name: "carlift",
  means: "A two-post lift with a car on its platform: the platform follows the pointer's height and the car rises with it.",
  rules: [3, 5, 8],
  range: [30, 45, 60],
  tour: [[194, 212], [194, 110], [194, 164], null],
  mount,
});

fuelpump.code:
/**
 * Fuel pump: a pump cabinet on its island, with a screen and three nozzles
 * hung in holsters along its front. The pointer picks a nozzle by where it
 * stands; that nozzle lifts out of its holster on its hose, and the ones
 * beside it rock a little, staggered. At rest the middle nozzle is half out,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const XS = [-13, 0, 13], FAV = 1, LIFT = 24, FY = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-34, -24, 0], [34, 30, 0], [34, -24, 0], [-34, 30, 0], [-20, -14, 84], [20, 14, 84]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [ir, ii] = rings(-34, -24, 34, 30, 7, 2);
  put(solid(g), prism(P, front, ir, ii, 0, 4));
  const [pr, pi] = rings(-20, -14, 20, FY, 5, 1.6);
  put(solid(g), prism(P, front, pr, pi, 4, 84));
  mk("path", { d: poly([P(-14, FY, 60), P(14, FY, 60), P(14, FY, 76), P(-14, FY, 76)]), class: "nf lo" }, g);
  const [hr, hi_] = rings(-24, -16, 24, FY + 2, 4, 1.4);
  put(solid(g), prism(P, front, hr, hi_, 84, 88));

  const items = XS.map((x, k) => {
    mk("path", { d: poly([P(x - 4, FY, 30), P(x + 4, FY, 30), P(x + 4, FY, 44), P(x - 4, FY, 44)]), class: "nf lo" }, g);
    const grp = mk("g", {}, g), hose = mk("path", { class: "nf lo" }, grp), nz = solid(grp);
    return { k, x, hose, nz, z: tween(k === FAV ? LIFT * 0.5 : 0), last: NaN };
  });

  function draw(it, l) {
    if (l === it.last) return;
    it.last = l;
    const x = it.x, y0 = FY + 1 + l * 0.35, z0 = 32 + l;
    const [r, i] = rings(x - 4, y0, x + 4, y0 + 6, 2, 0.9);
    put(it.nz, prism(P, front, r, i, z0, z0 + 13));
    const pts = [];
    for (let s = 0; s <= 10; s++) { const t = s / 10; pts.push(P(x + 1.5, FY + (y0 + 2.5 - FY) * t + Math.sin(t * Math.PI) * 6, 16 + (z0 - 16) * t - Math.sin(t * Math.PI) * 6)); }
    it.hose.setAttribute("d", open([P(x + 1.5, FY, 16)].concat(pts)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, FY, 38));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 16 && Math.abs(mids[best][1] - sy) < 50 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.5 : 0) : dd === 0 ? LIFT : dd === 1 ? 3 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.nz.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "pump " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

