launchpad.code:
/**
 * Launchpad: a rocket standing on its pad beside a lattice tower, three
 * service arms reaching from the tower to the rocket. The pointer picks an
 * arm by its height: it slides back into the tower, and the arms beside it
 * pull back a little, staggered from it. At rest the middle arm is drawn
 * back, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single column.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, rings, ringAt, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, proj,
} = HL;

const PZ = 4, TX0 = 8, TX1 = 20, TY0 = 20, TY1 = 32, TZ = 96;
const RX = 54, RY = 26, RR = 9, RZ = 78, NOSE = 16;
const AZ = [30, 50, 70], FULL = RX - RR - TX1 + 1, FAV = 1;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const restLen = (k) => (k === FAV ? 3 : FULL);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.8);
  fit(C, [[-4, -4, 0], [74, 52, 0], [74, -4, 0], [-4, 52, 0], [TX0, TY0, TZ], [RX, RY, PZ + RZ + NOSE]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-4, -4, 74, 52, 4, 2);
  put(solid(g), prism(P, front, pr, pi, 0, PZ));
  // flame trench: a dashed ring on the pad under the rocket
  mk("path", { d: poly(ringAt(P, disc(RX, RY, RR + 4), PZ)), class: "dash nf" }, g);

  // the tower: a tall box with lattice cross-braces on its front faces
  const tw = mk("g", {}, g);
  const [tr, ti] = rings(TX0, TY0, TX1, TY1, 1, 0.8);
  put(solid(tw), prism(P, front, tr, ti, PZ, TZ));
  let d = "";
  for (let z = PZ; z + 10 <= TZ - 2; z += 10) {
    d += seg(P(TX1, TY0, z), P(TX1, TY1, z + 10)) + seg(P(TX1, TY1, z), P(TX1, TY0, z + 10));
    d += seg(P(TX0, TY1, z), P(TX1, TY1, z + 10)) + seg(P(TX1, TY1, z), P(TX0, TY1, z + 10));
  }
  mk("path", { d, class: "nf lo" }, tw);
  const [hr, hi2] = rings(TX0 - 2, TY0 - 2, TX1 + 2, TY1 + 2, 1, 0.8);
  put(solid(tw), prism(P, front, hr, hi2, TZ, TZ + 3));

  const arms = AZ.map((z, k) => {
    const grp = mk("g", {}, g);
    return { k, z, grp, s: solid(grp), len: tween(restLen(k)), last: NaN };
  });

  // the rocket: a body, a band, a nose cone
  const rg = mk("g", {}, g);
  put(solid(rg), prism(P, front, disc(RX, RY, RR), disc(RX, RY, RR - 1), PZ, PZ + RZ));
  mk("path", { d: poly(ringAt(P, disc(RX, RY, RR), PZ + RZ * 0.62).slice(0, 21)), class: "nf lo" }, rg);
  const cone = [];
  for (let i = 0; i <= 6; i++) cone.push(...ringAt(P, disc(RX, RY, Math.max(0.4, RR * (1 - i / 6) ** 0.8), 28), PZ + RZ + (NOSE * i) / 6));
  mk("path", { d: poly(hull(cone)) }, rg);
  for (const a of [0, Math.PI / 2]) {
    const x = RX + RR * Math.cos(a) * 1.0, y = RY + RR * Math.sin(a);
    const [fr, fi] = rings(x - 1, y - 1, x + 1 + 5 * Math.cos(a), y + 1 + 5 * Math.sin(a), 0.6, 0.4);
    put(solid(rg), prism(P, front, fr, fi, PZ + 2, PZ + 16));
  }

  function draw(a, L) {
    if (L === a.last) return;
    a.last = L;
    const [ar, ai] = rings(TX1 - 1, RY - 3, TX1 + Math.max(1.2, L), RY + 3, 0.8, 0.6);
    put(a.s, prism(P, front, ar, ai, a.z, a.z + 5));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const a of arms) { draw(a, tval(a.len, now)); if (!tdone(a.len, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = arms.map((a) => P(TX1 + FULL / 2, RY, a.z + 1.5));
  function hit([sx, sy]) {
    if (Math.abs(sx - mids[0][0]) > 60) return -1;
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    arms.forEach((it, k) => {
      const dd = Math.abs(k - a), L = a < 0 ? restLen(k) : dd === 0 ? 1.2 : dd === 1 ? FULL * 0.6 : FULL;
      tset(it.len, L, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "arm " + (3 - a);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "launchpad",
  means: "A rocket beside its launch tower: the service arm under the pointer slides back into the tower, its neighbours pull back a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[197, 112], [197, 144], [197, 175], null],
  mount,
});

skis.code:
/**
 * Skis: five pairs of skis standing in a rack along a low bench, held by a
 * rail near their tips. The pointer picks a pair by where it stands: it
 * lifts up out of the rack, and the pairs beside it rise a little,
 * staggered from it. At rest one pair stands raised, bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 16, W = 5, D = 2, H = 92, BZ = 6, LIFT = 22, FAV = 3, RZ = 66;
const X1 = (N - 1) * STEP + 2 * W + 8;
const rest = (k) => (k === FAV ? LIFT * 0.7 : [2, 0, 4, 0, 1][k]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-6, -6, 0], [X1 + 6, 18, 0], [X1 + 6, -6, 0], [-6, 18, 0], [0, 6, H + LIFT + BZ], [X1, 6, H + LIFT + BZ]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-6, -6, X1 + 6, 18, 3, 1.5);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  // the rack's back posts and rail, behind the skis
  const [p0, p0i] = rings(-4, 0, 0, 4, 1, 0.6), [p1, p1i] = rings(X1, 0, X1 + 4, 4, 1, 0.6);
  put(solid(g), prism(P, front, p0, p0i, BZ, RZ + 4));
  put(solid(g), prism(P, front, p1, p1i, BZ, RZ + 4));
  const [rr, ri] = rings(-4, 0, X1 + 4, 4, 1, 0.6);
  put(solid(g), prism(P, front, rr, ri, RZ, RZ + 4));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 8 + k * STEP, grp = mk("g", {}, g);
    const a = solid(grp), b = solid(grp), tip = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, grp, a, b, tip, z: tween(rest(k)), last: NaN });
  }
  // the front rail, in front of the skis
  const fg = mk("g", {}, g);
  const [fr, fi] = rings(-4, 10, X1 + 4, 13, 1, 0.6);
  put(solid(fg), prism(P, front, fr, fi, RZ - 8, RZ - 5));

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = BZ + lift, x = it.x;
    const [r1, i1] = rings(x, 5, x + W, 5 + D, 1.2, 0.5), [r2, i2] = rings(x, 5 + D + 0.6, x + W, 5 + 2 * D + 0.6, 1.2, 0.5);
    put(it.a, prism(P, front, r1, i1, z0, z0 + H));
    put(it.b, prism(P, front, r2, i2, z0, z0 + H - 3));
    // a binding: two short marks across the front ski
    it.tip.setAttribute("d", seg(P(x, 5 + 2 * D + 0.6, z0 + 34), P(x + W, 5 + 2 * D + 0.6, z0 + 34)) + seg(P(x, 5 + 2 * D + 0.6, z0 + 42), P(x + W, 5 + 2 * D + 0.6, z0 + 42)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + W / 2, 6, BZ + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 16 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? rest(k) : dd === 0 ? LIFT : dd === 1 ? 6 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      it.a.sil.classList.toggle("hi", on);
      it.b.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "pair " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "skis",
  means: "Five pairs of skis in a rack: the pair under the pointer lifts out of the rack, and the pairs beside it rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[156, 149], [201, 172], [247, 194], null],
  mount,
});

footballgoal.code:
/**
 * Football goal: a goal frame with its net pulled back, three balls waiting
 * on the spots in front of it. The pointer picks a ball by where it stands:
 * it pops up off the grass, the balls beside it hop a little, staggered from
 * it. At rest one ball is up, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, flatDot, place,
} = HL;

const W = 110, H = 40, D = 26, BR = 7, N = 3, BY = 40, LIFT = 26, FAV = 2, S = 2.0;
const BX = [22, 55, 88];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, S);
  fit(C, [[-4, -D - 4, 0], [W + 4, -D, 0], [W + 4, BY + BR + 4, 0], [-4, BY + BR, 0], [0, 0, H], [W, 0, H], [BX[0], BY, 2 * BR + LIFT], [BX[2], BY, 2 * BR + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the net: guides from the frame back to the ground, behind the posts
  let nd = "";
  for (let i = 0; i <= 10; i++) { const x = (W * i) / 10; nd += seg(P(x, 0, H), P(x, -D, H * 0.55)) + seg(P(x, -D, H * 0.55), P(x, -D, 0)); }
  for (let j = 0; j <= 4; j++) { const z = (H * 0.55 * j) / 4; nd += seg(P(0, -D, z), P(W, -D, z)); }
  for (const x of [0, W]) nd += seg(P(x, 0, 0), P(x, -D, 0)) + seg(P(x, 0, H), P(x, -D, H * 0.55)) + seg(P(x, -D, 0), P(x, -D, H * 0.55));
  mk("path", { d: nd, class: "nf lo" }, g);
  mk("path", { d: seg(P(-14, 0, 0), P(W + 14, 0, 0)), class: "nf dash" }, g);
  // the frame: two posts and the bar
  for (const x of [0, W]) { const [r, i] = rings(x - 2, -2, x + 2, 2, 2, 0.6); put(solid(g), prism(P, front, r, i, 0, H)); }
  const [br, bi] = rings(-2, -2, W + 2, 2, 2, 0.6);
  const bar = solid(g);
  put(bar, prism(P, front, br, bi, H - 4, H));

  const balls = BX.map((x, k) => {
    const grp = mk("g", {}, g);
    const shadow = flatDot(grp, C, 2.4, "dot off");
    place(shadow, P(x, BY, 0));
    const body = mk("ellipse", { class: "sil", rx: BR * S, ry: BR * S }, grp);
    const seam = mk("ellipse", { class: "nf lo", rx: BR * S * 0.92, ry: BR * S * 0.36 }, grp);
    const patch = mk("ellipse", { class: "nf lo", rx: BR * S * 0.3, ry: BR * S * 0.3 }, grp);
    return { k, x, body, seam, patch, z: tween(k === FAV ? LIFT * 0.55 : 0), last: NaN };
  });

  function draw(b, lift) {
    if (lift === b.last) return;
    b.last = lift;
    const [cx, cy] = P(b.x, BY, BR + lift);
    for (const e of [b.body, b.seam]) { e.setAttribute("cx", cx); e.setAttribute("cy", cy); }
    b.patch.setAttribute("cx", cx - BR * S * 0.25); b.patch.setAttribute("cy", cy - BR * S * 0.5);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of balls) { draw(b, tval(b.z, now)); if (!tdone(b.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = balls.map((b) => P(b.x, BY, BR));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 && sy > mids[best][1] - 90 && sy < mids[best][1] + 30 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    balls.forEach((b, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.55 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(b.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      b.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "ball " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "footballgoal",
  means: "A goal with its net and three balls on the spots: the ball under the pointer pops up off the grass, its neighbours hop a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[112, 178], [158, 201], [205, 225], null],
  mount,
});

pingpong.code:
/**
 * Ping pong: a table with its net and a paddle lying at each end. The
 * pointer picks a side of the table: that paddle lifts off the top, ready to
 * serve, and the other settles back down. At rest the far paddle is up,
 * bright. The slider is how high the paddle lifts.
 *
 * The pattern: one of a few, picked by screen x (riffle).
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, seg, tdone, tset, tval, tween, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 128, W = 70, TZ = 26, TH = 3, PR = 10, S = 1.8;
const PX = [26, 102], PY = 30;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, S);
  fit(C, [[-2, -2, 0], [L + 2, W + 2, 0], [L + 2, -2, 0], [-2, W + 2, 0], [PX[0], PY, TZ + TH + 30], [PX[1], PY, TZ + TH + 30]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const top = TZ + TH;
  for (const x of [14, L - 20]) { const [r, i] = rings(x, 8, x + 6, W - 8, 2, 0.8); put(solid(g), prism(P, front, r, i, 0, TZ)); }
  const [tr, ti] = rings(0, 0, L, W, 3, 1.4);
  put(solid(g), prism(P, front, tr, ti, TZ, top));
  mk("path", { d: seg(P(3, W / 2, top), P(L - 3, W / 2, top)), class: "nf lo" }, g);

  const mkPaddle = (k) => {
    const grp = mk("g", {}, g);
    return { k, x: PX[k], grp, handle: solid(grp), face: solid(grp), z: tween(k === 0 ? 0.7 : 0), last: NaN };
  };
  const pads = [mkPaddle(0)];
  const [nr, ni] = rings(L / 2 - 1.2, -5, L / 2 + 1.2, W + 5, 1, 0.4);
  put(solid(g), prism(P, front, nr, ni, top, top + 9));
  pads.push(mkPaddle(1));
  const ball = mk("ellipse", { class: "", rx: 2.2 * S, ry: 2.2 * S }, g);
  const bp = P(L / 2 + 14, W - 14, top + 2.2);
  ball.setAttribute("cx", bp[0]); ball.setAttribute("cy", bp[1]);

  function draw(p, t) {
    const z = top + 0.2 + t * lift;
    if (z === p.last) return;
    p.last = z;
    const [hr, hi] = rings(p.x - 1.8, PY + PR - 2, p.x + 1.8, PY + PR + 11, 1.6, 0.5);
    put(p.handle, prism(P, front, hr, hi, z, z + 3));
    put(p.face, prism(P, front, disc(p.x, PY, PR), disc(p.x, PY, PR - 1.6), z, z + 1.6));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const p of pads) { draw(p, tval(p.z, now)); if (!tdone(p.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = pads.map((p) => P(p.x, PY, top));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 70 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    pads.forEach((p, k) => {
      tset(p.z, a < 0 ? (k === 0 ? 0.7 : 0) : k === a ? 1 : 0, now, 0);
      p.face.sil.classList.toggle("hi", k === (a < 0 ? 0 : a));
      p.handle.sil.classList.toggle("hi", k === (a < 0 ? 0 : a));
    });
    read.textContent = a < 0 ? "rest" : a === 0 ? "far" : "near";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = clamp(v, 6, 30); pads.forEach((p) => { p.last = NaN; }); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "pingpong",
  means: "A ping pong table with a paddle at each end: the paddle on the side under the pointer lifts off the table, ready to serve.",
  rules: [1, 3, 5, 6],
  range: [6, 22, 30],
  tour: [[158, 124], [255, 173], [158, 124], null],
  mount,
});

crutches.code:
/**
 * Crutches: three crutches standing in a row on a mat, each a leg with a
 * rubber foot, two rails splitting up to an underarm pad, and a hand grip
 * between the rails. The pointer picks a crutch by where it stands: it swings
 * forward from its foot like a step, and the crutches beside it lean a
 * little, staggered from it. At rest one crutch leans out, bright. The slider
 * is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 30, MZ = 2, SWING = 24, FAV = 1;
const REST = [-5, 13, -2];
// the crutch in its own plane: [u0, z0, u1, z1, radius], back to front
const PARTS = [
  [-5, 29, -5, 40, 1.2], [-5, 40, -5, 62, 1.2], [0, 26, -5, 40, 1.2],
  [0, 0, 0, 3.5, 2.6], [0, 2, 0, 30, 1.5], [0, 25, 0, 30, 2.2],
  [-5, 44, 5, 44, 1.8],
  [0, 26, 5, 40, 1.2], [5, 40, 5, 62, 1.2], [-8, 64, 8, 64, 2.8],
];
const SPH = [];
for (let i = 0; i < 12; i++) {
  const a = (i / 12) * Math.PI * 2, c = Math.cos(a), s = Math.sin(a);
  SPH.push([c, s, 0], [c, 0, s], [0, c, s]);
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.9);
  const X1 = (N - 1) * STEP;
  const lean = (d) => Math.sin((d * Math.PI) / 180) * 66;
  fit(C, [[-14, -10, 0], [X1 + 14, 10, 0], [-10, lean(SWING) + 4, 66], [X1 + 10, lean(SWING) + 4, 66], [-10, lean(-8) - 4, 66], [X1 + 10, -10, 0]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [mr, mi] = rings(-14, -10, X1 + 14, 10, 5, 1.6);
  put(solid(g), prism(P, front, mr, mi, 0, MZ));

  const cap = (pts) => poly(hull(pts));
  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    const paths = PARTS.map(() => mk("path", { class: "sil" }, grp));
    items.push({ k, x: k * STEP, grp, paths, t: tween(REST[k]), last: NaN });
  }

  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const a = (deg * Math.PI) / 180, sa = Math.sin(a), ca = Math.cos(a);
    const W = (u, z) => [it.x + u, z * sa, MZ + z * ca];
    PARTS.forEach(([u0, z0, u1, z1, r], i) => {
      const A = W(u0, z0), Bp = W(u1, z1), pts = [];
      for (const [dx, dy, dz] of SPH) {
        pts.push(P(A[0] + dx * r, A[1] + dy * r, A[2] + dz * r), P(Bp[0] + dx * r, Bp[1] + dy * r, Bp[2] + dz * r));
      }
      it.paths[i].setAttribute("d", cap(pts));
    });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.t, now)); if (!tdone(it.t, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  // hit against the rest pose: each crutch's standing centre on screen
  const mids = items.map((it) => P(it.x, 0, MZ + 32));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 28 && Math.abs(mids[best][1] - sy) < 110 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), deg = a < 0 ? REST[k] : dd === 0 ? SWING : dd === 1 ? 5 : 0;
      tset(it.t, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      it.paths.forEach((p) => p.classList.toggle("hi", on));
    });
    read.textContent = a < 0 ? "rest" : "step " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "crutches",
  means: "Three crutches on a mat: the crutch under the pointer swings forward from its foot like a step, and its neighbours lean a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[160, 136], [221, 167], [283, 198], null],
  mount,
});

dentalchair.code:
/**
 * Dental chair: a padded seat on a pedestal, its backrest hinged at the seat,
 * an overhead lamp on a pole behind. The pointer's place across the chair
 * sets the recline: the backrest tilts back on a spring and lights. At rest
 * the back stands half-reclined and the lamp head is the bright mark.
 */
const {
  Cam, clamp, fit, facing, hull, lerp, poly, prism, proj, rad, rings, rrect, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid, unproj,
} = HL;

const SZ = 30, L = 46, T = 6, REST = 58, A0 = 18, A1 = 80;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-46, 0, 0], [70, 26, 0], [-46, 26, SZ + 50], [40, -18, 100], [70, -18, 0], [-10, 2, SZ + L]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [fr, fi] = rings(-6, -2, 62, 28, 6, 2);
  put(solid(g), prism(P, front, fr, fi, 0, 3));
  // lamp pole, behind the chair
  const [pr, pi] = rings(36, -20, 42, -14, 3, 1);
  put(solid(g), prism(P, front, pr, pi, 0, 96));
  const back = solid(g);
  const [dr, di] = rings(16, 6, 36, 20, 5, 1.5);
  put(solid(g), prism(P, front, dr, di, 3, SZ - 4));
  const [sr, si] = rings(0, 2, 50, 24, 5, 1.6);
  put(solid(g), prism(P, front, sr, si, SZ - 4, SZ));
  // leg rest sloping down from the seat's end
  const legO = rrect(0, 2, 24, 24, 5, 4), legI = rrect(1.6, 3.6, 22.4, 22.4, 3.4, 4);
  const legAt = (ring, t) => ring.map((q) => P(50 + q.u * Math.cos(rad(32)) , q.v, SZ - q.u * Math.sin(rad(32)) - 4 + t));
  const leg = solid(g);
  leg.sil.setAttribute("d", poly(hull(legAt(legO, 0).concat(legAt(legO, 4)))));
  leg.cr.setAttribute("d", poly(legAt(legI, 4)));
  // arm and lamp head over the seat
  mk("path", { d: seg(P(39, -17, 96), P(22, 8, 86)), class: "nf" }, g);
  const [hr, hi] = rings(14, 2, 30, 14, 5, 1.5);
  const head = solid(g);
  put(head, prism(P, front, hr, hi, 80, 86));
  head.sil.classList.add("hi");

  const bO = rrect(0, 2, L, 24, 6, 4), bI = rrect(1.8, 3.8, L - 1.8, 22.2, 4.2, 4);
  const at = (ring, a, t) => ring.map((q) => P(-q.u * Math.cos(a) + t * Math.sin(a), q.v, SZ + q.u * Math.sin(a) + t * Math.cos(a)));
  const ang = spring(REST);
  let last = NaN;
  function draw() {
    const a = r2a(ang.x);
    if (a === last) return;
    last = a;
    back.sil.setAttribute("d", poly(hull(at(bO, rad(a), 0).concat(at(bO, rad(a), T)))));
    back.cr.setAttribute("d", poly(at(bI, rad(a), T)));
  }
  const r2a = (v) => Math.round(v * 10) / 10;
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(); return m; });
  bag.add(B.unregister);

  const sx0 = P(-30, 12, 0)[0], sx1 = P(60, 12, 0)[0];
  let on = null;
  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, 0);
    const inside = wx > -50 && wx < 75 && wy > -25 && wy < 35;
    if (!inside) return leave();
    const t = clamp((sx - sx0) / (sx1 - sx0), 0, 1);
    ang.t = lerp(REST, lerp(A1, A0, t), reach / 100);
    if (on !== true) { on = true; back.sil.classList.add("hi"); head.sil.classList.remove("hi"); }
    read.textContent = Math.round(ang.t) + "°";
    B.wake();
  }
  function leave() {
    ang.t = REST;
    if (on !== false) { on = false; back.sil.classList.remove("hi"); head.sil.classList.add("hi"); }
    read.textContent = "rest";
    B.wake();
  }
  leave();
  draw();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "dentalchair",
  means: "A dental chair under its lamp: the pointer's place across the chair reclines the backrest on its hinge.",
  rules: [1, 3, 5, 8],
  range: [20, 100, 100],
  tour: [[124, 201], [170, 223], [253, 265], null],
  mount,
});

pillbottles.code:
/**
 * Pill bottles: four round bottles of different heights on a shelf, each
 * with a ridged cap. The pointer picks a bottle by where it stands: its cap
 * lifts off, and the caps beside it rise a little, staggered from it. At rest
 * one cap sits loosened, bright. The slider is the stagger.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 30, R = 11, LIFT = 18, FAV = 2, SZ = 4, CH = 7;
const H = [30, 40, 26, 34];
const X1 = (N - 1) * STEP + 2 * R;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-6, -6, 0], [X1 + 6, 2 * R + 6, 0], [X1 + 6, -6, 0], [-6, 2 * R + 6, 0], [R + STEP, R, SZ + 40 + CH + LIFT], [X1 - R, R, SZ + 34 + CH + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-6, -6, X1 + 6, 2 * R + 6, 5, 2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = R + k * STEP, y = R, grp = mk("g", {}, g), top = SZ + H[k];
    put(solid(grp), prism(P, front, disc(x, y, R), disc(x, y, R - 1.6), SZ, top));
    // the label band: one dim ring around the body
    mk("path", { d: open(ringAt(P, disc(x, y, R, 32).filter(front), SZ + H[k] * 0.35)), class: "nf lo" }, grp);
    mk("path", { d: open(ringAt(P, disc(x, y, R, 32).filter(front), SZ + H[k] * 0.75)), class: "nf lo" }, grp);
    const cap = solid(grp), ridges = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, y, top, cap, ridges, z: tween(k === FAV ? LIFT * 0.4 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = it.top + 0.4 + lift;
    put(it.cap, prism(P, front, disc(it.x, it.y, R + 1), disc(it.x, it.y, R - 0.6), z0, z0 + CH));
    let d = "";
    for (const q of disc(it.x, it.y, R + 1, 24)) if (front(q) && q.nu + q.nv > -0.2) { const a = P(q.u, q.v, z0 + 1.4), b = P(q.u, q.v, z0 + CH - 1.4); d += `M${a[0]} ${a[1]}L${b[0]} ${b[1]}`; }
    it.ridges.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, SZ + it.top / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.4 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.cap.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "rx " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "pillbottles",
  means: "Four pill bottles on a shelf: the cap of the bottle under the pointer twists up and off, and its neighbours loosen a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[127, 136], [176, 151], [273, 209], null],
  mount,
});

wardrobe.code:
/**
 * Wardrobe: a tall cabinet with two doors on its front, a rail of hangers
 * inside. The pointer picks a door by where it stands: that door swings open
 * on its hinge to show the clothes, and the other closes. At rest the left
 * door stands ajar, bright. The slider is how far a door swings.
 *
 * The pattern: one of two in a single row (riffle).
 */
const {
  Cam, fit, facing, fillet, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 64, D = 30, H = 104, Z0 = 4, ZT = H - 5, DW = W / 2 - 2, AJAR = 24;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-2, -2, 0], [W + 2, D + DW + 4, 0], [W + 2, -2, H], [-2, D + DW + 4, H], [W + 2, D + 2, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-2, -2, W + 2, D + 2, 3, 1.2);
  put(solid(g), prism(P, front, pr, pi, 0, Z0));
  const [br, bi] = rings(0, 0, W, D, 4, 1.5);
  put(solid(g), prism(P, front, br, bi, Z0, H));
  // inside: a rail and hangers with clothes, seen when a door opens
  let ins = seg(P(4, D, H - 16), P(W - 4, D, H - 16));
  for (let i = 0; i < 6; i++) {
    const x = 8 + i * 9.6, top = H - 16, sh = top - 6, len = [34, 46, 30, 52, 40, 36][i];
    ins += seg(P(x, D, top), P(x - 4, D, sh)) + seg(P(x, D, top), P(x + 4, D, sh));
    ins += "M" + [P(x - 4, D, sh), P(x - 4, D, sh - len), P(x + 4, D, sh - len), P(x + 4, D, sh)].map((q) => q.join(",")).join("L");
  }
  mk("path", { d: ins, class: "nf lo" }, g);

  const doors = [0, 1].map((k) => {
    const grp = mk("g", {}, g);
    const sil = mk("path", { class: "sil" }, grp), knob = mk("path", { class: "nf lo" }, grp);
    return { k, hx: k ? W - 1 : 1, dir: k ? -1 : 1, sil, knob, a: tween(k === 0 ? AJAR : 0), last: NaN };
  });

  function draw(d, a) {
    if (a === d.last) return;
    d.last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a)), fx = d.hx + d.dir * DW * c, fy = D + DW * s;
    const pts = [P(d.hx, D, Z0 + 3), P(d.hx, D, ZT), P(fx, fy, ZT), P(fx, fy, Z0 + 3)];
    d.sil.setAttribute("d", poly(fillet(pts, [2, 2, 2, 2])));
    const kx = d.hx + d.dir * (DW - 4) * c, ky = D + (DW - 4) * s;
    d.knob.setAttribute("d", seg(P(kx, ky, H / 2 - 8), P(kx, ky, H / 2 + 8)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const d of doors) { draw(d, tval(d.a, now)); if (!tdone(d.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = [P(W / 4, D, H / 2), P((3 * W) / 4, D, H / 2)];
  function hit([sx, sy]) {
    const k = Math.abs(mids[0][0] - sx) < Math.abs(mids[1][0] - sx) ? 0 : 1;
    return Math.abs(mids[k][0] - sx) < 40 && Math.abs(mids[k][1] - sy) < 95 ? k : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    doors.forEach((d) => {
      tset(d.a, a < 0 ? (d.k === 0 ? AJAR : 0) : d.k === a ? swing : 4, now, 0);
      d.sil.classList.toggle("hi", d.k === (a < 0 ? 0 : a));
    });
    read.textContent = a < 0 ? "rest" : a === 0 ? "left" : "right";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; if (act >= 0) { const a = act; act = -2; setActive(a); } }, destroy: bag.dispose };
}

hairline({
  name: "wardrobe",
  means: "A wardrobe with two doors: the door under the pointer swings open on its hinge to show the hangers, the other closes.",
  rules: [1, 4, 5, 8],
  range: [60, 100, 120],
  tour: [[143, 95], [254, 95], [226, 238], null],
  mount,
});

whiteboard.code:
/**
 * Whiteboard: a board on two legs with a marker tray under it, four markers
 * lying in the tray. The pointer picks a marker by where it stands: it lifts
 * out of the tray, and the markers beside it rise a little, staggered from
 * it. At rest one marker is raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rings, rrect, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, ML = 18, MW = 4.2, MX0 = 26, MSTEP = 21, TZ = 42, LIFT = 22, FAV = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-4, -16, 0], [134, 20, 0], [134, -16, 0], [-4, 20, 0], [0, 0, 112], [130, 3, 112], [MX0, 8, TZ + LIFT + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1, parent = g) => { const [o, i] = rings(x0, y0, x1, y1, r, b); return put(solid(parent), prism(P, front, o, i, z0, z1)); };

  // legs and feet, then the board, then the tray in front of it
  for (const lx of [10, 120]) { box(lx - 4, -16, lx + 4, 20, 2, 0.8, 0, 3); box(lx - 2, -0.5, lx + 2, 3.5, 1, 0.6, 3, 44); }
  box(0, 0, 130, 3, 1.4, 0.7, 40, 110);
  // what is drawn on the board: two notes and a bar sketch, dim
  const face = (x0, z0, x1, z1) => poly([P(x0, 3.05, z0), P(x1, 3.05, z0), P(x1, 3.05, z1), P(x0, 3.05, z1)]);
  mk("path", { d: face(14, 82, 30, 98), class: "nf lo" }, g);
  mk("path", { d: face(34, 86, 48, 100), class: "nf lo" }, g);
  for (const [x, h] of [[70, 12], [82, 22], [94, 16], [106, 30]]) mk("path", { d: face(x, 54, x + 7, 54 + h), class: "nf lo" }, g);
  box(20, 3, 110, 12, 1.6, 0.8, TZ - 4, TZ);
  mk("path", { d: poly(ringAt(P, rrect(21.5, 4.5, 108.5, 10.5, 1.2, 3), TZ)), class: "nf lo" }, g);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = MX0 + k * MSTEP, grp = mk("g", {}, g);
    const body = solid(grp), cap = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, body, cap, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }
  const [mo, mi] = rings(0, 0, ML, MW, 1.8, 0.6);
  const sh = (ring, dx) => ring.map((q) => ({ ...q, u: q.u + dx, v: q.v + 5.7 }));

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = TZ + lift;
    put(it.body, prism(P, front, sh(mo, it.x), sh(mi, it.x), z0, z0 + MW));
    // the cap: a seam two thirds of the way along
    const c0 = it.x + ML * 0.68;
    it.cap.setAttribute("d", open([P(c0, 5.7 + MW, z0), P(c0, 5.7 + MW, z0 + MW), P(c0, 5.7, z0 + MW)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + ML / 2, 7.5, TZ + 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 40 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 6 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "pen " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "whiteboard",
  means: "A whiteboard with a marker tray: the marker under the pointer lifts out of the tray, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[149, 162], [209, 192], [240, 207], null],
  mount,
});

mailtray.code:
/**
 * Letter trays: three trays stacked between two side panels, each holding a
 * pile of sheets. The pointer picks a tray by height: it slides out toward
 * the reader, and the trays beside it slide a little, staggered from it. At
 * rest the middle tray stands half out, bright. The slider is the stagger.
 *
 * The pattern: one of many in a stack, picked by rest pose (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, W = 64, D = 46, TH = 8, GAP = 15, Z0 = 3, OUT = 24, FAV = 1, H = Z0 + (N - 1) * GAP + TH + 6;
const PILE = [2.4, 4, 1.4];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[-3, -2, 0], [W + 3, D + 2, 0], [W + 3, -2, H], [-3, -2, H], [0, D + OUT, Z0], [W, D + OUT, Z0], [-3, D + 2, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1, parent = g) => { const [o, i] = rings(x0, y0, x1, y1, r, b); return put(solid(parent), prism(P, front, o, i, z0, z1)); };

  // far panel, the trays from the bottom up, then the near panel over them
  box(-3, -2, 0, D + 2, 1.2, 0.6, 0, H);
  box(-3, -2, W + 3, D + 2, 3, 1.4, 0, 2.4);
  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    items.push({ k, z: Z0 + k * GAP, grp, tray: solid(grp), pile: solid(grp), y: tween(k === FAV ? OUT * 0.5 : 0), last: NaN });
  }
  box(W, -2, W + 3, D + 2, 1.2, 0.6, 0, H);

  function draw(it, dy) {
    if (dy === it.last) return;
    it.last = dy;
    const [o, i] = rings(1, dy, W - 1, D + dy, 3, 2.2);
    put(it.tray, prism(P, front, o, i, it.z, it.z + TH));
    const [po, pi] = rings(7, dy + 5, W - 9, D + dy - 7, 1, 0.8);
    put(it.pile, prism(P, front, po, pi, it.z + TH, it.z + TH + PILE[it.k]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.y, now)); if (!tdone(it.y, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  // hit: each tray's rest front, nearest on screen
  const mids = items.map((it) => P(W / 2, D, it.z + TH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 22 && Math.abs(mids[best][0] - sx) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), y = a < 0 ? (k === FAV ? OUT * 0.5 : 0) : dd === 0 ? OUT : dd === 1 ? 5 : 0;
      tset(it.y, y, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.tray.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tray " + (N - a);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

