clawmachine.code:
/**
 * Claw machine: a cabinet with a glass case over a pit of prizes, a gantry
 * rail under the roof and a claw on a cable. The pointer over the pit steers
 * the claw: it slides over the prize below and drops toward it on its cable.
 * At rest the claw hangs high over the chute corner, bright. The slider is
 * how far the claw drops.
 *
 * The pattern: one part following the pointer over a ground plane (terrain).
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rings, ringAt, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 60, BZ = 34, GZ = 92, HZ = 104, TOPZ = 86, REST = [50, 10];
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const PRIZES = [[14, 14, 6], [28, 10, 5], [12, 30, 5], [26, 26, 7], [42, 34, 6], [16, 46, 6], [32, 44, 5], [46, 48, 6], [44, 18, 4]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let drop = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[0, 0, 0], [W, W, 0], [W, 0, 0], [0, W, 0], [0, 0, HZ], [W, W, HZ], [W, 0, HZ], [0, W, HZ]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // back posts and back glass edges, behind everything
  mk("path", { d: seg(P(0, 0, BZ), P(0, 0, GZ)) + seg(P(W, 0, BZ), P(W, 0, GZ)) + seg(P(0, W, BZ), P(0, W, GZ)), class: "nf lo" }, g);
  const [br, bi] = rings(0, 0, W, W, 4, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  // the chute: a square opening on the front corner of the pit floor
  mk("path", { d: poly(ringAt(P, rings(W - 16, W - 16, W - 3, W - 3, 2, 1)[0], BZ)), class: "nf lo" }, g);

  // prizes: little round lumps, back to front
  [...PRIZES].sort((a, b) => a[0] + a[1] - b[0] - b[1]).forEach(([x, y, r]) => {
    const pts = [];
    for (let i = 0; i <= 4; i++) { const t = (i / 4) * (Math.PI / 2); pts.push(...ringAt(P, disc(x, y, r * Math.cos(t) + 0.3), BZ + r * 0.9 * (1 + Math.sin(t)))); }
    mk("path", { d: poly(hull(pts)) }, g);
  });

  // gantry rail under the roof
  const rail = mk("path", { class: "nf lo" }, g);
  const cable = mk("path", { class: "nf lo" }, g);
  const head = solid(g), prongs = mk("path", { class: "nf" }, g);
  head.sil.classList.add("hi");

  // front posts, glass rim and the roof header
  mk("path", { d: seg(P(W, W, BZ), P(W, W, GZ)), class: "nf lo" }, g);
  mk("path", { d: poly(ringAt(P, br, GZ)), class: "nf lo" }, g);
  const [hr, hi] = rings(-2, -2, W + 2, W + 2, 4, 1.6);
  const roof = solid(g);
  put(roof, prism(P, front, hr, hi, GZ, HZ));
  roof.g.querySelector("path").classList.add("nf");

  const sx = spring(REST[0]), sy = spring(REST[1]), sz = spring(TOPZ);
  let last = "";
  function draw() {
    const x = sx.x, y = sy.x, z = sz.x, key = [x, y, z].map((n) => n.toFixed(2)).join();
    if (key === last) return;
    last = key;
    rail.setAttribute("d", seg(P(0, y, GZ - 2), P(W, y, GZ - 2)) + seg(P(x, 0, GZ - 2), P(x, W, GZ - 2)));
    cable.setAttribute("d", seg(P(x, y, GZ - 2), P(x, y, z + 8)));
    const [r0, r1] = [disc(x, y, 6), disc(x, y, 4.2)];
    put(head, prism(P, front, r0, r1, z, z + 8));
    let d = "";
    for (const a of [0, 2.09, 4.19]) {
      const c = Math.cos(a + 0.8), s = Math.sin(a + 0.8);
      d += open([P(x + 5 * c, y + 5 * s, z), P(x + 11 * c, y + 11 * s, z - 9), P(x + 6 * c, y + 6 * s, z - 17)]);
    }
    prongs.setAttribute("d", d);
  }

  const B = register(stage, (dt) => {
    const m = [sx, sy, sz].map((sp) => stepS(sp, dt)).some(Boolean);
    draw();
    return m;
  });
  bag.add(B.unregister);

  function aim(p) {
    const [wx, wy] = p ? unproj(C, p[0], p[1], BZ) : [NaN, NaN];
    const inside = p && wx > -4 && wx < W + 4 && wy > -4 && wy < W + 4;
    if (inside) {
      sx.t = clamp(wx, 8, W - 8); sy.t = clamp(wy, 8, W - 8);
      sz.t = TOPZ - (TOPZ - BZ - 20) * drop;
      read.textContent = "x" + (1 + Math.floor(sx.t / 15)) + "·" + (1 + Math.floor(sy.t / 15));
    } else {
      sx.t = REST[0]; sy.t = REST[1]; sz.t = TOPZ;
      read.textContent = "rest";
    }
    B.wake();
  }
  aim(null);
  draw();
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { drop = v; }, destroy: bag.dispose };
}

hairline({
  name: "clawmachine",
  means: "A claw machine over a pit of prizes: the claw slides over the prize under the pointer and drops toward it on its cable.",
  rules: [1, 3, 5, 8],
  range: [0, 0.7, 1],
  tour: [[173, 196], [228, 204], [205, 165], null],
  mount,
});

rockinghorse.code:
/**
 * Rocking horse: a wooden horse on two curved runners. The pointer's side
 * sets the rock: to the right the nose dips and the runners roll forward, to
 * the left it sits back. At rest it leans back a little, the saddle bright.
 * The slider is how far it rocks.
 *
 * The pattern: one object tilting toward the pointer (spring).
 */
const {
  Cam, fit, facing, hull, open, poly, proj, rings, run, clamp, rad, spring, stepS,
  disposer, mk, pointer, register, solid,
} = HL;

const R = 60, A = 0.58, BAND = 3.2, REST = -4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 3.3);
  fit(C, [[-42, -12, 0], [44, 12, 0], [-42, 12, 0], [44, -12, 0], [-30, 0, 46], [36, 0, 66], [0, 0, 70]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // a world point on the horse, rolled by th along its runners
  const T = (th) => { const c = Math.cos(th), s = Math.sin(th), ox = R * th;
    return (x, y, z) => { const dz = z - R; return P(ox + x * c + dz * s, y, R + dz * c - x * s); }; };

  const part = (x0, y0, x1, y1, r, b, z0, z1, sh = 0) => { const [ring, inner] = rings(x0, y0, x1, y1, r, b); return { ring, inner, z0, z1, sh }; };
  const rocker = (y) => ({ y, rk: true });
  const parts = [
    rocker(-9.5), rocker(-8),
    part(-16, -9, -12, -6, 1.4, 0.6, 5.5, 26), part(12, -9, 16, -6, 1.4, 0.6, 5.5, 26),
    part(-27, -2, -21, 2, 2, 0.8, 26, 40, -6),
    part(-20, -7, 20, 7, 5, 1.5, 24, 36),
    part(-8, -7.6, 7, 7.6, 3, 1, 36, 37.6),
    part(12, -4, 22, 4, 3, 1, 34, 52, 5),
    part(16, -4.2, 34, 4.2, 4, 1.2, 48, 58),
    part(17, -3, 21, 3, 1.5, 0.6, 58, 62),
    part(-16, 6, -12, 9, 1.4, 0.6, 5.5, 26), part(12, 6, 16, 9, 1.4, 0.6, 5.5, 26),
    rocker(8), rocker(9.5),
  ];
  for (const p of parts) p.s = p.rk ? { g: mk("g", {}, g), sil: null } : solid(g);
  for (const p of parts) if (p.rk) p.s.sil = mk("path", { class: p.y > 0 && p.y > 9 || p.y < -9 ? "sil" : "lo" }, p.s.g);
  const saddle = parts[6].s.sil, head = parts[8].s.sil, tail = parts[4].s.sil;

  function draw(th) {
    const tp = T(th);
    for (const p of parts) {
      if (p.rk) {
        const out = [], inn = [];
        for (let i = 0; i <= 24; i++) { const f = -A + (2 * A * i) / 24;
          out.push(tp(R * Math.sin(f), p.y, R - R * Math.cos(f)));
          inn.push(tp((R - BAND) * Math.sin(f), p.y, R - (R - BAND) * Math.cos(f))); }
        const tipA = tp(R * Math.sin(-A) - 3, p.y, R - R * Math.cos(-A) + 4), tipB = tp(R * Math.sin(A) + 3, p.y, R - R * Math.cos(A) + 4);
        p.s.sil.setAttribute("d", poly([tipA, ...out, tipB, ...inn.reverse()]));
        continue;
      }
      const top = p.ring.map((q) => tp(q.u + p.sh, q.v, p.z1));
      p.s.sil.setAttribute("d", poly(hull(p.ring.map((q) => tp(q.u, q.v, p.z0)).concat(top))));
      p.s.cr.setAttribute("d", open(run(p.inner, front).map((q) => tp(q.u + p.sh, q.v, p.z1))));
    }
  }

  const th = spring(rad(REST));
  let last = NaN;
  const B = register(stage, (dt) => {
    const moving = stepS(th, dt);
    if (th.x !== last) { last = th.x; draw(th.x); }
    return moving;
  });
  bag.add(B.unregister);
  draw(th.x);

  const cx = P(0, 0, 30)[0];
  let mode = "";
  function aim(sx) {
    const f = sx == null ? null : clamp((sx - cx) / 80, -1, 1);
    const deg = f == null ? REST : f * max;
    th.t = rad(deg);
    const m = f == null ? "rest" : f > 0.15 ? "head" : f < -0.15 ? "tail" : "seat";
    if (m !== mode) { mode = m;
      saddle.classList.toggle("hi", m === "rest" || m === "seat");
      head.classList.toggle("hi", m === "head");
      tail.classList.toggle("hi", m === "tail"); }
    read.textContent = f == null ? "rest" : (deg >= 0 ? "+" : "") + Math.round(deg) + "°";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p[0]), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; if (mode !== "rest") B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "rockinghorse",
  means: "A rocking horse on curved runners: the pointer's side rocks it, nose down to the right, sitting back to the left.",
  rules: [1, 3, 4, 5, 8],
  range: [4, 12, 18],
  tour: [[256, 117], [104, 181], [200, 150], null],
  mount,
});

tricycles.code:
/**
 * Tricycles: three children's tricycles parked side by side on a play mat,
 * each facing the same way. The pointer picks a tricycle by where it stands:
 * it rolls forward, its wheels turning as it goes, and the ones beside it
 * creep forward a little, staggered from it. At rest one has rolled out of
 * line, its front wheel bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, GAP = 42, RR = 7, FR = 11, ROLL = 18, FAV = 1, MZ = 2;
const REST = [3, 12, 0];
const Y0 = 14, YN = Y0 + (N - 1) * GAP;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-14, -2, 0], [64, -2, 0], [64, YN + 14, 0], [-14, YN + 14, 0], [24 + ROLL, Y0, MZ + 32], [0, YN, MZ + 26]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [mr, mi] = rings(-14, -2, 64, YN + 14, 8, 2);
  put(solid(g), prism(P, front, mr, mi, 0, MZ));

  // a wheel standing in the xz plane, centre (x, y, z), radius r, width w
  const loop = (x, y, z, r) => { const o = []; for (let i = 0; i < 32; i++) { const a = (i / 32) * Math.PI * 2; o.push(P(x + r * Math.cos(a), y, z + r * Math.sin(a))); } return o; };
  function wheel(el, x, y, z, r, w, turn) {
    el.s.setAttribute("d", poly(hull(loop(x, y - w / 2, z, r).concat(loop(x, y + w / 2, z, r)))));
    let sp = poly(loop(x, y + w / 2, z, r * 0.42));
    for (let i = 0; i < 3; i++) { const a = turn + (i / 3) * Math.PI * 2; sp += seg(P(x + r * 0.42 * Math.cos(a), y + w / 2, z + r * 0.42 * Math.sin(a)), P(x + r * 0.82 * Math.cos(a), y + w / 2, z + r * 0.82 * Math.sin(a))); }
    el.c.setAttribute("d", sp);
  }
  const wheelEls = (grp, cls) => ({ s: mk("path", { class: cls }, grp), c: mk("path", { class: "nf lo" }, grp) });

  const items = [];
  for (let k = 0; k < N; k++) {
    const y = Y0 + k * GAP, grp = mk("g", {}, g);
    const it = { k, y, grp, last: NaN, d: tween(REST[k]) };
    it.rearFar = wheelEls(grp, "sil");
    it.frame = mk("path", { class: "nf" }, grp);
    it.seat = solid(grp);
    it.rearNear = wheelEls(grp, "sil");
    it.fork = mk("path", { class: "nf" }, grp);
    it.front = wheelEls(grp, "sil");
    it.bar = mk("path", { class: "nf" }, grp);
    items.push(it);
  }

  function draw(it, d) {
    if (d === it.last) return;
    it.last = d;
    const y = it.y, z0 = MZ, x = d;
    const rz = z0 + RR, fz = z0 + FR, fx = x + 26;
    wheel(it.rearFar, x, y - 10, rz, RR, 3, -d / RR);
    it.frame.setAttribute("d", seg(P(x, y - 10, rz), P(x, y + 10, rz)) + open([P(x, y, rz), P(x + 6, y, z0 + 20), P(fx - 3, y, z0 + 22)]) + seg(P(x + 3, y, rz + 3), P(fx - 3, y, z0 + 22)));
    const [sr, si] = rings(x + 1, y - 5, x + 11, y + 5, 4, 1.2);
    put(it.seat, prism(P, front, sr, si, z0 + 20, z0 + 23));
    wheel(it.rearNear, x, y + 10, rz, RR, 3, -d / RR);
    it.fork.setAttribute("d", seg(P(fx - 3, y - 2.5, z0 + 22), P(fx, y - 2.5, fz)));
    wheel(it.front, fx, y, fz, FR, 4, -d / FR);
    const hz = z0 + 29;
    it.bar.setAttribute("d", seg(P(fx - 3, y + 2.5, z0 + 22), P(fx, y + 2.5, fz)) + open([P(fx - 3, y, z0 + 22), P(fx - 4, y, hz)]) + seg(P(fx - 6, y - 10, hz), P(fx - 4, y + 10, hz)) + seg(P(fx - 6, y - 10, hz), P(fx - 9, y - 11, hz)) + seg(P(fx - 4, y + 10, hz), P(fx - 7, y + 11, hz)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.d, now)); if (!tdone(it.d, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(13 + REST[it.k], it.y, MZ + 12));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), d = a < 0 ? REST[k] : dd === 0 ? REST[k] + ROLL : REST[k] + 4;
      tset(it.d, d, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.front.s.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "trike " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "tricycles",
  means: "Three tricycles parked on a play mat: the one under the pointer rolls forward, wheels turning, and its neighbours creep after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[285, 135], [208, 155], [135, 175], null],
  mount,
});

dogkennel.code:
/**
 * Dog kennel: a gabled kennel with an arched door on a garden slab, a water
 * bowl beside it. The pointer over the kennel lifts its roof off to show the
 * rim of the walls; over the bowl, the bowl slides out. At rest the roof sits
 * a little ajar, bright. The slider is how far the roof lifts.
 *
 * The pattern: parts of one object, picked on the ground (terrain).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SZ = 2, WZ = SZ + 26, RZ = WZ + 15, BX = 54, BY = 22;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-10, -10, 0], [72, -10, 0], [72, 46, 0], [-10, 46, 0], [-3, 17, RZ + 24], [43, 17, RZ + 24]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-10, -10, 72, 46, 6, 2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));

  const [wr, wi] = rings(0, 0, 40, 34, 3, 1.5);
  put(solid(g), prism(P, front, wr, wi, SZ, WZ));
  const door = [];
  for (let i = 0; i <= 12; i++) { const a = (i / 12) * Math.PI; door.push(P(20 + 7 * Math.cos(a), 34, SZ + 12 + 7 * Math.sin(a))); }
  mk("path", { d: open([P(27, 34, SZ)].concat(door, [P(13, 34, SZ)])), class: "nf" }, g);
  mk("path", { d: poly(ringAt(P, rings(2, 2, 38, 32, 2, 1)[0], WZ)), class: "nf lo" }, g);

  const roof = mk("path", { class: "sil" }, g), roofC = mk("path", { class: "nf lo" }, g);
  const bowlG = mk("g", {}, g), bowl = solid(bowlG);
  const water = mk("path", { class: "nf lo" }, bowlG);

  const lift = tween(4), slide = tween(0);
  let lastL = NaN, lastS = NaN;
  function draw(l, s) {
    if (l !== lastL) {
      lastL = l;
      const ez = WZ + l, rz = RZ + l, eave = [P(-3, -3, ez), P(43, -3, ez), P(43, 37, ez), P(-3, 37, ez)];
      roof.setAttribute("d", poly(hull(eave.concat([P(-3, 17, rz), P(43, 17, rz)]))));
      roofC.setAttribute("d", seg(P(-3, 17, rz - 1), P(43, 17, rz - 1)) + open([P(43, 37, ez), P(43, 17, rz), P(43, -3, ez)]) + seg(P(-3, 37, ez + 1.5), P(43, 37, ez + 1.5)));
    }
    if (s !== lastS) {
      lastS = s;
      const x = BX + s;
      put(bowl, prism(P, front, disc(x, BY, 6), disc(x, BY, 4.6), SZ, SZ + 4));
      water.setAttribute("d", poly(ringAt(P, disc(x, BY, 3.6, 24), SZ + 3)));
    }
  }

  const B = register(stage, (_dt, now) => {
    draw(tval(lift, now), tval(slide, now));
    return !tdone(lift, now) || !tdone(slide, now);
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [bx, by] = unproj(C, sx, sy, SZ);
    if (Math.hypot(bx - BX, by - BY) < 10) return 1;
    for (const z of [SZ, WZ, RZ]) { const [x, y] = unproj(C, sx, sy, z); if (x > -4 && x < 44 && y > -4 && y < 38) return 0; }
    return -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    tset(lift, a === 0 ? 8 + 16 * reach : a < 0 ? 4 : 0, now, 0);
    tset(slide, a === 1 ? 9 : 0, now, 0);
    roof.classList.toggle("hi", a <= 0);
    bowl.sil.classList.toggle("hi", a === 1);
    read.textContent = a < 0 ? "rest" : a === 0 ? "roof" : "bowl";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (act === 0) { act = -2; setActive(0); } }, destroy: bag.dispose };
}

hairline({
  name: "dogkennel",
  means: "A gabled dog kennel and its water bowl: over the kennel the roof lifts off, over the bowl it slides out.",
  rules: [1, 3, 5, 6],
  range: [0, 0.6, 1],
  tour: [[200, 120], [250, 190], [190, 150], null],
  mount,
});

dogleashes.code:
/**
 * Dog leashes: a wall board with five hooks, a leash hung on each by its
 * handle loop, strap and clasp hanging below. The pointer picks a leash by
 * where it stands: it lifts off its hook, ready for a walk, and its
 * neighbours sway a little, staggered from it. At rest one leash is lifted,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, open, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 30, HZ = 92, LIFT = 12, FAV = 3;
const X1 = (N + 1) * STEP;
const LEN = [38, 52, 30, 46, 40];
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, -6, 0], [X1, 0, 0], [X1, -6, HZ + 14], [0, -6, HZ + 14], [X1, 14, 0], [0, 14, HZ + LIFT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, -6, X1, 0, 3, 1.2);
  put(solid(g), prism(P, front, br, bi, 0, HZ + 14));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = STEP * (k + 1), grp = mk("g", {}, g);
    const [hr, hi] = rings(x - 2.5, 0, x + 2.5, 9, 2.4, 0.6);
    put(solid(grp), prism(P, front, hr, hi, HZ - 3, HZ + 2));
    const loop = mk("path", { class: "nf sil" }, grp), strap = mk("path", { class: "nf sil" }, grp);
    const clasp = solid(grp);
    items.push({ k, x, grp, loop, strap, clasp, z: tween(k === FAV ? LIFT : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const sway = (lift / LIFT) * 4, top = HZ + lift, y = 6, lp = [];
    for (let i = 0; i <= 24; i++) {
      const t = (i / 24) * Math.PI * 2;
      lp.push(P(it.x + 5.5 * Math.sin(t) + sway * (1 - Math.cos(t)) * 0.5, y, top - 11 + 11 * Math.cos(t)));
    }
    it.loop.setAttribute("d", poly(lp));
    const z0 = top - 22, z1 = z0 - LEN[it.k], sp = [];
    for (let i = 0; i <= 10; i++) { const s = i / 10; sp.push(P(it.x + sway * (1 + s * 1.5), y, lerpZ(z0, z1, s))); }
    it.strap.setAttribute("d", open(sp));
    const cx = it.x + sway * 2.5;
    put(it.clasp, prism(P, front, disc(cx, y, 3), disc(cx, y, 2.2), z1 - 9, z1));
  }
  const lerpZ = (a, b, s) => a + (b - a) * s;

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 6, HZ - 30));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT : 0) : dd === 0 ? LIFT : dd === 1 ? 3 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      it.loop.classList.toggle("hi", on); it.strap.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "leash " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "dogleashes",
  means: "Five leashes on wall hooks: the leash under the pointer lifts off its hook, and its neighbours sway a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[123, 116], [160, 135], [272, 191], null],
  mount,
});

busstop.code:
/**
 * Bus stop: a shelter with a back panel, a roof on two posts and a bench,
 * and beside it a pole carrying a flag sign. The sign turns on its pole to
 * face the pointer, on a spring, as if looking up the road for the bus.
 * At rest it stands angled toward the kerb, bright. The slider is how far
 * it may turn from that rest.
 *
 * The pattern: one part turning to face the pointer (aim).
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, rrect, unproj, clamp, rad, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PX = 118, PY = 34, PZ = 92, SW = 40, SH = 30, REST = 30;
const disc = (x, y, r, n = 16) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: PX + c * q.u - s * q.v, v: PY + s * q.u + c * q.v, nu: c * q.nu - s * q.nv, nv: s * q.nu + c * q.nv }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-6, -6, 0], [90, -6, 0], [-6, 40, 0], [PX + SW, PY, 0], [PX, PY + SW, 0], [PX - SW, PY, PZ], [PX, PY - SW, PZ], [-6, -6, 62]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1, parent = g) => { const [o, i] = rings(x0, y0, x1, y1, r, b); return put(solid(parent), prism(P, front, o, i, z0, z1)); };

  box(-4, -4, 84, 40, 3, 1.2, 0, 2);            // pavement slab
  box(0, 0, 80, 3, 1.2, 0.5, 2, 56);             // back panel
  box(10, 6, 70, 16, 2, 1, 14, 17);              // bench seat
  box(12, 7, 15, 10, 1, 0.4, 2, 14);
  box(65, 7, 68, 10, 1, 0.4, 2, 14);
  box(1, 33, 4, 36, 1, 0.4, 2, 56);              // posts
  box(76, 33, 79, 36, 1, 0.4, 2, 56);
  box(-6, -6, 86, 40, 3, 1.4, 56, 60);           // roof

  const pole = mk("g", {}, g);
  box(PX - 8, PY - 8, PX + 8, PY + 8, 4, 1.4, 0, 2, pole);
  put(solid(pole), prism(P, front, disc(PX, PY, 2), disc(PX, PY, 1.2), 2, PZ + 4));
  const sign = solid(g);
  sign.sil.classList.add("hi");

  const ang = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const r = rad(a);
    const o = turn(rrect(3, -1.6, 3 + SW, 1.6, 1.4, 4), r), i = turn(rrect(3.7, -0.9, 2.3 + SW, 0.9, 0.7, 4), r);
    put(sign, prism(P, front, o, i, PZ - SH, PZ));
    // paint order: the sign goes in front of the pole when its middle is nearer the viewer
    if (Math.cos(r) + Math.sin(r) > 0) pole.after(sign.g); else pole.before(sign.g);
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function aim(p) {
    const [wx, wy] = unproj(C, p[0], p[1], 0);
    let d = (Math.atan2(wy - PY, wx - PX) * 180) / Math.PI;
    d = REST + clamp(((d - REST + 540) % 360) - 180, -reach * 1.6, reach * 1.6);
    ang.t = d;
    read.textContent = String(Math.round(((d % 360) + 360) % 360)).padStart(3, "0") + "°";
    B.wake();
  }
  function rest() { ang.t = REST; read.textContent = "rest"; B.wake(); }
  draw(REST); rest();
  bag.add(pointer(stage, { move: aim, leave: rest }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

