bunsenburner.code:
/**
 * Bunsen burner: a burner on a square foot, its tube rising through an air
 * collar to a flame. The pointer's side-to-side position turns the collar,
 * sliding its air hole round: more air, and the flame shrinks to a tight
 * cone; less, and it stands tall and lazy. At rest the collar is part open
 * and the flame is the bright mark. The slider is the flame's full height.
 *
 * The pattern: one continuous dial (spring).
 */
const {
  Cam, circ, clamp, fit, facing, hull, lerp, open, poly, prism, proj, rings, ringAt, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const TR = 5, TZ = 62, CR = 6.8, REST = 0.2;
const disc = (r, n = 32) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxH = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-26, -26, 0], [26, 26, 0], [26, -26, 0], [-26, 26, 0], [0, 0, TZ + 44]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-26, -26, 26, 26, 9, 2);
  put(solid(g), prism(P, front, br, bi, 0, 4));
  // the foot's boss and the gas inlet stub, nearest corner kept clear
  put(solid(g), prism(P, front, disc(9), disc(7.5), 4, 8));
  const inlet = rings(-24, -2.6, -8, 2.6, 2.6, 0.8);
  put(solid(g), prism(P, front, inlet[0], inlet[1], 7, 11.5));
  put(solid(g), prism(P, front, disc(TR), disc(TR - 1.2), 8, TZ));
  put(solid(g), prism(P, front, disc(CR), disc(CR - 1.4), 14, 24));
  const hole = mk("path", { class: "nf" }, g);
  const flame = mk("path", { class: "sil hi" }, g), cone = mk("path", { class: "nf lo" }, g);

  const a = spring(REST);
  let last = NaN, lastH = NaN;
  function draw(v) {
    if (v === last && maxH === lastH) return;
    last = v; lastH = maxH;
    // the air hole: a slot on the collar, swung round by the air setting
    const th = lerp(-2.2, 1.2, v), w = 0.28 + 0.32 * v, pts = [];
    const facingHole = Math.cos(th - Math.PI / 4) > 0.15;
    for (let i = 0; i <= 6; i++) { const t = th - w + (2 * w * i) / 6; pts.push(P(CR * Math.cos(t), CR * Math.sin(t), 16.5)); }
    for (let i = 6; i >= 0; i--) { const t = th - w + (2 * w * i) / 6; pts.push(P(CR * Math.cos(t), CR * Math.sin(t), 21.5)); }
    hole.setAttribute("d", facingHole ? poly(pts) : "");
    const h = lerp(maxH, maxH * 0.42, v), r = lerp(6.2, 4, v), ch = lerp(0.18, 0.55, v) * h;
    const f = [];
    f.push(...ringAt(P, disc(r * 0.85, 24), TZ + 0.5), ...ringAt(P, disc(r, 24), TZ + h * 0.22), ...ringAt(P, disc(r * 0.7, 24), TZ + h * 0.55));
    f.push(P(0, 0, TZ + h), P(lerp(1.6, 0.3, v), lerp(-1.6, -0.3, v), TZ + h * 0.92));
    flame.setAttribute("d", poly(hull(f)));
    const c = ringAt(P, disc(r * 0.55, 20), TZ + 0.8).concat([P(0, 0, TZ + ch)]);
    cone.setAttribute("d", poly(hull(c)));
  }

  const B = register(stage, (dt) => { const m = stepS(a, dt); draw(a.x); return m; });
  bag.add(B.unregister);
  function setAir(t) { a.t = t; read.textContent = t === REST && idle ? "rest" : "air " + Math.round(t * 100) + "%"; B.wake(); }
  let idle = true;
  draw(REST);
  read.textContent = "rest";
  bag.add(pointer(stage, {
    move: (p) => { idle = false; setAir(clamp((p[0] - 120) / 160, 0, 1)); },
    leave: () => { idle = true; setAir(REST); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxH = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "bunsenburner",
  means: "A burner whose air collar turns with the pointer: open it and the flame tightens to a short cone, close it and it stands tall.",
  rules: [3, 5, 8, 9],
  range: [24, 38, 44],
  tour: [[298, 171], [102, 171], [200, 91], null],
  mount,
});

centrifuge.code:
/**
 * Centrifuge: a squat benchtop body with a round lid hinged at the back,
 * and under it a rotor holding six tubes. The pointer over the body swings
 * the lid open to show the rotor; leaving lets it fall back ajar. At rest
 * the lid is the bright mark; open, the rotor takes it. The slider is how
 * far the lid swings.
 *
 * The pattern: one part opening (tween).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rad, rings, ringAt, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const H = 24, LR = 24, HY = -LR, AJAR = 14;
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[-32, -32, 0], [32, 32, 0], [32, -32, 0], [-32, 32, 0], [0, HY, H + 2 * LR + 4], [-24, HY - 6, H + 40]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-32, -32, 32, 32, 13, 2);
  put(solid(g), prism(P, front, br, bi, 0, H));
  mk("path", { d: poly(ringAt(P, disc(0, 0, LR - 1), H)), class: "nf lo" }, g);
  // the front panel: a recessed strip and a start button on the near face
  mk("path", { d: open([P(32, -14, 7), P(32, 14, 7)]), class: "nf lo" }, g);
  const btn = mk("ellipse", { class: "dot off" }, g);
  const bp = P(32, 20, 13); btn.setAttribute("cx", bp[0]); btn.setAttribute("cy", bp[1]); btn.setAttribute("rx", 2.2); btn.setAttribute("ry", 2.2);
  // the rotor and its six tubes, below the rim
  const rotor = mk("path", { d: poly(ringAt(P, disc(0, 0, 17), H - 2)), class: "sil" }, g);
  for (let i = 0; i < 6; i++) { const t = (i * Math.PI) / 3 + 0.3; mk("path", { d: poly(ringAt(P, disc(11 * Math.cos(t), 11 * Math.sin(t), 2.6, 14), H - 2)), class: "nf lo" }, g); }
  mk("path", { d: poly(ringAt(P, disc(0, 0, 3, 16), H - 2)), class: "nf" }, g);
  const lid = mk("path", { class: "sil" }, g), lidC = mk("path", { class: "nf lo" }, g);

  const tw = tween(AJAR);
  let last = NaN;
  const rot = (ring, z, a) => ring.map((q) => P(q.u, HY + (q.v - HY) * Math.cos(a), z + (q.v - HY) * Math.sin(a)));
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg);
    const outer = disc(0, 0, LR), inner = disc(0, 0, LR - 2.4);
    // thickness grows along the lid's own normal as it swings
    const lo = rot(outer, H, a), hiP = outer.map((q) => P(q.u, HY + (q.v - HY) * Math.cos(a) - 3 * Math.sin(a), H + (q.v - HY) * Math.sin(a) + 3 * Math.cos(a)));
    lid.setAttribute("d", poly(hull(lo.concat(hiP))));
    const ci = inner.map((q) => P(q.u, HY + (q.v - HY) * Math.cos(a) - 3 * Math.sin(a), H + (q.v - HY) * Math.sin(a) + 3 * Math.cos(a)));
    lidC.setAttribute("d", deg < 92 ? poly(ci) : "");
  }

  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  let on = null;
  function setOpen(o) {
    if (o === on) return;
    on = o;
    tset(tw, o ? maxA : AJAR, performance.now(), 0);
    lid.classList.toggle("hi", !o);
    rotor.classList.toggle("hi", o);
    btn.setAttribute("class", o ? "dot m" : "dot off");
    read.textContent = o ? "open " + maxA + "°" : "rest";
    B.wake();
  }
  setOpen(false);
  function hit([sx, sy]) { const [x, y] = unproj(C, sx, sy, H); return Math.abs(x) < 36 && Math.abs(y) < 36; }
  bag.add(pointer(stage, { move: (p) => setOpen(hit(p)), leave: () => setOpen(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; if (on) { on = null; setOpen(true); } }, destroy: bag.dispose };
}

hairline({
  name: "centrifuge",
  means: "A benchtop centrifuge: the pointer over it swings the lid open on its back hinge to show the rotor and its six tubes.",
  rules: [1, 4, 5, 8],
  range: [60, 100, 110],
  tour: [[200, 184], [200, 243], [200, 126], null],
  mount,
});

magnifier.code:
/**
 * Magnifier: a hand lens held over a specimen slide strewn with grains. The
 * lens slides to follow the pointer across the slide, clamped to its edge,
 * and the grains under the glass come up a step. At rest the lens sits off
 * centre with its rim bright. The slider is the lens's height.
 *
 * The pattern: one part following the pointer (spring).
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rings, ringAt, spring, stepS, unproj,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const W = 46, LR = 15, RX = -10, RY = 8;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let LZ = value;
  const C = Cam(45, 0.5, 2.65);
  fit(C, [[-W, -W, 0], [W, W, 0], [W, -W, 0], [-W, W, 0], [W, W, 40], [-W, -W, 32]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-W, -W * 0.62, W, W * 0.62, 6, 2);
  put(solid(g), prism(P, front, sr, si, 0, 3));
  const grains = [];
  let s = 7;
  const rnd = () => ((s = (s * 9301 + 49297) % 233280) / 233280);
  for (let i = 0; i < 34; i++) {
    const x = (rnd() * 2 - 1) * (W - 8), y = (rnd() * 2 - 1) * (W * 0.62 - 6), d = flatDot(g, C, 1.6, "dot off");
    place(d, P(x, y, 3)); grains.push({ x, y, d, on: false });
  }
  const lg = mk("g", {}, svg);
  const handle = solid(lg), lens = mk("path", { class: "sil hi nf" }, lg), inner = mk("path", { class: "nf lo" }, lg);
  const mx = spring(RX), my = spring(RY);
  let lx = NaN, ly = NaN, lz = NaN;
  function draw(x, y) {
    if (x === lx && y === ly && LZ === lz) return;
    lx = x; ly = y; lz = LZ;
    const a = ringAt(P, disc(x, y, LR), LZ), b = ringAt(P, disc(x, y, LR), LZ + 2.5);
    lens.setAttribute("d", poly(hull(a.concat(b))) + " " + poly(ringAt(P, disc(x, y, LR - 2.2), LZ + 2.5)));
    inner.setAttribute("d", poly(ringAt(P, disc(x, y, LR - 3.4), LZ + 2.5)));
    const [hr, hi] = rings(x + LR - 1, y - 2.2, x + LR + 26, y + 2.2, 2.2, 0.8);
    put(handle, prism(P, front, hr, hi, LZ, LZ + 4.5));
    for (const gr of grains) {
      const on = Math.hypot(gr.x - x, gr.y - y) < LR - 3;
      if (on !== gr.on) { gr.on = on; gr.d.setAttribute("class", on ? "dot m" : "dot off"); place(gr.d, P(gr.x, gr.y, on ? 6 : 3)); }
    }
  }
  const B = register(stage, (dt) => { const m = stepS(mx, dt) | stepS(my, dt); draw(mx.x, my.x); return !!m; });
  bag.add(B.unregister);
  function aim(x, y, rest) {
    mx.t = clamp(x, -W + 8, W - 8); my.t = clamp(y, -W * 0.62 + 6, W * 0.62 - 6);
    read.textContent = rest ? "rest" : "x" + Math.round(mx.t) + " y" + Math.round(my.t);
    B.wake();
  }
  draw(RX, RY); read.textContent = "rest";
  bag.add(pointer(stage, { move: ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, 0); aim(x, y, false); }, leave: () => aim(RX, RY, true) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { LZ = v; lz = NaN; B.wake(); draw(mx.x, my.x); }, destroy: bag.dispose };
}

