musicstands.code:
/**
 * Music stands: three stands in a row, each a round foot, a pole and a desk
 * with a ledge and a sheet on it. The pointer picks a stand by where it
 * stands and its desk tilts back toward reading, the neighbours following a
 * little, staggered from it. At rest the desks lean unevenly and the middle
 * one is bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 48, PH = 44, DW = 17, DH = 24, FAV = 1, REST = [14, 30, 20], UP = 58;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  const X1 = (N - 1) * STEP;
  fit(C, [[-DW, -DH, 0], [X1 + DW, 12, 0], [-DW, -DH, PH + DH], [X1 + DW, 12, PH + DH], [-DW, 12, 0], [X1 + DW, -DH, PH + DH]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, 0, 10), disc(x, 0, 8.4), 0, 1.6));
    put(solid(grp), prism(P, front, disc(x, 0, 1.3, 12), disc(x, 0, 0.6, 12), 1.6, PH));
    const desk = mk("path", { class: "sil" }, grp), sheet = mk("path", { class: "nf lo" }, grp), ledge = mk("path", { class: "nf" }, grp);
    items.push({ k, x, desk, sheet, ledge, a: tween(REST[k]), last: NaN });
  }

  const at = (x, a, u, s, t = 0) => {
    const ca = Math.cos(rad(a)), sa = Math.sin(rad(a));
    return P(x + u, -s * sa + t * ca, PH + s * ca + t * sa);
  };
  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    const pts = [];
    for (const u of [-DW, DW]) for (const s of [0, DH]) for (const t of [0, 1.4]) pts.push(at(it.x, a, u, s, t));
    it.desk.setAttribute("d", poly(hull(pts)));
    it.sheet.setAttribute("d", poly([at(it.x, a, -DW + 4, 4, 1.4), at(it.x, a, DW - 4, 4, 1.4), at(it.x, a, DW - 4, DH - 2, 1.4), at(it.x, a, -DW + 4, DH - 2, 1.4)]));
    it.ledge.setAttribute("d", poly(hull([at(it.x, a, -DW, 0, 1.4), at(it.x, a, DW, 0, 1.4), at(it.x, a, DW, 0, 4), at(it.x, a, -DW, 0, 4), at(it.x, a, DW, 2, 4), at(it.x, a, -DW, 2, 4)])));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 0, PH));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? REST[k] : dd === 0 ? UP : dd === 1 ? 26 : 12;
      tset(it.a, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.desk.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "desk " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "musicstands",
  means: "Three music stands in a row: the desk under the pointer tilts back toward reading, its neighbours following a little.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[133, 92], [203, 125], [273, 160], null],
  mount,
});

vintagetv.code:
/**
 * Vintage TV: a wooden cabinet set on four short legs, a rounded screen on
 * its front, a channel knob and a volume knob beside it, and a rabbit-ear
 * antenna on top. The pointer tunes it: where it is across the set picks the
 * channel, the knob turns to it, bright, and the antenna leans after the
 * pointer. At rest the screen is the bright mark and the ears stand apart,
 * leaning a little. The slider is the ears' spread.
 *
 * The pattern: one value along a row (riffle) on a fixed plane through the
 * cabinet; the lean is a spring, the knob a tween.
 */
const {
  Cam, clamp, facing, fit, lerp, hull, poly, prism, proj, rad, rings, ringAt, rrect, seg, spring, stepS, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = 0, X1 = 44, Y0 = 0, Y1 = 30, Z0 = 9, Z1 = 42, AX = 22, AY = 15, AL = 30, NCH = 12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let spread = value;
  const C = Cam(45, 0.5, 3.05);
  fit(C, [[X0, Y0, 0], [X1, Y1 + 3, 0], [X1, Y0, 0], [X0, Y1 + 3, 0], [AX - 24, AY, Z1 + 30], [AX + 24, AY, Z1 + 30]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // legs, far to near
  [[4, 4], [X1 - 4, 4], [4, Y1 - 4], [X1 - 4, Y1 - 4]].forEach(([x, y]) => {
    const [r, i] = rings(x - 2, y - 2, x + 2, y + 2, 1.6, 0.6);
    put(solid(g), prism(P, front, r, i, 0, Z0 + 1));
  });
  // the cabinet, the screen on its front face (y = Y1) and a speaker grille
  const cab = solid(g);
  const [cr, ci] = rings(X0, Y0, X1, Y1, 4, 1.4);
  put(cab, prism(P, front, cr, ci, Z0, Z1));
  const face = (pts) => poly(pts.map(([x, z]) => P(x, Y1, z)));
  const scr = [];
  for (let i = 0; i <= 40; i++) {
    const a = (i / 40) * Math.PI * 2, c = Math.cos(a), s = Math.sin(a);
    scr.push([17 + 12.5 * Math.sign(c) * Math.pow(Math.abs(c), 0.45), 26 + 12 * Math.sign(s) * Math.pow(Math.abs(s), 0.45)]);
  }
  const screen = mk("path", { class: "nf sil", d: face(scr) }, cab.g);
  mk("path", { class: "nf lo", d: face(scr.map(([x, z]) => [17 + (x - 17) * 0.86, 26 + (z - 26) * 0.86])) }, cab.g);
  let gr = "";
  for (let k = 0; k < 4; k++) gr += seg(P(33, Y1, 14 + k * 2), P(41, Y1, 14 + k * 2));
  mk("path", { class: "nf lo", d: gr }, cab.g);

  // knobs: short cylinders standing out of the face along y
  function knob(cx, cz, R) {
    const kg = mk("g", {}, g), ring = (y) => { const o = []; for (let i = 0; i < 24; i++) { const a = (i / 24) * Math.PI * 2; o.push(P(cx + R * Math.cos(a), y, cz + R * Math.sin(a))); } return o; };
    const sil = mk("path", { class: "sil", d: poly(hull(ring(Y1).concat(ring(Y1 + 3)))) }, kg);
    mk("path", { class: "nf lo", d: poly(ring(Y1 + 3)) }, kg);
    const tick = mk("path", { class: "nf" }, kg);
    return { sil, tick, set(a) { tick.setAttribute("d", seg(P(cx, Y1 + 3, cz), P(cx + R * 0.8 * Math.cos(a), Y1 + 3, cz + R * 0.8 * Math.sin(a)))); } };
  }
  const chK = knob(37, 33, 3.6), volK = knob(37, 24.5, 2.6);
  volK.set(rad(130));

  // the antenna: a small base and two rods in the x–z plane
  const base = solid(g);
  const [br, bi] = rings(AX - 4, AY - 3, AX + 4, AY + 3, 3, 1);
  put(base, prism(P, front, br, bi, Z1, Z1 + 3));
  const rods = mk("path", { class: "nf" }, g);
  const tips = [mk("circle", { r: 1.6 }, g), mk("circle", { r: 1.6 }, g)];
  const lean = spring(8), kn = tween(rad(60));
  let last = "";
  function drawAnt(l) {
    const key = l.toFixed(2) + "," + spread;
    if (key === last) return;
    last = key;
    const o = P(AX, AY, Z1 + 3);
    let d = "";
    [-1, 1].forEach((s, i) => {
      const a = rad(l + s * spread), t = P(AX + AL * Math.sin(a), AY, Z1 + 3 + AL * Math.cos(a));
      d += seg(o, t);
      tips[i].setAttribute("cx", t[0]); tips[i].setAttribute("cy", t[1]);
    });
    rods.setAttribute("d", d);
  }

  const B = register(stage, (dt, now) => {
    const m = stepS(lean, dt);
    drawAnt(lean.x);
    chK.set(tval(kn, now));
    return m || !tdone(kn, now);
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, Z1 * 0.6);
    if (x < X0 - 12 || x > X1 + 12 || y < Y0 - 12 || y > Y1 + 14) return null;
    return clamp((x - X0 + 12) / (X1 - X0 + 24), 0, 1);
  }
  let act = -2;
  function update(f) {
    const ch = f === null ? -1 : clamp(Math.round(f * (NCH - 1)), 0, NCH - 1);
    lean.t = f === null ? 8 : clamp(lerp(-38, 38, f), -38, 38);
    B.wake();
    if (ch === act) return;
    act = ch;
    tset(kn, ch < 0 ? rad(60) : rad(150 - ch * 25), performance.now(), 0);
    screen.classList.toggle("hi", ch < 0);
    chK.sil.classList.toggle("hi", ch >= 0);
    read.textContent = ch < 0 ? "rest" : "ch " + String(ch + 2).padStart(2, "0");
  }
  update(null);
  bag.add(pointer(stage, { move: (p) => update(hit(p)), leave: () => update(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { spread = v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "vintagetv",
  means: "A vintage TV: the pointer across the set turns the channel knob to a channel, and the rabbit-ear antenna leans after it.",
  rules: [1, 3, 5, 8],
  range: [12, 26, 40],
  tour: [[130, 141], [156, 153], [277, 214], null],
  mount,
});

hatboxes.code:
/**
 * Hat boxes: three round boxes of different sizes standing in a row on a
 * boutique shelf, each with a deep lid. The pointer picks a box by where it
 * stands: its lid lifts and tips open, and the lids beside it lift a crack,
 * staggered from it. At rest the middle lid sits ajar, bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, run, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BOX = [[16, 26], [21, 34], [13, 20]], GAP = 6, LH = 7, LIFT = 20, FAV = 1, SZ = 3;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  let x = 0;
  const pos = BOX.map(([r]) => { const c = x + r; x += 2 * r + GAP; return c; });
  const W = x - GAP, Y = 22;
  fit(C, [[-6, -6, 0], [W + 6, 2 * Y + 6, 0], [W + 6, -6, 0], [-6, 2 * Y + 6, 0], [pos[1], Y, SZ + 34 + LIFT + 14], [pos[0], Y, SZ + 26 + LIFT + 14]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-6, -6, W + 6, 2 * Y + 6, 5, 2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));

  const items = BOX.map(([r, h], k) => {
    const cx = pos[k], grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(cx, Y, r), disc(cx, Y, r - 1.5), SZ, SZ + h - LH + 2));
    const lid = solid(grp);
    return { k, cx, r, h, grp, lid, z: tween(k === FAV ? 0.45 : 0), last: NaN };
  });

  // the lid: a short drum, tipped about the far rim as it lifts
  function draw(it, t) {
    if (t === it.last) return;
    it.last = t;
    const base = SZ + it.h - LH + t * LIFT, tip = t * 0.5, R = it.r + 1.2;
    const at = (rr, dz) => disc(it.cx, Y, rr, 44).map((q) => ({ ...q, z: base + dz + Math.max(0, (q.u - it.cx) + (q.v - Y)) * tip * 0.5 }));
    const ringZ = (rr, dz) => at(rr, dz).map((q) => P(q.u, q.v, q.z));
    const s = hull(ringZ(R, 0).concat(ringZ(R, LH)));
    const inner = run(at(R - 1.6, LH), front).map((q) => P(q.u, q.v, q.z));
    it.lid.sil.setAttribute("d", poly(s));
    it.lid.cr.setAttribute("d", open(inner));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.cx, Y, SZ + it.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return best >= 0 && bd < 45 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? 0.45 : 0) : dd === 0 ? 1 : dd === 1 ? 0.15 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.lid.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "box " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "hatboxes",
  means: "Three round hat boxes on a shelf: the box under the pointer lifts and tips its lid open, and its neighbours lift a crack.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[136, 150], [204, 157], [262, 205], null],
  mount,
});

roomservice.code:
/**
 * Room service cart: a two-shelf trolley on casters with a push handle at
 * one end and a domed cloche on its top. The cart rolls along its length to
 * follow the pointer, and while the pointer is near, the cloche lifts off
 * its plate. At rest the cart stands a little off centre with the dome
 * ajar, bright. The slider is how far the cart may roll.
 *
 * The pattern: a whole object following the pointer on a spring.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, unproj, clamp, spring, stepS, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, seg, solid,
} = HL;

const L = 80, W = 36, TZ = 40, SZ = 12, R0 = -6, DR = 13, LIFT = 16;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = 4 + value * 0.2;
  const C = Cam(45, 0.5, 2.2);
  const MX = 22;
  fit(C, [[-12 - MX, -2, 0], [L + MX, W + 2, 0], [L + MX, -2, 0], [-12 - MX, W + 2, 0], [-12 - MX, W / 2, TZ + 14], [L + MX - 30, W / 2, TZ + 2 + DR + LIFT + 6]], 200, 172);
  const P = proj(C), front = facing(C);
  const o = P(0, 0, 0), ox = P(1, 0, 0);
  const g = mk("g", {}, svg);
  // casters, then the lower legs, then the shelf, then the upper legs
  const legs = [[4, 4], [L - 4, 4], [4, W - 4], [L - 4, W - 4]];
  for (const [x, y] of legs) put(solid(g), prism(P, front, disc(x, y, 3, 20), disc(x, y, 1.6, 20), 0, 4));
  for (const [x, y] of legs) put(solid(g), prism(P, front, disc(x, y, 1.2, 12), disc(x, y, 0.6, 12), 4, SZ));
  const [sr, si] = rings(0, 0, L, W, 4, 1.6);
  put(solid(g), prism(P, front, sr, si, SZ, SZ + 2));
  for (const [x, y] of legs) put(solid(g), prism(P, front, disc(x, y, 1.2, 12), disc(x, y, 0.6, 12), SZ + 2, TZ));
  // the push handle at the far end
  const hd = [[0, 6, TZ], [-9, 6, TZ + 12], [-9, W - 6, TZ + 12], [0, W - 6, TZ]].map((p) => P(...p));
  mk("path", { d: seg(hd[0], hd[1]) + seg(hd[1], hd[2]) + seg(hd[2], hd[3]), class: "nf lo" }, g);
  const [tr, ti] = rings(0, 0, L, W, 5, 2);
  put(solid(g), prism(P, front, tr, ti, TZ, TZ + 2.5));
  // a plate and its cloche
  const cx = L - 26, cy = W / 2, PZ = TZ + 2.5;
  put(solid(g), prism(P, front, disc(cx, cy, DR + 3), disc(cx, cy, DR), PZ, PZ + 1.4));
  const mound = [];
  for (const [r, z] of [[8, 0], [6, 2.5], [3, 4.5]]) mound.push(...ringAt(P, disc(cx, cy, r, 20), PZ + 1.4 + z));
  mk("path", { d: poly(hull(mound)), class: "nf" }, g);
  const dome = mk("path", { class: "sil hi" }, g), rim = mk("path", { class: "nf lo" }, g), knob = mk("path", { class: "nf" }, g);

  const REST = 8, AJAR = 0.3;
  const sx = spring(REST), lid = tween(AJAR);
  let lastX = NaN, lastL = NaN;
  function draw(x, l) {
    if (x !== lastX) { lastX = x; g.setAttribute("transform", `translate(${(ox[0] - o[0]) * x} ${(ox[1] - o[1]) * x})`); }
    if (l === lastL) return;
    lastL = l;
    const base = PZ + 1.6 + l * LIFT, pts = [];
    for (let i = 0; i <= 6; i++) { const t = (i / 6) * (Math.PI / 2); pts.push(...ringAt(P, disc(cx, cy, DR * Math.cos(t), 28), base + DR * 0.85 * Math.sin(t))); }
    dome.setAttribute("d", poly(hull(pts)));
    rim.setAttribute("d", poly(ringAt(P, disc(cx, cy, DR, 40), base + 1.2)));
    const top = base + DR * 0.85;
    knob.setAttribute("d", poly(hull(ringAt(P, disc(cx, cy, 2.2, 16), top).concat(ringAt(P, disc(cx, cy, 2.2, 16), top + 3)))));
  }

  const B = register(stage, (dt, now) => {
    const m = stepS(sx, dt);
    draw(sx.x, tval(lid, now));
    return m || !tdone(lid, now);
  });
  bag.add(B.unregister);

  function show(x, on) {
    read.textContent = on ? "roll " + (x >= 0 ? "+" : "") + Math.round(x) : "rest";
  }
  function move([px, py]) {
    const [wx] = unproj(C, px, py, TZ / 2);
    const x = clamp(wx - L / 2, -reach, reach);
    sx.t = x;
    tset(lid, 1, performance.now(), 0);
    show(x, true);
    B.wake();
  }
  function leave() {
    sx.t = REST;
    tset(lid, AJAR, performance.now(), 0);
    show(0, false);
    B.wake();
  }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = 4 + v * 0.2; }, destroy: bag.dispose };
}

hairline({
  name: "roomservice",
  means: "A room service cart rolls along its length to follow the pointer, and the cloche on its top lifts while the pointer is near.",
  rules: [1, 3, 5, 8],
  range: [0, 45, 90],
  tour: [[170, 165], [256, 167], [296, 215], null],
  mount,
});

skylights.code:
/**
 * Skylights: a gabled house with three roof windows on the near slope. The
 * pointer picks a skylight by where it stands: its sash swings open on the
 * hinge at its top edge, and the sashes beside it open a crack, staggered
 * from it. At rest the middle one stands ajar, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, fillet, hull, open, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 120, D = 60, H = 30, R = 28, OV = 5, N = 3, SW = 27, S0 = 5, S1 = 33, OPEN = 58, FAV = 1;
const HALF = D / 2, SL = Math.hypot(HALF, R);
const dv = [0, HALF / SL, -R / SL], nv = [0, R / SL, HALF / SL];
const zAt = (y) => H + R * (1 - Math.abs(y - HALF) / HALF);
const onSlope = (x, s, h = 0) => [x, HALF + dv[1] * s + nv[1] * h, H + R + dv[2] * s + nv[2] * h];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-OV, -OV, 0], [W + OV, D + OV, 0], [W + OV, -OV, 0], [-OV, D + OV, 0], [0, HALF, H + R], [W, HALF, H + R + 12]], 200, 170);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, D, 2, 1.5);
  put(solid(g), prism(P, () => true, br, bi, 0, H));
  // the roof: a gable, with a second line for its thickness at the eaves
  const zE = zAt(D + OV), xs = [-OV, W + OV];
  const top = [], low = [];
  for (const x of xs) {
    top.push(P(x, -OV, zE), P(x, HALF, H + R), P(x, D + OV, zE));
    low.push(P(x, -OV, zE - 2.5), P(x, D + OV, zE - 2.5));
  }
  const roof = solid(g);
  put(roof, {
    sil: poly(fillet(hull(top.concat(low)), hull(top.concat(low)).map(() => 1.5))),
    crease: open([P(-OV, HALF, H + R), P(W + OV, HALF, H + R)]) + seg(P(-OV, D + OV, zE), P(W + OV, D + OV, zE)) + seg(P(W + OV, -OV, zE), P(W + OV, HALF, H + R)) + seg(P(W + OV, HALF, H + R), P(W + OV, D + OV, zE)),
  });

  const items = [];
  for (let k = 0; k < N; k++) {
    const cx = W / 2 + (k - 1) * 38, x0 = cx - SW / 2, x1 = cx + SW / 2, grp = mk("g", {}, g);
    const fr = [onSlope(x0 - 2, S0 - 2, 0.4), onSlope(x1 + 2, S0 - 2, 0.4), onSlope(x1 + 2, S1 + 2, 0.4), onSlope(x0 - 2, S1 + 2, 0.4)].map((p) => P(...p));
    mk("path", { d: poly(fillet(fr, [2, 2, 2, 2])), class: "lo" }, grp);
    const well = [onSlope(x0, S0, 0.5), onSlope(x1, S0, 0.5), onSlope(x1, S1, 0.5), onSlope(x0, S1, 0.5)].map((p) => P(...p));
    mk("path", { d: poly(fillet(well, [1, 1, 1, 1])), class: "nf lo" }, grp);
    const sash = mk("path", { class: "sil" }, grp), edge = mk("path", { class: "nf lo" }, grp);
    items.push({ k, cx, x0, x1, sash, edge, a: tween(k === FAV ? 22 : 0), last: NaN });
  }

  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    const c = Math.cos(a * Math.PI / 180), s = Math.sin(a * Math.PI / 180), L = S1 - S0;
    const pt = (x, t, h) => { const b = onSlope(x, S0, 1.2); return [x, b[1] + (dv[1] * c + nv[1] * s) * t + (nv[1] * c - dv[1] * s) * h, b[2] + (dv[2] * c + nv[2] * s) * t + (nv[2] * c - dv[2] * s) * h]; };
    const pts = [];
    for (const x of [it.x0 - 1, it.x1 + 1]) for (const t of [-1, L + 1]) for (const h of [0, 2]) pts.push(P(...pt(x, t, h)));
    const hl = hull(pts);
    it.sash.setAttribute("d", poly(fillet(hl, hl.map(() => 1.5))));
    it.edge.setAttribute("d", poly(fillet([pt(it.x0 + 2, 2, 2), pt(it.x1 - 2, 2, 2), pt(it.x1 - 2, L - 2, 2), pt(it.x0 + 2, L - 2, 2)].map((p) => P(...p)), [1, 1, 1, 1])));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(...onSlope(it.cx, (S0 + S1) / 2, 6)));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 && Math.abs(mids[best][1] - sy) < 55 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), ang = a < 0 ? (k === FAV ? 22 : 0) : dd === 0 ? OPEN : dd === 1 ? 30 : 0;
      tset(it.a, ang, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.sash.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "sky " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "skylights",
  means: "Three roof windows on a gabled house: the sash under the pointer swings open on its top hinge, its neighbours open a crack.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[133, 112], [180, 136], [227, 159], null],
  mount,
});

forsalesigns.code:
/**
 * Property signs: three yard signs in a row, each an L-shaped post with a
 * panel hanging from its arm. The pointer picks a sign by where it stands:
 * its panel swings out on the arm, and the panels beside it sway a little,
 * staggered from it. At rest the middle panel hangs swung, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, fillet, hull, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 46, ARM = 34, ZA = 58, PL = 24, BZ = 3, FAV = 1, SWING = 55;
const REST = [-8, 24, 6];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  const X1 = (N - 1) * STEP + ARM + 4;
  fit(C, [[-10, -14, 0], [X1 + 6, 14, 0], [X1 + 6, -14, 0], [-10, 14, 0], [0, 0, ZA + 6], [X1, PL, ZA - 4]], 200, 168);
  const P = proj(C), front = () => true;
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-10, -14, X1 + 6, 14, 6, 2);
  put(solid(g), prism(P, front, sr, si, 0, BZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, grp = mk("g", {}, g);
    const [pr, pi] = rings(x - 2, -2, x + 2, 2, 1.6, 0.7);
    put(solid(grp), prism(P, front, pr, pi, BZ, ZA + 5));
    const [ar, ai] = rings(x - 2, -1.5, x + ARM, 1.5, 1.4, 0.6);
    put(solid(grp), prism(P, front, ar, ai, ZA, ZA + 3));
    // two short hangers from the arm to the panel
    const hang = mk("path", { class: "nf lo" }, grp);
    const panel = mk("path", { class: "sil" }, grp), face = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, x0: x + 4, x1: x + ARM - 2, hang, panel, face, a: tween(REST[k]), last: NaN });
  }

  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    const c = Math.cos(a * Math.PI / 180), s = Math.sin(a * Math.PI / 180), Z0 = ZA - 3;
    const pt = (x, t, h) => [x, t * s + h * c, Z0 - t * c + h * s];
    const pts = [];
    for (const x of [it.x0, it.x1]) for (const t of [0, PL]) for (const h of [-0.9, 0.9]) pts.push(P(...pt(x, t, h)));
    const hl = hull(pts);
    it.panel.setAttribute("d", poly(fillet(hl, hl.map(() => 1.4))));
    it.face.setAttribute("d", poly(fillet([pt(it.x0 + 3, 3, 0.9), pt(it.x1 - 3, 3, 0.9), pt(it.x1 - 3, PL - 3, 0.9), pt(it.x0 + 3, PL - 3, 0.9)].map((p) => P(...p)), [1, 1, 1, 1])));
    let d = "";
    for (const x of [it.x0 + 3, it.x1 - 3]) { const a0 = P(x, 0, ZA), a1 = P(...pt(x, 0, 0)); d += "M" + a0.join(",") + "L" + a1.join(","); }
    it.hang.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P((it.x0 + it.x1) / 2, 0, ZA - PL / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), ang = a < 0 ? REST[k] : dd === 0 ? SWING : dd === 1 ? 18 : 0;
      tset(it.a, ang, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.panel.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "lot " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "forsalesigns",
  means: "Three yard signs on L-posts: the panel under the pointer swings out on its arm, and the panels beside it sway a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[141, 107], [203, 138], [264, 169], null],
  mount,
});

lanterns.code:
/**
 * Lanterns: four camping lanterns of different heights standing on a plank,
 * each a base, a glass with its flame, a peaked cap and a wire bail. The
 * pointer picks a lantern by where it stands: it is lifted by its bail, and
 * the lanterns beside it rise a little, staggered from it. At rest one
 * lantern hangs raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 30, R = 10, LIFT = 22, FAV = 2, CZ = 4, HS = [1, 0.84, 1.12, 0.92];
const X1 = (N - 1) * STEP + 2 * R;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-8, -8, 0], [X1 + 8, 2 * R + 8, 0], [X1 + 8, -8, 0], [-8, 2 * R + 8, 0], [R, R, CZ + 38 + LIFT], [X1 - R, R, CZ + 38 + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-8, -8, X1 + 8, 2 * R + 8, 6, 2);
  put(solid(g), prism(P, front, pr, pi, 0, CZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = R + k * STEP, y = R, grp = mk("g", {}, g);
    const body = mk("path", { class: "sil" }, grp), lines = mk("path", { class: "nf lo" }, grp), bail = mk("path", { class: "nf" }, grp);
    items.push({ k, x, y, h: HS[k], body, lines, bail, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }
  const restZ = (k) => (k === FAV ? LIFT * 0.7 : 0);

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const { x, y, h } = it, b = CZ + lift, gt = b + 3 + 15 * h, ct = gt + 6 * h;
    const base = disc(x, y, 9), glass = disc(x, y, 7), brim = disc(x, y, 9.5), cap = disc(x, y, 3, 16);
    it.body.setAttribute("d", poly(hull([].concat(ringAt(P, base, b), ringAt(P, base, b + 3), ringAt(P, glass, gt), ringAt(P, brim, gt), ringAt(P, cap, ct)))));
    const fl = disc(x, y, 1.6, 12), fz = b + 3 + 6 * h;
    let d = open(ringAt(P, run(base, front), b + 3)) + " " + open(ringAt(P, run(brim, front), gt));
    for (const a of [-0.55, 0.55]) {
      const u = x + 7 * Math.cos(Math.PI / 4 + a), v = y + 7 * Math.sin(Math.PI / 4 + a);
      d += " " + open([P(u, v, b + 3), P(u, v, gt)]);
    }
    d += " " + poly(hull(ringAt(P, fl, fz).concat(ringAt(P, disc(x, y, 0.4, 6), fz + 5 * h))));
    it.lines.setAttribute("d", d);
    const arc = [];
    for (let i = 0; i <= 16; i++) { const t = Math.PI * (i / 16); arc.push(P(x - 7 * Math.cos(t), y, ct - 3 + 10 * Math.sin(t))); }
    it.bail.setAttribute("d", open(arc));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, CZ + 12));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? restZ(k) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "lamp " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "lanterns",
  means: "Four camping lanterns on a plank: the one under the pointer is lifted by its bail, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[133, 150], [223, 192], [267, 214], null],
  mount,
});

picnictable.code:
/**
 * Picnic table: a slatted top on two A-frame legs, a basket with its handle
 * on the top, and a bench along each side on short posts. The pointer picks
 * a bench by which side of the table it stands on: that bench slides out
 * from the table, and the other tucks back in. At rest the near bench sits
 * pulled a little out, bright. The slider is how far a bench slides.
 *
 * The pattern: one of two, picked on a fixed plane (terrain).
 */
const {
  Cam, clamp, fit, facing, hull, open, poly, prism, proj, rings, ringAt, rrect, run, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 84, W = 36, TZ = 27, SZ = 16, FAV = 1;
const box = (x0, y0, x1, y1, r = 1) => rrect(x0, y0, x1, y1, r, 4);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[0, -30, 0], [L, -30, 0], [0, W + 30, 0], [L, W + 30, 0], [0, -10, TZ + 3], [L, W, TZ + 3], [L / 2, W / 2, TZ + 22]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const slab = (parent, x0, y0, x1, y1, z0, z1, b = 1) => { const [r, i] = rings(x0, y0, x1, y1, 1.6, b); const s = solid(parent); put(s, prism(P, front, r, i, z0, z1)); return s; };
  const bar = (parent, x, ya, za, yb, zb) => {
    const s = solid(parent), a = box(x - 2, ya - 2, x + 2, ya + 2), b = box(x - 2, yb - 2, x + 2, yb + 2);
    s.sil.setAttribute("d", poly(hull(ringAt(P, a, za).concat(ringAt(P, b, zb)))));
  };

  // benches: far (side 0) and near (side 1), each a group that slides along y
  const benches = [];
  function bench(side) {
    const grp = mk("g", {}, g), y0 = side ? W + 8 : -16;
    for (const x of [10, L - 10]) slab(grp, x - 2, y0 + 2, x + 2, y0 + 6, 0, SZ - 2, 0.6);
    const seat = slab(grp, 2, y0, L - 2, y0 + 8, SZ - 2, SZ, 1.2);
    benches[side] = { grp, seat: seat.sil, y0, s: side ? 1 : -1, t: tween(side === FAV ? 0.4 : 0), last: NaN };
  }
  bench(0);
  for (const x of [8, L - 8]) { bar(g, x, -2, 0, 12, TZ); bar(g, x, W + 2, 0, W - 12, TZ); }
  slab(g, 0, 0, L, W, TZ - 3, TZ, 1.4);
  const seams = mk("path", { class: "nf lo" }, g);
  seams.setAttribute("d", [9, 18, 27].map((y) => open([P(1.5, y, TZ), P(L - 1.5, y, TZ)])).join(" "));
  // the basket and its handle
  const bk = mk("g", {}, g), [br, bi] = rings(30, 11, 52, 25, 3, 1.2);
  put(solid(bk), prism(P, front, br, bi, TZ, TZ + 9));
  const lid = mk("path", { class: "nf lo" }, bk);
  lid.setAttribute("d", open(ringAt(P, run(br, front), TZ + 6)));
  const arc = [];
  for (let i = 0; i <= 16; i++) { const t = Math.PI * (i / 16); arc.push(P(41 - 9 * Math.cos(t), 18, TZ + 9 + 9 * Math.sin(t))); }
  mk("path", { class: "nf", d: open(arc) }, bk);
  bench(1);

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of benches) {
      const v = tval(b.t, now);
      if (v !== b.last) { b.last = v; const [ox, oy] = P(0, b.s * v * reach, 0), [cx, cy] = P(0, 0, 0); b.grp.setAttribute("transform", `translate(${(ox - cx).toFixed(2)} ${(oy - cy).toFixed(2)})`); }
      if (!tdone(b.t, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [u, v] = unproj(C, sx, sy, SZ);
    if (u < -12 || u > L + 12 || v < -34 || v > W + 34) return -1;
    return v < W / 2 ? 0 : 1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    const now = performance.now();
    benches.forEach((b, k) => {
      tset(b.t, a < 0 ? (k === FAV ? 0.4 : 0) : k === a ? 1 : 0, now, 0);
      b.seat.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : a ? "near" : "far";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = clamp(v, 0, 16); for (const b of benches) b.last = NaN; B.wake(); }, destroy: bag.dispose };
}

