  rules: [1, 3, 5, 6],
  range: [4, 10, 16],
  tour: [[250, 131], [144, 184], [110, 200], null],
  mount,
});

columns.code:
/**
 * Columns: a portico of five columns on a stepped plinth, each with a square
 * base and a square capital. The pointer picks a column by where it stands:
 * it rises out of the row as if set into place, and its neighbours rise a
 * little, staggered from it. At rest the middle column stands raised, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 30, R = 6.5, H = 62, LIFT = 18, FAV = 2, PZ = 8;
const X1 = (N - 1) * STEP + 24;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-8, -8, 0], [X1 + 8, 32, 0], [X1 + 8, -8, 0], [-8, 32, 0], [12, 12, PZ + H + LIFT + 6], [X1 - 12, 12, PZ + H + LIFT + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [a0, a1] = rings(-8, -8, X1 + 8, 32, 4, 2);
  put(solid(g), prism(P, front, a0, a1, 0, 4));
  const [b0, b1] = rings(-3, -3, X1 + 3, 27, 3, 1.6);
  put(solid(g), prism(P, front, b0, b1, 4, PZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 12 + k * STEP, y = 12, grp = mk("g", {}, g);
    const base = solid(grp), shaft = solid(grp), cap = solid(grp);
    items.push({ k, x, y, base, shaft, cap, z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = PZ + lift, { x, y } = it;
    const [r0, r1] = rings(x - 10, y - 10, x + 10, y + 10, 2, 1);
    put(it.base, prism(P, front, r0, r1, z0, z0 + 4));
    put(it.shaft, prism(P, front, disc(x, y, R), disc(x, y, R - 1.2), z0 + 4, z0 + H - 4));
    const [c0, c1] = rings(x - 11, y - 11, x + 11, y + 11, 2, 1);
    put(it.cap, prism(P, front, c0, c1, z0 + H - 4, z0 + H));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, PZ + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      for (const s of [it.base, it.shaft, it.cap]) s.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "col " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "columns",
  means: "A portico of five columns on a plinth: the column under the pointer rises out of the row, its neighbours a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[163, 191], [237, 228], [126, 173], null],
  mount,
});

cuttingboard.code:
/**
 * Cutting board: a thick board with a carrot lying along it, cut into
 * rounds, and a chef's knife held over it. The pointer stands on the board:
 * the knife slides along the carrot to it, on a spring, and drops onto the
 * carrot when the pointer is over it. At rest the knife hangs at the cut,
 * bright. The slider is how far the knife lifts.
 *
 * The pattern: a part following the pointer (spring).
 */
const {
  Cam, clamp, fit, facing, poly, prism, proj, rings, rrect, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BT = 5, CT = BT + 7, REST_X = 52;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let hover = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[0, -14, 0], [80, 44, 0], [80, -14, 0], [0, 44, 0], [40, -14, CT + 30], [40, 20, CT + 30]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [o, i] = rings(0, 0, 80, 44, 6, 2);
  put(solid(g), prism(P, front, o, i, 0, BT));
  mk("path", { d: poly(rrect(70, 18, 75, 26, 2.5, 3).map((q) => P(q.u, q.v, BT))), class: "nf lo" }, g); // hang hole
  // the carrot: rounds on the left, the uncut length on the right
  for (let k = 0; k < 4; k++) {
    const x = 10 + k * 8, [a, b] = rings(x, 16, x + 6, 28, 3, 1);
    put(solid(g), prism(P, front, a, b, BT, CT - k * 0.4));
  }
  const [co, ci] = rings(44, 16, 72, 28, 6, 1.2);
  put(solid(g), prism(P, front, co, ci, BT, CT));

  const handle = solid(g), knife = solid(g);
  knife.sil.classList.add("hi");
  const sx = spring(REST_X), sz = spring(CT + hover);
  let lx = NaN, lz = NaN;
  function draw(x, z) {
    if (x === lx && z === lz) return;
    lx = x; lz = z;
    const [ko, ki] = rings(x - 0.8, 4, x + 0.8, 38, 0.6, 0.3);
    const blade = prism(P, front, ko, ki, z, z + 12);
    put(knife, blade);
    const [ho, hi] = rings(x - 1.6, -14, x + 1.6, 4, 1.4, 0.6);
    put(handle, prism(P, front, ho, hi, z + 7, z + 12));
  }

  const B = register(stage, (dt) => { const m = stepS(sx, dt) | stepS(sz, dt); draw(sx.x, sz.x); return !!m; });
  bag.add(B.unregister);

  function aim(p) {
    const [u, v] = unproj(C, p[0], p[1], 0);
    if (u < -6 || u > 86 || v < -16 || v > 50) return leave();
    sx.t = clamp(u, 8, 74);
    const over = v > 10 && v < 34;
    sz.t = CT + (over ? 0.5 : hover);
    read.textContent = (over ? "cut " : "x ") + Math.round(sx.t);
    B.wake();
  }
  function leave() { sx.t = REST_X; sz.t = CT + hover; read.textContent = "rest"; B.wake(); }
  draw(REST_X, CT + hover);
  read.textContent = "rest";
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { hover = v; if (sz.t > CT + 1) sz.t = CT + v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "cuttingboard",
  means: "A cutting board with a carrot: the knife slides along to the pointer and drops onto the carrot to cut.",
  rules: [1, 3, 5, 8],
  range: [4, 9, 16],
  tour: [[132, 178], [169, 196], [242, 233], null],
  mount,
});

noodlebowls.code:
/**
 * Noodle bowls: three bowls on a low tray, each with a pair of chopsticks
 * laid across its rim and a mound of noodles inside. The pointer picks a
 * bowl by where it stands: its chopsticks lift and tilt, pinching, and pull
 * two strands of noodle up with them; the bowls beside it stir a little,
 * staggered from it. At rest the middle pair is half raised, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 50, RT = 20, RF = 10, H = 13, LIFT = 20, FAV = 1, CZ = 3;
const X0 = RT + 4, X1 = X0 + (N - 1) * STEP + RT + 4, Y1 = 2 * RT + 8;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  const T = CZ + H;
  fit(C, [[0, 0, 0], [X1, Y1, 0], [X1, 0, 0], [0, Y1, 0], [X0, RT + 4 - 26, T + LIFT + 3], [X1 - RT - 4, RT + 4 + 26, T]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(0, 0, X1, Y1, 7, 2);
  put(solid(g), prism(P, front, tr, ti, 0, CZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP, y = RT + 4, grp = mk("g", {}, g);
    // the bowl: a foot ring smaller than its rim, hulled
    const foot = ringAt(P, disc(x, y, RF, 32), CZ), top = ringAt(P, disc(x, y, RT, 48), T);
    mk("path", { d: poly(hull(foot.concat(top))), class: "sil" }, grp);
    mk("path", { d: poly(ringAt(P, disc(x, y, RT - 1.6, 48), T)), class: "nf lo" }, grp);
    // the broth line: the back of the inner wall, seen over the front rim
    mk("path", { d: open(ringAt(P, run(disc(x, y, RT - 3, 48), (q) => !front(q)), T - 3)), class: "nf lo" }, grp);
    // the noodles: a low mound rising just over the rim
    const mound = [];
    for (const [r, z] of [[12, -3], [10, 0], [7, 2], [3, 3]]) mound.push(...ringAt(P, disc(x + 1, y + 1, r, 24), T + z));
    mk("path", { d: poly(hull(mound)), class: "nf" }, grp);
    const strands = mk("path", { class: "nf lo" }, grp);
    const sticks = [mk("path", { class: "sil" }, grp), mk("path", { class: "sil" }, grp)];
    items.push({ k, x, y, sticks, strands, z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN });
  }

  // a rod lying from a to b: the hull of two small rounds, thinner at the tip
  const rod = (a, b) => poly(hull(ringAt(P, disc(a[0], a[1], 1.4, 10), a[2]).concat(ringAt(P, disc(b[0], b[1], 0.9, 10), b[2]))));

  function draw(it, L) {
    if (L === it.last) return;
    it.last = L;
    const { x, y } = it, f = L / LIFT, base = T + 1.6;
    const tipZ = base + L * 0.45, backZ = base + L * 1.05;
    const tips = [];
    [-1, 1].forEach((s, i) => {
      const tip = [x + s * (3.2 - 2 * f), y + 24, tipZ], back = [x + s * 3.4, y - 27, backZ];
      it.sticks[i].setAttribute("d", rod(back, tip));
      tips.push(tip);
    });
    if (L < 1.5) { it.strands.setAttribute("d", ""); return; }
    // strands hang from the tips, inside the bowl, back down to the mound
    const d = [];
    for (const [dx, w] of [[-1, 1.2], [1.2, -1]]) {
      const pts = [];
      for (let i = 0; i <= 6; i++) {
        const t = i / 6, wz = lerpN(tipZ - 1, T + 2, t);
        pts.push(P(x + dx + w * Math.sin(t * 6), lerpN(y + 18, y + 6, t), wz));
      }
      d.push(open(pts));
    }
    it.strands.setAttribute("d", d.join(" "));
  }
  const lerpN = (a, b, t) => a + (b - a) * t;

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, T));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 3 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      for (const s of it.sticks) s.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bowl " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "noodlebowls",
  means: "Three noodle bowls on a tray: the chopsticks over the bowl under the pointer lift and pinch, pulling noodles up.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[133, 140], [267, 200], [200, 150], null],
  mount,
});

milkshakes.code:
/**
 * Milkshakes: three tulip glasses on a diner counter, each topped with a
 * dome of cream, a cherry and a leaning straw. The pointer picks a glass by
 * where it stands at rest: that glass slides forward across the counter,
 * served, and the glasses beside it nudge a little, staggered from it. At
 * rest the middle glass is half served, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 44, Y0 = 16, SLIDE = 22, FAV = 1, CZ = 3;
const RB = 6, RT = 12, ZB = 10, ZT = 34, X1 = 2 * 16 + (N - 1) * STEP, Y1 = Y0 + SLIDE + 16;
const LEAN = [[-5, -2], [4, -3], [-2, -4]];
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [X1, 0, 0], [0, Y1, 0], [16, Y0, CZ + ZT + 26], [X1 - 16, Y0 + SLIDE, CZ + ZT + 20]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(0, 0, X1, Y1, 7, 2);
  put(solid(g), prism(P, front, cr, ci, 0, CZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g), el = {};
    el.foot = solid(grp);
    el.stem = solid(grp);
    el.straw = mk("path", { class: "sil" }, grp);
    el.bowl = mk("path", { class: "sil" }, grp);
    el.rim = mk("path", { class: "nf lo" }, grp);
    el.band = mk("path", { class: "nf lo" }, grp);
    el.cream = mk("path", { class: "sil" }, grp);
    el.swirl = mk("path", { class: "nf lo" }, grp);
    el.cherry = mk("path", { class: "sil" }, grp);
    items.push({ k, x: 16 + k * STEP, el, s: tween(k === FAV ? SLIDE * 0.55 : k === 2 ? 3 : 0), last: NaN });
  }

  function draw(it, s) {
    if (s === it.last) return;
    it.last = s;
    const { x, el, k } = it, y = Y0 + s, z0 = CZ;
    put(el.foot, prism(P, front, disc(x, y, 8), disc(x, y, 6.6), z0, z0 + 1.6));
    put(el.stem, prism(P, front, disc(x, y, 2.2, 16), disc(x, y, 1.4, 16), z0 + 1.6, z0 + ZB));
    // the bowl: narrow at the stem, flared at the rim
    el.bowl.setAttribute("d", poly(hull(ringAt(P, disc(x, y, RB), z0 + ZB).concat(ringAt(P, disc(x, y, RT, 44), z0 + ZT)))));
    el.rim.setAttribute("d", open(ringAt(P, run(disc(x, y, RT - 1.4, 44), front), z0 + ZT - 0.6)));
    el.band.setAttribute("d", open(ringAt(P, run(disc(x, y, RB + (RT - RB) * 0.35, 36), front), z0 + ZB + (ZT - ZB) * 0.35)));
    // the straw leans out of the cream, its foot hidden behind the dome
    const [lx, ly] = LEAN[k], b = [x + 1, y - 3, z0 + ZT], t = [x + 1 + lx, y - 3 + ly, z0 + ZT + 22];
    el.straw.setAttribute("d", poly(hull(ringAt(P, disc(b[0], b[1], 1.5, 12), b[2]).concat(ringAt(P, disc(t[0], t[1], 1.5, 12), t[2])))));
    const dome = [];
    for (let i = 0; i <= 6; i++) { const a = (i / 6) * (Math.PI / 2); dome.push(...ringAt(P, disc(x, y, (RT + 0.6) * Math.cos(a), 36), z0 + ZT + 9 * Math.sin(a))); }
    el.cream.setAttribute("d", poly(hull(dome)));
    el.swirl.setAttribute("d", open(ringAt(P, run(disc(x, y, RT * 0.72, 36), front), z0 + ZT + 6.3)));
    const cz = z0 + ZT + 9;
    el.cherry.setAttribute("d", poly(hull(ringAt(P, disc(x, y, 1.6, 12), cz).concat(ringAt(P, disc(x, y, 2.6, 16), cz + 2.2), ringAt(P, disc(x, y, 1.6, 12), cz + 4.4)))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.s, now)); if (!tdone(it.s, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, Y0, CZ + ZT / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 36 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), s = a < 0 ? (k === FAV ? SLIDE * 0.55 : k === 2 ? 3 : 0) : dd === 0 ? SLIDE : dd === 1 ? 4 : 0;
      tset(it.s, s, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.el.bowl.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "glass " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "milkshakes",
  means: "Three milkshakes on a diner counter: the glass under the pointer slides forward, served, and its neighbours nudge.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[154, 140], [276, 160], [215, 150], null],
  mount,
