slide.code:
/**
 * Slide: a playground slide on a low pad, a ladder up the back to a small
 * platform and a curved chute running down to the ground. A ball rides the
 * chute: the pointer runs along the chute and the ball follows it there, on
 * a spring. At rest the ball waits near the top, bright. The slider moves
 * where it waits.
 *
 * The pattern: one value along a path (where).
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rings, seg, spring, stepS, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = 20, LEN = 84, TOP = 50, LOW = 5, W0 = 2, W1 = 22, WALL = 5, R = 7.5, PZ = 46;
const zAt = (s) => LOW + (TOP - LOW) * (Math.cos(Math.PI * s) + 1) / 2;
const xAt = (s) => X0 + LEN * s;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let restS = clamp(value / 100, 0, 0.3);
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-16, -8, 0], [112, 32, 0], [112, -8, 0], [-16, 32, 0], [0, 0, TOP + 4], [20, 24, TOP + 4]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-16, -8, 112, 32, 8, 2);
  put(solid(g), prism(P, front, br, bi, 0, 2));

  // ladder up the back
  let lad = "";
  for (const y of [W0, W1]) lad += seg(P(-12, y, 2), P(0, y, PZ));
  mk("path", { d: lad, class: "nf" }, g);
  let rungs = "";
  for (let i = 1; i <= 5; i++) { const t = i / 6; rungs += seg(P(-12 + 12 * t, W0, 2 + (PZ - 2) * t), P(-12 + 12 * t, W1, 2 + (PZ - 2) * t)); }
  mk("path", { d: rungs, class: "nf lo" }, g);
  // posts under the platform and the chute's foot
  let posts = "";
  for (const y of [W0, W1]) { posts += seg(P(X0, y, 2), P(X0, y, PZ)) + seg(P(0, y, 2), P(0, y, PZ)) + seg(P(X0 + LEN - 6, y, 2), P(X0 + LEN - 6, y, zAt(0.93))); }
  mk("path", { d: posts, class: "nf lo" }, g);
  const [pr, pi] = rings(0, 0, X0, 24, 2, 1.2);
  put(solid(g), prism(P, front, pr, pi, PZ, PZ + 4));

  // chute: far wall, bed, ball, near wall
  const N = 40, ss = [...Array(N + 1)].map((_, i) => i / N);
  const edge = (y, dz) => ss.map((s) => P(xAt(s), y, zAt(s) + dz));
  const wall = (y) => poly(edge(y, 0).concat(edge(y, WALL).reverse()));
  mk("path", { d: wall(W0), class: "sil" }, g);
  mk("path", { d: poly(edge(W0, 0).concat(edge(W1, 0).reverse())) }, g);
  mk("path", { d: open(edge((W0 + W1) / 2, 0)), class: "nf lo" }, g);
  const ball = mk("path", { class: "sil hi" }, g);
  mk("path", { d: wall(W1), class: "sil" }, g);
  mk("path", { d: open(edge(W1, WALL - 1.2)), class: "nf lo" }, g);

  const sp = spring(restS);
  let last = NaN;
  function draw(s) {
    if (s === last) return;
    last = s;
    const c = P(xAt(s), (W0 + W1) / 2, zAt(s) + R), e = P(xAt(s), (W0 + W1) / 2, zAt(s) + 2 * R);
    const rr = Math.hypot(e[0] - c[0], e[1] - c[1]) / 0.866, pts = [];
    for (let a = 0; a < 32; a++) { const t = (a / 32) * Math.PI * 2; pts.push([c[0] + rr * Math.cos(t), c[1] + rr * Math.sin(t)]); }
    ball.setAttribute("d", poly(pts));
  }
  draw(restS);

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  const track = ss.map((s) => [s, P(xAt(s), (W0 + W1) / 2, zAt(s))]);
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    for (const [s, q] of track) { const d = Math.hypot(q[0] - sx, q[1] - sy); if (d < bd) { bd = d; best = s; } }
    return bd < 34 ? best : -1;
  }
  function setS(s) {
    sp.t = s < 0 ? restS : s;
    read.textContent = s < 0 ? "rest" : "drop " + Math.round(s * 100);
    B.wake();
  }
  setS(-1);
  bag.add(pointer(stage, { move: (p) => setS(hit(p)), leave: () => setS(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { restS = clamp(v / 100, 0, 0.3); if (read.textContent === "rest") setS(-1); }, destroy: bag.dispose };
}

hairline({
  name: "slide",
  means: "A playground slide with a ladder and a curved chute: the ball rides the chute to where the pointer runs along it.",
  rules: [1, 3, 5, 6],
  range: [0, 10, 30],
  tour: [[178, 113], [220, 166], [262, 228], null],
  mount,
});

teddybears.code:
/**
 * Teddy bears: five soft bears of mixed sizes sitting along a wall shelf,
 * each a round body, legs out front, a head with two ears and a muzzle. The
 * pointer picks a bear by where it stands: that bear hops up off the shelf,
 * and the bears beside it bob a little, staggered from it. At rest one bear
 * sits up, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 27, SZ = [0.9, 1.1, 0.8, 1.0, 0.85], LIFT = 16, FAV = 1, SZ0 = 4;
const X1 = (N - 1) * STEP + 24;
const D = Math.SQRT1_2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-4, -10, 0], [X1 + 4, 28, 0], [X1 + 4, -10, 58], [-4, -10, 58], [12, 12, SZ0 + 40 + LIFT]], 200, 166);
  const P = proj(C), front = facing(C);
  const unit = (() => { const a = P(0, 0, 0), b = P(0, 0, 1); return Math.hypot(b[0] - a[0], b[1] - a[1]) / 0.866; })();
  const g = mk("g", {}, svg);
  const [wr, wi] = rings(-4, -10, X1 + 4, -6, 1.5, 1);
  put(solid(g), prism(P, front, wr, wi, 0, 58));
  const [sr, si] = rings(-4, -6, X1 + 4, 28, 3, 1.6);
  put(solid(g), prism(P, front, sr, si, 0, SZ0));

  const circle = (q, R) => {
    const c = P(q[0], q[1], q[2]), r = R * unit, pts = [];
    for (let a = 0; a < 28; a++) { const t = (a / 28) * Math.PI * 2; pts.push([c[0] + r * Math.cos(t), c[1] + r * Math.sin(t)]); }
    return poly(pts);
  };

  const items = [];
  for (let k = 0; k < N; k++) {
    const s = SZ[k], x = 12 + k * STEP, y = 10, grp = mk("g", {}, g);
    const parts = {};
    for (const [n, cls] of [["body", "sil"], ["legL", "sil"], ["legR", "sil"], ["earL", "sil"], ["earR", "sil"], ["head", "sil"], ["muz", "lo"]]) parts[n] = mk("path", { class: cls }, grp);
    items.push({ k, s, x, y, parts, z: tween(k === FAV ? LIFT * 0.5 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const { s, x, y, parts } = it, z = SZ0 + lift;
    const at = (f, sd, dz) => [x + (f + sd) * D, y + (f - sd) * D, z + dz];
    parts.body.setAttribute("d", circle(at(0, 0, 9 * s), 9 * s));
    parts.legL.setAttribute("d", circle(at(8 * s, -5 * s, 3 * s), 3.4 * s));
    parts.legR.setAttribute("d", circle(at(8 * s, 5 * s, 3 * s), 3.4 * s));
    const hz = 9 * s + 14 * s;
    parts.earL.setAttribute("d", circle(at(0, -5.5 * s, hz + 5 * s), 2.8 * s));
    parts.earR.setAttribute("d", circle(at(0, 5.5 * s, hz + 5 * s), 2.8 * s));
    parts.head.setAttribute("d", circle(at(0, 0, hz), 7 * s));
    parts.muz.setAttribute("d", circle(at(5 * s, 0, hz - 2 * s), 2.6 * s));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, SZ0 + 16 * it.s));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 50 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.5 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      for (const n of ["body", "legL", "legR", "earL", "earR", "head"]) it.parts[n].classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "bear " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "teddybears",
  means: "Five teddy bears of mixed sizes on a shelf: the bear under the pointer hops up, and its neighbours bob a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[97, 126], [175, 169], [254, 204], null],
  mount,
});

tramcar.code:
/**
 * Tramcar: a tram on a pair of rails, its roof with a pantograph, a row of
 * windows along the near side, and four low platforms by the track. The
 * pointer picks a platform by where it is along the line: that platform's
 * edge goes bright and the tram glides to stop at it. At rest the tram
 * waits just short of the second stop, which is bright.
 *
 * The pattern: one of many in a single row; the hit is on the ground plane.
 */
const {
  Cam, clamp, facing, fit, open, poly, prism, proj, rings, ringAt, rrect, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, SP = 40, X0 = 20, L = 46, Y0 = -3, Y1 = 11, ZB = 3, ZT = 22, PY0 = 15, PY1 = 23, PW = 14;
const REST_X = X0 + SP - L / 2 - 9, FAV = 1, PH = [2, 3, 2.5, 3.5];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let dur = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-12, Y0, 0], [X0 + 3 * SP + 30, Y0, 0], [-12, PY1, 0], [X0 + 3 * SP + 30, PY1, 0], [REST_X + L / 2, 4, 36]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the track: two rails and their sleepers, painted first
  const XA = -12, XB = X0 + 3 * SP + 30;
  let track = seg(P(XA, 0, 0), P(XB, 0, 0)) + seg(P(XA, 8, 0), P(XB, 8, 0));
  for (let x = XA + 4; x < XB; x += 9) track += seg(P(x, -2, 0), P(x, 10, 0));
  mk("path", { class: "nf lo", d: track }, g);

  // the tram: body, roof and pantograph, redrawn as it glides
  const tg = mk("g", {}, g);
  const body = solid(tg), roof = solid(tg);
  const marks = mk("path", { class: "nf lo" }, tg), panto = mk("path", { class: "nf" }, tg);
  const tx = tween(REST_X, dur);
  let last = NaN;
  function drawTram(x) {
    if (x === last) return;
    last = x;
    const [r, i] = rings(x, Y0, x + L, Y1, 7, 1.4);
    put(body, prism(P, front, r, i, ZB, ZT));
    const [rr, ri] = rings(x + 6, Y0 + 3, x + L - 6, Y1 - 3, 4, 1);
    put(roof, prism(P, front, rr, ri, ZT, ZT + 3));
    let d = "";
    for (let k = 0; k < 5; k++) {
      const wx = x + 7 + k * 6.8;
      d += poly(rrect(wx, 11, wx + 5, 18, 1.2, 3).map((s) => P(s.u, Y1, s.v)));
    }
    d += seg(P(x + 2, Y1, 7), P(x + L - 2, Y1, 7));
    marks.setAttribute("d", d);
    const cx = x + L / 2;
    panto.setAttribute("d", open([P(cx - 5, 4, ZT + 3), P(cx + 1, 4, ZT + 9), P(cx - 3, 4, ZT + 13)]) + seg(P(cx - 3, -1, ZT + 13), P(cx - 3, 9, ZT + 13)));
  }

  // the platforms, nearer than the track, each a low plate
  const plats = [];
  for (let k = 0; k < N; k++) {
    const s = solid(g), cx = X0 + k * SP;
    const [r, i] = rings(cx - PW, PY0, cx + PW, PY1, 2, 1);
    put(s, prism(P, front, r, i, 0, PH[k]));
    plats.push(s);
  }

  const B = register(stage, (_dt, now) => { drawTram(tval(tx, now)); return !tdone(tx, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    if (x < -14 || x > XB + 2 || y < Y0 - 8 || y > PY1 + 4) return -1;
    return clamp(Math.round((x - X0) / SP), 0, N - 1);
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tx.dur = dur;
    tset(tx, a < 0 ? REST_X : X0 + a * SP - L / 2, performance.now(), 0);
    plats.forEach((s, k) => s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a)));
    read.textContent = a < 0 ? "rest" : "stop " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { dur = v; }, destroy: bag.dispose };
}

hairline({
  name: "tramcar",
  means: "A tram on its rails: the platform under the pointer lights and the tram glides along the line to stop at it.",
  rules: [1, 5, 6, 8],
  range: [400, 700, 1200],
  tour: [[104, 137], [190, 180], [282, 224], null],
  mount,
});

bulldozer.code:
/**
 * Bulldozer: a crawler dozer on two rounded tracks, a body, a cab and a wide
 * blade on two push arms. The pointer stands on the ground: the nearer it
 * comes to the blade end, the higher the blade lifts on its arms, on a
 * spring. At rest the blade hangs just off the ground, bright. The slider is
 * how high the blade can rise.
 *
 * The pattern: a part following the pointer (spring).
 */
const {
  Cam, clamp, fit, facing, prism, proj, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BX = 64, REST = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[-2, -6, 0], [BX + 5, 42, 0], [BX + 5, -6, 0], [-2, 42, 0], [20, 18, 40], [BX + 5, -6, 22 + 16], [BX + 5, 42, 22 + 16]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, o, i, z0, z1)); };

  block(0, 0, 56, 9, 6, 1.5, 0, 12);          // far track
  block(6, 8, 48, 28, 3, 1.5, 9, 22);         // body
  block(30, 10, 48, 26, 2, 1.2, 22, 27);      // engine hood
  block(9, 10, 29, 26, 3, 1.5, 22, 40);       // cab
  block(0, 27, 56, 36, 6, 1.5, 0, 12);        // near track
  // tread marks on the near track's side: a few dim drops
  const tread = mk("path", { class: "lo nf" }, g);
  let td = "";
  for (let x = 10; x <= 46; x += 9) td += seg(P(x, 36, 2), P(x, 36, 10));
  tread.setAttribute("d", td);

  const arms = mk("path", { class: "nf" }, g);
  const blade = solid(g);
  blade.sil.classList.add("hi");
  const [bo, bi] = rings(BX, -5, BX + 4, 41, 1.6, 0.7);

  const lift = spring(REST);
  let last = NaN;
  function draw(z) {
    if (z === last) return;
    last = z;
    put(blade, prism(P, front, bo, bi, z, z + 16));
    let d = "";
    for (const y of [4.5, 31.5]) d += seg(P(40, y, 7), P(BX, y, z + 6)) + seg(P(44, y, 15), P(BX, y, z + 12));
    arms.setAttribute("d", d);
  }

  const B = register(stage, (dt) => { const m = stepS(lift, dt); draw(lift.x); return m; });
  bag.add(B.unregister);

  function aim(p) {
    const [u, v] = unproj(C, p[0], p[1], 0);
    if (u < -12 || u > BX + 18 || v < -16 || v > 52) return leave();
    const t = clamp(u / BX, 0, 1);
    lift.t = REST + t * (max - REST);
    read.textContent = "blade " + Math.round(t * 100) + "%";
    B.wake();
  }
  function leave() { lift.t = REST; read.textContent = "rest"; B.wake(); }
  draw(REST);
  read.textContent = "rest";
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; if (lift.t > REST) lift.t = Math.min(lift.t, max); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "bulldozer",
  means: "A crawler bulldozer: the nearer the pointer comes to the blade end, the higher the blade lifts on its push arms.",
  rules: [1, 3, 5, 8],
  range: [8, 15, 22],
  tour: [[154, 174], [205, 200], [255, 225], null],
  mount,
});

windpump.code:
/**
 * Windpump: a tapering farm tower on a pad, a water trough at its foot, and
 * on top a bladed wheel with a tail vane. The pointer is the wind: the head
 * turns on its mast to face the point on the ground under the pointer, a
 * spring following it. At rest it faces the front left, the vane bright.
 * The slider is how far the head may swing from rest.
 *
 * The pattern: one part turning to face the pointer (officechairs).
 */
const {
  Cam, circ, fit, facing, fillet, hull, open, poly, prism, proj, rings, ringAt, rrect, run, seg, clamp, rad, unproj,
  disposer, mk, pointer, put, register, solid, spring, stepS,
} = HL;

const H = 96, R = 22, REST = rad(80), FOOT = 15, TOPW = 3.5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = rad(value);
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-30, -30, 0], [44, 30, 0], [30, 44, 0], [0, 0, H + R + 6], [-24, 0, H + R], [0, -24, H + R]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [pr, pi] = rings(-26, -26, 26, 26, 6, 2);
  put(solid(g), prism(P, front, pr, pi, 0, 3));
  // the trough, low and round, beside the tower's front
  const tr = (r) => circ(r, 32).map((q) => ({ ...q, u: q.u + 30, v: q.v + 26 }));
  put(solid(g), prism(P, front, tr(11), tr(9.5), 0, 7));

  // the tower: a foot ring wider than its top ring, hull and crease
  const foot = rrect(-FOOT, -FOOT, FOOT, FOOT, 3, 4), top = rrect(-TOPW, -TOPW, TOPW, TOPW, 1.5, 4), inner = rrect(-TOPW + 0.8, -TOPW + 0.8, TOPW - 0.8, TOPW - 0.8, 0.7, 4);
  const tw = solid(g);
  put(tw, { sil: poly(hull(ringAt(P, foot, 3).concat(ringAt(P, top, H)))), crease: open(ringAt(P, run(inner, front), H)) });
  // braces on the two near faces
  let br = "";
  const at = (z) => FOOT + (TOPW - FOOT) * ((z - 3) / (H - 3));
  for (let i = 0; i < 4; i++) {
    const z0 = 3 + i * 22, z1 = z0 + 22, w0 = at(z0) - 1, w1 = at(z1) - 1;
    br += seg(P(w0, -w0, z0), P(w1, w1, z1)) + seg(P(-w0, w0, z0), P(w1, w1, z1)) + seg(P(w0, w0, z0), P(w1, -w1, z1)) + seg(P(w0, w0, z0), P(-w1, w1, z1));
  }
  mk("path", { d: br, class: "lo nf" }, g);
  // the pump rod running down into the pad
  mk("path", { d: seg(P(FOOT + 3, 0, 3), P(FOOT + 3, 0, 20)), class: "lo nf" }, g);

  const head = mk("g", {}, g);
  const tail = mk("path", { class: "sil" }, head), boom = mk("path", { class: "nf" }, head);
  const wheel = mk("g", {}, head);
  const rim = mk("path", { class: "sil" }, wheel), blades = mk("path", { class: "lo nf" }, wheel), hub = mk("path", {}, wheel);

  const yaw = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const dx = Math.cos(a), dy = Math.sin(a), px = -dy, py = dx, hz = H + R * 0.2 + 4;
    const c = [dx * 6, dy * 6], wpt = (t, r, k = 0) => P(c[0] + k * dx + r * Math.cos(t) * px, c[1] + k * dy + r * Math.cos(t) * py, hz + r * Math.sin(t));
    const ring = [], ring2 = [];
    for (let i = 0; i < 40; i++) { const t = (i / 40) * 2 * Math.PI; ring.push(wpt(t, R), wpt(t, R, 1.6)); }
    rim.setAttribute("d", poly(hull(ring)));
    let b = "";
    for (let i = 0; i < 16; i++) { const t = (i / 16) * 2 * Math.PI; b += seg(wpt(t, 5), wpt(t, R - 2)); }
    for (let i = 0; i < 40; i++) ring2.push(wpt((i / 40) * 2 * Math.PI, R - 2));
    blades.setAttribute("d", b + poly(ring2));
    const hb = [];
    for (let i = 0; i < 12; i++) { const t = (i / 12) * 2 * Math.PI; hb.push(wpt(t, 3.5), wpt(t, 3.5, 4)); }
    hub.setAttribute("d", poly(hull(hb)));
    // the tail: a boom back from the mast, a vane standing at its end
    const T = (k, z) => P(-dx * k, -dy * k, hz + z);
    boom.setAttribute("d", seg(T(-6, 0), T(30, 2)));
    tail.setAttribute("d", poly(fillet([T(18, -1), T(40, -6), T(42, 14), T(22, 6)], [1, 2, 2, 1])));
    // whichever is nearer the viewer is painted last
    if (-dx - dy > dx + dy) head.append(tail); else head.prepend(tail);
  }

  const B = register(stage, (dt) => { const m = stepS(yaw, dt); draw(yaw.x); return m; });
  bag.add(B.unregister);

  let on = null;
  function aim(p) {
    let want = REST, act = !!p;
    if (p) {
      const [wx, wy] = unproj(C, p[0], p[1], 0);
      let d = Math.atan2(wy, wx) - REST;
      d = Math.atan2(Math.sin(d), Math.cos(d));
      want = REST + clamp(d, -reach, reach);
    }
    yaw.t = want;
    if (act !== on) { on = act; tail.classList.toggle("hi", !act); rim.classList.toggle("hi", act); }
    const deg = Math.round((((want * 180) / Math.PI) % 360 + 360) % 360);
    read.textContent = act ? "wind " + deg + "°" : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = rad(v); if (on === false) aim(null); }, destroy: bag.dispose };
}

