  mount,
});

powerlines.code:
/**
 * Power lines: three tapering pylons in a row, each with a cross arm, two
 * lines hanging between them in sagging spans. The pointer picks a span by
 * where it stands: its lines swing out and sag deeper, the span beside it
 * a little, staggered from it. At rest one span hangs swung, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, ringAt, rrect, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, GAP = 64, H = 74, ARM = 15, FAV = 0, SW = 30;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.7);
  const X1 = (N - 1) * GAP;
  fit(C, [[-12, -20, 0], [X1 + 12, 20, 0], [0, 0, H + 4], [X1, 0, H + 4], [GAP / 2, -ARM - SW, H - 30]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const back = mk("g", {}, g), mid = mk("g", {}, g), near = mk("g", {}, g);

  for (let k = 0; k < N; k++) {
    const x = k * GAP, grp = mk("g", {}, mid);
    const [pr, pi] = rings(x - 9, -9, x + 9, 9, 3, 1.2);
    put(solid(grp), prism(P, front, pr, pi, 0, 2));
    const foot = rrect(x - 7, -7, x + 7, 7, 2, 4), top = rrect(x - 1.8, -1.8, x + 1.8, 1.8, 0.8, 4), inn = rrect(x - 1.2, -1.2, x + 1.2, 1.2, 0.5, 4);
    put(solid(grp), { sil: poly(hull(ringAt(P, foot, 2).concat(ringAt(P, top, H)))), crease: open(ringAt(P, run(inn, front), H)) });
    const [ar, ai] = rings(x - 1.6, -ARM - 2, x + 1.6, ARM + 2, 1.2, 0.5);
    put(solid(grp), prism(P, front, ar, ai, H - 12, H - 9));
    // insulators hanging under the arm's two ends
    for (const y of [-ARM, ARM]) mk("path", { d: open([P(x, y, H - 12), P(x, y, H - 17)]), class: "nf" }, grp);
  }

  const spans = [];
  for (let s = 0; s < N - 1; s++) {
    const far = mk("path", { class: "nf" }, back), nr = mk("path", { class: "nf" }, near);
    spans.push({ s, x0: s * GAP, far, nr, w: tween(s === FAV ? 0.6 : 0), last: NaN });
  }
  function draw(sp, a) {
    if (a === sp.last) return;
    sp.last = a;
    for (const [el, y] of [[sp.far, -ARM], [sp.nr, ARM]]) {
      const pts = [];
      for (let i = 0; i <= 20; i++) {
        const t = i / 20, bow = 4 * t * (1 - t);
        pts.push(P(sp.x0 + t * GAP, y - a * SW * bow, H - 17 - (10 + a * 20) * bow));
      }
      el.setAttribute("d", open(pts));
    }
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const sp of spans) { draw(sp, tval(sp.w, now)); if (!tdone(sp.w, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = spans.map((sp) => P(sp.x0 + GAP / 2, 0, H - 30));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 70 && Math.abs(mids[best][1] - sy) < 110 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    spans.forEach((sp, k) => {
      const d = Math.abs(k - a), w = a < 0 ? (k === FAV ? 0.6 : 0) : d === 0 ? 1 : 0.25;
      tset(sp.w, w, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      sp.far.classList.toggle("hi", on); sp.nr.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "span " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "powerlines",
  means: "Three pylons with lines hanging between them: the span under the pointer swings out and sags, the one beside it a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[165, 125], [238, 159], [123, 66], null],
  mount,
});

transformer.code:
/**
 * Transformer: a substation tank on its plinth, cooling fins down its front
 * face and three porcelain bushings standing on its lid. The pointer picks a
 * bushing by where it stands: it draws up out of its flange, and the bushings
 * beside it rise a little, staggered from it. At rest the middle bushing is
 * raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, XS = [18, 40, 62], BY = 24, TOP = 52, H = 20, LIFT = 22, FAV = 1, SHEDS = 4;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.85);
  fit(C, [[-6, -6, 0], [86, 62, 0], [86, -6, 0], [-6, 62, 0], [18, 24, TOP + 2 + H + LIFT + 6], [62, 24, TOP + 2 + H + LIFT + 6]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-6, -6, 86, 62, 4, 2);
  put(solid(g), prism(P, front, pr, pi, 0, 4));
  const [tr, ti] = rings(0, 0, 80, 48, 4, 1.6);
  put(solid(g), prism(P, front, tr, ti, 4, TOP));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = XS[k], grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, BY, 7.5), disc(x, BY, 6), TOP, TOP + 2));
    const core = solid(grp), sheds = [];
    for (let i = 0; i < SHEDS; i++) sheds.push(solid(grp));
    const cap = solid(grp);
    items.push({ k, x, core, sheds, cap, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }
  // cooling fins on the front face, nearer than the bushings, painted last
  for (let i = 0; i < 6; i++) {
    const x = 10 + i * 12, [fr, fi] = rings(x - 1.3, 48, x + 1.3, 60, 1, 0.5);
    put(solid(g), prism(P, front, fr, fi, 10, 44));
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = TOP + 2 + lift;
    put(it.core, prism(P, front, disc(it.x, BY, 3), disc(it.x, BY, 2.2), TOP + 1, z0 + H));
    it.sheds.forEach((s, i) => { const z = z0 + 3 + i * 4.6; put(s, prism(P, front, disc(it.x, BY, 6), disc(it.x, BY, 4.8), z, z + 1.4)); });
    put(it.cap, prism(P, front, disc(it.x, BY, 2), disc(it.x, BY, 1.3), z0 + H, z0 + H + 4));
  }
  function light(it, on) {
    for (const s of [it.core, ...it.sheds, it.cap]) s.sil.classList.toggle("hi", on);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, BY, TOP + 2 + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      light(it, k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "H" + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "transformer",
  means: "A substation transformer with three bushings on its lid: the bushing under the pointer draws up, its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[176, 96], [205, 110], [234, 125], null],
  mount,
});

cardterminal.code:
/**
 * Card terminal: a handheld payment terminal lying on the counter, a card
 * standing in the slot at its head, a screen and a twelve-key pad. The
 * pointer presses the key under it: the key sinks into the body and the
 * keys around it dip a little, staggered from it. At rest the confirm key
 * is half pressed, bright. The slider is the stagger.
 *
 * The pattern: a field of keys pressing (pianokeys), on a face plane.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, ringAt, rrect, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BZ = 10, KH = 5, DIP = 4.2, COLS = 3, ROWS = 4, KX = 14, KY = 10.5, X0 = 10, Y0 = 43, KW = 11, KD = 7.6, FAV = 11;
const NAMES = ["1", "2", "3", "4", "5", "6", "7", "8", "9", "clr", "0", "ok"];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[0, -24, 0], [62, 92, 0], [62, -24, 0], [0, 92, 0], [12, -24, 30], [50, -24, 30]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the card, standing up out of the slot at the far end
  const [cr, ci] = rings(14, -3, 48, -1.6, 0.6, 0.4);
  put(solid(g), prism(P, front, cr, ci, 4, 30));
  const [br, bi] = rings(0, 0, 62, 92, 9, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  mk("path", { d: poly(ringAt(P, rrect(18, 3, 44, 5, 1, 4), BZ)), class: "lo" }, g);
  mk("path", { d: poly(ringAt(P, rrect(9, 10, 53, 35, 3, 4), BZ)), class: "lo" }, g);

  const keys = [];
  for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) {
    const i = r * COLS + c, x = X0 + c * KX + KW / 2 + 1, y = Y0 + r * KY + KD / 2;
    keys.push({ i, r, c, x, y, s: null, d: tween(i === FAV ? DIP * 0.6 : 0), last: NaN });
  }
  // paint back to front, by ascending x + y
  keys.slice().sort((a, b) => a.x + a.y - (b.x + b.y)).forEach((k) => { k.s = solid(g); });

  function draw(k, dip) {
    if (dip === k.last) return;
    k.last = dip;
    const [kr, ki] = rings(k.x - KW / 2, k.y - KD / 2, k.x + KW / 2, k.y + KD / 2, 2, 0.9);
    put(k.s, prism(P, front, kr, ki, BZ, BZ + KH - dip));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const k of keys) { draw(k, tval(k.d, now)); if (!tdone(k.d, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, BZ + KH);
    for (const k of keys) if (Math.abs(x - k.x) < KX / 2 && Math.abs(y - k.y) < KY / 2) return k.i;
    return -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const fr = from >= 0 ? keys[from] : null, ak = a >= 0 ? keys[a] : null;
    keys.forEach((k) => {
      const dd = ak ? Math.max(Math.abs(k.r - ak.r), Math.abs(k.c - ak.c)) : 9;
      const d = !ak ? (k.i === FAV ? DIP * 0.6 : 0) : dd === 0 ? DIP : dd === 1 ? 1.2 : 0;
      tset(k.d, d, now, fr ? Math.hypot(k.r - fr.r, k.c - fr.c) * stag : 0);
      k.s.sil.classList.toggle("hi", k.i === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "key " + NAMES[a];
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "cardterminal",
  means: "A card terminal with a card in its slot: the key under the pointer presses into the body and the keys around it dip.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[152, 159], [159, 180], [147, 209], null],
  mount,
});

coinsorter.code:
/**
 * Coin sorter: a counting tray with four sleeves of different bores, each
 * holding a stack of coins of its own size and height. The pointer picks a
 * sleeve by where it stands: its stack pushes up out of the sleeve, and the
 * stacks beside it rise a little, staggered from it. At rest the second
 * stack is raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const RS = [7, 8.5, 10, 11.5], COUNT = [6, 9, 5, 7], CT = 2.4, Y = 16, BASE = 8, SL = 8, LIFT = 16, FAV = 1;
const XS = [10, 31, 55, 82];
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.55);
  const topZ = BASE + SL + LIFT + 9 * CT + 4;
  fit(C, [[-4, -4, 0], [98, 34, 0], [98, -4, 0], [-4, 34, 0], [10, Y, topZ], [82, Y, topZ]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-4, -4, 98, 34, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, BASE));

  const items = [];
  for (let k = 0; k < XS.length; k++) {
    const x = XS[k], r = RS[k], grp = mk("g", {}, g), coins = [];
    const sleeve = solid(grp), rod = solid(grp);
    for (let i = 0; i < COUNT[k]; i++) coins.push(solid(grp));
    items.push({ k, x, r, coins, sleeve, rod, z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = BASE + SL + lift;
    // the stack rides a push rod out of the sleeve, painted after it
    put(it.rod, prism(P, front, disc(it.x, Y, it.r * 0.45, 20), disc(it.x, Y, it.r * 0.45 - 1, 20), BASE + SL - 1, z0 + 0.5));
    it.coins.forEach((s, i) => { const z = z0 + i * CT; put(s, prism(P, front, disc(it.x, Y, it.r - 0.8), disc(it.x, Y, it.r - 1.6), z, z + CT - 0.3)); });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);
  for (const it of items) put(it.sleeve, prism(P, front, disc(it.x, Y, it.r + 1.2), disc(it.x, Y, it.r), BASE, BASE + SL));

  const mids = items.map((it) => P(it.x, Y, BASE + SL));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      for (const s of it.coins) s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "lane " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "coinsorter",
  means: "A coin sorter with four sleeves of stacked coins: the stack under the pointer pushes up out of its sleeve, its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[131, 118], [213, 158], [261, 182], null],
  mount,
});

turnstiles.code:
/**
 * Turnstiles: a row of four waist-high cabinets on a slab, an arm reaching
 * from each across the lane beside it. The pointer picks a lane by where it
 * stands: that arm swings back along the lane to let you through, and the
 * arms beside it give a little, staggered from it. At rest one lane stands
 * open, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, rad, tdone, tset, tval, tween,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 42, CW = 12, CD = 44, CH = 30, AZ = 24, AL = 30, FAV = 1, SZ = 4;
const X1 = (N - 1) * STEP + CW;
const disc = (x, y, r, n = 14) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-8, -8, 0], [X1 + 8, CD + 8, 0], [X1 + 8, -8, 0], [-8, CD + 8, 0], [0, 0, SZ + CH + 2], [X1, 0, SZ + CH + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-8, -8, X1 + 8, CD + 8, 6, 2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));

  const cabs = [], arms = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * STEP, cg = mk("g", {}, g);
    const [r, i] = rings(x0, 0, x0 + CW, CD, 4, 1.4);
    put(solid(cg), prism(P, front, r, i, SZ, SZ + CH));
    // the card reader: a slim plate on the cabinet's top, near the lane
    const [pr, pi] = rings(x0 + 3, CD / 2 - 6, x0 + CW - 3, CD / 2 + 6, 2, 0.8);
    put(solid(cg), prism(P, front, pr, pi, SZ + CH, SZ + CH + 1.4));
    const dot = flatDot(cg, C, 2.2, "dot off");
    place(dot, P(x0 + CW / 2, CD / 2, SZ + CH + 1.4));
    cabs.push({ cg, dot });
    if (k < N - 1) {
      const ag = mk("g", {}, g);
      const hub = mk("path", { class: "nf" }, ag), arm = mk("path", { class: "sil" }, ag);
      const px = x0 + CW + 1.5, py = CD / 2 + 4;
      hub.setAttribute("d", poly(hull(ringAt(P, disc(px, py, 3), SZ + AZ - 3).concat(ringAt(P, disc(px, py, 3), SZ + AZ + 4)))));
      arms.push({ k, px, py, ag, arm, a: tween(k === FAV ? 80 : 6 * k), last: NaN });
    }
  }
  // paint order: arm k sits between cabinet k and k+1
  for (let k = 0; k < N - 1; k++) cabs[k].cg.after(arms[k].ag);

  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const ex = it.px + AL * Math.cos(rad(deg)), ey = it.py + AL * Math.sin(rad(deg));
    const z = SZ + AZ, pts = [];
    for (const zz of [z, z + 3.2]) pts.push(...ringAt(P, disc(it.px, it.py, 2.2), zz), ...ringAt(P, disc(ex, ey, 2.2), zz));
    it.arm.setAttribute("d", poly(hull(pts)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of arms) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = arms.map((it) => P(it.px + AL / 2, it.py - 6, SZ + AZ / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const on = a < 0 ? FAV : a;
    arms.forEach((it, k) => {
      const dd = Math.abs(k - a), deg = a < 0 ? (k === FAV ? 80 : 6 * k) : dd === 0 ? 90 : dd === 1 ? 14 : 0;
      tset(it.a, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.arm.classList.toggle("hi", k === on);
    });
    cabs.forEach((c, k) => c.dot.setAttribute("class", k === on ? "dot m" : "dot off"));
    read.textContent = a < 0 ? "rest" : "lane " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "turnstiles",
  means: "A row of turnstiles: the arm in the lane under the pointer swings back to let you through, and the arms beside it give a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[142, 135], [199, 163], [255, 191], null],
  mount,
});

metaldetector.code:
/**
 * Security gate: a walk-through arch on a mat, each post faced with a column
 * of zone pads. The pointer picks a height through the arch: the pads of that
 * zone push out of both posts, and the zones beside it push a little,
 * staggered from it. At rest one zone is out, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single column, both sides answering as one.
 */
const {
  Cam, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NZ = 6, GW = 64, PW = 12, D = 16, H = 84, BH = 12, MZ = 3, ZH = 12, Z0 = MZ + 6, OUT = 9, FAV = 2;
const REST = [1.5, 0.5, OUT * 0.8, 1, 2, 0.5];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.8);
  fit(C, [[-14, -14, 0], [GW + 14, D + 30, 0], [GW + 14, -14, 0], [-14, D + 30, 0], [0, 0, H + BH], [GW, 0, H + BH], [0, D + OUT, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [mr, mi] = rings(-14, -14, GW + 14, D + 30, 6, 2);
  put(solid(g), prism(P, front, mr, mi, 0, MZ));

  const zones = Array.from({ length: NZ }, (_, k) => ({ k, pads: [], o: tween(REST[k]), last: NaN }));
  for (const x0 of [0, GW - PW]) {
    const [pr, pi] = rings(x0, 0, x0 + PW, D, 4, 1.6);
    put(solid(g), prism(P, front, pr, pi, MZ, H));
    for (const z of zones) {
      const s = solid(g);
      s.sil.classList.add("sil");
      z.pads.push({ s, x0 });
    }
  }
  const [br, bi] = rings(-2, -1, GW + 2, D + 1, 5, 1.8);
  put(solid(g), prism(P, front, br, bi, H, H + BH));

  function draw(z, o) {
    if (o === z.last) return;
    z.last = o;
    const zb = Z0 + z.k * ZH;
    for (const p of z.pads) {
      const [r, i] = rings(p.x0 + 2, D - 4 + o, p.x0 + PW - 2, D + o, 1.5, 0.7);
      put(p.s, prism(P, front, r, i, zb, zb + ZH - 2.5));
    }
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const z of zones) { draw(z, tval(z.o, now)); if (!tdone(z.o, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  // hit: rest centres of the left post's pads, by screen y; the arch's span by screen x
  const mids = zones.map((z) => P(PW / 2, D, Z0 + z.k * ZH + ZH / 2));
  const xl = P(-6, D + 6, 0)[0], xr = P(GW + 6, 0, 0)[0];
  function hit([sx, sy]) {
    if (sx < xl || sx > xr) return -1;
    const off = (sx - mids[0][0]) * 0.5;
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[1] + off - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < ZH * 1.6 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const on = a < 0 ? FAV : a;
    zones.forEach((z) => {
      const dd = Math.abs(z.k - a), o = a < 0 ? REST[z.k] : dd === 0 ? OUT : dd === 1 ? 3 : 0.5;
      tset(z.o, o, now, from < 0 ? 0 : Math.abs(z.k - from) * stag);
      for (const p of z.pads) p.s.sil.classList.toggle("hi", z.k === on);
    });
    read.textContent = a < 0 ? "rest" : "zone " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "metaldetector",
  means: "A walk-through security arch: the zone pads at the pointer's height push out of both posts, and the zones beside them a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[200, 209], [200, 171], [200, 134], null],
  mount,
});

observatory.code:
/**
 * Observatory: a round drum on a plinth under a dome, a telescope tube
 * standing out of the dome's crown. The tube turns to face the pointer's
 * bearing on the ground and tips lower as the pointer goes farther out. At
 * rest it looks up toward the left, bright. The slider is the reach.
 *
 * The pattern: one part turning to face the pointer (aim).
 */
const {
  Cam, circ, clamp, fit, facing, hull, lerp, poly, prism, proj, rad, rings, ringAt, unproj,
  disposer, mk, pointer, put, register, solid, spring, stepS,
} = HL;

const R = 26, ZD = 30, LEN = 40, TR = 5, REST = [135, 40];
const disc = (r, n = 48) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-36, -36, 0], [36, 36, 0], [36, -36, 0], [-36, 36, 0], [-30, -30, 95], [30, 30, 70], [0, 0, ZD + R + LEN + 6]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-34, -34, 34, 34, 8, 2);
  put(solid(g), prism(P, front, pr, pi, 0, 4));
  put(solid(g), prism(P, front, disc(R), disc(R - 1.5), 4, ZD));
  // the dome: a hemisphere's hull, a seam ring where it meets the drum
  const pts = [];
  for (let i = 0; i <= 8; i++) { const t = (i / 8) * (Math.PI / 2); pts.push(...ringAt(P, disc(R * Math.cos(t), 40), ZD + R * 0.92 * Math.sin(t))); }
  mk("path", { d: poly(hull(pts)), class: "sil" }, g);
  mk("path", { d: poly(ringAt(P, disc(R - 2, 48), ZD + 1.5)).replace(/Z$/, ""), class: "nf lo" }, g);
  const base = [0, 0, ZD + R * 0.92 - 1];
  mk("path", { d: poly(hull(ringAt(P, disc(7, 20), base[2] - 1).concat(ringAt(P, disc(7, 20), base[2] + 2)))), class: "" }, g);
  const tube = mk("path", { class: "sil" }, g), cap = mk("path", { class: "nf lo" }, g);

  const az = spring(REST[0]), el = spring(REST[1]);
  let lastA = NaN, lastE = NaN;
  function ring(c, u, w, r) {
    const out = [];
    for (let i = 0; i < 24; i++) { const a = (i / 24) * Math.PI * 2, ca = Math.cos(a) * r, sa = Math.sin(a) * r; out.push(P(c[0] + ca * u[0] + sa * w[0], c[1] + ca * u[1] + sa * w[1], c[2] + ca * u[2] + sa * w[2])); }
    return out;
  }
  function draw() {
    if (az.x === lastA && el.x === lastE) return;
    lastA = az.x; lastE = el.x;
    const th = rad(az.x), e = rad(el.x);
    const d = [Math.cos(th) * Math.cos(e), Math.sin(th) * Math.cos(e), Math.sin(e)];
    const u = [-Math.sin(th), Math.cos(th), 0], w = [d[1] * u[2] - d[2] * u[1], d[2] * u[0] - d[0] * u[2], d[0] * u[1] - d[1] * u[0]];
    const a = base.map((v, k) => v - d[k] * 6), b = base.map((v, k) => v + d[k] * LEN);
    const end = ring(b, u, w, TR + 0.6);
    tube.setAttribute("d", poly(hull(ring(a, u, w, TR).concat(end))));
    cap.setAttribute("d", poly(ring(base.map((v, k) => v + d[k] * (LEN - 1.5)), u, w, TR - 0.4)));
  }

  const B = register(stage, (dt) => {
    const m = stepS(az, dt) | stepS(el, dt);
    draw();
    return !!m;
  });
  bag.add(B.unregister);

  let on = false;
  function aim(p) {
    const [x, y] = unproj(C, p[0], p[1], 0), dist = Math.hypot(x, y);
    if (dist < 4) return;
    let t = (Math.atan2(y, x) * 180) / Math.PI, dlt = ((t - az.t) % 360 + 540) % 360 - 180;
    az.t += dlt;
    el.t = clamp(lerp(70, 18, dist / (60 + reach)), 18, 70);
    on = true;
    tube.classList.add("hi");
    read.textContent = "az " + String(Math.round(((az.t % 360) + 360) % 360)).padStart(3, "0");
    B.wake();
  }
  function leave() {
    on = false;
    az.t += ((REST[0] - az.t) % 360 + 540) % 360 - 180;
    el.t = REST[1];
    read.textContent = "rest";
    B.wake();
  }
  tube.classList.add("hi");
  draw();
  leave();
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "observatory",
  means: "A domed observatory on a plinth: the telescope turns to face the pointer and tips lower the farther out it goes.",
  rules: [1, 3, 5, 8],
  range: [0, 40, 120],
  tour: [[110, 200], [300, 220], [260, 110], null],
  mount,
});

marsbase.code:
/**
 * Mars base: four habitat domes on a landing pad, joined by low tunnels. The
 * pointer picks a dome by where it stands on the ground: that dome inflates
 * tall and its neighbours swell a little, staggered from it. At rest the
 * domes stand at uneven heights, the far one bright. The slider is the stagger.
 *
 * The pattern: one of many on a plane, picked by world position (terrain).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PZ = 3, FAV = 0;
const DOMES = [[0, 0, 18, 0.85], [46, 0, 13, 0.55], [0, 44, 14, 0.7], [44, 42, 11, 1]];
const TUNNELS = [[16.5, -4, 35, 4], [-4, 16, 4, 32], [42, 12, 48, 32]];
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-30, -30, 0], [66, 62, 0], [66, -30, 0], [-30, 62, 0], [0, 0, PZ + 18 * 1.5], [46, 0, PZ + 16]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-30, -28, 66, 62, 16, 2);
  put(solid(g), prism(P, front, pr, pi, 0, PZ));
  // order back to front by x + y; tunnels sit between the domes they join
  const items = DOMES.map(([x, y, r, f], k) => ({ k, x, y, r, f, z: tween(f), last: NaN }));
  const paint = [["d", 0], ["t", 0], ["t", 1], ["d", 1], ["t", 2], ["d", 2], ["d", 3]];
  for (const [kind, k] of paint) {
    if (kind === "t") {
      const [x0, y0, x1, y1] = TUNNELS[k], [tr, ti] = rings(x0, y0, x1, y1, 3.5, 1);
      put(solid(g), prism(P, front, tr, ti, PZ, PZ + 7));
    } else {
      const it = items[k];
      it.grp = mk("g", {}, g);
      it.dome = mk("path", { class: "sil" }, it.grp);
      it.seam = mk("path", { class: "nf lo" }, it.grp);
      it.hatch = mk("path", { class: "nf" }, it.grp);
    }
  }

  function draw(it, f) {
    if (f === it.last) return;
    it.last = f;
    const H = it.r * f, pts = [];
    for (let i = 0; i <= 8; i++) { const t = (i / 8) * (Math.PI / 2); pts.push(...ringAt(P, disc(it.x, it.y, it.r * Math.cos(t), 32), PZ + H * Math.sin(t))); }
    it.dome.setAttribute("d", poly(hull(pts)));
    const sr = it.r * Math.cos(Math.PI / 6), sz = PZ + H * 0.5;
    it.seam.setAttribute("d", poly(ringAt(P, disc(it.x, it.y, sr, 40), sz)));
    const hz = PZ + H;
    it.hatch.setAttribute("d", poly(hull(ringAt(P, disc(it.x, it.y, it.r * 0.22, 16), hz - 0.5).concat(ringAt(P, disc(it.x, it.y, it.r * 0.22, 16), hz + 1.6)))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, PZ + 6);
    let best = -1, bd = Infinity;
    items.forEach((it, k) => { const d = Math.hypot(x - it.x, y - it.y) - it.r; if (d < bd) { bd = d; best = k; } });
    return bd < 10 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), f = a < 0 ? it.f : dd === 0 ? 1.6 : dd === 1 ? it.f + 0.3 : it.f;
      tset(it.z, f, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.dome.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "hab " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "marsbase",
  means: "Four habitat domes on a pad joined by tunnels: the dome under the pointer inflates tall and its neighbours swell a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[290, 160], [205, 200], [120, 180], null],
  mount,
});

baseballbats.code:
/**
 * Baseball bats: five bats standing barrel down in a floor rack, knobs up.
 * The pointer picks a bat by where it stands along the row: it slides up out
 * of the rack, and the bats beside it lift a little, staggered from it. At
 * rest one bat stands half drawn, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 16, LIFT = 26, FAV = 3, BL = 62;
const X1 = (N - 1) * STEP + 20;
const REST = [2, 0, 5, 14, 3];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-4, -10, 0], [X1 + 4, 10, 0], [X1 + 4, -10, 0], [-4, 10, 0], [10, 0, BL + LIFT + 6], [X1 - 10, 0, BL + LIFT + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-4, -10, X1 + 4, 10, 5, 1.5);
  put(solid(g), prism(P, front, br, bi, 0, 4));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 10 + k * STEP, grp = mk("g", {}, g);

    mk("path", { d: poly(ringAt(P, disc(x, 0, 4.6, 28), 4)), class: "nf lo" }, grp);
    const bat = mk("path", { class: "sil" }, grp), tape = mk("path", { class: "nf lo" }, grp), knob = mk("path", { class: "nf" }, grp);
    items.push({ k, x, bat, tape, knob, z: tween(REST[k]), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const x = it.x, z0 = 4 + lift;
    const body = [...ringAt(P, disc(x, 0, 3.6), z0), ...ringAt(P, disc(x, 0, 3.6), z0 + 24), ...ringAt(P, disc(x, 0, 2.6), z0 + 38), ...ringAt(P, disc(x, 0, 1.5), z0 + BL - 4)];
    it.bat.setAttribute("d", poly(hull(body)));
    it.tape.setAttribute("d", poly(ringAt(P, disc(x, 0, 1.7), z0 + BL - 14)));
    it.knob.setAttribute("d", poly(hull(ringAt(P, disc(x, 0, 2.7, 16), z0 + BL - 3.5).concat(ringAt(P, disc(x, 0, 2.7, 16), z0 + BL - 1.5)))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 0, 30));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 16 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? REST[k] : dd === 0 ? LIFT : dd === 1 ? 6 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.bat.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bat " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "baseballbats",
  means: "Five bats standing in a floor rack: the bat under the pointer slides up out of the rack, its neighbours lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[150, 150], [200, 170], [250, 190], null],
  mount,
});

saxophones.code:
/**
 * Saxophones: three saxophones resting on pegs along a low stand, each a
 * curved brass tube with a flared bell. The pointer picks one by where it
 * stands: it lifts off its peg and its neighbours rise a little, staggered
 * from it. At rest the middle one is half raised, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 34, LIFT = 16, FAV = 1, BZ = 4, PEG = 5;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
// the centreline in the sax's own plane: [x, z, half-width]
const LINE = [];
for (let i = 0; i <= 4; i++) { const t = i / 4; LINE.push([-7 + 7 * Math.sin(t * Math.PI / 2), 68 - 6 * t, 1.2 + 0.4 * t]); }
for (let i = 1; i <= 8; i++) { const t = i / 8; LINE.push([0, 62 - 48 * t, 1.6 + 2.2 * t]); }
for (let i = 1; i <= 8; i++) { const a = Math.PI - (i / 8) * Math.PI; LINE.push([6 + 6 * Math.cos(a), 14 - 6 * Math.sin(a), 3.8 + 0.3 * i / 8]); }
for (let i = 1; i <= 6; i++) { const t = i / 6; LINE.push([12 + 4 * t, 14 + 22 * t, 4.1 + 1.6 * t * t]); }

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.2);
  const Y1 = (N - 1) * STEP;
  fit(C, [[-16, -12, 0], [30, Y1 + 12, 0], [-16, Y1 + 12, 0], [30, -12, 0], [-9, 0, 70 + LIFT + BZ + PEG], [-9, Y1, 70 + BZ + PEG]], 200, 166);
  const P = proj(C), front = facing(C), S = 2.2;
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-16, -12, 30, Y1 + 12, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const y = k * STEP, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(6, y, 3), disc(6, y, 2), BZ, BZ + PEG));
    const body = mk("path", { class: "sil" }, grp), bell = mk("path", { class: "lo" }, grp), keys = mk("path", { class: "nf lo" }, grp);
    items.push({ k, y, grp, body, bell, keys, z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = BZ + PEG - 8 + lift, pts = LINE.map(([x, z]) => P(x, it.y, z0 + z)), L = [], R = [];
    pts.forEach((p, i) => {
      const a = pts[Math.max(0, i - 1)], b = pts[Math.min(pts.length - 1, i + 1)];
      const tx = b[0] - a[0], ty = b[1] - a[1], d = Math.hypot(tx, ty) || 1, w = LINE[i][2] * S;
      L.push([p[0] - (ty / d) * w, p[1] + (tx / d) * w]); R.push([p[0] + (ty / d) * w, p[1] - (tx / d) * w]);
    });
    const top = LINE[LINE.length - 1], rim = ringAt(P, disc(top[0], it.y, 7, 28), z0 + top[1]);
    it.body.setAttribute("d", poly(L.concat(R.reverse())));
    it.bell.setAttribute("d", poly(rim));
    let k = "";
    for (const zz of [24, 32, 40, 48]) { const c = P(0, it.y, z0 + zz); k += `M${c[0] + 2.4},${c[1]}a2.4,1.2 0 1,0 0.01,0z`; }
    it.keys.setAttribute("d", k);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(6, it.y, BZ + PEG + 36));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 3 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "sax " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

