  tour: [[172, 220], [172, 165], [172, 109], null],
  mount,
});

porchlights.code:
/**
 * Porch lights: four lanterns hanging on short chains from the beam of a
 * porch, in front of a house wall with its door. The pointer picks a lantern
 * by where it stands: it swings out on its chain and lights, and the lanterns
 * beside it sway a little, staggered from it. At rest one lantern hangs a
 * little swung, lit. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), each part turning on a pivot.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, seg, tdone, tset, tval, tween, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 96, N = 4, PZ = 58, BY = 26, FAV = 2, SWING = 36;
const REST = [-3, 4, 12, -6];
const XS = [18, 38, 58, 78];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-6, -6, 0], [W + 6, 36, 0], [W + 6, -6, 0], [-6, 36, 0], [0, 0, 72], [W, 3, 72]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r, b, parent = g) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(parent); put(s, prism(P, front, o, i, z0, z1)); return s; };
  box(-6, -6, W + 6, 36, 0, 3, 4, 1.6);
  box(0, -2, W, 2, 3, 72, 1.5, 0.8);
  // the door, set in the wall between the second and third lanterns
  mk("path", { d: seg(P(40, 2, 3), P(40, 2, 36)) + seg(P(40, 2, 36), P(56, 2, 36)) + seg(P(56, 2, 36), P(56, 2, 3)), class: "nf lo" }, g);
  box(0, BY - 2, 4, BY + 2, 3, PZ, 1.2, 0.6);
  box(0, BY - 2.5, W, BY + 2.5, PZ, PZ + 4, 1.5, 0.8);

  const rot = (px, k, a) => (x, y, z) => { const dx = x - px, dz = z - PZ, c = Math.cos(a), s = Math.sin(a); return P(px + dx * c + dz * s, y, PZ - dx * s + dz * c); };
  const items = XS.map((x, k) => {
    const grp = mk("g", {}, g), chain = mk("path", { class: "nf lo" }, grp), s = solid(grp);
    return { k, x, chain, s, a: tween(REST[k]), last: NaN };
  });
  g.appendChild(box(W - 4, BY - 2, W, BY + 2, 3, PZ, 1.2, 0.6).g);

  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const R = rot(it.x, it.k, rad(deg)), x = it.x, h = 5, pts = [];
    for (const z of [33, 49]) for (const [u, v] of [[-h, -h], [h, -h], [h, h], [-h, h]]) pts.push(R(x + u, BY + v, z));
    for (const [u, v] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) pts.push(R(x + u, BY + v, 52.5));
    for (const [u, v] of [[-3, -3], [3, -3], [3, 3], [-3, 3]]) pts.push(R(x + u, BY + v, 31));
    it.s.sil.setAttribute("d", poly(hull(pts)));
    it.s.cr.setAttribute("d", poly([R(x - 3, BY + h, 36), R(x + 3, BY + h, 36), R(x + 3, BY + h, 47), R(x - 3, BY + h, 47)]) + " " + poly([R(x + h, BY - 3, 36), R(x + h, BY + 3, 36), R(x + h, BY + 3, 47), R(x + h, BY - 3, 47)]));
    it.chain.setAttribute("d", seg(R(x, BY, PZ), R(x, BY, 52.5)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = XS.map((x) => P(x, BY, 45));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 20 && Math.abs(mids[best][1] - sy) < 40 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), d = a < 0 ? REST[k] : dd === 0 ? SWING : dd === 1 ? (k < a ? -10 : 12) : 0;
      tset(it.a, d, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "lamp " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "porchlights",
  means: "Four lanterns on a porch beam: the one under the pointer swings out on its chain and lights, its neighbours sway a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[143, 139], [199, 166], [226, 180], null],
  mount,
});

campfire.code:
/**
 * Campfire: a ring of stones round two crossed logs, five flames standing
 * on the logs. The pointer picks a flame by where it stands on the fire: it
 * leaps up, and the flames beside it rise a little, staggered from it. At
 * rest the flames stand at uneven heights, the tallest bright. The slider is
 * the stagger.
 *
 * The pattern: one of many on the ground (terrain), picked by world position.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const FZ = 11, FAV = 2, TALL = 44;
const FL = [[-8, -6], [6, -8], [0, 0], [-6, 8], [8, 6]];
const REST = [13, 17, 26, 15, 10];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.4);
  fit(C, [[-32, -32, 0], [32, 32, 0], [32, -32, 0], [-32, 32, 0], [0, 0, FZ + TALL]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const stones = [];
  for (let i = 0; i < 9; i++) { const a = (i / 9) * Math.PI * 2 + 0.3; stones.push([27 * Math.cos(a), 27 * Math.sin(a), 4 + (i % 3)]); }
  stones.sort((a, b) => a[0] + a[1] - b[0] - b[1]);
  const stone = ([x, y, r]) => put(solid(g), prism(P, front, disc(x, y, r), disc(x, y, r - 1.2), 0, 3 + r * 0.5));
  stones.filter((s) => s[0] + s[1] < 0).forEach(stone);
  const [lr, li] = rings(-22, -3, 22, 3, 3, 1);
  put(solid(g), prism(P, front, lr, li, 0, 6));
  const [mr, mi] = rings(-3, -22, 3, 22, 3, 1);
  put(solid(g), prism(P, front, mr, mi, 5, 11));

  const order = FL.map((f, k) => k).sort((a, b) => FL[a][0] + FL[a][1] - FL[b][0] - FL[b][1]);
  const items = [];
  for (const k of order) items[k] = { k, s: solid(g), h: tween(REST[k]), last: NaN };
  stones.filter((s) => s[0] + s[1] >= 0).forEach(stone);

  function draw(it, h) {
    if (h === it.last) return;
    it.last = h;
    const [x, y] = FL[it.k];
    const pts = ringAt(P, disc(x, y, 5), FZ).concat(ringAt(P, disc(x + 0.5, y, 4.2), FZ + h * 0.35), ringAt(P, disc(x + 1, y, 0.8, 8), FZ + h));
    it.s.sil.setAttribute("d", poly(hull(pts)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.h, now)); if (!tdone(it.h, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, FZ);
    let best = -1, bd = Infinity;
    FL.forEach(([x, y], k) => { const dd = Math.hypot(x - wx, y - wy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 9 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = a < 0 ? 0 : Math.hypot(FL[k][0] - FL[a][0], FL[k][1] - FL[a][1]);
      const h = a < 0 ? REST[k] : k === a ? TALL : Math.max(8, 22 - dd);
      const df = from < 0 ? 0 : Math.hypot(FL[k][0] - FL[from][0], FL[k][1] - FL[from][1]) / 10;
      tset(it.h, h, now, df * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "flame " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "campfire",
  means: "Five flames on crossed logs in a stone ring: the flame under the pointer leaps up, and the ones beside it rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[195, 159], [234, 174], [205, 193], null],
  mount,
});

gavel.code:
/**
 * Gavel: a round sound block with a gavel held above it, a barrel head on a
 * long handle. The pointer near the block raises the gavel, higher the
 * closer it comes, ready to strike; leaving lowers it to hover just over
 * the block. The head is the one bright mark. The slider is the reach.
 *
 * The pattern: one part answering the pointer's distance (spring).
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, ringAt, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BR = 18, BZ = 7, HR = 6, HL2 = 12, ARM = 40, REST = 4, TOP = 30;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 4);
  fit(C, [[-BR, -BR, 0], [BR, BR, 0], [ARM, 0, BZ + HR + TOP + 2], [0, -HL2, BZ + 2 * HR + TOP], [0, HL2, BZ]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(BR, 40), circ(BR - 2.5, 40), 0, BZ));
  const head = mk("path", { class: "sil hi" }, g), cap = mk("path", { class: "nf lo" }, g), handle = mk("path", { class: "sil" }, g);
  const sp = spring(REST);
  let last = NaN;

  const discX = (x, y, z, r, n = 24) => { const o = []; for (let i = 0; i < n; i++) { const t = (i / n) * 2 * Math.PI; o.push(P(x + r * Math.cos(t), y, z + r * Math.sin(t))); } return o; };
  const discY = (x, y, z, r, n = 16) => { const o = []; for (let i = 0; i < n; i++) { const t = (i / n) * 2 * Math.PI; o.push(P(x, y + r * Math.cos(t), z + r * Math.sin(t))); } return o; };
  function draw(lift) {
    if (lift === last) return;
    last = lift;
    const hz = BZ + HR + 0.6 + lift;
    head.setAttribute("d", poly(hull(discX(0, -HL2, hz, HR).concat(discX(0, HL2, hz, HR)))));
    cap.setAttribute("d", poly(discX(0, HL2 - 1.6, hz, HR - 1)));
    handle.setAttribute("d", poly(hull(discY(HR - 0.5, 0, hz, 1.8).concat(discY(ARM, 0, hz + lift * 0.15, 2.2)))));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [u, v] = unproj(C, sx, sy, 0), d = Math.hypot(u - 8, v);
    const near = clamp(1 - d / (40 + reach), 0, 1);
    sp.t = REST + (TOP - REST) * near;
    read.textContent = near > 0 ? "up " + Math.round(near * 100) : "rest";
    B.wake();
  }
  function leave() { sp.t = REST; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  draw(REST);
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = clamp(v, 0, 60); }, destroy: bag.dispose };
}

