pencilcase.code:
/**
 * Pencil case: a hard case with three pens laid in its tray and a lid hinged
 * along the back. At rest the lid stands a little open, bright; the pointer
 * over the case lifts it all the way to show the pens. The slider is how far
 * the lid opens.
 *
 * The pattern: one part on a hinge (lid).
 */
const {
  Cam, fit, hull, poly, prism, proj, rings, rrect, clamp, rad, tdone, tset, tval, tween, facing,
  disposer, mk, pointer, put, register, solid,
} = HL;

const LEN = 120, D = 40, ZT = 12, T = 6, REST = 18;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[0, 0, 0], [LEN, 0, 0], [LEN, D, 0], [0, D, 0], [0, -10, ZT + D + 4], [LEN, -10, ZT + D + 4]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(0, 0, LEN, D, 10, 2);
  put(solid(g), prism(P, front, tr, ti, 0, ZT));
  mk("path", { d: poly(rrect(4, 4, LEN - 4, D - 4, 7, 4).map((q) => P(q.u, q.v, ZT))), class: "nf lo" }, g);
  for (const [x0, x1, y] of [[12, 96, 8], [18, 104, 17], [10, 88, 26]]) {
    const [a, i] = rings(x0, y, x1, y + 6, 3, 0.8);
    put(solid(g), prism(P, front, a, i, ZT, ZT + 4));
  }
  // the lid: a slab turning about the back edge of the tray
  const lid = solid(g);
  const outer = rrect(0, 0, LEN, D, 10, 4), inner = rrect(2, 2, LEN - 2, D - 2, 8, 4);
  const at = (ring, h, a) => ring.map((q) => P(q.u, q.v * Math.cos(rad(a)) - h * Math.sin(rad(a)), ZT + 0.5 + q.v * Math.sin(rad(a)) + h * Math.cos(rad(a))));
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    lid.sil.setAttribute("d", poly(hull(at(outer, 0, a).concat(at(outer, T, a)))));
    lid.cr.setAttribute("d", poly(at(inner, a < 39 ? T : 0, a)));
  }
  lid.cr.setAttribute("class", "nf lo");
  lid.sil.classList.add("hi");
  const ang = tween(REST);
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  // hit: the closed case's silhouette, which never moves
  const shape = hull([0, LEN].flatMap((x) => [0, D].flatMap((y) => [P(x, y, 0), P(x, y, ZT + T)])));
  const inside = ([sx, sy]) => [1, -1].some((s) => shape.every((a, i) => { const b = shape[(i + 1) % shape.length]; return s * ((b[0] - a[0]) * (sy - a[1]) - (b[1] - a[1]) * (sx - a[0])) >= 0; }));
  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(ang, v ? clamp(reach, 30, 100) : REST, performance.now(), 0);
    read.textContent = v ? "open" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(inside(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (on) { tset(ang, clamp(v, 30, 100), performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "pencilcase",
  means: "A hard pencil case with pens in its tray: the pointer over it lifts the lid on its back hinge.",
  rules: [1, 4, 5, 6],
  range: [40, 75, 100],
  tour: [[194, 199], [130, 190], [265, 225], null],
  mount,
});

massagetable.code:
/**
 * Massage table: a padded top on four legs, the head end a hinged section
 * with a face cradle. The pointer raises the head section: the further
 * along the table it stands, the steeper the section tilts on its spring.
 * At rest the section leans up a little, bright. The slider is the steepest
 * tilt it can reach.
 *
 * The pattern: one part answering where the pointer stands (terrain).
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rings, rrect, unproj, rad,
  disposer, mk, pointer, put, register, solid, spring, stepS,
} = HL;

const L = 96, HL_ = 44, W = 40, Z = 30, T = 6, REST = 12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let most = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[0, 0, 0], [L + HL_, W, 0], [L + HL_, 0, 0], [0, W, 0], [0, 0, Z + T], [L + 20, W, Z + 40]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // legs, back to front, then a stretcher between each pair
  for (const [x, y] of [[6, 6], [L - 10, 6], [6, W - 10], [L - 10, W - 10]].sort((a, b) => a[0] + a[1] - b[0] - b[1])) {
    const [lr, li] = rings(x, y, x + 4, y + 4, 2, 0.6);
    put(solid(g), prism(P, front, lr, li, 0, Z));
  }
  // the body pad
  const [br, bi] = rings(0, 0, L, W, 6, 1.6);
  put(solid(g), prism(P, front, br, bi, Z, Z + T));
  mk("path", { d: "M" + P(L * 0.5, 1.5, Z + T).join(",") + "L" + P(L * 0.5, W - 1.5, Z + T).join(","), class: "nf lo" }, g);
  // the head section, hinged at x = L
  const sec = solid(g), hole = mk("path", { class: "nf lo" }, g);
  sec.sil.classList.add("hi");
  const ring = rrect(1, 0, HL_, W, 6, 6), inner = rrect(2.6, 1.6, HL_ - 1.6, W - 1.6, 4.5, 6), cradle = rrect(HL_ - 18, W / 2 - 6, HL_ - 7, W / 2 + 6, 5, 6);
  const at = (u, v, n, a) => P(L + u * Math.cos(a) - n * Math.sin(a), v, Z + u * Math.sin(a) + n * Math.cos(a));
  const sp = spring(REST);
  let last = NaN;
  function draw(deg) {
    if (Math.abs(deg - last) < 0.01) return;
    last = deg;
    const a = rad(deg);
    const pts = ring.map((q) => at(q.u, q.v, 0, a)).concat(ring.map((q) => at(q.u, q.v, T, a)));
    sec.sil.setAttribute("d", poly(hull(pts)));
    sec.cr.setAttribute("d", poly(inner.map((q) => at(q.u, q.v, T, a))));
    hole.setAttribute("d", poly(cradle.map((q) => at(q.u, q.v, T, a))));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  draw(REST);

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, Z);
    if (x < -20 || x > L + HL_ + 20 || y < -30 || y > W + 30) return leave();
    const u = clamp(x / (L + HL_), 0, 1);
    sp.t = clamp(REST + (most - REST) * u, 0, 45);
    read.textContent = Math.round(sp.t) + "°";
    B.wake();
  }
  function leave() { sp.t = REST; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { most = v; }, destroy: bag.dispose };
}

hairline({
  name: "massagetable",
  means: "A massage table with a hinged head section: the pointer tilts the section up, steeper the further along the table it stands.",
  rules: [1, 3, 5, 6],
  range: [20, 38, 45],
  tour: [[160, 110], [230, 150], [274, 174], null],
  mount,
});

oxygentanks.code:
/**
 * Oxygen tanks: four tall cylinders standing in a low rack, each with a
 * rounded shoulder, a valve and a round gauge. The pointer picks a tank by
 * where it stands: it lifts out of the rack, and the tanks beside it rise a
 * little, staggered from it. At rest one tank stands raised, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 30, R = 12, H = 70, LIFT = 22, FAV = 2, RZ = 10;
const X1 = (N - 1) * STEP + 2 * R;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.7);
  fit(C, [[-6, -6, 0], [X1 + 6, 2 * R + 6, 0], [X1 + 6, -6, 0], [-6, 2 * R + 6, 0], [R, R, H + LIFT + 14], [X1 - R, R, H + LIFT + 14]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-6, -6, X1 + 6, 2 * R + 6, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, 3));
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = R + k * STEP, y = R, grp = mk("g", {}, g);
    const body = mk("path", { class: "sil" }, grp), band = mk("path", { class: "nf lo" }, grp);
    const valve = mk("path", {}, grp), gauge = mk("path", {}, grp);
    items.push({ k, x, y, body, band, valve, gauge, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }
  // the rack's front rail, over the tanks' feet
  const [fr, fi] = rings(-6, 2 * R - 2, X1 + 6, 2 * R + 6, 3, 1);
  put(solid(g), prism(P, front, fr, fi, 3, RZ));

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = 3 + lift, pts = ringAt(P, disc(it.x, it.y, R), z0);
    for (let i = 0; i <= 5; i++) { const t = (i / 5) * (Math.PI / 2); pts.push(...ringAt(P, disc(it.x, it.y, Math.max(3, R * Math.cos(t))), z0 + H - R + R * Math.sin(t))); }
    it.body.setAttribute("d", poly(hull(pts)));
    it.band.setAttribute("d", open(ringAt(P, run(disc(it.x, it.y, R), front), z0 + H - R - 6)));
    const v0 = z0 + H;
    it.valve.setAttribute("d", poly(hull(ringAt(P, disc(it.x, it.y, 3, 16), v0 - 1).concat(ringAt(P, disc(it.x, it.y, 3, 16), v0 + 7)))));
    const c = [];
    for (let i = 0; i < 20; i++) { const a = (i / 20) * Math.PI * 2; c.push(P(it.x + 3.5 * Math.cos(a), it.y + 7 + 3.5 * Math.cos(a), v0 + 5 + 4 * Math.sin(a))); }
    it.gauge.setAttribute("d", poly(hull(c)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tank " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "oxygentanks",
  means: "Four oxygen tanks in a rack: the tank under the pointer lifts out with its valve and gauge, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[146, 155], [200, 185], [254, 215], null],
  mount,
});

eyedrops.code:
/**
 * Eye drops: five small squeeze bottles in a tray, each with a shoulder and
 * a tapered dropper tip. The pointer picks a bottle by where it stands: it
 * lifts out of the tray, and the bottles beside it rise a little, staggered
 * from it. At rest one bottle stands raised, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 20, R = 8, H = 30, LIFT = 18, FAV = 1, RZ = 6;
const X1 = (N - 1) * STEP + 2 * R;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-6, -6, 0], [X1 + 6, 2 * R + 6, 0], [X1 + 6, -6, 0], [-6, 2 * R + 6, 0], [R, R, H + LIFT + 16], [X1 - R, R, H + LIFT + 16]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-6, -6, X1 + 6, 2 * R + 6, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, 3));
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = R + k * STEP, y = R, grp = mk("g", {}, g);
    const body = mk("path", { class: "sil" }, grp), band = mk("path", { class: "nf lo" }, grp);
    const valve = mk("path", {}, grp), gauge = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, y, body, band, valve, gauge, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }
  // the rack's front rail, over the tanks' feet
  const [fr, fi] = rings(-6, 2 * R - 2, X1 + 6, 2 * R + 6, 3, 1);
  put(solid(g), prism(P, front, fr, fi, 3, RZ));

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = 3 + lift, pts = ringAt(P, disc(it.x, it.y, R), z0);
    for (let i = 0; i <= 5; i++) { const t = (i / 5) * (Math.PI / 2); pts.push(...ringAt(P, disc(it.x, it.y, Math.max(3.2, R * Math.cos(t))), z0 + H - R + R * Math.sin(t))); }
    it.body.setAttribute("d", poly(hull(pts)));
    it.band.setAttribute("d", open(ringAt(P, run(disc(it.x, it.y, R), front), z0 + H * 0.35)));
    const v0 = z0 + H - 2;
    it.valve.setAttribute("d", poly(hull(ringAt(P, disc(it.x, it.y, 3.2, 16), v0).concat(ringAt(P, disc(it.x, it.y, 0.8, 12), v0 + 11)))));
    it.gauge.setAttribute("d", open(ringAt(P, run(disc(it.x, it.y, 3.2, 16), front), v0 + 2.5)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 18 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "no. " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "eyedrops",
  means: "Five eye drop bottles in a tray: the bottle under the pointer lifts out by its dropper tip, and its neighbours rise a little.",
