pancakestack.code:
/**
 * Pancake stack: five pancakes on a plate, a pat of butter on top. The
 * pointer picks a pancake by its height in the stack: everything above it
 * lifts clear, staggered outward from it, so the cut shows. At rest the stack
 * leans a little and the top pancake is bright. The slider is the stagger.
 *
 * The pattern: one of many in a single column, picked by rest height.
 */
const {
  Cam, circ, fit, facing, proj, prism, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, R = 26, TH = 4.6, PZ = 2.4, LIFT = 16, CX = 0, CY = 0;
const OFF = [[0, 0], [1.6, -1], [-1.2, 1.4], [1.8, 1.2], [-0.6, -1.6]];
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.1);
  const top = PZ + N * TH + LIFT + 6;
  fit(C, [[-40, -40, 0], [40, 40, 0], [40, -40, 0], [-40, 40, 0], [0, 0, top]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the plate: a wide disc with a rim crease
  put(solid(g), prism(P, front, disc(CX, CY, 38, 48), disc(CX, CY, 30, 48), 0, PZ));

  const cakes = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g), s = solid(grp);
    cakes.push({ k, s, x: CX + OFF[k][0], y: CY + OFF[k][1], z0: PZ + k * TH, lift: tween(0), last: NaN });
  }
  // the butter rides on the top pancake
  const bs = solid(cakes[N - 1].s.g);
  const butter = (z) => { const [a, b] = [rrect(-6, -5, 6, 5, 1.6, 4), rrect(-5, -4, 5, 4, 1, 4)]; put(bs, prism(P, front, a, b, z, z + 3)); };

  function draw(c, l) {
    if (l === c.last) return;
    c.last = l;
    const z = c.z0 + l;
    put(c.s, prism(P, front, disc(c.x, c.y, R - (c.k % 2) * 0.8), disc(c.x, c.y, R - 2.4), z, z + TH - 0.3));
    if (c.k === N - 1) butter(z + TH - 0.3);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const c of cakes) { draw(c, tval(c.lift, now)); if (!tdone(c.lift, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  // hit: the pointer's screen y against each pancake's rest middle
  const mids = cakes.map((c) => P(c.x, c.y, c.z0 + TH / 2));
  const axis = P(CX, CY, 0)[0];
  function hit([sx, sy]) {
    if (Math.abs(sx - axis) > R * 2.6) return -1;
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[1] - sy); if (d < bd) { bd = d; best = k; } });
    return bd < 26 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    cakes.forEach((c, k) => {
      const l = a < 0 ? (k === N - 1 ? 4 : 0) : k > a ? LIFT * (0.7 + 0.3 * Math.min(1, (k - a) / 2)) : 0;
      tset(c.lift, l, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      c.s.sil.classList.toggle("hi", k === (a < 0 ? N - 1 : a));
    });
    read.textContent = a < 0 ? "rest" : "cake " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "pancakestack",
  means: "Five pancakes on a plate: the one under the pointer stays put and everything above it lifts clear, so the stack opens there.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[200, 175], [200, 149], [200, 121], null],
  mount,
});

burgerstack.code:
/**
 * Burger: a bun, patty, cheese, lettuce, tomato and a domed top bun on a
 * board. The pointer picks a layer by its height: that layer slides out
 * toward the viewer, and the layers next to it follow a little, staggered
 * from it. At rest the cheese sticks out, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single column, picked by rest height.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, ringAt, rings, rrect, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SL = 15, FAV = 2;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const wavy = (x, y, r) => circ(r, 64).map((q, i) => { const k = 1 + 0.07 * Math.sin(i * Math.PI / 4); return { ...q, u: x + q.nu * r * k, v: y + q.nv * r * k }; });
// [name, thickness, ring(dx, dy), inner(dx, dy)]
const LAYERS = [
  ["bun", 7, (x, y) => disc(x, y, 24), (x, y) => disc(x, y, 22)],
  ["patty", 6, (x, y) => disc(x, y, 25.5), (x, y) => disc(x, y, 23.5)],
  ["cheese", 1.6, (x, y) => rrect(x - 22, y - 22, x + 22, y + 22, 1.5, 4), (x, y) => rrect(x - 21, y - 21, x + 21, y + 21, 0.8, 4)],
  ["leaf", 1.8, (x, y) => wavy(x, y, 26), (x, y) => disc(x, y, 23)],
  ["tomato", 2.8, (x, y) => disc(x, y, 21), (x, y) => disc(x, y, 18)],
  ["top", 0, null, null],
];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.0);
  const H = 4 + LAYERS.reduce((s, l) => s + l[1], 0) + 18;
  fit(C, [[-36, -36, 0], [36 + SL, 36 + SL, 0], [36, -36, 0], [-36, 36, 0], [0, 0, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-36, -36, 36, 36, 10, 2);
  put(solid(g), prism(P, front, br, bi, 0, 4));

  let z = 4;
  const items = LAYERS.map(([name, th, ring, inner], k) => {
    const it = { k, name, th, ring, inner, z0: z, s: solid(mk("g", {}, g)), off: tween(0), last: NaN };
    z += th;
    return it;
  });

  function draw(it, o) {
    if (o === it.last) return;
    it.last = o;
    const d = o / Math.SQRT2;
    if (it.ring) { put(it.s, prism(P, front, it.ring(d, d), it.inner(d, d), it.z0, it.z0 + it.th)); return; }
    // the top bun: a dome over a short wall
    const base = it.z0, pts = [];
    for (let i = 0; i <= 7; i++) { const t = (i / 7) * (Math.PI / 2); pts.push(...ringAt(P, disc(d, d, 24 * Math.cos(t), 32), base + 3 + 15 * Math.sin(t))); }
    pts.push(...ringAt(P, disc(d, d, 24, 32), base));
    put(it.s, { sil: poly(hull(pts)), crease: open(ringAt(P, run(disc(d, d, 23, 40), front), base + 3)) });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.off, now)); if (!tdone(it.off, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  // hit: the pointer's screen y against each layer's rest middle
  const mids = items.map((it) => P(0, 0, it.z0 + (it.th || 9) / 2));
  const axis = P(0, 0, 0)[0];
  function hit([sx, sy]) {
    if (Math.abs(sx - axis) > 80) return -1;
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[1] - sy); if (d < bd) { bd = d; best = k; } });
    return bd < 24 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), o = a < 0 ? (k === FAV ? 6 : 0) : dd === 0 ? SL : dd === 1 ? 3 : 0;
      tset(it.off, o, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : items[a].name;
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "burgerstack",
  means: "A burger on a board, layer by layer: the layer under the pointer slides out toward you, and the ones beside it follow a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[200, 150], [200, 126], [200, 87], null],
  mount,
});

souppots.code:
/**
 * Soup pots: three pots of different sizes on a stove top, each with a lid
 * and a knob. The pointer picks a pot by where it stands: its lid tips open
 * on its back rim, and the lids beside it crack open a little, staggered
 * from it. At rest the middle lid sits ajar, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), with a hinged lid.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SZ = 6, POTS = [[30, 18, 20], [80, 22, 26], [128, 16, 17]], FAV = 1, OPEN = 64;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, -6, 0], [152, 52, 0], [152, -6, 0], [0, 52, 0], [58, 23, SZ + 26 + 50], [146, 23, SZ + 17 + 34]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(0, -6, 152, 52, 8, 2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));
  // burner rings on the stove top, behind the pots
  for (const [x, r] of POTS) mk("path", { d: poly(disc(x, 23, r + 4, 40).map((q) => P(q.u, q.v, SZ))), class: "nf lo" }, g);

  const items = POTS.map(([x, r, h], k) => {
    const grp = mk("g", {}, g), y = 23, z1 = SZ + h;
    const hd = (s) => { const [a, b] = rings(x - 3, s < 0 ? y - r - 4 : y + r - 1, x + 3, s < 0 ? y - r + 1 : y + r + 4, 1.5, 0.6); return prism(P, front, a, b, z1 - 6, z1 - 3.5); };
    put(solid(grp), hd(-1));
    put(solid(grp), prism(P, front, disc(x, y, r), disc(x, y, r - 1.6), SZ, z1));
    put(solid(grp), hd(1));
    const lid = mk("path", { class: "sil" }, grp), knob = mk("path", { class: "nf" }, grp);
    return { k, x, y, r, z1, lid, knob, a: tween(k === FAV ? 18 : 0), last: NaN };
  });

  // the lid hinges on its back rim (smallest x): sample (u, v) rotates up by deg
  function lidPts(it, deg, ring, dz) {
    const c = Math.cos(deg * Math.PI / 180), s = Math.sin(deg * Math.PI / 180);
    return ring.map((q) => { const du = q.u - (it.x - it.r); return P(it.x - it.r + du * c - dz * s, q.v, it.z1 + du * s + dz * c); });
  }
  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const rim = disc(it.x, it.y, it.r + 1, 40);
    it.lid.setAttribute("d", poly(hull(lidPts(it, deg, rim, 0).concat(lidPts(it, deg, rim, 1.6), lidPts(it, deg, disc(it.x, it.y, it.r * 0.7, 32), 3.4)))));
    const kb = disc(it.x, it.y, 2.6, 16);
    it.knob.setAttribute("d", poly(hull(lidPts(it, deg, kb, 3.4).concat(lidPts(it, deg, kb, 6.4)))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, it.z1 / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 50 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), deg = a < 0 ? (k === FAV ? 18 : 0) : dd === 0 ? OPEN : dd === 1 ? 10 : 0;
      tset(it.a, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.lid.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "pot " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "souppots",
  means: "Three soup pots on a stove: the lid of the pot under the pointer tips open on its back rim, and the lids beside it crack open.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[137, 152], [206, 178], [272, 211], null],
  mount,
});

mixerbowl.code:
/**
 * Stand mixer: a tilt-head mixer on its base, a bowl in front and a balloon
 * whisk hanging from the head into it. The pointer's height tilts the head
 * back on its hinge, lifting the whisk out of the bowl. At rest the head sits
 * almost closed and the speed dot is bright. The slider is the furthest tilt.
 *
 * The pattern: one part hinged, following the pointer (swing).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, rrect, seg, clamp, rad, spring, stepS,
  disposer, mk, place, pointer, put, register, solid,
} = HL;

const HX = 6, HZ = 48, REST = 5, BX = 40, BY = 18;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxT = value;
  const C = Cam(45, 0.5, 2.7);
  const rot = (x, y, z, a) => { const dx = x - HX, dz = z - HZ, c = Math.cos(rad(a)), s = Math.sin(rad(a)); return [HX + dx * c - dz * s, y, HZ + dx * s + dz * c]; };
  const ext = [[-2, -2, 0], [66, 38, 0], [66, -2, 0], [-2, 38, 0]];
  for (const [x, z] of [[0, 44], [58, 44], [58, 60], [0, 60]]) for (const y of [10, 26]) ext.push(rot(x, y, z, 60), rot(x, y, z, REST));
  fit(C, ext, 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [br, bi] = rings(0, 0, 64, 36, 9, 2);
  put(solid(g), prism(P, front, br, bi, 0, 6));
  const [cr, ci] = rings(0, 8, 16, 28, 6, 1.5);
  put(solid(g), prism(P, front, cr, ci, 6, 46));
  const speed = mk("circle", { r: 2.4, class: "dot" }, g);
  place(speed, P(16, 18, 30));

  // the whisk: a shaft and a balloon of wires, turning with the head
  const wg = mk("g", {}, g);
  const shaft = mk("path", { class: "nf" }, wg), balloon = mk("path", { class: "nf lo" }, wg), wires = mk("path", { class: "nf lo" }, wg);

  // the bowl: narrow foot, wide rim
  const foot = disc(BX, BY, 9), top = rrect(BX - 16, BY - 16, BX + 16, BY + 16, 16, 10), inner = rrect(BX - 14, BY - 14, BX + 14, BY + 14, 14, 10);
  put(solid(g), { sil: poly(hull(ringAt(P, foot, 6).concat(ringAt(P, top, 28)))), crease: open(ringAt(P, run(inner, front), 28)) });

  // the head, a rounded box that tilts back on its hinge
  const head = solid(g);
  head.sil.classList.add("sil");
  const [hr, hi] = rings(0, 10, 58, 26, 7, 2);

  const tilt = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = [];
    for (const q of hr) for (const z of [44, 58]) pts.push(P(...rot(q.u, q.v, z, a)));
    const crease = run(hi, front).map((q) => P(...rot(q.u, q.v, 58, a)));
    put(head, { sil: poly(hull(pts)), crease: open(crease) });
    const s0 = P(...rot(BX, BY, 44, a)), s1 = P(...rot(BX, BY, 36, a));
    shaft.setAttribute("d", seg(s0, s1));
    const bal = [], wd = [];
    for (let i = 0; i <= 8; i++) {
      const t = i / 8, z = 36 - 22 * t, r = 6 * Math.sin(Math.PI * Math.pow(t, 0.7));
      for (const q of circ(r, 12)) bal.push(P(...rot(BX + q.u, BY + q.v, z, a)));
    }
    balloon.setAttribute("d", poly(hull(bal)));
    for (const k of [-0.5, 0.5]) {
      const w = [];
      for (let i = 0; i <= 8; i++) { const t = i / 8, z = 36 - 22 * t, r = 6 * Math.sin(Math.PI * Math.pow(t, 0.7)); w.push(P(...rot(BX + r * k, BY - r * k, z, a))); }
      wd.push(open(w));
    }
    wires.setAttribute("d", wd.join(" "));
  }

  const B = register(stage, (dt) => { const m = stepS(tilt, dt); draw(tilt.x); return m; });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { tilt.t = REST; speed.setAttribute("class", "dot"); head.sil.classList.remove("hi"); read.textContent = "rest"; B.wake(); return; }
    const f = clamp((250 - p[1]) / 170, 0.08, 1);
    tilt.t = REST + (maxT - REST) * f;
    speed.setAttribute("class", "dot off");
    head.sil.classList.add("hi");
    read.textContent = "tilt " + Math.round(tilt.t) + "°";
    B.wake();
  }
  draw(REST);
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxT = v; }, destroy: bag.dispose };
}

hairline({
  name: "mixerbowl",
  means: "A tilt-head stand mixer: the pointer's height swings the head back on its hinge and lifts the whisk out of the bowl.",
  rules: [1, 3, 5, 8],
  range: [25, 45, 60],
  tour: [[227, 260], [234, 146], [200, 90], null],
  mount,
});

sodafountain.code:
/**
 * Soda fountain: a tower on a counter with four taps along its face, a drip
 * tray under them. The pointer picks a tap by where it stands: its handle
 * pulls forward and a stream drops to the tray; the handles beside it give a
 * little, staggered from it. At rest one tap is half pulled, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, seg, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 24, X0 = 15, PY = 16, PZ = 40, HL_ = 22, PULL = 58, FAV = 1;
const REST = [6, 26, 10, 3];
const disc = (x, y, r, n = 16) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.25);
  const XN = X0 + (N - 1) * STEP + X0;
  fit(C, [[-6, -2, 0], [XN + 6, 40, 0], [XN + 6, -2, 0], [-6, 40, 0], [0, 0, 56], [XN, 0, 56], [X0, PY + HL_, PZ + 24]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [tr, ti] = rings(0, 0, XN, 14, 6, 1.8);
  put(solid(g), prism(P, front, tr, ti, 0, 50));
  const [cr, ci] = rings(-3, -2, XN + 3, 16, 7, 2);
  put(solid(g), prism(P, front, cr, ci, 50, 55));
  const [dr, di] = rings(-4, 14, XN + 4, 38, 5, 2.2);
  put(solid(g), prism(P, front, dr, di, 0, 4));
  for (let k = 0; k < 9; k++) { const x = 6 + k * (XN - 12) / 8; mk("path", { d: seg(P(x, 18, 4), P(x, 34, 4)), class: "nf lo" }, g); }

  const taps = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP, grp = mk("g", {}, g);
    const stream = mk("path", { class: "nf dash" }, grp);
    const [sr, si] = rings(x - 3, 13, x + 3, 25, 2.2, 0.8);
    put(solid(grp), prism(P, front, sr, si, 33, 37.5));
    put(solid(grp), prism(P, front, disc(x, 22.5, 1.8), disc(x, 22.5, 1), 29.5, 33));
    const h = solid(grp);
    h.sil.classList.add("sil");
    taps.push({ k, x, stream, h, a: tween(REST[k]), last: NaN });
  }

  function draw(t, a) {
    if (a === t.last) return;
    t.last = a;
    const s = Math.sin(rad(a)), c = Math.cos(rad(a)), pts = [];
    for (let i = 0; i <= 6; i++) {
      const d = (i / 6) * HL_, r = 1.6 + 1.6 * (i / 6) * (i / 6);
      const ring = ringAt(P, disc(t.x, PY + d * s, r), PZ + d * c);
      pts.push(...ring);
    }
    t.h.sil.setAttribute("d", poly(hull(pts)));
    t.h.cr.setAttribute("d", "");
    t.stream.setAttribute("d", a > 30 ? seg(P(t.x, 22.5, 29), P(t.x, 22.5, 4)) : "");
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const t of taps) { draw(t, tval(t.a, now)); if (!tdone(t.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = taps.map((t) => P(t.x, 14, 34));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    taps.forEach((t, k) => {
      const dd = Math.abs(k - a), to = a < 0 ? REST[k] : dd === 0 ? PULL : dd === 1 ? 16 : 3;
      tset(t.a, to, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      t.h.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tap " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "sodafountain",
  means: "A soda fountain with four taps: the handle under the pointer pulls forward and pours into the tray; its neighbours give a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[172, 120], [218, 130], [250, 150], null],
  mount,
});

bedsidetable.code:
/**
 * Bedside table: a small cabinet with a lamp on top and one drawer. The
 * pointer draws the drawer out toward it: the nearer the pointer comes on
 * the floor in front, the further it slides. At rest the drawer stands a
 * little open and the lamp's shade is bright. The slider is the furthest pull.
 *
 * The pattern: one part following the pointer (slide).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, seg, clamp, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 36, D = 30, H = 50, REST = 5;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxO = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[0, 0, 0], [W, D + 26, 0], [W, 0, 0], [0, D + 26, 0], [W / 2, D / 2, H + 26]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  for (const [x, y] of [[4, 4], [W - 4, 4], [4, D - 4], [W - 4, D - 4]]) put(solid(g), prism(P, front, disc(x, y, 1.8, 12), disc(x, y, 1, 12), 0, 6));
  const [br, bi] = rings(0, 0, W, D, 4, 1.6);
  put(solid(g), prism(P, front, br, bi, 6, H));
  mk("path", { d: seg(P(3, D, 28), P(W - 3, D, 28)), class: "nf lo" }, g);

  // the lamp: a round foot, a stem, a drum shade
  const lx = W / 2 - 3, ly = D / 2 - 3;
  put(solid(g), prism(P, front, disc(lx, ly, 6), disc(lx, ly, 4.6), H, H + 2));
  mk("path", { d: seg(P(lx, ly, H + 2), P(lx, ly, H + 14)), class: "nf" }, g);
  const shade = solid(g);
  shade.sil.classList.add("sil");
  put(shade, { sil: poly(hull(ringAt(P, disc(lx, ly, 10), H + 13).concat(ringAt(P, disc(lx, ly, 6.5), H + 24)))), crease: "" });

  const tray = solid(g), face = solid(g), knob = mk("path", { class: "nf" }, g);
  face.sil.classList.add("sil");
  const out = spring(REST);
  let last = NaN;
  function draw(o) {
    if (o === last) return;
    last = o;
    if (o > 1.2) { const [r, i] = rings(4, D - 1, W - 4, D + o, 1.5, 0.6); put(tray, prism(P, front, r, i, 33, 45)); } else put(tray, { sil: "", crease: "" });
    const [fr, fi] = rings(2, D + o, W - 2, D + o + 2.4, 1, 0.5);
    put(face, prism(P, front, fr, fi, 31, 47));
    knob.setAttribute("d", poly(hull(ringAt(P, disc(W / 2, D + o + 2.4, 1.6, 10), 39).concat(ringAt(P, disc(W / 2, D + o + 4.4, 1.6, 10), 39)))));
  }
  const B = register(stage, (dt) => { const m = stepS(out, dt); draw(out.x); return m; });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { out.t = REST; shade.sil.classList.add("hi"); face.sil.classList.remove("hi"); read.textContent = "rest"; B.wake(); return; }
    const [, wy] = unproj(C, p[0], p[1], 0);
    out.t = clamp(((wy - 8) / 40) * maxO, 0, maxO);
    shade.sil.classList.remove("hi");
    face.sil.classList.add("hi");
    read.textContent = "open " + Math.round((out.t / 22) * 100) + "%";
    B.wake();
  }
  draw(REST);
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxO = v; }, destroy: bag.dispose };
}

hairline({
  name: "bedsidetable",
  means: "A bedside table with a lamp: the drawer slides out toward the pointer, further the nearer it comes.",
  rules: [1, 3, 5, 8],
  range: [10, 16, 22],
  tour: [[200, 160], [180, 230], [160, 280], null],
  mount,
});

fireplace.code:
/**
 * Fireplace: a chimney breast with a mantel shelf and an arched opening,
 * three logs lying on the hearth in front of it. The pointer picks a log
 * by where it stands: it lifts off the hearth, its neighbours rise a little,
 * staggered from it. At rest the middle log is raised, bright. The slider
 * is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, XS = [26, 45, 64], R = 6, LIFT = 20, FAV = 1, HZ = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-8, -4, 0], [98, 64, 0], [98, -4, 80], [-8, 64, 0], [-8, -4, 80]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // chimney breast
  const [br, bi] = rings(0, 0, 90, 30, 3, 1.5);
  put(solid(g), prism(P, front, br, bi, 0, 70));
  // the opening: an arch on the front face, a back line inside it
  const arch = [];
  for (let i = 0; i <= 16; i++) { const a = Math.PI * (i / 16); arch.push(P(45 - 26 * Math.cos(a), 30, 30 + 14 * Math.sin(a))); }
  mk("path", { d: poly([P(19, 30, HZ), ...arch, P(71, 30, HZ)]), class: "nf" }, g);
  mk("path", { d: open([P(23, 30, HZ), P(23, 22, HZ + 2), P(67, 22, HZ + 2), P(67, 30, HZ)]), class: "nf lo" }, g);
  // mantel shelf
  const [mr, mi] = rings(-8, -4, 98, 36, 2, 1);
  put(solid(g), prism(P, front, mr, mi, 70, 75));
  // hearth
  const [hr, hi] = rings(-6, 30, 96, 62, 3, 1.5);
  put(solid(g), prism(P, front, hr, hi, 0, HZ));

  const logs = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    logs.push({ k, x: XS[k], sil: mk("path", { class: "sil" }, grp), end: mk("path", { class: "nf lo" }, grp), ring: mk("path", { class: "nf lo" }, grp), z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN });
  }
  function circleAt(x, y, z, r, n = 28) { const o = []; for (let i = 0; i < n; i++) { const a = (i / n) * Math.PI * 2; o.push(P(x + r * Math.cos(a), y, z + r * Math.sin(a))); } return o; }
  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z = HZ + R + lift, a = circleAt(it.x, 34, z, R), b = circleAt(it.x, 58, z, R);
    it.sil.setAttribute("d", poly(hull(a.concat(b))));
    it.end.setAttribute("d", poly(b));
    it.ring.setAttribute("d", poly(circleAt(it.x, 58, z, R * 0.45, 16)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of logs) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = logs.map((it) => P(it.x, 46, HZ + R));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 22 && Math.abs(mids[best][1] - sy) < 45 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    logs.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : 4;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "log " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "fireplace",
  means: "A fireplace with three logs on the hearth: the log under the pointer lifts off, its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[153, 215], [179, 228], [204, 241], null],
  mount,
});

shoecabinet.code:
/**
 * Shoe cabinet: a slim hallway cabinet with three tip-out flaps stacked on
 * its front, each with a pull, a dim slot behind it. The pointer picks a
 * flap by height: it tips open on its bottom hinge, the flaps beside it
 * crack open a little, staggered from it. At rest the middle flap stands
 * ajar, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single column (riffle).
 */
const {
  Cam, fit, facing, fillet, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, Y1 = 28, H = 24, OPEN = 42, FAV = 1;
const Z0 = (k) => 6 + (N - 1 - k) * 26; // k 0 is the top flap

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, 0, 0], [80, Y1 + 18, 0], [80, 0, 88], [0, Y1 + 18, 0], [0, 0, 88]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, 80, Y1, 3, 1.5);
  put(solid(g), prism(P, front, br, bi, 2, 84));
  const [fr, fi] = rings(0, 0, 80, Y1, 3, 1.2);
  put(solid(g), prism(P, front, fr, fi, 84, 88));
  for (const fx of [5, 75]) { const [r, i] = rings(fx - 2, Y1 - 6, fx + 2, Y1 - 2, 1.5, 0.6); put(solid(g), prism(P, front, r, i, 0, 2)); }

  const flaps = [];
  for (let k = N - 1; k >= 0; k--) {
    const z0 = Z0(k), grp = mk("g", {}, g);
    mk("path", { d: poly(fillet([P(5, Y1, z0 + 1), P(75, Y1, z0 + 1), P(75, Y1, z0 + H - 1), P(5, Y1, z0 + H - 1)], [2, 2, 2, 2])), class: "nf lo" }, grp);
    flaps[k] = { k, z0, plate: mk("path", { class: "sil" }, grp), pull: mk("path", { class: "nf lo" }, grp), a: tween(k === FAV ? 16 : 0), last: NaN };
  }
  function draw(f, deg) {
    if (deg === f.last) return;
    f.last = deg;
    const t = (deg * Math.PI) / 180, F = (x, s) => P(x, Y1 + 0.5 + s * Math.sin(t), f.z0 + s * Math.cos(t));
    f.plate.setAttribute("d", poly(fillet([F(4, 0), F(76, 0), F(76, H), F(4, H)], [2, 2, 2.5, 2.5])));
    f.pull.setAttribute("d", seg(F(32, H - 4), F(48, H - 4)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const f of flaps) { draw(f, tval(f.a, now)); if (!tdone(f.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = flaps.map((f) => P(40, Y1, f.z0 + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && Math.abs(mids[best][0] - sx) < 75 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    flaps.forEach((f, k) => {
      const dd = Math.abs(k - a), deg = a < 0 ? (k === FAV ? 16 : 0) : dd === 0 ? OPEN : dd === 1 ? 7 : 0;
      tset(f.a, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      f.plate.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "flap " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "shoecabinet",
  means: "A shoe cabinet with three tip-out flaps: the flap under the pointer tips open, the ones beside it crack open a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[193, 126], [193, 169], [193, 213], null],
  mount,
});

armchair.code:
/**
 * Armchair: a boxy armchair on four short feet, with a loose seat cushion
 * and a loose back cushion. The pointer picks a cushion by where it lies:
 * it lifts out of the chair, and the other one rises a little, staggered
 * from it. At rest the seat cushion sits slightly proud, bright. The slider
 * is the stagger.
 *
 * The pattern: two parts at different heights, picked by rest pose.
 */
const {
  Cam, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const LIFT = 20, FAV = 0;
// cushions: [x0, y0, x1, y1, z0, z1, name]
const CU = [[11, 13, 49, 55, 22, 30, "seat"], [11, 12, 49, 21, 30, 56, "back"]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[0, 0, 0], [60, 58, 0], [60, 0, 60 + LIFT], [0, 58, 0], [0, 0, 62]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r = 3, b = 1.4, cls) => { const s = solid(g); put(s, prism(P, front, ...rings(x0, y0, x1, y1, r, b), z0, z1)); if (cls) s.sil.classList.add(cls); return s; };
  for (const [fx, fy] of [[4, 4], [56, 4], [4, 52], [56, 52]]) box(fx - 2, fy - 2, fx + 2, fy + 2, 0, 4, 1.5, 0.6);
  box(0, 0, 60, 56, 4, 22, 4, 1.6);
  box(0, 0, 60, 12, 4, 60, 4, 1.6);
  box(0, 0, 10, 56, 4, 38, 4, 1.6);
  const cg = mk("g", {}, g), rightArm = mk("g", {}, g);
  { const s = solid(rightArm); put(s, prism(P, front, ...rings(50, 0, 60, 56, 4, 1.6), 4, 38)); }

  const cush = CU.map(([x0, y0, x1, y1, z0, z1, name], k) => {
    const s = solid(mk("g", {}, cg));
    return { k, x0, y0, x1, y1, z0, z1, name, s, z: tween(k === FAV ? 6 : 0), last: NaN };
  });
  // the back cushion is farther: paint it first
  cg.prepend(cush[1].s.g.parentNode);
  function draw(c, lift) {
    if (lift === c.last) return;
    c.last = lift;
    put(c.s, prism(P, front, ...rings(c.x0, c.y0, c.x1, c.y1, 4, 1.8), c.z0 + lift, c.z1 + lift));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const c of cush) { draw(c, tval(c.z, now)); if (!tdone(c.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = cush.map((c) => P((c.x0 + c.x1) / 2, (c.y0 + c.y1) / 2, (c.z0 + c.z1) / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 48 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    cush.forEach((c, k) => {
      const z = a < 0 ? (k === FAV ? 6 : 0) : k === a ? LIFT : 4;
      tset(c.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      c.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : cush[a].name;
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "armchair",
  means: "An armchair with loose cushions: the cushion under the pointer lifts out of the chair, the other rises a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[192, 181], [222, 130], [156, 131], null],
  mount,
});

mirrorstand.code:
/**
 * Floor mirror: a cheval mirror, its framed glass hung between two posts on
 * long feet, pivoting on a pin at mid-height. The pointer's height sets the
 * tilt: above the pin the glass tips back, below it tips forward, clamped,
 * on a spring. At rest the glass leans back a little, its frame bright.
 * The slider is the reach of the tilt.
 *
 * The pattern: one part following the pointer (aim).
 */
const {
  Cam, clamp, fit, facing, fillet, poly, prism, proj, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PY = 10, PZ = 48, HH = 34, X0 = 5, X1 = 47, REST = 8;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-2, -4, 0], [54, 24, 0], [54, -4, 84], [-2, 24, 0], [-2, -4, 84]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const post = (x, parent) => {
    put(solid(parent), prism(P, front, ...rings(x - 2.5, -4, x + 2.5, 24, 2, 0.8), 0, 3));
    put(solid(parent), prism(P, front, ...rings(x - 2, PY - 2, x + 2, PY + 2, 1.6, 0.6), 3, 84));
  };
  post(0, g);
  const mg = mk("g", {}, g);
  const frame = mk("path", { class: "sil hi" }, mg), glass = mk("path", { class: "nf lo" }, mg);
  post(52, mk("g", {}, g));

  const tilt = spring(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const t = (deg * Math.PI) / 180, F = (x, s) => P(x, PY + s * Math.sin(t), PZ + s * Math.cos(t));
    frame.setAttribute("d", poly(fillet([F(X0, -HH), F(X1, -HH), F(X1, HH), F(X0, HH)], [4, 4, 4, 4])));
    glass.setAttribute("d", poly(fillet([F(X0 + 4, -HH + 4), F(X1 - 4, -HH + 4), F(X1 - 4, HH - 4), F(X0 + 4, HH - 4)], [2.5, 2.5, 2.5, 2.5])));
  }

  const B = register(stage, (dt) => { const m = stepS(tilt, dt); draw(tilt.x); return m; });
  bag.add(B.unregister);

  const pin = P(26, PY, PZ);
  function aim([sx, sy]) {
    if (Math.abs(sx - pin[0]) > 110) return leave();
    const deg = Math.round(clamp(((pin[1] - sy) / 70) * reach, -reach, reach));
    tilt.t = deg;
    read.textContent = "tilt " + (deg > 0 ? "+" : "") + deg + "°";
    B.wake();
  }
  function leave() { tilt.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

