  mount,
});

deskorganizer.code:
/**
 * Desk organiser: a low tray with four cups of different heights, each cup
 * holding pens. The pointer picks a cup by where it stands: its pens lift
 * out, and the pens of the cups beside it rise a little, staggered from it.
 * At rest one cup's pens stand raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 30, W = 13, D = 26, LIFT = 26, FAV = 2, TZ = 4;
const HS = [30, 20, 38, 24];
const X1 = (N - 1) * STEP + 2 * W + 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-4, -4, 0], [X1 + 4, D + 8, 0], [X1 + 4, -4, 0], [-4, D + 8, 0], [STEP * 2 + W + 3, D / 2, TZ + 38 + 20 + LIFT], [W + 3, D / 2, TZ + 30 + 20 + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(-4, -4, X1 + 4, D + 8, 5, 1.6);
  put(solid(g), prism(P, front, tr, ti, 0, TZ));

  const cups = [];
  for (let k = 0; k < N; k++) {
    const x0 = 3 + k * STEP, x1 = x0 + 2 * W, y0 = 2, y1 = y0 + D, h = HS[k], grp = mk("g", {}, g);
    const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
    const [cr, ci] = rings(x0, y0, x1, y1, 4, 1.6);
    put(solid(grp), prism(P, front, cr, ci, TZ, TZ + h));
    const pens = [];
    const spots = [[cx - 5, cy - 6, 20], [cx + 4, cy - 1, 24], [cx - 2, cy + 7, 17]];
    for (const [px, py, len] of spots) {
      const s = solid(grp), [pr, pi] = rings(px - 1.6, py - 1.6, px + 1.6, py + 1.6, 1.6, 0.5);
      pens.push({ s, pr, pi, len });
    }
    cups.push({ k, cx, cy, h, pens, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }

  function draw(c, lift) {
    if (lift === c.last) return;
    c.last = lift;
    const base = TZ + c.h - 6 + lift;
    for (const p of c.pens) put(p.s, prism(P, front, p.pr, p.pi, Math.max(TZ + c.h, base), base + p.len));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const c of cups) { draw(c, tval(c.z, now)); if (!tdone(c.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = cups.map((c) => P(c.cx, c.cy, TZ + c.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    cups.forEach((c, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(c.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      for (const p of c.pens) p.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "cup " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "deskorganizer",
  means: "A desk organiser of four cups: the pens in the cup under the pointer lift out, and the cups beside it raise theirs a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[136, 142], [179, 174], [264, 216], null],
  mount,
});

networkswitch.code:
/**
 * Network switch: a flat rack switch with a row of eight ports along its
 * front face, a patch plug seated in each, a link light above every port.
 * The pointer picks a port by where it is along the switch: that plug slides
 * out of its socket and its light goes bright, its neighbours ease out a
 * little after it. At rest the plugs sit at uneven depths, one pulled, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is on a fixed plane
 * through the plugs' resting middles.
 */
const {
  Cam, clamp, facing, fit, open, poly, prism, proj, rings, ringAt, rrect, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 8, STEP = 11, X0 = 10, X1 = X0 + (N - 1) * STEP + 10, Y1 = 34, H = 14, PZ = [3.5, 9], PL = 9, PULL = 14;
const REST = [0.6, 0, 1.2, 0.2, 4, 0.4, 0, 1], FAV = 4, LIT = [1, 1, 0, 1, 1, 0, 1, 1];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[0, 0, 0], [X1, 0, 0], [X1, Y1 + PL + PULL + 6, 0], [0, Y1 + PL + PULL + 6, 0], [0, 0, H], [X1, Y1, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the body: one long low solid, vents on the lid, sockets on the front face
  const [outer, inner] = rings(0, 0, X1, Y1, 4, 1.4);
  const body = solid(g);
  put(body, prism(P, front, outer, inner, 0, H));
  let deco = "";
  for (let k = 0; k < 6; k++) deco += seg(P(8 + k * 5, 8, H), P(8 + k * 5, 20, H));
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP;
    deco += poly([P(x - 3.6, Y1, PZ[0] - 1), P(x + 3.6, Y1, PZ[0] - 1), P(x + 3.6, Y1, PZ[1] + 1), P(x - 3.6, Y1, PZ[1] + 1)]);
  }
  mk("path", { class: "nf lo", d: deco }, body.g);
  const leds = [];
  for (let k = 0; k < N; k++) {
    const c = mk("circle", { class: LIT[k] ? "dot m" : "dot off", r: 1.3 }, body.g);
    const [sx, sy] = P(X0 + k * STEP, Y1, H - 2.4);
    c.setAttribute("cx", sx); c.setAttribute("cy", sy);
    leds.push(c);
  }

  // a plug: a short boot along y with its cable dropping to the floor
  const plugs = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    plugs.push({ k, x: X0 + k * STEP, cab: mk("path", { class: "nf" }, grp), s: solid(grp), o: tween(REST[k]), last: NaN });
  }
  function draw(p, o) {
    if (o === p.last) return;
    p.last = o;
    const y0 = Y1 - 1 + o, y1 = y0 + PL;
    const [r, i] = rings(p.x - 2.8, y0, p.x + 2.8, y1, 1.4, 0.7);
    put(p.s, prism(P, front, r, i, PZ[0], PZ[1]));
    const zc = (PZ[0] + PZ[1]) / 2, pts = [];
    for (let t = 0; t <= 8; t++) { const u = t / 8; pts.push(P(p.x, y1 + u * 8, zc * (1 - u) * (1 - u))); }
    p.cab.setAttribute("d", open(pts));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    plugs.forEach((p) => { draw(p, tval(p.o, now)); if (!tdone(p.o, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, (PZ[0] + PZ[1]) / 2);
    if (x < -4 || x > X1 + 4 || y < Y1 - 14 || y > Y1 + PL + PULL + 8) return -1;
    return clamp(Math.round((x - X0) / STEP), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    plugs.forEach((p, k) => {
      const o = a < 0 ? REST[k] : k === a ? PULL : Math.max(0, 2.4 - Math.abs(k - a) * 0.8);
      tset(p.o, o, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      p.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
      leds[k].setAttribute("class", k === (a < 0 ? FAV : a) ? "dot" : LIT[k] ? "dot m" : "dot off");
    });
    read.textContent = a < 0 ? "rest" : "port " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "networkswitch",
  means: "A network switch: the plug in the port under the pointer slides out and its light goes bright, its neighbours easing after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[109, 139], [173, 171], [258, 214], null],
  mount,
});

gpus.code:
/**
 * Graphics cards: four cards standing in a row of slots on a board, each a
 * long thin shroud with two fans on its open side. The pointer picks a card
 * by where it is along the row: that card lifts out of its slot, its
 * neighbours rise a little after it. At rest the cards sit seated at uneven
 * heights, one half out, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is on a fixed plane
 * through the cards' resting middles.
 */
const {
  Cam, clamp, facing, fit, poly, prism, proj, rings, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 14, X0 = 10, T = 4, Y0 = 6, Y1 = 50, H = 22, LIFT = 18, XB = X0 + (N - 1) * STEP + 12;
const REST = [0.5, 7, 1.5, 0], FAV = 1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[0, 0, -4], [XB, 0, -4], [XB, Y1 + 6, -4], [0, Y1 + 6, -4], [X0, Y0, H + LIFT], [XB, Y1, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the board: a low slab with a slot under each card
  const [bo, bi] = rings(0, 0, XB, Y1 + 6, 4, 1.4);
  const board = solid(g);
  put(board, prism(P, front, bo, bi, -4, 0));
  let slots = "";
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP;
    slots += poly([P(x - 1, Y0 - 1, 0), P(x + T + 1, Y0 - 1, 0), P(x + T + 1, Y1 + 1, 0), P(x - 1, Y1 + 1, 0)]);
  }
  mk("path", { class: "nf lo", d: slots }, board.g);

  // a card: a thin tall solid along y, two fans on its +x face
  const cards = [];
  for (let k = 0; k < N; k++) {
    const s = solid(g);
    cards.push({ k, x: X0 + k * STEP, s, fans: mk("path", { class: "nf lo" }, s.g), z: tween(REST[k]), last: NaN });
  }
  function fan(x, yc, zc, r) {
    const ring = [], hub = [];
    for (let i = 0; i < 24; i++) {
      const a = (i / 24) * Math.PI * 2;
      ring.push(P(x, yc + r * Math.cos(a), zc + r * Math.sin(a)));
      hub.push(P(x, yc + r * 0.3 * Math.cos(a), zc + r * 0.3 * Math.sin(a)));
    }
    return poly(ring) + poly(hub);
  }
  function draw(c, z) {
    if (z === c.last) return;
    c.last = z;
    const [r, i] = rings(c.x, Y0, c.x + T, Y1, 1.6, 0.8);
    put(c.s, prism(P, front, r, i, z, z + H));
    c.fans.setAttribute("d", fan(c.x + T, Y0 + 11.5, z + H / 2, 8) + fan(c.x + T, Y1 - 11.5, z + H / 2, 8));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    cards.forEach((c) => { draw(c, tval(c.z, now)); if (!tdone(c.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H / 2);
    if (x < -6 || x > XB + 6 || y < Y0 - 8 || y > Y1 + 8) return -1;
    return clamp(Math.round((x - X0 - T / 2) / STEP), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    cards.forEach((c, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : Math.max(0, 4 - Math.abs(k - a) * 1.5);
      tset(c.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      c.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "gpu " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "gpus",
  means: "Graphics cards in a row of slots: the card under the pointer lifts out, its neighbours rising a little after it.",
  rules: [1, 2, 5, 6],
