smartbulbs.code:
/**
 * Smart bulbs: four bulbs standing in sockets along a low base, each a
 * screw cap under a round glass. The pointer picks a bulb by where it is
 * along the base: that bulb lifts out of its socket, its neighbours rise a
 * little after it. At rest the bulbs sit at uneven heights, one raised,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is on a fixed plane
 * through the bulbs' resting middles.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, ringAt, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 18, X0 = 10, YC = 10, XB = X0 + (N - 1) * STEP + 10, LIFT = 16;
const REST = [0.5, 0, 6, 1], FAV = 2, PROF = [[3, 3.2], [7, 3.4], [10, 5], [14, 8], [19, 9], [24, 8], [28, 5], [30, 1.5]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.4);
  fit(C, [[0, 0, -3], [XB, 0, -3], [XB, 20, -3], [0, 20, -3], [X0, YC, 30 + LIFT], [XB, YC, 30]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [bo, bi] = rings(0, 0, XB, 20, 6, 1.4);
  const base = solid(g);
  put(base, prism(P, front, bo, bi, -3, 0));
  let sockets = "";
  for (let k = 0; k < N; k++) sockets += poly(ringAt(P, circ(4.2, 16).map((s) => ({ ...s, u: s.u + X0 + k * STEP, v: s.v + YC })), 0));
  mk("path", { class: "nf lo", d: sockets }, base.g);

  const bulbs = [];
  for (let k = 0; k < N; k++) {
    const s = solid(g);
    bulbs.push({ k, x: X0 + k * STEP, s, z: tween(REST[k]), last: NaN });
  }
  const ring = (x, r, z) => ringAt(P, circ(r, 20).map((s) => ({ ...s, u: s.u + x, v: s.v + YC })), z);
  function draw(b, z) {
    if (z === b.last) return;
    b.last = z;
    let pts = ring(b.x, 3.2, z);
    PROF.forEach(([h, r]) => { pts = pts.concat(ring(b.x, r, z + h)); });
    b.s.sil.setAttribute("d", poly(hull(pts)));
    const half = (zz, r) => open(ring(b.x, r, zz).filter((_, i) => i <= 10));
    b.s.cr.setAttribute("d", half(z + 4, 3.3) + half(z + 7, 3.4) + half(z + 10, 5));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    bulbs.forEach((b) => { draw(b, tval(b.z, now)); if (!tdone(b.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 15);
    if (x < -6 || x > XB + 6 || y < -6 || y > 26) return -1;
    return clamp(Math.round((x - X0) / STEP), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    bulbs.forEach((b, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : Math.max(0, 4 - Math.abs(k - a) * 1.5);
      tset(b.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      b.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bulb " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "smartbulbs",
  means: "Smart bulbs in a row of sockets: the bulb under the pointer lifts out, its neighbours rising a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[135, 141], [178, 162], [265, 206], null],
  mount,
});

webcams.code:
/**
 * Webcams: four small cameras on stands along a desk. Every camera pans to
 * face the point under the pointer, each on its own spring; the one nearest
 * the pointer takes the bright edge. At rest they look in slightly different
 * directions and one is bright. The slider is how far they may turn.
 *
 * The pattern: parts turning to face the pointer.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rad, rings, ringAt, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 36, CZ = 4, SH = 12, BZ = 10, FAV = 2;
const X1 = (N - 1) * STEP;
const REST = [62, 30, 52, 20];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const rot = (ring, x, y, th) => {
  const c = Math.cos(th), s = Math.sin(th);
  return ring.map((q) => ({ u: x + q.u * c - q.v * s, v: y + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-16, -16, 0], [X1 + 16, 16, 0], [X1 + 16, -16, 0], [-16, 16, 0], [0, 0, CZ + SH + BZ + 2], [X1, 0, CZ + SH + BZ + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [dr, di] = rings(-16, -16, X1 + 16, 16, 6, 2);
  put(solid(g), prism(P, front, dr, di, 0, CZ));
  const [br, bi] = rings(-4.5, -10, 4.5, 10, 3.2, 1.2);

  const cams = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, y = 0, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, y, 7), disc(x, y, 5.5), CZ, CZ + 1.5));
    put(solid(grp), prism(P, front, disc(x, y, 1.6, 12), disc(x, y, 1, 12), CZ + 1.5, CZ + SH));
    const body = solid(grp);
    const lens = mk("path", { class: "nf" }, grp), glass = mk("path", { class: "nf lo" }, grp);
    cams.push({ k, x, y, body, lens, glass, a: spring(rad(REST[k])), last: NaN });
  }

  function lensRing(it, th, R, out) {
    const c = Math.cos(th), s = Math.sin(th), pts = [], zc = CZ + SH + BZ / 2 + 0.6;
    for (let i = 0; i < 24; i++) {
      const t = (i / 24) * Math.PI * 2, w = R * Math.cos(t);
      pts.push(P(it.x + c * (4.5 + out) - s * w, it.y + s * (4.5 + out) + c * w, zc + R * Math.sin(t)));
    }
    return pts;
  }

  function draw(it) {
    const th = it.a.x;
    if (Math.abs(th - it.last) < 1e-4) return;
    it.last = th;
    put(it.body, prism(P, front, rot(br, it.x, it.y, th), rot(bi, it.x, it.y, th), CZ + SH, CZ + SH + BZ));
    it.lens.setAttribute("d", poly(hull(lensRing(it, th, 3.6, 0).concat(lensRing(it, th, 3.6, 1.6)))));
    it.glass.setAttribute("d", poly(lensRing(it, th, 2, 1.6)));
  }

  const B = register(stage, (dt) => {
    let moving = false;
    for (const it of cams) { if (stepS(it.a, dt)) moving = true; draw(it); }
    return moving;
  });
  bag.add(B.unregister);

  const mids = cams.map((it) => P(it.x, it.y, CZ + SH));
  let act = -2;
  function aim(p) {
    let best = -1, bd = Infinity;
    if (p) mids.forEach((m, k) => { const dd = Math.abs(m[0] - p[0]); if (dd < bd) { bd = dd; best = k; } });
    const a = p && bd < 30 && Math.abs(mids[best][1] - p[1]) < 70 ? best : -1;
    const g0 = p ? unproj(C, p[0], p[1], 0) : null;
    const lim = 25 + reach;
    cams.forEach((it, k) => {
      const want = g0 ? Math.atan2(g0[1] - it.y + 30, g0[0] - it.x + 30) : rad(REST[k]);
      it.a.t = clamp(want, rad(45 - lim), rad(45 + lim));
      it.body.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    if (a !== act || a >= 0) read.textContent = a < 0 ? "rest" : "cam " + (a + 1) + " " + Math.round((cams[a].a.t * 180) / Math.PI - 45) + "°";
    act = a;
    B.wake();
  }
  cams.forEach(draw);
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "webcams",
  means: "Four webcams on a desk: each pans on its stand to face the pointer, and the one nearest it takes the bright edge.",
  rules: [1, 3, 5, 8],
  range: [10, 45, 70],
  tour: [[118, 102], [173, 129], [282, 184], null],
  mount,
});

joysticks.code:
/**
 * Joysticks: three arcade sticks on a control panel, each a ball on a shaft
 * over a dust washer. Every stick tilts toward the point under the pointer
 * on its own spring; the nearest takes the bright edge. At rest they lean a
 * little each way and one is bright. The slider is how far a stick tilts.
 *
 * The pattern: parts turning to face the pointer.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, ringAt, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 40, PZ = 8, L = 20, BR = 6, FAV = 1;
const X1 = (N - 1) * STEP;
const REST = [[0.25, -0.1], [-0.15, 0.3], [0.1, 0.2]];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let tilt = value / 100;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-20, -20, 0], [X1 + 20, 20, 0], [X1 + 20, -20, 0], [-20, 20, 0], [0, 0, PZ + L + BR + 2], [X1, 0, PZ + L + BR + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-20, -20, X1 + 20, 20, 7, 2);
  put(solid(g), prism(P, front, pr, pi, 0, PZ));

  const sticks = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, y = 0, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, y, 9), disc(x, y, 7), PZ, PZ + 1.2));
    const shaft = mk("path", { class: "nf" }, grp), ball = mk("path", { class: "sil" }, grp);
    sticks.push({ k, x, y, shaft, ball, tx: spring(REST[k][0]), ty: spring(REST[k][1]), lx: NaN, ly: NaN });
  }

  function draw(s) {
    const a = s.tx.x, b = s.ty.x;
    if (Math.abs(a - s.lx) < 1e-4 && Math.abs(b - s.ly) < 1e-4) return;
    s.lx = a; s.ly = b;
    const z0 = PZ + 1.2, bx = s.x + L * a, by = s.y + L * b, bz = z0 + L * Math.sqrt(Math.max(0, 1 - a * a - b * b));
    s.shaft.setAttribute("d", poly(hull(ringAt(P, disc(s.x, s.y, 1.6, 12), z0).concat(ringAt(P, disc(bx, by, 1.6, 12), bz)))));
    const pts = [];
    for (let i = -6; i <= 6; i++) { const t = (i / 6) * (Math.PI / 2); pts.push(...ringAt(P, disc(bx, by, BR * Math.cos(t), 24), bz + BR * Math.sin(t))); }
    s.ball.setAttribute("d", poly(hull(pts)));
  }

  const B = register(stage, (dt) => {
    let moving = false;
    for (const s of sticks) { if (stepS(s.tx, dt)) moving = true; if (stepS(s.ty, dt)) moving = true; draw(s); }
    return moving;
  });
  bag.add(B.unregister);

  const mids = sticks.map((s) => P(s.x, s.y, PZ + L / 2));
  function aim(p) {
    let best = -1, bd = Infinity;
    if (p) mids.forEach((m, k) => { const dd = Math.abs(m[0] - p[0]); if (dd < bd) { bd = dd; best = k; } });
    const a = p && bd < 34 && Math.abs(mids[best][1] - p[1]) < 70 ? best : -1;
    const w = p ? unproj(C, p[0], p[1], PZ) : null;
    sticks.forEach((s, k) => {
      if (!w) { s.tx.t = REST[k][0]; s.ty.t = REST[k][1]; } else {
        const dx = w[0] - s.x, dy = w[1] - s.y, d = Math.hypot(dx, dy) || 1, m = tilt * clamp(d / 30, 0.3, 1);
        s.tx.t = (dx / d) * m; s.ty.t = (dy / d) * m;
      }
      s.ball.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "p" + (a + 1) + " " + (w[0] - sticks[a].x > 0 ? "→" : "←");
    B.wake();
  }
  sticks.forEach(draw);
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { tilt = v / 100; }, destroy: bag.dispose };
}

hairline({
  name: "joysticks",
  means: "Three arcade joysticks on a panel: each stick tilts toward the pointer, and the nearest one takes the bright edge.",
  rules: [1, 3, 5, 8],
  range: [20, 40, 55],
  tour: [[150, 140], [200, 170], [250, 195], null],
  mount,
});

ballpit.code:
/**
 * Ball pit: a soft-walled pit heaped with balls. The pointer picks the ball
 * it stands over, on the plane through the balls' rest centres: that ball
 * bounces up out of the heap and the balls round it rise a little, staggered
 * by distance. At rest one ball is half raised, bright. The slider is the stagger.
 *
 * The pattern: a field picked on a plane (terrain).
 */
const {
  Cam, fit, facing, prism, proj, rings, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const G = 4, R = 8, SP = 17, WH = 10, LIFT = 22, FAV = 6;
const W = G * SP + 8;
const REST = [2, 0, 3, 1, 0, 4, 0, 2, 3, 1, 0, 2, 1, 3, 2, 0];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-4, -4, 0], [W + 4, W + 4, 0], [W + 4, -4, 0], [-4, W + 4, 0], [W / 2, W / 2, WH + R * 2 + LIFT + 4]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-4, -4, W + 4, W + 4, 10, 4);
  put(solid(g), prism(P, front, pr, pi, 0, WH));

  const items = [], order = [];
  for (let i = 0; i < G; i++) for (let j = 0; j < G; j++) order.push([i, j]);
  order.sort((a, b) => a[0] + a[1] - (b[0] + b[1]));
  const byK = [];
  for (const [i, j] of order) {
    const k = i * G + j, x = 4 + R + i * SP + (j % 2) * 3, y = 4 + R + j * SP;
    const ball = mk("ellipse", { class: "sil", rx: R * 2.3, ry: R * 2.3 }, g);
    const seam = mk("path", { class: "nf lo" }, g);
    byK[k] = { k, i, j, x, y, ball, seam, z: tween(k === FAV ? LIFT * 0.5 : REST[k]), last: NaN };
  }
  items.push(...byK);

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const c = P(it.x, it.y, WH + R * 0.4 + lift);
    it.ball.setAttribute("cx", c[0]); it.ball.setAttribute("cy", c[1]);
    // a seam: one short arc across the ball's face
    const rr = R * 2.3 * 0.62;
    it.seam.setAttribute("d", "M" + (c[0] - rr) + "," + (c[1] - 2) + "Q" + c[0] + "," + (c[1] + rr * 0.55) + " " + (c[0] + rr) + "," + (c[1] - 2));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, WH + R * 0.4);
    let best = -1, bd = Infinity;
    for (const it of items) { const d = Math.hypot(it.x - wx, it.y - wy); if (d < bd) { bd = d; best = it.k; } }
    return bd < R * 1.4 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act, f = items[from];
    act = a;
    for (const it of items) {
      const dd = a < 0 ? 9 : Math.hypot(it.i - items[a].i, it.j - items[a].j);
      const z = a < 0 ? (it.k === FAV ? LIFT * 0.5 : REST[it.k]) : dd === 0 ? LIFT : dd < 1.5 ? 6 : 0;
      tset(it.z, z, now, f ? Math.hypot(it.i - f.i, it.j - f.j) * stag : 0);
      it.ball.classList.toggle("hi", it.k === (a < 0 ? FAV : a));
    }
    read.textContent = a < 0 ? "rest" : "ball " + (items[a].i + 1) + "·" + (items[a].j + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "ballpit",
  means: "A pit heaped with balls: the ball under the pointer bounces up out of the heap, and the balls round it rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[150, 150], [200, 170], [250, 190], null],
  mount,
});

dollhouse.code:
/**
 * Dollhouse: a toy house on a low base, door and windows on its face. The
 * pointer over the house lifts its gable roof off to show the rooms inside;
 * at rest the roof sits a little raised, bright. The slider is the lift.
 */
const {
  Cam, fit, facing, fillet, hull, open, poly, prism, proj, rings, ringAt, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = 0, X1 = 64, Y0 = 0, Y1 = 44, BZ = 4, H = 40, RH = 22, OV = 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value / 100;
  const LIFT = 26;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[X0 - 8, Y0 - 8, 0], [X1 + 8, Y1 + 8, 0], [X1 + 8, Y0 - 8, 0], [X0 - 8, Y1 + 8, 0], [X0, (Y0 + Y1) / 2, BZ + H + RH + LIFT], [X1, (Y0 + Y1) / 2, BZ + H + RH + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(X0 - 8, Y0 - 8, X1 + 8, Y1 + 8, 5, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  const [hr, hi] = rings(X0, Y0, X1, Y1, 2, 1.4);
  put(solid(g), prism(P, front, hr, hi, BZ, BZ + H));
  // the rooms: the open top, a floor and a party wall seen when the roof is off
  const top = BZ + H;
  mk("path", { d: poly(ringAt(P, hi, top)), class: "nf lo" }, g);
  mk("path", { d: seg(P(X1 / 2, Y0 + 1.4, top), P(X1 / 2, Y1 - 1.4, top)) + seg(P(X1 / 2, Y0 + 1.4, top), P(X1 / 2, Y0 + 1.4, top - 14)), class: "nf lo" }, g);
  // the face: a door and two windows on the near (+y) wall
  const fy = Y1;
  const rect = (u0, u1, z0, z1) => open([P(u0, fy, z0), P(u0, fy, z1), P(u1, fy, z1), P(u1, fy, z0)]);
  mk("path", { d: rect(26, 38, BZ, BZ + 18), class: "nf lo" }, g);
  mk("path", { d: poly([P(8, fy, BZ + 22), P(8, fy, BZ + 32), P(18, fy, BZ + 32), P(18, fy, BZ + 22)]), class: "nf lo" }, g);
  mk("path", { d: poly([P(46, fy, BZ + 22), P(46, fy, BZ + 32), P(56, fy, BZ + 32), P(56, fy, BZ + 22)]), class: "nf lo" }, g);
  mk("path", { d: poly([P(X1, 14, BZ + 22), P(X1, 14, BZ + 32), P(X1, 30, BZ + 32), P(X1, 30, BZ + 22)]), class: "nf lo" }, g);
  const knob = mk("circle", { r: 1.6, class: "dot off" }, g);
  const kp = P(35, fy, BZ + 9); knob.setAttribute("cx", kp[0]); knob.setAttribute("cy", kp[1]);

  const rg = mk("g", {}, g);
  const roof = mk("path", { class: "sil" }, rg), ridge = mk("path", { class: "nf lo" }, rg);
  const REST = 6, z = tween(REST);
  let last = NaN;
  function draw(l) {
    if (l === last) return;
    last = l;
    const b = top + l, ym = (Y0 + Y1) / 2;
    const pts = [[X0 - OV, Y0 - OV, b], [X1 + OV, Y0 - OV, b], [X1 + OV, Y1 + OV, b], [X0 - OV, Y1 + OV, b], [X0 - OV, ym, b + RH], [X1 + OV, ym, b + RH],
      [X0 - OV, Y0 - OV, b + 2], [X1 + OV, Y0 - OV, b + 2], [X1 + OV, Y1 + OV, b + 2], [X0 - OV, Y1 + OV, b + 2]].map((q) => P(...q));
    const h = hull(pts);
    roof.setAttribute("d", poly(fillet(h, h.map(() => 2), 3)));
    ridge.setAttribute("d", seg(P(X0 - OV + 1, ym, b + RH - 1.5), P(X1 + OV - 1, ym, b + RH - 1.5)) + seg(P(X1 + OV - 1, ym, b + RH - 1.5), P(X1 + OV - 1, Y1 + OV - 1, b + 2)) + seg(P(X0 - OV + 1, Y1 + OV - 1, b + 2), P(X1 + OV - 1, Y1 + OV - 1, b + 2)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(z, now)); return !tdone(z, now); });
  bag.add(B.unregister);

  // hit against the house at rest: its box on screen never moves
  const box = [P(X0, Y0, BZ), P(X1, Y1, BZ), P(X1, Y0, BZ + H + RH), P(X0, Y1, BZ + H + RH), P(X1, Y1, 0), P(X0, Y0, BZ + H + RH)];
  const xs = box.map((q) => q[0]), ys = box.map((q) => q[1]);
  const inside = ([sx, sy]) => sx > Math.min(...xs) && sx < Math.max(...xs) && sy > Math.min(...ys) && sy < Math.max(...ys);

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(z, on ? LIFT * (0.5 + 0.5 * amt) : REST, performance.now(), 0);
    knob.setAttribute("class", on ? "dot" : "dot off");
    roof.classList.toggle("hi", !on);
    ridge.setAttribute("class", "nf lo");
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(inside(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v / 100; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "dollhouse",
  means: "A toy house on a base: the pointer over it lifts the gable roof off to show the rooms inside.",
  rules: [1, 4, 5, 6],
  range: [0, 100, 100],
  tour: [[200, 184], [176, 150], [226, 206], null],
  mount,
});

kidstable.code:
/**
 * Kids table: a low play table with crayons on its top and three small
 * chairs along its near side. The pointer picks a chair by where it stands:
 * that chair slides out from the table, its neighbours a little, staggered.
 * At rest one chair is pulled out, bright. The slider is the stagger.
 */
const {
  Cam, fit, facing, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, TX = 96, TY = 40, TZ = 20, CW = 20, OUT = 22, FAV = 1;
const REST = [3, OUT * 0.8, 0];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-4, -4, 0], [TX + 4, TY + 30 + OUT, 0], [TX + 4, -4, 0], [-4, TY + 30 + OUT, 0], [0, 0, TZ + 4], [TX, TY + 30 + OUT, 32]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (parent, x0, y0, x1, y1, z0, z1, r = 1.5, b = 1) => { const [a, i] = rings(x0, y0, x1, y1, r, b); const s = solid(parent); put(s, prism(P, front, a, i, z0, z1)); return s; };
  for (const [x, y] of [[2, 2], [TX - 6, 2], [2, TY - 6], [TX - 6, TY - 6]]) box(g, x, y, x + 4, y + 4, 0, TZ - 3, 1.5, 0.8);
  box(g, -2, -2, TX + 2, TY + 2, TZ - 3, TZ, 3, 1.6);
  // crayons and a sheet of paper on the top
  mk("path", { d: seg(P(14, 10, TZ), P(44, 10, TZ)) + seg(P(44, 10, TZ), P(44, 30, TZ)) + seg(P(44, 30, TZ), P(14, 30, TZ)) + seg(P(14, 30, TZ), P(14, 10, TZ)), class: "nf lo" }, g);
  for (let k = 0; k < 4; k++) box(g, 58 + k * 6, 10 + k * 2, 61 + k * 6, 26 + k * 2, TZ, TZ + 2.4, 1.2, 0.5);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 8 + k * 30, grp = mk("g", {}, g);
    const seat = solid(grp), back = solid(grp);
    items.push({ k, x, grp, seat, back, y: tween(REST[k]), last: NaN });
  }
  function draw(it, d) {
    if (d === it.last) return;
    it.last = d;
    const y0 = TY + 4 + d, [a, i] = rings(it.x, y0, it.x + CW, y0 + 18, 3, 1.4);
    put(it.seat, prism(P, front, a, i, 0, 12));
    const [ba, bi] = rings(it.x, y0 + 15, it.x + CW, y0 + 18, 1.5, 0.8);
    put(it.back, prism(P, front, ba, bi, 12, 28));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.y, now)); if (!tdone(it.y, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + CW / 2, TY + 13, 10));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), y = a < 0 ? REST[k] : dd === 0 ? OUT : dd === 1 ? 5 : 0;
      tset(it.y, y, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.seat.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
      it.back.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "seat " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "kidstable",
  means: "A low play table with crayons and three small chairs: the chair under the pointer slides out, its neighbours a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[144, 154], [187, 175], [230, 196], null],
  mount,
});

birdbath.code:
/**
 * Bird bath: a basin on a pedestal over a round foot. The basin tips toward
 * the pointer, its water lying level inside, as if a bird had landed on that
 * rim. At rest it leans a little, its water bright. The slider is the reach.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, ringAt, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const H = 44, R0 = 12, R1 = 30, D = 9;
const disc = (r, n = 40) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value / 100;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-R1 - 4, -R1 - 4, 0], [R1 + 4, R1 + 4, 0], [R1 + 4, -R1 - 4, H + D + 8], [-R1 - 4, R1 + 4, H + D + 8]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(20), disc(18), 0, 4));
  put(solid(g), prism(P, front, disc(7), disc(6), 4, H - 4));
  const s = solid(g), water = mk("path", { class: "nf" }, g);
  const tx = spring(0.06), ty = spring(0.03);
  let last = "";
  const tip = (ring, z, a, b) => ring.map((q) => { const p = P(q.u, q.v, z + a * q.u + b * q.v); return p; });
  function draw() {
    const key = tx.x.toFixed(4) + ty.x.toFixed(4);
    if (key === last) return;
    last = key;
    const a = tx.x, b = ty.x;
    s.sil.setAttribute("d", poly(hull(tip(disc(R0), H - 4, a * 0.3, b * 0.3).concat(tip(disc(R1), H + D, a, b)))));
    s.cr.setAttribute("d", poly(tip(disc(R1 - 2), H + D, a, b)));
    s.cr.setAttribute("class", "nf lo");
    water.setAttribute("d", poly(ringAt(P, disc(R1 - 7 - 10 * Math.hypot(a, b)), H + D - 3)));
  }
  draw();
  const B = register(stage, (dt) => { const m = stepS(tx, dt) | stepS(ty, dt); draw(); return !!m; });
  bag.add(B.unregister);

  let act = null;
  function aim(p) {
    const on = !!p;
    let a = 0.06, b = 0.03;
    if (on) {
      const [x, y] = unproj(C, p[0], p[1], 0), d = Math.hypot(x, y) || 1, m = clamp(d / 80, 0.3, 1) * 0.16 * (0.4 + 0.6 * reach);
      a = -(x / d) * m; b = -(y / d) * m;
      read.textContent = Math.round(((Math.atan2(y, x) * 180) / Math.PI + 360) % 360) + "°";
    } else read.textContent = "rest";
    tx.t = a; ty.t = b;
    if (on !== act) { act = on; water.classList.toggle("hi", !on); s.sil.classList.toggle("hi", on); }
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v / 100; }, destroy: bag.dispose };
}

hairline({
  name: "birdbath",
  means: "A basin on a pedestal: it tips toward the pointer, the water lying level inside, as if a bird had landed on that rim.",
  rules: [3, 4, 5, 8],
  range: [0, 70, 100],
  tour: [[150, 150], [250, 150], [200, 230], null],
  mount,
});

horsestable.code:
/**
 * Horse stable: a low block with a gabled roof and four stall doors along
 * its front, each a split door with a braced lower leaf. The pointer picks
 * a stall by where it stands: the top leaf of its door swings open on its
 * hinge, and the leaves beside it crack open, staggered from it. At rest
 * one top leaf stands half open, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, fillet, hull, open, poly, prism, proj, rings, ringAt, rrect, run, seg,
  tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, W = 16, GAP = 27, M = 10, D = 34, H = 34, ZM = 14, ZT = 28, RH = 15, OPEN = 105, FAV = 2;
const X1 = 2 * M + (N - 1) * GAP + W;
const REST = [0, 12, 60, 0];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, 0, 0], [X1, D, 0], [X1 + 4, -4, H], [-4, D + 4, H], [X1 / 2, D / 2, H + RH], [M, D + W, 0], [X1, D + W, ZT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, X1, D, 3, 1.5);
  put(solid(g), prism(P, front, br, bi, 0, H));

  // the doors on the front face: frame, braced lower leaf
  const F = (x, z) => P(x, D, z);
  const xs = [];
  for (let k = 0; k < N; k++) {
    const x = M + k * GAP; xs.push(x);
    mk("path", { d: poly(fillet([F(x - 1.5, 0), F(x - 1.5, ZT + 1.5), F(x + W + 1.5, ZT + 1.5), F(x + W + 1.5, 0)], [0.5, 1.5, 1.5, 0.5])), class: "nf lo" }, g);
    mk("path", { d: poly(fillet([F(x, 0.8), F(x, ZM), F(x + W, ZM), F(x + W, 0.8)], [0.6, 0.6, 0.6, 0.6])), class: "nf" }, g);
    mk("path", { d: seg(F(x + 1.5, 2), F(x + W - 1.5, ZM - 1.5)) + seg(F(x + 1.5, ZM / 2), F(x + W - 1.5, ZM / 2)), class: "nf lo" }, g);
  }

  // the gabled roof: an eave ring under a ridge ring
  const foot = rrect(-4, -4, X1 + 4, D + 4, 2, 4), top = rrect(-4, D / 2 - 1.2, X1 + 4, D / 2 + 1.2, 1, 4);
  const inner = rrect(-3.2, D / 2 - 0.5, X1 + 3.2, D / 2 + 0.5, 0.4, 4);
  put(solid(g), { sil: poly(hull(ringAt(P, foot, H).concat(ringAt(P, top, H + RH)))), crease: open(ringAt(P, run(inner, front), H + RH)) });

  const items = xs.map((x, k) => {
    const grp = mk("g", {}, g);
    return { k, x, grp, leaf: mk("path", { class: "sil" }, grp), edge: mk("path", { class: "nf lo" }, grp), a: tween(REST[k]), last: NaN };
  });

  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const a = (deg * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a), t = 1.4;
    const ex = it.x + W * c, ey = D + W * s, nx = -s * t, ny = c * t;
    const pts = [];
    for (const z of [ZM + 0.6, ZT]) pts.push(P(it.x, D, z), P(ex, ey, z), P(it.x + nx, D + ny, z), P(ex + nx, ey + ny, z));
    it.leaf.setAttribute("d", poly(hull(pts)));
    const mx = it.x + W * 0.5 * c, my = D + W * 0.5 * s;
    it.edge.setAttribute("d", seg(P(it.x + 1.2 * c + nx, D + 1.2 * s + ny, (ZM + ZT) / 2), P(ex - 1.2 * c + nx, ey - 1.2 * s + ny, (ZM + ZT) / 2)) + seg(P(mx + nx, my + ny, ZM + 2), P(mx + nx, my + ny, ZT - 1.5)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = xs.map((x) => F(x + W / 2, ZM));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), deg = a < 0 ? REST[k] : dd === 0 ? OPEN : dd === 1 ? 30 : 0;
      tset(it.a, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.leaf.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "stall " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "horsestable",
  means: "Four stall doors along a stable: the top leaf under the pointer swings open on its hinge, and its neighbours crack open.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[110, 127], [158, 152], [221, 183], null],
  mount,
});

catflap.code:
/**
 * Cat flap: a door standing on a sill, a framed flap set low in it, hung
 * from its top edge. The pointer, on the floor in front of the door, draws
 * the flap out toward it: the nearer the door, the wider it swings; behind
 * the door it falls shut. At rest the flap hangs a little ajar, bright.
 * The slider is how far the flap can swing.
 *
 * The pattern: one part answering where the pointer stands (spring).
 */
const {
  Cam, clamp, fit, facing, fillet, hull, poly, prism, proj, rings, seg, unproj,
  disposer, mk, pointer, put, register, solid, spring, stepS,
} = HL;

const DW = 64, DH = 104, T = 5, Z0 = 3, FX0 = 18, FX1 = 46, FZ0 = Z0 + 8, FZ1 = Z0 + 38, REST = 18;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.75);
  const Y = T / 2, L = FZ1 - FZ0;
  fit(C, [[-12, -26, 0], [DW + 12, 40, 0], [DW + 12, -26, 0], [-12, 40, 0], [0, 0, Z0 + DH], [DW, Y, Z0 + DH]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [fr, fi] = rings(-12, -26, DW + 12, 40, 5, 2);
  put(solid(g), prism(P, front, fr, fi, 0, Z0));
  const [dr, di] = rings(0, -Y, DW, Y, 1.6, 0.8);
  put(solid(g), prism(P, front, dr, di, Z0, Z0 + DH));

  // on the door's face: two sunk panels above, the flap's frame below, a knob
  const F = (x, z) => P(x, Y, z);
  const rr = (x0, z0, x1, z1, r) => poly(fillet([F(x0, z0), F(x0, z1), F(x1, z1), F(x1, z0)], [r, r, r, r]));
  mk("path", { d: rr(8, Z0 + 54, DW - 8, Z0 + DH - 8, 2) + rr(8, Z0 + 48, DW - 8, Z0 + 50, 1), class: "nf lo" }, g);
  mk("path", { d: rr(FX0 - 3, FZ0 - 3, FX1 + 3, FZ1 + 3, 3), class: "nf lo" }, g);
  mk("path", { d: rr(FX0, FZ0, FX1, FZ1, 2), class: "nf" }, g);
  const kn = [];
  for (const [dx, dz] of [[-2, -2], [2, -2], [2, 2], [-2, 2]]) kn.push(P(DW - 8 + dx, Y, Z0 + 52 + dz), P(DW - 8 + dx, Y + 4, Z0 + 52 + dz * 0.8));
  mk("path", { d: poly(hull(kn)) }, g);

  const flap = mk("path", { class: "sil" }, g), hinge = mk("path", { class: "nf lo" }, g);
  const ang = spring(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = (deg * Math.PI) / 180, by = Y + L * Math.sin(a), bz = FZ1 - L * Math.cos(a), t = 1.3;
    const ny = Math.cos(a) * t, nz = Math.sin(a) * t, pts = [];
    for (const x of [FX0 + 0.8, FX1 - 0.8]) pts.push(P(x, Y, FZ1 - 0.8), P(x, by, bz), P(x, Y + ny, FZ1 - 0.8 + nz), P(x, by + ny, bz + nz));
    flap.setAttribute("d", poly(hull(pts)));
    const hy = Y + 3 * Math.sin(a) + ny, hz = FZ1 - 3 * Math.cos(a) + nz;
    hinge.setAttribute("d", seg(P(FX0 + 3, hy, hz), P(FX1 - 3, hy, hz)));
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(Math.round(ang.x * 100) / 100); return m; });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { ang.t = REST; read.textContent = "rest"; B.wake(); return; }
    const [x, y] = unproj(C, p[0], p[1], 0);
    const inside = x > -12 && x < DW + 12 && y > -26 && y < 70;
    if (!inside) return aim(null);
    const deg = y <= Y ? 0 : clamp((1 - (y - Y) / 64) * reach, 6, reach);
    ang.t = deg;
    read.textContent = y <= Y ? "shut" : Math.round(deg) + "°";
    B.wake();
  }
  flap.classList.add("hi");
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "catflap",
  means: "A cat flap low in a door: the pointer on the floor in front draws the flap out toward it; behind the door it falls shut.",
  rules: [1, 3, 5, 8],
  range: [30, 70, 85],
  tour: [[150, 210], [230, 220], [250, 120], null],
  mount,
});

trainplatform.code:
/**
 * Train platform: a raised platform under a canopy on three posts, rails
 * alongside, and a carriage standing at the platform. The pointer along the
 * platform draws the carriage to it, on a spring, so it slides in or out of
 * the station. At rest the carriage has stopped a little short, and the
 * canopy's edge is the bright mark. The slider is the carriage's reach.
 *
 * The pattern: one part following the pointer; the hit is on the ground plane.
 */
const {
  Cam, clamp, facing, fit, poly, prism, proj, rings, ringAt, rrect, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 90, PW = 22, PZ = 6, CZ = 34, TY0 = 28, TY1 = 42, TL = 50, TZ = 22, REST = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-14, -2, 0], [L + 14, TY1 + 4, 0], [L + 14, -2, 0], [-14, TY1 + 4, 0], [0, 0, CZ + 2], [L, 0, CZ + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the platform slab, its edge line, and the canopy on its posts
  const plat = solid(g);
  const [pr, pi] = rings(0, 0, L, PW, 2, 1);
  put(plat, prism(P, front, pr, pi, 0, PZ));
  mk("path", { class: "nf lo", d: seg(P(2, PW - 3, PZ), P(L - 2, PW - 3, PZ)) }, plat.g);
  [12, L / 2, L - 12].forEach((x) => {
    const [r, i] = rings(x - 1.4, 6, x + 1.4, 8.8, 1.2, 0.5);
    put(solid(g), prism(P, front, r, i, PZ, CZ));
  });
  const canopy = solid(g);
  const [cr, ci] = rings(-4, -3, L + 4, PW + 3, 3, 1.2);
  put(canopy, prism(P, front, cr, ci, CZ, CZ + 2));

  // the rails: two dim lines with sleepers
  let rails = seg(P(-14, TY0 + 3, 0), P(L + 14, TY0 + 3, 0)) + seg(P(-14, TY1 - 3, 0), P(L + 14, TY1 - 3, 0));
  for (let x = -12; x <= L + 12; x += 8) rails += seg(P(x, TY0 + 1, 0), P(x, TY1 - 1, 0));
  mk("path", { class: "nf lo", d: rails }, g);

  // the carriage: a rounded body, its roof crease, windows and two doors on the near side
  const car = solid(g);
  const marks = mk("path", { class: "nf lo" }, car.g);
  const x0 = spring(REST);
  let last = NaN;
  function draw(x) {
    if (x === last) return;
    last = x;
    const [r, i] = rings(x, TY0 + 1, x + TL, TY1 - 1, 5, 1.6);
    put(car, prism(P, front, r, i, 3, TZ));
    let d = "";
    for (let k = 0; k < 5; k++) {
      const wx = x + 5 + k * 9;
      if (k === 2) continue;
      d += poly([P(wx, TY1 - 1, 12), P(wx + 6, TY1 - 1, 12), P(wx + 6, TY1 - 1, 18), P(wx, TY1 - 1, 18)]);
    }
    d += poly([P(x + 23, TY1 - 1, 5), P(x + 29, TY1 - 1, 5), P(x + 29, TY1 - 1, 18), P(x + 23, TY1 - 1, 18)]);
    marks.setAttribute("d", d);
  }

  const B = register(stage, (dt) => {
    const m = stepS(x0, dt);
    draw(x0.x);
    return m;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    if (x < -14 || x > L + 14 || y < -6 || y > TY1 + 4) return null;
    return x;
  }
  let on = null;
  function setPointer(x) {
    if (x === null) {
      x0.t = REST;
      if (on !== null) read.textContent = "rest";
    } else {
      const c = L / 2 - TL / 2;
      x0.t = clamp(c + (x - L / 2) * reach, -12, L - TL + 12);
      read.textContent = "car " + Math.round(clamp((x0.t + 12) / (L - TL + 24), 0, 1) * 100) + "%";
    }
    car.sil.classList.toggle("hi", x !== null);
    canopy.sil.classList.toggle("hi", x === null);
    on = x;
    B.wake();
  }
  read.textContent = "rest";
  setPointer(null);
  bag.add(pointer(stage, { move: (p) => setPointer(hit(p)), leave: () => setPointer(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "trainplatform",
  means: "A train platform under a canopy: the carriage slides along the rails toward the pointer, and stops a little short at rest.",
  rules: [1, 3, 5, 8],
  range: [0.3, 0.9, 1.4],
  tour: [[217, 198], [110, 180], [300, 210], null],
  mount,
});

cargoship.code:
/**
 * Cargo ship: a rounded hull with the bridge at the stern and four bays of
 * stacked containers along the deck. The pointer picks a bay by where it is
 * along the ship: that bay's top container is hoisted clear, the bays beside
 * it lift a little, staggered from it. At rest one box hangs just off its
 * stack, bright, as if mid-load. The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is the nearest bay's
 * rest centre along the screen x.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, L = 104, W = 30, HZ = 12, BX = 24, BS = 19, BW = 16, CH = 6, LIFT = 18;
const LAYERS = [3, 2, 4, 2], REST = [0, 0, 3, 0], FAV = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[0, 0, 0], [L, W, 0], [L, 0, 0], [0, W, 0], [BX + 2 * BS, 4, HZ + 5 * CH + LIFT], [6, 4, HZ + 22]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the hull: a long rounded solid, the bow rounder than the stern, with a deck line
  const hull = solid(g);
  const [hr, hi] = rings(0, 0, L, W, 13, 1.8);
  put(hull, prism(P, front, hr, hi, 0, HZ));
  mk("path", { class: "nf lo", d: seg(P(4, W, 4), P(L - 12, W, 4)) }, hull.g);
  // the bridge at the stern
  const br = solid(g);
  const [rr, ri] = rings(4, 6, 16, W - 6, 2, 0.8);
  put(br, prism(P, front, rr, ri, HZ, HZ + 22));
  mk("path", { class: "nf lo", d: seg(P(16, 9, HZ + 18), P(16, W - 9, HZ + 18)) }, br.g);

  // the bays: a fixed stack and one top container that hoists
  const bays = [];
  for (let k = 0; k < N; k++) {
    const x = BX + k * BS, top = HZ + (LAYERS[k] - 1) * CH;
    const stack = solid(g);
    const [r, i] = rings(x, 4, x + BW, W - 4, 1.4, 0.6);
    put(stack, prism(P, front, r, i, HZ, top));
    let d = "";
    for (let l = 1; l < LAYERS[k] - 1; l++) d += seg(P(x + 1, W - 4, HZ + l * CH), P(x + BW - 1, W - 4, HZ + l * CH));
    mk("path", { class: "nf lo", d }, stack.g);
    const box = solid(g);
    const ribs = mk("path", { class: "nf lo" }, box.g);
    bays.push({ x, top, r, i, box, ribs, z: tween(REST[k]), last: NaN });
  }
  function draw(b, lift) {
    if (lift === b.last) return;
    b.last = lift;
    const z0 = b.top + lift;
    put(b.box, prism(P, front, b.r, b.i, z0, z0 + CH));
    let d = "";
    for (let u = 4; u < BW; u += 4) d += seg(P(b.x + u, W - 4, z0 + 1), P(b.x + u, W - 4, z0 + CH - 1));
    b.ribs.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    bays.forEach((b) => { draw(b, tval(b.z, now)); if (!tdone(b.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: inside the hull's footprint, then the bay whose rest centre is nearest on screen x
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, HZ);
    if (x < 0 || x > L + 4 || y < -8 || y > W + 4) return -1;
    let best = -1, bd = Infinity;
    bays.forEach((b, k) => { const d = Math.abs(P(b.x + BW / 2, W / 2, b.top)[0] - sx); if (d < bd) { bd = d; best = k; } });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    bays.forEach((b, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : clamp(5 - 2.5 * Math.abs(k - a), 0, 5);
      tset(b.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      b.box.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bay " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "cargoship",
  means: "A cargo ship with four bays of containers: the top box of the bay under the pointer is hoisted clear, its neighbours lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[163, 128], [231, 156], [265, 178], null],
  mount,
});

carbattery.code:
/**
 * Car battery: a rounded block with a lid, six cell caps in a row and two
 * terminal posts, each wearing a cable clamp whose cable runs over the lid
 * and down the front. The pointer picks a terminal by where it stands: its
 * clamp lifts off the post. At rest the negative clamp sits half off,
 * bright. The slider is how far a clamp lifts.
 *
 * The pattern: one of a few in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 72, D = 40, H = 34, LZ = H + 3, POSTS = [14, W - 14], PY = 11, FAV = 1;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[0, 0, 0], [W, D + 14, 0], [W, 0, 0], [0, D + 14, 0], [0, 0, LZ + 30], [W, 0, LZ + 30]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, D, 5, 2);
  put(solid(g), prism(P, front, br, bi, 0, H));
  const [lr, li] = rings(2, 2, W - 2, D - 2, 4, 1.5);
  put(solid(g), prism(P, front, lr, li, H, LZ));
  // six cell caps along the lid's middle
  for (let k = 0; k < 6; k++) {
    const x = 18 + k * 7.2;
    put(solid(g), prism(P, front, disc(x, D / 2 + 6, 2.2, 14), disc(x, D / 2 + 6, 1.4, 14), LZ, LZ + 1));
  }

  const items = POSTS.map((x, k) => {
    const grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, PY, 4.5), disc(x, PY, 3.4), LZ, LZ + 2));
    put(solid(grp), prism(P, front, disc(x, PY, 3), disc(x, PY, 2.2), LZ + 2, LZ + 8));
    const cable = mk("path", { class: "nf" }, grp), cable2 = mk("path", { class: "nf lo" }, grp);
    const clamp = solid(grp);
    return { k, x, grp, cable, cable2, clamp, z: tween(k === FAV ? 0.5 : 0), last: NaN };
  });

  function draw(it, t) {
    if (t === it.last) return;
    it.last = t;
    const z0 = LZ + 3 + t * lift, x = it.x;
    put(it.clamp, prism(P, front, disc(x, PY, 5.2), disc(x, PY, 4), z0, z0 + 4.5));
    // the cable leaves the clamp's front, droops onto the lid and runs down the face
    const path = (dx) => [[x + dx, PY + 5, z0 + 2], [x + dx, PY + 11, z0 + 1 - t * lift * 0.4], [x + dx, D - 4, LZ + 1.5], [x + dx, D + 1.5, LZ - 1],
      [x + dx, D + 1.5, 4], [x + dx, D + 4, 1], [x + dx, D + 14, 0.5]].map((q) => P(...q));
    it.cable.setAttribute("d", open(path(-1.6)));
    it.cable2.setAttribute("d", open(path(1.6)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, PY, LZ + 6));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, (m[1] - sy) * 0.6); if (dd < bd) { bd = dd; best = k; } });
    return bd < 55 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    items.forEach((it, k) => {
      tset(it.z, a < 0 ? (k === FAV ? 0.5 : 0) : k === a ? 1 : 0, now, 0);
      it.clamp.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : a === 0 ? "pos +" : "neg −";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = v; items.forEach((it) => { it.last = NaN; }); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "carbattery",
  means: "A car battery with two cable clamps: the clamp on the terminal under the pointer lifts off its post.",
  rules: [1, 4, 5, 6],
  range: [10, 22, 30],
  tour: [[189, 114], [270, 154], [194, 226], null],
  mount,
});

bottlingline.code:
/**
 * Bottling line: a short conveyor belt carrying five bottles, each with its
 * cap set on its neck. The pointer picks a bottle by where it is along the
 * belt: that cap lifts clear off its neck as if the capper had raised it, and
 * the neighbours' caps rise a little, staggered from it. At rest one cap sits
 * half seated, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is on a fixed plane
 * through the bottles' shoulders, nearest bottle along x.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, ringAt, run, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 12, X0 = 8, BELT = 0, R = 4.2, SH = 13, NK = 18, NT = 23, CAP = 3.4, LIFT = 17;
const L = X0 + (N - 1) * STEP + 8;
const REST = [0.3, 0.8, 4, 0.6, 0.2], FAV = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.8);
  fit(C, [[-8, -7, -5], [L, 7, -5], [L, -7, -5], [-8, 7, -5], [X0, 0, NT + CAP + LIFT], [L, 0, NT + CAP + LIFT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the belt: a long rounded slab, rollers marked on its near side, a lane line on top
  const [br, bi] = rings(-8, -7, L, 7, 6, 1.2);
  const belt = solid(g);
  put(belt, prism(P, front, br, bi, -5, BELT));
  let marks = seg(P(-2, -3.5, BELT), P(L - 4, -3.5, BELT)) + seg(P(-2, 3.5, BELT), P(L - 4, 3.5, BELT));
  for (let k = 0; k <= N; k++) marks += seg(P(X0 - 6 + k * STEP, 7, -1.5), P(X0 - 6 + k * STEP, 7, -3.5));
  mk("path", { class: "nf lo", d: marks }, belt.g);

  const body = circ(R, 16), bodyIn = circ(R - 1, 16), neck = circ(1.9, 12), capR = circ(2.4, 12), capIn = circ(1.7, 12);
  const at = (ring, x) => ring.map((s) => ({ ...s, u: s.u + x }));
  const bottles = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP;
    const b = solid(g);
    b.sil.setAttribute("d", poly(hull(ringAt(P, at(body, x), BELT).concat(ringAt(P, at(body, x), SH), ringAt(P, at(neck, x), NK), ringAt(P, at(neck, x), NT)))));
    b.cr.setAttribute("d", open(ringAt(P, run(at(bodyIn, x), front), SH)) + open(ringAt(P, run(at(body, x), front), 4)));
    const cap = solid(g);
    bottles.push({ x, cap, z: tween(REST[k]), last: NaN });
  }

  function draw(b, lift) {
    if (lift === b.last) return;
    b.last = lift;
    put(b.cap, prism(P, front, at(capR, b.x), at(capIn, b.x), NT - 2.5 + lift, NT - 2.5 + lift + CAP));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    bottles.forEach((b) => { draw(b, tval(b.z, now)); if (!tdone(b.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, SH);
    if (x < -8 || x > L || y < -12 || y > 12) return -1;
    return clamp(Math.round((x - X0) / STEP), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    bottles.forEach((b, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : Math.max(0, 3 - 1.2 * Math.abs(k - a));
      tset(b.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      b.cap.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "cap " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "bottlingline",
  means: "Five bottles on a conveyor: the cap of the bottle under the pointer lifts off its neck, the neighbours' caps rise a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[146, 138], [232, 180], [275, 202], null],
  mount,
});

roller.code:
/**
 * Road roller: a tandem roller on a strip of fresh paving, two steel drums
 * under a low body and an open cab. The pointer stands on the road and the
 * roller rolls toward it, drums turning as they go; the drum leading the way
 * is bright. At rest it has stopped a little short of the middle. The slider
 * is how far it may roll.
 *
 * The pattern: one object answering where the pointer stands (terrain).
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rings, ringAt, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 34, R = 11, RD = 2, MID = 40, REST = -7;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-40, -8, 0], [120, W + 8, 0], [120, -8, 0], [-40, W + 8, 0], [40, W / 2, 46]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [gr, gi] = rings(-40, -8, 120, W + 8, 6, 2);
  put(solid(g), prism(P, front, gr, gi, 0, RD));
  const seam = mk("path", { class: "dash nf" }, g);
  seam.setAttribute("d", "M" + P(-36, W / 2, RD).join(",") + "L" + P(116, W / 2, RD).join(","));

  // drums: [x at rest, solid, spoke]
  const mkDrum = () => { const s = solid(mk("g", {}, g)); return { s, spoke: mk("path", { class: "lo nf" }, s.g) }; };
  const rear = mkDrum();
  const body = solid(mk("g", {}, g)), cab = solid(mk("g", {}, g)), roof = solid(mk("g", {}, g));
  const fore = mkDrum();

  function disk(x, y, zc, r, n = 32) {
    const out = [];
    for (let i = 0; i < n; i++) { const a = (i / n) * Math.PI * 2; out.push(P(x + r * Math.cos(a), y, zc + r * Math.sin(a))); }
    return out;
  }
  function drum(d, x, ang) {
    const zc = RD + R, a = disk(x, 2, zc, R), b = disk(x, W - 2, zc, R);
    d.s.sil.setAttribute("d", poly(hull(a.concat(b))));
    d.s.cr.setAttribute("d", poly(b));
    let s = "";
    for (let k = 0; k < 3; k++) {
      const t = ang + (k * Math.PI * 2) / 3;
      s += "M" + P(x + 2.5 * Math.cos(t), W - 2, zc + 2.5 * Math.sin(t)).join(",") + "L" + P(x + (R - 2) * Math.cos(t), W - 2, zc + (R - 2) * Math.sin(t)).join(",");
    }
    d.spoke.setAttribute("d", s + poly(disk(x, W - 2, zc, 2.5, 12)));
  }
  function box(s, x0, y0, x1, y1, z0, z1, r, b) { const [a, i] = rings(x0, y0, x1, y1, r, b); put(s, prism(P, front, a, i, z0, z1)); }

  let last = NaN;
  function draw(d) {
    if (d === last) return;
    last = d;
    const ang = -d / R;
    drum(rear, 8 + d, ang);
    box(body, 16 + d, 3, 64 + d, W - 3, RD + 9, RD + 22, 4, 1.6);
    box(cab, 30 + d, 7, 50 + d, W - 7, RD + 22, RD + 38, 3, 1.4);
    box(roof, 27 + d, 4, 53 + d, W - 4, RD + 38, RD + 41, 3, 1);
    drum(fore, 72 + d, ang);
  }

  const pos = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(pos, dt); draw(pos.x); return m; });
  bag.add(B.unregister);

  function lead(dir) {
    fore.s.sil.classList.toggle("hi", dir >= 0);
    rear.s.sil.classList.toggle("hi", dir < 0);
  }
  function aim(p) {
    if (!p) { pos.t = REST; lead(1); read.textContent = "rest"; B.wake(); return; }
    const [wx, wy] = unproj(C, p[0], p[1], 0);
    if (wy < -30 || wy > W + 30) return aim(null);
    const t = clamp(wx - MID, -reach, reach);
    lead(t - pos.t === 0 ? (t >= pos.x ? 1 : -1) : t - pos.t);
    pos.t = t;
    read.textContent = (t >= 0 ? "+" : "") + (t / 10).toFixed(1) + " m";
    B.wake();
  }
  draw(REST);
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "roller",
  means: "A tandem road roller on fresh paving: it rolls toward the pointer along the road, drums turning, the leading drum bright.",
  rules: [1, 3, 4, 5, 8],
  range: [6, 22, 34],
  tour: [[150, 200], [250, 200], [200, 170], null],
  mount,
});

sitecabin.code:
/**
 * Site cabin: a steel office container on two skids, a window on its long
 * side and a door beside it. The pointer over the cabin swings the door open
 * on its hinge; leaving lets it fall back ajar. At rest the door stands a
 * little open, bright. The slider is how far it swings.
 *
 * The pattern: one part answering whether the pointer is over the object.
 */
const {
  Cam, clamp, fit, facing, poly, prism, proj, rings, rrect, ringAt, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 84, D = 32, Z0 = 5, H = 32, HX = 52, DW = 14, AJAR = 22;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let wide = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[-8, -8, 0], [L + 8, D + 8, 0], [L + 8, -8, 0], [-8, D + 20, 0], [0, 0, Z0 + H + 3], [L, D, Z0 + H + 3]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [gr, gi] = rings(-8, -8, L + 8, D + 20, 6, 2);
  put(solid(g), prism(P, front, gr, gi, 0, 2));
  for (const y of [4, D - 4]) { const [a, i] = rings(-1, y - 2.5, L + 1, y + 2.5, 1.5, 0.8); put(solid(g), prism(P, front, a, i, 2, Z0)); }
  const [br, bi] = rings(0, 0, L, D, 2.5, 1.6);
  put(solid(g), prism(P, front, br, bi, Z0, Z0 + H));
  const [rr, ri] = rings(-2, -2, L + 2, D + 2, 3, 1.4);
  put(solid(g), prism(P, front, rr, ri, Z0 + H, Z0 + H + 2.5));

  // marks on the near faces: ribs on the long side, a window, the doorway
  const face = (pts) => poly(pts.map(([x, z]) => P(x, D, z)));
  const side = (pts) => poly(pts.map(([y, z]) => P(L, y, z)));
  const win = (x0, x1, z0, z1) => face(rrect(x0, z0, x1, z1, 1.5, 3).map((q) => [q.u, q.v]));
  mk("path", { class: "lo nf", d: win(12, 38, Z0 + 14, Z0 + 25) }, g);
  mk("path", { class: "lo nf", d: side(rrect(9, Z0 + 14, D - 9, Z0 + 25, 1.5, 3).map((q) => [q.u, q.v])) }, g);
  mk("path", { class: "lo nf", d: face([[HX, Z0 + 2], [HX + DW, Z0 + 2], [HX + DW, Z0 + 27], [HX, Z0 + 27]]) }, g);
  const step = solid(mk("g", {}, g));
  const [sr, si] = rings(HX - 2, D, HX + DW + 2, D + 8, 1.5, 1);
  put(step, prism(P, front, sr, si, 2, Z0));

  const door = mk("path", { class: "sil" }, g), edge = mk("path", { class: "lo nf" }, g), knob = mk("path", { class: "lo nf" }, g);
  const ang = tween(AJAR);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const t = (a * Math.PI) / 180, ex = HX + DW * Math.cos(t), ey = D + DW * Math.sin(t);
    const tx = -1.2 * Math.sin(t), ty = 1.2 * Math.cos(t);
    const q = (x, y, z) => P(x, y, z);
    door.setAttribute("d", poly([q(HX, D, Z0 + 2), q(ex, ey, Z0 + 2), q(ex + tx, ey + ty, Z0 + 2), q(ex + tx, ey + ty, Z0 + 27), q(HX + tx, D + ty, Z0 + 27), q(HX, D, Z0 + 27)]));
    edge.setAttribute("d", "M" + q(ex, ey, Z0 + 2).join(",") + "L" + q(ex, ey, Z0 + 27).join(",") + "L" + q(HX, D, Z0 + 27).join(","));
    const k = 0.82, kx = HX + DW * k * Math.cos(t) + tx, ky = D + DW * k * Math.sin(t) + ty;
    knob.setAttribute("d", "M" + q(kx, ky, Z0 + 13).join(",") + "L" + q(kx, ky, Z0 + 16).join(","));
  }
  door.classList.add("hi");

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let inside = null;
  function aim(p) {
    let on = false;
    if (p) { const [wx, wy] = unproj(C, p[0], p[1], 0); on = wx > -10 && wx < L + 10 && wy > -10 && wy < D + 24; }
    if (on === inside) return;
    inside = on;
    tset(ang, on ? clamp(wide, AJAR, 120) : AJAR, performance.now(), 0);
    read.textContent = on ? "open " + Math.round(wide) + "°" : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { wide = v; if (inside) { inside = null; } }, destroy: bag.dispose };
}

hairline({
  name: "sitecabin",
  means: "A steel site cabin on skids: the pointer over it swings the door open on its hinge, and leaving lets it fall back ajar.",
  rules: [1, 4, 5, 8],
  range: [50, 95, 120],
  tour: [[150, 160], [240, 200], [200, 140], null],
  mount,
});

thermometers.code:
/**
 * Thermometers: five glass thermometers standing in a rounded rack, each a
 * bulb and a tall tube with a few graduation ticks and a mercury column. The
 * pointer picks one by where it is along the row: it lifts out of the rack
 * and its column climbs to a fever, the neighbours rise a little after it.
 * At rest they stand at uneven heights, the middle one reading high, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row, picked by rest centre on screen x.
 */
const {
  Cam, circ, clamp, facing, fit, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 12, TOP = 8, BR = 3.8, TR = 2.5, BH = 8, TH = 46, LIFT = 16;
const REST = [0.2, 0.05, 0.45, 0.12, 0.28], FAV = 2, TEMPS = ["36.6", "37.1", "38.4", "36.9", "37.5"];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.9);
  const X1 = (N - 1) * STEP;
  fit(C, [[-7, -7, 0], [X1 + 7, 7, 0], [X1 + 7, -7, 0], [-7, 7, 0], [0, 0, TOP + LIFT + BH + TH], [X1, 0, TOP + LIFT + BH + TH]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the rack: one rounded block with a cup per thermometer on its top
  const rack = solid(g), [ro, ri] = rings(-7, -7, X1 + 7, 7, 6, 1.2);
  put(rack, prism(P, front, ro, ri, 0, TOP));
  const cups = [];
  for (let k = 0; k < N; k++) {
    const pts = circ(BR + 1.2, 16).map((s) => P(k * STEP + s.u, s.v, TOP));
    cups.push("M" + pts.map((p) => p.join(",")).join("L") + "Z");
  }
  mk("path", { class: "nf lo", d: cups.join("") }, rack.g);

  const bulbRing = circ(BR, 16), bulbIn = circ(BR - 0.8, 16), tubeRing = circ(TR, 16), tubeIn = circ(TR - 0.6, 16);
  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    items.push({ k, x: k * STEP, bulb: solid(grp), tube: solid(grp), col: mk("path", { class: "nf" }, grp), e: tween(REST[k]), last: NaN });
  }
  const shift = (ring, x) => ring.map((s) => ({ ...s, u: s.u + x }));
  function draw(it, e) {
    if (e === it.last) return;
    it.last = e;
    const z0 = TOP + e * LIFT, zb = z0 + BH, zt = zb + TH;
    put(it.bulb, prism(P, front, shift(bulbRing, it.x), shift(bulbIn, it.x), z0, zb));
    put(it.tube, prism(P, front, shift(tubeRing, it.x), shift(tubeIn, it.x), zb, zt));
    const fx = it.x + TR * 0.5, fy = TR * 0.5, lvl = zb + 4 + (TH - 10) * (0.25 + 0.7 * e);
    let d = seg(P(fx, fy, zb + 1), P(fx, fy, lvl));
    for (let t = 1; t <= 5; t++) { const z = zb + t * (TH / 6); d += seg(P(fx + 0.9, fy + 0.9, z), P(fx + 0.9, fy + 0.9, z + 0.01)) + seg(P(fx - 1.4, fy + 1.4, z), P(fx + 1.4, fy + 1.4, z)); }
    it.col.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    items.forEach((it) => { draw(it, tval(it.e, now)); if (!tdone(it.e, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest rest centre along screen x, inside the row's band
  const cx = items.map((it) => P(it.x, 0, TOP)[0]);
  const yTop = P(0, 0, TOP + LIFT + BH + TH)[1] - 4, yBot = P(X1 + 7, 7, 0)[1] + 4;
  function hit([sx, sy]) {
    if (sy < yTop || sy > yBot) return -1;
    let best = -1, bd = 1e9;
    cx.forEach((x, k) => { const d = Math.abs(sx - x); if (d < bd) { bd = d; best = k; } });
    return bd < STEP * C.S * 0.75 + 6 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const e = a < 0 ? REST[k] : k === a ? 1 : clamp(0.3 - Math.abs(k - a) * 0.08, 0.05, 0.3);
      tset(it.e, e, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      it.bulb.sil.classList.toggle("hi", on);
      it.tube.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : TEMPS[a] + "°";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "thermometers",
  means: "A rack of thermometers: the one under the pointer lifts out and its column climbs, the others rise a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[151, 132], [225, 169], [249, 181], null],
  mount,
});

ricecooker.code:
/**
 * Rice cooker: a rounded body with a domed lid hinged at the back, a pot rim
 * inside, a handle and a switch on the front. The pointer over the cooker
 * swings the lid open on its hinge and steam rises from the pot in dashed
 * wisps. At rest the lid sits a little ajar, bright. The slider is how far
 * the lid opens.
 *
 * The pattern: one part swinging on a hinge; the hit is the body's rest top.
 */
const {
  Cam, clamp, facing, fit, hull, open, poly, prism, proj, rad, rrect, ringAt, run, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 17, H = 22, LT = 3, DOME = 6, HY = -R;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 4.4);
  fit(C, [[-R, -R, 0], [R, R, 0], [R, -R, 0], [-R, R, 0], [0, -R - 8, H + 2 * R], [0, 0, H + 26]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the body, with the pot rim on its top, a handle and a switch on the near faces
  const body = solid(g);
  put(body, prism(P, front, rrect(-R, -R, R, R, 13, 14), rrect(-R + 1.4, -R + 1.4, R - 1.4, R - 1.4, 11.6, 14), 0, H));
  mk("path", {
    class: "nf lo",
    d: poly(ringAt(P, rrect(-R + 4, -R + 4, R - 4, R - 4, 9, 14), H)) +
      seg(P(-5, R, 14), P(5, R, 14)),
  }, body.g);

  // the lid: a plate and a dome, hinged along x at the back edge
  const foot = rrect(-R, -R, R, R, 13, 14), top = rrect(-R + 5, -R + 5, R - 5, R - 5, 8, 14), inner = rrect(-R + 6.4, -R + 6.4, R - 6.4, R - 6.4, 6.6, 14);
  const steam = mk("path", { class: "nf dash" }, g);
  const lid = solid(g);
  const ang = tween(8);
  let last = NaN;
  function lidPts(ring, z, a) {
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    return ring.map((p) => { const dy = p.v - HY, dz = z - H; return P(p.u, HY + dy * c - dz * s, H + dy * s + dz * c); });
  }
  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = lidPts(foot, H, a).concat(lidPts(foot, H + LT, a), lidPts(top, H + LT + DOME, a));
    lid.sil.setAttribute("d", poly(hull(pts)));
    lid.cr.setAttribute("d", open(lidPts(run(inner, front), H + LT + DOME, a)) + open(lidPts(run(foot, front), H + LT, a)));
    const k = clamp((a - 20) / 50, 0, 1);
    let d = "";
    if (k > 0.02) for (let i = -1; i <= 1; i++) {
      const w = [];
      for (let j = 0; j <= 8; j++) w.push(P(i * 6 + 2.2 * Math.sin(j * 0.9 + i), i * 3, H + 2 + j * 3.2 * k));
      d += open(w);
    }
    steam.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    return Math.abs(x) < R + 3 && Math.abs(y) < R + 3;
  }
  let on = null;
  function setOpen(o) {
    if (o === on) return;
    on = o;
    tset(ang, o ? maxA : 8, performance.now(), 0);
    lid.sil.classList.add("hi");
    read.textContent = o ? "open" : "rest";
    B.wake();
  }
  setOpen(false);
  bag.add(pointer(stage, { move: (p) => setOpen(hit(p)), leave: () => setOpen(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; if (on) { tset(ang, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "ricecooker",
  means: "A rice cooker: over it the lid swings open on its back hinge and steam rises from the pot.",
  rules: [1, 3, 5, 6],
  range: [40, 75, 95],
  tour: [[200, 160], [215, 170], [185, 150], null],
  mount,
});

pooltable.code:
/**
 * Pool table: a felt table on four legs, a rack of balls at the far end, the
 * cue ball on the spot and the cue resting behind it. The cue turns about
 * the cue ball to line up on the pointer, on a spring, so the shot always
 * points where the hand is. At rest it lines up on the rack, bright.
 * The slider is the cue's draw-back from the ball.
 *
 * The pattern: one part turning to face the pointer (aim).
 */
const {
  Cam, clamp, fit, facing, open, poly, prism, proj, rings, rrect, ringAt, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 120, D = 64, TZ = 26, BX = 32, BY = 32, CL = 52, BR = 2.6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gap = value;
  const C = Cam(45, 0.5, 1.9);
  const reach = [];
  for (let i = 0; i < 8; i++) { const a = (i / 8) * Math.PI * 2; reach.push([BX + 40 * Math.cos(a), BY + 40 * Math.sin(a), TZ + 3]); }
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, TZ], [0, D, TZ], ...reach], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  for (const [x, y] of [[6, 6], [W - 12, 6], [6, D - 12], [W - 12, D - 12]]) {
    const [r, i] = rings(x, y, x + 6, y + 6, 2, 1);
    put(solid(g), prism(P, front, r, i, 0, 14));
  }
  const [ring, inner] = rings(0, 0, W, D, 6, 2);
  put(solid(g), prism(P, front, ring, inner, 14, TZ));
  mk("path", { d: poly(ringAt(P, rrect(7, 7, W - 7, D - 7, 3, 4), TZ)), class: "nf lo" }, g);
  for (const [x, y] of [[5, 5], [W / 2, 4], [W - 5, 5], [5, D - 5], [W / 2, D - 4], [W - 5, D - 5]]) {
    const p = P(x, y, TZ);
    mk("ellipse", { cx: p[0], cy: p[1], rx: 3.4, ry: 1.9, class: "lo" }, g);
  }
  // the rack: a triangle of balls, apex toward the cue ball, painted far to near
  const rack = [];
  for (let c = 0; c < 4; c++) for (let r = 0; r <= c; r++) rack.push([88 + c * 4.6, BY + (r - c / 2) * 5.4]);
  rack.sort((a, b) => a[0] + a[1] - b[0] - b[1]);
  const R = BR * C.S;
  for (const [x, y] of rack) { const p = P(x, y, TZ + BR); mk("ellipse", { cx: p[0], cy: p[1], rx: R, ry: R }, g); }
  const cb = P(BX, BY, TZ + BR);
  const cueBall = mk("ellipse", { cx: cb[0], cy: cb[1], rx: R, ry: R }, g);
  const cue = mk("path", { class: "sil hi" }, g), tip = mk("path", { class: "nf lo" }, g);
  const ang = spring(0);
  let last = NaN, lastGap = NaN;
  function draw(a) {
    if (a === last && gap === lastGap) return;
    last = a; lastGap = gap;
    const ux = Math.cos(a), uy = Math.sin(a), nx = -uy, ny = ux;
    const at = (d, w, z) => P(BX - ux * d + nx * w, BY - uy * d + ny * w, z);
    const d0 = BR + 2 + gap, d1 = d0 + CL;
    cue.setAttribute("d", poly([at(d0, -0.7, TZ + BR), at(d0, 0.7, TZ + BR), at(d1, 1.6, TZ + BR + 7), at(d1, -1.6, TZ + BR + 7)]));
    tip.setAttribute("d", open([at(d0 + 3, -0.9, TZ + BR + 0.4), at(d0 + 3, 0.9, TZ + BR + 0.4)]));
    // keep the cue behind the ball when it reaches away from the viewer
    if (ux + uy > 0) cue.after(cueBall), tip.after(cueBall); else cueBall.after(tip);
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  let on = false;
  function aim([sx, sy]) {
    on = true;
    const [wx, wy] = unproj(C, sx, sy, TZ);
    const dx = wx - BX, dy = wy - BY;
    if (Math.hypot(dx, dy) < 6) return;
    let t = Math.atan2(dy, dx);
    while (t - ang.t > Math.PI) t -= 2 * Math.PI;
    while (t - ang.t < -Math.PI) t += 2 * Math.PI;
    ang.t = t;
    let deg = Math.round((t * 180) / Math.PI) % 360;
    if (deg < 0) deg += 360;
    read.textContent = "aim " + deg + "°";
    B.wake();
  }
  function leave() { on = false; ang.t = Math.round(ang.t / (2 * Math.PI)) * 2 * Math.PI; read.textContent = "rest"; B.wake(); }
  draw(0);
  leave();
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { gap = clamp(v, 0, 12); draw(ang.x); }, destroy: bag.dispose };
}

hairline({
  name: "pooltable",
  means: "A pool table with a racked set of balls: the cue turns about the cue ball to line up its shot on the pointer.",
  rules: [1, 3, 5, 8],
  range: [0, 4, 12],
  tour: [[200, 120], [120, 200], [290, 210], null],
  mount,
});

petcarrier.code:
/**
 * Pet carrier: a rounded travel crate with a carry handle, vent slots and a
 * barred door on its front. The pointer swings the door open on its hinge,
 * further the further right it goes; once the door is well open two eyes
 * show in the dark of the doorway. At rest the door stands ajar, bright.
 * The slider is how far the door may open.
 *
 * The pattern: one part following the pointer on a spring (aim).
 */
const {
  Cam, clamp, fit, facing, fillet, open, poly, prism, proj, rad, rings, ringAt, run, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 60, D = 40, H = 36, HY = 34, DW = 26, DZ0 = 6, DZ1 = 30, REST = 32;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[0, 0, 0], [W, D, 0], [W + DW, HY, 0], [W + DW, HY, DZ1], [0, 0, H + 12], [W, 0, H], [0, D, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the shell: lower tub and upper hood with a seam between them
  const [ring, inner] = rings(0, 0, W, D, 7, 2);
  put(solid(g), prism(P, front, ring, inner, 0, H));
  mk("path", { d: open(ringAt(P, run(ring, front), 15)), class: "nf lo" }, g);
  // carry handle: posts and a grip arching over the hood
  const hp = [];
  for (let i = 0; i <= 10; i++) { const t = (i / 10) * Math.PI; hp.push(P(W / 2 - 13 * Math.cos(t), D / 2, H + 9 * Math.sin(t))); }
  mk("path", { d: open(hp), class: "nf" }, g);
  mk("path", { d: open(hp.map(([x, y]) => [x, y + 2.4])), class: "nf lo" }, g);
  // vent slots on the left side (y = D)
  let vd = "";
  for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++) vd += seg(P(10 + c * 14, D, 20 + r * 4), P(18 + c * 14, D, 20 + r * 4));
  mk("path", { d: vd, class: "nf lo" }, g);
  // the doorway on the right side (x = W)
  const opening = fillet([P(W, HY, DZ0), P(W, HY - DW, DZ0), P(W, HY - DW, DZ1), P(W, HY, DZ1)], [3, 3, 3, 3]);
  mk("path", { d: poly(opening), class: "lo" }, g);
  const eyes = [P(W, HY - 9, 19), P(W, HY - 16, 19)].map((p) => mk("circle", { cx: p[0], cy: p[1], r: 1.6, class: "dot off" }, g));
  // the door: a barred plate turning about the hinge at y = HY
  const door = mk("path", { class: "sil hi" }, g), bars = mk("path", { class: "nf lo" }, g);
  const ang = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    const at = (t, z) => P(W + t * DW * s, HY - t * DW * c, z);
    door.setAttribute("d", poly(fillet([at(0, DZ0), at(1, DZ0), at(1, DZ1), at(0, DZ1)], [3, 3, 3, 3])));
    let bd = "";
    for (let i = 1; i < 6; i++) bd += seg(at(i / 6, DZ0 + 2), at(i / 6, DZ1 - 2));
    bd += seg(at(0.06, (DZ0 + DZ1) / 2), at(0.94, (DZ0 + DZ1) / 2));
    bars.setAttribute("d", bd);
    eyes.forEach((e) => e.setAttribute("class", a > 60 ? "dot m" : "dot off"));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  const x0 = P(0, D, 0)[0], x1 = P(W + DW, HY, 0)[0];
  let on = false;
  function aim([sx]) {
    on = true;
    const a = Math.round(clamp((sx - x0) / (x1 - x0), 0, 1) * maxA);
    ang.t = a;
    read.textContent = a < 4 ? "shut" : "door " + a + "°";
    B.wake();
  }
  function leave() { on = false; ang.t = Math.min(REST, maxA); read.textContent = "rest"; B.wake(); }
  draw(REST);
  leave();
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; if (!on) leave(); }, destroy: bag.dispose };
}

hairline({
  name: "petcarrier",
  means: "A travel crate with a barred door: the pointer swings the door open on its hinge, and two eyes show in the doorway.",
  rules: [1, 3, 5, 8],
  range: [60, 110, 140],
  tour: [[160, 170], [260, 170], [320, 170], null],
  mount,
});

theodolite.code:
/**
 * Theodolite: a surveyor's instrument on a tripod over a station mark, a
 * plumb line hanging to the ground. The pointer is a point on the site: the
 * alidade turns to face it and the telescope dips toward it, the nearer the
 * steeper. At rest it sights a peg standing in the ground, bright. The
 * slider is how far the telescope may dip.
 *
 * The pattern: one part turning to face the pointer (aim).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, rrect, unproj, clamp, rad, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const H = 58, TZ = H + 19, PEG = [56, -14];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const rot = (ring, a) => { const c = Math.cos(a), s = Math.sin(a); return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c })); };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[-36, -36, 0], [-34, 30, 0], [30, -34, 0], [0, 0, TZ + 8], [PEG[0], PEG[1], 10]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // station mark and plumb line, behind everything that stands
  const mark = flatDot(g, C, 2.4, "dot off");
  place(mark, P(0, 0, 0));
  mk("path", { d: open([P(0, 0, H - 1), P(0, 0, 3)]), class: "dash" }, g);

  // the peg, rest target
  const pegG = mk("g", {}, g);
  put(solid(pegG), prism(P, front, disc(PEG[0], PEG[1], 1.6, 12), disc(PEG[0], PEG[1], 0.8, 12), 0, 10));
  const pegDot = flatDot(pegG, C, 2, "dot");
  place(pegDot, P(PEG[0], PEG[1], 10));

  // three legs, far to near
  const feet = [rad(-135), rad(-15), rad(105)].map((a) => [34 * Math.cos(a), 34 * Math.sin(a), a])
    .sort((p, q) => p[0] + p[1] - (q[0] + q[1]));
  for (const [fx, fy, a] of feet) {
    const tx = 5 * Math.cos(a), ty = 5 * Math.sin(a), s = solid(g);
    s.sil.setAttribute("d", poly(hull(ringAt(P, disc(fx, fy, 1.4, 12), 0).concat(ringAt(P, disc(tx, ty, 2.4, 12), H)))));
    s.cr.setAttribute("d", open([P(fx * 0.55 + tx * 0.45, fy * 0.55 + ty * 0.45, H * 0.45), P(fx * 0.5 + tx * 0.5, fy * 0.5 + ty * 0.5, H * 0.5)]));
    s.cr.setAttribute("class", "nf lo");
  }
  // head plate and tribrach
  const [hr, hi] = rings(-9, -9, 9, 9, 9, 1.4);
  put(solid(g), prism(P, front, hr, hi, H, H + 2.5));
  put(solid(g), prism(P, front, disc(0, 0, 6.5), disc(0, 0, 5.2), H + 2.5, H + 5));

  const body = solid(g), scope = mk("path", { class: "sil" }, g), lens = mk("path", { class: "nf lo" }, g);
  const az = spring(Math.atan2(PEG[1], PEG[0])), pit = spring(0);
  let last = "";

  function draw() {
    const a = az.x, p = pit.x, key = a.toFixed(4) + p.toFixed(4);
    if (key === last) return;
    last = key;
    const [br, bi] = [rot(rrect(-8, -6, 8, 6, 3, 4), a), rot(rrect(-6.6, -4.6, 6.6, 4.6, 1.8, 4), a)];
    put(body, prism(P, front, br, bi, H + 5, H + 15));
    const d = [Math.cos(a) * Math.cos(p), Math.sin(a) * Math.cos(p), Math.sin(p)];
    const e1 = [-Math.sin(a), Math.cos(a), 0], e2 = [-Math.cos(a) * Math.sin(p), -Math.sin(a) * Math.sin(p), Math.cos(p)];
    const ring = (off, r) => { const o = []; for (let i = 0; i < 24; i++) { const t = (i / 24) * 2 * Math.PI, c = Math.cos(t) * r, s = Math.sin(t) * r; o.push(P(d[0] * off + e1[0] * c + e2[0] * s, d[1] * off + e1[1] * c + e2[1] * s, TZ + d[2] * off + e1[2] * c + e2[2] * s)); } return o; };
    const obj = ring(17, 4.6);
    scope.setAttribute("d", poly(hull(obj.concat(ring(-13, 3.2)))));
    lens.setAttribute("d", front({ nu: Math.cos(a), nv: Math.sin(a) }) ? poly(ring(16, 3.4)) : poly(ring(4, 4.1)));
  }

  const B = register(stage, (dt) => { const m = stepS(az, dt) | stepS(pit, dt); draw(); return !!m; });
  bag.add(B.unregister);

  function aim(w) {
    const t = Math.atan2(w[1], w[0]);
    let dt = t - az.t; dt -= Math.round(dt / (2 * Math.PI)) * 2 * Math.PI;
    az.t += dt;
    pit.t = -clamp(Math.atan2(TZ, Math.hypot(w[0], w[1]) + 1) * 0.6, 0, rad(reach));
  }
  function setActive(w) {
    const on = !!w;
    aim(on ? w : PEG);
    if (!on) pit.t = -rad(Math.min(reach, 8));
    scope.classList.toggle("hi", on);
    pegDot.setAttribute("class", on ? "dot off" : "dot");
    const deg = ((Math.round((az.t * 180) / Math.PI) % 360) + 360) % 360;
    read.textContent = on ? String(deg).padStart(3, "0") + "°" : "rest";
    B.wake();
  }
  setActive(null);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { const w = unproj(C, sx, sy, 0); setActive(Math.hypot(w[0], w[1]) < 140 ? w : null); },
    leave: () => setActive(null),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

