newsstand.code:
/**
 * Newsstand: a kiosk counter with a back rack and a row of magazines standing
 * on it, a bundle of papers lying in front. The pointer picks a magazine by
 * where it stands: it slides up out of the row, and its neighbours rise a
 * little, staggered from it. At rest one magazine is half drawn, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 25, W = 21, MH = 30, LIFT = 20, FAV = 2, CZ = 26, MY = 6;
const X1 = (N - 1) * STEP + W + 8;
const REST = [4, 9, 12, 2, 7];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[-4, -10, 0], [X1, 30, 0], [X1, -10, 0], [-4, 30, 0], [-4, -10, CZ + MH + LIFT + 4], [X1, -10, CZ + MH + LIFT + 4]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // counter, then the rack behind the row
  const [cr, ci] = rings(-4, -10, X1, 30, 5, 2);
  put(solid(g), prism(P, front, cr, ci, 0, CZ));
  const [br, bi] = rings(-4, -10, X1, -5, 2, 0.8);
  put(solid(g), prism(P, front, br, bi, CZ, CZ + MH - 4));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 4 + k * STEP, grp = mk("g", {}, g), s = solid(grp);
    const [r, i] = rings(x, MY, x + W, MY + 3, 1.4, 0.6);
    // the cover's spine fold: one dim mark down its face
    const fold = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, s, r, i, fold, z: tween(REST[k]), last: NaN });
  }
  // a tied bundle of papers in front of the row
  const pg = mk("g", {}, g);
  const [pr, pi] = rings(36, 15, 84, 27, 2, 1);
  put(solid(pg), prism(P, front, pr, pi, CZ, CZ + 6));
  const tie = mk("path", { class: "nf lo" }, pg);
  tie.setAttribute("d", "M" + P(60, 27, CZ).join(",") + "L" + P(60, 27, CZ + 6).join(",") + "L" + P(60, 15, CZ + 6).join(","));

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    put(it.s, prism(P, front, it.r, it.i, CZ + lift, CZ + MH + lift));
    const a = P(it.x + 3, MY + 3, CZ + lift + 3), b = P(it.x + 3, MY + 3, CZ + MH + lift - 3);
    it.fold.setAttribute("d", "M" + a.join(",") + "L" + b.join(","));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + W / 2, MY, CZ + MH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && Math.abs(mids[best][1] - sy) < 55 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? REST[k] : dd === 0 ? LIFT : dd === 1 ? REST[k] * 0.4 + 3 : REST[k] * 0.3;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "mag " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "newsstand",
  means: "A kiosk counter lined with magazines: the one under the pointer slides up out of the row, its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[152, 139], [205, 148], [258, 160], null],
  mount,
});

poolladder.code:
/**
 * Pool ladder: a pool's coping wall, the water in front of it, and a ladder
 * of two bent rails with three treads hanging into the water, a ripple round
 * each rail foot. The pointer picks a tread by its rest place: it presses
 * down under a foot, and the treads beside it give a little, staggered from
 * it. At rest the middle tread is bright. The slider is the stagger.
 *
 * The pattern: one of many in a stepped column (picked by rest centres).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const WZ = 14, TOP = 50, RZ = 64, Y0 = 28, Y1 = 62, TX0 = 41, TX1 = 53, TZ = [20, 31, 42], PRESS = 7, FAV = 1;
const disc = (x, y, r, n = 14) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [130, 90, 0], [130, 0, 0], [0, 90, 0], [0, 0, TOP], [30, Y0, RZ + 2], [30, Y1, RZ + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [wr, wi] = rings(0, 0, 40, 90, 3, 1.6);
  put(solid(g), prism(P, front, wr, wi, 0, TOP));
  const [qr, qi] = rings(40, 0, 130, 90, 3, 2);
  put(solid(g), prism(P, front, qr, qi, 0, WZ));
  // a ripple round each rail foot
  for (const y of [Y0, Y1]) mk("path", { d: poly(ringAt(P, disc(46, y, 5, 28), WZ)), class: "nf lo" }, g);

  function rail(y) {
    const rg = mk("g", {}, g), r = 1.6;
    put(solid(rg), prism(P, front, disc(31, y, r), disc(31, y, r - 0.6), TOP, RZ));
    const arm = [];
    for (const x of [31, 46]) arm.push(...ringAt(P, disc(x, y, r), RZ - r), ...ringAt(P, disc(x, y, r), RZ + r));
    mk("path", { d: poly(hull(arm)), class: "sil" }, rg);
    put(solid(rg), prism(P, front, disc(46, y, r), disc(46, y, r - 0.6), WZ, RZ));
  }
  rail(Y0);
  const items = TZ.map((z, k) => {
    const s = solid(g), [r, i] = rings(TX0, Y0, TX1, Y1, 1.4, 0.8);
    return { k, z, s, r, i, d: tween(0), last: NaN };
  });
  rail(Y1);

  function draw(it, dz) {
    if (dz === it.last) return;
    it.last = dz;
    put(it.s, prism(P, front, it.r, it.i, it.z - dz, it.z - dz + 2.4));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.d, now)); if (!tdone(it.d, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P((TX0 + TX1) / 2, (Y0 + Y1) / 2, it.z + 1.2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, (m[1] - sy) * 1.4); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), d = a < 0 ? (k === FAV ? 1.5 : 0) : dd === 0 ? PRESS : dd === 1 ? 2.5 : 0;
      tset(it.d, d, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "step " + (TZ.length - a);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "poolladder",
  means: "A pool ladder hanging into the water: the tread under the pointer presses down, the treads beside it give a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[178, 129], [178, 146], [178, 162], null],
  mount,
});

cardtable.code:
/**
 * Card table: a felt table with five cards dealt face down in a row and a
 * short stack of chips at the far corner. The pointer picks a card by where it
 * stands: it lifts off the felt and tips up toward the player, its neighbours
 * rising a little, staggered from it. At rest one card is half lifted, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, poly, prism, proj, rings, ringAt, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 30, CW = 22, CL = 32, LIFT = 16, FAV = 2, TZ = 4, Y0 = 34;
const X1 = (N - 1) * STEP + CW + 24;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[-4, -4, 0], [X1, Y0 + CL + 16, 0], [X1, -4, 0], [-4, Y0 + CL + 16, 0], [X1 / 2, Y0, TZ + LIFT + 12]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(-4, -4, X1, Y0 + CL + 16, 10, 2.2);
  put(solid(g), prism(P, front, tr, ti, 0, TZ));
  // chips: three short discs stacked at the far corner
  for (let i = 0; i < 3; i++) put(solid(g), prism(P, front, disc(12, 14, 7), disc(12, 14, 5.6), TZ + i * 2.4, TZ + i * 2.4 + 2.2));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = 12 + k * STEP, grp = mk("g", {}, g);
    const card = mk("path", { class: "sil" }, grp), back = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x0, grp, card, back, z: tween(k === FAV ? 0.55 : 0), last: NaN });
  }
  // a card's corners: rest flat; lifted it rises and tips its near edge down toward the player
  function corners(it, f) {
    const z = TZ + 0.6 + f * LIFT, tip = f * 14;
    const at = (u, v) => P(u, v, z + ((Y0 + CL / 2 - v) / CL) * tip);
    return { at, z };
  }
  function draw(it, f) {
    if (f === it.last) return;
    it.last = f;
    const { at } = corners(it, f);
    const ring = rrect(it.x0, Y0, it.x0 + CW, Y0 + CL, 3, 4);
    const top = ring.map((q) => at(q.u, q.v)), bot = ring.map((q) => { const p = at(q.u, q.v); return [p[0], p[1] + 1.4]; });
    const all = top.concat(bot);
    it.card.setAttribute("d", poly(HL.hull(all)));
    it.back.setAttribute("d", poly(rrect(it.x0 + 3, Y0 + 3, it.x0 + CW - 3, Y0 + CL - 3, 2, 3).map((q) => at(q.u, q.v))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x0 + CW / 2, Y0 + CL / 2, TZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), f = a < 0 ? (k === FAV ? 0.55 : 0) : dd === 0 ? 1 : dd === 1 ? 0.22 : 0;
      tset(it.z, f, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.card.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "card " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "cardtable",
  means: "Five cards dealt face down on a felt table: the card under the pointer lifts and tips up, its neighbours rising a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[150, 150], [200, 175], [250, 200], null],
  mount,
});

boardinggate.code:
/**
 * Boarding gate: a terminal block with a jet bridge reaching out across the
 * apron, a fixed tunnel and a cab that telescopes over it on a wheeled leg.
 * The pointer's place along the apron sets how far the cab slides out. At
 * rest the cab sits part-way out, bright. The slider is the reach.
 *
 * The pattern: one part following the pointer along an axis.
 */
const { Cam, fit, facing, prism, proj, rings, unproj, clamp, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const REST = 14;
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.5);
  fit(C, [[-34, -14, 0], [160, 60, 0], [160, -14, 0], [-34, 60, 0], [-34, -14, 62], [150, 22, 46]], 200, 166);
  const P = proj(C), front = facing(C);
  const box = (par, x0, y0, x1, y1, z0, z1, r = 3, b = 1.4) => { const [a, i] = rings(x0, y0, x1, y1, r, b); const s = solid(par); put(s, prism(P, front, a, i, z0, z1)); return s; };
  const g = mk("g", {}, svg);
  box(g, -38, -18, 164, 64, 0, 2, 6, 2);
  // guide: where the leg's wheels run
  mk("path", { d: seg(P(84, 22, 2), P(150, 22, 2)), class: "dash" }, g);
  box(g, -30, -10, 30, 54, 2, 60, 5, 2);
  const door = mk("path", { class: "nf lo" }, g);
  door.setAttribute("d", "M" + [P(30, 14, 22), P(30, 14, 44), P(30, 32, 44), P(30, 32, 22)].map((q) => q.join(",")).join("L"));
  box(g, 40, 18, 48, 26, 2, 26, 2, 0.8);
  box(g, 30, 14, 92, 30, 26, 40, 3, 1.2);
  const mov = mk("g", {}, g);
  const sp = spring(REST), lim = () => 14 + reach * 0.4;
  let last = NaN, cab = null;
  function draw(e) {
    if (e === last) return;
    last = e;
    mov.replaceChildren();
    const x1 = 100 + e;
    box(mov, x1 - 20, 12, x1 - 4, 32, 2, 7, 2, 0.8);
    box(mov, x1 - 15, 18, x1 - 9, 26, 7, 23, 2, 0.8);
    cab = box(mov, 50 + e, 11, x1, 33, 23, 43, 3, 1.4);
    cab.sil.classList.add("hi");
    for (let k = 1; k < 4; k++) mk("path", { d: seg(P(50 + e + k * 12.5, 33, 30), P(50 + e + k * 12.5, 33, 38)), class: "lo nf" }, mov);
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  draw(REST);
  function aim(p) {
    if (!p) { sp.t = REST; read.textContent = "rest"; B.wake(); return; }
    const [wx] = unproj(C, p[0], p[1], 0);
    sp.t = clamp(wx - 80, 0, lim());
    read.textContent = "ext " + Math.round(sp.t);
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "boardinggate",
  means: "A jet bridge at a terminal: its cab telescopes out over the apron as far as the pointer reaches along it.",
  rules: [1, 3, 5, 8],
  range: [0, 50, 100],
  tour: [[230, 220], [267, 239], [293, 252], null],
  mount,
});

carjack.code:
/**
 * Car jack: a scissor jack on its base plate, two pairs of arms meeting at a
 * screw rod, a saddle on top. The pointer's height sets how far the jack is
 * wound up: the arms close in and the saddle rises. At rest it stands half
 * raised, its saddle bright. The slider is the reach.
 *
 * The pattern: one part following the pointer along an axis.
 */
const { Cam, fit, facing, prism, proj, rings, clamp, lerp, poly, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const L = 34, CX = 40, REST = 36, LO = 22, HI = 62;
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.7);
  fit(C, [[-4, -4, 0], [84, 24, 0], [84, -4, 0], [-4, 24, 0], [30, 0, HI + 6], [50, 20, HI + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const box = (par, x0, y0, x1, y1, z0, z1, r = 2, b = 1) => { const [a, i] = rings(x0, y0, x1, y1, r, b); const s = solid(par); put(s, prism(P, front, a, i, z0, z1)); return s; };
  const g = mk("g", {}, svg);
  box(g, -4, -4, 84, 24, 0, 4, 3, 1.4);
  const mov = mk("g", {}, g);
  const arm = (par, a, b, y) => {
    const dx = b[0] - a[0], dz = b[1] - a[1], n = Math.hypot(dx, dz), ox = (-dz / n) * 2.2, oz = (dx / n) * 2.2;
    mk("path", { d: poly([P(a[0] + ox, y, a[1] + oz), P(b[0] + ox, y, b[1] + oz), P(b[0] - ox, y, b[1] - oz), P(a[0] - ox, y, a[1] - oz)]) }, par);
  };
  const sp = spring(REST);
  let last = NaN;
  function draw(H) {
    if (H === last) return;
    last = H;
    mov.replaceChildren();
    const zm = (4 + H) / 2, w = Math.sqrt(L * L - ((H - 4) / 2) ** 2);
    const bot = [CX, 6], top = [CX, H - 2], lp = [CX - w, zm], rp = [CX + w, zm];
    box(mov, CX - 10, 2, CX + 10, 18, 4, 8, 2, 0.8);
    for (const y of [3, 5]) { arm(mov, bot, lp, y); arm(mov, lp, top, y); arm(mov, bot, rp, y); arm(mov, rp, top, y); }
    mk("path", { d: seg(P(CX - w - 4, 10, zm), P(CX + w + 12, 10, zm)), class: "nf" }, mov);
    mk("path", { d: poly([P(CX + w + 12, 10, zm - 3), P(CX + w + 12, 10, zm + 3), P(CX + w + 16, 10, zm + 3), P(CX + w + 16, 10, zm - 3)]), class: "nf" }, mov);
    for (const y of [15, 17]) { arm(mov, bot, lp, y); arm(mov, lp, top, y); arm(mov, bot, rp, y); arm(mov, rp, top, y); }
    const sad = box(mov, CX - 11, 0, CX + 11, 20, H - 4, H + 2, 2, 1);
    sad.sil.classList.add("hi");
    box(mov, CX - 4, 6, CX + 4, 14, H + 2, H + 4, 1, 0.5);
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  draw(REST);
  function aim(p) {
    if (!p) { sp.t = REST; read.textContent = "rest"; B.wake(); return; }
    const top = LO + (HI - LO) * (0.3 + 0.7 * reach / 100);
    sp.t = clamp(lerp(top, LO, (p[1] - 70) / 180), LO, top);
    read.textContent = "lift " + Math.round(sp.t - LO);
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "carjack",
  means: "A scissor jack on its base plate: the higher the pointer, the further it winds up, arms closing in and the saddle rising.",
  rules: [3, 5, 8, 9],
  range: [0, 50, 100],
  tour: [[200, 100], [200, 180], [200, 240], null],
  mount,
});

gasmeter.code:
/**
 * Gas meter: a squat meter box with two pipes rising from its back and a row
 * of four round index dials set into its top. The pointer picks a dial by
 * where it stands on the top: that dial's needle swings to point at the
 * pointer, and its neighbours turn part of the way, less with distance. At
 * rest the needles sit at uneven readings, one dial bright. The slider is how
 * far the neighbours follow.
 *
 * The pattern: one of many in a single row, aimed by a spring.
 */
const {
  Cam, circ, fit, facing, fillet, poly, prism, proj, rings, ringAt, unproj, clamp, lerp,
  disposer, mk, pointer, put, register, solid, spring, stepS, seg, tween, tset, tval, tdone, flatDot, place,
} = HL;

const W = 122, D = 60, H = 50, R = 12, DY = 40, FAV = 1, LIFT = 10;
const DX = [19, 47, 75, 103], REST = [0.7, 2.5, -1.3, 1.6];
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let follow = value / 100;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, 0, H + 26], [W, 0, H + 26], [0, D, H + LIFT + 4]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, D, 7, 2);
  put(solid(g), prism(P, front, br, bi, 0, H));
  // the index window on the front face
  const win = [[34, 16], [88, 16], [88, 34], [34, 34]].map(([x, z]) => P(x, D, z));
  mk("path", { d: poly(fillet(win, [3, 3, 3, 3])), class: "lo" }, g);
  // the inlet and outlet pipes, with a union nut each
  for (const x of [14, W - 14]) {
    put(solid(g), prism(P, front, disc(x, 12, 6, 24), disc(x, 12, 4.6, 24), H, H + 22));
    put(solid(g), prism(P, front, disc(x, 12, 8, 24), disc(x, 12, 6.4, 24), H + 8, H + 13));
  }

  const dials = DX.map((x, k) => {
    const grp = mk("g", {}, g), s = solid(grp);
    const ticks = mk("path", { class: "nf lo" }, grp), needle = mk("path", { class: "nf" }, grp);
    const hub = flatDot(grp, C, 1.8, "dot m");
    return { k, x, s, ticks, needle, hub, a: spring(REST[k]), z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN, lz: NaN };
  });

  function draw(d, lz) {
    const a = d.a.x, x = d.x;
    if (a === d.last && lz === d.lz) return;
    if (lz !== d.lz) {
      d.lz = lz;
      put(d.s, prism(P, front, disc(x, DY, R), disc(x, DY, R - 1.8), H, H + 1.4 + lz));
      let t = "";
      for (let i = 0; i < 10; i++) {
        const q = (i / 10) * Math.PI * 2, c = Math.cos(q), sn = Math.sin(q);
        t += seg(P(x + c * 8, DY + sn * 8, H + 1.4 + lz), P(x + c * 9.6, DY + sn * 9.6, H + 1.4 + lz));
      }
      d.ticks.setAttribute("d", t);
      place(d.hub, P(x, DY, H + 1.4 + lz));
    }
    d.last = a;
    const c = Math.cos(a), sn = Math.sin(a), z = H + 1.6 + lz;
    d.needle.setAttribute("d", seg(P(x - c * 3, DY - sn * 3, z), P(x + c * 9, DY + sn * 9, z)));
  }

  const B = register(stage, (dt, now) => {
    let moving = false;
    for (const d of dials) { if (stepS(d.a, dt)) moving = true; if (!tdone(d.z, now)) moving = true; draw(d, tval(d.z, now)); }
    return moving;
  });
  bag.add(B.unregister);
  dials.forEach((d) => draw(d, tval(d.z, performance.now())));

  const near = (from, to) => { let t = to; while (t - from > Math.PI) t -= Math.PI * 2; while (t - from < -Math.PI) t += Math.PI * 2; return t; };
  let act = -2;
  function aim(p) {
    let a = -1, w = null;
    if (p) {
      w = unproj(C, p[0], p[1], H);
      if (w[1] > -4 && w[1] < D + 10 && w[0] > -6 && w[0] < W + 6) {
        let bd = Infinity;
        DX.forEach((x, k) => { const dd = Math.abs(x - w[0]); if (dd < bd) { bd = dd; a = k; } });
      }
    }
    dials.forEach((d, k) => {
      const rest = REST[k];
      if (a < 0) { d.a.t = near(d.a.x, rest); return; }
      const dist = Math.abs(k - a), f = dist === 0 ? 1 : clamp(follow * Math.pow(0.5, dist - 1), 0, 1);
      const toward = near(rest, Math.atan2(w[1] - DY, w[0] - d.x));
      d.a.t = near(d.a.x, lerp(rest, toward, f));
    });
    if (a !== act) {
      const now = performance.now(), from = a >= 0 ? a : act;
      act = a;
      dials.forEach((d, k) => {
        const on = k === (a < 0 ? FAV : a);
        tset(d.z, a < 0 ? (on ? LIFT * 0.6 : 0) : on ? LIFT : 0, now, from < 0 ? 0 : Math.abs(k - from) * 40);
        d.s.sil.classList.toggle("hi", on);
      });
    }
    if (a < 0) read.textContent = "rest";
    else {
      const t = dials[a].a.t, frac = ((t % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
      read.textContent = "dial " + (a + 1) + "·" + (Math.round((frac / (Math.PI * 2)) * 10) % 10);
    }
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { follow = v / 100; }, destroy: bag.dispose };
}

hairline({
  name: "gasmeter",
  means: "A gas meter with four index dials on top: the dial under the pointer rises and swings its needle at it; neighbours follow part way.",
  rules: [1, 3, 5, 8],
  range: [0, 50, 100],
  tour: [[130, 125], [168, 144], [243, 182], null],
  mount,
});

chartboard.code:
/**
 * Chartboard: a bar chart built as five square columns on a low board, rising
 * left to right like a growth report. The pointer picks a column by where it
 * stands: it grows a step taller, and its neighbours rise a little, staggered
 * from it. At rest the last, tallest column is bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, tset, tval, tdone, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 26, W = 16, BZ = 4, GROW = 26, FAV = N - 1;
const REST = [16, 26, 22, 38, 52];
const X1 = (N - 1) * STEP + W + 12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[-8, -10, 0], [X1, -10, 0], [-8, W + 14, 0], [X1, W + 14, 0], [STEP * (N - 1), 2, BZ + REST[N - 1] + GROW + 4], [0, 2, BZ + REST[0] + GROW + 8]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-8, -10, X1, W + 14, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  const [fr, fi] = rings(-4, -6, X1 - 4, -2, 1.5, 0.6);
  put(solid(g), prism(P, front, fr, fi, BZ, BZ + 1.2));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = 2 + k * STEP, y0 = 2;
    const [ring, inner] = rings(x0, y0, x0 + W, y0 + W, 3, 1.4);
    const s = solid(mk("g", {}, g));
    items.push({ k, ring, inner, s, h: tween(REST[k]), last: NaN, mid: P(x0 + W / 2, y0 + W / 2, BZ + REST[k] / 2) });
  }

  function draw(it, h) {
    if (h === it.last) return;
    it.last = h;
    put(it.s, prism(P, front, it.ring, it.inner, BZ, BZ + h));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.h, now)); if (!tdone(it.h, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    items.forEach((it, k) => { const d = Math.abs(it.mid[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 24 && Math.abs(items[best].mid[1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), h = a < 0 ? REST[k] : REST[k] + (d === 0 ? GROW : d === 1 ? 8 : 0);
      tset(it.h, h, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "Q" + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "chartboard",
  means: "Five columns rising on a board like a growth chart: the column under the pointer grows taller and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[150, 150], [220, 140], [260, 120], null],
  mount,
});

coinjar.code:
/**
 * Coinjar: three savings jars of different heights on a shelf, each with a
 * screw lid. The pointer picks a jar by where it stands: its lid lifts and a
 * coin rises out of the mouth, and the jars beside it crack their lids,
 * staggered from it. At rest the middle jar is open, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, tset, tval, tdone, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 40, R = 15, NR = 10, SZ = 3, LIFT = 22, FAV = 1;
const H = [30, 40, 24];
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const X1 = (N - 1) * STEP + 2 * R;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-6, -6, 0], [X1 + 6, -6, 0], [-6, 2 * R + 6, 0], [X1 + 6, 2 * R + 6, 0], [R + STEP, R, SZ + H[1] + 6 + LIFT + 5], [R, R, SZ + H[0] + 6 + LIFT + 5]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-6, -6, X1 + 6, 2 * R + 6, 6, 2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = R + k * STEP, y = R, grp = mk("g", {}, g), top = SZ + H[k];
    put(solid(grp), prism(P, front, disc(x, y, R), disc(x, y, R - 2), SZ, top));
    put(solid(grp), prism(P, front, disc(x, y, NR), disc(x, y, NR - 1.5), top, top + 4));
    const coin = solid(grp), lid = solid(grp);
    items.push({ k, x, y, top: top + 4, coin, lid, z: tween(k === FAV ? LIFT * 0.8 : 0), last: NaN, mid: P(x, y, top / 2) });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const cz = it.top + lift * 0.55 - 1;
    put(it.coin, prism(P, front, disc(it.x, it.y, 6, 24), disc(it.x, it.y, 4.6, 24), cz, cz + 1.6));
    put(it.lid, prism(P, front, disc(it.x, it.y, NR + 1.5), disc(it.x, it.y, NR), it.top + lift, it.top + lift + 4));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    items.forEach((it, k) => { const d = Math.abs(it.mid[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 32 && Math.abs(items[best].mid[1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.8 : 0) : d === 0 ? LIFT : d === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : d * stag);
      it.lid.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "jar " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "coinjar",
  means: "Three savings jars on a shelf: the jar under the pointer lifts its lid and a coin rises out, its neighbours crack theirs.",
  rules: [1, 2, 5, 6],
  range: [0, 50, 100],
  tour: [[130, 170], [200, 150], [270, 160], null],
  mount,
});

alarmpanel.code:
/**
 * Alarm sirens: four beacons on a wall rail, each a squat base with a domed
 * lens. The pointer picks a beacon by where it stands: its lens rises out of
 * the base as it sounds, and its neighbours rise a little, staggered from it.
 * At rest one lens is up, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 38, BR = 13, LR = 9, LIFT = 20, FAV = 2, RZ = 5, BH = 7, LH = 8;
const X1 = (N - 1) * STEP + 2 * BR;
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  const top = RZ + BH + LH + LIFT + LR;
  fit(C, [[-6, -6, 0], [X1 + 6, 2 * BR + 6, 0], [X1 + 6, -6, 0], [-6, 2 * BR + 6, 0], [BR, BR, top], [X1 - BR, BR, top]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-6, -6, X1 + 6, 2 * BR + 6, 6, 2);
  put(solid(g), prism(P, front, cr, ci, 0, RZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = BR + k * STEP, y = BR, grp = mk("g", {}, g);
    const lens = mk("path", { class: "sil" }, grp), band = mk("path", { class: "nf lo" }, grp);
    const base = solid(grp);
    put(base, prism(P, front, disc(x, y, BR), disc(x, y, BR - 2), RZ, RZ + BH));
    // a vent ring on the base top, with dots to number the beacon
    mk("path", { d: poly(ringAt(P, disc(x, y, LR + 1.5, 32), RZ + BH)), class: "nf lo" }, grp);
    items.push({ k, x, y, grp, lens, band, base, z: tween(k === FAV ? LIFT * 0.8 : 3), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = RZ + BH - 2, z1 = RZ + BH + LH + lift, pts = ringAt(P, disc(it.x, it.y, LR, 28), z0);
    for (let i = 0; i <= 6; i++) { const t = (i / 6) * (Math.PI / 2); pts.push(...ringAt(P, disc(it.x, it.y, LR * Math.cos(t) + 0.01, 28), z1 + LR * 0.85 * Math.sin(t))); }
    it.lens.setAttribute("d", poly(hull(pts)));
    it.band.setAttribute("d", poly(ringAt(P, disc(it.x, it.y, LR, 28), z1 - LH * 0.45)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, RZ + BH));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.8 : 3) : dd === 0 ? LIFT : dd === 1 ? 6 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.lens.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "siren " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "alarmpanel",
  means: "Four alarm beacons on a rail: the lens under the pointer rises out of its base to sound, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[119, 134], [281, 215], [227, 188], null],
  mount,
});

petri.code:
/**
 * Petri dishes: six shallow dishes on a lab tray, each with colonies growing
 * in it and a clear lid on top. The pointer picks a dish by where it stands
 * on the tray: its lid lifts off to show the culture, and the dishes beside
 * it crack their lids a little, staggered from it. At rest one lid is raised,
 * bright. The slider is the stagger.
 *
 * The pattern: a grid on the ground, picked by world position.
 */
const {
  Cam, circ, fit, facing, poly, prism, proj, rings, unproj, tdone, tset, tval, tween,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const CX = 3, CY = 2, STEP = 38, R = 16, TZ = 3, DH = 4, LIFT = 18, FAV = 4;
const W = CX * STEP, H = CY * STEP;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const COL = [[[-6, -3], [4, 5], [5, -6]], [[0, 0], [-7, 4]], [[-5, -5], [6, 2], [-2, 7], [2, -2]], [[3, 4], [-6, 0]], [[-4, 4], [5, -4], [0, 0], [6, 5]], [[-3, -6], [4, 3]]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-4, -4, 0], [W + 4, H + 4, 0], [W + 4, -4, 0], [-4, H + 4, 0], [STEP / 2, STEP / 2, TZ + DH + LIFT + 3]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(-4, -4, W + 4, H + 4, 7, 2);
  put(solid(g), prism(P, front, tr, ti, 0, TZ));

  const items = [], order = [];
  for (let j = 0; j < CY; j++) for (let i = 0; i < CX; i++) order.push([i, j]);
  order.sort((a, b) => a[0] + a[1] - (b[0] + b[1]));
  for (const [i, j] of order) {
    const k = j * CX + i, x = STEP / 2 + i * STEP, y = STEP / 2 + j * STEP, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, y, R), disc(x, y, R - 1.5), TZ, TZ + DH));
    for (const [u, v] of COL[k]) place(flatDot(grp, C, 1.6, "dot off"), P(x + u, y + v, TZ + 1));
    const lid = solid(grp);
    items[k] = { k, i, j, x, y, lid, z: tween(k === FAV ? LIFT * 0.8 : 0), last: NaN };
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = TZ + DH - 1 + lift;
    put(it.lid, prism(P, front, disc(it.x, it.y, R + 1), disc(it.x, it.y, R - 0.5), z0, z0 + 2));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, TZ + DH);
    let best = -1, bd = R + 4;
    items.forEach((it) => { const d = Math.hypot(wx - it.x, wy - it.y); if (d < bd) { bd = d; best = it.k; } });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const fi = from % CX, fj = Math.floor(from / CX);
    items.forEach((it) => {
      const dd = a < 0 ? 0 : Math.max(Math.abs(it.i - (a % CX)), Math.abs(it.j - Math.floor(a / CX)));
      const z = a < 0 ? (it.k === FAV ? LIFT * 0.8 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : (Math.abs(it.i - fi) + Math.abs(it.j - fj)) * stag);
      it.lid.sil.classList.toggle("hi", it.k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "dish " + (a % CX + 1) + "·" + (Math.floor(a / CX) + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "petri",
