moonphases.code:
/**
 * Moon phases: a moon disc stands on a post above a round plinth, ringed by
 * eight orbit studs. The pointer's x sweeps the lunar month: the lit part of
 * the disc, its outline bright, grows from a sliver to full and wanes again.
 * At rest a waxing crescent is lit. The slider is the month's start.
 *
 * The pattern: one continuous value on a spring.
 */
const {
  Cam, circ, fit, facing, poly, prism, proj, rings, clamp, open, spring, stepS,
  disposer, mk, pointer, put, register, solid, flatDot, place,
} = HL;

const R = 34, ZC = 62, T = 2.2, PZ = 6, OR = 40, REST = 0.32;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let off = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-OR - 6, -OR - 6, 0], [OR + 6, OR + 6, 0], [-R, 0, ZC + R], [R, 0, ZC + R], [R, 0, ZC - R]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const disc = (r, n = 48) => circ(r, n);
  put(solid(g), prism(P, front, disc(OR + 4), disc(OR + 2), 0, PZ));
  const studs = [];
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2, d = flatDot(g, C, 2.2, "dot off");
    place(d, P(OR * Math.cos(a) * 0.82, OR * Math.sin(a) * 0.82, PZ));
    studs.push(d);
  }
  const [pr, pi] = rings(-4, -4, 4, 4, 3, 1.2);
  put(solid(g), prism(P, front, pr, pi, PZ, ZC - R + 4));
  // the disc: a thin plate standing in the x-z plane
  const face = (y) => { const o = []; for (let i = 0; i <= 64; i++) { const t = (i / 64) * Math.PI * 2; o.push(P(R * Math.cos(t), y, ZC + R * Math.sin(t))); } return o; };
  const back = face(-T), fr = face(T);
  const sh = solid(g);
  const hl = (pts) => { const { hull } = HL; return poly(hull(pts)); };
  sh.sil.setAttribute("d", hl(back.concat(fr)));
  sh.cr.setAttribute("d", open(fr));
  sh.cr.setAttribute("class", "nf lo");
  const lit = mk("path", { class: "nf hi" }, g);

  function litPath(s) {
    const wax = s < 1, f = wax ? s : 2 - s, k = 1 - 2 * f, sg = wax ? 1 : -1, pts = [];
    for (let i = 0; i <= 32; i++) { const t = -Math.PI / 2 + (i / 32) * Math.PI; pts.push(P(sg * R * Math.cos(t), T + 0.2, ZC + R * Math.sin(t))); }
    for (let i = 0; i <= 32; i++) { const t = Math.PI / 2 - (i / 32) * Math.PI; pts.push(P(sg * k * R * Math.cos(t), T + 0.2, ZC + R * Math.sin(t))); }
    return poly(pts);
  }

  const sp = spring(REST);
  let last = NaN;
  function draw() {
    const s = clamp(sp.x, 0.03, 1.97);
    if (s === last) return;
    last = s;
    lit.setAttribute("d", litPath(s));
    const day = Math.round(((s / 2 + off) % 1) * 29.5);
    studs.forEach((d, i) => d.setAttribute("class", i === Math.round(s * 4) % 8 ? "dot m" : "dot off"));
    return day;
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  const x0 = P(-R - 10, 0, ZC)[0], x1 = P(R + 10, 0, ZC)[0];
  function setS(s, label) { sp.t = s; read.textContent = label; B.wake(); }
  bag.add(pointer(stage, {
    move: ([sx]) => { const s = clamp(((sx - x0) / (x1 - x0)) * 2, 0.03, 1.97); setS(s, "day " + Math.round(((s / 2 + off) % 1) * 29.5)); },
    leave: () => setS(REST, "rest"),
  }));
  draw();
  read.textContent = "rest";
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { off = v; last = NaN; draw(); }, destroy: bag.dispose };
}

hairline({
  name: "moonphases",
  means: "A moon disc on a plinth: the pointer sweeps the month across it, and the lit part waxes from a sliver to full and wanes again.",
  rules: [1, 3, 4, 5, 8],
  range: [0, 0, 0.5],
  tour: [[154, 101], [200, 123], [246, 146], null],
  mount,
});

meteor.code:
/**
 * Meteor: a rough rock hangs high over a cratered slab, a dashed trail
 * behind it. Over the slab the rock falls into the crater, and the chips
 * round the rim kick up, staggered outward from the near side. At rest the
 * rock is high and bright. The slider is the stagger.
 *
 * The pattern: one discrete state on the long ease.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween, unproj, seg,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 46, SZ = 6, HIGH = 92, LOW = SZ + 6, MX = 34, MY = -6;
const at = (ring, x, y) => ring.map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const rock = (r) => circ(r, 7).map((q, i) => ({ ...q, u: q.u * (1 + 0.22 * Math.sin(i * 2.3)), v: q.v * (1 + 0.18 * Math.cos(i * 1.7)) }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-W, -W, 0], [W, W, 0], [W, -W, 0], [-W, W, 0], [MX + 14, MY - 20, HIGH + 16], [MX + 30, MY - 30, HIGH + 40]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-W, -W, W, W, 10, 2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));
  const rim = solid(g);
  put(rim, prism(P, front, circ(26, 48), circ(23, 48), SZ, SZ + 3));
  mk("path", { d: poly(ringAt(P, circ(16, 40), SZ + 2)), class: "nf lo" }, g);
  mk("path", { d: poly(ringAt(P, circ(8, 32), SZ + 1)), class: "nf lo" }, g);

  const chips = [];
  for (let i = 0; i < 6; i++) {
    const a = rad0(i), x = 34 * Math.cos(a), y = 34 * Math.sin(a), grp = mk("g", {}, g), s = solid(grp);
    chips.push({ x, y, s, a, z: tween(0), last: NaN, near: x + y });
  }
  chips.sort((p, q) => p.near - q.near).forEach((c) => g.appendChild(c.s.g.parentNode));
  function rad0(i) { return (i / 6) * Math.PI * 2 + 0.4; }

  const tr = mk("path", { class: "dash nf" }, g);
  const met = solid(mk("g", {}, g));
  const R1 = rock(9), R2 = rock(12), R3 = rock(7);
  const m = { z: tween(HIGH), last: NaN };

  function drawMet(z) {
    if (z === m.last) return;
    m.last = z;
    const t = (z - LOW) / (HIGH - LOW), x = MX * t, y = MY * t;
    const pts = ringAt(P, at(R3, x, y), z - 9).concat(ringAt(P, at(R2, x, y), z), ringAt(P, at(R1, x + 1, y), z + 9));
    met.sil.setAttribute("d", poly(hull(pts)));
    met.cr.setAttribute("d", poly(ringAt(P, at(rock(6), x + 1, y), z + 8)));
    met.cr.setAttribute("class", "nf lo");
    tr.setAttribute("d", seg(P(x + 9, y - 6, z + 6), P(x + 9 + 30 * t, y - 6 - 18 * t, z + 6 + 50 * t)) + seg(P(x - 2, y - 10, z + 2), P(x - 2 + 22 * t, y - 10 - 14 * t, z + 2 + 38 * t)));
  }
  function drawChip(c, z) {
    if (z === c.last) return;
    c.last = z;
    const x = c.x * (1 + z * 0.012), y = c.y * (1 + z * 0.012);
    put(c.s, prism(P, front, at(rock(3.2), x, y), at(rock(2), x, y), SZ + z, SZ + z + 3.4));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    drawMet(tval(m.z, now)); if (!tdone(m.z, now)) moving = true;
    for (const c of chips) { drawChip(c, tval(c.z, now)); if (!tdone(c.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    const now = performance.now();
    tset(m.z, on ? LOW : HIGH, now, 0);
    chips.forEach((c) => tset(c.z, on ? 14 : 0, now, on ? 260 + (c.near + 34) / 68 * 4 * stag : 0));
    met.sil.classList.toggle("hi", !on);
    rim.sil.classList.toggle("hi", on);
    read.textContent = on ? "impact" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, 0); setActive(Math.abs(x) < W && Math.abs(y) < W); },
    leave: () => setActive(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "meteor",
  means: "A rock hangs over a cratered slab: over the slab it falls into the crater, and the chips round the rim kick up outward.",
  rules: [1, 2, 4, 5, 8],
  range: [0, 40, 90],
  tour: [[144, 203], [195, 228], [144, 254], null],
  mount,
});

benchpress.code:
/**
 * Bench press: a padded bench under a rack, the barbell resting in the hooks
 * with a plate at each end. The pointer's height lifts the bar off the hooks
 * and its left-right tips the bar a little, both on springs. At rest the bar
 * sits just above the hooks, bright. The slider is the reach of the lift.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, clamp, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BX = 10, HZ = 52, PRR = 15, PT = 4, BR = 1.6, YB = 50, YP = 38;
// a disc standing across y: points round (x, z) at width y0..y1
const drum = (P, x, z, r, y0, y1, n = 28) => {
  const pts = [];
  for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2, cx = x + r * Math.cos(t), cz = z + r * Math.sin(t); pts.push(P(cx, y0, cz), P(cx, y1, cz)); }
  return poly(hull(pts));
};
const face = (P, x, z, r, y, n = 28) => {
  const pts = [];
  for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; pts.push(P(x + r * Math.cos(t), y, z + r * Math.sin(t))); }
  return poly(pts);
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-6, -YB - 4, 0], [100, 14, 0], [BX, YB + 4, 0], [BX, -YB, HZ + 4 + 40 + PRR], [BX, YB, HZ + 40 + PRR]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, z0, z1, r, b, par = g) => { const [a, i] = rings(x0, y0, x1, y1, r, b); return put(solid(par), prism(P, front, a, i, z0, z1)); };

  // far upright, far plate and stub (behind everything else)
  block(BX - 3, -YP + 6, BX + 3, -YP + 12, 0, HZ + 6, 2, 0.8);
  const farStub = mk("path", {}, g), farPlate = mk("path", { class: "sil" }, g), farHub = mk("path", { class: "nf lo" }, g);
  // the bench: two legs, then the pad
  block(14, -9, 22, 9, 0, 16, 2, 1);
  block(78, -9, 86, 9, 0, 16, 2, 1);
  block(4, -11, 96, 11, 16, 24, 5, 1.6);
  block(BX - 8, -YP + 6, BX + 8, YP - 6, 0, 2, 3, 1);
  const bar = mk("path", { class: "sil" }, g);
  // near upright, hooks, near plate
  block(BX - 3, YP - 12, BX + 3, YP - 6, 0, HZ + 6, 2, 0.8);
  const nearPlate = mk("path", { class: "sil" }, g), nearHub = mk("path", { class: "nf lo" }, g), nearStub = mk("path", {}, g);

  const REST = 3;
  const lift = spring(REST), tip = spring(0);
  let last = "";
  function draw() {
    const z0 = HZ + lift.x, zf = z0 - tip.x, zn = z0 + tip.x;
    const key = z0.toFixed(2) + tip.x.toFixed(2);
    if (key === last) return;
    last = key;
    const zAt = (y) => z0 + (tip.x * y) / YP;
    farStub.setAttribute("d", drum(P, BX, zAt(-YB), BR + 0.6, -YB, -YP - PT, 14));
    farPlate.setAttribute("d", drum(P, BX, zf, PRR, -YP - PT, -YP));
    farHub.setAttribute("d", face(P, BX, zf, 4, -YP, 16));
    const pts = [];
    for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2, dx = BR * Math.cos(t), dz = BR * Math.sin(t); pts.push(P(BX + dx, -YP, zf + dz), P(BX + dx, YP, zn + dz)); }
    bar.setAttribute("d", poly(hull(pts)));
    nearPlate.setAttribute("d", drum(P, BX, zn, PRR, YP, YP + PT));
    nearHub.setAttribute("d", face(P, BX, zn, 4, YP + PT, 16));
    nearStub.setAttribute("d", drum(P, BX, zAt(YB), BR + 0.6, YP + PT, YB, 14));
  }
  draw();
  const B = register(stage, (dt) => {
    const a = stepS(lift, dt), b = stepS(tip, dt);
    draw();
    return a || b;
  });
  bag.add(B.unregister);

  const top = P(BX, 0, HZ + 40)[1], base = P(BX, 0, HZ)[1] + 40;
  function setLit(on) { for (const el of [bar, farPlate, nearPlate]) el.classList.toggle("hi", on); }
  function move([sx, sy]) {
    const f = clamp((base - sy) / (base - top), 0, 1);
    lift.t = REST + f * reach;
    tip.t = clamp((sx - 200) / 120, -1, 1) * 4;
    setLit(true);
    read.textContent = "up " + Math.round(f * reach);
    B.wake();
  }
  function leave() { lift.t = REST; tip.t = 0; setLit(true); read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "benchpress",
  means: "A bench under a racked barbell: the pointer's height presses the bar up off the hooks, and its side tips the bar.",
  rules: [3, 5, 6, 8],
