organpipes.code:
/**
 * Organ pipes: a rank of round flue pipes standing on a wind chest, tallest
 * in the middle, each with its conical foot and a mouth cut in its front.
 * The pointer picks a pipe by where it stands: that pipe lifts in its hole as
 * if its stop were drawn, and the pipes beside it rise a little, staggered
 * from it. At rest one pipe stands raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 7, STEP = 14, R = 5.5, CZ = 12, FOOT = 10, LIFT = 9, FAV = 2;
const H = [46, 60, 74, 88, 74, 60, 46];
const X1 = (N - 1) * STEP + 2 * R + 8, Y1 = 2 * R + 8;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.98);
  fit(C, [[-4, -4, 0], [X1 + 4, Y1 + 4, 0], [X1 + 4, -4, 0], [-4, Y1 + 4, 0], [X1 / 2, Y1 / 2, CZ + 88 + LIFT + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-4, -4, X1 + 4, Y1 + 4, 4, 1.6);
  put(solid(g), prism(P, front, cr, ci, 0, CZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = R + 4 + k * STEP, y = Y1 / 2, grp = mk("g", {}, g);
    mk("path", { d: poly(ringAt(P, disc(x, y, R + 0.8), CZ)), class: "nf lo" }, grp);
    const foot = mk("path", { class: "" }, grp);
    const body = solid(grp);
    const mouth = mk("path", { class: "nf lo" }, grp);
    const rest = k === FAV ? LIFT * 0.7 : 0;
    items.push({ k, x, y, h: H[k], foot, body, mouth, z: tween(rest), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = CZ + lift - 3, zb = z0 + FOOT, zt = CZ + it.h + lift;
    it.foot.setAttribute("d", poly(hull(ringAt(P, disc(it.x, it.y, 1.6, 16), z0).concat(ringAt(P, disc(it.x, it.y, R, 28), zb)))));
    put(it.body, prism(P, front, disc(it.x, it.y, R), disc(it.x, it.y, R - 1.1), zb, zt));
    const at = (a, z) => P(it.x + R * Math.cos(a), it.y + R * Math.sin(a), z);
    const a0 = Math.PI / 4, mz = zb + 3;
    it.mouth.setAttribute("d", open([at(a0 - 0.55, mz), at(a0 - 0.35, mz + 3), at(a0, mz + 5), at(a0 + 0.35, mz + 3), at(a0 + 0.55, mz)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const bands = items.map((it) => [P(it.x, it.y, CZ)[0], P(it.x, it.y, CZ + it.h)[1] - 6, P(it.x, it.y, CZ)[1] + 8]);
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    bands.forEach((b, k) => { const d = Math.abs(b[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 16 && sy > bands[best][1] && sy < bands[best][2] ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : d === 0 ? LIFT : d === 1 ? 3.5 : d === 2 ? 1.2 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "pipe " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "organpipes",
  means: "A rank of organ pipes on a wind chest: the pipe under the pointer lifts as its stop is drawn, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[200, 99], [141, 87], [259, 146], null],
  mount,
});

boommic.code:
/**
 * Boom mic: a weighted stand with a post, a boom pivoting on its top with a
 * counterweight behind, and a microphone hanging from the boom's far end on
 * a short cord. The boom swings round the post to hang the mic over the
 * pointer, its spot marked on the floor by a dashed drop. At rest it leans
 * out to one side, the mic bright. The slider is how far the boom reaches.
 *
 * The pattern: one part turning to face the pointer (aim).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, unproj, rings, ringAt, seg, clamp, lerp, rad, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const PZ = 72, A0 = rad(-15), A1 = rad(105), REST = rad(15);
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.45);
  const ext = [[-16, -16, 0], [16, 16, 0], [0, 0, PZ + 14]];
  for (let a = A0; a <= A1 + 1e-6; a += (A1 - A0) / 6) ext.push([80 * Math.cos(a), 80 * Math.sin(a), PZ + 12], [80 * Math.cos(a), 80 * Math.sin(a), 0]);
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-14, -14, 14, 14, 14, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, 4));
  const spot = flatDot(g, C, 2.4, "dot m");
  const back = solid(g), weight = solid(g);
  put(solid(g), prism(P, front, disc(0, 0, 2.4, 16), disc(0, 0, 1.4, 16), 4, PZ));
  put(solid(g), prism(P, front, disc(0, 0, 3.4, 16), disc(0, 0, 2.4, 16), PZ - 3, PZ + 3));
  const boom = solid(g);
  const drop = mk("path", { class: "dash nf" }, g);
  const cord = mk("path", { class: "nf lo" }, g);
  const mic = solid(g);
  mic.sil.classList.add("hi");

  const ang = spring(REST), len = spring(lerp(48, 72, value));
  let last = "";
  const rod = (a, b, r) => hull([a, b].flatMap(([x, y, z]) => ringAt(P, disc(x, y, r, 12), z - r).concat(ringAt(P, disc(x, y, r, 12), z + r))));

  function draw() {
    const a = ang.x, L = len.x, key = a.toFixed(4) + L.toFixed(3);
    if (key === last) return;
    last = key;
    const c = Math.cos(a), s = Math.sin(a);
    const tip = [L * c, L * s, PZ + 10], tail = [-16 * c, -16 * s, PZ - 2];
    back.sil.setAttribute("d", poly(rod([0, 0, PZ], tail, 1.4)));
    weight.sil.setAttribute("d", poly(rod([tail[0] * 0.8, tail[1] * 0.8, PZ - 2], [tail[0] * 1.1, tail[1] * 1.1, PZ - 2.6], 3.6)));
    boom.sil.setAttribute("d", poly(rod([0, 0, PZ], tip, 1.2)));
    const mz = PZ + 2, mb = mz - 18;
    cord.setAttribute("d", "M" + P(tip[0], tip[1], tip[2]).join(",") + "L" + P(tip[0], tip[1], mz).join(","));
    put(mic, prism(P, front, disc(tip[0], tip[1], 3.6), disc(tip[0], tip[1], 2.4), mb, mz));
    drop.setAttribute("d", seg(P(tip[0], tip[1], mb), P(tip[0], tip[1], 0)));
    place(spot, P(tip[0], tip[1], 0));
  }

  const B = register(stage, (dt) => {
    const m = stepS(ang, dt) | stepS(len, dt);
    draw();
    return !!m;
  });
  bag.add(B.unregister);

  function aim(p) {
    const [wx, wy] = unproj(C, p[0], p[1], 0);
    if (Math.hypot(wx, wy) < 6) return;
    let a = Math.atan2(wy, wx);
    if (a < -Math.PI * 0.75) a += Math.PI * 2;
    ang.t = clamp(a, A0, A1);
    read.textContent = Math.round((ang.t * 180) / Math.PI) + "°";
    B.wake();
  }
  function leave() { ang.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  draw();
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { len.t = lerp(48, 72, v); B.wake(); }, destroy: bag.dispose };
}

