hotelbed.code:
/**
 * Hotel bed: a low frame under a mattress, a padded headboard, two pillows
 * and a duvet turned down at the top. The pointer, moving along the bed,
 * sets how far the duvet is turned back: the flap folds over itself toward
 * the foot and the sheet shows beneath. At rest a short turndown, its flap
 * bright. The slider is how far the turndown may reach.
 *
 * The pattern: one continuous value on one object (a spring), read off the ground.
 */
const {
  Cam, clamp, fit, facing, proj, prism, rings, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 96, W = 64, FZ = 9, MZ = 19, F = 26, REST = 9;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxD = 20 + value * 0.13;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-6, -2, 0], [L + 2, W + 2, 0], [L + 2, -2, 0], [-6, W + 2, 40]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1, cls) => { const s = solid(g); put(s, prism(P, front, ...rings(x0, y0, x1, y1, r, b), z0, z1)); if (cls) s.sil.classList.add(cls); return s; };
  // headboard, then the frame and the mattress
  box(-6, -2, 0, W + 2, 2.5, 1, 0, 40);
  box(0, 0, L, W, 4, 1.6, 0, FZ);
  box(1, 1, L - 1, W - 1, 6, 2, FZ, MZ);
  // the two pillows, plump: a wide low solid under a narrower top
  for (const y of [5, W / 2 + 2]) { box(4, y, 21, y + W / 2 - 9, 7, 1.6, MZ, MZ + 4); box(6, y + 2, 19, y + W / 2 - 11, 6, 1.4, MZ + 4, MZ + 7); }
  const duvet = solid(g), flap = solid(g);
  flap.sil.classList.add("hi");

  const d = spring(REST);
  let last = NaN;
  function draw(v) {
    if (v === last) return;
    last = v;
    put(duvet, prism(P, front, ...rings(F + v, -1.5, L + 1.5, W + 1.5, 4, 1.8), MZ, MZ + 3));
    put(flap, prism(P, front, ...rings(F + v, -1.5, F + 2 * v, W + 1.5, Math.min(4, v / 2), Math.min(1.6, v / 3)), MZ + 3, MZ + 5.5));
  }
  draw(REST);

  const B = register(stage, (dt) => { const m = stepS(d, dt); draw(d.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [ux, uy] = unproj(C, sx, sy, MZ);
    if (ux < -10 || ux > L + 10 || uy < -16 || uy > W + 16) return leave();
    d.t = clamp((ux - F) * 0.8, 3, maxD);
    read.textContent = "turn " + Math.round((d.t / 33) * 100) + "%";
    B.wake();
  }
  function leave() { d.t = REST; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxD = 20 + v * 0.13; }, destroy: bag.dispose };
}

hairline({
  name: "hotelbed",
  means: "A made hotel bed with two pillows: the pointer moving along it turns the duvet back further, its flap folding toward the foot.",
  rules: [1, 3, 5, 8],
  range: [0, 50, 100],
  tour: [[176, 131], [250, 168], [213, 150], null],
  mount,
});

balconies.code:
/**
 * Balconies: a block's facade with three floors of three balconies, each a
 * slab with a glass rail before a door. The pointer picks a balcony by where
 * it sits on the wall: its slab slides out from the facade, and the ones
 * beside it ease out a little, staggered. At rest one balcony stands out, bright.
 * The slider is the stagger.
 *
 * The pattern: grid on a face plane (depositboxes).
 */
const {
  Cam, fit, fillet, poly, prism, proj, rings, tdone, tset, tval, tween, facing,
  disposer, mk, pointer, put, register, solid,
} = HL;

const COLS = 3, ROWS = 3, CW = 40, FH = 28, BW = 28, W = COLS * CW + 8, H = ROWS * FH + 34, FAV = 4;
const REST = [7, 5, 9, 6, 15, 5, 8, 6, 7], OUT = 18;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[0, -10, 0], [W, -10, 0], [0, OUT + 2, 0], [W, OUT + 2, 0], [0, -10, H], [W, -10, H], [W, OUT, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [wr, wi] = rings(0, -10, W, 0, 2, 1);
  put(solid(g), prism(P, front, wr, wi, 0, H));
  const quad = (x0, x1, z0, z1, r) => poly(fillet([P(x0, 0, z0), P(x1, 0, z0), P(x1, 0, z1), P(x0, 0, z1)], [r, r, r, r]));
  // the street door
  mk("path", { d: quad(W / 2 - 9, W / 2 + 9, 0, 22, 2), class: "nf lo" }, g);

  const items = [];
  for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) {
    const k = r * COLS + c, x0 = 4 + c * CW + (CW - BW) / 2, x1 = x0 + BW, zf = 30 + r * FH;
    mk("path", { d: quad(x0 + 7, x1 - 7, zf + 2, zf + 21, 1.5), class: "nf lo" }, g);
    items.push({ k, r, c, x0, x1, zf, zt: zf, d: tween(REST[k]), last: NaN });
  }
  // lower floors first, then left to right: the near ones cover the far
  for (const it of items) {
    it.grp = mk("g", {}, g);
    it.slab = solid(it.grp); it.rail = solid(it.grp);
  }

  function draw(it, d) {
    if (d === it.last) return;
    it.last = d;
    const [sr, si] = rings(it.x0, 0, it.x1, d, 1.5, 0.6);
    put(it.slab, prism(P, front, sr, si, it.zf, it.zf + 2.2));
    const [rr, ri] = rings(it.x0, d - 1.4, it.x1, d, 0.6, 0.3);
    put(it.rail, prism(P, front, rr, ri, it.zf + 2.2, it.zf + 12));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.d, now)); if (!tdone(it.d, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P((it.x0 + it.x1) / 2, 0, it.zf + 9));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, (m[1] - sy) * 1.3); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act, at = items[a];
    act = a;
    items.forEach((it, k) => {
      const dd = at ? Math.abs(it.r - at.r) + Math.abs(it.c - at.c) : 0;
      const d = a < 0 ? REST[k] : dd === 0 ? OUT : dd === 1 ? 9 : 5;
      const f = items[from];
      tset(it.d, d, now, f ? (Math.abs(it.r - f.r) + Math.abs(it.c - f.c)) * stag : 0);
      const on = k === (a < 0 ? FAV : a);
      it.slab.sil.classList.toggle("hi", on); it.rail.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "flat " + (at.r + 1) + "·" + (at.c + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "balconies",
  means: "A facade of nine balconies: the one under the pointer slides out from the wall, and its neighbours ease out a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[241, 180], [154, 170], [199, 110], null],
  mount,
});

carport.code:
/**
 * Carport: a flat roof on four posts over a slab drive, a car parked under
 * it. The pointer stands on the drive and the car rolls to it, out from
 * under the roof or back into the bay, on a spring. At rest the car sits
 * half out and the roof is bright; once the pointer is on the drive the car takes it.
 *
 * The pattern: a part following the pointer along one axis (spring).
 */
const {
  Cam, fit, poly, prism, proj, rings, clamp, spring, stepS, unproj, facing,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 72, D = 44, CL = 48, A0 = 6, A1 = 66, REST = 34, RZ = 30, X1 = A1 + CL + 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-6, -6, 0], [X1, -6, 0], [-6, D + 6, 0], [X1, D + 6, 0], [-4, -4, RZ + 3], [L + 4, D + 4, RZ + 3]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1, parent) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(parent); put(s, prism(P, front, o, i, z0, z1)); return s; };
  box(-6, -6, X1, D + 6, 4, 1.5, 0, 2, g);
  // the bay, marked on the slab
  mk("path", { d: poly([P(2, 4, 2), P(L - 2, 4, 2), P(L - 2, D - 4, 2), P(2, D - 4, 2)]), class: "nf dash" }, g);
  const post = (x, y, parent) => box(x - 1.6, y - 1.6, x + 1.6, y + 1.6, 1.6, 0.5, 2, RZ, parent);
  post(0, 0, g); post(L, 0, g);
  const carG = mk("g", {}, g);
  post(0, D, g); post(L, D, g);
  const roof = box(-4, -4, L + 4, D + 4, 3, 1.5, RZ, RZ + 2.5, g);

  const body = solid(carG), cab = solid(carG), wheels = [mk("path", {}, carG), mk("path", {}, carG)];
  const wheel = (cx, y) => { const pts = []; for (let i = 0; i < 20; i++) { const t = (i / 20) * Math.PI * 2; pts.push(P(cx + 4.2 * Math.cos(t), y, 4.2 + 4.2 * Math.sin(t))); } return poly(pts); };
  let last = NaN;
  function draw(a) {
    a = Math.round(a * 20) / 20;
    if (a === last) return;
    last = a;
    const [o, i] = rings(a, 9, a + CL, D - 9, 5, 1.5);
    put(body, prism(P, front, o, i, 3.5, 11.5));
    const [co, ci] = rings(a + 12, 11, a + CL - 12, D - 11, 5, 1.5);
    put(cab, prism(P, front, co, ci, 11.5, 19));
    wheels[0].setAttribute("d", wheel(a + 10, D - 9));
    wheels[1].setAttribute("d", wheel(a + CL - 10, D - 9));
  }

  const pos = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(pos, dt); draw(pos.x); return m; });
  bag.add(B.unregister);

  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    roof.sil.classList.toggle("hi", !v);
    body.sil.classList.toggle("hi", v); cab.sil.classList.toggle("hi", v);
  }
  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, 0);
    if (wx < -14 || wx > X1 + 14 || wy < -16 || wy > D + 16) return leave();
    const a = clamp(wx - CL / 2, A0, lerpA()), pct = Math.round(((a - A0) / (A1 - A0)) * 100);
    pos.t = a;
    setOn(true);
    read.textContent = pct < 4 ? "in" : pct + "%";
    B.wake();
  }
  const lerpA = () => A0 + (A1 - A0) * (0.4 + 0.6 * reach);
  function leave() { pos.t = REST; setOn(false); read.textContent = "rest"; B.wake(); }
  draw(REST);
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "carport",
  means: "A carport over a slab drive: the car rolls out from under the roof, or back into the bay, to wherever the pointer stands.",
  rules: [1, 3, 5, 8],
  range: [0, 1, 1],
  tour: [[253, 201], [142, 146], [204, 176], null],
  mount,
});

campingstove.code:
/**
 * Camping stove: a two-burner stove case with a squat pot and a tall pot on
 * its grates, each with a lid and knob, and a dial at the front for each
 * burner. The pointer picks a pot by where it stands: its lid lifts off to
 * let the steam out, and the other lid rises a little after it. At rest the
 * squat pot's lid sits ajar, bright. The slider is the lift.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SZ = 10, GZ = 12, FAV = 0, STAG = 40;
const POTS = [{ x: 28, y: 24, r: 19, h: 18 }, { x: 80, y: 24, r: 14, h: 27 }];
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const cyl = (P, front, x, y, r, z0, z1, b = 1.6) => prism(P, front, disc(x, y, r), disc(x, y, r - b), z0, z1);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = clamp(value, 8, 26);
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[0, 0, 0], [108, 48, 0], [108, 0, 0], [0, 48, 0], [28, 24, GZ + 18 + 30], [80, 24, GZ + 27 + 30]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(0, 0, 108, 48, 7, 2);
  put(solid(g), prism(P, front, cr, ci, 0, SZ));
  // burner grates: a low ring plate under each pot
  for (const p of POTS) put(solid(g), cyl(P, front, p.x, p.y, p.r + 3, SZ, GZ, 2));
  // dials on the front edge
  for (const p of POTS) put(solid(g), cyl(P, front, p.x, 44, 3.2, SZ, SZ + 3, 1));

  const items = POTS.map((p, k) => {
    const grp = mk("g", {}, g);
    put(solid(grp), cyl(P, front, p.x, p.y, p.r, GZ, GZ + p.h, 2));
    // the handle stub on the near side
    put(solid(grp), prism(P, front, ...rings(p.x - 3, p.y + p.r - 1, p.x + 3, p.y + p.r + 6, 1.5, 0.8), GZ + p.h - 6, GZ + p.h - 3));
    const lid = solid(grp), knob = solid(grp);
    return { k, p, grp, lid, knob, z: tween(k === FAV ? 5 : 0), last: NaN };
  });

  function draw(it, z) {
    if (z === it.last) return;
    it.last = z;
    const { x, y, r, h } = it.p, base = GZ + h + z;
    put(it.lid, cyl(P, front, x, y, r + 1, base, base + 2, 2.2));
    put(it.knob, cyl(P, front, x, y, 2.6, base + 2, base + 5, 1));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.p.x, it.p.y, GZ + it.p.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 60 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a, force) {
    if (a === act && !force) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const z = a < 0 ? (k === FAV ? 5 : 0) : k === a ? lift : 3;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * STAG);
      it.lid.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : a === 0 ? "pot" : "tall pot";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = clamp(v, 8, 26); setActive(act, true); }, destroy: bag.dispose };
}

hairline({
  name: "campingstove",
  means: "A two-burner camping stove with two pots: the lid of the pot under the pointer lifts off, the other rises a little after.",
  rules: [1, 2, 5, 6],
  range: [8, 18, 26],
  tour: [[160, 140], [238, 152], [200, 192], null],
  mount,
});

podiumflags.code:
/**
 * Flag stands: four poles on weighted feet along a low dais, a flag hanging
 * from the top of each. The pointer picks a stand by where it stands: its
 * flag runs up to the top and swings round to face the room, and the flags beside it
 * turn part of the way, staggered from it. At rest the flags hang at uneven
 * heights and angles and the second one faces out, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fillet, fit, facing, poly, prism, proj, rad, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 32, DZ = 4, TOP = 74, FH = 22, FW = 26, FAV = 1, FACE = -45;
const REST = [70, FACE + 10, 110, 40], DROP = [16, 0, 22, 10];
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const cyl = (P, front, x, y, r, z0, z1, b) => prism(P, front, disc(x, y, r), disc(x, y, r - b), z0, z1);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  const X1 = (N - 1) * STEP;
  fit(C, [[-14, -14, 0], [X1 + 14, 14, 0], [X1 + 14, -14, 0], [-14, 14, 0], [-FW, 0, TOP + 4], [X1 + FW, 0, TOP + 4], [0, FW, TOP], [X1, -FW, TOP]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [dr, di] = rings(-14, -14, X1 + 14, 14, 6, 2);
  put(solid(g), prism(P, front, dr, di, 0, DZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, grp = mk("g", {}, g);
    put(solid(grp), cyl(P, front, x, 0, 7, DZ, DZ + 3, 1.6));
    put(solid(grp), cyl(P, front, x, 0, 1.3, DZ + 3, TOP, 0.5));
    put(solid(grp), cyl(P, front, x, 0, 2.4, TOP, TOP + 3, 0.8));
    const flag = mk("path", { class: "sil" }, grp), hem = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, grp, flag, hem, a: tween(REST[k]), h: tween(DROP[k]), last: NaN });
  }

  function draw(it, deg, h) {
    if (deg + h * 1e3 === it.last) return;
    it.last = deg + h * 1e3;
    const c = Math.cos(rad(deg)), s = Math.sin(rad(deg)), x = it.x;
    // the cloth hangs a little lower at its fly end
    const corners = [[x + 1.4 * c, 1.4 * s, TOP - 2 - h], [x + FW * c, FW * s, TOP - 4 - h], [x + FW * c, FW * s, TOP - 4 - FH - h], [x + 1.4 * c, 1.4 * s, TOP - 2 - FH - h]];
    it.flag.setAttribute("d", poly(fillet(corners.map(([a, b, z]) => P(a, b, z)), [0.6, 1.5, 1.5, 0.6])));
    it.hem.setAttribute("d", poly([P(x + 4 * c, 4 * s, TOP - 5 - h), P(x + 4 * c, 4 * s, TOP - FH + 1 - h)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now), tval(it.h, now)); if (!tdone(it.a, now) || !tdone(it.h, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 0, TOP / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), to = a < 0 ? REST[k] : d === 0 ? FACE : d === 1 ? (REST[k] + FACE) / 2 + 12 : REST[k];
      const dl = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(it.a, to, now, dl);
      tset(it.h, a < 0 ? DROP[k] : d === 0 ? 0 : DROP[k] + 14, now, dl);
      it.flag.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "flag " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "podiumflags",
  means: "Four flag stands on a dais: the flag under the pointer runs up and swings to face the room, its neighbours turn part way after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[141, 138], [220, 178], [259, 198], null],
  mount,
});

lunchtrays.code:
/**
 * Lunch trays: four cafeteria trays laid along a counter, each moulded with
 * a main well and two small ones, an apple in one. The pointer picks a tray
 * by where it is along the row: that tray lifts off the counter, its
 * neighbours rise a little after it. At rest the trays sit a touch out of
 * line, the one with the apple bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is the nearest rest
 * centre along screen x.
 */
const {
  Cam, clamp, facing, fit, poly, prism, proj, rings, ringAt, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 27, W = 23, D = 34, T = 2.4, LIFT = 22, BUMP = 6;
const OFF = [1, -3, 2, -1], REST = [1, 0, 3, 0.5], FAV = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.25);
  const X1 = (N - 1) * STEP + W;
  fit(C, [[0, -4, 0], [X1, D + 3, 0], [X1, -4, 0], [0, D + 3, 0], [0, -4, LIFT + 9], [X1, -4, LIFT + 9]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the counter: a long low plate the trays rest on
  const [cr, ci] = rings(-6, -8, X1 + 6, D + 7, 6, 1.4);
  put(solid(g), prism(P, front, cr, ci, -5, 0));

  const trays = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * STEP, y0 = OFF[k];
    const grp = mk("g", {}, g);
    const body = solid(grp);
    const wells = mk("path", { class: "nf lo" }, grp);
    const apple = k === FAV ? solid(grp) : null;
    trays.push({ k, x0, y0, body, wells, apple, z: tween(REST[k]), last: NaN });
  }

  function draw(t, z) {
    if (z === t.last) return;
    t.last = z;
    const { x0, y0 } = t;
    const [r, i] = rings(x0, y0, x0 + W, y0 + D, 4, 1.2);
    put(t.body, prism(P, front, r, i, z, z + T));
    const zt = z + T;
    t.wells.setAttribute("d",
      poly(ringAt(P, rrect(x0 + 2.5, y0 + 14, x0 + W - 2.5, y0 + D - 2.5, 3, 4), zt)) +
      poly(ringAt(P, rrect(x0 + 2.5, y0 + 2.5, x0 + W / 2 - 0.8, y0 + 12, 2.5, 4), zt)) +
      poly(ringAt(P, rrect(x0 + W / 2 + 0.8, y0 + 2.5, x0 + W - 2.5, y0 + 12, 2.5, 4), zt)));
    if (t.apple) {
      const cx = x0 + W * 0.74, cy = y0 + 7.2;
      const [ar, ai] = rings(cx - 3.4, cy - 3.4, cx + 3.4, cy + 3.4, 3.4, 1);
      put(t.apple, prism(P, front, ar, ai, zt, zt + 5.5));
    }
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    trays.forEach((t) => { draw(t, tval(t.z, now)); if (!tdone(t.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest tray by its rest centre along screen x, inside the row's band
  const centres = trays.map((t) => P(t.x0 + W / 2, t.y0 + D / 2, REST[t.k]));
  function hit([sx, sy]) {
    let best = -1, bd = 1e9;
    centres.forEach((c, k) => { const d = Math.abs(sx - c[0]); if (d < bd && Math.abs(sy - c[1]) < 70) { bd = d; best = k; } });
    return bd < 40 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    trays.forEach((t, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : clamp(BUMP - 2 * Math.abs(k - a), 0, BUMP);
      tset(t.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      t.body.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tray " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "lunchtrays",
