easelboard.code:
/**
 * Flip chart: a pad of pages clamped to the top of an easel board, a marker
 * ledge across its foot. The pointer picks a page by where it is across the
 * board: the pages before it flip up over the clamp, staggered from it, and
 * the chosen page hangs bright. At rest the top page is lifted a little off
 * the pad, bright. The slider is the stagger.
 *
 * The pattern: which-of-many by fixed screen bands across the rest board;
 * paint order follows each page's depth.
 */
const {
  Cam, clamp, facing, fillet, fit, poly, prism, proj, rad, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, W = 60, Z0 = 24, Z1 = 84, L = 54, REST = [28, 4, 0, 0];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-2, -20, 0], [W + 2, 6, 0], [W + 2, -20, 0], [-2, 6, 0], [0, -12, Z1 + L], [W, -12, Z1 + L], [W, L * 0.7, Z1]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r, b, parent) => { const [a, i] = rings(x0, y0, x1, y1, r, b); const s = solid(parent || g); put(s, prism(P, front, a, i, z0, z1)); return s; };

  // the stand: a back leg, the board, then the pages, the ledge and the front legs
  box(W / 2 - 1.5, -20, W / 2 + 1.5, -17, 0, Z1 - 8, 1.2, 0.5);
  box(-1, -2, W + 1, 0, Z0 - 4, Z1 + 1, 0.9, 0.4);
  const pg = mk("g", {}, g);
  box(-3, 0, W + 3, 7, Z0 - 4, Z0 - 1, 1.5, 0.6);
  box(3, 1, 6, 4, 0, Z0 - 4, 1.2, 0.5);
  box(W - 6, 1, W - 3, 4, 0, Z0 - 4, 1.2, 0.5);
  box(-2, -1, W + 2, 4.5, Z1, Z1 + 3, 1.5, 0.6);

  const pages = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, pg);
    pages.push({ k, py: 0.6 + (N - 1 - k) * 0.7, grp, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), a: tween(REST[k]), last: NaN, my: 0 });
  }
  const corners = fillet([[1, 0], [W - 1, 0], [W - 1, L], [1, L]], [0.1, 0.1, 3, 3], 4);
  const lines = [[8, 12, 34], [8, 20, 48], [8, 28, 26]];

  function draw(p, a) {
    if (a === p.last) return false;
    p.last = a;
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    const at = (u, d) => P(u, p.py + d * s, Z1 - d * c);
    p.sil.setAttribute("d", poly(corners.map(([u, d]) => at(u, d))));
    p.cr.setAttribute("d", lines.map(([u, d, w]) => "M" + at(u, d).join(",") + "L" + at(u + w, d).join(",")).join(""));
    p.my = p.py + (L / 2) * s;
    return true;
  }

  const B = register(stage, (_dt, now) => {
    let moving = false, changed = false;
    pages.forEach((p) => { if (draw(p, tval(p.a, now))) changed = true; if (!tdone(p.a, now)) moving = true; });
    if (changed) pages.slice().sort((a, b) => a.my - b.my).forEach((p) => pg.appendChild(p.grp));
    return moving;
  });
  bag.add(B.unregister);

  // the hit: bands across the board at rest, fixed in screen space
  const xl = P(0, 0, (Z0 + Z1) / 2)[0], xr = P(W, 0, (Z0 + Z1) / 2)[0];
  const top = P(0, 0, Z1 + 4)[1], bot = P(W, 0, Z0 - 4)[1];
  function hit([sx, sy]) {
    if (sx < xl - 4 || sx > xr + 4 || sy < top - 6 || sy > bot + 6) return -1;
    return clamp(Math.floor(((sx - xl) / (xr - xl)) * N), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    pages.forEach((p, k) => {
      const t = a < 0 ? REST[k] : k < a ? 168 - 5 * k : k === a ? 6 : 0;
      tset(p.a, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      p.sil.classList.toggle("hi", k === (a < 0 ? 0 : a));
    });
    read.textContent = a < 0 ? "rest" : "page " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "easelboard",
  means: "A flip chart on an easel: point across the board and the pages before that one flip up over the clamp, one after another.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[151, 180], [197, 203], [219, 214], null],
  mount,
});

ambulance.code:
/**
 * Ambulance: a box-bodied van with a low cab, a roof beacon and two rear
 * doors. The pointer near the back swings the doors open, the nearer the
 * wider; away from the back they settle ajar. At rest the beacon is bright.
 * The slider is how far the doors may swing.
 *
 * The pattern: one part answering where the pointer stands (spring).
 */
const {
  Cam, fit, facing, fillet, poly, prism, proj, rings, unproj, clamp, rad, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 74, W = 36, Z0 = 8, ZT = 46, DW = 18, AJAR = 10;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[-28, -2, 0], [L + DW + 2, W + 2, 0], [L + DW + 2, -2, 0], [-28, W, ZT + 6], [L, W + 2, 0], [0, 0, ZT + 6]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = (cx, y) => {
    const pts = [];
    for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; pts.push(P(cx + 8 * Math.cos(t), y, 8 + 8 * Math.sin(t))); }
    return poly(pts);
  };
  // far wheels, then the cab, the body, the near wheels
  for (const cx of [-12, 56]) mk("path", { d: wheel(cx, 2), class: "lo" }, g);
  const [cR, cI] = rings(-28, 1, 2, W - 1, 6, 1.6);
  put(solid(g), prism(P, front, cR, cI, Z0, 34));
  const win = [[-26, W - 1, 22], [-10, W - 1, 22], [-10, W - 1, 31], [-22, W - 1, 31]].map((q) => P(...q));
  mk("path", { d: poly(fillet(win, [1, 1, 1, 1])), class: "nf lo" }, g);
  const [bR, bI] = rings(0, 0, L, W, 4, 1.6);
  put(solid(g), prism(P, front, bR, bI, Z0, ZT));
  mk("path", { d: poly([P(4, W, 26), P(L - 4, W, 26)]), class: "nf lo" }, g);
  const [lR, lI] = rings(8, 12, 18, 24, 2, 0.8);
  const beacon = solid(g);
  put(beacon, prism(P, front, lR, lI, ZT, ZT + 5));
  for (const cx of [-12, 56]) mk("path", { d: wheel(cx, W), class: "sil" }, g);

  // two doors on the back face (x = L), hinged at y = 0 and y = W
  const doors = [0, 1].map(() => mk("path", { class: "sil" }, g));
  const ang = spring(AJAR);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    const tips = [[L + DW * s, DW * c], [L + DW * s, W - DW * c]];
    [[L, 0], [L, W]].forEach(([hx, hy], k) => {
      const [tx, ty] = tips[k];
      const pts = [P(hx, hy, Z0 + 2), P(tx, ty, Z0 + 2), P(tx, ty, ZT - 2), P(hx, hy, ZT - 2)];
      doors[k].setAttribute("d", poly(fillet(pts, [1.5, 1.5, 1.5, 1.5])));
    });
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);
  draw(AJAR);

  let on = null;
  function setOpen(t) {
    const live = t !== null;
    if (live !== on) { on = live; beacon.sil.classList.toggle("hi", !live); doors.forEach((d) => d.classList.toggle("hi", live)); }
    ang.t = live ? AJAR + t * (maxA - AJAR) : AJAR;
    read.textContent = live ? Math.round(ang.t) + "°" : "rest";
    B.wake();
  }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    if (x < -30 || x > L + 30 || y < -40 || y > W + 40) return setOpen(null);
    setOpen(clamp((x - 10) / (L - 10), 0, 1));
  }
  setOpen(null);
  bag.add(pointer(stage, { move, leave: () => setOpen(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; if (on) B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "ambulance",
  means: "An ambulance whose rear doors swing open as the pointer nears the back; the beacon is lit at rest.",
  rules: [1, 3, 5, 8],
  range: [40, 100, 110],
  tour: [[170, 150], [225, 175], [261, 193], null],
  mount,
});

mriscanner.code:
/**
 * Scanner: an imaging gantry with its round bore and a patient bed on a
 * pedestal in front of it. The pointer's place along the bed's axis slides
 * the table into the bore or back out. At rest the table sits drawn out,
 * bright. The slider is the table's travel.
 *
 * The pattern: one part following the pointer along an axis (slide).
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, unproj, clamp, spring, stepS, rrect,
  disposer, mk, pointer, put, register, solid,
} = HL;

const GX0 = 40, GX1 = 70, GY = 46, GZ = 92, BR = 26, BZ = 46, L = 96;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let travel = value;
  const C = Cam(45, 0.5, 1.5);
  fit(C, [[GX0, -GY, 0], [GX1 + 150, GY, 0], [GX0, GY, GZ], [GX0, -GY, GZ], [GX1 + 160, -14, 30]], 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // floor plate
  const [fr, fi] = rings(GX0 - 8, -GY - 8, GX1 + 136, GY + 8, 8, 2);
  put(solid(g), prism(P, front, fr, fi, 0, 3));
  // gantry: a deep rounded block, the bore cut in its front face
  const [gr, gi] = rings(GX0, -GY, GX1, GY, 12, 2);
  put(solid(g), prism(P, front, gr, gi, 3, GZ));
  const bore = (x, r) => { const pts = []; for (let i = 0; i < 48; i++) { const t = (i / 48) * Math.PI * 2; pts.push(P(x, r * Math.cos(t), BZ + r * Math.sin(t))); } return pts; };
  mk("path", { d: poly(bore(GX1, BR + 6)), class: "nf lo" }, g);
  mk("path", { d: poly(bore(GX1, BR)), class: "" }, g);
  mk("path", { d: poly(bore(GX0 + 10, BR)), class: "nf lo" }, g);
  // pedestal under the bed
  const [pr, pi] = rings(GX1 + 40, -12, GX1 + 100, 12, 6, 1.5);
  put(solid(g), prism(P, front, pr, pi, 3, BZ - 18));
  // the table
  const bed = solid(g);
  bed.sil.classList.add("hi");
  const s = spring(0.85);
  let last = NaN;
  function draw(v) {
    if (v === last) return;
    last = v;
    const x0 = GX0 + 4 + v * travel;
    const [br, bi] = rings(x0, -14, x0 + L, 14, 8, 1.5);
    put(bed, prism(P, front, br, bi, BZ - 18, BZ - 13));
  }
  draw(s.x);

  const B = register(stage, (dt) => { const m = stepS(s, dt); draw(s.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [wx] = unproj(C, sx, sy, 0);
    const v = clamp((wx - GX1) / 120, 0, 1);
    s.t = v;
    read.textContent = "bed " + Math.round(v * 100);
    B.wake();
  }
  function leave() { s.t = 0.85; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { travel = v; last = NaN; draw(s.x); }, destroy: bag.dispose };
}

hairline({
  name: "mriscanner",
  means: "A scanner gantry and its bed: the pointer's place along the bed slides the table into the round bore or back out.",
  rules: [1, 3, 5, 8],
  range: [60, 90, 110],
  tour: [[200, 160], [120, 120], [280, 200], null],
  mount,
});

peppermills.code:
/**
 * Pepper mills: four mills of different heights standing in a row on a
 * board, each a round body, a tapered neck, a grinding cap and a knob. The
 * pointer picks a mill by where it stands: it lifts off the board, ready to
 * grind, and the mills beside it rise a little, staggered from it. At rest
 * one mill is raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, register, put, solid,
} = HL;

const N = 4, STEP = 30, R = 9, BZ = 4, LIFT = 18, FAV = 2;
const HS = [30, 40, 26, 36];
const X1 = (N - 1) * STEP + 2 * R + 8;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-4, -4, 0], [X1, 2 * R + 8, 0], [X1, -4, 0], [-4, 2 * R + 8, 0], [R + 4, R + 4, BZ + 54 + LIFT], [X1 - R, R + 4, BZ + 54 + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-4, -4, X1, 2 * R + 8, 5, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = R + 4 + k * STEP, y = R + 4, grp = mk("g", {}, g), h = HS[k];
    const body = mk("path", { class: "sil" }, grp), crease = mk("path", { class: "nf lo" }, grp);
    const neck = mk("path", { class: "sil" }, grp), cap = mk("path", { class: "sil" }, grp);
    const groove = mk("path", { class: "nf lo" }, grp), knob = mk("path", { class: "sil" }, grp);
    items.push({ k, x, y, h, body, crease, neck, cap, groove, knob, z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN });
  }

  const at = (it, r, z) => ringAt(P, disc(it.x, it.y, r), z);
  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = BZ + lift, z1 = z0 + it.h, z2 = z1 + 7, z3 = z2 + 8;
    it.body.setAttribute("d", poly(hull(at(it, R, z0).concat(at(it, R, z1)))));
    it.crease.setAttribute("d", poly(at(it, R - 2, z1 - 4)));
    it.neck.setAttribute("d", poly(hull(at(it, R, z1).concat(at(it, 5.5, z2)))));
    it.cap.setAttribute("d", poly(hull(at(it, 7, z2).concat(at(it, 7, z3)))));
    it.groove.setAttribute("d", poly(at(it, 5, z3)));
    it.knob.setAttribute("d", poly(hull(at(it, 2.2, z3).concat(at(it, 2.2, z3 + 3.5)))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, BZ + it.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      for (const el of [it.body, it.neck, it.cap, it.knob]) el.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "mill " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "peppermills",
  means: "Four pepper mills on a board: the mill under the pointer lifts off to grind, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[135, 160], [178, 173], [265, 225], null],
  mount,
});

hangingfiles.code:
/**
 * Hanging files: a row of suspension folders in an open drawer, each with a
 * tab at a different place along its top. The pointer picks a folder by
 * where it stands: it lifts out of the drawer, its neighbours rise a little,
 * staggered from it. At rest one folder stands half out, bright.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 7, STEP = 10, X0 = 8, Y1 = 44, H = 26, FZ = 4, FH = 26, LIFT = 18, FAV = 4;
const X1 = X0 * 2 + (N - 1) * STEP;
const REST = [1, 0, 2, 0, LIFT * 0.6, 1, 0];
const TABS = [5, 17, 29, 11, 23, 33, 7];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.65);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [X1, 0, 0], [0, Y1, 0], [X0, 4, FZ + FH + LIFT + 5], [X1 - X0, Y1 - 4, FZ + FH + LIFT + 5]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, X1, Y1, 3, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, H));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP, grp = mk("g", {}, g);
    const body = solid(grp), tab = solid(grp);
    const [fr, fi] = rings(x - 0.9, 3, x + 0.9, Y1 - 3, 0.8, 0.4);
    const [tr, ti] = rings(x - 0.7, TABS[k], x + 0.7, TABS[k] + 9, 0.6, 0.3);
    items.push({ k, x, body, tab, fr, fi, tr, ti, z: tween(REST[k]), last: NaN });
  }
  // the drawer's near walls cover the folders' lower halves
  const [wr, wi] = rings(0, Y1 - 2.4, X1, Y1, 1.2, 0.6);
  put(solid(g), prism(P, front, wr, wi, 0, H));
  const [xr, xi] = rings(X1 - 2.4, 0, X1, Y1, 1.2, 0.6);
  put(solid(g), prism(P, front, xr, xi, 0, H));
  const [pr, pi] = rings(X1 - 0.5, Y1 / 2 - 7, X1 + 3, Y1 / 2 + 7, 1.5, 0.6);
  put(solid(g), prism(P, front, pr, pi, H - 9, H - 5));

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = FZ + lift, z1 = z0 + FH;
    put(it.body, prism(P, front, it.fr, it.fi, z0, z1));
    put(it.tab, prism(P, front, it.tr, it.ti, z1 - 0.5, z1 + 4));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, Y1 / 2, FZ + FH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 16 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? REST[k] : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      it.body.sil.classList.toggle("hi", on);
      it.tab.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "file " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "hangingfiles",
  means: "Suspension folders in an open drawer: the folder under the pointer lifts out by its tab, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[163, 167], [219, 196], [256, 214], null],
  mount,
});

airhockey.code:
/**
 * Air hockey: a table with a rail, a centre line and circle, two mallets at
 * the ends and a puck. The puck slides on a spring to the point of the table
 * under the pointer, the mallet on that half follows behind it, and the paint
 * order follows them. At rest
 * the puck sits off centre, bright. The slider is how far it travels.
 *
 * The pattern: one part following the pointer on a plane (terrain pick).
 */
const {
  Cam, circ, clamp, fit, facing, poly, prism, proj, rings, ringAt, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 130, D = 70, TZ = 10, RIM = 4, PR = 5, RX = 80, RY = 24;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, 0, TZ + 12], [W, D, TZ + 12]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the table body, then its playing surface inside a rail
  const [tr, ti] = rings(0, 0, W, D, 8, 2);
  put(solid(g), prism(P, front, tr, ti, 0, TZ));
  const [sr, si] = rings(RIM, RIM, W - RIM, D - RIM, 6, 1.2);
  put(solid(g), prism(P, front, sr, si, TZ, TZ + 0.01));
  mk("path", { d: seg(P(W / 2, RIM, TZ), P(W / 2, D - RIM, TZ)), class: "nf lo" }, g);
  mk("path", { d: poly(ringAt(P, disc(W / 2, D / 2, 12, 36), TZ)), class: "nf lo" }, g);
  // the goals: slots in the short rails
  for (const x of [RIM / 2, W - RIM / 2]) mk("path", { d: seg(P(x, D / 2 - 10, TZ), P(x, D / 2 + 10, TZ)), class: "nf" }, g);

  const parts = [];
  const mallets = [];
  function mallet(x, y, side) {
    const grp = mk("g", {}, g), m = { grp, side, hx: x, hy: y, sx: spring(x), sy: spring(y), base: solid(grp), grip: solid(grp), lx: NaN, ly: NaN };
    m.draw = () => {
      if (m.sx.x === m.lx && m.sy.x === m.ly) return;
      const x = (m.lx = m.sx.x), y = (m.ly = m.sy.x);
      put(m.base, prism(P, front, disc(x, y, 7.5), disc(x, y, 6), TZ, TZ + 2.5));
      put(m.grip, prism(P, front, disc(x, y, 3.2, 20), disc(x, y, 2.2, 20), TZ + 2.5, TZ + 10));
    };
    mallets.push(m);
    parts.push({ grp, key: () => m.sx.x + m.sy.x });
  }
  mallet(16, D / 2 + 6, -1);
  mallet(W - 16, D / 2 - 8, 1);
  const pg = mk("g", {}, g), puck = solid(pg);
  puck.sil.classList.add("hi");
  const px = spring(RX), py = spring(RY);
  parts.push({ grp: pg, key: () => px.x + py.x });

  let lx = NaN, ly = NaN, order = "";
  function draw() {
    mallets.forEach((m) => m.draw());
    if (px.x !== lx || py.x !== ly) {
      lx = px.x; ly = py.x;
      put(puck, prism(P, front, disc(lx, ly, PR), disc(lx, ly, PR - 1.2), TZ, TZ + 1.8));
    }
    const sorted = parts.slice().sort((a, b) => a.key() - b.key());
    const o = sorted.map((p) => parts.indexOf(p)).join();
    if (o !== order) { order = o; sorted.forEach((p) => g.appendChild(p.grp)); }
  }
  const B = register(stage, (dt) => {
    let m = stepS(px, dt) | stepS(py, dt);
    for (const k of mallets) m |= stepS(k.sx, dt) | stepS(k.sy, dt);
    draw();
    return !!m;
  });
  bag.add(B.unregister);

  function aim(p) {
    const [wx, wy] = unproj(C, p[0], p[1], TZ);
    if (wx < -10 || wx > W + 10 || wy < -10 || wy > D + 10) return leave();
    const tx = clamp(wx, RIM + PR, W - RIM - PR), ty = clamp(wy, RIM + PR, D - RIM - PR);
    px.t = RX + (tx - RX) * reach; py.t = RY + (ty - RY) * reach;
    // the mallet on the pointer's half comes up behind the puck, staying on its own side
    for (const k of mallets) {
      const mine = (tx < W / 2 ? -1 : 1) === k.side;
      k.sx.t = mine ? clamp(px.t + k.side * 16, k.side < 0 ? RIM + 8 : W / 2 + 8, k.side < 0 ? W / 2 - 8 : W - RIM - 8) : k.hx;
      k.sy.t = mine ? clamp(py.t, RIM + 8, D - RIM - 8) : k.hy;
    }
    read.textContent = "puck " + (1 + Math.floor(tx / (W / 5))) + "·" + (1 + Math.floor(ty / (D / 3)));
    B.wake();
  }
  function leave() { px.t = RX; py.t = RY; for (const k of mallets) { k.sx.t = k.hx; k.sy.t = k.hy; } read.textContent = "rest"; B.wake(); }
  leave();
  draw();
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "airhockey",
  means: "An air hockey table: the puck slides to the point under the pointer and the mallet on that half comes up behind it.",
  rules: [1, 3, 5, 6],
  range: [0.4, 0.8, 1],
  tour: [[124, 157], [250, 170], [200, 150], null],
  mount,
});

laundrybasket.code:
/**
 * Laundry baskets: three woven hampers of different heights on a mat, each
 * with a hinged lid and a hand slot. The pointer picks a hamper by where it
 * stands: its lid swings open on the back hinge to show the folded washing,
 * and the hampers beside it crack theirs, staggered from it. At rest one lid
 * stands ajar, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, fillet, hull, open, poly, prism, proj, rad, rings, ringAt, rrect, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, W = 34, D = 28, GAP = 12, Z0 = 2, HS = [30, 38, 33], FAV = 1, OPEN = 100, AJAR = 68;
const X1 = N * W + (N - 1) * GAP;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  const top = Z0 + Math.max(...HS);
  fit(C, [[-8, -8, 0], [X1 + 8, D + 8, 0], [X1 + 8, -8, 0], [-8, D + 8, 0], [0, -2, top + D + 3], [X1, -2, top + D + 3]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [mr, mi] = rings(-8, -8, X1 + 8, D + 8, 6, 2);
  put(solid(g), prism(P, front, mr, mi, 0, Z0));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * (W + GAP), x1 = x0 + W, T = Z0 + HS[k], grp = mk("g", {}, g);
    const [br, bi] = rings(x0, 0, x1, D, 6, 2);
    put(solid(grp), prism(P, front, br, bi, Z0, T));
    // the weave: two bands round the visible faces
    for (const f of [0.33, 0.62]) mk("path", { d: open(ringAt(P, run(br, front), Z0 + HS[k] * f)), class: "nf lo" }, grp);
    // the hand slot on the front face
    const xm = (x0 + x1) / 2, slot = [[xm - 6, D, T - 7], [xm + 6, D, T - 7], [xm + 6, D, T - 3.5], [xm - 6, D, T - 3.5]].map((p) => P(...p));
    mk("path", { d: poly(fillet(slot, [1.5, 1.5, 1.5, 1.5])), class: "nf lo" }, grp);
    // the washing folded inside, seen once the lid lifts
    mk("path", { d: poly(ringAt(P, rrect(x0 + 5, 5, x1 - 5, D - 5, 4, 4), T)), class: "nf lo" }, grp);
    mk("path", { d: open([P(x0 + 6, D / 2 - 2, T), P(x1 - 9, D / 2 + 1, T), P(x1 - 6, D / 2 + 5, T)]), class: "nf lo" }, grp);
    const lid = mk("path", { class: "sil" }, grp), lcr = mk("path", { class: "nf lo" }, grp);
    const ring = rrect(x0 - 1, -1, x1 + 1, D + 1, 7, 6), inner = rrect(x0 + 1.5, 1.5, x1 - 1.5, D - 1.5, 5, 6);
    items.push({ k, x0, x1, T, lid, lcr, ring, inner, a: tween(k === FAV ? AJAR : 0), last: NaN });
  }

  // a lid point (u, v) at thickness dz, swung by ang about the back hinge
  const swing = (it, u, v, dz, ang) => {
    const dy = v + 1, c = Math.cos(rad(ang)), s = Math.sin(rad(ang));
    return P(u, -1 + dy * c - dz * s, it.T + dy * s + dz * c);
  };
  function draw(it, ang) {
    if (ang === it.last) return;
    it.last = ang;
    const pts = [];
    for (const q of it.ring) pts.push(swing(it, q.u, q.v, 0, ang), swing(it, q.u, q.v, 2.2, ang));
    it.lid.setAttribute("d", poly(hull(pts)));
    it.lcr.setAttribute("d", poly(it.inner.map((q) => swing(it, q.u, q.v, 2.2, ang))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P((it.x0 + it.x1) / 2, D / 2, it.T / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), ang = a < 0 ? (k === FAV ? AJAR : 0) : dd === 0 ? OPEN : dd === 1 ? 14 : 0;
      tset(it.a, ang, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.lid.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bin " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "laundrybasket",
  means: "Three woven hampers on a mat: the lid under the pointer swings open on its hinge, and its neighbours crack theirs.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[128, 165], [184, 147], [238, 190], null],
  mount,
});

lathe.code:
/**
 * Lathe: a long bed with a headstock and chuck at one end, a tailstock at
 * the other, a round workpiece held between them, and a tool carriage on
 * the front ways. The carriage slides along the bed to the pointer, its
 * cutting tool riding against the workpiece. At rest it sits a third of the
 * way along, tool bright. The slider is how much of the bed it may travel.
 *
 * The pattern: one part sliding to follow the pointer.
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rings, rrect, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 160, W = 46, BZ = 10, AX = 20, AZ = 34, R = 7, X0 = 34, X1 = 128, REST = 62;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value / 100;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[0, 0, 0], [L, W, 0], [L, 0, 0], [0, W, 0], [0, 0, 58], [L, W, 30]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r = 3, b = 1.4, par = g) => {
    const [a, i] = rings(x0, y0, x1, y1, r, b);
    const s = solid(par);
    put(s, prism(P, front, a, i, z0, z1));
    return s;
  };
  box(0, 0, L, W, 0, BZ, 5, 2);
  box(4, 6, L - 4, 18, BZ, BZ + 4, 2, 1); // rear ways
  box(0, 2, 30, 40, BZ, 52, 5, 2); // headstock
  // a round bar lying along x, as the hull of its two end circles
  const bar = (x0, x1, r, cls, par = g) => {
    const pts = [];
    const end = [];
    for (let i = 0; i < 28; i++) {
      const t = (i / 28) * Math.PI * 2, y = AX + r * Math.cos(t), z = AZ + r * Math.sin(t);
      pts.push(P(x0, y, z), P(x1, y, z));
      end.push(P(x1, y, z));
    }
    mk("path", { d: poly(hull(pts)), class: cls }, par);
    mk("path", { d: poly(hull(end)), class: "nf lo" }, par);
  };
  bar(30, 38, 12, "sil"); // chuck
  for (let k = 0; k < 3; k++) { const t = (k / 3) * Math.PI * 2 + 0.5; mk("path", { d: poly(hull([P(36, AX + 9 * Math.cos(t) - 1.5, AZ + 9 * Math.sin(t)), P(36, AX + 9 * Math.cos(t) + 1.5, AZ + 9 * Math.sin(t)), P(40, AX + 9 * Math.cos(t) + 1.5, AZ + 9 * Math.sin(t)), P(40, AX + 9 * Math.cos(t) - 1.5, AZ + 9 * Math.sin(t))])), class: "lo" }, g); }
  bar(38, 134, R, "sil"); // workpiece
  box(134, 8, 156, 32, BZ, 40, 4, 1.6); // tailstock
  bar(126, 134, 2.5, "sil"); // centre
  box(4, 32, L - 4, 42, BZ, BZ + 3, 2, 1); // front ways

  const car = mk("g", {}, g);
  const pos = spring(REST);
  let last = NaN;
  function draw(x) {
    if (x === last) return;
    last = x;
    car.replaceChildren();
    box(x - 12, 26, x + 12, 44, BZ + 3, BZ + 10, 3, 1.4, car); // saddle
    box(x - 7, 28, x + 7, 40, BZ + 10, AZ - 6, 2.5, 1.2, car); // cross slide
    const tool = box(x - 2, AX + R + 0.5, x + 2, 38, AZ - 6, AZ - 2, 1, 0.6, car);
    tool.sil.classList.add("hi");
  }
  draw(REST);
  const B = register(stage, (dt) => { const m = stepS(pos, dt); draw(pos.x); return m; });
  bag.add(B.unregister);

  function aim(p) {
    const [x] = unproj(C, p[0], p[1], BZ);
    const span = (X1 - X0) * reach / 2;
    const t = clamp(x, REST - span, REST + span);
    pos.t = clamp(t, X0, X1);
    read.textContent = "z " + String(Math.round(pos.t - X0)).padStart(3, "0");
    B.wake();
  }
  function leave() { pos.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v / 100; }, destroy: bag.dispose };
}

hairline({
  name: "lathe",
  means: "A lathe with a round workpiece between its centres: the tool carriage slides along the bed to the pointer.",
  rules: [1, 3, 5, 8],
  range: [40, 100, 100],
  tour: [[250, 220], [130, 140], [210, 180], null],
  mount,
});

scarecrow.code:
/**
 * Scarecrow: a straw figure on a pole in a square plot, arms out on a
 * crossbar, a round head under a brimmed hat. The scarecrow turns on its
 * pole to face the pointer, arms swinging round with it. At rest it stands
 * a quarter-turn off, arms bright. The slider is how far it may turn.
 *
 * The pattern: one part turning to face the pointer.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, ringAt, rrect, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const CX = 40, CY = 40, REST = 35;
const disc = (r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + CX, v: q.v + CY }));
function rot(ring, a) {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: CX + q.u * c - q.v * s, v: CY + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[0, 0, 0], [80, 80, 0], [80, 0, 0], [0, 80, 0], [CX, CY, 92], [CX - 32, CY - 32, 52], [CX + 32, CY + 32, 52]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(0, 0, 80, 80, 8, 2);
  put(solid(g), prism(P, front, pr, pi, 0, 4));
  // furrows across the plot
  for (let i = 1; i < 5; i++) mk("path", { d: "M" + P(6, i * 16, 4) + "L" + P(74, i * 16, 4), class: "nf lo" }, g);
  put(solid(g), prism(P, front, disc(2.2, 16), disc(1.2, 16), 4, 30));

  const torso = solid(g), arms = solid(g);
  arms.sil.classList.add("hi");
  const legs = rrect(-6, -9, 6, 9, 4, 4), legsI = rrect(-4.6, -7.6, 4.6, 7.6, 3, 4);
  const bar = rrect(-3, -30, 3, 30, 3, 4), barI = rrect(-1.8, -28.8, 1.8, 28.8, 1.8, 4);
  // head, hat: round, they do not show the turn
  const hg = mk("g", {}, g);
  put(solid(hg), prism(P, front, disc(1.6, 12), disc(0.8, 12), 52, 56));
  const head = [];
  for (let i = 0; i <= 6; i++) { const t = (i / 6) * Math.PI; head.push(...ringAt(P, disc(Math.max(0.5, 8 * Math.sin(t)), 24), 56 + 8 - 8 * Math.cos(t))); }
  mk("path", { d: poly(hull(head)), class: "sil" }, hg);
  put(solid(hg), prism(P, front, disc(15, 40), disc(13, 40), 70, 71.5));
  put(solid(hg), prism(P, front, rrect(CX - 7, CY - 7, CX + 7, CY + 7, 6, 6), rrect(CX - 5.8, CY - 5.8, CX + 5.8, CY + 5.8, 5, 6), 71.5, 80));

  const ang = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const r = (a * Math.PI) / 180;
    put(torso, prism(P, front, rot(legs, r), rot(legsI, r), 28, 50));
    put(arms, prism(P, front, rot(bar, r), rot(barI, r), 46, 51));
  }
  draw(REST);
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function aim(p) {
    const [x, y] = unproj(C, p[0], p[1], 0);
    const want = (Math.atan2(y - CY, x - CX) * 180) / Math.PI + 90;
    let d = want - REST;
    d = ((d % 180) + 270) % 180 - 90; // a crossbar looks the same half a turn round
    d = clamp(d, -reach, reach);
    ang.t = REST + d;
    read.textContent = String(Math.round(((REST + d) % 360 + 360) % 360)).padStart(3, "0") + "°";
    B.wake();
  }
  function leave() { ang.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "scarecrow",
  means: "A scarecrow on a pole in a field plot turns to face the pointer, its arms swinging round on the crossbar.",
  rules: [1, 3, 5, 8],
  range: [30, 90, 90],
  tour: [[300, 150], [110, 230], [260, 260], null],
  mount,
});

votingbooths.code:
/**
 * Voting booths: four booths in a row, each with an opening in its face and a
 * curtain hung on a rail across it, a writing shelf behind. The pointer picks
 * a booth by where it stands: its curtain draws aside to show the shelf, and
 * the curtains beside it part a little, staggered from it. At rest one
 * curtain is half drawn, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, fillet, lerp, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, W = 30, GAP = 9, D = 22, H = 56, FAV = 1, OZ0 = 8, OZ1 = H - 7, IN = 4;
const REST = [0.12, 0.6, 0.04, 0.24];
const X1 = N * W + (N - 1) * GAP;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.72);
  fit(C, [[-4, -4, 0], [X1 + 4, D + 6, 0], [X1 + 4, -4, 0], [-4, D + 6, 0], [0, 0, H + 3], [X1, 0, H + 3]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-4, -4, X1 + 4, D + 6, 4, 1.5);
  put(solid(g), prism(P, front, br, bi, 0, 3));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * (W + GAP), grp = mk("g", {}, g);
    const [r, i] = rings(x0, 0, x0 + W, D, 3, 1.4);
    put(solid(grp), prism(P, front, r, i, 3, H));
    const yf = D + 0.1, ox0 = x0 + IN, ox1 = x0 + W - IN;
    const q = (x, z) => P(x, yf, z);
    mk("path", { d: poly(fillet([q(ox0, OZ0), q(ox1, OZ0), q(ox1, OZ1), q(ox0, OZ1)], [1.5, 1.5, 1.5, 1.5])), class: "nf lo" }, grp);
    // the shelf behind the curtain, and the rail above it
    mk("path", { d: seg(q(ox0, 30), q(ox1, 30)) + seg(q(ox0 + 2, 30), P(ox0 + 2, yf - 7, 30)) + seg(q(ox1 - 2, 30), P(ox1 - 2, yf - 7, 30)), class: "nf lo" }, grp);
    mk("path", { d: seg(P(ox0 - 2, yf + 1.2, OZ1 + 2), P(ox1 + 2, yf + 1.2, OZ1 + 2)), class: "nf" }, grp);
    const cur = mk("path", { class: "sil" }, grp), folds = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x0, ox0, ox1, cur, folds, o: tween(REST[k]), last: NaN });
  }

  function draw(it, open) {
    if (open === it.last) return;
    it.last = open;
    const y = D + 1.2, w = lerp(it.ox1 - it.ox0 + 1, 6, open), xa = it.ox0 - 0.5, xb = xa + w, zb = OZ0 + 1 + open * 4;
    const pts = [P(xa, y, zb + 1), P(xb, y, zb), P(xb, y, OZ1 + 2), P(xa, y, OZ1 + 2)];
    it.cur.setAttribute("d", poly(fillet(pts, [1.2, 1.2, 0.6, 0.6])));
    let d = "";
    for (let f = 1; f < 4; f++) { const x = xa + (w * f) / 4; d += seg(P(x, y, OZ1 + 1), P(x, y, zb + 3)); }
    it.folds.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.o, now)); if (!tdone(it.o, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x0 + W / 2, D, H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), o = a < 0 ? REST[k] : dd === 0 ? 1 : dd === 1 ? 0.3 : 0.06;
      tset(it.o, o, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.cur.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "booth " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "votingbooths",
  means: "Four voting booths in a row: the curtain under the pointer draws aside to show the shelf, and its neighbours part a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[97, 129], [163, 162], [285, 222], null],
  mount,
});

kitchensink.code:
/**
 * Kitchen sink: a cabinet with a counter, a basin sunk in it with its drain,
 * a stack of plates beside it and a swivel tap at the back. The pointer over
 * the counter turns the spout to face it, clamped to the basin's width, and
 * water runs from the tip while it is there. At rest the spout stands turned
 * aside over the counter, bright, and dry. The slider is how far the spout may swing.
 *
 * The pattern: a part turning to face the pointer (aim).
 */
const {
  Cam, circ, clamp, fit, facing, lerp, open, poly, prism, proj, rad, rings, ringAt, rrect, run, seg, spring, stepS, unproj,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const X1 = 124, Y1 = 72, ZC = 34, ZT = 38, TX = 50, TY = 9, ZS = 64, L = 31, REST = 4, FLOOR = ZT - 12;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const turn = (ring, a, x, y) => { const c = Math.cos(a), s = Math.sin(a); return ring.map((q) => ({ u: x + q.u * c - q.v * s, v: y + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c })); };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.55);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [X1, 0, 0], [0, Y1, 0], [TX, TY, ZS + 4], [-2, -2, ZT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(2, 2, X1 - 2, Y1 - 2, 3, 1.5);
  put(solid(g), prism(P, front, cr, ci, 0, ZC));
  const [tr, ti] = rings(-2, -2, X1 + 2, Y1 + 2, 3, 1.4);
  put(solid(g), prism(P, front, tr, ti, ZC, ZT));
  // the basin: its rim on the counter, the far wall falling to its floor, the drain
  const rim = rrect(24, 22, 84, 62, 8, 6), fl = rrect(28, 26, 80, 58, 6, 6);
  mk("path", { d: poly(ringAt(P, rim, ZT)), class: "nf" }, g);
  mk("path", { d: open(ringAt(P, run(fl, (q) => !front(q)), FLOOR)), class: "nf lo" }, g);
  mk("path", { d: seg(P(24, 22, ZT), P(28, 26, FLOOR)) + seg(P(84, 22, ZT), P(80, 26, FLOOR)) + seg(P(24, 62, ZT), P(28, 58, FLOOR)), class: "nf lo" }, g);
  const drain = flatDot(g, C, 2.2, "dot off");
  place(drain, P(54, 42, FLOOR));
  // plates stacked to the right of the basin
  for (let k = 0; k < 3; k++) {
    const z = ZT + k * 2.4;
    put(solid(g), prism(P, front, disc(104, 44, 13 - k * 0.6), disc(104, 44, 9 - k * 0.6), z, z + 1.6));
  }
  // the tap: a column at the back, a lever, and the spout that swings
  put(solid(g), prism(P, front, disc(TX, TY, 5, 24), disc(TX, TY, 3.6, 24), ZT, ZS));
  put(solid(g), prism(P, front, disc(TX + 8, TY - 1, 2, 12), disc(TX + 8, TY - 1, 1.2, 12), ZT, ZT + 9));
  const water = mk("path", { class: "nf" }, g);
  const spout = solid(g), tip = solid(g);
  spout.sil.classList.add("hi");
  const [sr, si] = rings(-2.8, -2.8, L, 2.8, 2.8, 1);
  const ang = spring(REST);
  let wet = false, last = NaN;

  function draw(a) {
    if (a === last) return;
    last = a;
    const t = rad(a), x = TX + (L - 2) * Math.cos(t), y = TY + (L - 2) * Math.sin(t);
    put(spout, prism(P, front, turn(sr, t, TX, TY), turn(si, t, TX, TY), ZS - 4, ZS));
    put(tip, prism(P, front, disc(x, y, 2.6, 16), disc(x, y, 1.6, 16), ZS - 9, ZS - 3));
    water.setAttribute("d", wet ? seg(P(x - 0.8, y, ZS - 9.5), P(x - 0.8, y, FLOOR)) + seg(P(x + 0.8, y, ZS - 9.5), P(x + 0.8, y, FLOOR)) + poly(ringAt(P, disc(x, y, 5, 20), FLOOR)) : "");
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);
  draw(ang.x);

  function aim(p) {
    if (!p) { ang.t = REST; wet = false; read.textContent = "rest"; last = NaN; B.wake(); return; }
    const [wx, wy] = unproj(C, p[0], p[1], ZT);
    if (wx < -20 || wx > X1 + 20 || wy < -20 || wy > Y1 + 30) return aim(null);
    const span = lerp(25, 60, reach / 90);
    const a = clamp((Math.atan2(wy - TY, wx - TX) * 180) / Math.PI, 90 - span, 90 + span);
    if (!wet) last = NaN;
    wet = true;
    ang.t = a;
    read.textContent = Math.round(a - 90) + "°";
    B.wake();
  }
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "kitchensink",
  means: "A kitchen sink with a swivel tap: the spout turns to face the pointer over the counter, and water runs into the basin.",
  rules: [1, 3, 5, 8],
  range: [0, 45, 90],
  tour: [[150, 113], [133, 132], [210, 170], null],
  mount,
});

kilns.code:
/**
 * Kilns: three round top-loading kilns on a fired-brick pad, each with a
 * hinged lid and a banded wall. The pointer picks a kiln by where it stands:
 * its lid swings up on the back hinge, and the kilns beside it crack their
 * lids, staggered from it. At rest one lid is propped open, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, open, prism, proj, rad, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, R = 17, STEP = 44, H = 30, PZ = 4, OPEN = 72, FAV = 1;
const X1 = (N - 1) * STEP + 2 * R;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-7, -7, 0], [X1 + 7, 2 * R + 7, 0], [X1 + 7, -7, 0], [-7, 2 * R + 7, 0], [R, 0, PZ + H + 2 * R], [X1 - R, 0, PZ + H + 2 * R]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-7, -7, X1 + 7, 2 * R + 7, 6, 2);
  put(solid(g), prism(P, front, pr, pi, 0, PZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = R + k * STEP, y = R, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, y, R), disc(x, y, R - 1.6), PZ, PZ + H));
    // the bands round the wall and the peep hole on its face
    for (const z of [PZ + H * 0.35, PZ + H * 0.7]) mk("path", { d: open(ringAt(P, disc(x, y, R, 40), z).filter((_, i) => front(disc(x, y, R, 40)[i]))), class: "nf lo" }, grp);
    mk("path", { d: poly(ringAt(P, disc(x, y, R - 3.2, 36), PZ + H)), class: "nf lo" }, grp);
    const pp = P(x + R * 0.72, y + R * 0.7, PZ + H * 0.52);
    mk("ellipse", { cx: pp[0], cy: pp[1], rx: 2, ry: 1.4, class: "nf" }, grp);
    const lid = mk("path", { class: "sil" }, grp), lc = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, y, lid, lc, a: tween(k === FAV ? 34 : 0), last: NaN });
  }

  // the lid turns about a hinge on its back edge (y - R) at the rim
  function lidRing(it, ang, r, dz) {
    const c = Math.cos(rad(ang)), s = Math.sin(rad(ang)), top = PZ + H + 0.4, hy = it.y - R;
    return disc(it.x, it.y, r, 40).map((q) => { const d = q.v - hy; return P(q.u, hy + d * c - dz * s, top + d * s + dz * c); });
  }
  function draw(it, ang) {
    if (ang === it.last) return;
    it.last = ang;
    it.lid.setAttribute("d", poly(hull(lidRing(it, ang, R + 1, 0).concat(lidRing(it, ang, R + 1, 3.2)))));
    it.lc.setAttribute("d", poly(hull(lidRing(it, ang, 3, 3.2).concat(lidRing(it, ang, 3, 5.6)))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, PZ + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), ang = a < 0 ? (k === FAV ? 34 : 0) : dd === 0 ? OPEN : dd === 1 ? 10 : 0;
      tset(it.a, ang, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.lid.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "kiln " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "kilns",
  means: "Three round kilns on a brick pad: the kiln under the pointer swings its lid up on the hinge, and its neighbours crack theirs.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[138, 135], [200, 166], [262, 197], null],
  mount,
});

looms.code:
/**
 * Looms: a table loom with a warp of threads stretched between two beams and
 * a reed, the beater, standing across them. The pointer slides the beater
 * along the warp: behind it the cloth is woven, pick by pick; in front of it
 * the bare threads run on to the far beam. At rest the beater sits halfway,
 * bright. The slider is where it rests.
 *
 * The pattern: one part following the pointer along a track (slide).
 */
const {
  Cam, fit, facing, poly, open, prism, proj, rings, seg, spring, stepS, clamp, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 124, W = 64, BZ = 4, TZ = 13, X0 = 12, X1 = L - 12, REST = 64, LO = 30, HI = 100;

function mount({ stage, svg, read }, value) {
  let rest = clamp(value, LO, HI), over = false;
  const bag = disposer();
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, -6, 0], [L, W + 6, 0], [L, -6, 0], [0, W + 6, 0], [LO, -6, 30], [HI, W + 6, 30]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r, b, parent = g) => { const [o, i] = rings(x0, y0, x1, y1, r, b); return prism(P, front, o, i, z0, z1); };
  put(solid(g), box(0, 0, L, W, 0, BZ, 5, 2));
  put(solid(g), box(1, 1, X0, W - 1, BZ, TZ + 3, 3, 1.4));
  const cloth = solid(g), weft = mk("path", { class: "nf lo" }, g);
  const reed = solid(g), dents = mk("path", { class: "nf lo" }, g);
  reed.sil.classList.add("hi");
  const warp = mk("path", { class: "nf" }, g);
  put(solid(g), box(X1, 1, L - 1, W - 1, BZ, TZ + 3, 3, 1.4));
  const ys = []; for (let y = 6; y <= W - 6; y += 4.4) ys.push(y);

  const sp = spring(rest);
  let last = NaN;
  function draw(x) {
    if (x === last) return;
    last = x;
    put(cloth, box(X0 - 2, 3, x - 2, W - 3, TZ - 1, TZ + 0.6, 1.2, 0.8));
    let w = "";
    for (let wx = x - 5; wx > X0 + 1; wx -= 5) w += seg(P(wx, 4, TZ + 0.6), P(wx, W - 4, TZ + 0.6));
    weft.setAttribute("d", w);
    put(reed, box(x - 2, -5, x + 2, W + 5, BZ + 2, TZ + 15, 1.5, 0.6));
    let d = "";
    for (let y = 2; y <= W - 2; y += 6) d += seg(P(x + 2, y, BZ + 4), P(x + 2, y, TZ + 13));
    dents.setAttribute("d", d);
    warp.setAttribute("d", ys.map((y) => seg(P(x + 2, y, TZ), P(X1, y, TZ + 1))).join(""));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { over = false; sp.t = rest; read.textContent = "rest"; B.wake(); return; }
    const [wx, wy] = unproj(C, p[0], p[1], TZ);
    if (wy < -20 || wy > W + 20 || wx < -10 || wx > L + 10) return aim(null);
    over = true;
    sp.t = clamp(wx, LO, HI);
    read.textContent = "pick " + Math.round((sp.t - X0) / 5);
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { rest = clamp(v, LO, HI); if (!over) { sp.t = rest; B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "looms",
  means: "A table loom: the beater slides along the warp after the pointer, with woven cloth behind it and bare threads ahead.",
  rules: [1, 3, 5, 6],
  range: [30, 64, 100],
  tour: [[156, 139], [239, 180], [200, 160], null],
  mount,
});

batterywall.code:
/**
 * Battery wall: four home-battery packs standing side by side against a wall
 * plate, each with a status light and a handle seam. The pointer picks a pack
 * by where it is along the row: that pack slides out from the wall, the
 * others ease forward a little, staggered from it. At rest the packs sit at
 * uneven depths, one pulled out and bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is the nearest rest
 * centre by screen x.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, place, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 14, W = 11, D = 9, H = 44, SLIDE = 14, BUMP = 4;
const X1 = (N - 1) * STEP + W;
const REST = [1, 6, 0, 2.5], FAV = 1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.3);
  fit(C, [[-5, -5, 0], [X1 + 5, -5, 0], [-5, D + SLIDE, 0], [X1 + 5, D + SLIDE, 0], [-5, -5, H + 10], [X1 + 5, -5, H + 10]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the wall plate the packs hang against
  const wall = solid(g);
  const [wr, wi] = rings(-5, -5, X1 + 5, -2, 1.4, 0.6);
  put(wall, prism(P, front, wr, wi, 0, H + 10));

  const packs = [];
  for (let k = 0; k < N; k++) {
    const s = solid(g);
    packs.push({ k, x: k * STEP, s, seam: mk("path", { class: "nf lo" }, s.g), led: mk("circle", { class: "dot off", r: 1.6 }, s.g), y: tween(REST[k]), last: NaN });
  }

  function draw(p, y) {
    if (y === p.last) return;
    p.last = y;
    const [r, i] = rings(p.x, y, p.x + W, y + D, 3, 1.2);
    put(p.s, prism(P, front, r, i, 0, H));
    const fy = y + D;
    p.seam.setAttribute("d", seg(P(p.x + 2.5, fy, H - 9), P(p.x + W - 2.5, fy, H - 9)) + seg(P(p.x + 2.5, fy, 6), P(p.x + W - 2.5, fy, 6)));
    place(p.led, P(p.x + W / 2, fy, H - 5));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    packs.forEach((p) => { draw(p, tval(p.y, now)); if (!tdone(p.y, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest pack by its rest centre's screen x, inside the row's box
  const cx = packs.map((p) => P(p.x + W / 2, D / 2, H / 2)[0]);
  const top = P(0, -5, H + 10)[1], bot = P(X1, D + 4, 0)[1];
  function hit([sx, sy]) {
    if (sy < top - 6 || sy > bot + 10) return -1;
    let best = -1, bd = 1e9;
    cx.forEach((c, k) => { const d = Math.abs(sx - c); if (d < bd) { bd = d; best = k; } });
    return bd < 26 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    packs.forEach((p, k) => {
      const y = a < 0 ? REST[k] : k === a ? SLIDE : clamp(BUMP - Math.abs(k - a) * 1.5, 0, BUMP);
      tset(p.y, y, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      p.s.sil.classList.toggle("hi", on);
      p.led.setAttribute("class", on ? "dot" : "dot off");
    });
    read.textContent = a < 0 ? "rest" : "pack " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "batterywall",
  means: "A home battery wall: the pack under the pointer slides out from the wall, the others ease forward after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[150, 160], [212, 166], [248, 172], null],
  mount,
});

safebox.code:
/**
 * Safebox: a wall safe, a heavy box with a door on its right face, a dial
 * and a handle on the door. The pointer's place across the figure swings
 * the door open on its hinge, and the dial turns with it. At rest the door
 * stands ajar, bright. The slider is how far the door may swing.
 *
 * The outer face stays toward the camera to 135°, so paint order never changes.
 *
 * The pattern: one part following the pointer (spring).
 */
const {
  Cam, clamp, fit, facing, open, poly, prism, proj, rad, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 44, D = 56, H = 60, YA = 6, YB = 50, ZA = 8, ZB = 54, T = 3, REST = 22;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[0, 0, 0], [W, D, 0], [W + 46, YB + 16, 0], [0, 0, H], [W + 46, YB + 16, ZB], [W, D, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, D, 4, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, H));
  // the opening on the face, and a shelf inside it
  mk("path", { d: poly([P(W, YA, ZA), P(W, YB, ZA), P(W, YB, ZB), P(W, YA, ZB)]), class: "nf lo" }, g);
  mk("path", { d: open([P(W, YA + 2, 31), P(W - 10, YA + 2, 31), P(W - 10, YB - 2, 31)]), class: "nf lo" }, g);

  const back = mk("path", {}, g), face = mk("path", { class: "sil" }, g);
  const dial = mk("path", { class: "nf" }, g), tick = mk("path", { class: "nf lo" }, g), handle = mk("path", { class: "nf" }, g);
  const a = spring(REST);
  let last = NaN;

  // a point on the door: u along it from the hinge, z up, w out of its face
  function dp(th, u, z, w) {
    const dx = Math.sin(th), dy = -Math.cos(th), nx = Math.cos(th), ny = Math.sin(th);
    return P(W + u * dx + w * nx, YB + u * dy + w * ny, z);
  }
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const th = rad(deg), L = YB - YA;
    const plate = (w) => poly([dp(th, 0, ZA, w), dp(th, L, ZA, w), dp(th, L, ZB, w), dp(th, 0, ZB, w)]);
    back.setAttribute("d", plate(0));
    face.setAttribute("d", plate(T));
    const cu = L * 0.55, cz = (ZA + ZB) / 2 + 4, ring = [];
    for (let i = 0; i < 28; i++) { const f = (i / 28) * Math.PI * 2; ring.push(dp(th, cu + 7 * Math.cos(f), cz + 7 * Math.sin(f), T + 1.2)); }
    dial.setAttribute("d", poly(ring));
    const sp = th * 3;
    tick.setAttribute("d", open([dp(th, cu, cz, T + 1.2), dp(th, cu + 5 * Math.cos(sp), cz + 5 * Math.sin(sp), T + 1.2)]));
    handle.setAttribute("d", poly([dp(th, cu - 2, cz - 22, T), dp(th, cu - 2, cz - 14, T), dp(th, cu - 2, cz - 14, T + 4), dp(th, cu - 2, cz - 22, T + 4)]));
  }

  const B = register(stage, (dt) => {
    const m = stepS(a, dt);
    draw(Math.round(a.x * 10) / 10);
    return m;
  });
  bag.add(B.unregister);

  const x0 = P(0, D, 0)[0], x1 = P(W + 40, 0, 0)[0];
  function setOpen(t) {
    const want = t < 0 ? REST : t * maxA;
    a.t = want;
    face.classList.toggle("hi", true);
    read.textContent = t < 0 ? "rest" : Math.round(want) + "°";
    B.wake();
  }
  setOpen(-1);
  bag.add(pointer(stage, { move: ([sx]) => setOpen(clamp((sx - x0) / (x1 - x0), 0, 1)), leave: () => setOpen(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "safebox",
  means: "A wall safe: the pointer's place across it swings the heavy door open on its hinge, and the dial turns as it goes.",
  rules: [1, 3, 5, 8],
  range: [60, 105, 130],
  tour: [[190, 162], [259, 185], [300, 185], null],
  mount,
});

guardbooth.code:
/**
 * Guardbooth: a guard booth with a window and a flat roof, and a barrier
 * arm on a post beside it. The pointer's height over the figure lifts the
 * arm on its pivot. At rest the arm is tipped up a little, bright. The
 * slider is how high the arm may lift.
 *
 * The pattern: one part following the pointer (spring).
 */
const {
  Cam, clamp, fit, facing, open, poly, prism, proj, rad, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PX = 44, PY = 34, PZ = 24, L = 84, REST = 10;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[0, 0, 0], [PX + L, PY + 4, 0], [0, 0, 58], [PX, PY, PZ + L], [36, 36, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, 32, 32, 3, 1.4);
  put(solid(g), prism(P, front, br, bi, 0, 48));
  const [rr, ri] = rings(-3, -3, 35, 35, 3, 1.4);
  put(solid(g), prism(P, front, rr, ri, 48, 53));
  mk("path", { d: poly([P(32, 6, 24), P(32, 26, 24), P(32, 26, 40), P(32, 6, 40)]), class: "nf lo" }, g);
  mk("path", { d: poly([P(8, 32, 0), P(20, 32, 0), P(20, 32, 36), P(8, 32, 36)]), class: "nf lo" }, g);
  const [pr, pi] = rings(PX - 3, PY - 3, PX + 3, PY + 3, 2, 0.8);
  put(solid(g), prism(P, front, pr, pi, 0, PZ + 4));

  const arm = mk("path", { class: "sil" }, g), stripes = mk("path", { class: "nf lo" }, g);
  const a = spring(REST);
  let last = NaN;
  function ap(th, u, dz) { return P(PX + u * Math.cos(th), PY + 4, PZ + u * Math.sin(th) + dz); }
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const th = rad(deg);
    arm.setAttribute("d", poly([ap(th, -6, -2), ap(th, L, -2), ap(th, L, 2), ap(th, -6, 2)]));
    let d = "";
    for (let i = 1; i < 6; i++) d += open([ap(th, i * 14, -2), ap(th, i * 14 + 5, 2)]);
    stripes.setAttribute("d", d);
  }
  const B = register(stage, (dt) => {
    const m = stepS(a, dt);
    draw(Math.round(a.x * 10) / 10);
    return m;
  });
  bag.add(B.unregister);

  const y0 = P(PX, PY, PZ)[1], y1 = P(PX, PY, PZ + L)[1];
  function setLift(t) {
    const want = t < 0 ? REST : t * maxA;
    a.t = want;
    arm.classList.add("hi");
    read.textContent = t < 0 ? "rest" : Math.round(want) + "°";
    B.wake();
  }
  setLift(-1);
  bag.add(pointer(stage, { move: ([, sy]) => setLift(clamp((y0 - sy) / (y0 - y1), 0, 1)), leave: () => setLift(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "guardbooth",
  means: "A guard booth and its barrier: the pointer's height over the figure lifts the striped arm on its post.",
  rules: [1, 3, 5, 8],
  range: [45, 80, 88],
  tour: [[150, 205], [150, 140], [150, 70], null],
  mount,
});

missioncontrol.code:
/**
 * Mission control: a row of consoles, each a desk with a screen standing on
 * its back edge. The pointer picks a console by where it stands: its screen
 * rises on its stand and the screens beside it rise a little, staggered from
 * it. At rest one screen stands raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, tdone, tset, tval, tween, seg,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 34, W = 30, D = 24, DZ = 14, SH = 18, LIFT = 17, FAV = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.82);
  const X1 = (N - 1) * STEP + W;
  fit(C, [[-4, -4, 0], [X1 + 4, D + 8, 0], [X1 + 4, -4, 0], [-4, D + 8, 0], [0, 0, DZ + SH + LIFT + 6], [X1, 0, DZ + SH + LIFT + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [fr, fi] = rings(-4, -4, X1 + 4, D + 8, 4, 1.5);
  put(solid(g), prism(P, front, fr, fi, 0, 2));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, grp = mk("g", {}, g);
    const [r0, i0] = rings(x + 3, 6, x + W - 3, D - 2, 2, 1);
    put(solid(grp), prism(P, front, r0, i0, 2, DZ - 2));
    const [r1, i1] = rings(x, 0, x + W, D, 2.5, 1.4);
    put(solid(grp), prism(P, front, r1, i1, DZ - 2, DZ));
    // keyboard: a low slab near the front edge
    const [rk, ik] = rings(x + 6, D - 10, x + W - 6, D - 4, 1, 0.6);
    put(solid(grp), prism(P, front, rk, ik, DZ, DZ + 1));
    const scr = mk("g", {}, grp);
    const stand = mk("path", { class: "lo nf" }, scr);
    const body = solid(scr);
    const glass = mk("path", { class: "nf lo" }, scr);
    // put screen behind the keyboard in paint order: insert before keyboard
    grp.insertBefore(scr, grp.children[2]);
    items.push({ k, x, scr, stand, body, glass, z: tween(k === FAV ? LIFT * 0.8 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = DZ + 3 + lift, cx = it.x + W / 2;
    it.stand.setAttribute("d", seg(P(cx, 4, DZ), P(cx, 4, z0)) + seg(P(cx - 1.5, 4, DZ), P(cx - 1.5, 4, z0)));
    const [rs, is] = rings(it.x + 2, 2, it.x + W - 2, 5, 1.2, 0.6);
    put(it.body, prism(P, front, rs, is, z0, z0 + SH));
    const a = P(it.x + 4, 5, z0 + 2), b = P(it.x + W - 4, 5, z0 + 2), c = P(it.x + W - 4, 5, z0 + SH - 2), d = P(it.x + 4, 5, z0 + SH - 2);
    it.glass.setAttribute("d", "M" + [a, b, c, d].map((p) => p.join(",")).join("L") + "Z");
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + W / 2, D / 2, DZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.8 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "desk " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "missioncontrol",
  means: "A row of mission consoles: the screen on the desk under the pointer rises on its stand, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[133, 155], [183, 174], [262, 258], null],
  mount,
});

treadmill.code:
/**
 * Treadmill: a long deck between two uprights that carry the console. The
 * pointer walks along the deck: the nearer it stands to the console, the
 * higher the deck's front end rises, tilting the belt into an incline. At
 * rest the deck sits at a slight incline and the console is bright.
 *
 * The pattern: one continuous value read from the ground (terrain).
 */
const {
  Cam, clamp, fit, facing, hull, open, poly, prism, proj, rings, run, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 130, W = 44, MAX = 22, REST = 5, PH = 62;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 1.55);
  fit(C, [[-8, -10, 0], [L, W + 10, 0], [L, -10, 0], [-8, W + 10, 0], [-8, -10, PH + 8], [-8, W + 10, PH + 8], [0, W / 2, MAX + 10]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // far upright, then the deck, then the near upright, then the console
  const post = (y, parent) => { const [r, i] = rings(-2, y - 3, 4, y + 3, 3, 1); put(solid(parent), prism(P, front, r, i, 0, PH)); };
  post(-6, g);
  const deck = solid(g);
  const belt = mk("path", { class: "nf lo" }, g);
  post(W + 6, g);
  const con = solid(g);
  const [cr, ci] = rings(-8, -10, 8, W + 10, 4, 1.5);
  put(con, prism(P, front, cr, ci, PH, PH + 7));
  const [kr, ki] = rings(-6, W / 2 - 10, 2, W / 2 + 10, 3, 1);
  put(solid(g), prism(P, front, kr, ki, PH + 7, PH + 10));

  const [dr, di] = rings(0, -2, L, W + 2, 6, 2);
  const zAt = (u, z, h) => z + h * (1 - u / L);
  const at = (ring, z, h) => ring.map((q) => P(q.u, q.v, zAt(q.u, z, h)));
  let last = NaN;
  function draw(h) {
    h = Math.round(h * 20) / 20;
    if (h === last) return;
    last = h;
    deck.sil.setAttribute("d", poly(hull(at(dr, 0, h).concat(at(dr, 9, h)))));
    deck.cr.setAttribute("d", open(at(run(di, front), 9, h)));
    let d = "";
    for (let x = 14; x < L - 6; x += 14) d += seg(P(x, 4, zAt(x, 9, h)), P(x, W - 4, zAt(x, 9, h)));
    belt.setAttribute("d", d);
  }

  const sp = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  let on = null;
  function aim(p) {
    let h = REST, hit = false;
    if (p) {
      const [wx, wy] = unproj(C, p[0], p[1], 0);
      hit = wx > -10 && wx < L + 10 && wy > -16 && wy < W + 16;
      if (hit) h = clamp((L - wx) / L, 0, 1) * max;
    }
    sp.t = h;
    if (hit !== on) { on = hit; deck.sil.classList.toggle("hi", hit); con.sil.classList.toggle("hi", !hit); }
    read.textContent = hit ? Math.round(Math.atan2(h, L) * 180 / Math.PI) + "°" : "rest";
    B.wake();
  }
  draw(REST);
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; }, destroy: bag.dispose };
}

hairline({
  name: "treadmill",
  means: "A treadmill deck between two uprights: the closer the pointer walks to the console, the steeper the belt inclines.",
  rules: [1, 3, 5, 8],
  range: [8, 22, 30],
  tour: [[144, 185], [199, 212], [265, 245], null],
  mount,
});

eggcartons.code:
/**
 * Egg cartons: three cartons in a row, each a tray of six eggs under a lid
 * hinged at its back edge. The pointer picks a carton by where it stands:
 * its lid swings open to show the eggs, and the lids beside it crack open a
 * little, staggered from it. At rest one lid stands half open, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 46, W = 34, D = 24, BZ = 10, TH = 7, OPEN = 105, FAV = 1;
const X1 = (N - 1) * STEP + W;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const LID = rrect(0, 0, W, D, 4, 4), LIN = rrect(2, 2, W - 2, D - 2, 2.5, 4);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-2, -10, 0], [X1 + 2, D + 2, 0], [X1 + 2, -10, 0], [-2, D + 2, 0], [0, 0, BZ + D + 2], [X1, 0, BZ + D + 2]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * STEP, grp = mk("g", {}, g);
    const [br, bi] = rings(x0, 0, x0 + W, D, 4, 1.6);
    put(solid(grp), prism(P, front, br, bi, 0, BZ));
    const lidBack = mk("g", {}, grp), eggs = mk("g", {}, grp), lidFront = mk("g", {}, grp);
    for (let j = 0; j < 2; j++) for (let i = 0; i < 3; i++) {
      const ex = x0 + 6 + i * 11, ey = 6 + j * 12, pts = [];
      for (const [r, z] of [[4.6, 0], [4.3, 2], [3.4, 4.2], [1.6, 5.8]]) pts.push(...ringAt(P, disc(ex, ey, r), BZ - 1 + z));
      mk("path", { d: poly(hull(pts)), class: "nf" }, eggs);
    }
    const lid = mk("g", {}, lidFront);
    const sil = mk("path", { class: "sil" }, lid), cr = mk("path", { class: "nf lo" }, lid);
    items.push({ k, x0, lid, lidBack, lidFront, sil, cr, a: tween(k === FAV ? 55 : 0), last: NaN, back: false });
  }

  function lidPts(it, ring, w, a) {
    const c = Math.cos(a * Math.PI / 180), s = Math.sin(a * Math.PI / 180);
    return ring.map((q) => P(it.x0 + q.u, q.v * c - w * s, BZ + q.v * s + w * c));
  }
  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    it.sil.setAttribute("d", poly(hull(lidPts(it, LID, 0, a).concat(lidPts(it, LID, TH, a)))));
    it.cr.setAttribute("d", poly(lidPts(it, LIN, TH, a)));
    const back = a > 80;
    if (back !== it.back) { it.back = back; (back ? it.lidBack : it.lidFront).appendChild(it.lid); }
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x0 + W / 2, D / 2, BZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), ang = a < 0 ? (k === FAV ? 55 : 0) : dd === 0 ? OPEN : dd === 1 ? 14 : 0;
      tset(it.a, ang, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "box " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "eggcartons",
  means: "Three egg cartons in a row: the lid under the pointer swings open to show six eggs, and its neighbours crack open a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[119, 149], [193, 186], [268, 224], null],
  mount,
});

pendantlamps.code:
/**
 * Pendant lamps: four shades hung on cords from a ceiling rail, at uneven
 * heights. The pointer picks a lamp by where it stands: its cord pays out and
 * the shade lowers, and the lamps beside it drop a little, staggered from it.
 * At rest the lowest shade is bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 38, TOP = 118, DROP = [34, 50, 28, 42], LOW = 20, FAV = 1, SR = 15, SH = 14;
const X1 = (N - 1) * STEP;
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.7);
  fit(C, [[-SR, -SR, TOP + 6], [X1 + SR, SR, TOP + 6], [-SR, SR, TOP - 74 - SH], [X1 + SR, SR, TOP - 74 - SH], [X1 + SR, -SR, TOP + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [rr, ri] = rings(-10, -4, X1 + 10, 4, 4, 1.2);
  put(solid(g), prism(P, front, rr, ri, TOP, TOP + 5));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, y = 0, grp = mk("g", {}, g);
    const cord = mk("path", { class: "nf lo" }, grp), shade = mk("path", { class: "sil" }, grp);
    const band = mk("path", { class: "nf lo" }, grp), cap = mk("path", { class: "nf" }, grp);
    items.push({ k, x, y, grp, cord, shade, band, cap, d: tween(DROP[k]), last: NaN });
  }

  function draw(it, d) {
    if (d === it.last) return;
    it.last = d;
    const z1 = TOP - d, z0 = z1 - SH;
    it.cord.setAttribute("d", seg(P(it.x, it.y, TOP), P(it.x, it.y, z1 + 3)));
    const pts = ringAt(P, disc(it.x, it.y, 3.5, 20), z1).concat(ringAt(P, disc(it.x, it.y, SR), z0));
    it.shade.setAttribute("d", poly(hull(pts)));
    it.band.setAttribute("d", open(ringAt(P, run(disc(it.x, it.y, SR * 0.62), front), z0 + SH * 0.38)));
    it.cap.setAttribute("d", poly(hull(ringAt(P, disc(it.x, it.y, 2.4, 16), z1).concat(ringAt(P, disc(it.x, it.y, 2.4, 16), z1 + 3)))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.d, now)); if (!tdone(it.d, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, TOP - DROP[it.k] - SH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && sy > P(0, 0, TOP + 8)[1] - 40 && sy < mids[best][1] + 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), d = DROP[k] + (a < 0 ? 0 : dd === 0 ? LOW : dd === 1 ? 5 : 0);
      tset(it.d, d, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.shade.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "lamp " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "pendantlamps",
  means: "Four shades hung from a ceiling rail: the lamp under the pointer lowers on its cord, and its neighbours drop a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[131, 132], [223, 169], [269, 212], null],
  mount,
});

videowall.code:
/**
 * Video wall: nine thin screens stacked three by three on a plinth. The
 * pointer picks a screen by its rest face; that screen slides out of the
 * wall toward the viewer, and the screens around it ease out a little,
 * staggered from it. At rest one screen stands proud, bright. The slider is
 * the stagger.
 *
 * The pattern: grid on a face plane, pick by rest centre.
 */
const {
  Cam, fit, facing, fillet, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const COLS = 3, ROWS = 3, W = 34, H = 22, D = 4, G = 2, ZB = 5, SL = 14, FAV = 4;
const X1 = COLS * W + (COLS - 1) * G;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  const ZT = ZB + ROWS * H + (ROWS - 1) * G;
  fit(C, [[-6, -8, 0], [X1 + 6, D + SL + 4, 0], [X1 + 6, -8, 0], [-6, D + SL + 4, 0], [0, 0, ZT], [X1, D + SL, ZT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-6, -8, X1 + 6, D + 12, 4, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, ZB));

  const items = [];
  for (let r = 0; r < ROWS; r++) {
    const row = mk("g", {}, g);
    for (let c = 0; c < COLS; c++) {
      const k = r * COLS + c, x0 = c * (W + G), z0 = ZB + r * (H + G);
      const grp = mk("g", {}, row), s = solid(grp);
      s.sil.classList.add("sil");
      const face = mk("path", { class: "nf lo" }, grp);
      items.push({ k, r, c, x0, z0, row, grp, s, face, y: tween(k === FAV ? SL * 0.6 : 0), last: NaN });
    }
  }

  function draw(it, y) {
    if (y === it.last) return;
    it.last = y;
    const [ring, inner] = rings(it.x0, y, it.x0 + W, y + D, 1.6, 0.8);
    put(it.s, prism(P, front, ring, inner, it.z0, it.z0 + H));
    const fy = y + D, q = [[it.x0 + 2.5, it.z0 + 2.5], [it.x0 + W - 2.5, it.z0 + 2.5], [it.x0 + W - 2.5, it.z0 + H - 2.5], [it.x0 + 2.5, it.z0 + H - 2.5]];
    it.face.setAttribute("d", poly(fillet(q.map(([x, z]) => P(x, fy, z)), [2, 2, 2, 2])));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.y, now)); if (!tdone(it.y, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x0 + W / 2, D, it.z0 + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, (m[1] - sy) * 1.2); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const on = a < 0 ? FAV : a, A = items[on];
    items.forEach((it) => {
      const dd = Math.max(Math.abs(it.r - A.r), Math.abs(it.c - A.c));
      const y = a < 0 ? (it.k === FAV ? SL * 0.6 : 0) : dd === 0 ? SL : dd === 1 ? 3 : 0;
      const F = from >= 0 ? items[from] : A;
      tset(it.y, y, now, Math.max(Math.abs(it.r - F.r), Math.abs(it.c - F.c)) * stag);
      it.s.sil.classList.toggle("hi", it.k === on);
    });
    A.row.appendChild(A.grp);
    read.textContent = a < 0 ? "rest" : "scr " + (A.c + 1) + "·" + (A.r + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "videowall",
  means: "Nine screens stacked on a plinth: the screen under the pointer slides out of the wall, and the ones around it ease forward.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[159, 170], [204, 156], [248, 142], null],
  mount,
});

slotmachine.code:
/**
 * Slot machine: a cabinet with three reel windows on its face and a lever on
 * its side. The pointer on the cabinet pulls the lever down, and the reels
 * roll their marks, staggered out from the lever. At rest the lever stands
 * back, its knob bright. The slider is the stagger.
 *
 * The pattern: one press that ripples along a row.
 */
const {
  Cam, circ, fit, facing, hull, lerp, poly, prism, proj, rings, ringAt, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 48, D = 34, H = 84, WZ0 = 44, WZ1 = 62, LY = D / 2;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, 0], [W, D, 0], [W + 14, D, 0], [0, D, H], [W + 6, LY, H + 4], [0, 0, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, D, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, H));
  // the tray at the foot of the face
  mk("path", { d: poly([P(8, D, 10), P(W - 8, D, 10), P(W - 8, D, 18), P(8, D, 18)]), class: "nf lo" }, g);
  const reels = [];
  for (let i = 0; i < 3; i++) {
    const x0 = 6 + i * 13, x1 = x0 + 10;
    mk("path", { d: poly([P(x0, D, WZ0), P(x1, D, WZ0), P(x1, D, WZ1), P(x0, D, WZ1)]), class: "nf" }, g);
    const marks = mk("path", { class: "nf lo" }, g);
    reels.push({ x0, x1, marks, s: tween(i * 0.3), last: NaN });
  }
  // the lever: a pivot on the side, an arm and a knob
  put(solid(g), prism(P, front, disc(W + 2, LY, 4), disc(W + 2, LY, 3), 40, 48));
  const arm = mk("path", { class: "nf" }, g), knob = mk("path", { class: "sil hi" }, g);
  const lev = tween(0), last = { a: NaN };

  function drawReel(r, s) {
    if (s === r.last) return;
    r.last = s;
    let d = "";
    for (let k = 0; k < 3; k++) {
      const f = ((k / 3 + s) % 1 + 1) % 1, z = lerp(WZ0 + 2, WZ1 - 2, f);
      d += seg(P(r.x0 + 2, D, z), P(r.x1 - 2, D, z));
    }
    r.marks.setAttribute("d", d);
  }
  function drawLever(a) {
    if (a === last.a) return;
    last.a = a;
    const t = (-20 + a * 95) * Math.PI / 180, L = 34;
    const tip = [W + 9, LY + Math.sin(t) * L, 44 + Math.cos(t) * L];
    arm.setAttribute("d", poly(hull(ringAt(P, disc(W + 8, LY, 1.4, 10), 44).concat(ringAt(P, disc(tip[0], tip[1], 1.4, 10), tip[2])))));
    knob.setAttribute("d", poly(hull(ringAt(P, disc(tip[0], tip[1], 4.5, 20), tip[2] - 3).concat(ringAt(P, disc(tip[0], tip[1], 4.5, 20), tip[2] + 3)))));
  }
  const B = register(stage, (_dt, now) => {
    let moving = !tdone(lev, now);
    drawLever(tval(lev, now));
    for (const r of reels) { drawReel(r, tval(r.s, now)); if (!tdone(r.s, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const box = hull([P(0, 0, 0), P(W, 0, 0), P(W, D, 0), P(0, D, 0), P(0, 0, H), P(W, 0, H), P(W, D, H), P(0, D, H), P(W + 9, LY, 80)]);
  const xs = box.map((p) => p[0]), ys = box.map((p) => p[1]);
  const inside = ([sx, sy]) => sx > Math.min(...xs) && sx < Math.max(...xs) && sy > Math.min(...ys) && sy < Math.max(...ys);

  let on = null, spins = 0;
  function setOn(v) {
    if (v === on) return;
    on = v;
    const now = performance.now();
    tset(lev, v ? 1 : 0, now, 0);
    if (v) { spins++; reels.forEach((r, i) => tset(r.s, i * 0.3 + spins * (1 + i / 3), now, (2 - i) * stag)); }
    read.textContent = v ? "pull " + spins : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(inside(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "slotmachine",
  means: "A slot machine: the pointer on the cabinet pulls the lever down and the three reels roll their marks, one after another.",
  rules: [2, 5, 6, 8],
  range: [0, 60, 120],
  tour: [[181, 158], [198, 60], [243, 200], null],
  mount,
});

beadmaze.code:
/**
 * Bead maze: a wooden base with three wire arches, three beads on each.
 * The pointer picks a wire by where it stands on the base; that wire's
 * beads slide along it to follow the pointer, and the wire goes bright.
 * At rest the beads sit bunched unevenly, the middle wire bright.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, unproj, clamp, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 110, W = 48, BZ = 7, BR = 6.4, GAP = 13.5, X0 = 10, X1 = L - 10;
const WIRES = [{ y: 12, h: 30 }, { y: 24, h: 44 }, { y: 36, h: 22 }];
const REST = [[22, 35, 80], [30, 66, 79], [20, 34, 48]], FAV = 1;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const wz = (w, x) => BZ + 3 + w.h * Math.sin(Math.PI * clamp((x - X0) / (X1 - X0), 0, 1));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let pull = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[0, 0, 0], [L, W, 0], [L, 0, 0], [0, W, 0], [L / 2, 24, BZ + 52]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, L, W, 7, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));

  const wires = WIRES.map((w, j) => {
    const grp = mk("g", {}, g), pts = [];
    for (let i = 0; i <= 40; i++) { const x = X0 + ((X1 - X0) * i) / 40; pts.push(P(x, w.y, wz(w, x))); }
    put(solid(grp), prism(P, front, disc(X0, w.y, 2.2, 12), disc(X0, w.y, 1.4, 12), BZ, BZ + 3));
    put(solid(grp), prism(P, front, disc(X1, w.y, 2.2, 12), disc(X1, w.y, 1.4, 12), BZ, BZ + 3));
    const wire = mk("path", { d: open(pts), class: "nf sil" }, grp);
    const beads = REST[j].map((x) => ({ s: spring(x), el: mk("path", { class: "sil" }, grp), last: NaN }));
    return { ...w, j, wire, beads };
  });

  function drawBead(w, b) {
    const x = b.s.x;
    if (x === b.last) return;
    b.last = x;
    const z = wz(w, x), pts = [];
    for (let i = -3; i <= 3; i++) { const t = (i / 3) * (Math.PI / 2); pts.push(...ringAt(P, disc(x, w.y, BR * Math.cos(t), 16), z + BR * Math.sin(t))); }
    b.el.setAttribute("d", poly(hull(pts)));
  }

  const B = register(stage, (dt) => {
    let moving = false;
    for (const w of wires) for (const b of w.beads) { if (stepS(b.s, dt)) moving = true; drawBead(w, b); }
    return moving;
  });
  bag.add(B.unregister);

  let act = -2, lastX = NaN;
  function aim(a, px) {
    wires.forEach((w, j) => {
      w.wire.classList.toggle("hi", j === (a < 0 ? FAV : a));
      const base = a === j ? clamp(px, X0 + BR + GAP, X1 - BR - GAP) : null;
      w.beads.forEach((b, i) => {
        if (base == null) b.s.t = REST[j][i];
        else b.s.t = REST[j][i] + (base + (i - 1) * GAP - REST[j][i]) * pull;
      });
    });
    read.textContent = a < 0 ? "rest" : "wire " + (a + 1) + "·" + Math.round(((px - X0) / (X1 - X0)) * 9);
    B.wake();
  }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    let a = -1;
    if (x > -4 && x < L + 4 && y > -4 && y < W + 4) { let bd = Infinity; WIRES.forEach((w, j) => { const d = Math.abs(w.y - y); if (d < bd) { bd = d; a = j; } }); }
    const px = clamp(x, X0, X1);
    if (a === act && (a < 0 || Math.abs(px - lastX) < 0.3)) return;
    act = a; lastX = px;
    aim(a, px);
  }
  aim(-1, 0);
  bag.add(pointer(stage, { move, leave: () => { act = -1; aim(-1, 0); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { pull = v; if (act >= 0) aim(act, lastX); }, destroy: bag.dispose };
}

hairline({
  name: "beadmaze",
  means: "A bead maze with three wire arches: the wire under the pointer goes bright and its beads slide along it to follow.",
  rules: [1, 3, 5, 8],
  range: [0.2, 0.8, 1],
  tour: [[170, 180], [243, 236], [225, 165], null],
  mount,
});

parrotperch.code:
/**
 * Parrot perch: a T-stand on a round tray, a crossbar with a seed cup at
 * each end and a parrot sitting on it. The pointer's side of the stand sets
 * the bar's tilt: it swings on its pivot toward the pointer, cups and bird
 * riding with it. At rest it leans a little, the bird bright. The slider is
 * the swing's reach.
 *
 * The pattern: one part answering where the pointer is (lean).
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rad, rings, ringAt, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const H = 62, L = 34, BR = 2.2, REST = 7;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-40, -40, 0], [40, 40, 0], [-L - 6, 0, H + 26], [L + 6, 0, H + 26], [0, 0, H + 34]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(0, 0, 30, 48), disc(0, 0, 27.5, 48), 0, 4));
  put(solid(g), prism(P, front, disc(0, 0, 6, 24), disc(0, 0, 4.5, 24), 4, 9));
  put(solid(g), prism(P, front, disc(0, 0, 1.8, 16), disc(0, 0, 1, 16), 9, H));
  const cupA = solid(g), bar = mk("path", { class: "sil" }, g), bird = mk("g", {}, g), cupB = solid(g);
  const body = mk("path", { class: "sil" }, bird), wing = mk("path", { class: "nf lo" }, bird);
  const head = mk("path", { class: "sil" }, bird), beak = mk("path", {}, bird), eye = mk("circle", { r: 1.1, class: "dot" }, bird);

  const tilt = spring(REST);
  let last = NaN;
  // a point along the tilted bar: s along it, plus local up offset u
  const on = (a, s, u, y = 0) => [s * Math.cos(a) - u * Math.sin(a), y, H + s * Math.sin(a) + u * Math.cos(a)];
  const ball = (c, rx, ry, rz) => {
    const out = [];
    for (let i = 0; i <= 6; i++) {
      const t = -Math.PI / 2 + (i / 6) * Math.PI;
      for (let j = 0; j < 14; j++) { const f = (j / 14) * 2 * Math.PI; out.push(P(c[0] + rx * Math.cos(t) * Math.cos(f), c[1] + ry * Math.cos(t) * Math.sin(f), c[2] + rz * Math.sin(t))); }
    }
    return out;
  };
  function cup(s, a, sx) {
    const [x, y, z] = on(a, sx, 0);
    put(s, prism(P, front, disc(x, y, 5, 24), disc(x, y, 3.8, 24), z - 4, z + 1.5));
  }
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), pts = [];
    for (const s of [-L, L]) for (let j = 0; j < 12; j++) { const f = (j / 12) * 2 * Math.PI; pts.push(P(...on(a, s, BR * Math.sin(f), BR * Math.cos(f)))); }
    bar.setAttribute("d", poly(hull(pts)));
    cup(cupA, a, -L + 4); cup(cupB, a, L - 4);
    const bc = on(a, 6, 10), hc = on(a, 10, 21);
    body.setAttribute("d", poly(hull(ball(bc, 6, 5, 9).concat(ball(on(a, 1, 2), 3, 3, 3)))));
    wing.setAttribute("d", poly(hull(ball([bc[0] - 1, bc[1] + 4, bc[2]], 4, 1, 6))));
    head.setAttribute("d", poly(hull(ball(hc, 4.6, 4.4, 4.6))));
    const b0 = P(hc[0] + 4, hc[1], hc[2] + 1.5), b1 = P(hc[0] + 8.5, hc[1], hc[2] - 2), b2 = P(hc[0] + 4, hc[1], hc[2] - 3);
    beak.setAttribute("d", poly([b0, b1, b2]));
    const e = P(hc[0] + 1.8, hc[1] + 3.4, hc[2] + 1.4);
    eye.setAttribute("cx", e[0]); eye.setAttribute("cy", e[1]);
  }

  const B = register(stage, (dt) => { const m = stepS(tilt, dt); draw(tilt.x); return m; });
  bag.add(B.unregister);

  function setLit(on2) {
    body.classList.toggle("hi", !on2); head.classList.toggle("hi", !on2);
    bar.classList.toggle("hi", on2);
  }
  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, 0);
    const d = clamp((wx - wy) / 70, -1, 1);
    if (Math.abs(wx) > 90 || Math.abs(wy) > 90) return leave();
    tilt.t = d * reach;
    setLit(true);
    read.textContent = (tilt.t >= 0 ? "+" : "") + Math.round(tilt.t) + "°";
    B.wake();
  }
  function leave() { tilt.t = REST; setLit(false); read.textContent = "rest"; B.wake(); }
  draw(REST); leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "parrotperch",
  means: "A T-stand perch with a parrot on its bar: the bar swings toward the side the pointer is on, cups and bird riding with it.",
  rules: [3, 4, 5, 8],
  range: [6, 18, 26],
  tour: [[320, 260], [90, 250], [240, 270], null],
  mount,
});

helipad.code:
/**
 * Helipad: a square pad on a low deck, a touchdown ring painted on it and a
 * helicopter parked in the middle, skids, boom and a two-blade rotor. The
 * nearer the pointer comes to the pad's centre, the higher the helicopter
 * lifts off, the rotor turning a little as it climbs. At rest it sits on the
 * pad, the ring bright. The slider is the ceiling.
 *
 * The pattern: one part answering where the pointer is (lift).
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rings, ringAt, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 46, DZ = 6, SK = 3;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let ceil = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-W, -W, 0], [W, W, 0], [W, -W, 0], [-W, W, 0], [0, 0, DZ + 50 + 22]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-W, -W, W, W, 8, 2);
  put(solid(g), prism(P, front, pr, pi, 0, DZ));
  const ring = mk("path", { d: poly(ringAt(P, disc(0, 0, 30, 48), DZ)), class: "nf" }, g);
  mk("path", { d: poly(ringAt(P, disc(0, 0, 27, 48), DZ)), class: "nf lo" }, g);
  for (const [x, y] of [[-W + 6, -W + 6], [W - 6, -W + 6], [-W + 6, W - 6], [W - 6, W - 6]]) {
    const d = mk("circle", { r: 1.6, class: "dot off" }, g), q = P(x, y, DZ);
    d.setAttribute("cx", q[0]); d.setAttribute("cy", q[1]);
  }
  const shadow = mk("path", { class: "nf dash" }, g);
  const heli = mk("g", {}, g);
  const skids = mk("path", { class: "nf" }, heli), boom = mk("path", { class: "sil" }, heli);
  const body = mk("path", { class: "sil" }, heli), glass = mk("path", { class: "nf lo" }, heli);
  const mast = mk("path", { class: "nf" }, heli), rotor = mk("path", { class: "nf" }, heli), hub = mk("circle", { r: 1.5, class: "dot m" }, heli);

  const lift = spring(0);
  let last = NaN;
  const ball = (c, rx, ry, rz) => {
    const out = [];
    for (let i = 0; i <= 6; i++) {
      const t = -Math.PI / 2 + (i / 6) * Math.PI;
      for (let j = 0; j < 16; j++) { const f = (j / 16) * 2 * Math.PI; out.push(P(c[0] + rx * Math.cos(t) * Math.cos(f), c[1] + ry * Math.cos(t) * Math.sin(f), c[2] + rz * Math.sin(t))); }
    }
    return out;
  };
  function draw(h) {
    if (h === last) return;
    last = h;
    const z = DZ + h, bz = z + SK + 8;
    let d = "";
    for (const y of [-7, 7]) {
      d += seg(P(-14, y, z), P(14, y, z)) + seg(P(14, y, z), P(16, y, z + 1.5));
      d += seg(P(-8, y, z), P(-6, y * 0.6, bz - 4)) + seg(P(8, y, z), P(6, y * 0.6, bz - 4));
    }
    skids.setAttribute("d", d);
    boom.setAttribute("d", poly(hull(ball([-4, 0, bz + 1], 3, 2.4, 2.4).concat(ball([-34, 0, bz + 3], 1.6, 1.4, 1.6), ball([-36, 0, bz + 8], 1.5, 0.8, 5)))));
    body.setAttribute("d", poly(hull(ball([2, 0, bz], 13, 8, 8))));
    glass.setAttribute("d", open([P(8, -7, bz + 3), P(13, 0, bz + 2.5), P(8, 7, bz + 3)]));
    mast.setAttribute("d", poly(hull(ringAt(P, disc(1, 0, 1.6, 12), bz + 7).concat(ringAt(P, disc(1, 0, 1.6, 12), bz + 11)))));
    const a = 0.6 + h * 0.05, R = 34, top = bz + 11;
    rotor.setAttribute("d", seg(P(1 + R * Math.cos(a), R * Math.sin(a), top), P(1 - R * Math.cos(a), -R * Math.sin(a), top)) + seg(P(1 - R * Math.sin(a), R * Math.cos(a), top), P(1 + R * Math.sin(a), -R * Math.cos(a), top)));
    const q = P(1, 0, top); hub.setAttribute("cx", q[0]); hub.setAttribute("cy", q[1]);
    shadow.setAttribute("d", h > 1 ? poly(ringAt(P, disc(0, 0, 10 + h * 0.15, 32), DZ)) : "");
  }

  const B = register(stage, (dt) => { const m = stepS(lift, dt); draw(lift.x); return m; });
  bag.add(B.unregister);

  function lit(on) { ring.classList.toggle("hi", !on); body.classList.toggle("hi", on); }
  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, DZ), r = Math.hypot(wx, wy);
    if (r > W * 1.6) return leave();
    lift.t = ceil * clamp(1 - r / (W * 1.4), 0.15, 1);
    lit(true);
    read.textContent = Math.round(lift.t) + " m";
    B.wake();
  }
  function leave() { lift.t = 0; lit(false); read.textContent = "rest"; B.wake(); }
  draw(0); leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { ceil = v; }, destroy: bag.dispose };
}

hairline({
  name: "helipad",
  means: "A helicopter parked on a square pad: the nearer the pointer to the pad's centre, the higher it lifts off, rotor turning.",
  rules: [3, 4, 5, 8],
  range: [20, 40, 50],
  tour: [[200, 206], [102, 157], [200, 271], null],
  mount,
});

gondolalift.code:
/**
 * Gondola lift: two pylons carrying a sloping cable, three cabins hanging
 * from it on their grips. The pointer picks a cabin by where it stands: that
 * cabin swings out on its hanger and its neighbours sway a little after it,
 * staggered. At rest the middle cabin hangs with a slight swing, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, seg, tdone, tset, tval, tween, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SPAN = 150, Z0 = 70, Z1 = 92, HANG = 16, N = 3, FAV = 1, SW = 22;
const cz = (x) => Z0 + ((x + 10) / (SPAN + 20)) * (Z1 - Z0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[-20, -14, 0], [SPAN + 20, 14, 0], [-10, 0, Z0 + 8], [SPAN + 10, 0, Z1 + 8], [SPAN / 2, 30, 40]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const pylon = (x, z) => {
    const [r, i] = rings(x - 6, -6, x + 6, 6, 3, 1.2);
    put(solid(g), prism(P, front, r, i, 0, 3));
    const [r2, i2] = rings(x - 2, -2, x + 2, 2, 1.5, 0.6);
    put(solid(g), prism(P, front, r2, i2, 3, z));
    const [r3, i3] = rings(x - 2, -9, x + 2, 9, 1.5, 0.6);
    put(solid(g), prism(P, front, r3, i3, z, z + 3));
  };
  pylon(-10, Z0); pylon(SPAN + 10, Z1);
  mk("path", { d: seg(P(-10, 0, cz(-10) + 3), P(SPAN + 10, 0, cz(SPAN + 10) + 3)), class: "nf" }, g);

  const cabs = [];
  for (let k = 0; k < N; k++) {
    const x = 35 + k * 45, grp = mk("g", {}, g);
    const hang = mk("path", { class: "nf" }, grp), box = mk("path", { class: "sil" }, grp), win = mk("path", { class: "nf lo" }, grp);
    cabs.push({ k, x, hang, box, win, a: tween(k === FAV ? 8 : 0), last: NaN });
  }
  function draw(c, deg) {
    if (deg === c.last) return;
    c.last = deg;
    const a = rad(deg), top = cz(c.x) + 3;
    // swing in the y–z plane about the grip on the cable
    const at = (dx, dy, dz) => { const y = dy * Math.cos(a) - dz * Math.sin(a), z = dy * Math.sin(a) + dz * Math.cos(a); return P(c.x + dx, y, top + z); };
    c.hang.setAttribute("d", seg(at(0, 0, 0), at(0, 0, -HANG)) + seg(at(-4, 0, -HANG), at(4, 0, -HANG)));
    const pts = [];
    for (const dx of [-9, 9]) for (const dy of [-7, 7]) for (const dz of [-HANG - 1, -HANG - 24]) {
      for (let j = 0; j < 4; j++) { const f = (j / 4) * 2 * Math.PI; pts.push(at(dx + 1.5 * Math.cos(f), dy + 1.5 * Math.sin(f), dz)); }
    }
    c.box.setAttribute("d", poly(hull(pts)));
    c.win.setAttribute("d", poly([at(-7, 7.2, -HANG - 5), at(7, 7.2, -HANG - 5), at(7, 7.2, -HANG - 13), at(-7, 7.2, -HANG - 13)]));
  }
  const B = register(stage, (_dt, now) => {
    let m = false;
    for (const c of cabs) { draw(c, tval(c.a, now)); if (!tdone(c.a, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  const mids = cabs.map((c) => P(c.x, 0, cz(c.x) - HANG - 10));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    cabs.forEach((c, k) => {
      const d = Math.abs(k - a), t = a < 0 ? (k === FAV ? 8 : 0) : d === 0 ? SW : d === 1 ? 7 : 2;
      tset(c.a, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      c.box.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "cab " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "gondolalift",
  means: "Three cabins hanging from a sloping cable between two pylons: the cabin under the pointer swings out, its neighbours sway after it.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[155, 121], [206, 136], [257, 145], null],
  mount,
});

tyrechanger.code:
/**
 * Tyre changer: a garage machine, a cabinet with a turntable on top, a tyre
 * lying flat on it, and a column whose arm holds the mount head over the
 * back bead. The pointer turns the tyre: its valve swings round to face the
 * pointer, the lugs and sidewall ribs turning with it, and the mount head
 * presses down onto the bead. At rest the valve sits at a quarter turn,
 * bright. The slider is how far the head presses.
 *
 * The pattern: one part turning to face the pointer (spin).
 */
const {
  Cam, circ, fit, facing, poly, prism, proj, rings, ringAt, seg, stepS, spring, tset, tval, tdone, tween, unproj,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const CX = 40, CY = 32, TR = 26, TZ0 = 33, TZ1 = 45, REST = 135;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const rad = (d) => (d * Math.PI) / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let press = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[0, 0, 0], [70, 58, 0], [70, 0, 0], [0, 58, 0], [4, 4, 70], [44, 6, 70]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1, parent = g) => put(solid(parent), prism(P, front, ...rings(x0, y0, x1, y1, r, b), z0, z1));

  box(0, 0, 70, 58, 6, 2, 0, 30);
  box(4, 3, 16, 15, 4, 1.5, 30, 68);
  put(solid(g), prism(P, front, disc(CX, CY, 22), disc(CX, CY, 20.5), 30, TZ0));
  const tyre = solid(g);
  put(tyre, prism(P, front, disc(CX, CY, TR, 48), disc(CX, CY, TR - 2, 48), TZ0, TZ1));
  mk("path", { d: poly(ringAt(P, disc(CX, CY, 16, 40), TZ1)), class: "nf" }, g);
  mk("path", { d: poly(ringAt(P, disc(CX, CY, 14.5, 40), TZ1 - 3)), class: "nf lo" }, g);
  const ribs = mk("path", { class: "nf lo" }, g);
  const hub = mk("path", { class: "nf" }, g);
  const nuts = [0, 1, 2, 3, 4].map(() => flatDot(g, C, 1.3, "dot off"));
  const valve = solid(g);
  const head = solid(g), bar = solid(g);
  box(4, 5, 46, 13, 3, 1.2, 66, 71);

  const rot = spring(REST), drop = tween(0);
  let lastA = NaN, lastD = NaN;
  function draw(a, d) {
    if (a !== lastA) {
      lastA = a;
      let s = "";
      for (let i = 0; i < 12; i++) {
        const t = rad(a + 15 + i * 30), c = Math.cos(t), n = Math.sin(t);
        s += seg(P(CX + 18.5 * c, CY + 18.5 * n, TZ1), P(CX + 23.5 * c, CY + 23.5 * n, TZ1));
      }
      ribs.setAttribute("d", s);
      hub.setAttribute("d", poly(ringAt(P, disc(CX, CY, 6.5, 24), TZ1 - 1)));
      nuts.forEach((el, i) => { const t = rad(a + i * 72); place(el, P(CX + 4 * Math.cos(t), CY + 4 * Math.sin(t), TZ1 - 1)); });
      const vx = CX + 17.2 * Math.cos(rad(a)), vy = CY + 17.2 * Math.sin(rad(a));
      put(valve, prism(P, front, disc(vx, vy, 1.4, 12), disc(vx, vy, 0.8, 12), TZ1 - 2, TZ1 + 3.5));
    }
    if (d !== lastD) {
      lastD = d;
      const z = TZ1 + 6 - d;
      put(head, prism(P, front, ...rings(35, 4, 45, 14, 3, 1.2), z, z + 5));
      put(bar, prism(P, front, ...rings(38, 7.5, 42, 11.5, 2, 0.8), z + 5, 66));
    }
  }

  const B = register(stage, (dt, now) => {
    const m = stepS(rot, dt);
    draw(rot.x, tval(drop, now));
    return m || !tdone(drop, now);
  });
  bag.add(B.unregister);

  let on = null;
  function aim(p) {
    const [x, y] = unproj(C, p[0], p[1], TZ1), dx = x - CX, dy = y - CY;
    const hitT = Math.hypot(dx, dy) < TR + 8;
    const now = performance.now();
    if (hitT) {
      const th = (Math.atan2(dy, dx) * 180) / Math.PI;
      rot.t = th + 360 * Math.round((rot.t - th) / 360);
      read.textContent = String(Math.round(((th % 360) + 360) % 360)).padStart(3, "0") + "°";
    } else {
      rot.t = REST + 360 * Math.round((rot.t - REST) / 360);
      read.textContent = "rest";
    }
    if (hitT !== on) {
      on = hitT;
      tset(drop, hitT ? press : 0, now, 0);
      tyre.sil.classList.toggle("hi", hitT);
    }
    B.wake();
  }
  valve.sil.classList.add("hi");
  read.textContent = "rest";
  draw(REST, 0);
  bag.add(pointer(stage, { move: aim, leave: () => aim([-999, -999]) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { press = v; if (on) { tset(drop, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "tyrechanger",
  means: "A tyre on a changer's turntable: it turns so its valve faces the pointer, and the mount head presses onto the bead.",
  rules: [1, 3, 5, 8],
  range: [0, 5, 6],
  tour: [[237, 164], [135, 144], [244, 130], null],
  mount,
});

oilcans.code:
/**
 * Oil cans: four round cans of motor oil of different heights on a garage
 * shelf, each with a seam near its top, a screw cap and a slanted spout. The
 * pointer picks a can by where it stands: it lifts off the shelf, and the
 * cans beside it rise a little, staggered from it. At rest one can is
 * raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const H = [30, 40, 26, 35], N = 4, STEP = 34, R = 12, SZ = 5, LIFT = 20, FAV = 1;
const X1 = (N - 1) * STEP + 2 * R;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-6, -6, 0], [X1 + 6, 2 * R + 6, 0], [X1 + 6, -6, 0], [-6, 2 * R + 6, 0], [R + STEP, R, SZ + 40 + LIFT + 6], [X1 - R + 10, R, SZ + 35 + 14]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-6, -6, X1 + 6, 2 * R + 6, 5, 2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = R + k * STEP, y = R, grp = mk("g", {}, g);
    const spout = mk("path", { class: "nf" }, grp), body = solid(grp), seam = mk("path", { class: "nf lo" }, grp), cap = solid(grp);
    items.push({ k, x, y, h: H[k], spout, body, seam, cap, z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = SZ + lift, top = z0 + it.h, { x, y } = it;
    it.spout.setAttribute("d", poly(hull(ringAt(P, disc(x + 5, y - 3, 2.2, 12), top).concat(ringAt(P, disc(x + 13, y - 3, 1.3, 12), top + 11)))));
    put(it.body, prism(P, front, disc(x, y, R), disc(x, y, R - 2), z0, top));
    it.seam.setAttribute("d", open(ringAt(P, run(disc(x, y, R), front), top - 4)));
    put(it.cap, prism(P, front, disc(x - 4, y + 3, 3.4, 20), disc(x - 4, y + 3, 2.4, 20), top, top + 3.5));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, SZ + it.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "can " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "oilcans",
  means: "Four oil cans of different heights on a shelf: the can under the pointer lifts off, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[128, 134], [224, 182], [272, 206], null],
  mount,
});

weldingbench.code:
/**
 * Welding bench: two steel plates butted on a bench, a gantry rail over the
 * seam, a carriage with its torch hanging from the rail. The pointer picks a
 * tack along the seam: the carriage slides there and the torch drops to it;
 * the tacks behind it read as laid. At rest the torch waits over tack 1.
 *
 * The pattern: one of many in a single row, a carriage that travels.
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, tdone, tset, tval, tween, clamp,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const N = 5, X0 = 22, STEP = 24, SY = 30, PZ = 11, BZ = 60, FAV = 0;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const tackX = (k) => X0 + k * STEP;

function mount({ stage, svg, read }, value) {
  let drop = value;
  const tear = disposer();
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[0, 0, 0], [150, 0, 0], [0, 60, 0], [150, 60, 0], [0, 26, BZ + 6], [150, 34, BZ + 6]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r = 2, b = 1.2, parent = g) => {
    const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(parent); put(s, prism(P, front, o, i, z0, z1)); return s;
  };
  box(0, 0, 150, 60, 0, 8, 4, 2);
  box(10, 12, 140, 29.4, 8, PZ, 1.5, 1);
  box(10, 30.6, 140, 48, 8, PZ, 1.5, 1);
  const tacks = [];
  for (let k = 0; k < N; k++) { const d = flatDot(g, C, 1.6, "dot off"); place(d, P(tackX(k), SY, PZ)); tacks.push(d); }
  box(1, 25, 8, 35, 8, BZ, 1.5, 1);
  const mov = mk("g", {}, g);
  box(142, 25, 149, 35, 8, BZ, 1.5, 1);
  box(0, 25, 150, 35, BZ, BZ + 6, 2, 1.2);
  const nozzle = solid(mov), body = solid(mov);

  const cx = tween(tackX(FAV)), tip = tween(PZ + 14);
  let lx = NaN, lt = NaN;
  function draw(x, t) {
    if (x === lx && t === lt) return;
    lx = x; lt = t;
    put(nozzle, prism(P, front, disc(x, SY, 2.4), disc(x, SY, 1.4), t, BZ - 10));
    const [o, i] = rings(x - 10, SY - 7, x + 10, SY + 7, 3, 1.4);
    put(body, prism(P, front, o, i, BZ - 16, BZ));
  }
  nozzle.sil.classList.add("hi");

  const B = register(stage, (_dt, now) => {
    draw(tval(cx, now), tval(tip, now));
    return !tdone(cx, now) || !tdone(tip, now);
  });
  tear.add(B.unregister);

  const mids = tacks.map((_, k) => P(tackX(k), SY, PZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    const at = a < 0 ? FAV : a;
    tset(cx, tackX(at), now, 0);
    tset(tip, a < 0 ? PZ + 14 : PZ + 14 - clamp(drop, 0, 13), now, 0);
    tacks.forEach((d, k) => d.setAttribute("class", k === at && a >= 0 ? "dot" : k < at ? "dot m" : "dot off"));
    read.textContent = a < 0 ? "rest" : "tack " + (a + 1);
    B.wake();
  }
  setActive(-1);
  tear.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  tear.add(() => svg.replaceChildren());
  return { set: (v) => { drop = v; if (act >= 0) { const a = act; act = -2; setActive(a); } }, destroy: tear.dispose };
}

hairline({
  name: "weldingbench",
  means: "A welding bench with a torch on a gantry: the carriage slides to the tack under the pointer and drops the torch to the seam.",
  rules: [1, 4, 5, 8],
  range: [0, 12, 13],
  tour: [[150, 150], [230, 190], [290, 220], null],
  mount,
});

tilestacks.code:
/**
 * Tile stacks: four stacks of square floor tiles standing in a row on the
 * ground, each a different height, every tile's seam drawn round the stack's
 * near faces. The pointer picks a stack by where it is along the row: that
 * stack's top tile lifts clear, the neighbours' top tiles lift a little after
 * it. At rest one tile sits just off the tallest stack, bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single row, picked by each stack's rest
 * centre on screen; stacks of different heights, so no one plane.
 */
const {
  Cam, clamp, facing, fit, open, prism, proj, rings, ringAt, run, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, W = 20, GAP = 7, T = 2.6, COUNT = [5, 9, 3, 7], LIFT = 15, FAV = 1;
const REST = [0, 3, 0, 0.6];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.9);
  const X1 = N * (W + GAP) - GAP, top = Math.max(...COUNT) * T + LIFT;
  fit(C, [[0, 0, 0], [X1, W, 0], [X1, 0, 0], [0, W, 0], [0, 0, top], [X1, 0, top], [W + GAP, 0, top]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const stacks = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * (W + GAP), [ring, inner] = rings(x0, 0, x0 + W, W, 2.2, 1);
    const n = COUNT[k], zb = (n - 1) * T;
    const body = solid(g);
    put(body, prism(P, front, ring, inner, 0, zb));
    const near = run(ring, front), seams = [];
    for (let j = 1; j < n - 1; j++) seams.push(open(ringAt(P, near, j * T)));
    mk("path", { class: "nf lo", d: seams.join("") }, body.g);
    const tile = solid(g);
    const mid = P(x0 + W / 2, W / 2, 0)[0];
    stacks.push({ k, ring, inner, zb, tile, mid, z: tween(REST[k]), last: NaN });
  }

  function draw(s, lift) {
    if (lift === s.last) return;
    s.last = lift;
    put(s.tile, prism(P, front, s.ring, s.inner, s.zb + lift, s.zb + lift + T));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    stacks.forEach((s) => { draw(s, tval(s.z, now)); if (!tdone(s.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: the stack whose rest centre is nearest the pointer's screen x, inside the yard
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 10);
    if (x < -14 || x > X1 + 10 || y < -24 || y > W + 14) return -1;
    let best = -1, bd = Infinity;
    stacks.forEach((s) => { const d = Math.abs(s.mid - sx); if (d < bd) { bd = d; best = s.k; } });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    stacks.forEach((s, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : clamp(5 - 2.5 * Math.abs(k - a), 0, 5);
      tset(s.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      s.tile.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "stack " + (a + 1) + "·" + COUNT[a];
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "tilestacks",
  means: "Four stacks of floor tiles: the top tile of the stack under the pointer lifts clear, its neighbours' lift a little after.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[117, 122], [234, 181], [291, 197], null],
  mount,
});

barn.code:
/**
 * Barn: a gabled barn seen from its door end. Two braced leaves hang on a
 * rail across the big doorway, and a hayloft door sits in the gable above.
 * The pointer picks a door by where it stands: over the doorway the leaves
 * slide apart along the rail; over the loft the loft door swings out on its
 * hinge. At rest the loft door stands ajar, bright. The slider is how far
 * the leaves travel.
 *
 * The pattern: a few parts of one object, each with its own gesture.
 */
const {
  Cam, fit, facing, hull, open, poly, proj, rings, ringAt, seg, tdone, tset, tval, tween, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 72, D = 56, H = 34, R = 22, OV = 3, DW = 13, DH = 27, MY = D / 2;
const LY0 = 21, LY1 = 35, LZ0 = 38, LZ1 = 49, LW = LY1 - LY0, AJAR = 28;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let travel = value;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[0, -OV, 0], [L, -OV, 0], [L, D + OV, 0], [0, D + OV, 0], [0, MY, H + R], [L, MY, H + R], [L + LW, LY1, LZ1]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the barn: walls, eaves and the ridge, as one hull
  const [fr] = rings(0, 0, L, D, 2.5, 1.5);
  const pts = ringAt(P, fr, 0).concat([[0, -OV], [L, -OV], [L, D + OV], [0, D + OV]].map(([x, y]) => P(x, y, H - 1)), [P(0, MY, H + R), P(L, MY, H + R)]);
  const body = solid(g);
  put(body, { sil: poly(hull(pts)), crease: open([P(0.8, D + OV - 0.8, H - 0.4), P(L - 0.8, D + OV - 0.8, H - 0.4)]) });
  // rake of the near slope, the wall under the eave, the ridge cap
  mk("path", { class: "nf lo", d: seg(P(L, D + OV, H - 1), P(L, MY, H + R)) + seg(P(0, MY, H + R - 1.5), P(L - 1, MY, H + R - 1.5)) + seg(P(L - 0.6, 1, H - 1.4), P(L - 0.6, D - 1, H - 1.4)) }, g);

  // doorway: the dark gap the leaves uncover, with the floor line inside
  const F = (y, z, dx = 0) => P(L + dx, y, z);
  mk("path", { class: "nf lo", d: poly([F(MY - DW, 0), F(MY + DW, 0), F(MY + DW, DH), F(MY - DW, DH)]) + seg(P(L - 10, MY - DW + 2, 0.2), P(L - 10, MY + DW - 2, 0.2)) }, g);
  // the rail the leaves hang from
  mk("path", { class: "nf", d: seg(F(MY - 2 * DW - 1, DH + 2, 0.4), F(MY + 2 * DW + 1, DH + 2, 0.4)) }, g);
  const leaves = [-1, 1].map((s) => ({ s, sil: mk("path", { class: "sil" }, g), br: mk("path", { class: "nf lo" }, g) }));

  // hayloft: its opening, the hoist beam over it, and the hinged door
  mk("path", { class: "nf lo", d: poly([F(LY0, LZ0), F(LY1, LZ0), F(LY1, LZ1), F(LY0, LZ1)]) }, g);
  const beam = solid(g);
  put(beam, { sil: poly(hull(ringAt(P, rings(L - 2, MY - 1.4, L + 9, MY + 1.4, 1, 0.5)[0], LZ1 + 3).concat(ringAt(P, rings(L - 2, MY - 1.4, L + 9, MY + 1.4, 1, 0.5)[0], LZ1 + 5.4)))), crease: "" });
  const loft = { sil: mk("path", { class: "sil" }, g), br: mk("path", { class: "nf lo" }, g) };

  const slide = tween(2), swing = tween(AJAR);
  let lastS = NaN, lastA = NaN;
  function draw(now) {
    const s = tval(slide, now), a = tval(swing, now);
    if (s !== lastS) {
      lastS = s;
      for (const lf of leaves) {
        const y0 = lf.s < 0 ? MY - DW - s : MY + s, y1 = y0 + DW;
        const q = [F(y0, 0.4, 0.8), F(y1, 0.4, 0.8), F(y1, DH, 0.8), F(y0, DH, 0.8)];
        lf.sil.setAttribute("d", poly(q));
        lf.br.setAttribute("d", seg(q[0], q[2]) + seg(F(y0, DH / 2, 0.8), F(y1, DH / 2, 0.8)));
      }
    }
    if (a !== lastA) {
      lastA = a;
      const t = rad(a), hx = L + 0.6, ex = hx + LW * Math.sin(t), ey = LY1 - LW * Math.cos(t);
      const q = [P(hx, LY1, LZ0), P(ex, ey, LZ0), P(ex, ey, LZ1), P(hx, LY1, LZ1)];
      loft.sil.setAttribute("d", poly(q));
      loft.br.setAttribute("d", seg(q[0], q[2]));
    }
  }
  const B = register(stage, (_dt, now) => { draw(now); return !(tdone(slide, now) && tdone(swing, now)); });
  bag.add(B.unregister);

  // hit by the rest pose: the doorway's middle and the loft's middle on the gable
  const mids = [P(L, MY, DH / 2), P(L, (LY0 + LY1) / 2, (LZ0 + LZ1) / 2)];
  function hit([sx, sy]) {
    let best = -1, bd = 34;
    mids.forEach((m, k) => { const d = Math.hypot(m[0] - sx, m[1] - sy); if (d < bd) { bd = d; best = k; } });
    return best;
  }

  let act = -2;
  function setActive(k) {
    if (k === act) return;
    act = k;
    const now = performance.now();
    tset(slide, k === 0 ? travel : 2, now, 0);
    tset(swing, k === 1 ? 105 : k < 0 ? AJAR : 0, now, k === 0 ? 60 : 0);
    for (const lf of leaves) lf.sil.classList.toggle("hi", k === 0);
    loft.sil.classList.toggle("hi", k !== 0);
    read.textContent = k === 0 ? "doors" : k === 1 ? "loft" : "rest";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { travel = v; if (act === 0) { act = -2; setActive(0); } }, destroy: bag.dispose };
}

hairline({
  name: "barn",
  means: "A gabled barn: over the doorway its braced leaves slide apart on their rail; over the gable the hayloft door swings out.",
  rules: [1, 4, 5, 6],
  range: [5, 13, 13],
  tour: [[207, 156], [260, 157], [260, 218], null],
  mount,
});

wallet.code:
/**
 * Wallet: a leather wallet standing on its edge with four cards in its
 * pockets. The pointer picks a card by where it stands: that card slides up
 * out of its pocket and its neighbours rise a little, staggered from it. At
 * rest the cards sit at uneven heights and one is bright. The slider is the stagger.
 */
const {
  Cam, fit, facing, prism, proj, rings, ringAt, open, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, W = 19, GAP = 22, X0 = 7, BH = 46, BY = 12, LIFT = 30, FAV = 2;
const REST = [9, 15, 12, 6];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.45);
  const XW = X0 * 2 + (N - 1) * GAP + W;
  fit(C, [[0, 0, 0], [XW, BY, 0], [XW, 0, BH + LIFT + 6], [0, BY, 0], [0, 0, BH + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const back = mk("g", {}, g);
  const [br, bi] = rings(0, 0, XW, BY / 2, 4, 1.2);
  put(solid(back), prism(P, front, br, bi, 0, BH));
  const cardsG = mk("g", {}, g);
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * GAP, grp = mk("g", {}, cardsG), s = solid(grp);
    const [cr, ci] = rings(x, BY / 2 - 1.2, x + W, BY / 2 + 0.8, 1, 0.5);
    items.push({ k, x, s, cr, ci, z: tween(REST[k]), last: NaN });
  }
  const frontG = mk("g", {}, g);
  const [fr, fi] = rings(0, BY / 2 + 1.2, XW, BY, 4, 1.2);
  put(solid(frontG), prism(P, front, fr, fi, 0, BH - 8));
  // the stitch and the fold of the front pocket
  mk("path", { class: "dash nf", d: open([P(3, BY, BH - 11), P(XW - 3, BY, BH - 11)]) }, frontG);
  mk("path", { class: "lo nf", d: seg(P(XW / 2, BY, 2), P(XW / 2, BY, BH - 13)) }, frontG);

  function draw(it, h) {
    if (h === it.last) return;
    it.last = h;
    put(it.s, prism(P, front, it.cr, it.ci, 8, BH + h));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + W / 2, BY / 2, BH));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 24 && sy > mids[best][1] - 80 && sy < mids[best][1] + 80 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), h = a < 0 ? REST[k] : d === 0 ? LIFT : d === 1 ? 14 : 6;
      tset(it.z, h, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "card " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "wallet",
  means: "A wallet on its edge with four cards: the card under the pointer slides up out of its pocket, its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[142, 116], [218, 154], [256, 173], null],
  mount,
});

keycabinet.code:
/**
 * Key cabinet: a wall cabinet standing open, a row of five keys hanging on
 * pegs across its back, each key a tag with its blade below. The pointer
 * picks a key by where it is along the row: that key lifts off its peg, the
 * others settle onto theirs, staggered from it. At rest one key sits lifted
 * a little, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is the nearest key's
 * rest centre by screen x.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 64, D = 12, H = 58, N = 5, X0 = 12, STEP = 10, ZT = 24, LIFT = 12;
const REST = [0, 1.5, 0, 5, 0.8], FAV = 3, PEG = 44;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.1);
  fit(C, [[0, 0, 0], [W, D + 3, 0], [W, 0, H], [0, D + 3, H], [0, D, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the cabinet: one rounded solid, its open face framed by a dim inset
  const body = solid(g);
  put(body, prism(P, front, ...rings(0, 0, W, D, 3, 1.2), 0, H));
  const fr = [[4, 5], [W - 4, 5], [W - 4, H - 5], [4, H - 5]].map(([x, z]) => P(x, D, z));
  mk("path", { class: "nf lo", d: poly(fr) }, body.g);
  // the pegs, one per key, and a shelf line under the row
  let pegs = "";
  for (let k = 0; k < N; k++) { const x = X0 + k * STEP; pegs += seg(P(x, D, PEG), P(x, D + 3, PEG + 0.6)); }
  pegs += seg(P(6, D, 12), P(W - 6, D, 12));
  mk("path", { class: "nf lo", d: pegs }, body.g);

  const keys = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    keys.push({ x: X0 + k * STEP, blade: solid(grp), tag: solid(grp), hole: mk("path", { class: "nf lo" }, grp), z: tween(REST[k]), last: NaN });
  }

  function draw(kk, lift) {
    if (lift === kk.last) return;
    kk.last = lift;
    const x = kk.x, z = ZT + lift;
    put(kk.blade, prism(P, front, ...rings(x - 1.1, D + 0.4, x + 1.1, D + 1.6, 0.5, 0.3), z - 11, z + 1));
    put(kk.tag, prism(P, front, ...rings(x - 3.4, D + 0.2, x + 3.4, D + 2, 1.4, 0.5), z, z + 13));
    kk.hole.setAttribute("d", seg(P(x - 1, D + 2, z + 10.5), P(x + 1, D + 2, z + 10.5)) + seg(P(x + 1.6, D + 1, z - 8), P(x + 1.6, D + 1, z - 6)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    keys.forEach((kk) => { draw(kk, tval(kk.z, now)); if (!tdone(kk.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest key by its rest centre's screen x, within the cabinet's band
  const cx = keys.map((kk) => P(kk.x, D, ZT + 6)[0]);
  const top = P(0, D, H)[1] - 6, bot = P(W, D, 0)[1] + 4;
  function hit([sx, sy]) {
    if (sy < top || sy > bot || sx < cx[0] - 22 || sx > cx[N - 1] + 22) return -1;
    let best = 0;
    cx.forEach((c, k) => { if (Math.abs(sx - c) < Math.abs(sx - cx[best])) best = k; });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    keys.forEach((kk, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : 0;
      tset(kk.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      kk.tag.sil.classList.toggle("hi", on);
      kk.blade.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "key " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "keycabinet",
  means: "An open key cabinet: the key under the pointer lifts off its peg, the others settle back onto theirs after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[144, 139], [188, 161], [232, 183], null],
  mount,
});

bollards.code:
/**
 * Bollards: a row of five retractable steel posts set in a kerb slab, each
 * in its own ground sleeve with a band near its crown. The pointer picks a
 * post by where it is along the row: that post sinks into its sleeve, the
 * others rise to full height, staggered from it. At rest one post stands
 * half sunk, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is the nearest post's
 * rest centre by screen x.
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 16, R = 4, FULL = 26, LOW = 3;
const REST = [19, 16, 9, 21, 17], FAV = 2, XE = (N - 1) * STEP;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.3);
  fit(C, [[-12, -12, -3], [XE + 12, 12, -3], [XE + 12, -12, -3], [-12, 12, -3], [0, 0, FULL], [XE, 0, FULL]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the kerb slab, a thin plate, and each post's sleeve on it
  const slab = solid(g);
  put(slab, prism(P, front, ...rings(-12, -12, XE + 12, 12, 6, 1.4), -3, 0));
  let sleeves = "";
  for (let k = 0; k < N; k++) sleeves += poly(ringAt(P, rings(k * STEP - R - 1.8, -R - 1.8, k * STEP + R + 1.8, R + 1.8, R + 1.8, 0.5)[0], 0));
  mk("path", { class: "nf lo", d: sleeves }, slab.g);

  const posts = [];
  for (let k = 0; k < N; k++) {
    const s = solid(g);
    posts.push({ x: k * STEP, s, band: mk("path", { class: "nf lo" }, s.g), z: tween(REST[k]), last: NaN });
  }
  function draw(p, h) {
    if (h === p.last) return;
    p.last = h;
    const [ring, inner] = rings(p.x - R, -R, p.x + R, R, R, 0.9);
    put(p.s, prism(P, front, ring, inner, 0, h));
    p.band.setAttribute("d", h > 7 ? open(ringAt(P, run(ring, front), h - 5)) : "");
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    posts.forEach((p) => { draw(p, tval(p.z, now)); if (!tdone(p.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest post by its rest centre's screen x, within the row's band
  const cx = posts.map((p) => P(p.x, 0, 0)[0]);
  const top = P(0, 0, FULL)[1] - 10, bot = P(XE, 0, 0)[1] + 16;
  function hit([sx, sy]) {
    if (sy < top || sy > bot || sx < cx[0] - 20 || sx > cx[N - 1] + 20) return -1;
    let best = 0;
    cx.forEach((c, k) => { if (Math.abs(sx - c) < Math.abs(sx - cx[best])) best = k; });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    posts.forEach((p, k) => {
      tset(p.z, a < 0 ? REST[k] : k === a ? LOW : FULL, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      p.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "post " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "bollards",
  means: "A row of retractable bollards: the post under the pointer sinks into its sleeve, the others rise to full height after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[125, 113], [200, 151], [275, 188], null],
  mount,
});

teslacoil.code:
/**
 * Tesla coil: a wound column on a square base, crowned with a wide toroid.
 * One spark leaps from the toroid's rim and turns to face the pointer's
 * place on the ground, on a spring. At rest it strikes out to the right,
 * bright. The slider is the spark's reach.
 *
 * The pattern: one part turning to face the pointer (aim).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const TZ = 78, R0 = 25, REST = -0.55;
const JIT = [0, 0.8, -0.9, 0.6, -0.7, 0.9, -0.4, 0];
const JZ = [0, 0.6, -0.4, 0.9, -0.6, 0.3, -0.8, 0];
const disc = (r, n = 40) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.95);
  const ext = [];
  for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; ext.push([Math.cos(a) * 64, Math.sin(a) * 64, TZ - 12]); }
  fit(C, ext.concat([[-30, -30, 0], [30, 30, 0], [30, -30, 0], [-30, 30, 0], [0, 0, TZ + 6]]), 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-30, -30, 30, 30, 7, 2);
  put(solid(g), prism(P, front, br, bi, 0, 8));
  put(solid(g), prism(P, front, disc(13), disc(11), 8, 12));
  // the secondary: a tall wound column
  put(solid(g), prism(P, front, disc(9), disc(7.6), 12, TZ - 4));
  for (let z = 18; z < TZ - 6; z += 7) mk("path", { d: open(ringAt(P, run(disc(9), front), z)), class: "nf lo" }, g);
  const sparkBack = mk("g", {}, g);
  // the toroid: a wide rounded ring on top
  const tor = mk("g", {}, g);
  const pts = [];
  for (const [r, z] of [[R0 - 4, TZ - 4], [R0, TZ], [R0 - 4, TZ + 4]]) pts.push(...ringAt(P, disc(r, 48), z));
  mk("path", { d: poly(hull(pts)), class: "sil" }, tor);
  mk("path", { d: open(ringAt(P, run(disc(R0 - 6, 48), front), TZ + 3.6)), class: "nf lo" }, tor);
  mk("path", { d: poly(hull(ringAt(P, disc(3, 16), TZ + 4).concat(ringAt(P, disc(3, 16), TZ + 8)))) }, tor);
  const sparkFront = mk("g", {}, g);
  const spark = mk("path", { class: "nf hi" }, sparkFront);

  const ang = spring(REST);
  let last = NaN, lastR = NaN, inFront = true;
  function draw(a) {
    if (a === last && reach === lastR) return;
    last = a; lastR = reach;
    const L = 10 + 34 * (reach / 100), cx = Math.cos(a), sy = Math.sin(a), pts = [];
    for (let i = 0; i < JIT.length; i++) {
      const t = i / (JIT.length - 1), r = R0 + L * t, j = JIT[i] * 6;
      pts.push(P(cx * r - sy * j, sy * r + cx * j, TZ - t * 12 + JZ[i] * 5));
    }
    spark.setAttribute("d", open(pts));
    const fr = cx + sy > -0.2;
    if (fr !== inFront) { inFront = fr; (fr ? sparkFront : sparkBack).appendChild(spark); }
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function aim(t) {
    let d = t - ang.x;
    while (d > Math.PI) d -= 2 * Math.PI;
    while (d < -Math.PI) d += 2 * Math.PI;
    ang.t = ang.x + d;
  }
  const deg = (a) => String(((Math.round((a * 180) / Math.PI) % 360) + 360) % 360).padStart(3, "0");
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, 0); aim(Math.atan2(y, x)); read.textContent = "arc " + deg(ang.t); B.wake(); },
    leave: () => { aim(REST); read.textContent = "rest"; B.wake(); },
  }));
  read.textContent = "rest";
  draw(REST);
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "teslacoil",
  means: "A Tesla coil on its base: one spark leaps from the toroid and turns to face the pointer, wherever it stands.",
  rules: [1, 3, 4, 8],
  range: [0, 70, 100],
  tour: [[300, 200], [120, 220], [140, 110], null],
  mount,
});

radiotelescope.code:
/**
 * Radio telescope: three dishes on pedestals along a pad, each dish with a
 * feed held on struts at its focus. The pointer picks a dish by where it
 * stands: that dish tilts up to the sky and its neighbours follow a little,
 * staggered from it. At rest the dishes look out at uneven angles and the
 * middle one is bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), turned to face.
 */
const {
  Cam, circ, fit, facing, hull, poly, open, seg, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 62, R = 22, DEP = 7, FOC = 20, PZ = 3, HZ = 30, FAV = 1;
const REST = [[38, 70], [52, 45], [30, 20]]; // [elevation, azimuth] at rest
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const d2r = Math.PI / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  const X1 = (N - 1) * STEP;
  fit(C, [[-30, -30, 0], [X1 + 30, 30, 0], [X1 + 30, -30, 0], [-30, 30, 0], [0, 0, HZ + R + 8], [X1, 0, HZ + R + 8], [X1 + 24, 20, HZ + 10]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-30, -26, X1 + 30, 26, 8, 2);
  put(solid(g), prism(P, front, pr, pi, 0, PZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, y = 0, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, y, 9), disc(x, y, 7.5), PZ, PZ + 4));
    put(solid(grp), prism(P, front, disc(x, y, 4, 16), disc(x, y, 3, 16), PZ + 4, HZ - 2));
    const back = mk("path", { class: "sil" }, grp), rim = mk("path", { class: "nf lo" }, grp);
    const struts = mk("path", { class: "nf lo" }, grp), feed = mk("path", { class: "nf" }, grp);
    const [e, a] = REST[k];
    items.push({ k, x, y, grp, back, rim, struts, feed, el: tween(e), az: tween(a), last: "" });
  }

  function draw(it, el, az) {
    const key = el.toFixed(2) + "," + az.toFixed(2);
    if (key === it.last) return;
    it.last = key;
    const ce = Math.cos(el * d2r), se = Math.sin(el * d2r), ca = Math.cos(az * d2r), sa = Math.sin(az * d2r);
    const n = [ce * ca, ce * sa, se], u = [-sa, ca, 0], w = [-se * ca, -se * sa, ce];
    const c = [it.x, it.y, HZ];
    const at = (r, t, off) => P(c[0] + n[0] * off + r * (Math.cos(t) * u[0] + Math.sin(t) * w[0]),
      c[1] + n[1] * off + r * (Math.cos(t) * u[1] + Math.sin(t) * w[1]),
      c[2] + n[2] * off + r * (Math.cos(t) * u[2] + Math.sin(t) * w[2]));
    const ring = (r, off, m = 36) => Array.from({ length: m }, (_, i) => at(r, (i / m) * 2 * Math.PI, off));
    const shell = [];
    for (const f of [1, 0.75, 0.5, 0.25]) shell.push(...ring(R * f, DEP * f * f));
    shell.push(at(0, 0, -2));
    it.back.setAttribute("d", poly(hull(shell)));
    const rimPts = ring(R, DEP);
    it.rim.setAttribute("d", poly(rimPts));
    const fp = at(0, 0, FOC);
    it.struts.setAttribute("d", [0, 12, 24].map((i) => seg(rimPts[i], fp)).join(""));
    it.feed.setAttribute("d", poly(hull(ring(2.6, FOC - 1.5, 12).concat(ring(2.6, FOC + 2, 12)))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) {
      draw(it, tval(it.el, now), tval(it.az, now));
      if (!tdone(it.el, now) || !tdone(it.az, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, HZ / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), d = from < 0 ? 0 : Math.abs(k - from) * stag;
      const [e0, a0] = REST[k];
      const e = a < 0 ? e0 : dd === 0 ? 82 : lerpE(e0, dd);
      tset(it.el, e, now, d);
      tset(it.az, a < 0 ? a0 : 45, now, d);
      it.back.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "dish " + (a + 1) + " · 82°";
    B.wake();
  }
  const lerpE = (e0, dd) => (dd === 1 ? 64 : e0);
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "radiotelescope",
  means: "Three radio dishes on a pad: the dish under the pointer tilts up to the sky, and its neighbours follow a little.",
  rules: [1, 2, 5, 6],
  range: [0, 50, 100],
  tour: [[200, 147], [277, 186], [123, 109], null],
  mount,
});

tenniscourt.code:
/**
 * Tennis court: a court slab with its lines, a net across the middle on two
 * posts, and four balls lying about. The pointer picks the ball nearest
 * where it stands on the court: that ball bounces up, and the others hop a
 * little, staggered by distance. At rest one ball is caught mid-bounce,
 * bright. The slider is the stagger.
 *
 * The pattern: one of a scattered few on a ground plane (terrain pick).
 */
const {
  Cam, circ, fit, facing, poly, open, seg, prism, proj, rings, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, flatDot, place,
} = HL;

const L = 150, W = 76, PZ = 4, NX = L / 2, NH = 13, BR = 7, LIFT = 36, FAV = 1;
const BALLS = [[28, 22], [44, 54], [102, 30], [124, 58]];
const REST = [0, 16, 0, 0];
const disc = (x, y, r, n = 16) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-6, -6, 0], [L + 6, W + 6, 0], [L + 6, -6, 0], [-6, W + 6, 0], [NX, -6, PZ + NH + 2], [28, 22, PZ + LIFT + 10]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-6, -6, L + 6, W + 6, 6, 2);
  put(solid(g), prism(P, front, cr, ci, 0, PZ));
  const at = (x, y) => P(x, y, PZ);
  const lines = [
    poly([at(4, 6), at(L - 4, 6), at(L - 4, W - 6), at(4, W - 6)]),
    seg(at(4, 14), at(L - 4, 14)), seg(at(4, W - 14), at(L - 4, W - 14)),
    seg(at(36, 14), at(36, W - 14)), seg(at(L - 36, 14), at(L - 36, W - 14)),
    seg(at(36, W / 2), at(L - 36, W / 2)),
  ].join("");
  mk("path", { d: lines, class: "nf lo" }, g);

  const sr = Math.hypot(...[0, 1].map((i) => P(0, 0, 0)[i] - P(BR / Math.SQRT2, -BR / Math.SQRT2, 0)[i]));
  const v = [0.612, 0.612, 0.5];
  function makeBall(k, parent) {
    const [x, y] = BALLS[k];
    const shadow = flatDot(parent, C, 3, "dot off");
    place(shadow, P(x, y, PZ));
    const body = mk("ellipse", { rx: sr, ry: sr, class: "sil" }, parent);
    const seam = mk("path", { class: "nf lo" }, parent);
    return { k, x, y, body, seam, z: tween(REST[k]), last: NaN };
  }
  const items = [];
  const sorted = BALLS.map((_, k) => k).sort((a, b) => BALLS[a][0] + BALLS[a][1] - BALLS[b][0] - BALLS[b][1]);
  const backG = mk("g", {}, g);
  // the net: two posts, a plate with its mesh, a band on top
  const ng = mk("g", {}, g);
  for (const py of [-3, W + 3]) put(solid(ng), prism(P, front, disc(NX, py, 1.6, 12), disc(NX, py, 1, 12), PZ, PZ + NH + 1));
  mk("path", { d: poly([P(NX, -3, PZ + NH), P(NX, W + 3, PZ + NH), P(NX, W + 3, PZ + 1), P(NX, -3, PZ + 1)]) }, ng);
  let mesh = "";
  for (let yy = 3; yy < W; yy += 6) mesh += seg(P(NX, yy, PZ + 1), P(NX, yy, PZ + NH - 1.6));
  for (let zz = PZ + 4; zz < PZ + NH - 1; zz += 3) mesh += seg(P(NX, -3, zz), P(NX, W + 3, zz));
  mk("path", { d: mesh, class: "nf lo" }, ng);
  mk("path", { d: seg(P(NX, -3, PZ + NH - 1.6), P(NX, W + 3, PZ + NH - 1.6)), class: "nf" }, ng);
  const frontG = mk("g", {}, g);
  for (const k of sorted) items[k] = makeBall(k, BALLS[k][0] < NX ? backG : frontG);

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const cz = PZ + BR + lift, c = P(it.x, it.y, cz);
    it.body.setAttribute("cx", c[0]); it.body.setAttribute("cy", c[1]);
    let d = "";
    for (const s of [1, -1]) {
      const n = [s * 0.55, -s * 0.55, s * 0.62], u = [0.707, 0.707, 0], w = [n[1] * u[2] - n[2] * u[1], n[2] * u[0] - n[0] * u[2], n[0] * u[1] - n[1] * u[0]];
      const pts = [];
      for (let i = 0; i <= 32; i++) {
        const t = (i / 32) * 2 * Math.PI, rr = BR * 0.72, off = BR * 0.69;
        const q = [0, 1, 2].map((j) => n[j] * off + rr * (Math.cos(t) * u[j] + Math.sin(t) * w[j]));
        if (q[0] * v[0] + q[1] * v[1] + q[2] * v[2] > 0.4) pts.push(P(it.x + q[0], it.y + q[1], cz + q[2]));
        else if (pts.length > 1) { d += open(pts); pts.length = 0; } else pts.length = 0;
      }
      if (pts.length > 1) d += open(pts);
    }
    it.seam.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, PZ + BR);
    let best = -1, bd = Infinity;
    BALLS.forEach(([x, y], k) => { const dd = Math.hypot(wx - x, wy - y); if (dd < bd) { bd = dd; best = k; } });
    return bd < 20 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dist = from < 0 ? 0 : Math.hypot(it.x - BALLS[from][0], it.y - BALLS[from][1]) / 30;
      const z = a < 0 ? REST[k] : k === a ? LIFT : clampHop(dist);
      tset(it.z, z, now, dist * stag);
      it.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "ball " + (a + 1);
    B.wake();
  }
  const clampHop = (dist) => Math.max(3, 14 - dist * 4);
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v2) => { stag = v2; }, destroy: bag.dispose };
}

hairline({
  name: "tenniscourt",
  means: "A tennis court with a net and four balls: the ball nearest the pointer bounces up, and the others hop a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[162, 131], [243, 182], [236, 213], null],
  mount,
});

grandpiano.code:
/**
 * Grand piano: a curved case on three legs, keyboard at the near end, a lid
 * hinged along the straight side. The pointer over the piano props the lid
 * open, wider the further toward the tail it stands; leaving lowers it to a
 * half-stick rest. At rest the lid is up a little, bright. The slider is the
 * widest the lid will open.
 *
 * The pattern: a continuous aim on one hinge (a spring on an angle); the hit
 * is the case's rest footprint on its own height, which never moves.
 */
const {
  Cam, clamp, fillet, fit, facing, hull, poly, open, prism, proj, rings, ringAt, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const Z0 = 28, Z1 = 40, REST = 10;
// the case outline, tail at x 0, keyboard side at x 100; hinge along y 0
const OUT = fillet([[0, 6], [10, 0], [100, 0], [100, 60], [62, 60], [26, 34]], [6, 6, 2, 2, 14, 16], 4);
const ring = (pts) => pts.map(([u, v]) => ({ u, v }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.35);
  const lidPt = (a) => ([u, v]) => [u, v * Math.cos(a), Z1 + 1 + v * Math.sin(a)];
  const ext = OUT.map(lidPt((60 * Math.PI) / 180));
  fit(C, [[0, 0, 0], [114, 60, 0], [0, 60, 0], [114, 0, 0], ...ext], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // legs: tail, and two under the keyboard end
  for (const [x, y] of [[14, 8], [92, 6], [92, 54]]) {
    const [lr, li] = rings(x - 3, y - 3, x + 3, y + 3, 3, 0.8);
    put(solid(g), prism(P, front, lr, li, 0, Z0));
  }
  // the case: a convex hull of the curved rim at both heights, the rim as its crease
  const cs = solid(g);
  cs.sil.setAttribute("d", poly(hull(OUT.map(([u, v]) => P(u, v, Z0)).concat(OUT.map(([u, v]) => P(u, v, Z1))))));
  cs.cr.setAttribute("d", poly(OUT.map(([u, v]) => P(u, v, Z1))));
  // the harp inside: a few strings running tail to keys, dim
  const harp = mk("path", { class: "nf lo" }, g);
  let hd = "";
  for (let i = 1; i < 6; i++) { const v = i * 9; hd += seg(P(Math.max(14, 40 - v * 0.5 + v * 0.6), v, Z1 - 1), P(96, v, Z1 - 1)); }
  harp.setAttribute("d", hd);
  // keyboard: a slab at the near end, black keys as short dim marks
  const [kr, ki] = rings(100, 2, 114, 58, 2, 1);
  put(solid(g), prism(P, front, kr, ki, Z0 + 2, Z0 + 8));
  let kd = "";
  for (let i = 0; i < 12; i++) { if (i % 7 === 2 || i % 7 === 6) continue; const y = 6 + i * 4.3; kd += seg(P(103, y, Z0 + 8), P(108, y, Z0 + 8)); }
  mk("path", { d: kd, class: "nf lo" }, g);

  const prop = mk("path", { class: "dash nf" }, g);
  const lid = mk("path", { class: "sil hi" }, g), lidT = mk("path", { class: "nf lo" }, g);

  const ang = spring(REST);
  let last = NaN;
  function draw(deg) {
    const d = Math.round(deg * 10) / 10;
    if (d === last) return;
    last = d;
    const a = (d * Math.PI) / 180, f = lidPt(a);
    const top = OUT.map((p) => P(...f(p))), bot = OUT.map(([u, v]) => P(u, v * Math.cos(a), Z1 + v * Math.sin(a) - 0.6 * Math.cos(a)));
    lid.setAttribute("d", poly(hull(top.concat(bot))));
    lidT.setAttribute("d", poly(top));
    // the stick: from the rim near the bent side up to the lid's edge
    prop.setAttribute("d", d > 3 ? seg(P(58, 46, Z1), P(...f([58, 46]))) : "");
  }
  draw(REST);

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function aim([sx, sy]) {
    const [u, v] = unproj(C, sx, sy, Z1);
    if (u < -6 || u > 120 || v < -10 || v > 66) return null;
    return clamp(max * (0.55 + 0.45 * u / 100), 12, max);
  }
  function set(t) {
    ang.t = t === null ? REST : t;
    read.textContent = t === null ? "rest" : "lid " + Math.round(t) + "°";
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move: (p) => set(aim(p)), leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; }, destroy: bag.dispose };
}

hairline({
  name: "grandpiano",
  means: "A grand piano on three legs: the pointer props its lid open, wider toward the keys, and leaving lowers it to half-stick.",
  rules: [1, 3, 5, 8],
  range: [24, 45, 60],
  tour: [[150, 150], [200, 170], [260, 200], null],
  mount,
});

filmcamera.code:
/**
 * Film camera: a boxy cine camera on a low plinth, a lens barrel facing the
 * viewer and two film reels standing on its top. The pointer's place across
 * the stage winds the reels: their spokes turn on a spring and the lens
 * racks out, the front reel lighting up as it runs. At rest the lens hood is the bright mark and the
 * reels sit part-wound. The slider is how far one sweep winds them.
 *
 * The pattern: a continuous input turning parts (spin).
 */
const {
  Cam, circ, fit, facing, hull, poly, open, seg, prism, proj, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BX = 60, BY = 26, Z0 = 3, BZ = 44, RR = 15, RW = 7, LR = 9;
const REELS = [[15, 13], [45, 13]];
const REST = 0.5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gain = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-6, -6, 0], [BX + 6, BY + 18, 0], [BX + 6, -6, 0], [-6, BY + 18, 0], [BX / 2, BY + 25, 4], [0, BY / 2, BZ + 2 * RR + 2], [BX, BY / 2, BZ + 2 * RR + 2]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-6, -6, BX + 6, BY + 18, 5, 1.6);
  put(solid(g), prism(P, front, pr, pi, 0, Z0));
  const [br, bi] = rings(0, 0, BX, BY, 5, 1.8);
  put(solid(g), prism(P, front, br, bi, Z0, BZ));
  // a door seam on the side and a small finder on top
  mk("path", { d: open([P(BX, 4, Z0 + 6), P(BX, 4, BZ - 6)]) + seg(P(BX, 22, Z0 + 6), P(BX, 22, BZ - 6)), class: "nf lo" }, g);
  const [fr, fi] = rings(24, 2, 36, 9, 2, 0.8);

  // a disc standing in the x-z plane, centre (x, y, z): points at depth y
  const vcirc = (x, y, z, r, n = 36) => circ(r, n).map((q) => P(x + q.u, y, z + q.v));
  const ycirc = (x, z, y, r, n = 36) => circ(r, n).map((q) => P(x + q.u, y, z + q.v));

  put(solid(g), prism(P, front, fr, fi, BZ, BZ + 5));
  // reels, back to front (ascending x)
  const reels = REELS.map(([x, y], k) => {
    const cz = BZ + RR + 1, grp = mk("g", {}, g);
    // the arm that holds the reel
    put(solid(grp), prism(P, front, ...rings(x - 2, y - 2, x + 2, y + 2, 1, 0.6), BZ, cz));
    const sil = mk("path", { d: poly(hull(vcirc(x, y - RW / 2, cz, RR).concat(vcirc(x, y + RW / 2, cz, RR)))), class: "sil" }, grp);
    mk("path", { d: poly(vcirc(x, y + RW / 2, cz, RR - 1.6)), class: "nf lo" }, grp);
    const spokes = mk("path", { class: "nf" }, grp);
    mk("path", { d: poly(vcirc(x, y + RW / 2, cz, 2.4, 16)) }, grp);
    return { x, y, cz, sil, spokes, k };
  });

  // the lens barrel along +y, then its hood
  const lg = mk("g", {}, g), LX = BX / 2, LZ = (Z0 + BZ) / 2 - 2;
  const barrel = mk("path", { class: "sil" }, lg), hood = mk("path", { class: "sil" }, lg);
  const hr = mk("path", { class: "nf lo" }, lg), glass = mk("path", { class: "nf lo" }, lg);
  function lens(e) {
    barrel.setAttribute("d", poly(hull(ycirc(LX, LZ, BY, LR).concat(ycirc(LX, LZ, BY + 10 + e, LR)))));
    hood.setAttribute("d", poly(hull(ycirc(LX, LZ, BY + 10 + e, LR + 3).concat(ycirc(LX, LZ, BY + 15 + e, LR + 4)))));
    hr.setAttribute("d", poly(ycirc(LX, LZ, BY + 15 + e, LR + 2.6)));
    glass.setAttribute("d", poly(ycirc(LX, LZ, BY + 13 + e, LR - 2.5)));
  }
  const ext = spring(0);

  const ang = spring(REST);
  let lastA = NaN;
  let lastE = NaN;
  function draw(a, e) {
    if (e !== lastE) { lastE = e; lens(e); }
    if (a === lastA) return;
    lastA = a;
    for (const r of reels) {
      let d = "";
      for (let s = 0; s < 4; s++) {
        const t = a * (r.k ? 1 : 1.3) + (s * Math.PI) / 2;
        const c = Math.cos(t), sn = Math.sin(t);
        d += seg(P(r.x + 3 * c, r.y + RW / 2, r.cz + 3 * sn), P(r.x + (RR - 2.5) * c, r.y + RW / 2, r.cz + (RR - 2.5) * sn));
      }
      r.spokes.setAttribute("d", d);
    }
  }
  draw(REST, 0);

  const B = register(stage, (dt) => {
    const m = stepS(ang, dt), n = stepS(ext, dt);
    draw(ang.x, ext.x);
    return m || n;
  });
  bag.add(B.unregister);

  let on = null;
  function set(active, sx) {
    if (active) ang.t = REST + ((sx - 200) / 200) * Math.PI * gain;
    else ang.t = REST;
    ext.t = active ? 9 : 0;
    if (on !== active) {
      on = active;
      hood.classList.toggle("hi", !active);
      reels[1].sil.classList.toggle("hi", active);
    }
    const f = Math.round(((ang.t - REST) / (2 * Math.PI)) * 24);
    read.textContent = active ? "fr " + (f < 0 ? "−" : "+") + String(Math.abs(f)).padStart(2, "0") : "rest";
    B.wake();
  }
  set(false, 200);
  bag.add(pointer(stage, { move: ([sx]) => set(true, sx), leave: () => set(false, 200) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { gain = v; }, destroy: bag.dispose };
}

hairline({
  name: "filmcamera",
  means: "A cine camera with two film reels: moving across it winds the reels and racks the lens out; at rest the lens hood leads.",
  rules: [3, 4, 5, 8],
  range: [0.5, 1.5, 3],
  tour: [[230, 126], [150, 190], [271, 101], null],
  mount,
});

jewellerybox.code:
/**
 * Jewellery box: a low cabinet of four shallow drawers, each with a knob,
 * rings resting in the trays. The pointer picks a drawer by its front: it
 * slides out to show the rings, and the drawers beside it slide a little,
 * staggered from it. At rest one drawer stands ajar, bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single column (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 104, D = 58, N = 4, DH = 13, Z0 = 5, H = Z0 + N * DH + 6, OUT = 34, FAV = 2;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.62);
  fit(C, [[-4, -4, 0], [W + 4, D + OUT + 4, 0], [W + 4, -4, 0], [-4, D + OUT + 4, 0], [0, 0, H + 3], [W, 0, H + 3]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the cabinet, with a lid lip on top
  const [br, bi] = rings(0, 0, W, D, 4, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, H - 3));
  const [lr, li] = rings(-2, -2, W + 2, D + 2, 5, 2);
  put(solid(g), prism(P, front, lr, li, H - 3, H));
  // drawers painted bottom first, so a higher drawer covers the one below
  const items = [];
  for (let k = N - 1; k >= 0; k--) {
    const z0 = Z0 + (N - 1 - k) * DH, grp = mk("g", {}, g);
    const sol = solid(grp), ring = mk("path", { class: "nf" }, grp), ring2 = mk("path", { class: "nf" }, grp), knob = mk("path", {}, grp);
    items[k] = { k, z0, sol, ring, ring2, knob, o: tween(k === FAV ? OUT * 0.45 : 1 + ((k * 5) % 3)), last: NaN };
  }

  function draw(it, o) {
    if (o === it.last) return;
    it.last = o;
    const y1 = D + 2 + o, z0 = it.z0 + 1, z1 = it.z0 + DH - 1;
    const [r, i] = rings(5, D - 1, W - 5, y1, 2.5, 2.2);
    put(it.sol, prism(P, front, r, i, z0, z1));
    // two rings lying in the tray, shown as the drawer clears the cabinet
    const show = o > 10;
    it.ring.setAttribute("d", show ? poly(ringAt(P, disc(W * 0.3, D + o * 0.55, 5), z1 - 0.5)) : "");
    it.ring2.setAttribute("d", show ? poly(ringAt(P, disc(W * 0.62, D + o * 0.5, 4.2), z1 - 0.5)) : "");
    const kn = disc(W / 2, y1 + 1.5, 2.6, 12);
    it.knob.setAttribute("d", poly(hull(ringAt(P, kn, (z0 + z1) / 2 - 1.3).concat(ringAt(P, kn, (z0 + z1) / 2 + 1.3)))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.o, now)); if (!tdone(it.o, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  // rest fronts: static, so a drawer sliding out never moves its hit area
  const mids = items.map((it) => P(W / 2, D + 2, it.z0 + DH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < DH * 1.62 * 0.6 && Math.abs(mids[best][0] - sx) < 95 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), o = a < 0 ? (k === FAV ? OUT * 0.45 : 1 + ((k * 5) % 3)) : dd === 0 ? OUT : dd === 1 ? 7 : 1;
      tset(it.o, o, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.sol.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "drawer " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "jewellerybox",
  means: "A jewellery box of four drawers: the drawer under the pointer slides out to show its rings, and its neighbours open a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[184, 149], [184, 202], [184, 167], null],
  mount,
});

housekeeping.code:
/**
 * Housekeeping: a hotel cart on four castors with a push handle at one end
 * and three stacks of folded towels on its top deck. The pointer picks a
 * stack by where it stands: that stack lifts off the deck, and its
 * neighbours rise a little, staggered from it. At rest one stack is raised,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 40, W = 30, BZ = 50, LIFT = 20, FAV = 1, TH = 6;
const X1 = 130, Y1 = 44;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [X1, 0, 0], [0, Y1, 0], [-8, Y1 / 2, 74], [X1, Y1 / 2, BZ + 2 * TH + LIFT + 4]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // castors, far ones first
  for (const [x, y] of [[8, 8], [X1 - 8, 8], [8, Y1 - 8], [X1 - 8, Y1 - 8]]) put(solid(g), prism(P, front, disc(x, y, 5), disc(x, y, 3.5), 0, 8));
  // handle at the far end: two posts and a grip
  for (const y of [8, Y1 - 8]) { const [a, b] = rings(-6, y - 2, -2, y + 2, 1.5, 0.6); put(solid(g), prism(P, front, a, b, 30, 72)); }
  { const [a, b] = rings(-7, 4, -1, Y1 - 4, 2.5, 0.8); put(solid(g), prism(P, front, a, b, 68, 74)); }
  // the body: a lower shelf, a cabinet, a top deck
  { const [a, b] = rings(0, 0, X1, Y1, 5, 2); put(solid(g), prism(P, front, a, b, 8, 14)); }
  { const [a, b] = rings(3, 3, X1 - 3, Y1 - 3, 4, 2); put(solid(g), prism(P, front, a, b, 14, BZ - 4)); }
  { const [a, b] = rings(0, 0, X1, Y1, 5, 2); put(solid(g), prism(P, front, a, b, BZ - 4, BZ)); }

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 25 + k * STEP, y = Y1 / 2, grp = mk("g", {}, g);
    const towels = [0, 1].map(() => solid(grp));
    items.push({ k, x, y, grp, towels, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }
  const tr = items.map((it) => [rings(it.x - W / 2, it.y - W / 2, it.x + W / 2, it.y + W / 2, 4, 1.5), rings(it.x - W / 2 + 1, it.y - W / 2 + 2, it.x + W / 2 - 1, it.y + W / 2 - 1, 4, 1.5)]);

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    it.towels.forEach((s, j) => {
      const [a, b] = tr[it.k][j], z0 = BZ + lift + j * (TH + lift * 0.15);
      put(s, prism(P, front, a, b, z0, z0 + TH));
    });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, BZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.towels[1].sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "stack " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "housekeeping",
  means: "A hotel housekeeping cart: the towel stack under the pointer lifts off the top deck, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[151, 104], [200, 129], [249, 154], null],
  mount,
});

canoe.code:
/**
 * Canoe: an open canoe afloat on a round of lake, two thwarts across its
 * open hull, the bow and stern rising. The pointer stands somewhere on the
 * water and the canoe swings its bow round to face it, on a spring. At rest
 * it lies at a slant, the bow marked by one bright dot. The slider is how
 * far the canoe may swing from its rest heading.
 *
 * The pattern: one part turning to face the pointer.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rrect, seg, spring, stepS, unproj,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const L = 124, W = 15, D = 11, RISE = 7, R = 82, REST = 0.35, N = 18;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = (value * Math.PI) / 180;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[-R, -R, 0], [R, R, 0], [R, -R, 0], [-R, R, 0], [0, 0, D + RISE + 4]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const lr = rrect(-R, -R, R, R, R, 14), li = rrect(-R + 2.2, -R + 2.2, R - 2.2, R - 2.2, R - 2.2, 14);
  put(solid(g), prism(P, front, lr, li, -3, 0));
  // a ripple guide on the water around the hull
  mk("path", { d: poly(circ(R * 0.82, 48).map((q) => P(q.u, q.v, 0))), class: "dash nf" }, g);

  const boat = solid(g);
  boat.g.removeChild(boat.cr);
  const inner = mk("path", { class: "nf lo" }, boat.g), thw = mk("path", { class: "nf lo" }, boat.g);
  const bow = flatDot(boat.g, C, 2.4, "dot");

  // plan outline at fraction t along the length: half-width, deck height
  const half = (t, w) => w * Math.pow(Math.sin(Math.PI * t), 0.75);
  const deck = (t) => D + RISE * Math.pow(Math.abs(2 * t - 1), 4);
  function outline(len, w, zf, a) {
    const ca = Math.cos(a), sa = Math.sin(a), pts = [];
    for (let s = -1; s <= 1; s += 2) for (let i = 0; i <= N; i++) {
      const t = s > 0 ? i / N : 1 - i / N, x = (t - 0.5) * len, y = s * half(t, w);
      pts.push(P(x * ca - y * sa, x * sa + y * ca, zf(t)));
    }
    return pts;
  }
  const at = (x, y, z, a) => P(x * Math.cos(a) - y * Math.sin(a), x * Math.sin(a) + y * Math.cos(a), z);

  const yaw = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const keel = outline(L * 0.82, W * 0.55, () => 0, a), top = outline(L, W, deck, a);
    boat.sil.setAttribute("d", poly(hull(keel.concat(top))));
    inner.setAttribute("d", poly(outline(L - 6, W - 2.4, (t) => deck(t) - 0.6, a)));
    let d = "";
    for (const f of [0.34, 0.66]) {
      const x = (f - 0.5) * L, w = half(f, W - 2.4), z = deck(f) - 0.6;
      d += seg(at(x, -w, z, a), at(x, w, z, a));
    }
    thw.setAttribute("d", d);
    place(bow, at(L / 2 - 3, 0, deck(1) - 1, a));
  }

  const B = register(stage, (dt) => { const m = stepS(yaw, dt); draw(yaw.x); return m; });
  bag.add(B.unregister);

  let act = null;
  function setAim(p) {
    if (!p) {
      yaw.t = REST; act = null;
      boat.sil.classList.remove("hi"); bow.setAttribute("class", "dot");
      read.textContent = "rest";
    } else {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (Math.hypot(x, y) < 6) return;
      let d = Math.atan2(y, x) - REST;
      d = Math.atan2(Math.sin(d), Math.cos(d));
      yaw.t = REST + clamp(d, -reach, reach);
      act = p;
      boat.sil.classList.add("hi"); bow.setAttribute("class", "dot m");
      const deg = Math.round((((yaw.t * 180) / Math.PI) % 360 + 360) % 360);
      read.textContent = String(deg).padStart(3, "0") + "°";
    }
    B.wake();
  }
  setAim(null);
  draw(yaw.x);
  bag.add(pointer(stage, { move: setAim, leave: () => setAim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = (v * Math.PI) / 180; if (act) setAim(act); }, destroy: bag.dispose };
}

