climbingwall.code:
/**
 * Climbing wall: a tall panel standing on a crash mat, a route of holds
 * bolted up its face. The pointer picks the nearest hold: it pushes out of
 * the wall toward the hand, and the holds beside it on the route ease out a
 * little, staggered from it. At rest one hold stands out, bright.
 *
 * The pattern: one of many on a face plane.
 */
const { Cam, fit, prism, proj, rings, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const W = 120, T = 8, H = 112, FAV = 5;
const HOLDS = [[22, 16, 13, 7], [50, 30, 10, 6], [30, 48, 14, 8], [72, 56, 12, 7], [52, 76, 13, 6], [94, 82, 10, 7], [76, 100, 14, 8]];
const REST = [4, 3, 5, 3, 4, 11, 3], OUT = 30;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.62);
  fit(C, [[-8, -8, 0], [W + 8, 44, 0], [W + 8, -8, 0], [-8, 44, 0], [0, 0, H], [W, 0, H], [W, T + OUT, H]], 200, 166);
  const P = proj(C), front = HL.facing(C);
  const g = mk("g", {}, svg);
  const [mr, mi] = rings(-8, -8, W + 8, 44, 6, 2);
  put(solid(g), prism(P, front, mr, mi, 0, 4));
  const [wr, wi] = rings(0, 0, W, T, 3, 1.4);
  put(solid(g), prism(P, front, wr, wi, 4, H));

  const items = HOLDS.map(([x, z, w, h], k) => {
    const s = solid(g);
    return { k, x, z, w, h, s, d: tween(REST[k]), last: NaN };
  });

  function draw(it, d) {
    if (d === it.last) return;
    it.last = d;
    const [r, i] = rings(it.x - it.w / 2, T - 1, it.x + it.w / 2, T + d, Math.min(it.w, d) / 2.2, 1);
    put(it.s, prism(P, front, r, i, it.z - it.h / 2, it.z + it.h / 2));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.d, now)); if (!tdone(it.d, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, T, it.z));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 28 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), d = a < 0 ? REST[k] : dd === 0 ? OUT : dd === 1 ? 11 : 2;
      tset(it.d, d, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "hold " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "climbingwall",
  means: "A climbing wall on a crash mat: the hold under the pointer pushes out toward the hand, and its neighbours on the route ease out.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[168, 190], [225, 163], [230, 103], null],
  mount,
});

djdecks.code:
/**
 * DJ decks: two turntables either side of a mixer on one long case. The
 * pointer picks a deck by where it stands: that deck's tonearm swings in onto
 * the record and the mixer's crossfader slides over to it. At rest the left
 * arm sits on its record, bright. The slider is the arm's reach.
 *
 * The pattern: one of a few in a single row (riffle), picked by screen x.
 */
const {
  Cam, circ, fit, lerp, facing, open, poly, prism, proj, rings, ringAt, rad, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 150, D = 62, BZ = 8, PZ = 12, R = 23, LEN = 30;
const DECKS = [{ x: 30, y: 33, px: 55, py: 9 }, { x: 120, y: 33, px: 145, py: 9 }];
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.72);
  fit(C, [[-4, -4, 0], [W + 4, D + 4, 0], [W + 4, -4, 0], [-4, D + 4, 0], [W / 2, D / 2, PZ + 10]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(0, 0, W, D, 7, 2);
  put(solid(g), prism(P, front, cr, ci, 0, BZ));

  const decks = DECKS.map((d, k) => {
    const grp = mk("g", {}, g);
    // platter, record, label
    put(solid(grp), prism(P, front, disc(d.x, d.y, R), disc(d.x, d.y, R - 2), BZ, PZ));
    mk("path", { d: poly(ringAt(P, disc(d.x, d.y, R - 6), PZ)), class: "nf lo" }, grp);
    mk("path", { d: poly(ringAt(P, disc(d.x, d.y, 6, 24), PZ)), class: "nf lo" }, grp);
    // tonearm pivot
    put(solid(grp), prism(P, front, disc(d.px, d.py, 4, 20), disc(d.px, d.py, 2.6, 20), BZ, PZ + 3));
    const arm = mk("path", { class: "sil nf" }, grp), head = mk("path", { class: "nf" }, grp);
    if (k === 0) d.after = mk("g", {}, g);
    return { ...d, k, grp, arm, head, a: tween(k === 0 ? 1 : 0), last: NaN };
  });

  // mixer between the decks, painted after the left deck
  const mix = decks[0].after;
  const [mr, mi] = rings(62, 8, 88, 56, 3, 1.4);
  put(solid(mix), prism(P, front, mr, mi, BZ, BZ + 5));
  const MZ = BZ + 5;
  for (const [u, v] of [[69, 16], [81, 16], [69, 25], [81, 25]]) mk("path", { d: poly(ringAt(P, disc(u, v, 2.4, 16), MZ)), class: "nf lo" }, mix);
  for (const u of [69, 81]) mk("path", { d: seg(P(u, 31, MZ), P(u, 42, MZ)), class: "lo" }, mix);
  mk("path", { d: seg(P(66, 50, MZ), P(84, 50, MZ)), class: "lo" }, mix);
  const fader = solid(mix);
  const fade = tween(0);
  let lastF = NaN;

  function drawArm(d, t) {
    if (t === d.last) return;
    d.last = t;
    const ang = rad(lerp(-25, 32 + 12 * reach, t)), z = PZ + 3;
    const ex = d.px - LEN * Math.sin(ang), ey = d.py + LEN * Math.cos(ang);
    const bx = d.px - LEN * 0.6 * Math.sin(ang + rad(8)), by = d.py + LEN * 0.6 * Math.cos(ang + rad(8));
    d.arm.setAttribute("d", open([P(d.px, d.py, z), P(bx, by, z), P(ex, ey, z)]));
    const [hr, hi] = rings(ex - 2.5, ey - 1.5, ex + 2.5, ey + 3.5, 1.2, 0.8);
    d.head.setAttribute("d", prism(P, front, hr, hi, z - 1.5, z).sil);
  }
  function drawFader(f) {
    if (f === lastF) return;
    lastF = f;
    const u = lerp(68, 82, f), [r, i] = rings(u - 2, 47.5, u + 2, 52.5, 1, 0.7);
    put(fader, prism(P, front, r, i, MZ, MZ + 2.5));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const d of decks) { drawArm(d, tval(d.a, now)); if (!tdone(d.a, now)) moving = true; }
    drawFader(tval(fade, now)); if (!tdone(fade, now)) moving = true;
    return moving;
  });
  bag.add(B.unregister);

  const mids = decks.map((d) => P(d.x, d.y, PZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 70 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    const on = a < 0 ? 0 : a;
    decks.forEach((d, k) => {
      tset(d.a, k === on ? 1 : 0, now, 0);
      d.arm.classList.toggle("hi", k === on);
    });
    tset(fade, a < 0 ? 0.2 : a, now, 0);
    read.textContent = a < 0 ? "rest" : a === 0 ? "deck A" : "deck B";
    for (const d of decks) d.last = NaN;
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; for (const d of decks) d.last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "djdecks",
  means: "Two turntables and a mixer: the deck under the pointer swings its tonearm onto the record and the crossfader slides to it.",
  rules: [1, 4, 5, 8],
  range: [0, 0.5, 1],
  tour: [[143, 122], [205, 150], [252, 177], null],
  mount,
});

dressform.code:
/**
 * Dress form: a tailor's torso on a pole over a round foot. The pointer
 * stands somewhere on the studio floor and the form turns on its pole to
 * face it, its front seam swinging round to the pointer. At rest it stands
 * a quarter turned, the seam bright. The slider is how far it may turn.
 *
 * The pattern: one part turning to face the pointer (officechairs).
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rad, rings, ringAt, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

// the torso's profile: [z, half-width, half-depth], hip to shoulder
const PROF = [[66, 15, 11], [72, 17, 12.5], [80, 15, 11], [88, 12.5, 9.5], [96, 14, 10.5], [104, 17, 12.5], [112, 17.5, 12], [118, 15, 10], [122, 10, 7.5]];
const REST = 70, TOP = 122, NECK = 4.2;
const disc = (r, n = 40) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxT = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-24, -24, 0], [24, 24, 0], [-24, 24, 0], [24, -24, 0], [0, 0, TOP + 12], [-18, 18, 110], [18, -18, 110]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the foot, a low round plinth, and the pole
  const [fr, fi] = rings(-22, -22, 22, 22, 22, 2);
  put(solid(g), prism(P, front, fr, fi, 0, 5));
  const [pr, pi] = rings(-2.4, -2.4, 2.4, 2.4, 2.4, 0.8);
  put(solid(g), prism(P, front, pr, pi, 5, 68));

  const body = mk("path", { class: "sil" }, g);
  const hem = mk("path", { class: "nf lo" }, g);
  const waist = mk("path", { class: "nf lo" }, g);
  const seam = mk("path", { class: "nf sil hi" }, g);
  const neck = solid(g);
  const [nr, ni] = rings(-NECK, -NECK, NECK, NECK, NECK, 1);
  put(neck, prism(P, front, nr, ni, TOP - 1, TOP + 8));
  const cap = mk("path", { class: "nf" }, g);
  cap.setAttribute("d", poly(ringAt(P, disc(2), TOP + 10.5)));
  const capS = solid(g);
  put(capS, prism(P, front, disc(2.2, 16), disc(1.4, 16), TOP + 8, TOP + 11));

  // one level of the torso as screen points, turned to face phi
  const level = ([z, a, b], phi, n = 36) => {
    const fx = Math.cos(phi), fy = Math.sin(phi), out = [];
    for (let i = 0; i < n; i++) {
      const t = (i / n) * Math.PI * 2, s = a * Math.cos(t), f = b * Math.sin(t);
      out.push(P(-fy * s + fx * f, fx * s + fy * f, z));
    }
    return out;
  };
  const lower = (pts) => { const cy = pts.reduce((m, p) => m + p[1], 0) / pts.length; return pts.filter((p) => p[1] >= cy - 0.01).sort((p, q) => p[0] - q[0]); };

  const turn = spring(0);
  let last = NaN;
  function draw() {
    const phi = rad(REST + turn.x);
    if (phi === last) return;
    last = phi;
    const L = [], R = [];
    for (const lv of PROF) {
      const pts = level(lv, phi);
      let lo = pts[0], hi = pts[0];
      for (const p of pts) { if (p[0] < lo[0]) lo = p; if (p[0] > hi[0]) hi = p; }
      L.push(lo); R.push(hi);
    }
    const bot = lower(level(PROF[0], phi)), top = hull(level(PROF[PROF.length - 1], phi));
    const topUp = top.filter((p) => p[1] <= (L[L.length - 1][1] + R[R.length - 1][1]) / 2 + 0.5).sort((p, q) => p[0] - q[0]);
    body.setAttribute("d", poly([...bot.slice().reverse(), ...L, ...topUp, ...R.slice().reverse()]));
    hem.setAttribute("d", open(lower(level([PROF[0][0] + 2.5, PROF[0][1] - 0.4, PROF[0][2] - 0.3], phi))));
    waist.setAttribute("d", open(lower(level(PROF[3], phi))));
    // the front seam shows only while the front faces the viewer
    const facingFront = Math.cos(phi - rad(45)) > 0.05;
    const s = [];
    if (facingFront) for (let z = PROF[0][0] + 1; z <= 120; z += 2) {
      let k = 0; while (k < PROF.length - 2 && PROF[k + 1][0] < z) k++;
      const [z0, , b0] = PROF[k], [z1, , b1] = PROF[k + 1], b = b0 + ((b1 - b0) * clamp((z - z0) / (z1 - z0), 0, 1));
      s.push(P(Math.cos(phi) * b, Math.sin(phi) * b, z));
    }
    seam.setAttribute("d", s.length ? open(s) : "");
  }

  const B = register(stage, (dt) => { const m = stepS(turn, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(t) {
    turn.t = t;
    read.textContent = t === 0 ? "rest" : (t > 0 ? "+" : "−") + Math.abs(Math.round(t)) + "°";
    B.wake();
  }
  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, 0);
    if (Math.hypot(wx, wy) < 6) return;
    let d = (Math.atan2(wy, wx) * 180) / Math.PI - REST;
    d = ((d + 540) % 360) - 180;
    aim(clamp(d, -maxT, maxT) || 0.001);
  }
  draw();
  aim(0);
  bag.add(pointer(stage, { move, leave: () => aim(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxT = v; }, destroy: bag.dispose };
}

hairline({
  name: "dressform",
  means: "A tailor's dress form on a pole: it turns to face the pointer across the floor, its front seam swinging round.",
  rules: [1, 3, 5, 8],
  range: [40, 110, 170],
  tour: [[330, 210], [70, 220], [210, 300], null],
  mount,
});

shoeboxes.code:
/**
 * Shoe boxes: four lidded boxes in a row on a shop floor, each a little
 * different in height. The pointer picks a box by where it stands: its lid
 * lifts straight off, and the lids beside it rise a touch, staggered from
 * it. At rest one lid sits ajar, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 40, W = 30, D = 50, LH = 6, LIFT = 26, FAV = 2;
const HS = [18, 22, 16, 20];
const X1 = (N - 1) * STEP + W;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-4, -4, 0], [X1 + 4, D + 4, 0], [X1 + 4, -4, 0], [-4, D + 4, 0], [0, 0, 22 + LH + LIFT], [X1, 0, 22 + LH + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * STEP, h = HS[k], grp = mk("g", {}, g);
    const [br, bi] = rings(x0, 0, x0 + W, D, 1.5, 1.2);
    put(solid(grp), prism(P, front, br, bi, 0, h));
    const lid = solid(grp);
    const [lr, li] = rings(x0 - 1.2, -1.2, x0 + W + 1.2, D + 1.2, 1.8, 1.2);
    items.push({ k, x: x0 + W / 2, h, lid, lr, li, z: tween(k === FAV ? 7 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = it.h - 3 + lift;
    put(it.lid, prism(P, front, it.lr, it.li, z0, z0 + LH));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, D / 2, it.h));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? 7 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.lid.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "box " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "shoeboxes",
  means: "Four shoe boxes in a row: the lid of the box under the pointer lifts off, and the lids beside it rise a touch.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[150, 150], [240, 190], [290, 215], null],
  mount,
});

townhouses.code:
/**
 * Townhouses: a terrace of four houses sharing walls along a street, each a
 * different height, each with two windows and a front door. The pointer picks
 * a house by where it stands: its door swings open onto the pavement, and the
 * doors beside it crack open, staggered from it. At rest one door stands ajar,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, fillet, poly, prism, proj, rad, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, W = 30, D = 34, HS = [50, 62, 46, 56], DW = 12, DH = 25, OPEN = 85, FAV = 2;
const X1 = N * W;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-4, -4, 0], [X1 + 4, D + 16, 0], [X1 + 4, -4, 0], [-4, D + 16, 0], [0, 0, 62], [X1, D, 62]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the pavement
  const [pr, pi] = rings(-4, -4, X1 + 4, D + 16, 4, 1.5);
  put(solid(g), prism(P, front, pr, pi, 0, 2));

  const rect = (x0, x1, z0, z1, y) => fillet([P(x0, y, z0), P(x1, y, z0), P(x1, y, z1), P(x0, y, z1)], [0.8, 0.8, 0.8, 0.8], 2);
  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * W, h = HS[k], grp = mk("g", {}, g);
    const [r, ri] = rings(x0 + 0.5, 0, x0 + W - 0.5, D, 2, 1.4);
    put(solid(grp), prism(P, front, r, ri, 2, 2 + h));
    for (const wx of [x0 + 6, x0 + 17]) mk("path", { d: poly(rect(wx, wx + 7, 2 + h - 20, 2 + h - 8, D)), class: "nf lo" }, grp);
    const hx = x0 + (k % 2 ? W - 6 - DW : 6);
    mk("path", { d: poly(rect(hx, hx + DW, 2, 2 + DH, D)), class: "nf lo" }, grp);
    items.push({ k, x0, hx, flip: k % 2 === 1, t: tween(k === FAV ? 40 : 0), last: NaN });
  }
  // doors swing out in front of every facade, so they paint last
  for (const it of items) it.door = mk("path", { class: "sil" }, g);

  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    const th = rad(a), hx = it.flip ? it.hx + DW : it.hx, dir = it.flip ? -1 : 1;
    const ex = hx + dir * DW * Math.cos(th), ey = D + DW * Math.sin(th);
    it.door.setAttribute("d", poly(fillet([P(hx, D, 2), P(ex, ey, 2), P(ex, ey, 2 + DH), P(hx, D, 2 + DH)], [0.8, 0.8, 0.8, 0.8], 2)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.t, now)); if (!tdone(it.t, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x0 + W / 2, D / 2, 2 + HS[it.k] / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), v = a < 0 ? (k === FAV ? 40 : 0) : dd === 0 ? OPEN : dd === 1 ? 30 : 0;
      tset(it.t, v, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.door.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "no " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

