modelhouse.code:
/**
 * Model house: an architect's model on a board, a box house with a door and
 * windows under a pitched roof, an inside wall drawn across its open top. The
 * pointer near the model lifts the roof off to show the plan: the closer, the
 * higher, on a spring. At rest the roof sits a little raised, bright. The
 * slider is the highest lift.
 *
 * The pattern: one part answering the pointer's distance (terrain).
 */
const {
  Cam, clamp, fit, facing, fillet, open, poly, prism, proj, rings, seg, spring, stepS, unproj, hull,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = 0, X1 = 70, Y0 = 0, Y1 = 46, H = 34, RH = 22, E = 4, REST = 5, RAD = 90;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let top = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-14, -14, 0], [X1 + 14, Y1 + 14, 0], [X1 + 14, -14, 0], [-14, Y1 + 14, 0], [X0, (Y0 + Y1) / 2, H + 40 + RH], [X1, (Y0 + Y1) / 2, H + 40 + RH]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-14, -14, X1 + 14, Y1 + 14, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, 3));
  const [hr, hi] = rings(X0, Y0, X1, Y1, 2, 1.4);
  put(solid(g), prism(P, front, hr, hi, 3, 3 + H));
  // the plan: an inside wall across the open top
  mk("path", { d: seg(P(28, Y0 + 1.4, 3 + H), P(28, Y1 - 1.4, 3 + H)) + seg(P(28, 26, 3 + H), P(X1 - 1.4, 26, 3 + H)), class: "nf lo" }, g);
  const rect = (pts) => poly(fillet(pts, [0.8, 0.8, 0.8, 0.8], 2));
  // door and windows on the +y face, the one facing the viewer
  mk("path", { d: rect([P(44, Y1, 3), P(54, Y1, 3), P(54, Y1, 23), P(44, Y1, 23)]), class: "nf lo" }, g);
  for (const wx of [10, 26]) mk("path", { d: rect([P(wx, Y1, 16), P(wx + 9, Y1, 16), P(wx + 9, Y1, 26), P(wx, Y1, 26)]), class: "nf lo" }, g);
  mk("path", { d: rect([P(X1, 16, 14), P(X1, 30, 14), P(X1, 30, 25), P(X1, 16, 25)]), class: "nf lo" }, g);

  const roof = mk("path", { class: "sil hi" }, g), ridge = mk("path", { class: "nf lo" }, g);
  const sp = spring(REST);
  let last = NaN;
  const ym = (Y0 + Y1) / 2;
  function draw(z) {
    if (z === last) return;
    last = z;
    const b = 3 + H + z, a = [X0 - E, Y0 - E, b], c = [X1 + E, Y0 - E, b], d = [X1 + E, Y1 + E, b], e = [X0 - E, Y1 + E, b];
    const r0 = [X0 - E, ym, b + RH], r1 = [X1 + E, ym, b + RH];
    const pts = [a, c, d, e, r0, r1].map((q) => P(...q));
    roof.setAttribute("d", poly(hull(pts)));
    ridge.setAttribute("d", seg(P(...r0), P(...r1)) + open([P(...d), P(...r1)]) + seg(P(...c), P(...r1)));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    const d = Math.hypot(x - (X0 + X1) / 2, y - ym);
    sp.t = d > RAD ? REST : clamp(REST + (top - REST) * (1 - d / RAD) * 1.4, REST, top);
    read.textContent = d > RAD ? "rest" : "lift " + Math.round(sp.t);
    B.wake();
  }
  function leave() { sp.t = REST; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  draw(REST);
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { top = v; }, destroy: bag.dispose };
}

hairline({
  name: "modelhouse",
  means: "An architect's model house on a board: the pointer's nearness lifts the pitched roof off to show the plan inside.",
  rules: [1, 3, 5, 8],
  range: [20, 36, 40],
  tour: [[84, 229], [200, 235], [211, 293], null],
  mount,
});

cooler.code:
/**
 * Cooler: a cool box with its lid stood open at the back and a row of cans
 * on ice inside. The pointer picks a can by where it stands: it lifts out of
 * the box, bright, and the cans beside it rise a little, staggered from it.
 * At rest one can stands half out. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, W = 104, D = 52, H = 40, CR = 8, STEP = 22, LIFT = 40, FAV = 3;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, -4, 0], [W, D, 0], [W, -4, H + D], [0, -4, H + D], [0, D, 0], [W / 2, D / 2, H + 18 + LIFT]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the lid, stood open on its back hinge
  const [lr, li] = rings(-1, -5, W + 1, -1, 1.5, 0.8);
  const lid = put(solid(g), prism(P, front, lr, li, H, H + D - 6));
  mk("path", { d: seg(P(10, -1, H + D - 14), P(W - 10, -1, H + D - 14)), class: "lo nf" }, g);
  // the body and its opening
  const [br, bi] = rings(0, 0, W, D, 8, 2);
  put(solid(g), prism(P, front, br, bi, 0, H));
  const [or] = rings(6, 6, W - 6, D - 6, 5, 1);
  mk("path", { d: poly(ringAt(P, or, H)), class: "nf lo" }, g);
  // a handle on the near end, a drain on the front
  mk("path", { d: seg(P(W, 16, H - 8), P(W, D - 16, H - 8)), class: "nf" }, g);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 19 + k * STEP, y = D / 2 + (k % 2 ? 3 : -3), grp = mk("g", {}, g);
    const s = solid(grp), tab = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, y, s, tab, z: tween(k === FAV ? LIFT * 0.45 : (k === 0 ? 5 : 2)), last: NaN });
  }
  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const top = H + 6 + lift;
    put(it.s, prism(P, front, disc(it.x, it.y, CR), disc(it.x, it.y, CR - 2), H, top));
    it.tab.setAttribute("d", poly(hull(ringAt(P, disc(it.x - 3, it.y, 2, 10), top))));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, H));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 22 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.45 : (k === 0 ? 5 : 2)) : dd === 0 ? LIFT : dd === 1 ? 12 : 1;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "can " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "cooler",
  means: "A cool box with its lid open: the can under the pointer lifts out of the ice, and the cans beside it rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[160, 156], [180, 173], [235, 201], null],
  mount,
});

lockercubbies.code:
/**
 * Cubbies: a classroom cubby unit, four open bays in a row, each with a bag
 * tucked in and a hook on the rail above. The pointer picks a bay by where it
 * stands: its bag slides out toward the viewer, and the bags beside it ease
 * out a little, staggered from it. At rest the bags sit at uneven depths and
 * one is pulled out, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, fillet, poly, open, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, seg, circ,
} = HL;

const N = 4, BAY = 27, D = 24, H = 36, W = N * BAY + 4, OUT = 20, FAV = 2;
const REST = [5, 9, 13, 6];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[0, 0, 0], [W, D + OUT + 2, 0], [W, 0, H + 10], [0, D + OUT + 2, 0], [0, 0, H + 10], [W, D, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // hook rail along the back top, painted behind the unit's top
  const [rr, ri] = rings(2, 0, W - 2, 3, 1.2, 0.6);
  put(solid(g), prism(P, front, rr, ri, H, H + 8));
  const [ur, ui] = rings(0, 3, W, D, 2.5, 1.6);
  put(solid(g), prism(P, front, ur, ui, 0, H));
  const hooks = mk("path", { class: "nf lo" }, g);
  let hd = "";
  for (let k = 0; k < N; k++) {
    const x = 4 + k * BAY + 11.5;
    hd += seg(P(x, 3, H + 5), P(x, 6, H + 5)) + seg(P(x, 6, H + 5), P(x, 6, H + 7.5));
  }
  hooks.setAttribute("d", hd);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = 4 + k * BAY, x1 = x0 + BAY - 4;
    const face = [[x0, 4], [x1, 4], [x1, H - 4], [x0, H - 4]].map(([x, z]) => P(x, D, z));
    mk("path", { d: poly(fillet(face, [2, 2, 2, 2])), class: "nf lo" }, g);
    const grp = mk("g", {}, g), s = solid(grp), strap = mk("path", { class: "nf" }, grp);
    items.push({ k, x0: x0 + 2.5, x1: x1 - 2.5, grp, s, strap, p: tween(REST[k]), last: NaN });
  }

  function draw(it, p) {
    if (p === it.last) return;
    it.last = p;
    const y1 = D + p, [br, bi] = rings(it.x0, D, it.x1, y1, 2.5, 1.4);
    put(it.s, prism(P, front, br, bi, 4, 22));
    const xm = (it.x0 + it.x1) / 2, pts = [];
    for (let i = 0; i <= 8; i++) { const t = (i / 8) * Math.PI; pts.push(P(xm - 6 * Math.cos(t), y1 - Math.min(3, p / 2), 22 + 5 * Math.sin(t))); }
    it.strap.setAttribute("d", open(pts));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.p, now)); if (!tdone(it.p, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P((it.x0 + it.x1) / 2, D, H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), p = a < 0 ? REST[k] : dd === 0 ? OUT : dd === 1 ? 9 : 4;
      tset(it.p, p, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bay " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "lockercubbies",
  means: "A classroom cubby unit with four bays: the bag under the pointer slides out of its bay, and its neighbours ease out a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[123, 155], [196, 206], [254, 221], null],
  mount,
});

teacherdesk.code:
/**
 * Teacher desk: a desk on two legs and a pedestal of three drawers, an apple
 * on its top. The pointer picks a drawer by where it stands: it slides out,
 * and the drawers beside it ease out a little, staggered from it. At rest the
 * drawers stand at uneven depths and the top one is open, bright. The slider
 * is the stagger.
 *
 * The pattern: a stack picked by height (riffle on z).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, seg,
} = HL;

const N = 3, OUT = 22, FAV = 2, FY = 46, X0 = 72, X1 = 106;
const REST = [3, 6, 12], ZS = [[3, 13], [15, 25], [27, 37]];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[0, 0, 0], [110, 0, 44], [0, 50, 44], [110, FY + OUT, 0], [0, 50, 0], [30, 25, 60]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r = 1.5, b = 1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); return prism(P, front, o, i, z0, z1); };
  put(solid(g), box(3, 3, 9, 9, 0, 40));
  put(solid(g), box(3, 41, 9, 47, 0, 40));
  put(solid(g), box(70, 2, 108, FY, 0, 40, 2, 1.2));
  put(solid(g), box(0, 0, 110, 50, 40, 44, 2.5, 1.6));
  // the apple: a round body and a short stem
  const ap = [];
  for (const [r, z] of [[3, 0], [5.5, 1.5], [6, 4], [5, 7], [3, 8.5]]) ap.push(...ringAt(P, disc(28, 22, r), 44 + z));
  mk("path", { d: poly(hull(ap)) }, g);
  mk("path", { d: seg(P(28, 22, 52), P(29, 22, 56)), class: "nf" }, g);

  const items = ZS.map(([z0, z1], k) => {
    const grp = mk("g", {}, g), s = solid(grp), pull = mk("path", { class: "nf" }, grp);
    return { k, z0, z1, s, pull, p: tween(REST[k]), last: NaN };
  });

  function draw(it, p) {
    if (p === it.last) return;
    it.last = p;
    const y1 = FY + p, [o, i] = rings(X0, FY, X1, y1, 1.5, 1);
    put(it.s, prism(P, front, o, i, it.z0, it.z1));
    const zm = (it.z0 + it.z1) / 2 + 1.5, xm = (X0 + X1) / 2;
    it.pull.setAttribute("d", seg(P(xm - 6, y1, zm), P(xm + 6, y1, zm)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.p, now)); if (!tdone(it.p, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P((X0 + X1) / 2, FY, (it.z0 + it.z1) / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][0] - sx) < 50 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), p = a < 0 ? REST[k] : dd === 0 ? OUT : dd === 1 ? 6 : 2;
      tset(it.p, p, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "drawer " + (N - a);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "teacherdesk",
  means: "A teacher's desk with an apple on top and a pedestal of three drawers: the drawer under the pointer slides out.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[204, 184], [204, 205], [204, 227], null],
  mount,
});

syringes.code:
/**
 * Syringes: five syringes standing needle-down in a clinic rack. The pointer
 * picks one by where it stands: it lifts out of its hole, showing the needle,
 * and its neighbours rise a little, staggered from it. At rest one syringe is
 * half drawn, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 22, RT = 14, BR = 5, BH = 30, LIFT = 20, FAV = 2, NL = 11;
const X1 = (N - 1) * STEP;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-12, -12, 0], [X1 + 12, 12, 0], [-12, 12, 0], [X1 + 12, -12, 0], [0, 0, RT + BH + LIFT + 16], [X1, 0, RT + BH + LIFT + 16]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [rr, ri] = rings(-12, -12, X1 + 12, 12, 5, 2);
  put(solid(g), prism(P, front, rr, ri, 0, RT));
  for (let k = 0; k < N; k++) mk("path", { d: poly(ringAt(P, disc(k * STEP, 0, BR + 1.2), RT)), class: "nf lo" }, g);

  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g), x = k * STEP;
    const needle = mk("path", { class: "nf" }, grp), hub = solid(grp), barrel = solid(grp);
    const fill = mk("path", { class: "nf lo" }, grp), flange = solid(grp), rod = solid(grp), thumb = solid(grp);
    const rest = k === FAV ? LIFT * 0.6 : [3, 1, 0, 2, 0][k];
    items.push({ k, x, needle, hub, barrel, fill, flange, rod, thumb, rest, z: tween(rest), last: NaN });
  }
  const cyl = (s, x, r, z0, z1, b = 0.8) => put(s, prism(P, front, disc(x, 0, r), disc(x, 0, Math.max(0.3, r - b)), z0, z1));

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const b = RT + lift, x = it.x;
    it.needle.setAttribute("d", b - 3 > RT ? seg(P(x, 0, b - 3), P(x, 0, Math.max(RT, b - 3 - NL))) : "");
    if (b - 3 > RT) cyl(it.hub, x, 1.8, b - 3, b, 0.5); else put(it.hub, { sil: "", crease: "" });
    cyl(it.barrel, x, BR, b, b + BH);
    it.fill.setAttribute("d", poly(ringAt(P, disc(x, 0, BR - 0.3), b + BH * 0.55)));
    cyl(it.flange, x, BR + 3, b + BH, b + BH + 1.4, 1.2);
    cyl(it.rod, x, 1.4, b + BH + 1.4, b + BH + 10, 0.5);
    cyl(it.thumb, x, 4, b + BH + 10, b + BH + 11.5, 1);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 0, RT + BH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 75 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? it.rest : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.barrel.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "syr " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

