winebarrels.code:
/**
 * Wine casks: four bulging casks lying side by side on two cradle rails,
 * each with its head toward the reader, two hoops and a bung on top. The
 * pointer picks a cask by where it stands: it tips up on its front edge,
 * its back end raised, as a cellar tips a cask to draw the last of it, and
 * the casks beside it tip a little, staggered from it. At rest one cask is
 * already tipped, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), each part rotated about
 * its own pivot and redrawn as a hull.
 */
const {
  Cam, fit, hull, open, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 36, R = 13, RM = 16, LEN = 44, RZ = 5, TIP = 26, FAV = 2;
const REST = [3, 0, 16, 5];
const X1 = (N - 1) * STEP + 2 * RM;
const VIEW = [0.612, 0.612, 0.5];
const rOf = (yy) => R + (RM - R) * Math.sin((Math.PI * yy) / LEN);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  const ext = [[-4, -4, 0], [X1 + 4, LEN + 4, 0], [X1 + 4, -4, 0], [-4, LEN + 4, 0]];
  for (const x of [RM, X1 - RM]) ext.push([x, 4, RZ + LEN * Math.sin((TIP * Math.PI) / 180) + 2 * RM]);
  fit(C, ext, 200, 170);
  const P = proj(C);
  const g = mk("g", {}, svg);
  for (const ry of [7, LEN - 9]) {
    const [a, b] = rings(-4, ry - 3, X1 + 4, ry + 3, 2, 0.8);
    put(solid(g), prism(P, () => true, a, b, 0, RZ));
  }

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = RM + k * STEP, grp = mk("g", {}, g);
    const sil = mk("path", { class: "sil" }, grp), head = mk("path", { class: "nf lo" }, grp);
    const hoops = mk("path", { class: "nf lo" }, grp), bung = mk("path", { class: "nf" }, grp);
    items.push({ k, x, sil, head, hoops, bung, a: tween(REST[k]), last: NaN });
  }

  // a point on the cask at length yy, angle t, radius r, tipped by deg about its front-bottom edge
  function pt(it, yy, t, r, deg) {
    const s = Math.sin((deg * Math.PI) / 180), c = Math.cos((deg * Math.PI) / 180);
    const dy = yy - LEN, dz = RM + r * Math.sin(t);
    return { p: P(it.x + r * Math.cos(t), LEN + dy * c + dz * s, RZ + dz * c - dy * s), n: [Math.cos(t), Math.sin(t) * s, Math.sin(t) * c] };
  }
  const faces = (n) => n[0] * VIEW[0] + n[1] * VIEW[1] + n[2] * VIEW[2] > 0;

  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const all = [], M = 36;
    for (const yy of [0, LEN * 0.2, LEN * 0.5, LEN * 0.8, LEN]) for (let i = 0; i < M; i++) all.push(pt(it, yy, (i / M) * Math.PI * 2, rOf(yy), deg).p);
    it.sil.setAttribute("d", poly(hull(all)));
    const ring = [];
    for (let i = 0; i < M; i++) ring.push(pt(it, LEN, (i / M) * Math.PI * 2, R - 1.2, deg).p);
    it.head.setAttribute("d", poly(ring));
    let d = "";
    for (const yy of [LEN * 0.22, LEN * 0.78]) {
      const arc = [];
      for (let i = 0; i <= 48; i++) { const q = pt(it, yy, (i / 48) * Math.PI * 2, rOf(yy), deg); if (faces(q.n)) arc.push(q.p); else if (arc.length) break; }
      if (arc.length > 1) d += open(arc);
    }
    it.hoops.setAttribute("d", d);
    const b = [];
    for (let i = 0; i < 12; i++) { const t = (i / 12) * Math.PI * 2; const q = pt(it, LEN / 2 + 2.2 * Math.sin(t), Math.PI / 2 + (2.2 * Math.cos(t)) / RM, RM + 0.3, deg); b.push(q.p); }
    it.bung.setAttribute("d", poly(b));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, LEN / 2, RZ + RM));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), to = a < 0 ? REST[k] : dd === 0 ? TIP : dd === 1 ? 6 : 0;
      tset(it.a, to, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "cask " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "winebarrels",
  means: "Four casks on cradle rails: the cask under the pointer tips up on its front edge, and its neighbours tip a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[127, 131], [221, 181], [275, 207], null],
  mount,
});

sushiconveyor.code:
/**
 * Sushi conveyor: a stadium-shaped counter with its belt track inset round
 * the edge, eight small plates riding the loop with a piece on each, spaced
 * unevenly where one has been taken. The pointer picks the plate under it,
 * read on the belt's top: it lifts off the belt, and the plates beside it
 * along the loop rise a little, staggered from it. At rest one plate is
 * held up, bright. The slider is the stagger.
 *
 * The pattern: picked on a fixed plane (terrain), stagger along the loop.
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, rrect, ringAt, open, poly, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 170, D = 74, RR = 37, BZ = 7, PRAD = 9, LIFT = 22, FAV = 2;
const SLOTS = [0, 1, 2, 3, 5, 6, 7, 8];
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

// a point at fraction f round the track's centreline
function along(f) {
  const r = RR - 11, L = W - 2 * RR, per = 2 * L + 2 * Math.PI * r;
  let s = (((f % 1) + 1) % 1) * per;
  if (s < L) return [RR + s, D / 2 + r];
  s -= L;
  if (s < Math.PI * r) { const a = Math.PI / 2 - s / r; return [W - RR + r * Math.cos(a), D / 2 + r * Math.sin(a)]; }
  s -= Math.PI * r;
  if (s < L) return [W - RR - s, D / 2 - r];
  s -= L;
  const a = -Math.PI / 2 - s / r;
  return [RR + r * Math.cos(a), D / 2 + r * Math.sin(a)];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.85);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [W / 2, 0, BZ + LIFT + 12], [0, D / 2, BZ + LIFT + 12]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [o, oi] = rings(0, 0, W, D, RR, 1.6);
  put(solid(g), prism(P, front, o, oi, 0, BZ));
  mk("path", { d: open(ringAt(P, rrect(20, 20, W - 20, D - 20, RR - 20, 10), BZ).concat([P(20, D / 2, BZ)])), class: "nf lo" }, g);

  const items = SLOTS.map((s, k) => {
    const [x, y] = along(s / 9 + 0.02);
    return { k, x, y, z: tween(k === FAV ? LIFT * 0.7 : k % 3 === 1 ? 2 : 0), last: NaN, roll: k % 2 === 0 };
  });
  const order = items.slice().sort((a, b) => a.x + a.y - (b.x + b.y));
  for (const it of order) {
    it.grp = mk("g", {}, g);
    mk("path", { d: poly(ringAt(P, disc(it.x, it.y, PRAD, 28), BZ)), class: "nf dash" }, it.grp);
    it.plate = solid(it.grp); it.plate.sil.classList.add("sil");
    it.dish = solid(it.grp);
  }

  function draw(it, z) {
    if (z === it.last) return;
    it.last = z;
    const z0 = BZ + 0.2 + z;
    put(it.plate, prism(P, front, disc(it.x, it.y, PRAD), disc(it.x, it.y, PRAD - 2.4), z0, z0 + 1.6));
    if (it.roll) put(it.dish, prism(P, front, disc(it.x, it.y, 4.6, 24), disc(it.x, it.y, 3.2, 24), z0 + 1.6, z0 + 6));
    else { const [a, b] = rings(it.x - 6, it.y - 3, it.x + 6, it.y + 3, 3, 1); put(it.dish, prism(P, front, a, b, z0 + 1.6, z0 + 5)); }
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, BZ);
    let best = -1, bd = Infinity;
    items.forEach((it, k) => { const dd = Math.hypot(it.x - wx, it.y - wy); if (dd < bd) { bd = dd; best = k; } });
    return bd < PRAD + 4 ? best : -1;
  }

  let act = -2;
  const ring = (a, b) => { const d = Math.abs(a - b); return Math.min(d, items.length - d); };
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = ring(k, a), to = a < 0 ? (k === FAV ? LIFT * 0.7 : k % 3 === 1 ? 2 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, to, now, from < 0 ? 0 : ring(k, from) * stag);
      it.plate.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    for (const it of order) g.appendChild(it.grp);
    g.appendChild(items[a < 0 ? FAV : a].grp);
    read.textContent = a < 0 ? "rest" : "plate " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "sushiconveyor",
  means: "A loop of plates on a sushi belt: the plate under the pointer lifts off the belt, and the plates beside it rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[112, 170], [165, 196], [261, 177], null],
  mount,
});

cradle.code:
/**
 * Cradle: a basket on two curved rockers. The pointer's place across the
 * floor tips the cradle toward it, rolling on its rockers; leaving lets it
 * settle back to a slight rest lean. The basket's rim is the bright mark.
 * The slider is how far it may rock.
 *
 * The pattern: one object answering where (a spring).
 */
const {
  Cam, fit, hull, open, poly, proj, rrect, clamp, rad, spring, stepS, unproj,
  disposer, mk, pointer, register,
} = HL;

const L = 84, W = 40, Z0 = 16, Z1 = 40, R = 62, REST = 5;
const base = rrect(0, -W / 2, L, W / 2, 7, 4), inner = rrect(2.5, -W / 2 + 2.5, L - 2.5, W / 2 - 2.5, 5, 4);
const arc = [];
for (let i = 0; i <= 16; i++) { const a = rad(-36 + (72 * i) / 16); arc.push([R * Math.sin(a), R - R * Math.cos(a)]); }
arc.push([arc[16][0] - 4, Z0], [arc[0][0] + 4, Z0]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.4);
  const mx = Math.max(...arc.map((q) => Math.abs(q[0]))) + 16;
  fit(C, [[0, -mx, 0], [L, mx, 0], [0, -mx, Z1 + 6], [L, mx, Z1 + 6], [L, -mx, Z1], [0, mx, 0]], 200, 170);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const tilt = spring(REST);
  const xf = (x, y, z, th) => {
    const c = Math.cos(th), s = Math.sin(th), dz = z - R;
    return P(x, y * c - dz * s - R * th, y * s + dz * c + R);
  };
  const rockers = [6, L - 10].map(() => mk("path", { class: "sil" }, g));
  const body = mk("path", { class: "sil hi" }, g);
  const rim = mk("path", { class: "nf lo" }, g);
  const bed = mk("path", { class: "nf lo" }, g);
  let last = NaN;

  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const th = rad(deg);
    [6, L - 10].forEach((x, i) => {
      const pts = [];
      for (const [y, z] of arc) pts.push(xf(x, y, z, th), xf(x + 4, y, z, th));
      rockers[i].setAttribute("d", poly(hull(pts)));
    });
    const ring = (rg, z) => rg.map((q) => xf(q.u, q.v, z, th));
    body.setAttribute("d", poly(hull(ring(base, Z0).concat(ring(base, Z1)))));
    rim.setAttribute("d", poly(ring(inner, Z1)));
    bed.setAttribute("d", open(ring(rrect(6, -W / 2 + 6, L - 6, W / 2 - 6, 4, 4), Z1 - 9)));
  }

  const B = register(stage, (dt) => {
    const m = stepS(tilt, dt);
    draw(Math.round(tilt.x * 100) / 100);
    return m;
  });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { tilt.t = REST; read.textContent = "rest"; B.wake(); return; }
    const [, y] = unproj(C, p[0], p[1], 0);
    const d = clamp(y / 70, -1, 1) * reach;
    tilt.t = d;
    read.textContent = (d >= 0 ? "+" : "") + Math.round(d) + "°";
    B.wake();
  }
  draw(REST);
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "cradle",
  means: "A cradle on two curved rockers: it rolls toward the pointer's side of the floor and settles back to a slight lean.",
  rules: [3, 5, 8, 9],
  range: [6, 14, 20],
  tour: [[149, 160], [237, 237], [200, 141], null],
  mount,
});

windowbox.code:
/**
 * Window box: a planter on a sill under a window, five flowers in a row.
 * The pointer picks a flower by where it stands: it grows up toward the
 * light, its neighbours a little, staggered from it. At rest one flower
 * stands tall, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, fillet, hull, poly, prism, proj, rings, ringAt, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 22, BX = 6 + (N - 1) * STEP + 12, BH = 18, ST = 14, GROW = 26, FAV = 3;
const RESTH = [4, 0, 6, 10, 2];
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.2);
  const top = BH + ST + GROW + 14 + 8;
  fit(C, [[-4, -6, 0], [BX + 4, 18, 0], [-4, -6, top + 8], [BX + 4, -6, top + 8], [BX + 4, 18, 0]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the window behind: a frame on the wall plane, with its mullion
  const fr = fillet([P(-2, -6, 6), P(BX + 2, -6, 6), P(BX + 2, -6, top + 8), P(-2, -6, top + 8)], [3, 3, 3, 3]);
  mk("path", { d: poly(fr) }, g);
  const pane = fillet([P(4, -6, BH + 2), P(BX - 4, -6, BH + 2), P(BX - 4, -6, top + 2), P(4, -6, top + 2)], [2, 2, 2, 2]);
  mk("path", { d: poly(pane) + seg(P(BX / 2, -6, BH + 2), P(BX / 2, -6, top + 2)), class: "nf lo" }, g);
  const [sr, si] = rings(-4, -6, BX + 4, 18, 3, 1.2);
  put(solid(g), prism(P, front, sr, si, 0, 4));

  const flowers = [];
  for (let k = 0; k < N; k++) {
    const x = 12 + k * STEP, y = 4, grp = mk("g", {}, g);
    const stem = mk("path", { class: "nf lo" }, grp), head = mk("path", { class: "sil" }, grp), eye = mk("path", { class: "nf lo" }, grp);
    flowers.push({ k, x, y, grp, stem, head, eye, h: tween(RESTH[k]), last: NaN });
  }
  const [br, bi] = rings(0, -2, BX, 12, 3, 1.4);
  put(solid(g), prism(P, front, br, bi, 4, BH));

  function draw(f, h) {
    if (h === f.last) return;
    f.last = h;
    const zt = BH + ST + h;
    f.stem.setAttribute("d", seg(P(f.x, f.y, BH - 1), P(f.x, f.y, zt)) + seg(P(f.x, f.y, zt - 8), P(f.x + 4, f.y, zt - 4)));
    f.head.setAttribute("d", poly(hull(ringAt(P, disc(f.x, f.y, 7), zt).concat(ringAt(P, disc(f.x, f.y, 7), zt + 2.5)))));
    f.eye.setAttribute("d", poly(ringAt(P, disc(f.x, f.y, 2.5, 12), zt + 2.5)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const f of flowers) { draw(f, tval(f.h, now)); if (!tdone(f.h, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = flowers.map((f) => P(f.x, f.y, BH + ST / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    flowers.forEach((f, k) => {
      const dd = Math.abs(k - a), h = a < 0 ? RESTH[k] : dd === 0 ? GROW : dd === 1 ? 8 : 0;
      tset(f.h, h, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      f.head.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bloom " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "windowbox",
  means: "A window box of five flowers on a sill: the flower under the pointer grows toward the light, its neighbours a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[121, 142], [155, 159], [258, 211], null],
  mount,
});

meetingtable.code:
/**
 * Meeting table: a long table with three chairs down each side, tucked in at
 * uneven depths. The pointer picks a chair by where it stands: that chair
 * slides out from the table, bright, and its neighbours ease out a little,
 * staggered from it. At rest one chair is pulled out. The slider is the stagger.
 *
 * The pattern: one of many, picked on the ground (terrain).
 */
const {
  Cam, fit, facing, prism, proj, rings, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const TL = 132, TW = 54, TZ = 26, SH = 9, SZ = 15, BZ = 36, OUT = 20, FAV = 4;
const XS = [26, 66, 106];
const REST = [3, 6, 2, 5, OUT * 0.8, 1];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.85);
  fit(C, [[0, -SH * 2 - OUT - 4, 0], [TL, -SH * 2 - OUT - 4, BZ], [0, TW + SH * 2 + OUT + 4, 0], [TL, TW + SH * 2 + OUT + 4, 0], [TL, TW + OUT, BZ]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const far = mk("g", {}, g), mid = mk("g", {}, g), near = mk("g", {}, g);

  const chairs = [];
  for (let k = 0; k < 6; k++) {
    const side = k < 3 ? -1 : 1, x = XS[k % 3];
    const grp = mk("g", {}, side < 0 ? far : near);
    const a = solid(grp), b = solid(grp), c = solid(grp);
    // far chairs: back then legs then seat; near: legs, seat, back
    const parts = side < 0 ? { back: a, leg: b, seat: c } : { leg: a, seat: b, back: c };
    chairs.push({ k, side, x, ...parts, z: tween(REST[k]), last: NaN });
  }
  // the table: a pedestal and a thick top
  const [pr, pi] = rings(TL / 2 - 30, TW / 2 - 6, TL / 2 + 30, TW / 2 + 6, 5, 1.2);
  put(solid(mid), prism(P, front, pr, pi, 0, TZ - 3));
  const [tr, ti] = rings(0, 0, TL, TW, 12, 2);
  put(solid(mid), prism(P, front, tr, ti, TZ - 3, TZ));

  function draw(ch, out) {
    if (out === ch.last) return;
    ch.last = out;
    const yc = ch.side < 0 ? -SH + 6 - out : TW + SH - 6 + out;
    const x0 = ch.x - SH, x1 = ch.x + SH, y0 = yc - SH, y1 = yc + SH;
    const [lr, li] = rings(ch.x - 2, yc - 2, ch.x + 2, yc + 2, 2, 0.6);
    put(ch.leg, prism(P, front, lr, li, 0, SZ - 3));
    const [sr, si] = rings(x0, y0, x1, y1, 4, 1.4);
    put(ch.seat, prism(P, front, sr, si, SZ - 3, SZ));
    const by = ch.side < 0 ? y0 : y1 - 2.4;
    const [br, bi] = rings(x0 + 1, by, x1 - 1, by + 2.4, 1.2, 0.5);
    put(ch.back, prism(P, front, br, bi, SZ, BZ));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const ch of chairs) { draw(ch, tval(ch.z, now)); if (!tdone(ch.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, SZ);
    let best = -1, bd = Infinity;
    chairs.forEach((ch, k) => {
      const yc = ch.side < 0 ? -SH : TW + SH;
      const d = Math.hypot(wx - ch.x, (wy - yc) * 0.8);
      if (d < bd) { bd = d; best = k; }
    });
    return bd < 26 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    chairs.forEach((ch, k) => {
      const same = a >= 0 && chairs[a].side === ch.side, dd = a >= 0 ? Math.abs((k % 3) - (a % 3)) : 0;
      const z = a < 0 ? REST[k] : k === a ? OUT : same && dd === 1 ? 6 : 0;
      tset(ch.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      for (const s of [ch.leg, ch.seat, ch.back]) s.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "seat " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "meetingtable",
  means: "A meeting table with six chairs: the chair under the pointer slides out from the table, and its neighbours ease out a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[274, 104], [222, 78], [183, 203], null],
  mount,
});

phonebooth.code:
/**
 * Phone booth: a quiet office pod on a low plinth, a glass door on its front
 * face. The pointer draws the door open: the closer it comes to the pod, the
 * wider the door swings on its hinge, on a spring. At rest the door stands
 * ajar, bright. The slider is how far the door can open.
 *
 * The pattern: one part answering where the pointer is (spring).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, unproj, clamp, rad, spring, stepS, open,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 46, D = 40, H = 72, PZ = 3, DW = 28, HX = 6, REST = 18;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[-4, -4, 0], [W + 4, -4, 0], [-4, D + 4 + DW, 0], [W + 4, D + DW, 0], [0, 0, H + 4], [W, D, H + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-4, -4, W + 4, D + 4, 5, 1.4);
  put(solid(g), prism(P, front, br, bi, 0, PZ));
  const [pr, pi] = rings(0, 0, W, D, 8, 2);
  put(solid(g), prism(P, front, pr, pi, PZ, H - 4));
  const [rr, ri] = rings(-2, -2, W + 2, D + 2, 9, 1.6);
  put(solid(g), prism(P, front, rr, ri, H - 4, H));
  // the doorway, a dim frame on the front face, and a vent strip on the side
  const fz0 = PZ + 3, fz1 = H - 10;
  mk("path", { d: poly([P(HX, D, fz0), P(HX + DW, D, fz0), P(HX + DW, D, fz1), P(HX, D, fz1)]), class: "nf lo" }, g);
  mk("path", { d: open([P(W, 10, H - 14), P(W, D - 10, H - 14)]), class: "nf lo" }, g);
  const door = mk("path", { class: "sil" }, g), pane = mk("path", { class: "nf lo" }, g), grip = mk("path", { class: "nf" }, g);

  const sp = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const at = (t, z, o = 0) => P(HX + t * c - o * s, D + 0.4 + t * s + o * c, z);
    const pts = [];
    for (const t of [0, DW]) for (const o of [0, 1.6]) for (const z of [fz0, fz1]) pts.push(at(t, z, o));
    door.setAttribute("d", poly(hull(pts)));
    pane.setAttribute("d", poly([at(4, fz0 + 4, 1.6), at(DW - 4, fz0 + 4, 1.6), at(DW - 4, fz1 - 4, 1.6), at(4, fz1 - 4, 1.6)]));
    grip.setAttribute("d", poly(hull([at(DW - 3, 30, 1.6), at(DW - 2, 30, 1.6), at(DW - 3, 44, 1.6), at(DW - 2, 44, 1.6), at(DW - 3, 30, 3.2), at(DW - 3, 44, 3.2)])));
  }

  const B = register(stage, (dt) => {
    const m = stepS(sp, dt);
    draw(sp.x);
    return m;
  });
  bag.add(B.unregister);

  function aim(a, on) {
    sp.t = a;
    door.classList.toggle("hi", true);
    read.textContent = on ? "door " + Math.round(a) + "°" : "rest";
    B.wake();
  }
  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, 0);
    const d = Math.hypot(wx - (HX + DW / 2), wy - (D + DW / 2));
    if (d > 90) return aim(REST, false);
    aim(clamp(maxA * (1 - (d - 12) / 78), 4, maxA), true);
  }
  aim(REST, false);
  bag.add(pointer(stage, { move, leave: () => aim(REST, false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "phonebooth",
  means: "A quiet office pod: the closer the pointer comes, the wider its glass door swings open on the hinge.",
  rules: [1, 3, 5, 8],
  range: [40, 95, 130],
  tour: [[218, 127], [190, 215], [159, 258], null],
  mount,
});

playtent.code:
/**
 * Play tent: a kids' teepee on a play mat, poles crossing above its peak,
 * a door cut into its front face. The pointer's distance to the tent opens
 * the door flap: it swings out on its hinge edge the nearer the hand comes.
 * At rest the flap stands a little open, bright. The slider is the reach.
 *
 * The pattern: one part answering a continuous value (spring).
 */
const {
  Cam, fit, facing, hull, open, poly, proj, rrect, ringAt, run, seg, spring, stepS, unproj, clamp, rings, prism,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 60, H = 70, T0 = 26, T1 = 34, REST = 0.15;
const yAt = (z) => W - (W - T1) * z / H;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-14, -14, 0], [W + 14, W + 14, 0], [W + 14, -14, 0], [-14, W + 14, 0], [30, 30, H + 18]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [mr, mi] = rings(-14, -14, W + 14, W + 14, 8, 2);
  put(solid(g), prism(P, front, mr, mi, 0, 1.5));

  // poles, behind the cover where they cross above it
  const poles = mk("path", { class: "nf" }, g);
  let pd = "";
  for (const [x, y] of [[0, 0], [W, 0], [0, W], [W, W]]) {
    const a = [x, y, 1.5], b = [30 + (30 - x) * -0.32, 30 + (30 - y) * -0.32, H + 16];
    const tx = T0 + (x ? T1 - T0 : 0), ty = T0 + (y ? T1 - T0 : 0);
    pd += seg(P(tx, ty, H), P(b[0], b[1], b[2]));
  }
  poles.setAttribute("d", pd);

  // the cover: a tapered solid, foot to top
  const foot = rrect(0, 0, W, W, 8, 4), top = rrect(T0, T0, T1, T1, 2, 4), inner = rrect(T0 + 1.2, T0 + 1.2, T1 - 1.2, T1 - 1.2, 1, 4);
  put(solid(g), {
    sil: poly(hull(ringAt(P, foot, 1.5).concat(ringAt(P, top, H)))),
    crease: open(ringAt(P, run(inner, front), H)),
  });

  // the doorway on the +y face, then its flap hinged on the right edge
  const L = [12, W, 1.5], R = [48, W, 1.5], A = [30, yAt(52), 52];
  mk("path", { d: poly([P(...L), P(...R), P(...A)]), class: "nf lo" }, g);
  const flap = mk("path", { class: "sil hi" }, g);

  const ax = [R[0] - A[0], R[1] - A[1], R[2] - A[2]], al = Math.hypot(...ax), u = ax.map((v) => v / al);
  function rot(p, th) {
    const v = [p[0] - A[0], p[1] - A[1], p[2] - A[2]], c = Math.cos(th), s = Math.sin(th);
    const d = u[0] * v[0] + u[1] * v[1] + u[2] * v[2];
    const cx = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
    return [0, 1, 2].map((i) => A[i] + v[i] * c + cx[i] * s + u[i] * d * (1 - c));
  }
  const sign = rot(L, 0.3)[1] > rot(L, -0.3)[1] ? 1 : -1;

  const open_ = spring(REST);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const F = rot(L, sign * t * 2.4);
    flap.setAttribute("d", poly([P(...F), P(...R), P(...A)]));
  }
  const B = register(stage, (dt) => { const m = stepS(open_, dt); draw(open_.x); return m; });
  bag.add(B.unregister);
  draw(REST);

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0), d = Math.hypot(x - 30, y - 30);
    const t = clamp(1 - (d - 20) / (40 + reach), 0.08, 1);
    open_.t = t;
    read.textContent = "door " + Math.round(t * 100);
    B.wake();
  }
  bag.add(pointer(stage, { move, leave: () => { open_.t = REST; read.textContent = "rest"; B.wake(); } }));
  read.textContent = "rest";
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

