parkingmeters.code:
/**
 * Parking meters: four meters in a row on a kerb, each a post with a rounded
 * head and a paddle flag on its face. The pointer picks a meter by where it is
 * along the row: its flag swings up to paid, the neighbours' flags rise a
 * little after it. At rest the flags hang at uneven angles, one bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is the nearest rest head
 * along screen x.
 */
const {
  Cam, clamp, facing, fillet, fit, poly, prism, proj, rings, ringAt, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 20, HZ0 = 30, HZ1 = 50, KZ = 3, YF = 4.3, PZ = 35;
const REST = [208, 192, 150, 214], FAV = 2, UP = 90;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.1);
  const XN = (N - 1) * STEP;
  fit(C, [[-12, -9, 0], [XN + 10, 9, 0], [XN + 10, -9, 0], [-12, 9, 0], [-10, 0, HZ1], [XN + 6, 0, HZ1]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the kerb: one long low slab the meters stand on
  const [kr, ki] = rings(-12, -9, XN + 10, 9, 3, 1.2);
  put(solid(g), prism(P, front, kr, ki, 0, KZ));

  const meters = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP;
    const [pr, pi] = rings(x - 1.8, -1.8, x + 1.8, 1.8, 1.8, 0.6);
    put(solid(g), prism(P, front, pr, pi, KZ, HZ0 + 1));
    const [hr, hi] = rings(x - 6, -4, x + 6, 4, 4, 1.2);
    const head = solid(g);
    put(head, prism(P, front, hr, hi, HZ0, HZ1));
    // the coin slot on top and the window on the face
    mk("path", { class: "nf lo", d: poly(ringAt(P, rrect(x - 0.6, -2.4, x + 0.6, 2.4, 0.5, 3), HZ1)) +
      poly(rrect(x - 4, 40, x + 4, 46, 1.5, 4).map((s) => P(s.u, 4.05, s.v))) }, head.g);
    const flag = mk("path", { class: "sil" }, g);
    meters.push({ x, flag, a: tween(REST[k]), last: NaN });
  }

  // the paddle in the head's face plane, turned about its pivot by a degrees
  const PAD = fillet([[-1.4, -1], [7, -1], [7, -3], [14, -3], [14, 3], [7, 3], [7, 1], [-1.4, 1]],
    [0.8, 0.3, 1, 1.6, 1.6, 1, 0.3, 0.8], 4);
  function draw(m, a) {
    if (a === m.last) return;
    m.last = a;
    const c = Math.cos((a * Math.PI) / 180), s = Math.sin((a * Math.PI) / 180), px = m.x + 3;
    m.flag.setAttribute("d", poly(PAD.map(([u, w]) => P(px + u * c - w * s, YF, PZ + u * s + w * c))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    meters.forEach((m) => { draw(m, tval(m.a, now)); if (!tdone(m.a, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest rest head along screen x, within the row's band
  const heads = meters.map((m) => P(m.x, 0, (HZ0 + HZ1) / 2));
  function hit([sx, sy]) {
    let best = -1, bd = 1e9;
    heads.forEach(([hx, hy], k) => { const d = Math.abs(sx - hx); if (d < bd && Math.abs(sy - hy) < 90) { bd = d; best = k; } });
    return bd < 40 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    meters.forEach((m, k) => {
      const t = a < 0 ? REST[k] : k === a ? UP : clamp(REST[k] - 36 / Math.abs(k - a), 120, 214);
      tset(m.a, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      m.flag.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bay " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "parkingmeters",
  means: "A row of parking meters on a kerb: the flag of the meter under the pointer swings up to paid, its neighbours lift a little after.",
  rules: [1, 2, 4, 5],
  range: [0, 45, 90],
  tour: [[136, 88], [224, 132], [268, 154], null],
  mount,
});

spoolrack.code:
/**
 * Spool rack: a board with a row of five pegs, a thread spool on each. The
 * pointer picks a spool by where it is along the row: it lifts up its peg,
 * the neighbours rise a little after it. At rest the spools sit at uneven
 * heights on their pegs, one bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is the nearest rest
 * spool along screen x.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 13, BZ = 3, PEG = 26, LIFT = 18;
const REST = [2, 0, 5, 1, 3], FAV = 2, FLR = 5.4, COR = 3.2, SH = 12;

function shift(ring, x) { return ring.map((s) => ({ ...s, u: s.u + x })); }

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.7);
  const XN = (N - 1) * STEP;
  fit(C, [[-9, -9, 0], [XN + 9, 9, 0], [XN + 9, -9, 0], [-9, 9, 0], [0, 0, BZ + SH + LIFT + 6], [XN, 0, BZ + SH + LIFT + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [br, bi] = rings(-9, -9, XN + 9, 9, 3, 1.2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));

  const F = circ(FLR, 20), FI = circ(FLR - 0.8, 20), K = circ(COR, 16), KI = circ(COR - 0.6, 16);
  const pk = circ(0.8, 10), pki = circ(0.5, 10);
  const spools = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP;
    put(solid(g), prism(P, front, shift(pk, x), shift(pki, x), BZ, BZ + PEG));
    const lo = solid(g), core = solid(g), hi = solid(g);
    spools.push({ x, lo, core, hi, z: tween(REST[k]), last: NaN });
  }
  function draw(s, lift) {
    if (lift === s.last) return;
    s.last = lift;
    const z = BZ + lift;
    put(s.lo, prism(P, front, shift(F, s.x), shift(FI, s.x), z, z + 1.4));
    put(s.core, prism(P, front, shift(K, s.x), shift(KI, s.x), z + 1.4, z + SH - 1.4));
    put(s.hi, prism(P, front, shift(F, s.x), shift(FI, s.x), z + SH - 1.4, z + SH));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    spools.forEach((s) => { draw(s, tval(s.z, now)); if (!tdone(s.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  const cen = spools.map((s) => P(s.x, 0, BZ + SH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = 1e9;
    cen.forEach(([hx, hy], k) => { const d = Math.abs(sx - hx); if (d < bd && Math.abs(sy - hy) < 80) { bd = d; best = k; } });
    return bd < 26 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    spools.forEach((s, k) => {
      const t = a < 0 ? REST[k] : k === a ? LIFT : Math.max(0, 6 - 2 * Math.abs(k - a));
      tset(s.z, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      [s.lo, s.core, s.hi].forEach((p) => p.sil.classList.toggle("hi", on));
    });
    read.textContent = a < 0 ? "rest" : "peg " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "spoolrack",
  means: "A rack of thread spools on pegs: the spool under the pointer lifts up its peg, its neighbours rise a little after it.",
  rules: [1, 2, 4, 5],
  range: [0, 45, 90],
  tour: [[132, 151], [200, 184], [268, 219], null],
  mount,
});

cementbags.code:
/**
 * Cement bags: two layers of bags on a site pallet. The pointer picks a bag
 * in the top layer by where it stands: that bag is hoisted off the stack, and
 * the bags beside it shift up a little, staggered from it. At rest one bag is
 * half-lifted, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, BW = 24, GAP = 2, STEP = BW + GAP, BD = 40, BH = 9, PH = 6, LIFT = 26, FAV = 2;
const X1 = N * STEP - GAP;
const REST = [1.5, 0, LIFT * 0.6, 3];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-4, -4, 0], [X1 + 4, BD + 4, 0], [X1 + 4, -4, 0], [-4, BD + 4, 0], [0, 0, PH + 2 * BH + LIFT], [X1, BD, PH + 2 * BH + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the pallet: a deck on three runners
  for (const y of [-2, BD / 2 - 3, BD - 4]) {
    const [r, i] = rings(-2, y, X1 + 2, y + 6, 1.2, 0.8);
    put(solid(g), prism(P, front, r, i, 0, PH - 2));
  }
  const [dr, di] = rings(-4, -4, X1 + 4, BD + 4, 2, 1.2);
  put(solid(g), prism(P, front, dr, di, PH - 2, PH));

  // bottom layer: laid crosswise, two long bags
  for (let j = 0; j < 2; j++) {
    const y0 = j * (BD / 2 + 1) - 1, y1 = y0 + BD / 2 - 1;
    const [r, i] = rings(0, y0, X1, y1, 6, 2);
    put(solid(g), prism(P, front, r, i, PH, PH + BH));
  }

  // top layer: the bags that lift
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, grp = mk("g", {}, g), s = solid(grp);
    const [r, i] = rings(x, 0, x + BW, BD, 6, 2);
    const [vr, vi] = rings(x + 4, BD - 7, x + BW - 4, BD - 4, 1.2, 0.5);
    const valve = solid(grp);
    items.push({ k, x, s, r, i, vr, vi, valve, z: tween(REST[k]), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = PH + BH + lift;
    put(it.s, prism(P, front, it.r, it.i, z0, z0 + BH));
    put(it.valve, prism(P, front, it.vr, it.vi, z0 + BH, z0 + BH + 0.8));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + BW / 2, BD / 2, PH + BH * 1.5));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 28 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? REST[k] : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bag " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "cementbags",
  means: "Cement bags stacked on a pallet: the top bag under the pointer is hoisted off, and the bags beside it shift up a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[122, 119], [218, 148], [273, 194], null],
  mount,
});

cattlegate.code:
/**
 * Cattle gate: a five-rail farm gate hung on a stout post, latching to a
 * second post across a strip of ground. The gate swings on its hinge to
 * point toward the pointer, held to a quarter turn. At rest it hangs ajar
 * with its top rail bright. The slider is how far it may open.
 *
 * The pattern: one part turning to face the pointer (spring).
 */
const {
  Cam, circ, clamp, fit, facing, poly, prism, proj, rad, rings, rrect, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const LEN = 64, PH = 30, REST = 24;
const RAILS = [5, 10.5, 16, 21.5, 27];
const disc = (x, y, r, n = 16) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const turn = (ring, a) => { const c = Math.cos(a), s = Math.sin(a); return ring.map((q) => ({ u: q.v * s + q.u * c, v: q.v * c - q.u * s, nu: q.nv * s + q.nu * c, nv: q.nv * c - q.nu * s })); };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[-14, -10, 0], [LEN * 0.9, LEN * 0.4, 0], [14, LEN + 12, 0], [-8, -8, PH + 4], [LEN * 0.95, 4, PH]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-12, -10, 14, LEN + 12, 6, 2);
  put(solid(g), prism(P, front, sr, si, -3, 0));
  const [hr, hi] = rings(-3, -6, 3, 0, 1.5, 1);
  put(solid(g), prism(P, front, hr, hi, 0, PH + 3));
  const gate = mk("g", {}, g);
  const rails = RAILS.map(() => solid(gate)), brace = mk("path", { class: "nf" }, gate);
  const [lr, li] = rings(-2.5, LEN + 1, 2.5, LEN + 6, 1.5, 1);
  const latch = solid(g);
  put(latch, prism(P, front, lr, li, 0, PH + 1));
  const rail = rrect(-1, 0.5, 1, LEN, 0.8, 4), railIn = rrect(-0.4, 1.1, 0.4, LEN - 0.6, 0.3, 4);
  const sp = spring(REST);
  let last = NaN;

  function draw(deg) {
    const d = Math.round(deg * 20) / 20;
    if (d === last) return;
    last = d;
    const a = rad(d), R = turn(rail, a), Ri = turn(railIn, a);
    RAILS.forEach((z, i) => put(rails[i], prism(P, front, R, Ri, z, z + 2.4)));
    const at = (t, z) => P(Math.sin(a) * LEN * t, Math.cos(a) * LEN * t, z);
    const [b0, b1] = [at(0.08, RAILS[0] + 1), at(0.92, RAILS[4] + 1)];
    brace.setAttribute("d", "M" + b0.join(",") + "L" + b1.join(","));
    // a gate swung toward the viewer passes in front of the latch post
    if (d > 8) g.appendChild(gate); else latch.g.after(gate), g.appendChild(latch.g);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { sp.t = REST; rails[4].sil.classList.add("hi"); read.textContent = "rest"; B.wake(); return; }
    const [wx, wy] = unproj(C, p[0], p[1], PH / 2);
    const deg = clamp((Math.atan2(wx, Math.max(wy, 1)) * 180) / Math.PI, 0, maxA);
    sp.t = deg;
    read.textContent = deg < 2 ? "shut" : Math.round(deg) + "°";
    B.wake();
  }
  aim(null);
  draw(REST);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; aim(null); }, destroy: bag.dispose };
}

hairline({
  name: "cattlegate",
  means: "A five-rail farm gate on its hinge post: it swings open toward the pointer, up to a quarter turn, and hangs ajar at rest.",
  rules: [1, 3, 5, 8],
  range: [40, 80, 90],
  tour: [[93, 206], [246, 221], [318, 206], null],
  mount,
});

bowlingballs.code:
/**
 * Bowling balls: five balls resting on a ball return's twin rails. The
 * pointer picks a ball by where it stands: it lifts off the rails, turning
 * its finger holes up, and the balls beside it rise a little, staggered from
 * it. At rest one ball sits raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 30, R = 13, LIFT = 20, FAV = 2, RZ = 10;
const X1 = (N - 1) * STEP + 2 * R;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-6, -2, 0], [X1 + 6, 2 * R + 2, 0], [X1 + 6, -2, 0], [-6, 2 * R + 2, 0], [R, R, RZ + 2 * R + LIFT], [X1 - R, R, RZ + 2 * R + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the return: a low base and two rails the balls sit across
  const [br, bi] = rings(-6, -2, X1 + 6, 2 * R + 2, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, 4));
  const [r1, i1] = rings(-4, 4, X1 + 4, 8, 2, 0.8);
  put(solid(g), prism(P, front, r1, i1, 4, RZ));
  const [r2, i2] = rings(-4, 2 * R - 8, X1 + 4, 2 * R - 4, 2, 0.8);
  put(solid(g), prism(P, front, r2, i2, 4, RZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = R + k * STEP, y = R, grp = mk("g", {}, g);
    const ball = mk("path", { class: "sil" }, grp), holes = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, y, grp, ball, holes, z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN, spin: 0.3 + k * 1.1 });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const cz = RZ - 3 + R + lift, pts = [];
    for (let i = -6; i <= 6; i++) { const t = (i / 6) * (Math.PI / 2); pts.push(...ringAt(P, disc(it.x, it.y, R * Math.cos(t), 28), cz + R * Math.sin(t))); }
    it.ball.setAttribute("d", poly(hull(pts)));
    // three finger holes on the cap; the grip turns up as the ball lifts
    const tilt = 1.15 - (lift / LIFT) * 0.75, a0 = it.spin + lift / 12;
    let d = "";
    [[0, 2.2], [0.5, 1.7], [-0.5, 1.7]].forEach(([da, hr], j) => {
      const el = tilt + (j === 0 ? 0.3 : 0), az = a0 + da;
      const hx = it.x + R * Math.sin(el) * Math.cos(az), hy = it.y + R * Math.sin(el) * Math.sin(az), hz = cz + R * Math.cos(el);
      d += poly(ringAt(P, disc(hx, hy, hr, 12), hz));
    });
    it.holes.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, RZ + R));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.ball.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "ball " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "bowlingballs",
  means: "Five balls on a ball return: the one under the pointer lifts, turning its finger holes up, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[126, 130], [190, 162], [274, 204], null],
  mount,
});

basketballhoop.code:
/**
 * Basketball hoop: a pole on a weighted base holds a backboard with a
 * breakaway rim and its net. The pointer pulls the rim down as a dunk does:
 * the lower it stands under the rim, the further the rim tips on its hinge,
 * and the net swings with it. At rest the rim droops a touch, bright.
 * The slider is the rim's reach.
 *
 * The pattern: one part answering the pointer's position (spring).
 */
const {
  Cam, circ, clamp, fit, facing, open, poly, prism, proj, rad, rings, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const RR = 10, HZ = 74, HY = 4, NET = 14, REST = 5;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-30, -40, 0], [30, 24, 0], [-28, 2, 108], [28, 2, 108], [0, 26, HZ - 30]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-20, -40, 20, -10, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, 8));
  put(solid(g), prism(P, front, disc(0, -25, 3.5, 20), disc(0, -25, 2.5, 20), 8, 96));
  const [ar, ai] = rings(-3, -25, 3, 0, 1.5, 0.8);
  put(solid(g), prism(P, front, ar, ai, 86, 91));
  const [bdr, bdi] = rings(-28, 0, 28, 3, 1.2, 0.6);
  put(solid(g), prism(P, front, bdr, bdi, 64, 106));
  // the shooter's square on the board's face, behind the rim
  const sq = [[-9, 70], [9, 70], [9, 84], [-9, 84]].map(([x, z]) => P(x, 3.1, z));
  mk("path", { d: poly(sq), class: "nf lo" }, g);
  const net = mk("path", { class: "nf lo" }, g);
  const rim = mk("path", { class: "nf sil hi" }, g);
  const plate = mk("path", { class: "nf" }, g);

  // a point on the rim's own frame: u across, v out from the board, w down the net
  const at = (u, v, w, th) => P(u, HY + v * Math.cos(th) + w * Math.sin(th), HZ - v * Math.sin(th) + -w * Math.cos(th));
  let last = NaN;
  function draw(deg) {
    const d2 = Math.round(deg * 10) / 10;
    if (d2 === last) return;
    last = d2;
    const th = rad(deg), top = [], bot = [];
    for (let i = 0; i < 28; i++) {
      const a = (i / 28) * 2 * Math.PI;
      top.push(at(RR * Math.cos(a), RR + RR * Math.sin(a), 0, th));
      bot.push(at(0.6 * RR * Math.cos(a), RR + 0.6 * RR * Math.sin(a) + deg * 0.12, NET, th * 0.4));
    }
    let nd = poly(bot);
    for (let i = 0; i < 28; i += 2) nd += seg(top[i], bot[(i + 2) % 28]) + seg(top[i], bot[(i + 26) % 28]);
    net.setAttribute("d", nd);
    rim.setAttribute("d", poly(top));
    plate.setAttribute("d", poly([at(-4, 0, -1, th), at(4, 0, -1, th), at(4, 2, 0, th), at(-4, 2, 0, th)]));
    read.textContent = deg - REST < 0.5 ? "rest" : Math.round(deg) + "°";
  }

  const tip = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(tip, dt); draw(tip.x); return m; });
  bag.add(B.unregister);

  const home = P(0, HY + RR, HZ);
  function aim([sx, sy]) {
    if (Math.abs(sx - home[0]) > 90) return REST;
    return REST + clamp((sy - home[1] + 20) / 80, 0, 1) * (14 + reach * 0.4);
  }
  draw(REST);
  bag.add(pointer(stage, { move: (p) => { tip.t = aim(p); B.wake(); }, leave: () => { tip.t = REST; B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "basketballhoop",
  means: "A hoop on its pole: the lower the pointer stands under the rim, the further the breakaway rim tips down, swinging its net.",
  rules: [1, 3, 5, 6],
  range: [0, 45, 90],
  tour: [[179, 124], [169, 201], [162, 247], null],
  mount,
});

medicineballs.code:
/**
 * Medicine balls: a low rack holding a row of medicine balls of rising
 * weight, each with a seam round its middle. The pointer picks a ball by
 * where it stands: it lifts off the rack, and the balls beside it rise a
 * little, staggered from it. At rest one ball sits raised, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const RS = [11, 12.5, 14, 15.5, 17], N = RS.length, GAP = 5, LIFT = 24, FAV = 2, RZ = 8;
const XS = [];
{ let x = 0; RS.forEach((r, k) => { x += (k ? RS[k - 1] : 0) + r + (k ? GAP : 4); XS.push(x); }); }
const X1 = XS[N - 1] + RS[N - 1] + 4, W = 2 * RS[N - 1] + 4, YC = W / 2;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-4, -4, 0], [X1 + 4, W + 4, 0], [X1 + 4, -4, 0], [-4, W + 4, 0], [XS[0], YC, RZ + 2 * RS[0] + LIFT], [XS[N - 1], YC, RZ + 2 * RS[N - 1] + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the rack: two rails on short feet
  const rail = (y0, y1) => {
    for (const x of [2, X1 - 8]) { const [fr, fi] = rings(x, y0, x + 6, y1, 2, 1); put(solid(g), prism(P, front, fr, fi, 0, RZ - 3)); }
    const [rr, ri] = rings(-2, y0, X1 + 2, y1, 3, 1); put(solid(g), prism(P, front, rr, ri, RZ - 3, RZ));
  };
  rail(-2, 4);
  const bg = mk("g", {}, g);
  rail(W - 4, W + 2);

  const items = RS.map((r, k) => {
    const grp = mk("g", {}, bg);
    const ball = mk("path", { class: "sil" }, grp), seam = mk("path", { class: "nf lo" }, grp), seam2 = mk("path", { class: "nf lo" }, grp);
    return { k, r, x: XS[k], grp, ball, seam, seam2, z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN };
  });

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const r = it.r, zc = RZ - r * 0.25 + r + lift, pts = [];
    for (let i = 0; i <= 8; i++) { const t = -Math.PI / 2 + (i / 8) * Math.PI; pts.push(...ringAt(P, disc(it.x, YC, r * Math.cos(t) + 0.01, 28), zc + r * Math.sin(t))); }
    it.ball.setAttribute("d", poly(hull(pts)));
    // two seams on the near side: the equator and one meridian
    const eq = [], mer = [];
    for (let i = 0; i <= 40; i++) {
      const t = -Math.PI / 2 + (i / 40) * 2 * Math.PI, c = Math.cos(t), sn = Math.sin(t);
      if (0.612 * (c + sn) > 0.05) eq.push(P(it.x + r * c, YC + r * sn, zc));
      if (0.612 * c + 0.5 * sn > 0.05) mer.push(P(it.x + r * c, YC, zc + r * sn));
    }
    it.seam.setAttribute("d", open(eq));
    it.seam2.setAttribute("d", open(mer));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, YC, RZ + it.r));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 6 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.ball.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : (4 + 2 * a) + " kg";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "medicineballs",
  means: "Medicine balls of rising weight on a low rack: the ball under the pointer lifts off, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[150, 150], [200, 170], [250, 190], null],
  mount,
});

pullupbar.code:
/**
 * Pull-up bar: a free-standing frame of two posts on splayed feet, each
 * post drilled with a column of height holes, and a bar with two foam grips
 * pinned between them. The pointer picks a height by where it stands along
 * the posts: the bar slides to that pair of holes. At rest the bar sits at
 * the fourth hole, bright. The slider spreads the grips apart.
 *
 * The pattern: one value chosen from a column (a tween between stops).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 84, PH = 116, HZ = [56, 66, 76, 86, 96, 106], REST = 3, BR = 2.4, GR = 3.6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let grip = value;
  const C = Cam(45, 0.5, 1.7);
  fit(C, [[-4, -22, 0], [L + 4, 22, 0], [L + 4, -22, 0], [-4, 22, 0], [0, 0, PH], [L, 0, PH]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const tube = (parent, x0, x1, r, z, cls) => {
    const pts = [];
    for (const x of [x0, x1]) for (let i = 0; i < 24; i++) { const t = (i / 24) * 2 * Math.PI; pts.push(P(x, r * Math.cos(t), z + r * Math.sin(t))); }
    return mk("path", { d: poly(hull(pts)), class: cls }, parent);
  };
  const holes = [];
  function post(x) {
    const [fr, fi] = rings(x - 3, -22, x + 3, 22, 3, 1);
    put(solid(g), prism(P, front, fr, fi, 0, 4));
    const [pr, pi] = rings(x - 3, -3, x + 3, 3, 1.6, 0.8);
    put(solid(g), prism(P, front, pr, pi, 4, PH));
    holes.push(HZ.map((z) => { const d = mk("circle", { r: 1.5, class: "dot off" }, g), p = P(x, 3, z); d.setAttribute("cx", p[0]); d.setAttribute("cy", p[1]); return d; }));
  }
  post(0);
  const barG = mk("g", {}, g);
  post(L);
  const bar = { z: tween(HZ[REST]), last: NaN, lastG: NaN };

  function draw(z) {
    if (z === bar.last && grip === bar.lastG) return;
    bar.last = z; bar.lastG = grip;
    barG.replaceChildren();
    const sil = tube(barG, 3, L - 3, BR, z, "sil hi");
    const m = L / 2, half = 6 + grip * 0.28;
    tube(barG, m - half - 12, m - half, GR, z, "");
    tube(barG, m + half, m + half + 12, GR, z, "");
    return sil;
  }

  const B = register(stage, (_dt, now) => { draw(tval(bar.z, now)); return !tdone(bar.z, now); });
  bag.add(B.unregister);

  const mids = HZ.map((z) => { const a = P(0, 0, z), b = P(L, 0, z); return [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2]; });
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 48 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    const h = a < 0 ? REST : a;
    tset(bar.z, HZ[h], performance.now(), 0);
    holes.forEach((col) => col.forEach((d, k) => d.setAttribute("class", k === h ? "dot m" : "dot off")));
    read.textContent = a < 0 ? "rest" : "hole " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { grip = v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "pullupbar",
  means: "A pull-up bar pinned between two drilled posts: the bar slides to the pair of holes nearest the pointer.",
  rules: [1, 4, 5, 8],
  range: [0, 30, 60],
  tour: [[200, 120], [200, 150], [200, 100], null],
  mount,
});

aerobicsteps.code:
/**
 * Aerobic steps: a class row of step platforms, each a long deck on two
 * riser blocks. The pointer picks a step by where it stands: its deck
 * rises to the high setting, and the steps beside it rise a little,
 * staggered from it. At rest one step stands high, bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 34, DW = 22, DL = 70, DT = 4, RZ = 6, LIFT = 12, FAV = 1;
const X1 = (N - 1) * STEP + DW;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[0, 0, 0], [X1, DL, 0], [X1, 0, 0], [0, DL, 0], [0, 0, RZ + LIFT + DT], [X1, DL, RZ + LIFT + DT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, grp = mk("g", {}, g);
    const parts = [solid(grp), solid(grp), solid(grp)];
    items.push({ k, x, parts, z: tween(k === FAV ? LIFT : 0), last: NaN });
  }
  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const x = it.x, h = RZ + lift;
    [[6, 18], [DL - 18, DL - 6]].forEach(([y0, y1], i) => {
      const [r, ri] = rings(x + 2, y0, x + DW - 2, y1, 2, 1);
      put(it.parts[i], prism(P, front, r, ri, 0, h));
    });
    const [dr, di] = rings(x, 0, x + DW, DL, 5, 1.6);
    put(it.parts[2], prism(P, front, dr, di, h, h + DT));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + DW / 2, DL / 2, RZ + DT));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && Math.abs(mids[best][1] - sy) < 50 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.parts[2].sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "step " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "aerobicsteps",
  means: "A row of aerobic step platforms: the step under the pointer rises to its high setting, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[150, 140], [210, 170], [250, 190], null],
  mount,
});

cymbals.code:
/**
 * Cymbals: three cymbals on stands over a rug. The pointer picks a cymbal by
 * where it stands: it swings, tipping toward the viewer as if struck, and
 * the cymbals beside it rock a little, staggered from it. At rest each hangs
 * at its own angle and the ride is bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rad, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SP = 62, R = 24, FAV = 1;
const CY = [{ h: 58, rest: 10, name: "crash" }, { h: 46, rest: -6, name: "ride" }, { h: 66, rest: 16, name: "splash" }];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  const X0 = -R - 6, X1 = 2 * SP + R + 6;
  fit(C, [[X0, -R - 6, 0], [X1, R + 6, 0], [X1, -R - 6, 0], [X0, R + 6, 0], [0, 0, 66 + R * 0.6], [2 * SP, 0, 66 + R * 0.6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [rr, ri] = rings(X0, -R - 6, X1, R + 6, 8, 2);
  put(solid(g), prism(P, front, rr, ri, 0, 2));

  const e1 = [Math.SQRT1_2, -Math.SQRT1_2], d = [Math.SQRT1_2, Math.SQRT1_2];
  // a disc of radius r centred at (x, y, z), tipped by a about the e1 axis
  const tipRing = (x, y, z, r, a, n = 36) => {
    const out = [], ca = Math.cos(a), sa = Math.sin(a);
    for (let i = 0; i < n; i++) {
      const t = (i / n) * Math.PI * 2, c = r * Math.cos(t), s = r * Math.sin(t);
      out.push(P(x + c * e1[0] + s * d[0] * ca, y + c * e1[1] + s * d[1] * ca, z + s * sa));
    }
    return out;
  };

  const items = CY.map((cy, k) => {
    const x = k * SP, y = 0, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, y, 9), disc(x, y, 7), 2, 4));
    put(solid(grp), prism(P, front, disc(x, y, 1.6, 12), disc(x, y, 1, 12), 4, cy.h + 3));
    const body = mk("path", { class: "sil" }, grp), top = mk("path", { class: "nf lo" }, grp), bell = mk("path", {}, grp);
    return { k, x, y, cy, body, top, bell, a: tween(rad(cy.rest)), last: NaN };
  });

  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    const { x, y } = it, z = it.cy.h;
    it.body.setAttribute("d", poly(hull(tipRing(x, y, z, R, a).concat(tipRing(x, y, z - 1.6, R, a)))));
    it.top.setAttribute("d", poly(tipRing(x, y, z, R - 3, a)));
    it.bell.setAttribute("d", poly(hull(tipRing(x, y, z, 7, a, 20).concat(tipRing(x, y, z + 3, 4, a, 20)))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, it.cy.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), deg = a < 0 ? it.cy.rest : dd === 0 ? 34 : dd === 1 ? it.cy.rest + 8 : it.cy.rest;
      tset(it.a, rad(deg), now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : items[a].cy.name;
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "cymbals",
  means: "Three cymbals on stands: the one under the pointer swings as if struck, and its neighbours rock a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[123, 82], [200, 139], [277, 147], null],
  mount,
});

recordcrates.code:
/**
 * Record crates: a wooden crate of record sleeves standing on edge. The
 * pointer picks a sleeve by where it stands: that sleeve slides up out of
 * the crate to be read, and the sleeves beside it rise a little, staggered
 * from it. At rest the sleeves stand uneven and one is pulled up, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 8, GAP = 7.5, W = 38, H = 24, SH = 36, LIFT = 24, FAV = 4;
const L = N * GAP + 6;
const REST = [1, 0, 3, 0, 15, 2, 0, 1];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.1);
  fit(C, [[0, 0, 0], [L, W, 0], [L, 0, 0], [0, W, 0], [L / 2, W / 2, SH + LIFT + 2], [0, 0, SH + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r, b, cls) => {
    const s = solid(g), [rr, ri] = rings(x0, y0, x1, y1, r, b);
    put(s, prism(P, front, rr, ri, z0, z1));
    return s;
  };
  box(0, 0, L, W, 0, 2.5, 3, 1.2);
  box(0, 0, L, 3, 2.5, H, 1.2, 0.6);
  box(0, 0, 3, W, 2.5, H, 1.2, 0.6);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 4 + k * GAP + 1.5, s = solid(g);
    items.push({ k, x, s, z: tween(REST[k]), last: NaN });
  }
  box(L - 3, 0, L, W, 2.5, H, 1.2, 0.6);
  box(0, W - 3, L, W, 2.5, H, 1.2, 0.6);

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const [rr, ri] = rings(it.x, 4.5, it.x + 1.8, W - 4.5, 0.8, 0.35);
    put(it.s, prism(P, front, rr, ri, 3 + lift, SH + lift));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, W / 2, SH * 0.7));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 14 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? REST[k] : dd === 0 ? LIFT : dd === 1 ? 6 : dd === 2 ? 2 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "lp " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "recordcrates",
  means: "A crate of record sleeves: the sleeve under the pointer slides up out of the crate, and its neighbours rise a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[141, 116], [182, 137], [255, 173], null],
  mount,
});

billboard.code:
/**
 * Billboard: a roadside board on two posts, its face made of vertical
 * slats that turn like a tri-vision sign. The pointer picks a slat by its
 * screen x: it turns to show its other side, and the slats beside it turn
 * after it, staggered by distance. At rest one slat stands half turned,
 * bright. The slider is the stagger.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 8, W = 15, H0 = 34, H = 46, FAV = 5, X1 = N * W;
const REST = [0.08, 0.04, 0, 0.05, 0.12, 0.55, 0.18, 0.06];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-6, -10, 0], [X1 + 6, 10, 0], [-6, 10, H0 + H], [X1 + 6, -10, H0 + H]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  for (const px of [W * 1.5, X1 - W * 1.5]) {
    const [r, i] = rings(px - 3, -6, px + 3, 0, 1.5, 0.8);
    put(solid(g), prism(P, front, r, i, 0, H0 - 3));
  }
  const [lr, li] = rings(-4, -7, X1 + 4, 7, 2, 1.2);
  put(solid(g), prism(P, front, lr, li, H0 - 4, H0 - 1));

  const items = [];
  for (let k = 0; k < N; k++) {
    const cx = W / 2 + k * W, grp = mk("g", {}, g);
    const sil = mk("path", { class: "sil" }, grp), mid = mk("path", { class: "nf lo" }, grp);
    items.push({ k, cx, sil, mid, a: tween(REST[k]), last: NaN });
  }

  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    const h = W * 0.47, t = 1.2, ang = a * Math.PI, c = Math.cos(ang), s = Math.sin(ang), pts = [];
    const at = (u, v, z) => P(it.cx + u * c - v * s, u * s + v * c, z);
    for (const [u, v] of [[-h, -t], [h, -t], [h, t], [-h, t]]) pts.push(at(u, v, H0), at(u, v, H0 + H));
    it.sil.setAttribute("d", poly(hull(pts)));
    it.mid.setAttribute("d", "M" + at(-h * 0.7, t, H0 + H * 0.5) + "L" + at(h * 0.7, t, H0 + H * 0.5));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.cx, 0, H0 + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 16 && Math.abs(mids[best][1] - sy) < 50 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), v = a < 0 ? REST[k] : d === 0 ? 1 : d === 1 ? 0.62 : d === 2 ? 0.3 : 0;
      tset(it.a, v, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "slat " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "billboard",
  means: "A roadside board of turning slats: the slat under the pointer turns over, and its neighbours follow, staggered.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[140, 100], [232, 145], [272, 165], null],
  mount,
});

watchwinder.code:
/**
 * Watch winder: a lidded box holding a watch on a cushion. The pointer over
 * the box opens the lid on its back hinge, and the watch turns a full winding
 * as it opens. At rest the lid stands ajar, bright. The slider is how far
 * the lid opens.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 64, Y1 = 46, Z1 = 28, T = 3, AJAR = 0.16;
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.8);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [X1, 0, 0], [0, Y1, 0], [0, -4, Z1 + Y1], [X1, -4, Z1 + Y1]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, X1, Y1, 5, 1.8);
  put(solid(g), prism(P, front, br, bi, 0, Z1));
  const [wr, wi] = rings(5, 5, X1 - 5, Y1 - 5, 3, 1);
  mk("path", { d: poly(ringAt(P, wr, Z1)), class: "lo" }, g);
  const cx = X1 / 2, cy = Y1 / 2 + 2;
  const [cr, ci] = rings(cx - 16, cy - 12, cx + 16, cy + 12, 8, 1.6);
  put(solid(g), prism(P, front, cr, ci, Z1 - 4, Z1 + 4));
  const face = mk("path", { d: poly(ringAt(P, disc(cx, cy, 9), Z1 + 5)), class: "sil" }, g);
  mk("path", { d: poly(ringAt(P, disc(cx, cy, 7), Z1 + 5)), class: "nf lo" }, g);
  const hand = mk("path", { class: "nf" }, g);
  const lid = mk("path", { class: "sil" }, g), lidIn = mk("path", { class: "nf lo" }, g);
  const tw = tween(AJAR);
  let last = NaN;

  function draw(o) {
    if (o === last) return;
    last = o;
    const th = o * 1.75, c = Math.cos(th), s = Math.sin(th), pts = [], inner = [];
    const at = (x, l, h) => P(x, l * c - h * s, Z1 + l * s + h * c);
    for (const x of [0, X1]) for (const l of [0, Y1]) for (const h of [0, T]) pts.push(at(x, l, h));
    lid.setAttribute("d", poly(hull(pts)));
    for (const [x, l] of [[3, 3], [X1 - 3, 3], [X1 - 3, Y1 - 3], [3, Y1 - 3]]) inner.push(at(x, l, s > 0.5 ? 0 : T));
    lidIn.setAttribute("d", poly(inner));
    const a = o * Math.PI * 2 - 0.6;
    hand.setAttribute("d", "M" + P(cx, cy, Z1 + 5) + "L" + P(cx + 6 * Math.cos(a), cy + 6 * Math.sin(a), Z1 + 5));
  }

  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(tw, on ? 0.3 + 0.7 * reach / 100 : AJAR, performance.now(), 0);
    lid.classList.toggle("hi", !on);
    face.classList.toggle("hi", on);
    read.textContent = on ? "wind" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, Z1);
    return x > -6 && x < X1 + 6 && y > -6 && y < Y1 + 6;
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "watchwinder",
  means: "A watch winder box: the pointer opens its lid on the back hinge, and the watch on its cushion turns as it opens.",
  rules: [1, 3, 5, 6],
  range: [0, 80, 100],
  tour: [[178, 160], [192, 196], [212, 228], null],
  mount,
});

beertaps.code:
/**
 * Beer taps: four handles on a bar tower over a drip tray. The pointer picks
 * a tap by where it stands: its handle is pulled forward to pour, and the
 * handles beside it give a little, staggered from it. At rest one tap is
 * half pulled, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, rrect, run, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 24, X0 = 12, X1 = X0 * 2 + (N - 1) * STEP, ZB = 40, ZT = 66, FAV = 2;
const REST = [-5, 3, 20, -2];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-8, -12, 0], [X1 + 8, 28, 0], [X1 + 8, -12, 0], [-8, 28, 0], [X0, 0, ZT + 2], [X1 - X0, 0, ZT + 2], [X0, 22, ZT - 6]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1, parent = g) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(parent); put(s, prism(P, front, o, i, z0, z1)); return s; };

  box(-8, -12, X1 + 8, 28, 5, 2, 0, 4);
  box(5, -4, 13, 4, 3, 1.2, 4, ZB - 6);
  box(X1 - 13, -4, X1 - 5, 4, 3, 1.2, 4, ZB - 6);
  const tray = box(2, 8, X1 - 2, 22, 3, 1.6, 4, 6.5);
  // the tray's grate: a few slats inside its rim
  for (let k = 1; k < 8; k++) { const x = 2 + k * (X1 - 4) / 8; mk("path", { d: open([P(x, 10, 6.5), P(x, 20, 6.5)]), class: "nf lo" }, tray.g); }
  box(0, -5, X1, 5, 4, 1.6, ZB - 6, ZB);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP, grp = mk("g", {}, g);
    box(x - 2, 3, x + 2, 9, 1.5, 0.6, ZB - 12, ZB - 4, grp);
    const sil = mk("path", { class: "sil" }, grp), cr = mk("path", { class: "nf lo" }, grp);
    const foot = rrect(x - 2.2, -2.2, x + 2.2, 2.2, 2.2, 6), top = rrect(x - 4, -3, x + 4, 3, 2.5, 6), inner = rrect(x - 3, -2, x + 3, 2, 1.6, 6);
    items.push({ k, x, grp, sil, cr, foot, top, inner, a: tween(REST[k]), last: NaN });
  }

  // a ring tilted about the tower's top edge: the handle swings toward the viewer
  function tilted(ring, z, th) {
    const c = Math.cos(rad(th)), s = Math.sin(rad(th)), dz = z - ZB;
    return ring.map((q) => P(q.u, q.v * c + dz * s, ZB - q.v * s + dz * c));
  }
  function draw(it, th) {
    if (th === it.last) return;
    it.last = th;
    it.sil.setAttribute("d", poly(hull(tilted(it.foot, ZB, th).concat(tilted(it.top, ZT, th)))));
    it.cr.setAttribute("d", open(tilted(run(it.inner, front), ZT, th)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 0, (ZB + ZT) / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 28 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), th = a < 0 ? REST[k] : dd === 0 ? 50 : dd === 1 ? 10 : -4;
      tset(it.a, th, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tap " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "beertaps",
  means: "Four beer taps on a bar tower: the handle under the pointer is pulled forward to pour, and its neighbours give a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[154, 67], [233, 106], [272, 126], null],
  mount,
});

rooftopgarden.code:
/**
 * Rooftop garden: a building block with three planter beds on its roof, each
 * holding a shrub. The pointer picks a bed by where it stands: its shrub grows
 * tall and the beds beside it grow a little, staggered from it. At rest the
 * first shrub stands taller, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, W = 120, D = 70, H = 46, PZ = 9, FAV = 0, GROW = 40;
const BX = [8, 44, 80], BW = 32;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const REST = [16, 2, 6];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [W / 2, D / 2, H + PZ + 20 + GROW]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, D, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, H));
  // parapet ledge round the roof
  const [pr, pi] = rings(2, 2, W - 2, D - 2, 5, 1.2);
  mk("path", { d: poly(ringAt(P, pr, H)), class: "nf lo" }, g);
  // floor lines on the front faces
  for (const z of [H / 3, (2 * H) / 3]) {
    mk("path", { d: "M" + P(W, 6, z) + "L" + P(W, D, z) + "L" + P(6, D, z), class: "nf lo" }, g);
  }

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = BX[k], x = x0 + BW / 2, y = D / 2, grp = mk("g", {}, g);
    const [r, ri] = rings(x0, y - 15, x0 + BW, y + 15, 4, 1.4);
    const bed = solid(grp);
    put(bed, prism(P, front, r, ri, H, H + PZ));
    const bush = mk("path", { class: "nf" }, grp);
    items.push({ k, x, y, bed, bush, h: tween(REST[k]), last: NaN });
  }

  function draw(it, h) {
    if (h === it.last) return;
    it.last = h;
    const z0 = H + PZ - 1, pts = [];
    for (const [rf, zf] of [[0.75, 0], [1, 0.3], [0.85, 0.65], [0.4, 0.92], [0.1, 1]]) {
      pts.push(...ringAt(P, disc(it.x, it.y, (11 + h * 0.12) * rf + 0.01), z0 + (12 + h) * zf));
    }
    it.bush.setAttribute("d", poly(hull(pts)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.h, now)); if (!tdone(it.h, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, H + PZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), h = a < 0 ? REST[k] : dd === 0 ? GROW : dd === 1 ? 6 : 1;
      tset(it.h, h, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.bed.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bed " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "rooftopgarden",
  means: "Three planter beds on a building's roof: the shrub in the bed under the pointer grows tall, its neighbours a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[155, 112], [200, 134], [245, 156], null],
  mount,
});

birdhide.code:
/**
 * Bird hide: a timber hide on stilts over a wetland, with a row of viewing
 * hatches along its long wall. The pointer picks a hatch by where it stands:
 * its flap swings up and out on the top hinge, and the flaps beside it crack
 * open a little, staggered from it. At rest one flap is propped half open,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, fillet, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 96, Y1 = 40, Z0 = 16, Z1 = 52, N = 3, HW = 10, HT = 43, HH = 12, FAV = 1, OPEN = 84;
const disc = (x, y, r, n = 16) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-24, -18, 0], [X1 + 24, Y1 + 30, 0], [X1 + 24, -18, 0], [-24, Y1 + 30, 0], [-6, -6, Z1 + 12], [X1 + 6, Y1 + 6, Z1 + 12]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the wetland: a low bank with a waterline inside it
  const [wr, wi] = rings(-24, -18, X1 + 24, Y1 + 30, 14, 2);
  put(solid(g), prism(P, front, wr, wi, 0, 2));
  // stilts, far to near
  for (const [x, y] of [[6, 6], [X1 - 6, 6], [6, Y1 - 6], [X1 - 6, Y1 - 6]]) put(solid(g), prism(P, front, disc(x, y, 2.4), disc(x, y, 1.6), 2, Z0));
  // the cabin and its roof slab
  const [br, bi] = rings(0, 0, X1, Y1, 4, 1.4);
  put(solid(g), prism(P, front, br, bi, Z0, Z1));
  mk("path", { d: `M${P(0, Y1, Z0 + 12).join(",")}L${P(X1, Y1, Z0 + 12).join(",")}`.replace(/,/g, " "), class: "nf lo" }, g);
  const [rr, ri] = rings(-6, -6, X1 + 6, Y1 + 6, 4, 1.6);
  put(solid(g), prism(P, front, rr, ri, Z1, Z1 + 4));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 20 + k * 28, grp = mk("g", {}, g);
    const slot = [P(x - HW, Y1, HT), P(x + HW, Y1, HT), P(x + HW, Y1, HT - HH), P(x - HW, Y1, HT - HH)];
    mk("path", { d: poly(fillet(slot, [1.2, 1.2, 1.2, 1.2])), class: "lo" }, grp);
    const flap = mk("path", { class: "sil" }, grp), edge = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, flap, edge, a: tween(k === FAV ? OPEN * 0.6 : 0), last: NaN });
  }

  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    const t = (a * Math.PI) / 180, dy = HH * Math.sin(t), dz = HH * Math.cos(t), th = 1.4;
    const ex = (o) => [P(it.x - HW, Y1 + o, HT), P(it.x + HW, Y1 + o, HT), P(it.x + HW, Y1 + o + dy, HT - dz), P(it.x - HW, Y1 + o + dy, HT - dz)];
    it.flap.setAttribute("d", poly(fillet(ex(0.4), [1, 1, 1, 1])));
    const b0 = P(it.x - HW, Y1 + 0.4 + dy + th * Math.cos(t), HT - dz - th * Math.sin(t) * 0), b1 = P(it.x + HW, Y1 + 0.4 + dy + th * Math.cos(t), HT - dz);
    it.edge.setAttribute("d", a > 2 ? `M${b0[0]} ${b0[1]}L${b1[0]} ${b1[1]}` : "");
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, Y1, HT - HH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 28 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), v = a < 0 ? (k === FAV ? OPEN * 0.6 : 0) : dd === 0 ? OPEN : dd === 1 ? 34 : 0;
      tset(it.a, v, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.flap.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "hatch " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "birdhide",
  means: "A bird hide on stilts over a wetland: the hatch under the pointer swings its flap up, and its neighbours crack open.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[123, 139], [183, 159], [242, 198], null],
  mount,
});

globestand.code:
/**
 * Globe stand: a school globe on a tilted axis, held by a half meridian ring
 * on a stem and a round foot. The pointer's place across the frame spins the
 * globe on its axis, on a spring; the marked meridian, with its one city dot,
 * turns with it and the read-out gives its longitude. At rest the globe is
 * turned a little, the marked meridian bright on the near side.
 *
 * The pattern: one object answering a continuous input (spin).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, clamp, rad, spring, stepS,
  disposer, mk, pointer, put, register, solid, flatDot, place,
} = HL;

const R = 30, RR = 34, TILT = rad(23), CZ = 58, REST = 35, SPAN = 160;
const U = [Math.sin(TILT), 0, Math.cos(TILT)], E1 = [Math.cos(TILT), 0, -Math.sin(TILT)], E2 = [0, 1, 0];
const V = [0.612, 0.612, 0.5];
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const sph = (lat, lon, r = R) => {
  const a = Math.cos(lat) * Math.cos(lon), b = Math.cos(lat) * Math.sin(lon), c = Math.sin(lat);
  return [0, 1, 2].map((i) => r * (a * E1[i] + b * E2[i] + c * U[i]));
};
const vis = (p) => p[0] * V[0] + p[1] * V[1] + p[2] * V[2] > 0;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.4);
  const BX = -RR * U[0], BZ = CZ - RR * U[2];
  fit(C, [[BX - 26, -26, 0], [BX + 26, 26, 0], [-R, -R, CZ + R + 4], [R, R, CZ + R], [R, -R, CZ], [-R, R, CZ]], 200, 166);
  const P = proj(C), front = facing(C);
  const W = (p) => P(p[0], p[1], p[2] + CZ);
  const g = mk("g", {}, svg);
  const [fr, fi] = rings(BX - 24, -24, BX + 24, 24, 24, 2);
  put(solid(g), prism(P, front, fr, fi, 0, 4));
  put(solid(g), prism(P, front, disc(BX, 0, 7, 24), disc(BX, 0, 5.5, 24), 4, 7));
  put(solid(g), prism(P, front, disc(BX, 0, 2.4, 16), disc(BX, 0, 1.4, 16), 7, BZ + 2));

  // the half meridian ring, split into the part behind the globe and the part before it
  const arc = (keep) => {
    let d = "", on = false;
    for (let i = 0; i <= 48; i++) {
      const t = rad(-110 + (220 * i) / 48), p = [0, 1, 2].map((k) => RR * (Math.sin(t) * U[k] - Math.cos(t) * E1[k]));
      if (vis(p) === keep) { const s = W(p); d += (on ? "L" : "M") + s[0].toFixed(2) + " " + s[1].toFixed(2); on = true; } else on = false;
    }
    return d;
  };
  mk("path", { d: arc(false), class: "nf" }, g);
  const pts = [];
  for (let a = 0; a < 360; a += 6) for (let b = -90; b <= 90; b += 10) pts.push(W(sph(rad(b), rad(a))));
  mk("path", { d: poly(hull(pts)), class: "sil" }, g);
  const line = (fn, n) => {
    let d = "", on = false;
    for (let i = 0; i <= n; i++) {
      const p = fn(i / n);
      if (vis(p)) { const s = W(p); d += (on ? "L" : "M") + s[0].toFixed(2) + " " + s[1].toFixed(2); on = true; } else on = false;
    }
    return d;
  };
  for (const lat of [-40, 0, 40]) mk("path", { d: line((f) => sph(rad(lat), f * 2 * Math.PI), 72), class: "nf lo" }, g);
  const mers = [0, 1, 2, 3, 4, 5].map(() => mk("path", { class: "nf lo" }, g));
  const mark = mk("path", { class: "nf hi" }, g);
  mk("path", { d: arc(true), class: "nf" }, g);
  const pin = flatDot(g, C, 2.6, "dot");

  const spin = spring(REST);
  let last = NaN;
  function draw(s) {
    if (s === last) return;
    last = s;
    mers.forEach((m, k) => m.setAttribute("d", line((f) => sph(rad(-90 + 180 * f), rad(s + 30 + k * 60)), 36)));
    mark.setAttribute("d", line((f) => sph(rad(-90 + 180 * f), rad(s)), 36));
    const c = sph(rad(35), rad(s));
    place(pin, W(c));
    pin.setAttribute("class", vis(c) ? "dot" : "dot off");
  }
  const B = register(stage, (dt) => { const m = stepS(spin, dt); draw(spin.x); return m; });
  bag.add(B.unregister);

  let on = false;
  function aim(t) {
    spin.t = t;
    B.wake();
  }
  aim(REST);
  read.textContent = "rest";
  bag.add(pointer(stage, {
    move: ([sx]) => {
      const f = clamp((sx - 200) / 150, -1, 1), t = REST + 120 + f * SPAN * (0.4 + 0.6 * reach / 100);
      on = true;
      aim(t);
      const lon = Math.round(((((t - 45) % 360) + 540) % 360) - 180);
      read.textContent = Math.abs(lon) + "°" + (lon < 0 ? "W" : "E");
    },
    leave: () => { on = false; aim(REST); read.textContent = "rest"; },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "globestand",
  means: "A school globe on a tilted axis and meridian stand: the pointer across the frame spins it, the marked meridian turning to face you.",
  rules: [3, 4, 5, 8],
  range: [0, 60, 100],
  tour: [[90, 160], [310, 170], [200, 120], null],
  mount,
});

gurney.code:
/**
 * Gurney: a stretcher trolley on castors, its mattress in two sections. The
 * back section is hinged at the middle: the pointer's place along the bed,
 * read on the ground plane, sets how far the back is raised, on a spring.
 * At rest the back stands part-way up, bright. The slider is the top angle.
 *
 * The pattern: one part turning about a hinge (tilt).
 */
const {
  Cam, circ, clamp, fit, facing, hull, lerp, open, poly, prism, proj, rad, rings, ringAt, rrect, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 128, W = 40, HZ = 40, DZ = 36, MT = 7, HX = 44, REST = 14;
const disc = (x, y, r, n = 16) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let top = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, 0, 0], [L + 8, W, 0], [L + 8, 0, 0], [0, W, 0], [HX - 44 * Math.cos(rad(85)), 0, HZ + 44 + MT], [HX, W, HZ + 44 + MT], [L + 8, 0, 60]], 200, 170);
  const P = proj(C), front = facing(C), g = mk("g", {}, svg);
  // castors, then the base frame and the column
  for (const [x, y] of [[8, 6], [L - 8, 6], [8, W - 6], [L - 8, W - 6]]) put(solid(g), prism(P, front, disc(x, y, 4.5), disc(x, y, 3), 0, 6));
  const [br, bi] = rings(2, 4, L - 2, W - 4, 4, 1.4);
  put(solid(g), prism(P, front, br, bi, 6, 10));
  for (const x of [34, 94]) { const [cr, ci] = rings(x - 4, W / 2 - 5, x + 4, W / 2 + 5, 2.5, 1); put(solid(g), prism(P, front, cr, ci, 10, DZ)); }
  const [dr, di] = rings(0, 0, L, W, 3, 1.2);
  put(solid(g), prism(P, front, dr, di, DZ, HZ));
  // back section: a slab hinged at x = HX, drawn from its own rounded ring
  const back = solid(g);
  const bRing = rrect(0, 1, HX - 1, W - 1, 5, 4), bIn = rrect(2, 3, HX - 3, W - 3, 3, 4);
  // foot section and the push handle
  const [fr, fi] = rings(HX + 1, 1, L - 1, W - 1, 5, 2);
  put(solid(g), prism(P, front, fr, fi, HZ, HZ + MT));
  const hd = [];
  for (const y of [4, W - 4]) hd.push(seg(P(L + 6, y, DZ), P(L + 6, y, 60)), seg(P(L, y, DZ + 2), P(L + 6, y, DZ + 2)));
  hd.push(seg(P(L + 6, 4, 60), P(L + 6, W - 4, 60)));
  mk("path", { d: hd.join(""), class: "nf" }, g);

  const ang = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const at = (q, t) => P(HX - q.u * c - t * s, q.v, HZ + q.u * s + t * c);
    const pts = [];
    for (const q of bRing) pts.push(at(q, 0), at(q, MT));
    put(back, { sil: poly(hull(pts)), crease: poly(bIn.map((q) => at(q, MT))) });
  }
  back.cr.classList.add("nf");
  back.sil.classList.add("hi");
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, 0);
    if (wx < -20 || wx > L + 20 || wy < -30 || wy > W + 30) return leave();
    const a = Math.round(lerp(0, top, clamp((L - wx) / (L - 10), 0, 1)));
    ang.t = a;
    read.textContent = "back " + a + "°";
    B.wake();
  }
  function leave() { ang.t = REST; read.textContent = "rest"; B.wake(); }
  draw(REST);
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { top = v; }, destroy: bag.dispose };
}

hairline({
  name: "gurney",
  means: "A stretcher trolley on castors: the pointer's place along the bed raises the hinged back section, further toward the head.",
  rules: [1, 3, 5, 8],
  range: [40, 70, 85],
  tour: [[150, 120], [220, 170], [290, 210], null],
  mount,
});

dialysis.code:
/**
 * Drip monitor: a bedside monitor on a wheeled pole, a drip bag hung from
 * the pole's crossbar. The monitor head turns about the pole to face the
 * pointer, read on the ground plane, on a spring, its trace turning with it.
 * At rest it faces a little off the viewer, bright. The slider is the swing.
 *
 * The pattern: one part turning to face the pointer (aim).
 */
const {
  Cam, circ, clamp, fit, facing, open, poly, prism, proj, rad, rings, rrect, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PZ = 104, MZ0 = 46, MZ1 = 82, HW = 27, DP = 10, OFF = 6, REST = 22;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const turn = (ring, th) => {
  const c = Math.cos(th), s = Math.sin(th);
  // local u runs across the screen, local v is depth toward the face
  return ring.map((q) => ({ u: (q.v + OFF) * c - q.u * s, v: (q.v + OFF) * s + q.u * c, nu: q.nv * c - q.nu * s, nv: q.nv * s + q.nu * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let sw = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-26, -26, 0], [26, 26, 0], [-26, 26, 0], [26, -26, 0], [0, -26, PZ], [0, 26, PZ], [36, 0, MZ0], [0, 36, MZ0]], 200, 166);
  const P = proj(C), front = facing(C), g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(0, 0, 24, 40), disc(0, 0, 22, 40), 3, 7));
  for (let k = 0; k < 5; k++) { const a = rad(k * 72 + 20); put(solid(g), prism(P, front, disc(20 * Math.cos(a), 20 * Math.sin(a), 3, 12), disc(20 * Math.cos(a), 20 * Math.sin(a), 2, 12), 0, 3)); }
  // crossbar, the bag on its far end with a dashed line down, the pole
  mk("path", { d: seg(P(0, -22, PZ), P(0, 22, PZ)), class: "nf" }, g);
  mk("path", { d: seg(P(0, -18, 72), P(0, -18, 52)), class: "dash nf" }, g);
  const [br, bi] = rings(-4, -25, 4, -11, 4, 1.2);
  put(solid(g), prism(P, front, br, bi, 72, PZ - 4));
  const [pr, pi] = rings(-2, -2, 2, 2, 2, 0.6);
  put(solid(g), prism(P, front, pr, pi, 7, PZ + 3));
  const [hr, hi] = rings(-4, 18, 4, 26, 4, 1.2);
  put(solid(g), prism(P, front, hr, hi, 80, PZ - 6));

  const head = solid(g), screen = mk("path", { class: "nf lo" }, g), trace = mk("path", { class: "nf" }, g);
  head.sil.classList.add("hi");
  const ring = rrect(-HW, 0, HW, DP, 4, 4), inner = rrect(-HW + 1.5, 1.5, HW - 1.5, DP - 1.5, 2.5, 4);
  const face = (u, z, th) => P((OFF + DP) * Math.cos(th) - u * Math.sin(th), (OFF + DP) * Math.sin(th) + u * Math.cos(th), z);
  const wave = [[-20, 0], [-10, 0], [-7, 3], [-4, -10], [-1, 9], [2, 0], [20, 0]];
  const ang = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const th = rad(a);
    put(head, prism(P, front, turn(ring, th), turn(inner, th), MZ0, MZ1));
    screen.setAttribute("d", poly([[-22, MZ0 + 5], [22, MZ0 + 5], [22, MZ1 - 5], [-22, MZ1 - 5]].map(([u, z]) => face(u, z, th))));
    trace.setAttribute("d", open(wave.map(([u, z]) => face(u, (MZ0 + MZ1) / 2 + z, th))));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, 0);
    const a = Math.round(clamp((Math.atan2(wy, wx) * 180) / Math.PI, 45 - sw, 45 + sw));
    ang.t = a;
    read.textContent = "turn " + (a - 45) + "°";
    B.wake();
  }
  function leave() { ang.t = REST; read.textContent = "rest"; B.wake(); }
  draw(REST);
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { sw = v; }, destroy: bag.dispose };
}

hairline({
  name: "dialysis",
  means: "A bedside monitor on a drip pole: the monitor head turns about the pole to face the pointer, its vitals trace turning with it.",
  rules: [1, 3, 5, 8],
  range: [30, 60, 80],
  tour: [[290, 150], [200, 260], [110, 150], null],
  mount,
});

scrubsrack.code:
/**
 * Scrubs lockers: a row of tall staff lockers, each with a door below and a
 * bin of folded scrubs above it. The pointer picks a locker by where it
 * stands: its bin slides out toward the viewer, and the bins beside it ease
 * out a little, staggered from it. At rest one bin is half out, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, ringAt, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 34, W = 30, D = 26, H = 74, BZ0 = 44, BZ1 = 58, OUT = 30, FAV = 1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  const X1 = (N - 1) * STEP + W;
  fit(C, [[0, 0, 0], [X1, 0, 0], [0, D + OUT + 2, 0], [X1, D + OUT + 2, 0], [0, 0, H], [X1, D, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg), gd = mk("g", {}, svg);
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP;
    const [r, i] = rings(x, 0, x + W, D, 3, 1.4);
    put(solid(g), prism(P, front, r, i, 0, H));
    // the door: a rounded panel line on the front face, and a latch dot
    const door = [[x + 4, BZ0 - 4], [x + W - 4, BZ0 - 4], [x + W - 4, 5], [x + 4, 5]].map(([u, z]) => P(u, D, z));
    mk("path", { d: poly(door), class: "nf lo" }, g);
    const latch = mk("circle", { r: 1.6, class: "dot off" }, g), lp = P(x + W - 8, D, BZ0 * 0.45);
    latch.setAttribute("cx", lp[0]); latch.setAttribute("cy", lp[1]);
    const bin = solid(gd), fold = mk("path", { class: "nf lo" }, bin.g);
    items.push({ k, x, bin, fold, o: tween(k === FAV ? OUT * 0.55 : 0), last: NaN });
  }

  function draw(it, o) {
    if (o === it.last) return;
    it.last = o;
    const [r, i] = rings(it.x + 3, D - 2, it.x + W - 3, D + 2 + o, 1.5, 1);
    put(it.bin, prism(P, front, r, i, BZ0, BZ1));
    // a folded stack of scrubs inside the bin, shown once it is out
    if (o > 6) {
      const f = rrect(it.x + 7, D + 1, it.x + W - 7, D + o - 1, 1.5, 3);
      it.fold.setAttribute("d", poly(ringAt(P, f, BZ1 + 0.01)));
    } else it.fold.setAttribute("d", "");
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.o, now)); if (!tdone(it.o, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + W / 2, D / 2, H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), o = a < 0 ? (k === FAV ? OUT * 0.55 : 0) : dd === 0 ? OUT : dd === 1 ? 8 : 0;
      tset(it.o, o, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.bin.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bay " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "scrubsrack",
  means: "A row of staff lockers: the bin of folded scrubs under the pointer slides out, and its neighbours ease out a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[142, 109], [222, 159], [305, 191], null],
  mount,
});

fondue.code:
/**
 * Fondue: a pot of melted cheese on a burner stand, four long forks dipped in
 * it. The pointer picks a fork by its handle: it draws up out of the pot
 * along its own shaft, and the forks beside it rise a little, staggered from
 * it. At rest one fork is half out, bright. The slider is the stagger.
 *
 * The pattern: one of many round a centre.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PR = 26, PZ0 = 12, PZ1 = 36, LIFT = 34, FAV = 2;
const ANG = [-140, -55, 25, 115], DIP = 9, OUT = 50, TOPZ = 84;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  const axes = ANG.map((a) => {
    const c = Math.cos(a * Math.PI / 180), s = Math.sin(a * Math.PI / 180);
    const D = [DIP * c, DIP * s, PZ1 - 4], E = [OUT * c, OUT * s, TOPZ];
    const L = Math.hypot(E[0] - D[0], E[1] - D[1], E[2] - D[2]);
    return { D, E, u: [(E[0] - D[0]) / L, (E[1] - D[1]) / L, (E[2] - D[2]) / L], c, s };
  });
  const ext = [[-34, -34, 0], [34, 34, 0], [34, -34, 0], [-34, 34, 0]];
  axes.forEach((a) => ext.push(a.E.map((v, i) => v + a.u[i] * LIFT)));
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the stand: a round foot, three short posts, the burner cup
  const [fr, fi] = [disc(0, 0, 32, 48), disc(0, 0, 30, 48)];
  put(solid(g), prism(P, front, fr, fi, 0, 3));
  for (const a of [200, 320]) { const c = Math.cos(a * Math.PI / 180) * 24, s = Math.sin(a * Math.PI / 180) * 24; put(solid(g), prism(P, front, disc(c, s, 2.4, 16), disc(c, s, 1.6, 16), 3, PZ0)); }
  put(solid(g), prism(P, front, disc(0, 0, 10, 28), disc(0, 0, 8.5, 28), 3, 9));
  for (const a of [80]) { const c = Math.cos(a * Math.PI / 180) * 24, s = Math.sin(a * Math.PI / 180) * 24; put(solid(g), prism(P, front, disc(c, s, 2.4, 16), disc(c, s, 1.6, 16), 3, PZ0)); }
  // the pot: a round body, a lip, the cheese inside
  put(solid(g), prism(P, front, disc(0, 0, PR, 56), disc(0, 0, PR - 2, 56), PZ0, PZ1));
  mk("path", { d: poly(ringAt(P, disc(0, 0, PR - 2, 56), PZ1)), class: "nf" }, g);
  mk("path", { d: open(ringAt(P, disc(0, 0, PR - 4, 56), PZ1 - 4).filter((p, i, arr) => i > arr.length * 0.08 && i < arr.length * 0.42)), class: "nf lo" }, g);
  // a handle on the pot
  put(solid(g), prism(P, front, rings(PR - 2, -3, PR + 12, 3, 3, 1)[0], rings(PR - 2, -3, PR + 12, 3, 3, 1)[1], PZ1 - 9, PZ1 - 5));

  const forks = axes.map((a, k) => {
    const grp = mk("g", {}, g);
    return { k, a, grp, shaft: mk("path", { class: "nf" }, grp), tines: mk("path", { class: "nf lo" }, grp), handle: mk("path", { class: "sil" }, grp), z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN };
  });
  // nearer forks paint last
  forks.slice().sort((p, q) => (p.a.c + p.a.s) - (q.a.c + q.a.s)).forEach((f) => g.appendChild(f.grp));

  const at = (a, t, l) => P(...a.D.map((v, i) => v + (a.E[i] - a.D[i]) * t + a.u[i] * l));
  function draw(f, l) {
    if (l === f.last) return;
    f.last = l;
    const a = f.a;
    f.shaft.setAttribute("d", open([at(a, 0, l), at(a, 0.72, l)]));
    const px = -a.s * 1.6, py = a.c * 1.6, tip = (sg) => P(a.D[0] + px * sg - a.u[0] * 5 + a.u[0] * l, a.D[1] + py * sg - a.u[1] * 5 + a.u[1] * l, a.D[2] - a.u[2] * 5 + a.u[2] * l);
    const b = at(a, 0, l);
    f.tines.setAttribute("d", seg(tip(1), b) + seg(tip(-1), b));
    const h0 = a.D.map((v, i) => v + (a.E[i] - a.D[i]) * 0.7 + a.u[i] * l), h1 = a.E.map((v, i) => v + a.u[i] * l);
    f.handle.setAttribute("d", poly(hull(ringAt(P, disc(h0[0], h0[1], 2.6, 16), h0[2]).concat(ringAt(P, disc(h1[0], h1[1], 3, 16), h1[2])))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const f of forks) { draw(f, tval(f.z, now)); if (!tdone(f.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const ends = axes.map((a) => at(a, 0.86, 0));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    ends.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 48 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    forks.forEach((f, k) => {
      const dd = Math.min(Math.abs(k - a), 4 - Math.abs(k - a)), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 10 : 0;
      const df = Math.min(Math.abs(k - from), 4 - Math.abs(k - from));
      tset(f.z, z, now, from < 0 ? 0 : df * stag);
      f.handle.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "fork " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "fondue",
  means: "A fondue pot with four long forks: the fork under the pointer draws up out of the cheese, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[190, 89], [275, 141], [197, 205], null],
  mount,
});

cakeboxes.code:
/**
 * Cake boxes: three square bakery boxes in a row on a counter, each tied with
 * a ribbon across its lid, a round cake inside. The pointer picks a box by
 * where it stands: its lid lifts off to show the cake, and the lids beside it
 * lift a little, staggered from it. At rest one lid is raised, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, open, prism, proj, rings, ringAt, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, W = 40, GAP = 10, H = 20, LH = 7, LIFT = 26, FAV = 1, CZ = 3;
const X1 = N * W + (N - 1) * GAP;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.8);
  fit(C, [[-6, -6, 0], [X1 + 6, W + 6, 0], [X1 + 6, -6, 0], [-6, W + 6, 0], [0, 0, CZ + H + LIFT + 2], [X1, 0, CZ + H + LIFT + 2]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-6, -6, X1 + 6, W + 6, 6, 2);
  put(solid(g), prism(P, front, cr, ci, 0, CZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * (W + GAP), grp = mk("g", {}, g), cx = x0 + W / 2, cy = W / 2;
    const [br, bi] = rings(x0, 0, x0 + W, W, 3, 1.4);
    put(solid(grp), prism(P, front, br, bi, CZ, CZ + H - 4));
    // the cake: a round tier standing proud of the box
    put(solid(grp), prism(P, front, disc(cx, cy, 14, 40), disc(cx, cy, 12.6, 40), CZ + H - 4, CZ + H + 3));
    const lid = solid(grp), rib = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x0, cx, cy, grp, lid, rib, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = CZ + H - LH + 1 + lift, z1 = z0 + LH, [r, i] = rings(it.x0 - 1, -1, it.x0 + W + 1, W + 1, 3.4, 1.4);
    put(it.lid, prism(P, front, r, i, z0, z1));
    // the ribbon: a cross over the lid and down its two near faces
    it.rib.setAttribute("d", seg(P(it.cx, -1, z1), P(it.cx, W + 1, z1)) + seg(P(-1 + it.x0, it.cy, z1), P(it.x0 + W + 1, it.cy, z1))
      + open([P(it.cx, W + 1, z1), P(it.cx, W + 1, z0)]) + open([P(it.x0 + W + 1, it.cy, z1), P(it.x0 + W + 1, it.cy, z0)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.cx, it.cy, CZ + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 6 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.lid.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "box " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "cakeboxes",
  means: "Three ribboned cake boxes in a row: the lid under the pointer lifts to show the cake, and its neighbours lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[136, 141], [200, 173], [264, 205], null],
  mount,
});

bookcase.code:
/**
 * Wall shelves: three floating shelves set at staggered heights on a wall,
 * each holding a book block and a vase. The pointer picks a shelf by its rest
 * top: what stands on it lifts off, and the shelves beside it stir a little,
 * staggered from it. At rest the middle shelf is bright, its things raised.
 * The slider is the stagger.
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SH = [[0, 74, 14], [50, 128, 46], [14, 92, 78]], D = 20, T = 3, LIFT = 14, FAV = 2;
const ITEMS = [[["b", 8, 16, 18], ["c", 54, 6, 13]], [["c", 64, 5, 10], ["b", 92, 22, 9]], [["b", 26, 10, 14], ["c", 70, 7, 16]]];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.55);
  fit(C, [[-6, -4, 0], [134, -4, 0], [134, D, 0], [-6, 0, 104], [134, 0, 104], [70, 10, 78 + T + 16 + LIFT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [wr, wi] = rings(-6, -4, 134, 0, 2, 0.8);
  put(solid(g), prism(P, front, wr, wi, 0, 104));

  const shelves = SH.map(([x0, x1, z], k) => {
    const grp = mk("g", {}, g), plate = solid(grp);
    const [r, i] = rings(x0, 0, x1, D, 3, 1.4);
    put(plate, prism(P, front, r, i, z, z + T));
    const its = ITEMS[k].map(([t, x, w, h]) => {
      const [ring, inner] = t === "b" ? rings(x, 4, x + w, 15, 1.5, 1) : [disc(x, 10, w), disc(x, 10, w - 1.5)];
      return { s: solid(grp), ring, inner, h, z0: z + T };
    });
    return { k, x0, x1, z, plate, its, lift: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN };
  });

  function draw(sh, lift) {
    if (lift === sh.last) return;
    sh.last = lift;
    for (const it of sh.its) put(it.s, prism(P, front, it.ring, it.inner, it.z0 + lift, it.z0 + lift + it.h));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const sh of shelves) { draw(sh, tval(sh.lift, now)); if (!tdone(sh.lift, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    for (const sh of shelves) {
      const [wx, wy] = unproj(C, sx, sy, sh.z + T);
      if (wx < sh.x0 - 4 || wx > sh.x1 + 4 || wy < -24 || wy > D + 6) continue;
      const dd = Math.abs(wy - D / 2);
      if (dd < bd) { bd = dd; best = sh.k; }
    }
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    for (const sh of shelves) {
      const dd = Math.abs(sh.k - a), z = a < 0 ? (sh.k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 3 : 0;
      tset(sh.lift, z, now, from < 0 ? 0 : Math.abs(sh.k - from) * stag);
      sh.plate.sil.classList.toggle("hi", sh.k === (a < 0 ? FAV : a));
    }
    read.textContent = a < 0 ? "rest" : "shelf " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "bookcase",
  means: "Three floating shelves on a wall: what stands on the shelf under the pointer lifts, and the shelves beside it stir.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[150, 194], [215, 184], [172, 119], null],
  mount,
});

ottoman.code:
/**
 * Storage ottoman: a padded box on four short feet with a hinged lid. At rest
 * the lid sits a little ajar and its front pull is the bright mark. With the
 * pointer over it the lid swings up on its back hinge and shows the folded
 * throw stored inside. The slider is how far the lid opens.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, ringAt, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid, flatDot, place, hull, rad, clamp,
} = HL;

const W = 96, Dp = 56, H = 36, LT = 7, FT = 4, REST = 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let open = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[0, 0, 0], [W, Dp, 0], [W, 0, 0], [0, Dp, 0], [0, 0, H + 40], [W, 0, H + 40]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  for (const [x, y] of [[8, 8], [W - 14, 8], [8, Dp - 14], [W - 14, Dp - 14]]) {
    const [r, i] = rings(x, y, x + 6, y + 6, 3, 1);
    put(solid(g), prism(P, front, r, i, 0, FT));
  }
  const [br, bi] = rings(0, 0, W, Dp, 9, 4);
  put(solid(g), prism(P, front, br, bi, FT, H));
  mk("path", { d: poly(ringAt(P, bi, H)), class: "lo" }, g);
  const [tr] = rings(10, 10, W - 10, Dp - 10, 6, 1);
  mk("path", { d: poly(ringAt(P, tr, H - 2)), class: "lo" }, g);
  mk("path", { d: seg(P(12, Dp / 2, H - 2), P(W - 12, Dp / 2 + 2, H - 2)), class: "nf lo" }, g);

  const lid = solid(g), pull = flatDot(g, C, 2.2, "dot");
  const [lr, li] = rings(0, 0, W, Dp, 9, 3);
  const rot = (a) => (u, v, dz) => { const c = Math.cos(a), s = Math.sin(a); return P(u, v * c - dz * s, H + v * s + dz * c); };
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const R = rot(rad(deg));
    const pts = lr.map((q) => R(q.u, q.v, 0)).concat(lr.map((q) => R(q.u, q.v, LT)));
    lid.sil.setAttribute("d", poly(hull(pts)));
    lid.cr.setAttribute("d", poly(li.map((q) => R(q.u, q.v, LT))));
    place(pull, R(W / 2, Dp + 1.5, LT * 0.45));
  }
  const ang = tween(REST);
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    return x > -6 && x < W + 6 && y > -30 && y < Dp + 8;
  }
  let on = null;
  function setOn(v, force) {
    if (v === on && !force) return;
    on = v;
    tset(ang, v ? clamp(open, 8, 34) : REST, performance.now(), 0);
    lid.sil.classList.toggle("hi", v);
    pull.setAttribute("class", v ? "dot off" : "dot");
    read.textContent = v ? "open " + Math.round(clamp(open, 8, 34)) + "°" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { open = v; if (on) setOn(true, true); }, destroy: bag.dispose };
}

hairline({
  name: "ottoman",
  means: "A storage ottoman: with the pointer over it the lid swings up on its back hinge to show the throw folded inside.",
  rules: [1, 4, 5, 8],
  range: [12, 30, 34],
  tour: [[172, 120], [200, 167], [228, 227], null],
  mount,
});

cuckooclock.code:
/**
 * Cuckoo clock: a house-shaped clock hung on a wall board, a peaked roof, a
 * round face, a little door for the bird, two weights on chains and a
 * pendulum under the case. The pointer's x swings the pendulum toward it on
 * a spring; leaving lets it settle back to a slight rest swing. The bob is
 * the bright mark. The slider is the largest swing.
 *
 * The pattern: one part answering a continuous input (aim).
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rad, rings, ringAt, rrect, run, seg,
  disposer, mk, pointer, put, register, solid, spring, stepS,
} = HL;

const PX = 30, PY = 12, PZ = 45, L = 34, BR = 6, REST = -14;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.05);
  const sw = (a) => [PX + (L + BR) * Math.sin(rad(a)), PY, PZ - (L + BR) * Math.cos(rad(a))];
  fit(C, [[-10, -6, 0], [70, -2, 0], [-10, -6, 122], [70, -2, 122], [54, 23, 88], [6, 23, 88], [30, 23, 104], sw(40), sw(-40)], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const vc = (x, y, z, r, n = 28) => { const pts = []; for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; pts.push(P(x + r * Math.cos(t), y, z + r * Math.sin(t))); } return pts; };

  // the wall board
  const [wr, wi] = rings(-10, -6, 70, -2, 1.5, 0.8);
  put(solid(g), prism(P, front, wr, wi, 0, 122));

  // weights on chains, behind the pendulum
  for (const [wx, wz] of [[19, 14], [41, 22]]) {
    mk("path", { d: seg(P(wx, 6, PZ), P(wx, 6, wz + 12)), class: "lo nf" }, g);
    put(solid(g), prism(P, front, disc(wx, 6, 3), disc(wx, 6, 2), wz, wz + 12));
  }

  // the case
  const [cr, ci] = rings(10, 0, 50, 20, 3, 1.5);
  put(solid(g), prism(P, front, cr, ci, PZ, 88));
  mk("path", { d: poly(vc(30, 20.05, 64, 11)), class: "nf" }, g);
  mk("path", { d: seg(P(30, 20.1, 64), P(30, 20.1, 72)) + seg(P(30, 20.1, 64), P(35, 20.1, 61)), class: "nf" }, g);
  mk("path", { d: poly([P(26, 20.05, 78), P(34, 20.05, 78), P(34, 20.05, 85), P(26, 20.05, 85)]), class: "nf lo" }, g);

  // the roof: a ridge narrower than its eaves
  const foot = rrect(6, -3, 54, 23, 2, 4), top = rrect(28, -3, 32, 23, 1, 4), inner = rrect(29, -2, 31, 22, 0.5, 4);
  put(solid(g), { sil: poly(hull(ringAt(P, foot, 88).concat(ringAt(P, top, 104)))), crease: open(ringAt(P, run(inner, front), 104)) });

  // the pendulum
  const rod = mk("path", { class: "nf" }, g), bob = mk("path", { class: "sil hi" }, g);
  const th = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    const ex = PX + L * s, ez = PZ - L * c, w = 0.8;
    rod.setAttribute("d", poly([P(PX - w * c, PY, PZ - w * s), P(PX + w * c, PY, PZ + w * s), P(ex + w * c, PY, ez + w * s), P(ex - w * c, PY, ez - w * s)]));
    bob.setAttribute("d", poly(vc(PX + (L + BR * 0.6) * s, PY + 0.1, PZ - (L + BR * 0.6) * c, BR)));
  }
  draw(REST);

  const B = register(stage, (dt) => {
    const moving = stepS(th, dt);
    draw(th.x);
    return moving;
  });
  bag.add(B.unregister);

  const cx = P(PX, PY, PZ)[0];
  function aim(t, label) {
    th.t = t;
    read.textContent = label ? (t >= 0 ? "+" : "") + Math.round(t) + "°" : "rest";
    B.wake();
  }
  aim(REST, false);
  bag.add(pointer(stage, {
    move: ([sx]) => aim(clamp((sx - cx) / 45, -1, 1) * amp, true),
    leave: () => aim(REST, false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; }, destroy: bag.dispose };
}

