  name: "cuckooclock",
  means: "A cuckoo clock on a wall board: the pendulum swings toward the pointer and settles back to a slight lean when it leaves.",
  rules: [1, 3, 5, 8],
  range: [10, 28, 40],
  tour: [[214, 282], [150, 276], [200, 150], null],
  mount,
});

corkboard.code:
/**
 * Corkboard: a framed pin board on the wall with six paper notes pinned along
 * their top edges. The pointer picks a note by its rest place: it swings out
 * on its pin, and the notes beside it stir, staggered from it. At rest one
 * note hangs a little open, bright. The slider is the stagger.
 */
const {
  Cam, fillet, fit, hull, poly, proj, rrect, tdone, tset, tval, tween,
  disposer, mk, place, pointer, register,
} = HL;

const W = 120, H = 84, T = 5, NH = 26, FAV = 4;
const NOTES = [[10, 74, 28, 2], [46, 76, 26, 0], [82, 73, 28, 3], [12, 38, 26, 1], [47, 40, 30, 7], [84, 37, 26, 0]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  const sw = (x0, zt, w, a) => [[x0, T + 0.4, zt], [x0 + w, T + 0.4, zt], [x0 + w, T + 0.4 + NH * Math.sin(a), zt - NH * Math.cos(a)], [x0, T + 0.4 + NH * Math.sin(a), zt - NH * Math.cos(a)]];
  fit(C, [[0, 0, 0], [W, 0, 0], [0, T, 0], [W, T, H], [0, T, H], ...sw(84, 37, 26, 1.1)], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const face = (ring, y) => ring.map((q) => P(q.u, y, q.v));
  // the frame: a vertical slab, hull of its back and front faces
  const outer = rrect(0, 0, W, H, 4, 4), inner = rrect(1.6, 1.6, W - 1.6, H - 1.6, 2.6, 4);
  mk("path", { d: poly(hull(face(outer, 0).concat(face(outer, T)))), class: "sil" }, g);
  mk("path", { d: poly(face(inner, T)), class: "nf lo" }, g);
  mk("path", { d: poly(face(rrect(6, 6, W - 6, H - 6, 1.5, 3), T)), class: "nf lo" }, g);

  const rest = (k) => (k === FAV ? 0.45 : NOTES[k][3] * 0.02);
  const items = NOTES.map(([x0, zt, w], k) => {
    const grp = mk("g", {}, g);
    const sheet = mk("path", { class: "sil" }, grp);
    const fold = mk("path", { class: "nf lo" }, grp);
    const pin = mk("circle", { r: 2.2, class: "dot off" }, grp);
    place(pin, P(x0 + w / 2, T + 0.6, zt - 3));
    return { k, x0, zt, w, grp, sheet, fold, pin, a: tween(rest(k)), last: NaN, c: P(x0 + w / 2, T, zt - NH / 2) };
  });

  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    const pts = sw(it.x0, it.zt, it.w, a).map((p) => P(...p));
    it.sheet.setAttribute("d", poly(fillet(pts, [1, 1, 1.5, 1.5], 3)));
    const f = 0.82, y = T + 0.4 + NH * f * Math.sin(a), z = it.zt - NH * f * Math.cos(a);
    it.fold.setAttribute("d", "M" + P(it.x0 + 3, y, z).join(" ") + "L" + P(it.x0 + it.w - 3, y, z).join(" "));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    items.forEach((it, k) => { const d = Math.hypot(it.c[0] - sx, it.c[1] - sy); if (d < bd) { bd = d; best = k; } });
    return bd < 34 ? best : -1;
  }
  const col = (k) => k % 3, row = (k) => Math.floor(k / 3);
  const dist = (i, j) => Math.max(Math.abs(col(i) - col(j)), Math.abs(row(i) - row(j)));

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act, on = a < 0 ? FAV : a;
    act = a;
    items[on].grp.parentNode.appendChild(items[on].grp);
    items.forEach((it, k) => {
      const d = dist(k, a), to = a < 0 ? rest(k) : d === 0 ? 1.1 : d === 1 ? 0.18 : rest(k);
      tset(it.a, to, now, from < 0 ? 0 : dist(k, from) * stag);
      it.sheet.classList.toggle("hi", k === on);
      it.pin.setAttribute("class", k === on ? "dot" : "dot off");
    });
    read.textContent = a < 0 ? "rest" : "note " + (col(a) + 1) + "·" + (row(a) + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "corkboard",
  means: "A framed pin board of paper notes: the note under the pointer swings out on its pin, and its neighbours stir.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[115, 58], [200, 150], [258, 229], null],
  mount,
});

businesscards.code:
/**
 * Business cards: a desk holder with a short stack of cards leaning on its
 * back rest. The pointer picks a card by where it stands along the stack: it
 * slides up out of the holder, and the cards beside it rise a little,
 * staggered from it. At rest one card stands proud, bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fillet, fit, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, facing, mk, pointer, put, register, solid,
} = HL;

const N = 5, GAP = 7, L = 52, D = 44, CH = 24, LEAN = 0.2, LIFT = 17, FAV = 2, Y0 = 5, Y1 = 39;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.6);
  fit(C, [[0, 0, 0], [L, D, 0], [L, 0, 0], [0, D, 0], [8, Y0, 4 + CH + LIFT + 2], [L, D, 12]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, x1, z1, r, b) => { const [o, i] = rings(x0, 0, x1, D, r, b); put(solid(g), prism(P, front, o, i, 0, z1)); };
  block(0, L, 3, 5, 1.6);
  block(0, 5, 20, 2, 1);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 11 + k * GAP, grp = mk("g", {}, g);
    const card = mk("path", { class: "sil" }, grp), line = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, card, line, z: tween(k === FAV ? 7 : k % 2 ? 1.5 : 0), last: NaN, c: P(x, (Y0 + Y1) / 2, 14) });
  }
  block(L - 5, L, 11, 2, 1);

  const at = (x, y, h, lift) => P(x - h * Math.sin(LEAN), y, 4 + lift + h * Math.cos(LEAN));
  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const pts = [at(it.x, Y0, 0, lift), at(it.x, Y1, 0, lift), at(it.x, Y1, CH, lift), at(it.x, Y0, CH, lift)];
    it.card.setAttribute("d", poly(fillet(pts, [1.5, 1.5, 1.5, 1.5], 3)));
    it.line.setAttribute("d", "M" + at(it.x + 0.2, Y0 + 5, CH - 6, lift).join(" ") + "L" + at(it.x + 0.2, Y0 + 19, CH - 6, lift).join(" "));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    items.forEach((it, k) => { const d = Math.abs(it.c[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 26 && Math.abs(items[best].c[1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), z = a < 0 ? (k === FAV ? 7 : k % 2 ? 1.5 : 0) : d === 0 ? LIFT : d === 1 ? 3.5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.card.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "card " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "businesscards",
  means: "A desk holder of business cards: the card under the pointer slides up out of the stack, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[162, 172], [197, 190], [233, 208], null],
  mount,
});

routerstack.code:
/**
 * Modem: a low home router with three hinged antennas along its back edge
 * and a row of status lights on its front. The pointer picks an antenna by
 * where it stands along the edge: it swings upright, and its neighbours
 * swing part way, staggered from it. At rest the antennas lie back at
 * different angles, one bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, hull, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, facing, mk, place, pointer, put, register, solid,
} = HL;

const L = 74, D = 42, H = 12, AL = 34, N = 3, FAV = 1, REST = [0.95, 0.3, 0.7];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[0, 0, 0], [L, D, 0], [L, 0, 0], [0, D, 0], [14, 5, H + AL + 3], [60, 5, H + AL + 3], [14, 5 - AL, H + 8]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [o, i] = rings(0, 0, L, D, 7, 1.8);
  put(solid(g), prism(P, front, o, i, 0, H));
  mk("path", { d: "M" + P(6, D, 4).join(" ") + "L" + P(L - 6, D, 4).join(" "), class: "nf lo" }, g);
  for (let k = 0; k < 4; k++) place(mk("circle", { r: 1.6, class: "dot off" }, g), P(12 + k * 7, D, 8));

  const ring = circ(2.4, 16);
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 14 + k * 23, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, ring.map((q) => ({ ...q, u: q.u + x, v: q.v + 5 })), circ(1.2, 16).map((q) => ({ ...q, u: q.u + x, v: q.v + 5 })), H, H + 3));
    const rod = mk("path", { class: "sil" }, grp);
    items.push({ k, x, rod, a: tween(REST[k]), last: NaN, c: P(x, 5, H + AL / 2) });
  }

  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    const pts = [];
    for (const [t, r] of [[0, 2], [1, 1.4]]) {
      const cy = 5 - (AL * t) * Math.sin(a), cz = H + 3 + (AL * t) * Math.cos(a);
      for (const q of ring) pts.push(P(it.x + q.u * r / 2.4, cy + q.v * r / 2.4 * Math.cos(a), cz + q.v * r / 2.4 * Math.sin(a)));
    }
    it.rod.setAttribute("d", poly(hull(pts)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    items.forEach((it, k) => { const d = Math.abs(it.c[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 30 && Math.abs(items[best].c[1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), to = a < 0 ? REST[k] : d === 0 ? -0.05 : d === 1 ? 0.45 : REST[k];
      tset(it.a, to, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.rod.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "ant " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "routerstack",
  means: "A home modem with three hinged antennas: the antenna under the pointer swings upright, and its neighbours swing part way.",
  rules: [1, 2, 5, 6],
  range: [0, 50, 100],
  tour: [[186, 109], [233, 133], [280, 156], null],
  mount,
});

ebookreaders.code:
/**
 * E-readers: four thin reading slates standing in the slots of a desk stand,
 * each with an inset screen and a page button. The pointer picks a slate by
 * where it stands: it slides up out of its slot, and the slates beside it
 * rise a little, staggered from it. At rest one slate is half out, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 17, T = 3.4, W = 34, H = 46, LIFT = 20, FAV = 2, BZ = 8;
const X0 = 6, X1 = X0 + (N - 1) * STEP + T + 6;
const REST = [3, 0, LIFT * 0.6, 1.5];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[0, -4, 0], [X1, W + 4, 0], [X1, -4, 0], [0, W + 4, 0], [X0, 0, BZ + H + LIFT], [X1, W, BZ + H + LIFT]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the stand: a low block with one slot per slate
  const [br, bi] = rings(0, -4, X1, W + 4, 5, 1.8);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  const slots = mk("path", { class: "nf lo" }, g);
  let sd = "";
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP;
    sd += poly([P(x - 0.8, 1, BZ), P(x + T + 0.8, 1, BZ), P(x + T + 0.8, W - 1, BZ), P(x - 0.8, W - 1, BZ)]);
  }
  slots.setAttribute("d", sd);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP, grp = mk("g", {}, g), s = solid(grp);
    const scr = mk("path", { class: "nf lo" }, grp), btn = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, s, scr, btn, z: tween(REST[k]), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = BZ - 6 + lift, z1 = z0 + H, x = it.x, f = x + T;
    const [r, ri] = rings(x, 0, f, W, 1.6, 0.7);
    put(it.s, prism(P, front, r, ri, z0, z1));
    it.scr.setAttribute("d", poly([P(f, 4, z0 + 9), P(f, W - 4, z0 + 9), P(f, W - 4, z1 - 4), P(f, 4, z1 - 4)]));
    it.btn.setAttribute("d", seg(P(f, W / 2 - 4, z0 + 4.5), P(f, W / 2 + 4, z0 + 4.5)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + T, W / 2, BZ + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 22 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? REST[k] : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "slate " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "ebookreaders",
  means: "Four e-readers in a desk stand: the slate under the pointer slides up out of its slot, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[152, 115], [187, 132], [249, 161], null],
  mount,
});

ringtoss.code:
/**
 * Ring toss: a board of nine pegs in a three-by-three field, a rope ring
 * round each peg's foot. The pointer picks a peg on the board: its ring is
 * tossed up over the peg's tip, and the rings around it hop a little,
 * staggered by distance. At rest one ring hangs above its peg, bright.
 * The slider is the stagger.
 *
 * The pattern: pick on the ground plane (terrain), lift (cloches).
 */
const {
  Cam, circ, fit, facing, poly, prism, proj, rings, ringAt, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 34, M = 16, BZ = 5, PH = 22, PR = 2.6, RR = 10, LIFT = 30, FAV = 4;
const W = (N - 1) * STEP + 2 * M;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[0, 0, 0], [W, W, 0], [W, 0, 0], [0, W, 0], [M, M, BZ + PH + LIFT + 4], [W - M, M, BZ + PH + LIFT + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, W, 7, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));

  const items = [];
  const order = [];
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) order.push([i, j]);
  order.sort((a, b) => a[0] + a[1] - (b[0] + b[1]));
  const byK = [];
  for (const [i, j] of order) {
    const k = i * N + j, x = M + i * STEP, y = M + j * STEP, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, y, PR, 16), disc(x, y, PR - 0.8, 16), BZ, BZ + PH));
    const outer = mk("path", { class: "sil nf" }, grp), inner = mk("path", { class: "nf lo" }, grp);
    byK[k] = { k, i, j, x, y, outer, inner, z: tween(k === FAV ? LIFT * 0.8 : 0), last: NaN };
  }
  items.push(...byK);

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z = BZ + 1 + lift;
    it.outer.setAttribute("d", poly(ringAt(P, disc(it.x, it.y, RR, 40), z)));
    it.inner.setAttribute("d", poly(ringAt(P, disc(it.x, it.y, RR - 3, 40), z)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, BZ);
    let best = -1, bd = Infinity;
    items.forEach((it, k) => { const d = Math.hypot(it.x - wx, it.y - wy); if (d < bd) { bd = d; best = k; } });
    return bd < STEP * 0.7 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const f = from >= 0 ? items[from] : it, dd = Math.max(Math.abs(it.i - f.i), Math.abs(it.j - f.j));
      const z = a < 0 ? (k === FAV ? LIFT * 0.8 : 0) : k === a ? LIFT : dd === 1 ? 10 : 0;
      tset(it.z, z, now, from < 0 ? 0 : dd * stag);
      it.outer.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "peg " + (items[a].i + 1) + "·" + (items[a].j + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "ringtoss",
  means: "A board of nine pegs: the ring on the peg under the pointer is tossed up over its tip, and the rings around it hop.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[200, 152], [291, 197], [200, 243], null],
  mount,
});

playkitchen.code:
/**
 * Toy chest: a long chest with a lid hinged along its back edge, a ball and a
 * block inside. The pointer over the chest opens the lid and the toys rise to
 * the rim. At rest the lid stands ajar, bright. The slider is how far it opens.
 *
 * The pattern: one object, one hinge (lid).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 64, D = 36, H = 30, T = 3.5, AJAR = 22;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.85);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, -8, H + D], [W, -8, H + D], [W, D, H + 4]], 200, 170);
  const P = proj(C), front = facing(C);
  const root = mk("g", {}, svg), lidG = mk("g", {}, root), boxG = mk("g", {}, root);
  const [ring, inner] = rings(0, 0, W, D, 4, 3);
  put(solid(boxG), prism(P, front, ring, inner, 0, H));
  const toysG = mk("g", {}, boxG);
  const ball = mk("path", {}, toysG), block = solid(toysG);
  const fr = run(ring, front), top = ringAt(P, fr, H), bot = ringAt(P, fr, 0);
  mk("path", { d: poly(top.concat(bot.slice().reverse())), class: "fo" }, boxG);
  mk("path", { d: open([top[0], ...bot, top[top.length - 1]]), class: "nf sil" }, boxG);
  mk("path", { d: open(top), class: "nf" }, boxG);
  const latch = [[W / 2 - 4, H - 3], [W / 2 + 4, H - 3], [W / 2 + 4, H - 10], [W / 2 - 4, H - 10]].map(([x, z]) => P(x, D, z));
  mk("path", { d: poly(latch), class: "nf lo" }, boxG);

  const lid = solid(lidG);
  lid.sil.classList.add("hi");
  const lr = rrect(0, 0, W, D, 4, 4), li = rrect(2, 2, W - 2, D - 2, 2.5, 4);
  const at = (q, a, t) => P(q.u, q.v * Math.cos(a) - t * Math.sin(a), H + q.v * Math.sin(a) + t * Math.cos(a));
  const ang = tween(AJAR), rise = tween(0);
  let lastA = NaN, lastR = NaN;

  function draw(now) {
    const a = tval(ang, now), r = tval(rise, now);
    if (a !== lastA) {
      lastA = a;
      const ar = (a * Math.PI) / 180;
      lid.sil.setAttribute("d", poly(hull(lr.map((q) => at(q, ar, 0)).concat(lr.map((q) => at(q, ar, T))))));
      lid.cr.setAttribute("d", poly(li.map((q) => at(q, ar, a > 90 ? 0 : T))));
      if (a > 40 && lidG.nextSibling !== boxG) root.insertBefore(lidG, boxG);
      if (a <= 40 && boxG.nextSibling !== lidG) root.append(lidG);
    }
    if (r !== lastR) {
      lastR = r;
      const bz = H - 12 + r * 10, pts = [];
      for (let i = -4; i <= 4; i++) { const t = (i / 4) * (Math.PI / 2); pts.push(...ringAt(P, disc(20, 17, 9 * Math.cos(t)), bz + 9 * Math.sin(t))); }
      ball.setAttribute("d", poly(hull(pts)));
      const [br, bi] = rings(36, 10, 50, 24, 2, 1.2);
      put(block, prism(P, front, br, bi, H - 14 + r * 8, H - 1 + r * 8));
    }
  }
  const B = register(stage, (_dt, now) => { draw(now); return !(tdone(ang, now) && tdone(rise, now)); });
  bag.add(B.unregister);

  const corners = [[0, 0, 0], [W, 0, 0], [W, D, 0], [0, D, 0], [0, 0, H], [W, 0, H], [W, D, H], [0, D, H]].map(([x, y, z]) => P(x, y, z));
  const xs = corners.map((p) => p[0]), ys = corners.map((p) => p[1]);
  const box = [Math.min(...xs), Math.min(...ys) - 20, Math.max(...xs), Math.max(...ys)];
  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    const now = performance.now();
    tset(ang, v ? maxA : AJAR, now, 0);
    tset(rise, v ? 1 : 0, now, v ? 120 : 0);
    read.textContent = v ? "open" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => setOn(sx > box[0] && sx < box[2] && sy > box[1] && sy < box[3]),
    leave: () => setOn(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; if (on) { tset(ang, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "playkitchen",
  means: "A toy chest: the pointer over it lifts the lid on its back hinge and the ball and block rise to the rim.",
  rules: [1, 3, 5, 6],
  range: [60, 100, 112],
  tour: [[192, 181], [164, 205], null],
  mount,
});

cargotrain.code:
/**
 * Cargotrain: four flat wagons on a rail line, each carrying a container.
 * The pointer picks a wagon by where it stands: its container is hoisted off
 * the deck, and the containers beside it rise a little, staggered from it.
 * At rest one container is half lifted, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 46, L = 40, W = 18, DZ = 8, CH = 16, LIFT = 26, FAV = 2;
const X1 = (N - 1) * STEP + L;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[-8, -6, 0], [X1 + 8, W + 6, 0], [X1 + 8, -6, 0], [-8, W + 6, 0], [0, 0, DZ + CH + LIFT + 2], [X1, W, DZ + CH + LIFT + 2]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // rails and sleepers
  let rd = "";
  for (let x = -8; x <= X1 + 8; x += 8) rd += seg(P(x, 1, 0), P(x, W - 1, 0));
  mk("path", { d: rd, class: "nf lo" }, g);
  mk("path", { d: seg(P(-8, 4, 0.5), P(X1 + 8, 4, 0.5)) + seg(P(-8, W - 4, 0.5), P(X1 + 8, W - 4, 0.5)), class: "nf" }, g);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * STEP, grp = mk("g", {}, g);
    for (const bx of [x0 + 5, x0 + L - 13]) {
      const [br, bi] = rings(bx, 3, bx + 8, W - 3, 2, 1);
      put(solid(grp), prism(P, front, br, bi, 0.5, DZ - 2));
    }
    const [dr, di] = rings(x0, 0, x0 + L, W, 2, 1.2);
    put(solid(grp), prism(P, front, dr, di, DZ - 2, DZ));
    const box = solid(grp);
    box.sil.classList.add("sil");
    const [cr, ci] = rings(x0 + 2, 1, x0 + L - 2, W - 1, 2.5, 1.6);
    items.push({ k, x0, grp, box, cr, ci, z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    put(it.box, prism(P, front, it.cr, it.ci, DZ + lift, DZ + CH + lift));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x0 + L / 2, W / 2, DZ + CH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.box.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "wagon " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "cargotrain",
  means: "Four flat wagons with containers: the wagon under the pointer has its container hoisted, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[120, 140], [174, 167], [280, 215], null],
  mount,
});

toolboard.code:
/**
 * Tool pegboard: a perforated board on the garage wall with hand tools
 * hanging from its pegs, a screwdriver, a chisel, a file, an awl, a punch.
 * The pointer picks a tool by where it stands: it slides up off its peg and
 * out toward you, and the tools beside it stir, staggered from it. At rest
 * one tool is half off its peg, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 130, H = 86, TY = 7, OUT = 16, UP = 8, FAV = 2;
// [handle radius, handle length, shaft radius, shaft length]
const TOOLS = [[4.2, 22, 1.4, 30], [3.6, 18, 2.4, 22], [3.2, 16, 2.8, 36], [3, 14, 1, 26], [3.8, 16, 1.8, 18]];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, -4, 0], [W, -4, 0], [W, TY + OUT + 5, 0], [0, TY + OUT + 5, 0], [0, -4, H], [W, -4, H], [W, TY + OUT + 5, H + UP]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the board, a thin slab on the wall, with its holes and a foot rail
  const [br, bi] = rings(0, -4, W, 0, 1.6, 0.8);
  put(solid(g), prism(P, front, br, bi, 0, H));
  for (let i = 0; i < 12; i++) for (let j = 0; j < 8; j++) {
    const [sx, sy] = P(8 + i * 10.4, 0, 8 + j * 10.2);
    mk("circle", { cx: sx, cy: sy, r: 0.9, class: "dot off" }, g);
  }
  const [rr, ri] = rings(-3, -4, W + 3, 6, 2, 1);
  put(solid(g), prism(P, front, rr, ri, 0, 4));

  const items = TOOLS.map(([hr, hl, sr, sl], k) => {
    const x = 16 + k * 24.5, top = H - 10, grp = mk("g", {}, g);
    // the peg: a short rod out of the board
    put(solid(grp), prism(P, front, [...disc(x, 2, 1.1, 12)].map((q) => q), disc(x, 2, 0.6, 12), top + 1, top + 2.6));
    const shaft = solid(grp), handle = solid(grp);
    return { k, x, hr, hl, sr, sl, top, shaft, handle, t: tween(k === FAV ? 0.55 : 0), last: NaN };
  });

  function draw(it, t) {
    if (t === it.last) return;
    it.last = t;
    const y = TY + OUT * t, z1 = it.top + UP * t, z0 = z1 - it.hl, y2 = y;
    put(it.handle, prism(P, front, disc(it.x, y, it.hr), disc(it.x, y, it.hr - 1.2), z0, z1));
    put(it.shaft, prism(P, front, disc(it.x, y2, it.sr, 16), disc(it.x, y2, Math.max(0.3, it.sr - 0.6), 16), z0 - it.sl, z0));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.t, now)); if (!tdone(it.t, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, TY, it.top - 20));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 18 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), t = a < 0 ? (k === FAV ? 0.55 : 0) : dd === 0 ? 1 : dd === 1 ? 0.18 : 0;
      tset(it.t, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      it.handle.sil.classList.toggle("hi", on);
      it.shaft.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "peg " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "toolboard",
  means: "Hand tools on a garage pegboard: the tool under the pointer slides up off its peg and out, its neighbours stir.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[146, 122], [206, 152], [267, 183], null],
  mount,
});

crates3.code:
/**
 * Shipping crates: three slatted crates of different heights in a row on a
 * pallet. The pointer picks a crate by where it stands: its lid lifts off,
 * and the crates beside it ease their lids a little, staggered from it. At
 * rest one lid sits ajar, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const D = 34, GAP = 6, LIFT = 20, FAV = 0, PZ = 5;
const CR = [[0, 30, 34], [36, 34, 26], [76, 28, 38]]; // [x0, width, height]
const X1 = 104;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-4, -4, 0], [X1 + 4, -4, 0], [X1 + 4, D + 4, 0], [-4, D + 4, 0], [0, 0, PZ + 34 + LIFT + 4], [X1, D, PZ + 38 + LIFT + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-4, -4, X1 + 4, D + 4, 2, 1);
  put(solid(g), prism(P, front, pr, pi, 0, PZ));

  const items = CR.map(([x0, w, h], k) => {
    const grp = mk("g", {}, g), x1 = x0 + w, z1 = PZ + h;
    const [br, bi] = rings(x0, 0, x1, D, 1.5, 1);
    put(solid(grp), prism(P, front, br, bi, PZ, z1));
    // slats on the two seen faces
    let d = "";
    for (let i = 1; i < 3; i++) {
      const z = PZ + (h * i) / 3;
      d += seg(P(x0 + 1, D, z), P(x1, D, z)) + seg(P(x1, 1, z), P(x1, D, z));
    }
    d += seg(P(x0 + 1, D, PZ + 1), P(x1 - 1, D, z1 - 1));
    mk("path", { d, class: "nf lo" }, grp);
    const lid = solid(grp);
    return { k, x0, x1, z1, lid, t: tween(k === FAV ? 0.45 : 0), last: NaN };
  });

  function draw(it, t) {
    if (t === it.last) return;
    it.last = t;
    const z = it.z1 + 1 + LIFT * t;
    const [lr, li] = rings(it.x0 - 1.5, -1.5, it.x1 + 1.5, D + 1.5, 2, 1.2);
    put(it.lid, prism(P, front, lr, li, z, z + 3));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.t, now)); if (!tdone(it.t, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P((it.x0 + it.x1) / 2, D / 2, PZ + (it.z1 - PZ) / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), t = a < 0 ? (k === FAV ? 0.45 : 0) : dd === 0 ? 1 : dd === 1 ? 0.2 : 0;
      tset(it.t, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.lid.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "crate " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "crates3",
  means: "Three slatted shipping crates on a pallet: the crate under the pointer lifts its lid, its neighbours ease theirs.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[145, 156], [199, 183], [256, 212], null],
  mount,
});

furnace.code:
/**
 * Furnace: a foundry ladle hung between two posts on its trunnions, over a
 * floor plate with a mould beside it. The pointer's reach to the right tips
 * the ladle on its pivot; past the pour angle a stream falls from the lip
 * into the mould and takes the bright. At rest the ladle leans a little,
 * bright. The slider is the farthest tilt.
 *
 * The pattern: one part tilting on a pivot (spring).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, seg, spring, stepS, clamp, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 20, H = 34, PIV = 22, PZ = 50, PY = 30, REST = 12, POUR = 38;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxT = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-40, -40, 0], [46, 40, 0], [46, -40, 0], [-40, 40, 0], [0, 0, PZ + 14], [-20, 0, PZ + 14]], 200, 172);
  const P = proj(C), front = facing(C);
  // a point on the ladle: local u across, w up from its base; tilted by a about the pivot
  const L = (u, v, w, a) => { const wr = w - PIV, c = Math.cos(a), s = Math.sin(a); return P(u * c + wr * s, v, PZ + wr * c - u * s); };
  const ring = (r, w, a, n = 32) => circ(r, n).map((q) => L(q.u, q.v, w, a));

  const g = mk("g", {}, svg);
  const [fr, fi] = rings(-40, -40, 46, 40, 8, 2);
  put(solid(g), prism(P, front, fr, fi, 0, 3));
  const post = (y) => { const [a, b] = rings(-5, y - 4, 5, y + 4, 3, 1.2); put(solid(g), prism(P, front, a, b, 3, PZ + 4)); };
  post(-PY);
  // the mould: a low block with a sprue cup
  const [mr, mi] = rings(14, -12, 40, 12, 3, 1.5);
  put(solid(g), prism(P, front, mr, mi, 3, 13));
  mk("path", { d: poly(ringAt(P, disc(26, 0, 4, 20), 13)), class: "nf lo" }, g);
  const body = mk("path", { class: "sil" }, g), mouth = mk("path", { class: "nf lo" }, g), band = mk("path", { class: "nf lo" }, g);
  const pin = mk("path", { class: "nf" }, g);
  const stream = mk("path", { class: "nf" }, g);
  post(PY);

  const sp = spring(rad(REST));
  let last = NaN, pouring = false;
  function draw(a) {
    if (a === last) return;
    last = a;
    body.setAttribute("d", poly(hull(ring(R - 3, 0, a).concat(ring(R, H, a)))));
    mouth.setAttribute("d", poly(ring(R - 1.5, H, a, 40)));
    band.setAttribute("d", open(ring(R - 0.6, PIV - 3, a, 40).filter((_, i) => i <= 8 || i >= 32)));
    pin.setAttribute("d", poly(hull(circ(3, 12).map((q) => L(q.u, PY - 4, PIV + q.v, a)).concat(circ(3, 12).map((q) => L(q.u, R - 1, PIV + q.v, a))))));
    const lip = L(R, 0, H, a);
    const on = a > rad(POUR);
    stream.setAttribute("d", on ? seg(lip, P(26, 0, 13)) + seg([lip[0] + 2, lip[1]], P(27.5, 0, 13)) : "");
    if (on !== pouring) { pouring = on; stream.classList.toggle("hi", on); body.classList.toggle("hi", !on); }
    read.textContent = Math.round(a * 180 / Math.PI) + "°" + (on ? " pour" : "");
  }
  body.classList.add("hi");
  draw(sp.x);

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  const cx = P(0, 0, PZ)[0];
  let here = false;
  function aim([sx]) { here = true; sp.t = rad(clamp((sx - cx + 40) / 130, 0, 1) * maxT); B.wake(); }
  function leave() { here = false; sp.t = rad(REST); B.wake(); }
  draw(sp.x);
  read.textContent = "rest";
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxT = v; if (here) B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "furnace",
  means: "A foundry ladle on its trunnions: the pointer tips it toward the mould, and past the pour angle a stream runs from the lip.",
  rules: [3, 4, 5, 8],
  range: [30, 60, 70],
  tour: [[150, 160], [250, 170], [320, 190], null],
  mount,
});

sawbench.code:
/**
 * Sawbench: a table saw, a cabinet under a broad top with a rip fence along
 * its back and a toothed blade standing in the throat. The pointer's
 * nearness raises the blade through the slot; it sinks back when the hand
 * leaves. At rest the blade stands a little proud, bright. The slider is
 * the farthest rise.
 *
 * The pattern: one part rising to the pointer's nearness (spring).
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rings, seg, spring, stepS, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const TOP = 30, BR = 24, REST = 4, TEETH = 28;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxH = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-44, -34, 0], [44, 34, 0], [44, -34, 0], [-44, 34, 0], [0, 0, TOP + 31]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [kr, ki] = rings(-32, -24, 32, 24, 4, 1.5);
  put(solid(g), prism(P, front, kr, ki, 0, TOP - 4));
  const [tr, ti] = rings(-44, -34, 44, 34, 4, 1.8);
  put(solid(g), prism(P, front, tr, ti, TOP - 4, TOP));
  // the throat plate and its slot
  mk("path", { d: poly([P(-30, -6, TOP), P(30, -6, TOP), P(30, 6, TOP), P(-30, 6, TOP)]), class: "nf lo" }, g);
  mk("path", { d: seg(P(-BR, 0, TOP), P(BR, 0, TOP)), class: "nf lo" }, g);
  // the rip fence along the back
  const [fr, fi] = rings(-44, -28, 44, -22, 2, 1);
  put(solid(g), prism(P, front, fr, fi, TOP, TOP + 7));
  const blade = mk("path", { class: "sil hi" }, g), hub = mk("path", { class: "nf lo" }, g);
  // the miter gauge in the near groove
  const [mr, mi] = rings(-30, 16, -14, 22, 2, 1);
  put(solid(g), prism(P, front, mr, mi, TOP, TOP + 4));

  const sp = spring(REST);
  let last = NaN;
  function draw(h) {
    if (h === last) return;
    last = h;
    const cz = TOP - BR + h, pts = [];
    for (let i = 0; i < TEETH * 2; i++) {
      const t = -Math.PI / 2 + (i / (TEETH * 2)) * Math.PI * 2, r = i % 2 ? BR - 2.6 : BR;
      pts.push([r * Math.cos(t), cz + r * Math.sin(t)]);
    }
    const out = [];
    for (let i = 0; i < pts.length; i++) {
      const [ax, az] = pts[i], [bx, bz] = pts[(i + 1) % pts.length];
      if (az >= TOP) out.push(P(ax, 0, az));
      if ((az - TOP) * (bz - TOP) < 0) { const f = (TOP - az) / (bz - az); out.push(P(ax + f * (bx - ax), 0, TOP)); }
    }
    blade.setAttribute("d", out.length > 2 ? poly(out) : "");
    const hp = [];
    for (let i = 0; i <= 24; i++) { const t = (i / 24) * Math.PI * 2, z = cz + 5 * Math.sin(t); if (z >= TOP + 0.5) hp.push(P(5 * Math.cos(t), 0, z)); }
    hub.setAttribute("d", hp.length > 2 ? open(hp) : "");
    read.textContent = "+" + Math.round(h);
  }
  draw(sp.x);
  read.textContent = "rest";

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  const c = P(0, 0, TOP);
  let here = false, near = 0;
  function aim([sx, sy]) { here = true; near = clamp(1 - Math.hypot(sx - c[0], (sy - c[1]) * 1.6) / 170, 0, 1); sp.t = REST + (maxH - REST) * near; B.wake(); }
  function leave() { here = false; sp.t = REST; B.wake(); }
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxH = v; if (here) { sp.t = REST + (maxH - REST) * near; B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "sawbench",
  means: "A table saw with a toothed blade in its throat: the nearer the pointer, the higher the blade rises through the slot.",
  rules: [3, 5, 8, 9],
  range: [14, 28, 30],
  tour: [[120, 150], [200, 170], [280, 200], null],
  mount,
});

pallets.code:
/**
 * Pallets: four wooden pallets in a row on a yard slab, each stacked with
 * bricks to a different height, the courses scored on the faces. The pointer
 * picks a pallet by where it stands: it rises as if on forks, and the pallets
 * beside it lift a little, staggered from it. At rest one pallet is raised,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, open, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 40, W = 30, DECK = 5, CO = 4, LIFT = 18, FAV = 2;
const HS = [5, 6, 4, 5];
const X1 = (N - 1) * STEP + W;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-6, -6, 0], [X1 + 6, W + 6, 0], [X1 + 6, -6, 0], [-6, W + 6, 0], [0, 0, DECK + 6 * CO + LIFT + 2], [X1, 0, DECK + 6 * CO + LIFT + 2]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-6, -6, X1 + 6, W + 6, 5, 2);
  put(solid(g), prism(P, front, sr, si, 0, 2));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, grp = mk("g", {}, g);
    const deck = solid(grp), slots = mk("path", { class: "nf lo" }, grp);
    const stack = solid(grp), courses = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, grp, deck, slots, stack, courses, h: HS[k] * CO, z: tween(k === FAV ? LIFT * 0.55 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const x0 = it.x, x1 = it.x + W, z0 = 2 + lift, zd = z0 + DECK;
    const [dr, di] = rings(x0, 0, x1, W, 1.5, 1);
    put(it.deck, prism(P, front, dr, di, z0, zd));
    // the fork slots: two dark openings on each near face of the deck
    let d = "";
    for (const f of [0.22, 0.62]) {
      const a = f * W, b = a + 0.16 * W;
      d += open([P(x0 + a, W, z0 + 1), P(x0 + a, W, zd - 1.2), P(x0 + b, W, zd - 1.2), P(x0 + b, W, z0 + 1)]);
      d += open([P(x1, a, z0 + 1), P(x1, a, zd - 1.2), P(x1, b, zd - 1.2), P(x1, b, z0 + 1)]);
    }
    it.slots.setAttribute("d", d);
    const [br, bi] = rings(x0 + 2, 2, x1 - 2, W - 2, 1.2, 1);
    put(it.stack, prism(P, front, br, bi, zd, zd + it.h));
    // courses, and the staggered joints between bricks
    let c = "";
    for (let i = 1; i * CO < it.h; i++) {
      const z = zd + i * CO;
      c += open([P(x0 + 2, W - 2, z), P(x1 - 2, W - 2, z), P(x1 - 2, 2, z)]);
    }
    for (let i = 0; i * CO < it.h; i++) {
      const z = zd + i * CO, o = i % 2 ? 0.5 : 0.25;
      for (const f of [o, o + 0.5].filter((v) => v < 0.95)) {
        const u = 2 + f * (W - 4);
        c += seg(P(x0 + u, W - 2, z), P(x0 + u, W - 2, z + CO)) + seg(P(x1 - 2, u, z), P(x1 - 2, u, z + CO));
      }
    }
    it.courses.setAttribute("d", c);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + W / 2, W / 2, DECK + it.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.55 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.stack.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "pallet " + (a + 1) + " · " + HS[a] + "c";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "pallets",
  means: "Brick-stacked pallets in a row: the pallet under the pointer rises as if on forks, its neighbours lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[150, 150], [228, 185], [272, 205], null],
  mount,
});

seedsower.code:
/**
 * Seedsower: a seed drill on soil, a long toolbar carrying five seed hoppers,
 * each with a lid and a coulter running down into a furrow. The pointer picks
 * a hopper by where it stands: its lid lifts open, and the lids beside it
 * crack a little, staggered from it. At rest one lid is up, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 30, W = 20, BAR = 10, HZ = 16, HH = 18, LIFT = 12, FAV = 1;
const X1 = (N - 1) * STEP + W;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-8, -10, 0], [X1 + 8, W + 10, 0], [X1 + 8, -10, 0], [-8, W + 10, 0], [0, 0, HZ + HH + LIFT + 4], [X1, 0, HZ + HH + LIFT + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-8, -10, X1 + 8, W + 10, 6, 2);
  put(solid(g), prism(P, front, sr, si, 0, 3));
  // furrows under each hopper, dashed, then the coulters and the toolbar
  let f = "";
  for (let k = 0; k < N; k++) f += seg(P(k * STEP + W / 2, -8, 3), P(k * STEP + W / 2, W + 8, 3));
  mk("path", { d: f, class: "nf dash" }, g);
  for (let k = 0; k < N; k++) {
    const cx = k * STEP + W / 2, [r, i] = rings(cx - 1.2, W / 2 - 5, cx + 1.2, W / 2 + 5, 1, 0.4);
    put(solid(g), prism(P, front, r, i, 3, BAR));
  }
  const [br, bi] = rings(-6, W / 2 - 2.5, X1 + 6, W / 2 + 2.5, 2, 0.8);
  put(solid(g), prism(P, front, br, bi, BAR, BAR + 3));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, grp = mk("g", {}, g);
    const [tr, ti] = rings(x + 7, W / 2 - 1.5, x + W - 7, W / 2 + 1.5, 1, 0.5);
    put(solid(grp), prism(P, front, tr, ti, BAR + 3, HZ));
    const [hr, hi] = rings(x, 0, x + W, W, 3, 1.5);
    put(solid(grp), prism(P, front, hr, hi, HZ, HZ + HH * (k % 2 ? 0.85 : 1)));
    const lid = solid(grp);
    items.push({ k, x, lid, top: HZ + HH * (k % 2 ? 0.85 : 1), z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const [lr, li] = rings(it.x - 1, -1, it.x + W + 1, W + 1, 3.5, 1.5);
    put(it.lid, prism(P, front, lr, li, it.top + lift, it.top + lift + 1.6));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + W / 2, W / 2, HZ + HH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 3 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.lid.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "row " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "seedsower",
  means: "A seed drill with five hoppers on a toolbar: the hopper under the pointer opens its lid, its neighbours crack open.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[150, 135], [200, 152], [250, 175], null],
  mount,
});

irrigationpump.code:
/**
 * Irrigation pump: a hand pump on a stone pad over a well, with a spout and a
 * bucket under it. The pointer's height works the handle: lower the pointer
 * and the handle swings down, the plunger rod rises, and a drop runs from the
 * spout into the bucket. At rest the handle stands raised, bright. The slider
 * is the handle's travel.
 *
 * The pattern: one part following the pointer (lever).
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rad, rings, ringAt, spring, stepS,
  disposer, mk, place, pointer, put, register, solid,
} = HL;

const PX = -8, PZ = 60, ARM = 40, TAIL = 10, REST = 28;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-32, -32, 0], [32, 32, 0], [PX - ARM, 0, PZ + ARM * Math.sin(rad(REST)) + 4], [PX - ARM, 0, PZ - ARM * Math.sin(rad(40))], [30, 0, 0]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const cyl = (x, y, r, z0, z1, b = 1.4) => put(solid(g), prism(P, front, disc(x, y, r), disc(x, y, r - b), z0, z1));
  const bar = (a, b, r) => poly(hull([a, b].flatMap(([x, y, z]) => ringAt(P, disc(x, y, r, 12), z - r).concat(ringAt(P, disc(x, y, r, 12), z + r)))));

  const [pr, pi] = rings(-30, -30, 30, 30, 7, 2);
  put(solid(g), prism(P, front, pr, pi, 0, 6));
  cyl(0, 0, 8, 6, 52, 1.6);
  cyl(0, 0, 10, 52, 56, 1.6);
  // fulcrum post on the cap
  const [fr, fi] = rings(PX - 3, -2.5, PX + 3, 2.5, 1.5, 0.8);
  put(solid(g), prism(P, front, fr, fi, 56, PZ));
  const rod = mk("path", { class: "nf" }, g);
  const handle = mk("path", { class: "sil" }, g);
  const grip = mk("path", { class: "nf" }, g);
  // spout, then the bucket under it
  const [sr, si] = rings(7, -3.2, 24, 3.2, 2.5, 0.9);
  put(solid(g), prism(P, front, sr, si, 40, 46));
  cyl(26, 0, 9, 6, 20, 1.4);
  const drop = mk("circle", { r: 2.2, class: "dot off" }, g);

  const sp = spring(0);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const th = rad(REST - t * swing), c = Math.cos(th), s = Math.sin(th);
    const end = [PX - ARM * c, 0, PZ + ARM * s], tail = [PX + TAIL * c, 0, PZ - TAIL * s];
    handle.setAttribute("d", bar(end, tail, 2.2));
    grip.setAttribute("d", bar([PX - (ARM - 2) * c, 0, PZ + (ARM - 2) * s], [PX - (ARM - 10) * c, 0, PZ + (ARM - 10) * s], 3));
    rod.setAttribute("d", bar([tail[0], 0, 54], tail, 1.2));
    place(drop, P(23, 0, clamp(39 - t * 22, 20, 39)));
    drop.setAttribute("class", t > 0.08 ? "dot m" : "dot off");
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  const top = P(PX - ARM * Math.cos(rad(REST)), 0, PZ + ARM * Math.sin(rad(REST)))[1];
  function move([, sy]) {
    const t = clamp((sy - top) / 90, 0, 1);
    sp.t = t;
    read.textContent = Math.round(t * 100) + "%";
    B.wake();
  }
  function leave() { sp.t = 0; read.textContent = "rest"; B.wake(); }
  handle.classList.add("hi");
  draw(0);
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; last = NaN; draw(sp.x); }, destroy: bag.dispose };
}

hairline({
  name: "irrigationpump",
  means: "A hand pump over a well: lower the pointer and the handle swings down, the rod rises and a drop runs into the bucket.",
  rules: [1, 3, 5, 8],
  range: [30, 60, 75],
  tour: [[155, 74], [150, 112], [149, 147], null],
  mount,
});

pumpkins.code:
/**
 * Pumpkins: four ribbed pumpkins of different sizes along a soil bed, each
 * with a stalk. The pointer picks a pumpkin by where it stands: it lifts off
 * the bed as if harvested, and the ones beside it rock up a little, staggered
 * from it. At rest the largest sits a little raised, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, extremes, fit, facing, hull, open, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SIZES = [[13, 15], [17, 20], [11, 13], [14, 16]], STEP = 34, Y = 20, BZ = 5, LIFT = 22, FAV = 1;
const X1 = 20 + (SIZES.length - 1) * STEP + 20;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-4, -2, 0], [X1 + 4, 2 * Y + 2, 0], [X1 + 4, -2, 0], [-4, 2 * Y + 2, 0], [54, Y, BZ + 2 * 20 + LIFT + 6], [20, Y, BZ + 30 + LIFT]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-4, -2, X1 + 4, 2 * Y + 2, 8, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  const near = extremes(P, circ(1, 64))[2], phi0 = Math.atan2(near.v, near.u);

  const items = SIZES.map(([R, H], k) => {
    const x = 20 + k * STEP, grp = mk("g", {}, g);
    const body = mk("path", { class: "sil" }, grp);
    const ribs = [0, 1, 2].map(() => mk("path", { class: "nf lo" }, grp));
    const stalk = mk("path", { class: "nf" }, grp);
    return { k, x, R, H, body, ribs, stalk, z: tween(k === FAV ? 8 : 0), last: NaN };
  });

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const { x, R, H } = it, z0 = BZ + lift, pts = [];
    for (let i = 0; i <= 8; i++) {
      const t = -Math.PI / 2 + (i / 8) * Math.PI;
      pts.push(...ringAt(P, disc(x, Y, R * Math.cos(t) + 0.3, 28), z0 + H * (1 + Math.sin(t)) / 2));
    }
    it.body.setAttribute("d", poly(hull(pts)));
    [-0.6, 0, 0.6].forEach((o, j) => {
      const f = phi0 + o * 1.1, line = [];
      for (let i = 1; i < 12; i++) {
        const t = -Math.PI / 2 + (i / 12) * Math.PI, rr = R * Math.cos(t) * 0.97;
        line.push(P(x + rr * Math.cos(f), Y + rr * Math.sin(f), z0 + H * (1 + Math.sin(t)) / 2));
      }
      it.ribs[j].setAttribute("d", open(line));
    });
    it.stalk.setAttribute("d", poly(hull(ringAt(P, disc(x, Y, 1.8, 12), z0 + H - 1).concat(ringAt(P, disc(x + 1.5, Y, 1.4, 12), z0 + H + 5)))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, Y, BZ + it.H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 28 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? 8 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "pick " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "pumpkins",
  means: "Four pumpkins on a soil bed: the one under the pointer lifts as if harvested, and its neighbours rock up a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[128, 150], [176, 165], [272, 222], null],
  mount,
});

smartmeter.code:
/**
 * Smart meter: a meter unit with a screen on its face and a dial beside it,
 * the screen showing six bars of the day's use. The pointer picks a bar by
 * where it stands on the screen: that bar rises tall, the bars beside it rise
 * a little, staggered from it. At rest the bars make a low evening peak, its
 * top bar bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, BW = 7, GAP = 3, X0 = 8, Y0 = 10, TOP = 16, TALL = 26, FAV = 4;
const REST = [4, 6, 5, 9, 14, 8];
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const bx = (k) => X0 + k * (BW + GAP);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.85);
  fit(C, [[0, 0, 0], [96, 0, 0], [0, 40, 0], [96, 40, 0], [bx(0), Y0, TOP + TALL + 2], [bx(N - 1), Y0, TOP + TALL + 2]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [mr, mi] = rings(0, 0, 96, 40, 7, 2);
  put(solid(g), prism(P, front, mr, mi, 0, TOP));
  const [sr] = rings(X0 - 3, Y0 - 4, bx(N - 1) + BW + 3, Y0 + 20, 3, 1);
  mk("path", { d: poly(ringAt(P, sr, TOP)), class: "nf lo" }, g);

  const items = [];
  for (let k = 0; k < N; k++) {
    const [r, ri] = rings(bx(k), Y0, bx(k) + BW, Y0 + BW, 2, 1);
    items.push({ k, s: solid(g), r, ri, z: tween(REST[k]), last: NaN });
  }
  // the dial: a disc with a pointer notch, beside the screen
  put(solid(g), prism(P, front, disc(80, 20, 9), disc(80, 20, 7.6), TOP, TOP + 2));
  mk("circle", { r: 2, class: "dot off", cx: P(80, 14, TOP + 2)[0], cy: P(80, 14, TOP + 2)[1] }, g);
  function draw(it, h) {
    if (h === it.last) return;
    it.last = h;
    put(it.s, prism(P, front, it.r, it.ri, TOP, TOP + h));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TOP);
    if (y < Y0 - 14 || y > Y0 + BW + 18 || x < X0 - 8 || x > bx(N - 1) + BW + 8) return -1;
    let best = 0;
    for (let k = 1; k < N; k++) if (Math.abs(bx(k) + BW / 2 - x) < Math.abs(bx(best) + BW / 2 - x)) best = k;
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? REST[k] : dd === 0 ? TALL : dd === 1 ? 11 : 4;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "hr " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "smartmeter",
  means: "A smart meter whose screen shows six bars of use: the bar under the pointer rises tall and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[140, 131], [180, 152], [240, 182], null],
  mount,
});

tidal.code:
/**
 * Wave buoys: four point-absorber floats in a row on a sea platform, each
 * riding a tall spar. At rest they sit at uneven heights like a passing
 * swell, one bright. The pointer picks a buoy by where it stands: its float
 * rides high up the spar, and the floats beside it rise a little, staggered
 * from it. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 42, FR = 13, FH = 9, SR = 2.2, TOP = 58, LIFT = 26, BZ = 4, FAV = 2;
const REST = [6, 12, 3, 9];
const X1 = (N - 1) * STEP + 2 * FR;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-8, -8, 0], [X1 + 8, 2 * FR + 8, 0], [X1 + 8, -8, 0], [-8, 2 * FR + 8, 0], [FR, FR, TOP + 4], [X1 - FR, FR, TOP + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-8, -8, X1 + 8, 2 * FR + 8, 8, 2);
  put(solid(g), prism(P, front, pr, pi, 0, BZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = FR + k * STEP, y = FR, grp = mk("g", {}, g);
    // the spar, standing through the float, and its foot on the platform
    put(solid(grp), prism(P, front, disc(x, y, 5, 24), disc(x, y, 3.6, 24), BZ, BZ + 2));
    put(solid(grp), prism(P, front, disc(x, y, SR, 16), disc(x, y, SR - 0.8, 16), BZ + 2, TOP));
    const fl = solid(grp), stub = solid(grp);
    fl.sil.classList.add("sil");
    put(solid(grp), prism(P, front, disc(x, y, 3.4, 16), disc(x, y, 2.4, 16), TOP, TOP + 2.4));
    items.push({ k, x, y, fl, stub, z: tween(REST[k] + (k === FAV ? 8 : 0)), last: NaN });
  }

  function draw(it, z) {
    if (z === it.last) return;
    it.last = z;
    const z0 = BZ + 2 + z, z1 = z0 + FH;
    put(it.fl, prism(P, front, disc(it.x, it.y, FR, 40), disc(it.x, it.y, FR - 2, 40), z0, z1));
    put(it.stub, prism(P, front, disc(it.x, it.y, SR, 16), disc(it.x, it.y, SR - 0.8, 16), z1, TOP));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, TOP / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a);
      const z = a < 0 ? REST[k] + (k === FAV ? 8 : 0) : dd === 0 ? LIFT : dd === 1 ? REST[k] + 6 : REST[k];
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.fl.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "buoy " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "tidal",
  means: "Four wave buoys on spars: the float under the pointer rides high up its spar, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[122, 116], [226, 152], [278, 194], null],
  mount,
});

biogas.code:
/**
 * Biogas dome: a floating-drum digester on a farm slab, a round tank with
 * a domed gas drum riding in its mouth, a feed inlet behind and a slurry
 * chute in front. The pointer's place across the figure is how much gas the
 * drum holds: the drum rises out of the tank on a spring as it fills. At
 * rest it floats a third up, bright. The slider is the drum's full rise.
 *
 * The pattern: one value, one part (a gauge).
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const TR = 34, TZ = 30, DR = 29, DH = 10, DOME = 11, BZ = 4, REST = 0.25;
const disc = (x, y, r, n = 56) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let rise = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-62, -48, 0], [48, 70, 0], [48, -48, 0], [-62, 70, 0], [0, 0, TZ + DH + DOME + 54]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-62, -48, 48, 70, 10, 2);
  put(solid(g), prism(P, front, sr, si, 0, BZ));
  // the feed inlet, behind the tank, and its pipe in
  put(solid(g), prism(P, front, disc(-46, -6, 9, 32), disc(-46, -6, 7.4, 32), BZ, BZ + 18));
  put(solid(g), prism(P, front, disc(-46, -6, 6, 24), disc(-46, -6, 4.6, 24), BZ + 18, BZ + 19));
  // the tank
  put(solid(g), prism(P, front, disc(0, 0, TR), disc(0, 0, TR - 2.2), BZ, TZ));
  mk("path", { d: poly(ringAt(P, disc(0, 0, DR + 1.4), TZ)), class: "lo" }, g);
  // the drum: wall from the tank's mouth up, then the dome, with its gas valve
  const drum = mk("path", { class: "sil hi" }, g), seam = mk("path", { class: "nf lo" }, g);
  const valve = solid(g);
  // the slurry chute, in front
  const [cr, ci] = rings(-9, 38, 9, 60, 3, 1.4);
  put(solid(g), prism(P, front, cr, ci, BZ, BZ + 12));
  const [cr2, ci2] = rings(-6, 41, 6, 57, 2, 1.2);
  mk("path", { d: poly(ringAt(P, cr2, BZ + 12)), class: "lo" }, g);
  void ci2;

  const lvl = spring(REST);
  let last = NaN;
  function draw(t) {
    const v = Math.round(t * 1000) / 1000;
    if (v === last) return;
    last = v;
    const z1 = TZ + DH * 0.4 + v * rise, pts = ringAt(P, disc(0, 0, DR), TZ);
    for (let i = 0; i <= 6; i++) { const a = (i / 6) * (Math.PI / 2); pts.push(...ringAt(P, disc(0, 0, DR * Math.cos(a), 40), z1 + DOME * Math.sin(a))); }
    drum.setAttribute("d", poly(hull(pts)));
    seam.setAttribute("d", open(ringAt(P, run(disc(0, 0, DR - 1.6), front), z1)));
    const vz = z1 + DOME;
    put(valve, prism(P, front, disc(0, 0, 3, 16), disc(0, 0, 2, 16), vz - 0.5, vz + 4));
  }

  const B = register(stage, (dt) => {
    const m = stepS(lvl, dt);
    draw(lvl.x);
    return m;
  });
  bag.add(B.unregister);

  const cx = P(0, 0, 0)[0];
  let shown = "";
  function aim(t) {
    lvl.t = t;
    const s = t === REST ? "rest" : "gas " + Math.round(t * 100) + "%";
    if (s !== shown) { shown = s; read.textContent = s; }
    B.wake();
  }
  aim(REST);
  bag.add(pointer(stage, {
    move: ([sx]) => aim(Math.round(clamp((sx - cx + 70) / 140, 0, 1) * 20) / 20 || 0.001),
    leave: () => aim(REST),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { rise = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "biogas",
  means: "A floating-drum biogas digester: the pointer's place across it is how full of gas the drum is, and the drum rises out of the tank.",
  rules: [1, 3, 5, 8],
  range: [12, 46, 52],
  tour: [[150, 160], [240, 170], [290, 178], null],
  mount,
});

safedeposit2.code:
/**
 * Vault drawers: a steel vault cabinet holding a column of four long
 * drawers, each with a pull bar. The pointer picks a drawer by its height:
 * it slides out of the cabinet, and the drawers beside it ease out a little,
 * staggered from it. At rest one drawer stands open a hand's width, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single column.
 */
const {
  Cam, fit, facing, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, D = 44, W = 56, H = 19, GAP = 2, OUT = 34, BZ = 6, FAV = 2;
const REST = [0, 2, 12, 0];
const TOPZ = BZ + N * (H + GAP) + 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-4, -4, 0], [D + OUT + 4, W + 4, 0], [-4, W + 4, 0], [D + OUT + 4, -4, 0], [0, 0, TOPZ], [D + OUT, W, TOPZ]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-4, -4, D + 6, W + 4, 4, 1.6);
  put(solid(g), prism(P, front, pr, pi, 0, BZ));
  const [cr, ci] = rings(0, 0, D, W, 3, 1.8);
  put(solid(g), prism(P, front, cr, ci, BZ, TOPZ));
  for (let k = 0; k < N; k++) {
    const z0 = BZ + 2 + k * (H + GAP);
    const a = P(D, 3, z0), b = P(D, W - 3, z0), c = P(D, W - 3, z0 + H), d = P(D, 3, z0 + H);
    mk("path", { d: "M" + a + "L" + b + "L" + c + "L" + d + "Z", class: "nf lo" }, g);
  }

  const items = [];
  for (let k = 0; k < N; k++) {
    const z0 = BZ + 2 + k * (H + GAP), grp = mk("g", {}, g), box = solid(grp);
    box.sil.classList.add("sil");
    const bar = mk("path", { class: "nf" }, grp);
    items.push({ k, z0, box, bar, x: tween(REST[k]), last: NaN });
  }

  function draw(it, x) {
    if (x === it.last) return;
    it.last = x;
    const [r, i] = rings(D - 1, 3, D + 2.4 + x, W - 3, 1.4, 1);
    put(it.box, prism(P, front, r, i, it.z0, it.z0 + H));
    const hx = D + 2.4 + x, zc = it.z0 + H / 2;
    it.bar.setAttribute("d", seg(P(hx, W / 2 - 9, zc), P(hx + 2.6, W / 2 - 9, zc)) + seg(P(hx + 2.6, W / 2 - 9, zc), P(hx + 2.6, W / 2 + 9, zc)) + seg(P(hx + 2.6, W / 2 + 9, zc), P(hx, W / 2 + 9, zc)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.x, now)); if (!tdone(it.x, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(D, W / 2, it.z0 + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][0] - sx) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), x = a < 0 ? REST[k] : dd === 0 ? OUT : dd === 1 ? 5 : 0;
      tset(it.x, x, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.box.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "row " + (N - a);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "safedeposit2",
  means: "A vault cabinet of four long drawers: the drawer at the pointer's height slides out, and the drawers beside it ease out a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[210, 110], [210, 179], [210, 221], null],
  mount,
});

goldscale.code:
/**
 * Coin scale: a balance on a plinth, a beam on a post, two pans hanging from
 * its ends, a stack of coins in the left pan and one coin in the right. The
 * pointer leans on the beam: the pan on its side sinks and the other rises,
 * on a spring. At rest the heavier pan hangs low, bright. The slider is the
 * reach of the tilt.
 *
 * The pattern: one continuous value, a lean (spring).
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rad, rings, ringAt, seg,
  disposer, mk, pointer, put, register, solid, spring, stepS,
} = HL;

const PX = 30, PY = 15, PZ = 64, HALF = 40, HANG = 30, MAX = 14, REST = 6, BR = 13;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.5);
  const lowZ = PZ - HALF * Math.sin(rad(MAX)) - HANG;
  fit(C, [[PX - HALF - BR, PY, lowZ], [PX + HALF + BR, PY, lowZ], [12, 0, 0], [48, 30, 0], [PX - HALF, PY, PZ + HALF * Math.sin(rad(MAX)) + 3], [PX + HALF, PY, PZ + HALF * Math.sin(rad(MAX)) + 3]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const mkPan = (coins) => {
    const grp = mk("g", {}, g);
    return { coins, grp, str: mk("path", { class: "lo nf" }, grp), bowl: mk("path", { class: "sil" }, grp), rim: mk("path", { class: "lo nf" }, grp),
      stack: coins ? solid(grp) : null };
  };
  const left = mkPan(4);
  const [br, bi] = rings(12, 0, 48, 30, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, 6));
  const [pr, pi] = rings(PX - 3, PY - 3, PX + 3, PY + 3, 3, 1);
  put(solid(g), prism(P, front, pr, pi, 6, PZ - 1));
  const right = mkPan(1);
  const beam = mk("path", { class: "sil" }, g);
  const knob = solid(g);
  put(knob, prism(P, front, disc(PX, PY, 3.2, 16), disc(PX, PY, 2.2, 16), PZ - 2, PZ + 3));

  function drawPan(pan, cx, ez) {
    const pz = ez - HANG, hook = P(cx, PY, ez - 1.5);
    let d = "";
    for (const a of [90, 210, 330]) d += seg(hook, P(cx + BR * Math.cos(rad(a)), PY + BR * Math.sin(rad(a)), pz + 3));
    pan.str.setAttribute("d", d);
    pan.bowl.setAttribute("d", poly(hull(ringAt(P, disc(cx, PY, BR), pz + 3).concat(ringAt(P, disc(cx, PY, 8), pz)))));
    pan.rim.setAttribute("d", poly(ringAt(P, disc(cx, PY, BR - 1.2), pz + 3)));
    if (pan.stack) put(pan.stack, prism(P, front, disc(cx + 1, PY, 5.5, 24), disc(cx + 1, PY, 4.5, 24), pz + 2, pz + 2 + 1.8 * pan.coins));
  }

  let last = NaN;
  function draw(e) {
    if (e === last) return;
    last = e;
    const s = Math.sin(rad(e)), c = Math.cos(rad(e));
    const lx = PX - HALF * c, lz = PZ - HALF * s, rx = PX + HALF * c, rz = PZ + HALF * s;
    const pts = [];
    for (const [x, z] of [[lx, lz], [rx, rz]]) for (const dy of [-1.5, 1.5]) for (const dz of [-1.5, 1.5]) pts.push(P(x, PY + dy, z + dz));
    beam.setAttribute("d", poly(hull(pts)));
    drawPan(left, lx, lz);
    drawPan(right, rx, rz);
    left.bowl.classList.toggle("hi", e > 1);
    right.bowl.classList.toggle("hi", e < -1);
  }

  const tilt = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(tilt, dt); draw(tilt.x); return m; });
  bag.add(B.unregister);

  const pv = P(PX, PY, PZ);
  function aim(sx) {
    const e = sx == null ? REST : -clamp((sx - pv[0]) / 90, -1, 1) * MAX * reach;
    tilt.t = e;
    read.textContent = sx == null ? "rest" : Math.abs(e) < 1 ? "level" : (e > 0 ? "L " : "R ") + Math.round(Math.abs(e)) + "°";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p[0]), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "goldscale",
  means: "A balance with coins in its pans: the pan on the pointer's side sinks and the other rises, and at rest the heavier one hangs low.",
  rules: [1, 3, 5, 8],
  range: [0.4, 0.8, 1],
  tour: [[129, 152], [271, 223], [200, 114], null],
  mount,
});

securitygate.code:
/**
 * Security gate: a barred panel on a ground track between a wall and a
 * latch post. The pointer's place along the track slides the gate open or
 * shut, sprung. At rest it stands part open, its edge bright. The slider is
 * how far it rests open.
 *
 * The pattern: one part following the pointer along a line.
 */
const {
  Cam, clamp, fit, facing, open, poly, prism, proj, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 96, H = 50, Z0 = 3, GMIN = -88, GMAX = 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let restOpen = value / 100;
  const C = Cam(45, 0.5, 1.45);
  fit(C, [[-104, -14, 0], [116, 12, 0], [-104, 12, 0], [116, -14, 0], [-104, -14, Z0 + H + 6], [116, 12, Z0 + H + 8]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-104, -14, 116, 12, 5, 2);
  put(solid(g), prism(P, front, br, bi, 0, Z0));
  // the back wall the gate slides along
  const [wr, wi] = rings(-100, -10, 0, -5, 1.5, 1);
  put(solid(g), prism(P, front, wr, wi, Z0, Z0 + H - 6));
  // the track, painted under the gate
  mk("path", { d: seg(P(-96, 2, Z0), P(104, 2, Z0)), class: "lo nf" }, g);
  mk("path", { d: seg(P(-96, 3.5, Z0), P(104, 3.5, Z0)), class: "lo nf" }, g);

  const gate = solid(g), bars = mk("path", { class: "lo nf" }, gate.g);
  gate.sil.classList.add("sil");
  // the latch post, nearest, so appended last
  const post = solid(g);
  const [pr, pi] = rings(102, -3, 110, 7, 2, 1);
  put(post, prism(P, front, pr, pi, Z0, Z0 + H + 8));
  post.sil.classList.add("sil");
  const latch = mk("path", { class: "nf" }, g);
  latch.setAttribute("d", poly([P(102, 4, Z0 + 26), P(102, 4, Z0 + 31), P(102, 6, Z0 + 31), P(102, 6, Z0 + 26)]));

  const restG = () => GMAX + (GMIN - GMAX) * restOpen;
  const sp = spring(restG());
  let last = NaN;
  function draw(x) {
    if (x === last) return;
    last = x;
    const [r, i] = rings(x, 0, x + W, 4, 1.5, 1);
    put(gate, prism(P, front, r, i, Z0 + 1, Z0 + H));
    let d = "";
    for (let b = x + 8; b < x + W - 4; b += 11) d += seg(P(b, 4, Z0 + 5), P(b, 4, Z0 + H - 5));
    d += seg(P(x + 3, 4, Z0 + 9), P(x + W - 3, 4, Z0 + 9)) + seg(P(x + 3, 4, Z0 + H - 9), P(x + W - 3, 4, Z0 + H - 9));
    bars.setAttribute("d", d);
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  let on = null;
  function aim(p) {
    if (!p) { on = null; sp.t = restG(); }
    else {
      const [wx, wy] = unproj(C, p[0], p[1], 0);
      if (Math.abs(wy) > 70 || wx < -110 || wx > 125) return aim(null);
      on = wx;
      sp.t = clamp(wx - W, GMIN, GMAX);
    }
    const pct = Math.round(((GMAX - sp.t) / (GMAX - GMIN)) * 100);
    gate.sil.classList.toggle("hi", on !== null);
    post.sil.classList.toggle("hi", on === null);
    read.textContent = on === null ? "rest" : "open " + pct + "%";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { restOpen = v / 100; if (on === null) aim(null); }, destroy: bag.dispose };
}

hairline({
  name: "securitygate",
  means: "A barred gate on a ground track: it slides open toward the wall as the pointer moves along the track, and shuts at the latch.",
  rules: [1, 3, 5, 8],
  range: [0, 30, 60],
  tour: [[297, 217], [252, 195], [109, 123], null],
  mount,
});

lockers2.code:
/**
 * Safety deposit: a wall of lock boxes, four across and three high, each
 * with a pull and a pair of keyholes. The pointer picks a box by its face:
 * it slides out of the wall, and the boxes beside it ease forward a little,
 * staggered from it. At rest one box stands part out, bright. The slider is
 * the stagger.
 *
 * The pattern: a grid on a face plane.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NC = 4, NR = 3, BW = 24, BH = 20, X0 = 4, Z0 = 6, W = X0 * 2 + NC * BW, D = 40, H = Z0 + NR * BH + 6, OUT = 34, FAV = 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.8);
  fit(C, [[-4, -4, 0], [W + 4, D + 4, 0], [W + 4, -4, 0], [-4, D + OUT + 4, 0], [-4, -4, H], [0, D + OUT, H - 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-4, -4, W + 4, D + 4, 4, 2);
  put(solid(g), prism(P, front, pr, pi, 0, 3));
  const [cr, ci] = rings(0, 0, W, D, 3, 1.5);
  const cab = solid(g);
  put(cab, prism(P, front, cr, ci, 3, H));
  cab.sil.classList.add("sil");

  const items = [];
  for (let r = 0; r < NR; r++) for (let c = 0; c < NC; c++) {
    const k = r * NC + c, x0 = X0 + c * BW + 1, x1 = x0 + BW - 2, z0 = Z0 + r * BH + 1, z1 = z0 + BH - 2;
    const s = solid(g), pull = mk("path", { class: "nf" }, s.g), keys = mk("path", { class: "lo nf" }, s.g);
    s.sil.classList.add("sil");
    items.push({ k, r, c, x0, x1, z0, z1, s, pull, keys, out: tween(k === FAV ? OUT * 0.55 : 0), last: NaN });
  }

  function draw(it, o) {
    if (o === it.last) return;
    it.last = o;
    const [rr, ri] = rings(it.x0, D, it.x1, D + 1.5 + o, 1.2, 0.6);
    put(it.s, prism(P, front, rr, ri, it.z0, it.z1));
    const y = D + 1.5 + o, xm = (it.x0 + it.x1) / 2, zm = (it.z0 + it.z1) / 2;
    it.pull.setAttribute("d", poly([P(xm - 5, y, zm - 4), P(xm + 5, y, zm - 4), P(xm + 5, y, zm - 2), P(xm - 5, y, zm - 2)]));
    it.keys.setAttribute("d", seg(P(xm - 4, y, zm + 2), P(xm - 4, y, zm + 5)) + seg(P(xm + 4, y, zm + 2), P(xm + 4, y, zm + 5)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.out, now)); if (!tdone(it.out, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P((it.x0 + it.x1) / 2, D, (it.z0 + it.z1) / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.hypot(m[0] - sx, m[1] - sy); if (d < bd) { bd = d; best = k; } });
    return bd < 26 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act, sel = a < 0 ? FAV : a;
    act = a;
    const fr = items[Math.max(from, 0)];
    items.forEach((it) => {
      const dd = a < 0 ? 9 : Math.abs(it.r - items[a].r) + Math.abs(it.c - items[a].c);
      const o = a < 0 ? (it.k === FAV ? OUT * 0.55 : 0) : dd === 0 ? OUT : dd === 1 ? 7 : 0;
      tset(it.out, o, now, from < 0 ? 0 : (Math.abs(it.r - fr.r) + Math.abs(it.c - fr.c)) * stag);
      it.s.sil.classList.toggle("hi", it.k === sel);
    });
    items.forEach((it) => g.appendChild(it.s.g));
    g.appendChild(items[sel].s.g);
    read.textContent = a < 0 ? "rest" : "box " + (items[a].r + 1) + "·" + (items[a].c + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "lockers2",
  means: "A wall of lock boxes: the box under the pointer slides out of the wall, and the boxes beside it ease forward a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[242, 233], [181, 171], [150, 125], null],
  mount,
});

beakerset.code:
/**
 * Distillation: four round-bottom flasks in cork rings along a bench tray,
 * each holding a level of liquid. The pointer picks a flask by where it
 * stands: it lifts out of its ring, and the flasks beside it rise a little,
 * staggered from it. At rest one flask is raised, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 36, BR = 13, NR = 3.2, NH = 20, LIFT = 22, FAV = 2, TZ = 4;
const X1 = (N - 1) * STEP + 2 * BR;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-6, -6, 0], [X1 + 6, 2 * BR + 6, 0], [X1 + 6, -6, 0], [-6, 2 * BR + 6, 0], [BR, BR, TZ + 2 * BR + NH + LIFT + 2], [X1 - BR, BR, TZ + 2 * BR + NH + LIFT + 2]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(-6, -6, X1 + 6, 2 * BR + 6, 6, 2);
  put(solid(g), prism(P, front, tr, ti, 0, TZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = BR + k * STEP, y = BR, grp = mk("g", {}, g);
    const flask = mk("path", { class: "sil" }, grp), liq = mk("path", { class: "nf lo" }, grp), neck = mk("path", { class: "sil" }, grp), lip = mk("path", { class: "nf" }, grp);
    // the cork ring the flask sits in, in front of its foot
    put(solid(grp), prism(P, front, disc(x, y, 8), disc(x, y, 6), TZ, TZ + 3));
    items.push({ k, x, y, flask, neck, liq, lip, lv: 0.35 + 0.15 * ((k * 3) % 4), z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const b = TZ + 1 + lift, cz = b + BR, pts = [];
    for (let i = -6; i <= 6; i++) { const t = (i / 6) * (Math.PI / 2); pts.push(...ringAt(P, disc(it.x, it.y, Math.max(BR * Math.cos(t), 0.5), 24), cz + BR * Math.sin(t))); }
    const top = cz + BR + NH;
    it.flask.setAttribute("d", poly(hull(pts)));
    it.neck.setAttribute("d", poly(hull(ringAt(P, disc(it.x, it.y, NR, 16), cz + BR * 0.85).concat(ringAt(P, disc(it.x, it.y, NR, 16), top)))));
    const lz = cz - BR + 2 * BR * it.lv * 0.8;
    it.liq.setAttribute("d", poly(ringAt(P, disc(it.x, it.y, Math.sqrt(BR * BR - (lz - cz) ** 2), 28), lz)));
    it.lip.setAttribute("d", poly(ringAt(P, disc(it.x, it.y, NR + 1, 16), top)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, TZ + BR + 6));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 28 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.flask.classList.toggle("hi", k === (a < 0 ? FAV : a));
      it.neck.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "flask " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "beakerset",
  means: "Four round-bottom flasks in cork rings: the flask under the pointer lifts out of its ring, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[126, 141], [175, 166], [274, 216], null],
  mount,
});

rocketstages.code:
/**
 * Rocket stages: a three-stage rocket with a nose cone, standing on a launch
 * pad. The pointer picks a stage by its height on screen: the joint under it
 * opens and everything above lifts away, the joints beside it part a little,
 * staggered from it. At rest the upper stage has already separated, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single column.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 11, PZ = 4, GAP = 18, FAV = 2;
const STAGES = [[0, 42, R], [0, 30, R], [0, 20, R - 1.5], [0, 22, 0]];
const disc = (r, n = 32) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  const TOT = STAGES.reduce((s, q) => s + q[1], 0);
  fit(C, [[-30, -30, 0], [30, 30, 0], [30, -30, 0], [-30, 30, 0], [0, 0, PZ + TOT + GAP + 10]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-30, -30, 30, 30, 8, 2);
  put(solid(g), prism(P, front, pr, pi, 0, PZ));
  // the launch ring: a low collar the first stage stands in
  put(solid(g), prism(P, front, disc(R + 5), disc(R + 3), PZ, PZ + 2));

  const parts = [];
  let base = PZ + 2;
  STAGES.forEach(([, h, r], k) => {
    const grp = mk("g", {}, g), s = solid(grp);
    const band = mk("path", { class: "nf lo" }, grp);
    parts.push({ k, z0: base, h, r, grp, s, band, gap: tween(k === FAV ? 7 : 0), last: NaN });
    base += h;
  });
  const top = base;

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = it.z0 + lift, z1 = z0 + it.h;
    if (it.k === 3) {
      // the nose: a cone tapering from the stage's radius to a point
      const foot = disc(R - 1.5), tip = disc(0.8, 12);
      it.s.sil.setAttribute("d", poly(hull(ringAt(P, foot, z0).concat(ringAt(P, tip, z1)))));
      it.s.cr.setAttribute("d", "");
      it.band.setAttribute("d", "");
      return;
    }
    put(it.s, prism(P, front, disc(it.r), disc(it.r - 1.5), z0, z1));
    // an interstage band: one dim ring a few units above the stage's foot
    const bz = z0 + Math.min(6, it.h * 0.2), ring = ringAt(P, disc(it.r), bz);
    it.band.setAttribute("d", "M" + ring.filter((_, i) => front(disc(it.r)[i])).map((p) => p.join(",")).join("L"));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false, acc = 0;
    for (const it of parts) { acc += tval(it.gap, now); draw(it, acc); if (!tdone(it.gap, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = parts.map((it) => P(0, 0, it.z0 + it.h / 2));
  function hit([sx, sy]) {
    if (Math.abs(sx - mids[0][0]) > 45) return -1;
    if (sy > P(0, 0, PZ)[1] + 10 || sy < P(0, 0, top + GAP)[1]) return -1;
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[1] - sy); if (d < bd) { bd = d; best = k; } });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    parts.forEach((it, k) => {
      const d = Math.abs(k - a), z = a < 0 ? (k === FAV ? 7 : 0) : d === 0 ? GAP : d === 1 ? 4 : 0;
      tset(it.gap, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : a === 3 ? "nose" : "stg " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

