satellitearray.code:
/**
 * Antenna dish: a ground-station dish on a pedestal, its feed held out on
 * three struts. The pointer on the ground is where the dish aims: it swings
 * round to that bearing and tips lower the farther the pointer is. At rest it
 * looks up and to the left, its feed lit. The slider is how far it may tip.
 *
 * The pattern: one part turning to face the pointer (aim).
 */
const {
  Cam, circ, clamp, fit, facing, hull, lerp, poly, prism, proj, rad, rings, seg, stepS, spring, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const H = 34, R = 32, DEPTH = 9, FEED = 26, AZ0 = rad(75), EL0 = rad(52);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let tip = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-46, -46, 0], [46, 46, 0], [46, -46, 0], [-46, 46, 0], [0, 0, H + 6 + R + 8], [-30, -30, H + 40], [30, 30, H + 30]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-46, -46, 46, 46, 10, 2);
  put(solid(g), prism(P, front, pr, pi, 0, 4));
  put(solid(g), prism(P, front, circ(14, 32), circ(12, 32), 4, 9));
  put(solid(g), prism(P, front, circ(6, 24), circ(4.8, 24), 9, H));
  const back = mk("g", {}, g), dish = mk("path", { class: "sil" }, g), bowl = mk("path", { class: "nf lo" }, g);
  const fore = mk("g", {}, g);
  const struts = mk("path", { class: "nf lo" }, fore), feed = mk("path", {}, fore), dot = mk("circle", { r: 2.4, class: "dot" }, fore);

  const az = spring(AZ0), el = spring(EL0);
  let last = "";
  const add = (a, b, s = 1) => [a[0] + b[0] * s, a[1] + b[1] * s, a[2] + b[2] * s];

  function draw() {
    const key = az.x.toFixed(4) + el.x.toFixed(4);
    if (key === last) return;
    last = key;
    const ca = Math.cos(az.x), sa = Math.sin(az.x), ce = Math.cos(el.x), se = Math.sin(el.x);
    const n = [ce * ca, ce * sa, se], u = [-sa, ca, 0], w = [-se * ca, -se * sa, ce];
    const piv = [0, 0, H + 4], c = add(piv, n, 6);
    const ring = (o, r, m = 40) => {
      const out = [];
      for (let i = 0; i < m; i++) { const t = (i / m) * Math.PI * 2, q = add(add(o, u, r * Math.cos(t)), w, r * Math.sin(t)); out.push(P(q[0], q[1], q[2])); }
      return out;
    };
    const rim = ring(c, R), rear = ring(add(c, n, -DEPTH), R * 0.35, 20);
    // the rim's winding on screen says whether the bowl faces the reader
    let area = 0;
    rim.forEach((p, i) => { const q = rim[(i + 1) % rim.length]; area += p[0] * q[1] - q[0] * p[1]; });
    const open_ = area > 0;
    dish.setAttribute("d", poly(hull(rim.concat(rear))));
    bowl.setAttribute("d", open_ ? poly(ring(add(c, n, -DEPTH * 0.45), R * 0.72)) : poly(rear));
    const f = add(c, n, FEED), fp = P(f[0], f[1], f[2]);
    let s = "";
    for (const t of [0.5, 0.5 + 2.094, 0.5 + 4.189]) {
      const q = add(add(c, u, R * 0.93 * Math.cos(t)), w, R * 0.93 * Math.sin(t));
      s += seg(P(q[0], q[1], q[2]), fp);
    }
    struts.setAttribute("d", s);
    const fb = add(f, n, -5);
    feed.setAttribute("d", poly(hull(ring(f, 2.6, 12).concat(ring(fb, 3.6, 12)))));
    dot.setAttribute("cx", fp[0]); dot.setAttribute("cy", fp[1]);
    // feed and struts sit in front of the bowl when it faces the reader, behind it when not
    if (open_) g.append(fore); else back.append(fore);
  }

  const B = register(stage, (dt) => {
    const a = stepS(az, dt), b = stepS(el, dt);
    draw();
    return a || b;
  });
  bag.add(B.unregister);

  let on = null;
  function aim(p) {
    const [gx, gy] = unproj(C, p[0], p[1], 0), d = Math.hypot(gx, gy);
    let t = Math.atan2(gy, gx);
    while (t - az.t > Math.PI) t -= Math.PI * 2;
    while (t - az.t < -Math.PI) t += Math.PI * 2;
    az.t = t;
    el.t = rad(clamp(lerp(78, 78 - 60 * (0.35 + 0.65 * tip), d / 140), 14, 78));
    if (on !== true) { on = true; dish.classList.add("hi"); dot.setAttribute("class", "dot m"); }
    const deg = Math.round(((t * 180 / Math.PI) % 360 + 360) % 360);
    read.textContent = "az " + deg;
    B.wake();
  }
  function rest() {
    az.t = AZ0 + Math.round((az.t - AZ0) / (Math.PI * 2)) * Math.PI * 2; el.t = EL0;
    on = false; dish.classList.remove("hi"); dot.setAttribute("class", "dot");
    read.textContent = "rest";
    B.wake();
  }
  rest();
  draw();
  bag.add(pointer(stage, { move: aim, leave: rest }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { tip = v; }, destroy: bag.dispose };
}

hairline({
  name: "satellitearray",
  means: "A ground-station dish on its pedestal: it swings round to the pointer's bearing and tips lower the farther away the pointer is.",
  rules: [1, 3, 4, 8],
  range: [0, 0.5, 1],
  tour: [[300, 200], [120, 230], [110, 120], null],
  mount,
});

foamrollers.code:
/**
 * Foam rollers: five upright rollers standing in the holes of a low gym rack,
 * each with two grip bands. The pointer picks a roller by where it stands:
 * it lifts out of its hole, and its neighbours rise a little, staggered from
 * it. At rest one roller is half drawn, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 24, R = 9, H = 46, LIFT = 24, FAV = 2, BZ = 6, X0 = 14;
const RX = X0 * 2 + (N - 1) * STEP;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[0, 0, 0], [RX, 28, 0], [RX, 0, 0], [0, 28, 0], [X0, 14, BZ + H + LIFT], [RX - X0, 14, BZ + H + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, RX, 28, 7, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP, y = 14, grp = mk("g", {}, g);
    mk("path", { d: poly(ringAt(P, disc(x, y, R + 1.2), BZ)), class: "nf lo" }, grp);
    const body = solid(grp), bands = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, y, body, bands, z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN });
  }

  const ring = (it) => disc(it.x, it.y, R), inner = (it) => disc(it.x, it.y, R - 1.6);
  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = BZ - 3 + lift, z1 = z0 + H;
    put(it.body, prism(P, front, ring(it), inner(it), z0, z1));
    const half = run(ring(it), front);
    it.bands.setAttribute("d", open(ringAt(P, half, z0 + H * 0.33)) + " " + open(ringAt(P, half, z0 + H * 0.66)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, BZ + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "roller " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "foamrollers",
  means: "Five foam rollers standing in a gym rack: the roller under the pointer lifts out of its hole, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[130, 139], [200, 156], [270, 209], null],
  mount,
});

guitaramps.code:
/**
 * Guitar amps: a four-speaker cabinet with an amp head on top, its front a
 * grille of four cones. The pointer picks the cone nearest it on the face:
 * that cone pushes out of the grille, and the cones beside it give a little,
 * staggered from it. At rest one cone sits pushed out, bright. The slider is
 * the stagger.
 *
 * The pattern: a grid on a face plane.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, clamp,
} = HL;

const W = 64, D = 30, H = 64, HZ = 18, CR = 12, PUSH = 7, FAV = 1;
const SP = [[17, 17], [47, 17], [17, 47], [47, 47]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, 0, H + HZ + 2], [W, D + PUSH, H + HZ + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(0, 0, W, D, 4, 1.8);
  put(solid(g), prism(P, front, cr, ci, 0, H));
  const [hr, hi] = rings(3, 3, W - 3, D - 2, 3, 1.4);
  put(solid(g), prism(P, front, hr, hi, H + 1, H + HZ));
  // the head's control strip: a dim line and a row of knob dots along its front
  mk("path", { d: poly([P(8, D - 2, H + HZ - 6), P(W - 8, D - 2, H + HZ - 6), P(W - 8, D - 2, H + 5), P(8, D - 2, H + 5)]), class: "nf lo" }, g);
  for (let i = 0; i < 5; i++) { const d = mk("circle", { r: 1.6, class: "dot off" }, g); const p = P(16 + i * 8, D - 2, H + HZ / 2 + 0.5); d.setAttribute("cx", p[0]); d.setAttribute("cy", p[1]); }

  const circle = (cx, cz, r, y, n = 32) => {
    const out = [];
    for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; out.push(P(cx + r * Math.cos(t), y, cz + r * Math.sin(t))); }
    return out;
  };
  const items = SP.map(([cx, cz], k) => {
    mk("path", { d: poly(circle(cx, cz, CR + 1.5, D)), class: "nf lo" }, g);
    const cone = mk("path", { class: "nf sil" }, g), cap = mk("path", { class: "nf" }, g);
    return { k, cx, cz, cone, cap, z: tween(k === FAV ? PUSH * 0.6 : 0), last: NaN };
  });
  items.sort((a, b) => b.cz - a.cz).forEach((it) => { g.append(it.cone); g.append(it.cap); });

  function draw(it, push) {
    if (push === it.last) return;
    it.last = push;
    it.cone.setAttribute("d", poly(circle(it.cx, it.cz, CR, D + push * 0.5)) + " " + poly(circle(it.cx, it.cz, CR * 0.55, D + push * 0.8)));
    it.cap.setAttribute("d", poly(circle(it.cx, it.cz, 3, D + push)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = SP.map(([cx, cz]) => P(cx, D, cz));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 ? best : -1;
  }

  let act = -2;
  const gd = (a, b) => Math.abs(SP[a][0] - SP[b][0]) / 30 + Math.abs(SP[a][1] - SP[b][1]) / 30;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it) => {
      const k = it.k, z = a < 0 ? (k === FAV ? PUSH * 0.6 : 0) : k === a ? PUSH : gd(k, a) === 1 ? 2 : 0;
      tset(it.z, z, now, from < 0 ? 0 : gd(k, from) * stag);
      it.cone.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "spk " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = clamp(v, 0, 90); }, destroy: bag.dispose };
}

hairline({
  name: "guitaramps",
  means: "A guitar cabinet with an amp head on top: the speaker cone nearest the pointer pushes out of the grille, its neighbours give a little.",
  rules: [1, 2, 5, 6],
