drummachine.code:
/**
 * Drum machine: a low rounded box with a four-by-four grid of rubber pads on
 * its top and two knobs along the back. The pointer picks a pad by where it
 * lands on the deck: that pad presses down, its neighbours dip after it,
 * staggered by distance. At rest the pads stand at uneven heights, one lit.
 * The slider is the stagger.
 *
 * The pattern: a grid on one plane; the hit is on the deck's fixed plane.
 */
const {
  Cam, circ, clamp, facing, fit, prism, proj, rings, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, PS = 13, GAP = 3, X0 = 2, Y0 = 2, TOP = 12, H = 4.2, PRESS = 3.6;
const W = X0 * 2 + N * PS + (N - 1) * GAP;
const REST = [0.2, 0.9, 0.4, 1.3, 0.6, 1.1, 0.1, 0.7, 1.2, 0.3, 0.8, 0.5, 0.4, 1.0, 0.6, 0.2];
const FAV = 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[-3, -20, 0], [W + 3, W + 3, 0], [W + 3, -20, 0], [-3, W + 3, 0], [W, -14, TOP + 9], [0, 0, TOP + H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [bo, bi] = rings(-3, -20, W + 3, W + 3, 9, 1.4);
  put(solid(g), prism(P, front, bo, bi, 0, TOP));
  // two knobs on the back strip
  [[14, -10, 4.2], [30, -10, 3.2]].forEach(([x, y, r]) => {
    const ring = circ(r, 16).map((s) => ({ ...s, u: s.u + x, v: s.v + y }));
    const inner = circ(r - 0.8, 16).map((s) => ({ ...s, u: s.u + x, v: s.v + y }));
    put(solid(g), prism(P, front, ring, inner, TOP, TOP + 5));
  });

  const pads = [];
  const order = [];
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) order.push([i, j]);
  order.sort((a, b) => a[0] + a[1] - b[0] - b[1]);
  order.forEach(([i, j]) => {
    const k = j * N + i, x = X0 + i * (PS + GAP), y = Y0 + j * (PS + GAP);
    const s = solid(g);
    pads[k] = { i, j, s, rg: rings(x, y, x + PS, y + PS, 3, 1), z: tween(H - REST[k]), last: NaN };
  });
  function draw(p, h) {
    if (h === p.last) return;
    p.last = h;
    put(p.s, prism(P, front, p.rg[0], p.rg[1], TOP, TOP + h));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    pads.forEach((p) => { draw(p, tval(p.z, now)); if (!tdone(p.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TOP + H * 0.7);
    if (x < -2 || x > W + 2 || y < -2 || y > W + 2) return -1;
    const i = clamp(Math.floor((x - X0 + GAP / 2) / (PS + GAP)), 0, N - 1);
    const j = clamp(Math.floor((y - Y0 + GAP / 2) / (PS + GAP)), 0, N - 1);
    return j * N + i;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    pads.forEach((p, k) => {
      let h = H - REST[k];
      let d = 0;
      if (a >= 0) {
        d = Math.hypot(p.i - (a % N), p.j - Math.floor(a / N));
        h = H - PRESS * Math.max(0.12, 1 - d / 2.2);
      } else if (from >= 0) d = Math.hypot(p.i - (from % N), p.j - Math.floor(from / N));
      tset(p.z, h, now, d * stag);
      p.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "pad " + ((a % N) + 1) + "·" + (Math.floor(a / N) + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "drummachine",
  means: "A drum machine's pad grid: the pad under the pointer presses down and its neighbours dip after it, by distance.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[182, 137], [182, 92], [182, 188], null],
  mount,
});

panflute.code:
/**
 * Chime bars: a stand of six metal tubes, longest to shortest, each hung on a
 * short cord from a rail held up by two posts on a base. The pointer picks a
 * tube by where it is along the row: that tube swings out towards the viewer,
 * its neighbours sway after it, staggered by distance. At rest the tubes hang
 * with a slight uneven lean, one lit. The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is the nearest rest
 * centre along screen x.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rad, rings, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, X0 = 6, STEP = 10, ZR = 84, CORD = 7, R = 2.7, SWING = 30;
const LEN = [56, 50, 44, 38, 33, 28];
const REST = [4, -2, 6, 1, -3, 3], FAV = 2;
const XE = X0 + (N - 1) * STEP;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.15);
  const far = Math.sin(rad(SWING)) * (CORD + LEN[0]);
  fit(C, [[-12, -12, 0], [XE + 12, 12, 0], [-12, 12, 0], [XE + 12, -12, 0], [-8, -2, ZR + 4], [XE + 8, 2, ZR + 4], [X0, far, 30]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [bo, bi] = rings(-12, -12, XE + 12, 12, 7, 1.4);
  put(solid(g), prism(P, front, bo, bi, 0, 4));
  function post(x) {
    const [o, i] = rings(x - 2.2, -2.2, x + 2.2, 2.2, 2, 0.6);
    put(solid(g), prism(P, front, o, i, 4, ZR));
  }
  post(-6);

  const tubes = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    tubes.push({
      k, x: X0 + k * STEP, L: LEN[k], a: tween(REST[k]), last: NaN,
      cord: mk("path", { class: "nf lo" }, grp), sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp),
    });
  }
  post(XE + 6);
  const [ro, ri] = rings(-9, -2.6, XE + 9, 2.6, 2.4, 0.8);
  put(solid(g), prism(P, front, ro, ri, ZR, ZR + 4));

  const ring = circ(R, 16);
  function at(cx, cy, z, ring0) { return ring0.map((s) => P(cx + s.u, cy + s.v, z)); }
  function draw(t, deg) {
    if (deg === t.last) return;
    t.last = deg;
    const sa = Math.sin(rad(deg)), ca = Math.cos(rad(deg));
    const y0 = CORD * sa, z0 = ZR - CORD * ca, y1 = (CORD + t.L) * sa, z1 = ZR - (CORD + t.L) * ca;
    t.cord.setAttribute("d", open([P(t.x, 0, ZR), P(t.x, y0, z0)]));
    t.sil.setAttribute("d", poly(hull(at(t.x, y0, z0, ring).concat(at(t.x, y1, z1, ring)))));
    t.cr.setAttribute("d", open(at(t.x, y0, z0, run(ring, front))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    tubes.forEach((t) => { draw(t, tval(t.a, now)); if (!tdone(t.a, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest rest centre along screen x, inside the stand's band
  const cx = tubes.map((t) => P(t.x, 0, ZR - CORD - t.L / 2)[0]);
  const top = P(0, 0, ZR + 4)[1], left = P(-12, 0, 0)[0], right = P(XE + 12, 0, 0)[0];
  const bot = P(XE, 12, 0)[1];
  function hit([sx, sy]) {
    if (sx < left || sx > right || sy < top - 6 || sy > bot) return -1;
    let best = 0;
    cx.forEach((c, k) => { if (Math.abs(sx - c) < Math.abs(sx - cx[best])) best = k; });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    tubes.forEach((t, k) => {
      const d = from < 0 ? 0 : Math.abs(k - from);
      const deg = a < 0 ? REST[k] : SWING * Math.max(0.1, 1 - Math.abs(k - a) / 3);
      tset(t.a, deg, now, d * stag);
      t.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bar " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

