tacotruck.code:
/**
 * Food truck: a box van with a cab, a service window on its long side and a
 * hinged hatch over it. The pointer over the truck swings the hatch up into
 * an awning above the counter; leaving lets it fall back to ajar. At rest the
 * hatch hangs a little open, bright. The slider is how far it opens.
 *
 * The pattern: one part swinging on a hinge.
 */
const {
  Cam, fit, facing, fillet, hull, poly, prism, proj, rings, unproj, clamp, tset, tval, tdone, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 120, W = 50, Z0 = 9, ZT = 60, HZ = 54, HL_ = 27, X0 = 24, X1 = 96, RW = 9;
const REST = 0.42;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = (value * Math.PI) / 180;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[-4, -4, 0], [152, -4, 0], [152, W + 4, 0], [-4, W + 4, 0], [0, 0, ZT], [L, W + HL_, HZ], [X0, W + HL_, HZ + 4]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  function wheel(cx, y0, y1) {
    const pts = [];
    for (let i = 0; i < 24; i++) {
      const t = (i / 24) * Math.PI * 2, x = cx + RW * Math.cos(t), z = RW + RW * Math.sin(t);
      pts.push(P(x, y0, z), P(x, y1, z));
    }
    const s = solid(g);
    s.sil.setAttribute("d", poly(hull(pts)));
    const hub = [];
    for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2; hub.push(P(cx + 3.5 * Math.cos(t), y1, RW + 3.5 * Math.sin(t))); }
    mk("path", { d: poly(hub), class: "nf lo" }, s.g);
  }
  wheel(24, -1, 6); wheel(132, -1, 6);
  const [br, bi] = rings(0, 0, L, W, 6, 2);
  put(solid(g), prism(P, front, br, bi, Z0, ZT));
  const [cr, ci] = rings(L - 2, 3, 150, W - 3, 9, 2);
  put(solid(g), prism(P, front, cr, ci, Z0, 44));
  mk("path", { d: poly(fillet([P(150, 9, 28), P(150, W - 9, 28), P(150, W - 9, 40), P(150, 9, 40)], [2, 2, 2, 2])), class: "nf lo" }, g);
  wheel(24, W - 6, W + 1); wheel(132, W - 6, W + 1);
  // the service window and its counter
  mk("path", { d: poly(fillet([P(X0 + 4, W, 31), P(X1 - 4, W, 31), P(X1 - 4, W, HZ - 3), P(X0 + 4, W, HZ - 3)], [2, 2, 2, 2])), class: "nf lo" }, g);
  const [kr, ki] = rings(X0 + 2, W, X1 - 2, W + 7, 1.5, 0.6);
  put(solid(g), prism(P, front, kr, ki, 28, 30));

  const flap = mk("path", { class: "sil" }, g), edge = mk("path", { class: "nf lo" }, g);
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const dy = HL_ * Math.sin(a), dz = -HL_ * Math.cos(a), ny = 1.6 * Math.cos(a), nz = 1.6 * Math.sin(a);
    const c = (x, t, o) => P(x, W + 0.5 + dy * t + ny * o, HZ + dz * t + nz * o);
    const r = [2, 2, 2, 2];
    flap.setAttribute("d", poly(hull([c(X0, 0, 0), c(X1, 0, 0), c(X1, 1, 0), c(X0, 1, 0), c(X0, 0, 1), c(X1, 0, 1), c(X1, 1, 1), c(X0, 1, 1)])));
    edge.setAttribute("d", poly(fillet([c(X0 + 1, 0.04, 1), c(X1 - 1, 0.04, 1), c(X1 - 1, 0.97, 1), c(X0 + 1, 0.97, 1)], r)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let on = null;
  function setOpen(o) {
    if (o === on) return;
    on = o;
    tset(ang, o ? maxA : REST, performance.now(), 0);
    read.textContent = o ? "open " + Math.round((maxA * 180) / Math.PI) + "°" : "rest";
    B.wake();
  }
  flap.classList.add("hi");
  setOpen(false);
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 30);
    return x > -6 && x < 156 && y > -6 && y < W + 16;
  }
  bag.add(pointer(stage, { move: (p) => setOpen(hit(p)), leave: () => setOpen(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = clamp(v, 40, 100) * Math.PI / 180; if (on) { on = null; setOpen(true); } }, destroy: bag.dispose };
}

hairline({
  name: "tacotruck",
  means: "A food truck with a hinged hatch: the pointer swings it up into an awning over the counter; at rest it hangs ajar.",
  rules: [1, 3, 5, 8],
  range: [40, 80, 100],
  tour: [[200, 170], [150, 185], [250, 160], null],
  mount,
});

cerealboxes.code:
/**
 * Cereal boxes: five tall boxes standing in a row on a pantry shelf, each
 * with a window panel on its face and a fold line on its top. The pointer
 * picks a box by where it stands: it slides forward off the row and rises a
 * little, and its neighbours ease out after it, staggered. At rest one box
 * stands pulled out, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, fillet, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, BW = 24, GAP = 3, D = 11, OUT = 16, FAV = 2;
const H = [44, 54, 50, 58, 42], REST = [2, 0, 11, 3, 1];
const X1 = N * (BW + GAP) - GAP;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-6, -6, 0], [X1 + 6, -6, 0], [X1 + 6, D + OUT + 8, 0], [-6, D + OUT + 8, -6], [0, 0, 64], [X1, OUT, 64]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-6, -6, X1 + 6, D + OUT + 8, 3, 1.5);
  put(solid(g), prism(P, front, sr, si, -5, 0));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = k * (BW + GAP), s = solid(g);
    const pan = mk("path", { class: "nf lo" }, s.g), fold = mk("path", { class: "nf lo" }, s.g);
    items.push({ k, x, s, pan, fold, y: tween(REST[k]), last: NaN });
  }

  function draw(it, y) {
    if (y === it.last) return;
    it.last = y;
    const h = H[it.k], z0 = y * 0.25, z1 = z0 + h, x = it.x, yf = y + D;
    const [r, ri] = rings(x, y, x + BW, yf, 2, 1);
    put(it.s, prism(P, front, r, ri, z0, z1));
    it.pan.setAttribute("d", poly(fillet([P(x + 5, yf, z0 + 10), P(x + BW - 5, yf, z0 + 10), P(x + BW - 5, yf, z1 - 14), P(x + 5, yf, z1 - 14)], [3, 3, 3, 3])));
    it.fold.setAttribute("d", seg(P(x + 3, y + D / 2, z1), P(x + BW - 3, y + D / 2, z1)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.y, now)); if (!tdone(it.y, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + BW / 2, D / 2, H[it.k] / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 28 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), y = a < 0 ? REST[k] : dd === 0 ? OUT : dd === 1 ? 4 : 0;
      tset(it.y, y, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "box " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "cerealboxes",
  means: "Five cereal boxes on a pantry shelf: the box under the pointer slides forward off the row, its neighbours easing after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[150, 150], [210, 170], [260, 190], null],
  mount,
});

smoothie.code:
/**
 * Smoothie: a blender on its motor base, a tapered jug with a fill line and
 * a handle, and a lid on top. The pointer picks a part by its height at
 * rest: over the lid, the lid lifts off; over the jug, the jug lifts off the
 * base carrying its lid. At rest the lid sits ajar, bright.
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, ringAt, rrect, run, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BZ = 16, JZ = 46, AJAR = 5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[-2, -2, 0], [32, 32, 0], [32, -2, 0], [-2, 32, 0], [15, 15, BZ + 2 + JZ + 44]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, 30, 30, 7, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  // the dial on the base's top rim, in front of the jug's foot
  const dial = mk("path", { class: "nf lo" }, g);
  dial.setAttribute("d", poly(ringAt(P, rrect(23, 23, 28, 28, 2.5, 4), BZ)));

  const jugG = mk("g", {}, g), lidG = mk("g", {}, g);
  const foot = rrect(5, 5, 25, 25, 5, 6), top = rrect(1, 1, 29, 29, 7, 6), inner = rrect(2.6, 2.6, 27.4, 27.4, 5.4, 6);
  const fillR = rrect(3, 3, 27, 27, 6, 6);
  const jug = solid(jugG), level = mk("path", { class: "nf lo" }, jugG), handle = mk("path", { class: "nf" }, jugG);
  const lid = solid(lidG), knob = mk("path", { class: "nf" }, lidG);
  const [lr, li] = rings(0, 0, 30, 30, 8, 1.6);
  const kr = rrect(12, 12, 18, 18, 3, 4);

  const jz = tween(0), lz = tween(AJAR);
  let lastJ = NaN, lastL = NaN;
  function draw(j, l) {
    if (j === lastJ && l === lastL) return;
    lastJ = j; lastL = l;
    const z0 = BZ + 2 + j, z1 = z0 + JZ;
    jug.sil.setAttribute("d", poly(hull(ringAt(P, foot, z0).concat(ringAt(P, top, z1)))));
    jug.cr.setAttribute("d", open(ringAt(P, run(inner, front), z1)));
    level.setAttribute("d", open(ringAt(P, run(fillR, front), z0 + JZ * 0.62)));
    handle.setAttribute("d", open([P(29, 15, z1 - 6), P(37, 15, z1 - 9), P(37, 15, z0 + 14), P(27, 15, z0 + 10)]));
    const lb = z1 + l;
    put(lid, prism(P, front, lr, li, lb, lb + 4));
    knob.setAttribute("d", poly(hull(ringAt(P, kr, lb + 4).concat(ringAt(P, kr, lb + 8)))));
  }

  const B = register(stage, (_dt, now) => {
    draw(tval(jz, now), tval(lz, now));
    return !(tdone(jz, now) && tdone(lz, now));
  });
  bag.add(B.unregister);

  const lidY = P(15, 15, BZ + 2 + JZ + 6)[1], jugY = P(15, 15, BZ + 2 + JZ * 0.45)[1], cx = P(15, 15, 0)[0];
  function hit([sx, sy]) {
    if (Math.abs(sx - cx) > 70) return -1;
    if (sy < lidY + 18 && sy > lidY - 50) return 0;
    if (Math.abs(sy - jugY) < 52) return 1;
    return -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    tset(jz, a === 1 ? 14 + lift * 0.3 : 0, now, 0);
    tset(lz, a === 0 ? 14 + lift : a === 1 ? 2 : AJAR, now, a === 1 ? 60 : 0);
    jug.sil.classList.toggle("hi", a === 1);
    lid.sil.classList.toggle("hi", a !== 1);
    read.textContent = a === 0 ? "lid" : a === 1 ? "jug" : "rest";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = v; act = -2; setActive(-1); }, destroy: bag.dispose };
}

hairline({
  name: "smoothie",
  means: "A blender: over the lid it lifts off the jug; over the jug, the jug lifts off its motor base with the lid riding on it.",
  rules: [1, 5, 6, 8],
  range: [0, 10, 20],
  tour: [[200, 123], [200, 182], [200, 110], null],
  mount,
});

picnicbasket.code:
/**
 * Picnic basket: a woven basket, its weave as dim bands round the front,
 * with a lid hinged along the back edge. The pointer over the basket swings
 * the lid open on its hinge to show the inside; leaving drops it back to
 * rest, where it sits ajar and bright.
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rad, rings, ringAt, rrect, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, unproj,
} = HL;

const W = 56, D = 36, Z = 26, T = 3, AJAR = 16;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.8);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, -4, Z + D + 4], [W, -4, Z + D + 4]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, D, 6, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, Z));
  const fr = run(br, front);
  for (const z of [7, 13, 19]) mk("path", { d: open(ringAt(P, fr, z)), class: "nf lo" }, g);
  // the inside: a dim wall line one weave in from the rim
  mk("path", { d: poly(ringAt(P, rrect(2.5, 2.5, W - 2.5, D - 2.5, 4.5, 6), Z)), class: "nf lo" }, g);

  const lid = solid(g), face = mk("path", { class: "nf lo" }, g), latch = mk("path", { class: "nf" }, g);
  const lr = rrect(-1, -1, W + 1, D + 1, 7, 6);
  const at = (a, t) => {
    const c = Math.cos(a), s = Math.sin(a);
    return lr.map((q) => { const dy = q.v + 1; return P(q.u, -1 + dy * c - t * s, Z + dy * s + t * c); });
  };
  const ang = tween(AJAR);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), lo = at(a, 0), hiR = at(a, T);
    lid.sil.setAttribute("d", poly(hull(lo.concat(hiR))));
    face.setAttribute("d", poly(deg < 54 ? hiR : lo));
    const c = Math.cos(a), s = Math.sin(a), dy = D + 1;
    const lx = W / 2, ly = -1 + dy * c, lz = Z + dy * s;
    latch.setAttribute("d", poly(hull([P(lx - 4, ly, lz), P(lx + 4, ly, lz), P(lx - 4, ly + 2 * s, lz - 5 * c), P(lx + 4, ly + 2 * s, lz - 5 * c)])));
  }

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    for (const z of [0, Z]) {
      const [x, y] = unproj(C, sx, sy, z);
      if (x > -8 && x < W + 8 && y > -8 && y < D + 8) return 1;
    }
    return -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(ang, a > 0 ? maxA : AJAR, performance.now(), 0);
    lid.sil.classList.add("hi");
    read.textContent = a > 0 ? "open" : "rest";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; act = -2; setActive(-1); }, destroy: bag.dispose };
}

hairline({
  name: "picnicbasket",
  means: "A woven picnic basket: the pointer over it swings the lid open on its back hinge; leaving lets it fall back ajar.",
  rules: [1, 5, 6, 8],
  range: [60, 85, 100],
  tour: [[196, 189], [216, 270], [176, 160], null],
  mount,
});

vanitydesk.code:
/**
 * Vanity desk: a slim desk on four legs, an oval mirror standing on its back
 * edge and three drawers in the apron. The pointer picks a drawer by where it
 * stands: it slides out, and the drawers beside it open a little, staggered
 * from it. At rest the middle drawer stands half open, bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 140, D = 44, LZ = 40, AZ = 54, TZ = 57, OUT = 26, FAV = 1;
const DX = [[6, 46], [50, 90], [94, 134]], REST = [4, 14, 0];
const MX = W / 2, MZ = 86, MA = 26, MB = 25;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.5);
  fit(C, [[-3, -3, 0], [W + 3, D + OUT, 0], [W + 3, -3, 0], [-3, D + OUT, 0], [MX - MA, 4, MZ + MB + 2], [MX + MA, 4, MZ + MB + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (parent, x0, y0, x1, y1, r, b, z0, z1, s) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(s || solid(parent), prism(P, front, o, i, z0, z1)); };

  for (const [x, y] of [[0, 0], [W - 4, 0], [0, D - 6], [W - 4, D - 6]]) box(g, x, y, x + 4, y + 4, 1.5, 0.8, 0, LZ);
  box(g, 0, 0, W, D - 2, 2, 1.4, LZ, AZ);
  box(g, -3, -3, W + 3, D, 3, 2, AZ, TZ);
  // the mirror: an oval frame on a low foot, standing at the back edge
  box(g, MX - 12, 1, MX + 12, 9, 2, 1.2, TZ, TZ + 3);
  const oval = (a, b, y) => { const pts = []; for (let i = 0; i < 48; i++) { const t = (i / 48) * Math.PI * 2; pts.push(P(MX + a * Math.cos(t), y, MZ + b * Math.sin(t))); } return pts; };
  mk("path", { d: poly(hull(oval(MA, MB, 3).concat(oval(MA, MB, 7)))), class: "sil" }, g);
  mk("path", { d: poly(oval(MA - 4, MB - 4, 7)), class: "nf lo" }, g);

  const items = DX.map(([x0, x1], k) => {
    const grp = mk("g", {}, g);
    const tray = solid(grp), plate = solid(grp), knob = mk("path", { class: "nf" }, grp);
    return { k, x0, x1, tray, plate, knob, o: tween(REST[k]), last: NaN };
  });

  function draw(it, o) {
    if (o === it.last) return;
    it.last = o;
    const y1 = D + o, xm = (it.x0 + it.x1) / 2;
    if (o > 3) box(null, it.x0 + 2, D - 2, it.x1 - 2, y1 - 1.5, 1.5, 1.2, LZ + 2, AZ - 2, it.tray);
    else { it.tray.sil.setAttribute("d", ""); it.tray.cr.setAttribute("d", ""); }
    box(null, it.x0, y1 - 2, it.x1, y1, 1, 0.6, LZ + 1, AZ - 1, it.plate);
    const ring = (y) => { const pts = []; for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2; pts.push(P(xm + 3 * Math.cos(t), y, (LZ + AZ) / 2 + 2.4 * Math.sin(t))); } return pts; };
    it.knob.setAttribute("d", poly(hull(ring(y1).concat(ring(y1 + 2)))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.o, now)); if (!tdone(it.o, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P((it.x0 + it.x1) / 2, D, (LZ + AZ) / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 && Math.abs(mids[best][1] - sy) < 45 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), o = a < 0 ? REST[k] : dd === 0 ? OUT : dd === 1 ? 6 : 0;
      tset(it.o, o, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.plate.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "drawer " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "vanitydesk",
  means: "A vanity desk with an oval mirror: the drawer under the pointer slides out, and its neighbours open a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[142, 146], [189, 170], [236, 193], null],
  mount,
});

skeeball.code:
/**
 * Skee ball: three arcade lanes side by side, each a long alley ending in a
 * raised target box with ring holes on its top. The pointer picks a lane by
 * where it stands: that lane's ball rolls up the alley into the rings, and
 * the balls beside it start a little, staggered from it. At rest one ball
 * is halfway up its lane, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, lerp, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, W = 28, STEP = 36, L = 110, BOX = 30, BH = 16, LZ = 4, R = 8, FAV = 1;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  const X1 = (N - 1) * STEP + W;
  fit(C, [[-2, -BOX - 2, 0], [X1 + 2, L + 2, 0], [X1 + 2, -BOX - 2, BH + 2 * R + 2], [-2, L + 2, 0], [-2, -BOX - 2, BH + 2 * R + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * STEP, xc = x0 + W / 2, grp = mk("g", {}, g);
    const [lr, li] = rings(x0, 0, x0 + W, L, 4, 1.6);
    put(solid(grp), prism(P, front, lr, li, 0, LZ));
    mk("path", { d: poly(ringAt(P, rings(x0 + 5, 4, x0 + W - 5, L - 4, 3, 1)[0], LZ)), class: "nf lo" }, grp);
    const [br, bi] = rings(x0, -BOX, x0 + W, 0, 5, 1.8);
    put(solid(grp), prism(P, front, br, bi, 0, BH));
    for (const r of [11, 7, 3]) mk("path", { d: poly(ringAt(P, disc(xc, -BOX / 2, r, 32), BH)), class: "nf lo" }, grp);
    const ball = mk("path", { class: "sil" }, grp);
    items.push({ k, xc, ball, t: tween(k === FAV ? 0.45 : 0), last: NaN });
  }

  function draw(it, t) {
    if (t === it.last) return;
    it.last = t;
    const y = lerp(L - 12, -BOX / 2, t);
    const z = (y > 0 ? LZ : BH) + R - (y > 0 ? 0 : 3);
    const pts = [];
    for (let i = -3; i <= 3; i++) { const a = (i / 3) * (Math.PI / 2); pts.push(...ringAt(P, disc(it.xc, y, R * Math.cos(a) + 0.01, 20), z + R * Math.sin(a))); }
    it.ball.setAttribute("d", poly(hull(pts)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.t, now)); if (!tdone(it.t, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.xc, L / 2, LZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    items.forEach((it, k) => {
      const a = P(it.xc, -BOX, 0), b = P(it.xc, L, 0);
      const u = Math.max(0, Math.min(1, ((sx - a[0]) * (b[0] - a[0]) + (sy - a[1]) * (b[1] - a[1])) / ((b[0] - a[0]) ** 2 + (b[1] - a[1]) ** 2)));
      const dd = Math.hypot(sx - lerp(a[0], b[0], u), sy - lerp(a[1], b[1], u));
      if (dd < bd) { bd = dd; best = k; }
    });
    return bd < 26 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), t = a < 0 ? (k === FAV ? 0.45 : 0) : dd === 0 ? 1 : dd === 1 ? 0.2 : 0;
      tset(it.t, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.ball.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "lane " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "skeeball",
  means: "Three skee ball lanes: the ball in the lane under the pointer rolls up the alley into the target rings; its neighbours start a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[137, 173], [181, 195], [226, 217], null],
  mount,
});

xylophonetoy.code:
/**
 * Xylophone pull toy: a low cart on four wheels, five bars of falling length
 * across its deck, a mallet on a stick, and a pull string ending in a bead
 * handle on the floor. The pointer pulls: the further ahead of the cart it is
 * on the floor, the further the toy rolls toward it, the wheels turning with
 * it and the mallet bobbing on the bars. At rest the string lies slack, its
 * handle bright. The slider is how far the string can pull.
 *
 * The pattern: a continuous input (where) on the floor plane, which never
 * moves; one spring carries the whole toy.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, ringAt, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 46, W = 22, ZB = 7, ZT = 12, R = 6.5, TH = 2.4, WX = [9, 37];
const BARS = [[6, 20], [14, 18], [22, 16], [30, 14], [38, 12]];
const HX = L + 22, HY = W / 2 + 6, MAXD = 26;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.6);
  fit(C, [[-R, -2, 0], [L + MAXD, W + 3, 0], [HX + MAXD + 3, HY + 3, 0], [0, 0, ZT + 14], [L + MAXD, W, ZT + 14], [-R, W + 3, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // a wheel: a disc standing in the x–z plane, from y0 to y1, with a hub and two spokes on its outer face
  function wheel(parent, y0, y1, face) {
    const s = solid(parent);
    const sp = mk("path", { class: "nf lo" }, s.g);
    return { s, sp, y0, y1, face };
  }
  function drawWheel(w, cx, ang) {
    const a = [], b = [];
    for (let i = 0; i < 28; i++) {
      const t = (i / 28) * Math.PI * 2;
      a.push(P(cx + R * Math.cos(t), w.y0, R + R * Math.sin(t)));
      b.push(P(cx + R * Math.cos(t), w.y1, R + R * Math.sin(t)));
    }
    w.s.sil.setAttribute("d", poly(hull(a.concat(b))));
    const f = w.face, rim = [], hub = [];
    for (let i = 0; i < 28; i++) {
      const t = (i / 28) * Math.PI * 2;
      rim.push(P(cx + (R - 1.2) * Math.cos(t), f, R + (R - 1.2) * Math.sin(t)));
      hub.push(P(cx + 1.3 * Math.cos(t), f, R + 1.3 * Math.sin(t)));
    }
    let d = poly(rim) + poly(hub);
    for (let k = 0; k < 2; k++) {
      const t = ang + (k * Math.PI) / 2, c = Math.cos(t), s = Math.sin(t);
      d += seg(P(cx + 1.3 * c, f, R + 1.3 * s), P(cx + (R - 1.2) * c, f, R + (R - 1.2) * s));
      d += seg(P(cx - 1.3 * c, f, R - 1.3 * s), P(cx - (R - 1.2) * c, f, R - (R - 1.2) * s));
    }
    w.sp.setAttribute("d", d);
  }

  // back to front: far wheels, the cart, its bars, the mallet, the near wheels, then the string and handle on the floor
  const far = WX.map(() => wheel(g, -TH, 0, -TH));
  const cart = solid(g);
  const bars = BARS.map(() => solid(g));
  const post = solid(g);
  const stick = mk("path", { class: "nf" }, g);
  const head = solid(g);
  const near = WX.map(() => wheel(g, W, W + TH, W + TH));
  const string = mk("path", { class: "nf" }, g);
  const handle = solid(g);

  function rect(x0, y0, x1, y1, r, b) { return rings(x0, y0, x1, y1, r, b); }
  function draw(d, ang) {
    far.forEach((w, i) => drawWheel(w, WX[i] + d, ang));
    let [o, n] = rect(d - 2, 0, d + L, W, 4, 1.2);
    put(cart, prism(P, front, o, n, ZB, ZT));
    BARS.forEach(([x, len], i) => {
      [o, n] = rect(d + x - 2.6, W / 2 - len / 2, d + x + 2.6, W / 2 + len / 2, 1.4, 0.7);
      put(bars[i], prism(P, front, o, n, ZT + 1, ZT + 2.6));
    });
    // the mallet: a post at the cart's back corner, a stick to a ball that bobs as the wheels turn
    [o, n] = rect(d + 0.5, 1, d + 4.5, 5, 1.6, 0.6);
    put(post, prism(P, front, o, n, ZT, ZT + 9));
    const bob = 3.2 * Math.abs(Math.sin(ang * 1.5)), hx = d + 22, hz = ZT + 4 + bob;
    stick.setAttribute("d", open([P(d + 2.5, 3, ZT + 8), P(hx, W / 2 - 1, hz + 1)]));
    [o, n] = rings(hx - 2.4, W / 2 - 3.4, hx + 2.4, W / 2 + 1.4, 2.4, 0.8);
    put(head, prism(P, front, o, n, hz, hz + 4));
    near.forEach((w, i) => drawWheel(w, WX[i] + d, ang));
    // the string: from the front hitch, sagging to the bead handle on the floor
    const hx0 = HX + d, pts = [];
    for (let i = 0; i <= 12; i++) {
      const t = i / 12, slack = (1 - d / (MAXD + 1)) * 4;
      pts.push(P(lerp(d + L, hx0, t), lerp(W / 2, HY, t) + slack * Math.sin(t * Math.PI), Math.max(0.3, (1 - t) * 9 - 3 * Math.sin(t * Math.PI))));
    }
    string.setAttribute("d", open(pts));
    const hr = circ(2.8, 14), hi = circ(1.8, 14);
    const mv = (ring) => ring.map((p) => ({ ...p, u: p.u + hx0 + 2, v: p.v + HY }));
    put(handle, prism(P, front, mv(hr), mv(hi), 0, 3.2));
  }
  function lerp(a, b, t) { return a + (b - a) * t; }

  const sp = spring(0);
  let last = NaN;
  const B = register(stage, (dt) => {
    const moving = stepS(sp, dt);
    if (sp.x !== last) { last = sp.x; draw(sp.x, -sp.x / R); }
    return moving;
  });
  bag.add(B.unregister);
  handle.sil.classList.add("hi");

  // the hit: the pointer on the floor plane, which never moves; how far ahead of the cart's nose it is
  function target([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    if (y < -16 || y > W + 22 || x < -12) return 0;
    return clamp((x - L) * 0.8, 0, reach);
  }
  function setPull(d) {
    sp.t = d;
    read.textContent = d < 0.5 ? "rest" : "+" + Math.round(d) + "cm";
    B.wake();
  }
  setPull(0);
  draw(0, 0);
  last = 0;
  bag.add(pointer(stage, { move: (p) => setPull(target(p)), leave: () => setPull(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "xylophonetoy",
  means: "A xylophone pull toy: the pointer ahead of it on the floor pulls it along, wheels turning and the mallet bobbing on the bars.",
  rules: [1, 3, 5, 8],
  range: [10, 18, 26],
  tour: [[285, 247], [308, 258], [353, 281], null],
  mount,
});

nightlight.code:
/**
 * Mobile: a nursery mobile on a stand, an arm reaching out over four toys
 * hanging on strings at uneven lengths, balls and blocks in turn. The
 * pointer picks a toy by where it stands: its string winds up and the toy
 * rises toward the arm, and the toys beside it rise a little, staggered
 * from it. At rest one toy hangs high, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 30, Y = 20, ARM = 112, R = 10, FAV = 2, LIFT = 22;
const HANG = [38, 26, 44, 30];
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  const X1 = 30 + (N - 1) * STEP + 14;
  fit(C, [[-16, 2, 0], [24, 38, 0], [X1, Y, ARM + 4], [-4, Y, ARM + 4], [30 + 2 * STEP, Y, ARM - 44 - 2 * R - 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the stand: a weighted foot, a pole, an arm
  const [fr, fi] = rings(-16, 2, 24, 38, 8, 2);
  put(solid(g), prism(P, front, fr, fi, 0, 5));
  const [pr, pi] = rings(-1, Y - 3, 5, Y + 3, 3, 1);
  put(solid(g), prism(P, front, pr, pi, 5, ARM + 4));
  const [ar, ai] = rings(-4, Y - 2.5, X1, Y + 2.5, 2.5, 0.8);
  put(solid(g), prism(P, front, ar, ai, ARM, ARM + 4));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 30 + k * STEP, grp = mk("g", {}, g);
    const str = mk("path", { class: "nf lo" }, grp);
    const s = solid(grp);
    const eq = k % 2 === 0 ? mk("path", { class: "nf lo" }, grp) : null;
    const rest = k === FAV ? HANG[k] - LIFT * 0.7 : HANG[k];
    items.push({ k, x, ball: k % 2 === 0, str, s, eq, z: tween(rest), last: NaN });
  }

  function draw(it, h) {
    if (h === it.last) return;
    it.last = h;
    const top = ARM - h;
    it.str.setAttribute("d", seg(P(it.x, Y, ARM), P(it.x, Y, top)));
    if (it.ball) {
      const zc = top - R, pts = [];
      for (let i = -6; i <= 6; i++) { const t = (i / 6) * (Math.PI / 2); pts.push(...ringAt(P, disc(it.x, Y, R * Math.cos(t)), zc + R * Math.sin(t))); }
      it.s.sil.setAttribute("d", poly(hull(pts)));
      it.eq.setAttribute("d", open(ringAt(P, disc(it.x, Y, R - 0.6).filter(front), zc)));
    } else {
      const [br, bi] = rings(it.x - 8, Y - 8, it.x + 8, Y + 8, 3, 1.4);
      put(it.s, prism(P, front, br, bi, top - 16, top));
    }
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, Y, ARM - HANG[it.k] - R));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a);
      const h = a < 0 ? (k === FAV ? HANG[k] - LIFT * 0.7 : HANG[k]) : HANG[k] - (dd === 0 ? LIFT : dd === 1 ? 6 : 0);
      tset(it.z, h, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "toy " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "nightlight",
  means: "A nursery mobile on a stand: the toy under the pointer winds up on its string toward the arm, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[157, 164], [194, 164], [268, 244], null],
  mount,
});

scratchpost.code:
/**
 * Scratch posts: three posts of stepped heights on one base, each topped by
 * a round perch with a toy ball hanging from its rim on a cord. The pointer
 * picks a post by where it stands: its ball swings out as if batted, and
 * the balls beside it sway a little, staggered from it. At rest one ball is
 * already mid-swing, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, rad, open, run,
} = HL;

const N = 3, STEP = 46, PR = 7, TR = 17, CORD = 26, BR = 8, BZ = 5, FAV = 1;
const H = [86, 62, 40], REST = [-6, 34, 8], SW = -62;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.72);
  const X1 = (N - 1) * STEP;
  fit(C, [[-TR - 4, -TR - 4, 0], [X1 + TR + 4, TR + 10, 0], [-TR, 0, H[0] + 6], [X1 + TR + 4, -TR - 4, 0], [-TR - 4, TR + 10, 0], [X1 + CORD, TR, H[2]]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-TR - 4, -TR - 4, X1 + TR + 4, TR + 10, 8, 2);
  put(solid(g), prism(P, front, sr, si, 0, BZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, grp = mk("g", {}, g), h = H[k];
    put(solid(grp), prism(P, front, disc(x, 0, PR), disc(x, 0, PR - 1.5), BZ, h - 4));
    // sisal wrap: a few dim bands round the post
    for (let z = BZ + 8; z < h - 8; z += 9) mk("path", { d: open(ringAt(P, run(disc(x, 0, PR, 28), front), z)), class: "nf lo" }, grp);
    put(solid(grp), prism(P, front, disc(x, 0, TR, 40), disc(x, 0, TR - 2.5, 40), h - 4, h));
    const cord = mk("path", { class: "nf lo" }, grp), ball = mk("path", { class: "sil" }, grp);
    items.push({ k, x, h, cord, ball, a: tween(REST[k]), last: NaN });
  }

  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const ax = it.x, ay = TR - 3, az = it.h - 4, t = rad(deg);
    const bx = ax + CORD * Math.sin(t), bz = az - CORD * Math.cos(t);
    it.cord.setAttribute("d", seg(P(ax, ay, az), P(bx, ay, bz)));
    const pts = [];
    for (let i = -3; i <= 3; i++) { const a = (i / 3) * (Math.PI / 2); pts.push(...ringAt(P, disc(bx, ay, BR * Math.cos(a) + 0.01, 20), bz - BR + BR * Math.sin(a))); }
    it.ball.setAttribute("d", poly(hull(pts)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 0, it.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    const top = P(items[best].x, 0, items[best].h + 6)[1], bot = P(items[best].x, TR, 0)[1];
    return bd < 34 && sy > top && sy < bot + 10 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), d = a < 0 ? REST[k] : dd === 0 ? SW : dd === 1 ? -16 : 0;
      tset(it.a, d, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.ball.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "post " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "scratchpost",
  means: "Three cat scratch posts of stepped heights: the toy ball on the post under the pointer swings out, and its neighbours sway a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[148, 133], [204, 179], [260, 223], null],
  mount,
});

busfront.code:
/**
 * Bus: a city bus standing at the kerb, windows down its side, two doors.
 * The pointer picks a door by where it stands along the bus: that door
 * swings out open, the other swings back shut a beat later. At rest the
 * front door is half open, bright. The slider is how far a door swings.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 130, W = 40, Z0 = 8, Z1 = 56, DW = 18, FAV = 1;
const DOORS = [52, 104];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [L, W, 0], [L, 0, Z1], [0, W, Z1], [0, 0, Z1], [L, W + DW, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, L, W, 9, 1.6);
  put(solid(g), prism(P, front, br, bi, Z0, Z1));
  const lines = mk("path", { class: "nf lo" }, g);
  const sideRect = (x0, x1, z0, z1, r = 2) => poly(rrect(x0, z0, x1, z1, r, 3).map((q) => P(q.u, W, q.v)));
  let d = "";
  // side windows, skipping the door openings
  for (let x = 6; x + 16 <= L - 4; x += 20) if (!DOORS.some((dx) => x + 16 > dx - 2 && x < dx + DW + 2)) d += sideRect(x, x + 16, 34, 50);
  // windscreen and destination band on the front face
  const fr = (y0, y1, z0, z1) => poly(rrect(y0, z0, y1, z1, 2, 3).map((q) => P(L, q.u, q.v)));
  d += fr(5, W - 5, 30, 51) + fr(8, W - 8, 18, 24);
  // skirt line
  d += seg(P(6, W, 16), P(L - 6, W, 16));
  lines.setAttribute("d", d);
  // door openings: dim frames the doors close into
  const holes = mk("path", { class: "lo" }, g);
  holes.setAttribute("d", DOORS.map((x) => sideRect(x, x + DW, Z0 + 2, 52, 1)).join(""));
  // wheels: discs on the near side
  for (const wx of [24, L - 30]) {
    const pts = [], hub = [];
    for (let i = 0; i < 32; i++) { const t = (i / 32) * 2 * Math.PI; pts.push(P(wx + 9 * Math.cos(t), W + 0.6, 9 + 9 * Math.sin(t))); hub.push(P(wx + 3.5 * Math.cos(t), W + 0.8, 9 + 3.5 * Math.sin(t))); }
    mk("path", { d: poly(pts), class: "sil" }, g);
    mk("path", { d: poly(hub), class: "nf lo" }, g);
  }

  const items = DOORS.map((x, k) => {
    const el = mk("path", { class: "sil" }, g), pane = mk("path", { class: "nf lo" }, g);
    return { k, x, el, pane, a: tween(k === FAV ? 0.5 : 0), last: NaN };
  });

  function draw(it, t) {
    if (t === it.last) return;
    it.last = t;
    const a = (t * swing * Math.PI) / 180, ex = it.x + DW * Math.cos(a), ey = W + 0.4 + DW * Math.sin(a);
    const q = (u, z) => P(it.x + (ex - it.x) * u, W + 0.4 + (ey - W - 0.4) * u, z);
    it.el.setAttribute("d", poly([q(0, Z0 + 2), q(1, Z0 + 2), q(1, 52), q(0, 52)]));
    it.pane.setAttribute("d", poly([q(0.2, 26), q(0.8, 26), q(0.8, 48), q(0.2, 48)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = DOORS.map((x) => P(x + DW / 2, W, 30));
  function hit([sx, sy]) {
    const top = P(L / 2, W / 2, Z1)[1] - 10, bot = P(L / 2, W, 0)[1] + 30;
    if (sy < top || sy > bot) return -1;
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a, force) {
    if (a === act && !force) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      tset(it.a, a < 0 ? (k === FAV ? 0.5 : 0) : k === a ? 1 : 0, now, from < 0 ? 0 : Math.abs(k - from) * 60);
      it.el.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "door " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; items.forEach((it) => { it.last = NaN; }); B.wake(); }, destroy: bag.dispose };
}

