  tour: [[156, 173], [200, 195], [237, 214], null],
  mount,
});

plates.code:
/**
 * Weight plates: four plates of falling size standing in a rack, each on
 * its own peg. The pointer picks a plate by where it stands: it slides up
 * off its peg, the plates beside it lift a little, staggered from it. At
 * rest one plate stands raised, bright. The slider is the stagger.
 */
const {
  Cam, fit, hull, poly, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, register, solid,
} = HL;

const RS = [34, 30, 25, 19], GAP = 26, BZ = 6, LIFT = 22, FAV = 1, CX = 40, Y1 = RS.length * GAP + 8;
const ring = (cx, y, cz, R, n = 36) => Array.from({ length: n }, (_, i) => { const t = (i / n) * 2 * Math.PI; return [cx + R * Math.cos(t), y, cz + R * Math.sin(t)]; });

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.85);
  fit(C, [[0, -6, 0], [80, Y1 + 6, 0], [80, -6, 0], [0, Y1 + 6, 0], [CX, 8, BZ + 2 * 34 + LIFT], [CX, Y1, BZ + 2 * 19 + LIFT]], 200, 168);
  const P = proj(C), g = mk("g", {}, svg);
  const [br, bi] = rings(0, -6, 80, Y1 + 6, 6, 2);
  const base = solid(g);
  base.sil.setAttribute("d", poly(hull(ringAt(P, br, 0).concat(ringAt(P, br, BZ)))));
  base.cr.setAttribute("d", poly(ringAt(P, bi, BZ)));

  const items = RS.map((R, k) => {
    const y = 8 + k * GAP, grp = mk("g", {}, g);
    const s = solid(grp), hole = mk("path", { class: "nf lo" }, grp);
    const peg = mk("path", { class: "nf" }, grp);
    return { k, R, y, s, hole, peg, z: tween(k === FAV ? LIFT * 0.7 : k === 3 ? 4 : 0), last: NaN };
  });
  function draw(it, h) {
    if (h === it.last) return;
    it.last = h;
    const cz = BZ + it.R + h, pr = (pts) => pts.map((q) => P(q[0], q[1], q[2]));
    it.s.sil.setAttribute("d", poly(hull(pr(ring(CX, it.y - 2.5, cz, it.R).concat(ring(CX, it.y + 2.5, cz, it.R))))));
    it.s.cr.setAttribute("d", poly(pr(ring(CX, it.y + 2.5, cz, it.R - 4))));
    it.hole.setAttribute("d", poly(pr(ring(CX, it.y + 2.5, cz, 4, 20))));
    const pz = BZ + it.R;
    it.peg.setAttribute("d", poly(hull(pr(ring(CX, it.y + 2.6, pz, 2.6, 16).concat(ring(CX, it.y + 6, pz, 2.6, 16))))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(CX, it.y, BZ + it.R));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : k === 3 ? 4 : 0) : dd === 0 ? LIFT : dd === 1 ? 6 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "plate " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "plates",
  means: "Four weight plates of falling size on a rack: the plate under the pointer slides up off its peg, its neighbours a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[263, 132], [229, 149], [161, 207], null],
  mount,
});

vlogcam.code:
/**
 * Ring light: a round weighted base, a slim pole and, on top, a ring lamp
 * with a phone clipped in its middle. The ring and phone turn together on
 * the pole to face the pointer, wherever it is over the ground. At rest the
 * head is turned a little aside, the phone lit; while it follows, the ring
 * takes the bright. The slider is how far it may turn.
 *
 * The pattern: turn to face; the hit is the pointer on the ground plane.
 */
const {
  Cam, circ, clamp, facing, fit, hull, poly, prism, proj, rad, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const ZH = 74, RO = 22, RI = 17, TH = 2.6, REST = 18, VIEW = 45;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-18, -18, 0], [18, 18, 0], [-RO, 0, ZH], [RO, 0, ZH], [0, -RO, ZH], [0, RO, ZH], [0, 0, ZH + RO]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const base = circ(16, 24), baseIn = circ(14.8, 24);
  put(solid(g), prism(P, front, base, baseIn, 0, 4));
  const [po, pi] = rings(-1.6, -1.6, 1.6, 1.6, 1.6, 0.5);
  put(solid(g), prism(P, front, po, pi, 4, ZH - RO + 1));

  const ring = solid(g), phone = solid(g);
  const th = spring(REST);
  let last = NaN;

  function disc(r, t, f, h, n) {
    const pts = [];
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2, u = r * Math.cos(a), v = r * Math.sin(a);
      pts.push(P(h[0] * u + f[0] * t, h[1] * u + f[1] * t, ZH + v));
    }
    return pts;
  }
  function area(p) { let s = 0; p.forEach((a, i) => { const b = p[(i + 1) % p.length]; s += a[0] * b[1] - b[0] * a[1]; }); return s; }
  function draw(deg) {
    const d = Math.round(deg * 10) / 10;
    if (d === last) return;
    last = d;
    const f = [Math.cos(rad(d)), Math.sin(rad(d))], h = [-f[1], f[0]];
    const out = hull(disc(RO, TH / 2, f, h, 40).concat(disc(RO, -TH / 2, f, h, 40)));
    // the hole: the side of the ring facing the camera shows its inner rim
    const toCam = Math.cos(rad(d - VIEW)) >= 0 ? 1 : -1;
    let hole = disc(RI, toCam * TH / 2, f, h, 32);
    if (Math.sign(area(hole)) === Math.sign(area(out))) hole = hole.reverse();
    ring.sil.setAttribute("d", poly(out) + poly(hole));
    ring.cr.setAttribute("d", poly(disc(RI + 2.2, toCam * TH / 2, f, h, 32)));
    // the phone: a thin plate standing in the ring's plane
    const corners = [];
    [-0.7, 0.7].forEach((t) => [[-5, -9], [5, -9], [5, 9], [-5, 9]].forEach(([u, v]) => corners.push(P(h[0] * u + f[0] * t, h[1] * u + f[1] * t, ZH + v))));
    phone.sil.setAttribute("d", poly(hull(corners)));
    const scr = [[-4, -8], [4, -8], [4, 8], [-4, 8]].map(([u, v]) => P(h[0] * u + f[0] * toCam * 0.7, h[1] * u + f[1] * toCam * 0.7, ZH + v));
    phone.cr.setAttribute("d", poly(scr));
  }

  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(th.x); return m; });
  bag.add(B.unregister);

  let on = null;
  function aim(p) {
    if (!p) { th.t = REST; on = null; }
    else {
      const [x, y] = unproj(C, p[0], p[1], 0);
      let a = (Math.atan2(y, x) * 180) / Math.PI;
      if (a < VIEW - 180) a += 360;
      th.t = clamp(a, VIEW - reach, VIEW + reach);
      on = true;
    }
    ring.sil.classList.toggle("hi", !!on);
    phone.sil.classList.toggle("hi", !on);
    read.textContent = on ? "turn " + Math.round(th.t - VIEW) + "°" : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "vlogcam",
  means: "A ring light with a phone in its middle: the ring and phone turn on the pole to face the pointer.",
  rules: [1, 3, 4, 5],
  range: [30, 70, 110],
  tour: [[290, 250], [110, 250], [200, 300], null],
  mount,
});

tiebox.code:
/**
 * Bow ties: three bow ties laid side by side in a shallow presentation box.
 * The pointer picks a tie by where it stands: it lifts out of the box and
 * its neighbours rise a little, staggered from it. At rest the middle tie
 * is raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, fillet, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, register, put, solid,
} = HL;

const N = 3, STEP = 46, BZ = 7, LIFT = 26, FAV = 1, TH = 3.5;
const X1 = N * STEP + 8, Y1 = 64, YC = Y1 / 2;
const asRing = (pts) => pts.map(([u, v]) => ({ u, v, nu: 0, nv: 0 }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [X1, 0, 0], [0, Y1, 0], [STEP, YC, BZ + LIFT + TH + 2]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, X1, Y1, 7, 3);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  const [fr] = rings(4, 4, X1 - 4, Y1 - 4, 5, 1);
  mk("path", { d: poly(ringAt(P, fr, BZ)), class: "nf lo" }, g);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 4 + STEP / 2 + k * STEP + 4, grp = mk("g", {}, g);
    const wa = mk("path", { class: "sil" }, grp), wb = mk("path", { class: "sil" }, grp), knot = mk("path", { class: "sil" }, grp);
    const lines = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, wa, wb, knot, lines, z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN });
  }

  const wing = (x, s) => asRing(fillet([[x - 3, YC + s * 4], [x - 15, YC + s * 25], [x + 15, YC + s * 25], [x + 3, YC + s * 4]], [2, 4, 4, 2], 3));
  const slab = (ring, z) => poly(hull(ringAt(P, ring, z).concat(ringAt(P, ring, z + TH))));
  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z = BZ + 0.5 + lift, x = it.x;
    it.wa.setAttribute("d", slab(wing(x, -1), z));
    it.wb.setAttribute("d", slab(wing(x, 1), z));
    const kn = asRing(fillet([[x - 6, YC - 6], [x + 6, YC - 6], [x + 6, YC + 6], [x - 6, YC + 6]], [2, 2, 2, 2], 3));
    it.knot.setAttribute("d", slab(kn, z + 1.2));
    // the pleats: two folds on each wing
    let d = "";
    for (const s of [-1, 1]) for (const o of [-5, 5]) {
      const a = P(x + o * 0.4, YC + s * 9, z + TH), b = P(x + o * 1.6, YC + s * 22, z + TH);
      d += "M" + a[0].toFixed(2) + "," + a[1].toFixed(2) + "L" + b[0].toFixed(2) + "," + b[1].toFixed(2);
    }
    it.lines.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, YC, BZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      for (const el of [it.wa, it.wb, it.knot]) el.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tie " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "tiebox",
  means: "Three bow ties in a presentation box: the tie under the pointer lifts out, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[138, 130], [215, 169], [292, 208], null],
  mount,
});

shoeshine.code:
/**
 * Shoe shine: a shine box with its footrest on top, and in front of it two
 * polish tins and a brush. The pointer picks a piece by where it stands: a
 * tin's lid lifts off, the brush rises from the floor, and the piece beside
 * it stirs, staggered. At rest the second tin stands open, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const XS = [16, 48, 86], YF = 62, LIFT = 28, FAV = 1;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-4, -4, 0], [104, YF + 12, 0], [104, -4, 0], [-4, YF + 12, 0], [40, 18, 44], [XS[0], YF, 10 + LIFT]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, 100, 40, 5, 2);
  put(solid(g), prism(P, front, br, bi, 0, 30));
  // the footrest: a sole-shaped block on the lid
  const [fr, fi] = rings(18, 10, 82, 30, 9, 1.6);
  put(solid(g), prism(P, front, fr, fi, 30, 34));
  const [hr, hi] = rings(26, 13, 74, 27, 6, 1.4);
  put(solid(g), prism(P, front, hr, hi, 34, 40));

  const items = XS.map((x, k) => {
    const grp = mk("g", {}, g), brush = k === 2;
    const body = solid(grp), top = solid(grp);
    return { k, x, brush, body, top, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN };
  });

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const x = it.x;
    if (it.brush) {
      // bristles below, a rounded back above: the whole brush rises
      put(it.body, prism(P, front, rrect(x - 13, YF - 7, x + 13, YF + 7, 4, 4), rrect(x - 11.6, YF - 5.6, x + 11.6, YF + 5.6, 2.6, 4), lift, lift + 4));
      put(it.top, prism(P, front, rrect(x - 15, YF - 8, x + 15, YF + 8, 7, 4), rrect(x - 13.4, YF - 6.4, x + 13.4, YF + 6.4, 5.4, 4), lift + 4, lift + 9));
    } else {
      put(it.body, prism(P, front, disc(x, YF, 11), disc(x, YF, 9.4), 0, 5));
      put(it.top, prism(P, front, disc(x, YF, 11.6), disc(x, YF, 9.6), 5 + lift, 8.5 + lift));
    }
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, YF, 5));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && sy > mids[best][1] - 50 && sy < mids[best][1] + 30 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.top.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : ["tin 1", "tin 2", "brush"][a];
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "shoeshine",
  means: "A shine box with polish tins and a brush: the tin under the pointer opens its lid, the brush rises, neighbours stir.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[101, 167], [153, 193], [215, 224], null],
  mount,
});

minifridge.code:
/**
 * Ice bucket: a tapered bucket on a round tray, a champagne bottle leaning
 * in it. The pointer over the bucket lifts the bottle out of the ice and
 * stands it upright; leaving sets it back at its lean. At rest the bottle
 * is the bright mark. The slider is how far it lifts.
 *
 * The pattern: one object answering (lift).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, ringAt, run, spring, stepS,
  disposer, mk, pointer, put, register, solid, unproj,
} = HL;

const BR = 20, BF = 15, BH = 30, TZ = 3, LEAN = 0.32;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.1);
  fit(C, [[-30, -30, 0], [30, 30, 0], [30, -30, 0], [-30, 30, 0], [0, 0, TZ + 8 + 36 + 46], [14, 0, TZ + 60]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(0, 0, 28), disc(0, 0, 26), 0, TZ));
  // the bucket: tapered, its back wall first
  const foot = disc(0, 0, BF), top = disc(0, 0, BR), inner = disc(0, 0, BR - 1.6);
  mk("path", { d: poly(hull(ringAt(P, foot, TZ).concat(ringAt(P, top, TZ + BH)))), class: "sil" }, g);
  mk("path", { d: poly(ringAt(P, inner, TZ + BH)), class: "nf lo" }, g);
  const bottle = solid(g), neck = solid(g);
  // the front wall covers the bottle's foot
  const fr = run(top, front), ff = run(foot, front);
  mk("path", { d: poly(ringAt(P, fr, TZ + BH).concat(ringAt(P, ff, TZ).reverse())), class: "sil" }, g);
  for (const s of [-1, 1]) {
    const a = ringAt(P, disc(s * (BR + 2.5), 0, 2.4, 14), TZ + BH - 7), b = ringAt(P, disc(s * (BR + 2.5), 0, 2.4, 14), TZ + BH - 4);
    mk("path", { d: poly(hull(a.concat(b))), class: "nf lo" }, g);
  }
  bottle.sil.classList.add("hi");

  const lift = spring(0);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const z0 = TZ + 4 + t * reach, lean = LEAN * (1 - t);
    const at = (r, z, n) => ringAt(P, disc(lean * (z - z0), 0, r, n), z);
    const body = [], bi = [];
    for (const z of [z0, z0 + 34]) { body.push(...at(6.5, z, 28)); }
    for (let i = 0; i <= 6; i++) { const u = i / 6; body.push(...at(6.5 - 4.2 * u, z0 + 34 + 10 * u, 28)); }
    bottle.sil.setAttribute("d", poly(hull(body)));
    bottle.cr.setAttribute("d", poly(at(6.5, z0 + 22, 28)));
    neck.sil.setAttribute("d", poly(hull(at(2.6, z0 + 44, 16).concat(at(2.6, z0 + 52, 16)))));
    neck.cr.setAttribute("d", "");
  }

  const B = register(stage, (dt) => { const m = stepS(lift, dt); draw(lift.x); return m; });
  bag.add(B.unregister);

  function set(on) {
    lift.t = on ? 1 : 0;
    read.textContent = on ? "lift" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, TZ); set(Math.hypot(x, y) < 30 || Math.hypot(...unproj(C, sx, sy, TZ + BH)) < 24); },
    leave: () => set(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "minifridge",
  means: "A champagne bottle leaning in an ice bucket: the pointer over the bucket lifts it out of the ice and stands it upright.",
  rules: [1, 3, 5, 6],
  range: [10, 26, 36],
  tour: [[121, 231], [200, 204], [279, 177], null],
  mount,
});

deckchairs.code:
/**
 * Deck chairs: four loungers in a row on a deck, each a padded seat with a
 * backrest hinged at its head. The pointer picks a chair by where it stands:
 * its backrest swings up to sit, and the chairs beside it lift theirs a
 * little, staggered from it. At rest the backs lie at uneven angles and one
 * is bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, fillet, hull, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 27, W = 18, DEPTH = 34, L = 26, T = 1.8, CZ = 4, SZ = 9, FAV = 1;
const X1 = (N - 1) * STEP + W;
const REST = [62, 48, 70, 56], UP = 8;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  const top = CZ + SZ;
  fit(C, [[-6, -14, 0], [X1 + 6, DEPTH + 6, 0], [X1 + 6, -14, 0], [-6, DEPTH + 6, 0], [0, 2, top + L], [X1, 2, top + L]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [dr, di] = rings(-6, -14, X1 + 6, DEPTH + 6, 6, 2);
  put(solid(g), prism(P, front, dr, di, 0, CZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * STEP, x1 = x0 + W, grp = mk("g", {}, g);
    const back = mk("path", { class: "sil" }, grp);
    const [sr, si] = rings(x0, 0, x1, DEPTH, 3, 1.5);
    put(solid(grp), prism(P, front, sr, si, CZ, top));
    mk("path", { d: seg(P(x0 + 2, 7, top), P(x1 - 2, 7, top)), class: "nf lo" }, grp);
    items.push({ k, x0, x1, back, a: tween(REST[k]), last: NaN });
  }

  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const s = Math.sin(rad(deg)), c = Math.cos(rad(deg)), pts = [];
    for (const x of [it.x0 + 1, it.x1 - 1]) for (const l of [0, L]) for (const t of [0, T]) {
      pts.push(P(x, 2 - l * s - t * c, top + l * c - t * s + 0.5));
    }
    const h = hull(pts);
    it.back.setAttribute("d", poly(fillet(h, h.map(() => 1.6))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P((it.x0 + it.x1) / 2, DEPTH / 2, top));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), deg = a < 0 ? REST[k] : dd === 0 ? UP : dd === 1 ? REST[k] - 14 : REST[k];
      tset(it.a, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.back.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "chair " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "deckchairs",
  means: "Four loungers on a deck: the backrest under the pointer swings up to sit, and its neighbours lift theirs a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[135, 145], [214, 184], [253, 204], null],
  mount,
});

windowshutters.code:
/**
 * Window shutters: a house wall with three windows, each with a sill and a
 * pair of shutters hinged at its sides. The pointer picks a window by where
 * it stands: its shutters swing open, and the windows beside it open theirs
 * a crack, staggered from it. At rest the shutters stand at uneven angles
 * and one pair is bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, fillet, hull, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, W = 22, STEP = 50, PAD = 14, Y = 0, TH = 6, H = 74, Z0 = 22, Z1 = 56, T = 1.4, FAV = 1;
const X1 = PAD * 2 + (N - 1) * STEP + W;
const REST = [14, 72, 0], OPEN = 112;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.72);
  fit(C, [[0, -TH, 0], [X1, -TH, H], [X1, Y + 14, 0], [0, Y + 14, 0], [X1, Y, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [wr, wi] = rings(0, -TH, X1, Y, 2, 1.2);
  put(solid(g), prism(P, front, wr, wi, 0, H));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = PAD + k * STEP, x1 = x0 + W, xm = x0 + W / 2, grp = mk("g", {}, g);
    mk("path", { d: poly([P(x0, Y, Z0), P(x1, Y, Z0), P(x1, Y, Z1), P(x0, Y, Z1)]) + seg(P(xm, Y, Z0), P(xm, Y, Z1)) + seg(P(x0, Y, (Z0 + Z1) / 2), P(x1, Y, (Z0 + Z1) / 2)), class: "nf lo" }, grp);
    const [sr, si] = rings(x0 - 3, Y, x1 + 3, Y + 4, 1, 0.6);
    put(solid(grp), prism(P, front, sr, si, Z0 - 2.5, Z0));
    const leaves = [0, 1].map(() => ({ sil: mk("path", { class: "sil" }, grp), lou: mk("path", { class: "nf lo" }, grp) }));
    items.push({ k, x0, x1, leaves, a: tween(REST[k]), last: NaN });
  }

  function leaf(l, hx, dir, deg) {
    const c = Math.cos(rad(deg)), s = Math.sin(rad(deg)), w = W / 2 - 0.4, pts = [];
    const at = (u, t, z) => P(hx + dir * (u * c - t * s), Y + 0.3 + u * s + t * c, z);
    for (const u of [0, w]) for (const t of [0, T]) for (const z of [Z0 + 0.5, Z1 - 0.5]) pts.push(at(u, t, z));
    const h = hull(pts);
    l.sil.setAttribute("d", poly(fillet(h, h.map(() => 1.2))));
    let d = "";
    for (let i = 1; i < 6; i++) { const z = lerpZ(i / 6); d += seg(at(1.5, T, z), at(w - 1.5, T, z)); }
    l.lou.setAttribute("d", d);
  }
  const lerpZ = (t) => Z0 + (Z1 - Z0) * t;

  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    leaf(it.leaves[0], it.x0, 1, deg);
    leaf(it.leaves[1], it.x1, -1, deg);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P((it.x0 + it.x1) / 2, Y, (Z0 + Z1) / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), deg = a < 0 ? REST[k] : dd === 0 ? OPEN : dd === 1 ? 22 : 4;
      tset(it.a, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      for (const l of it.leaves) l.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "win " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "windowshutters",
  means: "A house wall with three windows: the shutters under the pointer swing open, and the windows beside it open a crack.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[144, 85], [205, 115], [266, 145], null],
  mount,
});

chimney.code:
/**
 * Chimneys: a gabled house with three chimney stacks along its ridge, each
 * topped by a flat cap on a pot. The pointer picks a stack by where it stands:
 * its cap lifts clear of the pot, and the caps beside it lift a little,
 * staggered from it. At rest the middle cap is raised, bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, L = 130, D = 60, EAVE = 38, RIDGE = 66, ST0 = 60, ST1 = 88, LIFT = 20, FAV = 1;
const XS = [26, 65, 104], REST = [3, LIFT * 0.7, 0];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.62);
  fit(C, [[0, 0, 0], [L, D, 0], [L, 0, 0], [0, D, 0], [XS[0], 30, ST1 + LIFT + 4], [XS[2], 30, ST1 + LIFT + 4]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the house: walls and a gable roof, one hull, with its eave and rake as creases
  const pts = [...ringAt(P, rrect(0, 0, L, D, 3, 4), 0), ...ringAt(P, rrect(-3, -3, L + 3, D + 3, 3, 4), EAVE),
    ...ringAt(P, rrect(-3, 29, L + 3, 31, 1, 4), RIDGE)];
  const house = solid(g);
  house.sil.setAttribute("d", poly(hull(pts)));
  house.cr.setAttribute("d", seg(P(0, D + 3, EAVE), P(L + 3, D + 3, EAVE)) + seg(P(L + 3, D + 3, EAVE), P(L + 3, 30, RIDGE)) +
    seg(P(0, D, 2), P(L, D, 2)));
  // a door on the long wall
  mk("path", { d: poly([P(40, D, 0), P(40, D, 22), P(54, D, 22), P(54, D, 0)]), class: "nf lo" }, g);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = XS[k], grp = mk("g", {}, g);
    const [r0, i0] = rings(x - 7, 23, x + 7, 37, 2, 1.4);
    put(solid(grp), prism(P, front, r0, i0, ST0, ST1));
    put(solid(grp), prism(P, front, disc(x, 30, 3.4), disc(x, 30, 2.2), ST1, ST1 + 5));
    const cap = solid(grp);
    items.push({ k, x, cap, z: tween(REST[k]), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const [a, b] = rings(it.x - 9, 21, it.x + 9, 39, 2.5, 1.6);
    put(it.cap, prism(P, front, a, b, ST1 + 5 + lift, ST1 + 8 + lift));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 30, ST1));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && sy > mids[best][1] - 70 && sy < mids[best][1] + 50 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? REST[k] : dd === 0 ? LIFT : 5;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.cap.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "flue " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "chimney",
  means: "A gabled house with three chimneys on its ridge: the cap on the stack under the pointer lifts off its pot, its neighbours a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[155, 59], [200, 82], [245, 103], null],
  mount,
});

gardenshed.code:
/**
 * Garden shed: a small gabled shed on a paving slab, its door standing ajar.
 * The pointer on the ground draws the door open: the nearer it comes to the
 * doorway, the wider the door swings on its hinge, up to a clamped stop. At
 * rest the door is a crack open, bright. The slider is the widest swing.
 *
 * The pattern: one part swinging toward the pointer.
 */
const {
  Cam, fit, open, poly, hull, proj, rings, prism, facing, unproj, rad, clamp, seg,
  spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const W = 60, D = 44, HW = 38, HR = 58, OV = 4, DX0 = 22, DX1 = 42, DH = 30, REST = 12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-14, -14, 0], [W + 14, D + 34, 0], [W + 14, -14, 0], [-14, D + 34, 0], [-OV, D / 2, HR], [W + OV, D / 2, HR]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-14, -14, W + 14, D + 34, 6, 2);
  put(solid(g), prism(P, front, sr, si, -4, 0));
  const [br, bi] = rings(0, 0, W, D, 2, 1.2);
  put(solid(g), prism(P, front, br, bi, 0, HW));
  // the roof: two pitched planes over the walls, eaves out past them
  const e0 = [-OV, -OV, HW - 2], e1 = [W + OV, -OV, HW - 2], e2 = [W + OV, D + OV, HW - 2], e3 = [-OV, D + OV, HW - 2];
  const r0 = [-OV, D / 2, HR], r1 = [W + OV, D / 2, HR];
  const pp = (q) => P(q[0], q[1], q[2]);
  mk("path", { d: poly(hull([e0, e1, e2, e3, r0, r1].map(pp))), class: "sil" }, g);
  mk("path", { d: seg(pp(r0), pp(r1)) + open([pp(e1), pp(r1), pp(e2)]), class: "nf lo" }, g);
  // the window on the gable-end wall
  mk("path", { d: poly([P(W, 12, 16), P(W, 30, 16), P(W, 30, 28), P(W, 12, 28)]) + seg(P(W, 21, 16), P(W, 21, 28)), class: "nf lo" }, g);
  // the doorway on the long wall, and the door hung on its left jamb
  mk("path", { d: open([P(DX0, D, 0), P(DX0, D, DH), P(DX1, D, DH), P(DX1, D, 0)]), class: "nf lo" }, g);
  const door = mk("path", { class: "sil hi" }, g), edge = mk("path", { class: "nf lo" }, g), knob = mk("path", { class: "nf" }, g);

  const sp = spring(REST);
  let last = NaN;
  function draw(A) {
    if (Math.abs(A - last) < 0.01) return;
    last = A;
    const L = DX1 - DX0, c = Math.cos(rad(A)), s = Math.sin(rad(A));
    const at = (t, z, n = 0) => P(DX0 + t * c - n * s, D + t * s + n * c, z);
    door.setAttribute("d", poly([at(0, 0.5), at(L, 0.5), at(L, DH - 0.5), at(0, DH - 0.5)]));
    edge.setAttribute("d", open([at(L, 0.5), at(L, 0.5, 1.6), at(L, DH - 0.5, 1.6), at(L, DH - 0.5)]));
    knob.setAttribute("d", seg(at(L - 3.5, DH * 0.45, 0.3), at(L - 3.5, DH * 0.55, 0.3)));
  }

  const B = register(stage, (dt) => {
    const m = stepS(sp, dt);
    draw(sp.x);
    return m;
  });
  bag.add(B.unregister);

  function aim([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    if (x < -14 || x > W + 14 || y < -14 || y > D + 34) return -1;
    const d = Math.hypot(x - (DX0 + DX1) / 2, Math.max(0, y - D) * 1.0 + Math.max(0, D - y) * 2);
    return clamp(maxA - d * 0.8, REST, maxA);
  }

  function set(A) {
    sp.t = A < 0 ? REST : A;
    read.textContent = A < 0 ? "rest" : Math.round(sp.t) + "°";
    B.wake();
  }
  set(-1);
  bag.add(pointer(stage, { move: (p) => set(aim(p)), leave: () => set(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "gardenshed",
  means: "A gabled garden shed with its door ajar: the nearer the pointer comes to the doorway, the wider the door swings open.",
  rules: [1, 3, 5, 8],
  range: [90, 120, 150],
  tour: [[230, 250], [203, 255], [175, 216], null],
  mount,
});

treehouse.code:
/**
 * Treehouse: a hut on a platform round a trunk, a ladder leaning up to it.
 * The pointer over the tree lifts the hut's pitched roof off its walls to
 * look inside; leaving sets it back. At rest the roof sits a little ajar and
 * the platform's edge is bright. The slider is how far the roof lifts.
 *
 * The pattern: one lid, lifting (cloches).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, rrect, run, tdone, tset, tval, tween, seg,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PZ = 40, WZ = 62, RH = 12, REST = 3;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[-24, -24, 0], [36, 24, 0], [24, 24, 0], [-24, 24, 0], [24, -24, 0], [0, 0, WZ + RH + 30]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // ground disc and trunk
  mk("path", { d: poly(ringAt(P, disc(2, 2, 26, 48), 0)), class: "nf lo" }, g);
  put(solid(g), prism(P, front, disc(0, 0, 6), disc(0, 0, 4.5), 0, PZ));
  // platform
  const [pr, pi] = rings(-22, -22, 22, 22, 4, 2);
  const plat = solid(g);
  put(plat, prism(P, front, pr, pi, PZ, PZ + 3));
  // walls with a door on the +x face
  const [wr, wi] = rings(-14, -14, 14, 14, 2, 1.2);
  put(solid(g), prism(P, front, wr, wi, PZ + 3, WZ));
  mk("path", { d: poly([P(14, -4, PZ + 3), P(14, 4, PZ + 3), P(14, 4, PZ + 14), P(14, -4, PZ + 14)]), class: "nf lo" }, g);
  mk("path", { d: poly([P(-3, 14, PZ + 9), P(4, 14, PZ + 9), P(4, 14, PZ + 15), P(-3, 14, PZ + 15)]), class: "nf lo" }, g);
  // roof: tapered solid, drawn per lift
  const roof = solid(g);
  const foot = rrect(-18, -18, 18, 18, 3, 4), top = rrect(-5, -5, 5, 5, 2, 4), inner = rrect(-4, -4, 4, 4, 1.5, 4);
  // ladder leaning on the +x edge
  const lad = mk("path", { class: "nf" }, g);
  let d = "";
  for (const y of [-5, 5]) d += seg(P(36, y, 0), P(22, y, PZ + 3));
  for (let i = 1; i <= 6; i++) { const t = i / 7, x = 36 - 14 * t, z = (PZ + 3) * t; d += seg(P(x, -5, z), P(x, 5, z)); }
  lad.setAttribute("d", d);

  const z = tween(REST);
  let last = NaN;
  function draw(l) {
    if (l === last) return;
    last = l;
    const z0 = WZ + l, z1 = z0 + RH;
    roof.sil.setAttribute("d", poly(hull(ringAt(P, foot, z0).concat(ringAt(P, top, z1)))));
    roof.cr.setAttribute("d", open(ringAt(P, run(inner, front), z1)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(z, now)); return !tdone(z, now); });
  bag.add(B.unregister);

  const mid = P(4, 0, PZ), box = [mid[0] - 110, mid[1] - 150, mid[0] + 110, mid[1] + 110];
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(z, on ? reach : REST, performance.now(), 0);
    roof.sil.classList.toggle("hi", on);
    plat.sil.classList.toggle("hi", !on);
    read.textContent = on ? "roof up" : "rest";
    B.wake();
  }
  setActive(false);
  const inside = ([sx, sy]) => sx > box[0] && sx < box[2] && sy > box[1] && sy < box[3];
  bag.add(pointer(stage, { move: (p) => setActive(inside(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (act) { tset(z, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

