  tour: [[170, 187], [236, 187], null],
  mount,
});

lockerrow.code:
/**
 * School lockers: a row of tall lockers on a plinth, each door with three vent
 * slots and a handle. The pointer picks a locker by where it stands and its
 * door swings open on its hinge; the doors beside it crack open a little,
 * staggered from it. At rest one door stands ajar, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, LW = 14, D = 15, H = 62, Z0 = 6, Z1 = 60, DW = 12.4, FAV = 2, OPEN = 105;
const X1 = N * LW;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[-3, -3, 0], [X1 + 3, D + 3 + DW, 0], [X1 + 3, -3, 0], [-3, D + 3 + DW, 0], [-3, -3, H + 3], [X1 + 3, D + 3, H + 3]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-3, -3, X1 + 3, D + 3, 3, 1.4);
  put(solid(g), prism(P, front, pr, pi, 0, 4));
  const [br, bi] = rings(0, 0, X1, D, 2, 1.2);
  put(solid(g), prism(P, front, br, bi, 4, H));
  for (let k = 1; k < N; k++) {
    const x = k * LW;
    mk("path", { d: "M" + P(x, D, Z0 - 1).join(" ") + "L" + P(x, D, Z1 + 1).join(" "), class: "nf lo" }, g);
  }

  const doors = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    const sil = mk("path", { class: "sil" }, grp), det = mk("path", { class: "nf lo" }, grp);
    doors.push({ k, hx: k * LW + 0.8, sil, det, a: tween(k === FAV ? 26 : 0), last: NaN });
  }
  function draw(dr, a) {
    if (a === dr.last) return;
    dr.last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const q = (d, z) => P(dr.hx + d * c, D + 0.2 + d * s, z);
    dr.sil.setAttribute("d", poly([q(0, Z0), q(DW, Z0), q(DW, Z1), q(0, Z1)]));
    let d = "";
    for (const z of [53, 50, 47]) d += "M" + q(3, z).join(" ") + "L" + q(DW - 3, z).join(" ");
    d += "M" + q(DW - 2, 30).join(" ") + "L" + q(DW - 2, 36).join(" ");
    dr.det.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const d of doors) { draw(d, tval(d.a, now)); if (!tdone(d.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = doors.map((d) => P(d.k * LW + LW / 2, D, 33));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 75 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    doors.forEach((d, k) => {
      const dd = Math.abs(k - a), t = a < 0 ? (k === FAV ? 26 : 0) : dd === 0 ? OPEN : dd === 1 ? 24 : 0;
      tset(d.a, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      d.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "locker " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "lockerrow",
  means: "A row of school lockers: the door under the pointer swings open on its hinge, and the doors beside it crack open.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[148, 141], [186, 160], [234, 184], null],
  mount,
});

pencilpot.code:
/**
 * Crayon cups: three round cups on a tray, each holding three crayons of
 * different lengths. The pointer picks a cup by where it stands: its crayons
 * slide up out of the cup, and the cups beside it lift theirs a little,
 * staggered from it. At rest the first cup's crayons stand raised, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 38, R = 13, H = 22, TZ = 4, LIFT = 20, FAV = 0, CR = 2.8;
const X1 = (N - 1) * STEP;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
// crayons in each cup, far to near: [dx, dy, length]
const CRAY = [[[-4, -4, 30], [5, -2, 24], [-2, 5, 34]], [[3, -5, 34], [-5, 1, 28], [4, 5, 22]], [[-3, -4, 26], [5, 0, 32], [-4, 5, 28]]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.15);
  const top = TZ + 2 + 34 + 4 + LIFT;
  fit(C, [[-R - 6, -R - 6, 0], [X1 + R + 6, R + 6, 0], [X1 + R + 6, -R - 6, 0], [-R - 6, R + 6, 0], [0, 0, top], [X1, 0, top]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(-R - 6, -R - 6, X1 + R + 6, R + 6, 8, 2);
  put(solid(g), prism(P, front, tr, ti, 0, TZ));

  const cups = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, y = 0, grp = mk("g", {}, g);
    const ring = disc(x, y, R), fr = run(ring, front);
    put(solid(grp), prism(P, front, ring, disc(x, y, R - 2), TZ, TZ + H));
    const cg = mk("g", {}, grp);
    const crs = CRAY[k].map(([dx, dy, len]) => ({ x: x + dx, y: y + dy, len, s: solid(cg) }));
    const wall = mk("path", { class: "sil", d: poly(ringAt(P, fr, TZ + H).concat(ringAt(P, fr, TZ).reverse())) }, grp);
    cups.push({ k, crs, wall, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }

  function draw(c, lift) {
    if (lift === c.last) return;
    c.last = lift;
    c.crs.forEach((cr, j) => {
      const z0 = TZ + 2 + lift * (1 - 0.18 * j), z1 = z0 + cr.len, ring = disc(cr.x, cr.y, CR, 16);
      const sil = poly(hull(ringAt(P, ring, z0).concat(ringAt(P, ring, z1), [P(cr.x, cr.y, z1 + 5)])));
      put(cr.s, { sil, crease: open(ringAt(P, run(ring, front), z1 - 3)) });
    });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const c of cups) { draw(c, tval(c.z, now)); if (!tdone(c.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = cups.map((c) => P(c.k * STEP, 0, TZ + H));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    cups.forEach((c, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(c.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      c.wall.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "cup " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "pencilpot",
  means: "Three crayon cups on a tray: the cup under the pointer pushes its crayons up, and its neighbours lift theirs a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[142, 106], [200, 135], [258, 164], null],
  mount,
});

stagecurtain.code:
/**
 * School stage: a raised platform with a back wall, a lectern, a valance and
 * two pleated curtains. The pointer picks a curtain by where it stands: that
 * curtain draws aside, its pleats bunching as it goes, and the other closes
 * back toward the middle. At rest the left curtain is half drawn, bright.
 * The slider is how far a curtain draws.
 *
 * The pattern: one of two in a single row (riffle).
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 120, D = 46, SZ = 10, CY = 34, CH = 64, L = 84, NP = 5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let pull = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-6, -6, 0], [W + 6, D, 0], [W + 6, -6, 0], [-6, D, 0], [-6, -6, SZ + CH + 10], [W + 6, -6, SZ + CH + 10], [-6, CY, SZ + CH + 10]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-6, -6, W + 6, D, 4, 1.5);
  put(solid(g), prism(P, front, pr, pi, 0, SZ));
  const [wr, wi] = rings(-4, -4, W + 4, 0, 1.5, 0.8);
  put(solid(g), prism(P, front, wr, wi, SZ, SZ + CH + 8));
  const [lr, li] = rings(31, 12, 45, 22, 2, 1.2);
  put(solid(g), prism(P, front, lr, li, SZ, SZ + 22));

  const sides = [0, 1].map((s) => {
    const grp = mk("g", {}, g);
    return { s, sheet: mk("path", { class: "sil" }, grp), folds: mk("path", { class: "nf lo" }, grp), w: tween(s === 0 ? 30 : 58), last: NaN };
  });
  const [vr, vi] = rings(-8, CY - 4, W + 8, CY + 4, 2, 1.2);
  put(solid(g), prism(P, front, vr, vi, SZ + CH, SZ + CH + 10));

  function draw(c, w) {
    if (w === c.last) return;
    c.last = w;
    const n = 2 * NP, dx = w / n, a = Math.min(Math.sqrt(Math.max((L / n) ** 2 - dx * dx, 1)) / 2, 3.5);
    const pts = [];
    for (let i = 0; i <= n; i++) {
      const x = c.s === 0 ? i * dx : W - i * dx;
      pts.push([x, CY + (i % 2 ? a : -a)]);
    }
    const z0 = SZ + 1.5, z1 = SZ + CH;
    const topE = pts.map(([x, y]) => P(x, y, z1)), botE = pts.map(([x, y]) => P(x, y, z0));
    c.sheet.setAttribute("d", poly(topE.concat(botE.slice().reverse())));
    let d = "";
    pts.forEach(([x, y], i) => { if (i % 2 && i < n) d += seg(P(x, y, z1 - 1), P(x, y, z0 + 1)); });
    c.folds.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const c of sides) { draw(c, tval(c.w, now)); if (!tdone(c.w, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = [P(W / 4, CY, SZ + CH / 2), P((3 * W) / 4, CY, SZ + CH / 2)];
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 80 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    sides.forEach((c, k) => {
      const w = a < 0 ? (k === 0 ? 30 : 58) : k === a ? 58 - 40 * pull : 60;
      tset(c.w, w, now, from < 0 ? 0 : Math.abs(k - from) * 45);
      c.sheet.classList.toggle("hi", k === (a < 0 ? 0 : a));
    });
    read.textContent = a < 0 ? "rest" : a === 0 ? "left" : "right";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return {
    set: (v) => { pull = v; const a = act; act = -2; setActive(a); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "stagecurtain",
  means: "A school stage with two pleated curtains: the one under the pointer draws aside, bunching its pleats, and the other slides shut.",
  rules: [1, 2, 5, 6],
  range: [0.3, 0.75, 1],
  tour: [[146, 159], [220, 196], [176, 166], null],
  mount,
});

pharmacycounter.code:
/**
 * Pharmacy drawers: a cabinet of small drawers in rows. The pointer picks
 * a drawer by its resting front, and that drawer slides out, its neighbours
 * easing a little after it. At rest one drawer stands half open, bright. The
 * slider is the stagger.
 *
 * The pattern: grid on a face plane.
 */
const {
  Cam, fit, facing, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NC = 4, NR = 3, DW = 28, DH = 18, D = 34, OUT = 28, FAV = 6;
const CW = NC * DW + 6, CH = NR * DH + 10, CD = 40;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [CW, CD + OUT, 0], [0, CD + OUT, CH], [CW, 0, CH + 4], [CW, CD + OUT, CH]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, CW, CD, 3, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, CH));
  const [tr, ti] = rings(-3, -3, CW + 3, CD + 3, 4, 1.6);
  put(solid(g), prism(P, front, tr, ti, CH, CH + 4));
  const dg = mk("g", {}, g);
  const items = [];
  for (let r = NR - 1; r >= 0; r--) for (let c = 0; c < NC; c++) {
    const k = r * NC + c, x0 = 3 + c * DW + 1, z0 = 5 + r * DH + 1;
    const s = solid(mk("g", {}, dg)), knob = mk("path", { class: "nf" }, s.g);
    items.push({ k, r, c, x0, z0, s, knob, out: tween(k === FAV ? OUT * 0.5 : 0), last: NaN });
  }
  items.sort((a, b) => a.c - b.c || b.r - a.r).forEach((it) => dg.appendChild(it.s.g));
  const byK = []; items.forEach((it) => { byK[it.k] = it; });

  function draw(it, o) {
    if (o === it.last) return;
    it.last = o;
    const [ring, inner] = rings(it.x0, CD - D + o, it.x0 + DW - 2, CD + o, 1.5, 1);
    put(it.s, prism(P, front, ring, inner, it.z0, it.z0 + DH - 2));
    const mx = it.x0 + DW / 2 - 1, mz = it.z0 + DH / 2 - 1;
    it.knob.setAttribute("d", seg(P(mx - 4, CD + o + 0.2, mz), P(mx + 4, CD + o + 0.2, mz)));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.out, now)); if (!tdone(it.out, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = byK.map((it) => P(it.x0 + DW / 2 - 1, CD, it.z0 + DH / 2 - 1));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const sel = a < 0 ? FAV : a;
    byK.forEach((it, k) => {
      const dd = a < 0 ? 9 : Math.abs(it.c - byK[a].c) + Math.abs(it.r - byK[a].r);
      const o = a < 0 ? (k === FAV ? OUT * 0.5 : 0) : dd === 0 ? OUT : dd === 1 ? 6 : 0;
      const fd = from < 0 ? 0 : Math.abs(it.c - byK[from].c) + Math.abs(it.r - byK[from].r);
      tset(it.out, o, now, fd * stag);
      it.s.sil.classList.toggle("hi", k === sel);
    });
    if (a >= 0) dg.appendChild(byK[a].s.g); else items.forEach((it) => dg.appendChild(it.s.g));
    read.textContent = a < 0 ? "rest" : String.fromCharCode(65 + (NR - 1 - byK[a].r)) + (byK[a].c + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "pharmacycounter",
  means: "A cabinet of small pharmacy drawers: the drawer under the pointer slides out, its neighbours easing after it.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 90],
  tour: [[136, 152], [205, 160], [245, 151], null],
  mount,
});

maskbox.code:
/**
 * Glove boxes: three dispenser boxes lying in a row on a clinic shelf, each
 * with an oval slot in its top. The pointer picks a box by where it stands:
 * a glove pulls up out of its slot, and the boxes beside it offer a little,
 * staggered from it. At rest one glove stands half out, bright.
 * The slider is the stagger.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween, circ,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 46, BW = 38, BD = 26, BH = 16, SZ = 4, LIFT = 46, FAV = 1;
const X1 = (N - 1) * STEP + BW;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-6, -6, 0], [X1 + 6, BD + 6, 0], [X1 + 6, -6, 0], [-6, BD + 6, 0], [BW / 2, BD / 2, SZ + BH + LIFT + 8], [X1 - BW / 2, BD / 2, SZ + BH + LIFT + 8]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-6, -6, X1 + 6, BD + 6, 4, 1.6);
  put(solid(g), prism(P, front, sr, si, 0, SZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * STEP, grp = mk("g", {}, g), cx = x0 + BW / 2, cy = BD / 2;
    const [br, bi] = rings(x0, 0, x0 + BW, BD, 3, 1.4);
    put(solid(grp), prism(P, front, br, bi, SZ, SZ + BH));
    const slot = circ(1, 32).map((q) => ({ ...q, u: cx + q.u * 14, v: cy + q.v * 4.5 }));
    mk("path", { d: poly(ringAt(P, slot, SZ + BH)), class: "nf lo" }, grp);
    const glove = solid(grp);
    items.push({ k, cx, cy, glove, z: tween(k === FAV ? LIFT * 0.4 : 1), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const [gr, gi] = rings(it.cx - 15, it.cy - 3, it.cx + 15, it.cy + 3, 3, 1);
    const top = SZ + BH + lift;

    put(it.glove, prism(P, front, gr, gi, SZ + BH - 1, top));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.cx, it.cy, SZ + BH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 45 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.4 : 1) : dd === 0 ? LIFT : dd === 1 ? 6 : 1;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.glove.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "box " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "maskbox",
  means: "Three glove boxes on a shelf: the box under the pointer gives up a glove through its slot, and its neighbours offer one a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[133, 151], [194, 146], [267, 218], null],
  mount,
});

cheesewheel.code:
/**
 * Cheese wheels: four wheels lying on an aging board, each a thick round
 * with a rind crease and a wedge already cut. The pointer picks a wheel by
 * where it stands: it lifts off the board to be turned, and the wheels beside
 * it rise a little, staggered from it. At rest one wheel is raised, bright.
 * The slider is the stagger.
 */
const {
  Cam, circ, fit, facing, poly, open, prism, proj, rings, ringAt, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 42, R = 19, H = 13, BZ = 4, LIFT = 30, FAV = 2;
const X1 = (N - 1) * STEP + 2 * R;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-6, -6, 0], [X1 + 6, 2 * R + 6, 0], [X1 + 6, -6, 0], [-6, 2 * R + 6, 0], [R, R, BZ + H + LIFT + 4], [X1 - R, R, BZ + H + LIFT + 4]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-6, -6, X1 + 6, 2 * R + 6, 5, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = R + k * STEP, y = R, grp = mk("g", {}, g);
    const s = solid(grp), mid = mk("path", { class: "nf lo" }, grp), cut = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, y, s, mid, cut, z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = BZ + lift, z1 = z0 + H;
    put(it.s, prism(P, front, disc(it.x, it.y, R), disc(it.x, it.y, R - 2), z0, z1));
    // the rind's waist, on the near side only
    const waist = disc(it.x, it.y, R).filter(front);
    it.mid.setAttribute("d", open(ringAt(P, waist, z0 + H / 2)));
    // a wedge cut into the top, pointing at the far corner
    const c = P(it.x, it.y, z1), a = P(it.x - R + 4, it.y - 6, z1), b = P(it.x - 6, it.y - R + 4, z1);
    it.cut.setAttribute("d", seg(c, a) + seg(c, b));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, BZ + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 65 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 6 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "wheel " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "cheesewheel",
  means: "Four cheese wheels on an aging board: the wheel under the pointer lifts to be turned, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[122, 137], [174, 133], [278, 215], null],
  mount,
});

soupkettle.code:
/**
 * Ladle stand: a bar on two posts over a base, four ladles of different
 * sizes hanging from it. The pointer picks a ladle by where it stands: it
 * swings out off the bar toward the viewer, and its neighbours sway a
 * little, staggered from it. At rest one ladle hangs swung out, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rad, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 30, PAD = 16, H = 92, FAV = 2;
const X1 = PAD * 2 + (N - 1) * STEP;
const LEN = [50, 62, 56, 44], BOWL = [9, 11, 8, 7], REST = [4, -3, 28, 6];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-PAD, -18, 0], [X1 + PAD, 18, 0], [X1 + PAD, -18, 0], [-PAD, 18, 0], [0, 0, H + 6], [X1, 0, H + 6], [PAD + STEP, 62 * Math.sin(rad(58)), H - 62 * Math.cos(rad(58))]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-PAD, -18, X1 + PAD, 18, 8, 2);
  put(solid(g), prism(P, front, br, bi, 0, 5));
  for (const x of [0, X1]) put(solid(g), prism(P, front, disc(x, 0, 3.2), disc(x, 0, 2.2), 5, H + 2));
  const [rr, ri] = rings(-4, -2.6, X1 + 4, 2.6, 2.6, 1);
  put(solid(g), prism(P, front, rr, ri, H, H + 5));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = PAD + k * STEP, grp = mk("g", {}, g);
    const handle = mk("path", { class: "sil" }, grp), bowl = mk("path", { class: "sil" }, grp), lip = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, handle, bowl, lip, a: tween(REST[k]), last: NaN });
  }

  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    const L = LEN[it.k], R = BOWL[it.k], s = Math.sin(rad(a)), c = Math.cos(rad(a));
    const at = (d) => [d * s, H + 1 - d * c];
    const [y0, z0] = at(0), [y1, z1] = at(L - R);
    it.handle.setAttribute("d", poly(hull(ringAt(P, disc(it.x, y0, 1.6, 10), z0).concat(ringAt(P, disc(it.x, y1, 1.6, 10), z1)))));
    const [cy, cz] = at(L);
    const pts = [];
    for (let i = 0; i <= 4; i++) { const t = (i / 4) * (Math.PI / 2); pts.push(...ringAt(P, disc(it.x, cy, R * Math.cos(t)), cz - R * 0.8 * Math.sin(t))); }
    it.bowl.setAttribute("d", poly(hull(pts)));
    it.lip.setAttribute("d", poly(ringAt(P, disc(it.x, cy, R - 1.6), cz)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 0, H - LEN[it.k] / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 22 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), to = a < 0 ? REST[k] : dd === 0 ? 58 : dd === 1 ? 12 : REST[k] * 0.5;
      tset(it.a, to, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      it.handle.classList.toggle("hi", on);
      it.bowl.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "ladle " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "soupkettle",
  means: "Four ladles hanging from a stand: the ladle under the pointer swings out off the bar, and its neighbours sway a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[150, 112], [179, 127], [236, 150], null],
  mount,
});

cookiejar.code:
/**
 * Cookie jars: three round jars of different heights on a counter, each with
 * a flat lid and a knob. The pointer picks a jar by where it stands: its lid
 * lifts off and a cookie rises out of the mouth. At rest one lid sits a
 * little raised, bright. The slider is the lift.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const JR = 16, STEP = 46, HS = [34, 46, 28], FAV = 1, CZ = 4;
const X1 = 2 * STEP + 2 * JR + 4;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 2.0);
  const top = CZ + 46 + 34 + 8;
  fit(C, [[-8, -8, 0], [X1 + 8, 2 * JR + 12, 0], [X1 + 8, -8, 0], [-8, 2 * JR + 12, 0], [JR + 2 + STEP, JR + 2, top]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-8, -8, X1 + 8, 2 * JR + 12, 7, 2);
  put(solid(g), prism(P, front, cr, ci, 0, CZ));

  const jars = HS.map((h, k) => {
    const x = JR + 2 + k * STEP, y = JR + 2, grp = mk("g", {}, g), z1 = CZ + h;
    put(solid(grp), prism(P, front, disc(x, y, JR), disc(x, y, JR - 1.5), CZ, z1));
    // a raised band round the shoulder
    const band = ringAt(P, disc(x, y, JR, 40).filter(front), z1 - 7);
    mk("path", { d: band.length ? "M" + band.map((p) => p.join(",")).join("L") : "", class: "nf lo" }, grp);
    const treat = solid(grp), lid = solid(grp), knob = solid(grp);
    return { k, x, y, z1, treat, lid, knob, z: tween(k === FAV ? 0.25 : 0), last: NaN };
  });

  function draw(j, t) {
    if (t === j.last) return;
    j.last = t;
    const L = lift * t, lz = j.z1 + L, cz = j.z1 - 3 + L * 0.5;
    if (t > 0.3) put(j.treat, prism(P, front, disc(j.x, j.y, 11, 28), disc(j.x, j.y, 9.5, 28), cz, cz + 2.4));
    else put(j.treat, { sil: "", crease: "" });
    put(j.lid, prism(P, front, disc(j.x, j.y, JR + 1.5), disc(j.x, j.y, JR - 1), lz, lz + 3));
    put(j.knob, prism(P, front, disc(j.x, j.y, 3.2, 20), disc(j.x, j.y, 2, 20), lz + 3, lz + 7));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const j of jars) { draw(j, tval(j.z, now)); if (!tdone(j.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = jars.map((j) => P(j.x, j.y, j.z1 / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 75 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    jars.forEach((j, k) => {
      tset(j.z, a < 0 ? (k === FAV ? 0.25 : 0) : k === a ? 1 : 0, now, 0);
      j.lid.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
      j.knob.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "jar " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = v; jars.forEach((j) => { j.last = NaN; }); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "cookiejar",
  means: "Three cookie jars on a counter: the jar under the pointer lifts its lid and a cookie rises out of the mouth.",
  rules: [1, 4, 5, 6],
  range: [14, 26, 34],
  tour: [[135, 146], [200, 161], [265, 211], null],
  mount,
});

spicejars.code:
/**
 * Spice carousel: a round turntable carrying eight small jars around a
 * centre post. Circling the pointer round it turns the carousel like a dial;
 * the jar that comes to the front lifts out of its seat, bright. At rest the
 * carousel stands a little turned with one jar raised. The slider is the lift.
 *
 * The pattern: a dial turned by the pointer's angle on the ground.
 */
const {
  Cam, circ, fit, facing, poly, prism, proj, rings, spring, stepS, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 8, R = 34, JR = 8, BR = 47, HS = [22, 18, 24, 20, 23, 17, 21, 19], FAV = 2, FRONT = Math.PI / 4;
const STEP = (2 * Math.PI) / N;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const wrap = (a) => Math.atan2(Math.sin(a), Math.cos(a));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-BR, -BR, 0], [BR, BR, 0], [BR, -BR, 0], [-BR, BR, 0], [0, 0, 52], [R * 0.7, R * 0.7, 6 + 24 + 40 + 5]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(0, 0, BR, 56), disc(0, 0, BR - 2, 56), 0, 5));
  const top = mk("g", {}, g);
  const post = solid(top);
  put(post, prism(P, front, disc(0, 0, 3.5, 20), disc(0, 0, 2.5, 20), 5, 46));
  put(solid(post.g), prism(P, front, disc(0, 0, 9, 28), disc(0, 0, 7.5, 28), 46, 49));
  const jars = HS.map((h, k) => {
    const grp = mk("g", {}, top);
    return { k, h, grp, body: solid(grp), lid: solid(grp), z: tween(k === FAV ? 0.5 : 0), last: NaN, lr: NaN };
  });

  const r0 = FRONT - FAV * STEP + 0.14;
  const rot = spring(r0);

  function drawJar(j, r, t) {
    if (r === j.lr && t === j.last) return;
    j.lr = r; j.last = t;
    const a = r + j.k * STEP, x = R * Math.cos(a), y = R * Math.sin(a), z0 = 5 + lift * t, z1 = z0 + j.h;
    j.d = x + y;
    put(j.body, prism(P, front, disc(x, y, JR), disc(x, y, JR - 1.2), z0, z1));
    put(j.lid, prism(P, front, disc(x, y, JR + 0.8), disc(x, y, JR - 0.6), z1, z1 + 4));
  }

  const B = register(stage, (dt, now) => {
    const m = stepS(rot, dt);
    let moving = m;
    for (const j of jars) { drawJar(j, rot.x, tval(j.z, now)); if (!tdone(j.z, now)) moving = true; }
    const order = jars.map((j) => ({ g: j.grp, d: j.d })).concat([{ g: post.g, d: 0 }]).sort((a, b) => a.d - b.d);
    for (const o of order) top.appendChild(o.g);
    return moving;
  });
  bag.add(B.unregister);

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    jars.forEach((j, k) => {
      tset(j.z, a < 0 ? (k === FAV ? 0.5 : 0) : k === a ? 1 : 0, now, 0);
      j.lid.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "jar " + (a + 1);
  }
  // the jar the target turn brings nearest the front
  const facingJar = () => {
    let best = 0, bd = Infinity;
    jars.forEach((j, k) => { const d = Math.abs(wrap(rot.t + k * STEP - FRONT)); if (d < bd) { bd = d; best = k; } });
    return best;
  };
  let prev = null;
  function leave() {
    prev = null;
    rot.t = r0 + Math.round((rot.t - r0) / (2 * Math.PI)) * 2 * Math.PI;
    setActive(-1);
    B.wake();
  }
  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, 0);
    if (Math.hypot(wx, wy) > BR + 26) return leave();
    const th = Math.atan2(wy, wx);
    if (prev !== null) rot.t += wrap(th - prev);
    prev = th;
    setActive(facingJar());
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = v; jars.forEach((j) => { j.last = NaN; }); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "spicejars",
  means: "A spice carousel: circling the pointer turns it like a dial, and the jar brought to the front lifts out of its seat.",
  rules: [1, 3, 4, 5, 6],
  range: [16, 30, 40],
  tour: [[115, 156], [200, 199], [285, 156], null],
  mount,
});

baguettebasket.code:
/**
 * Bread basket: a long low basket holding five rolls lying side by side.
 * The pointer picks a roll by where it stands: it lifts out of the basket,
 * and the rolls beside it rise a little, staggered from it. At rest one roll
 * sits raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 20, RW = 16, RL = 40, BZ = 14, LIFT = 26, FAV = 3;
const X1 = N * STEP + 8, Y1 = RL + 10;
const LEN = [38, 34, 40, 36, 32];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [X1, 0, 0], [0, Y1, 0], [X1 / 2, Y1 / 2, BZ + LIFT + 12]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the basket's back wall and floor first, rolls inside, then the front rim over them
  const [br, bi] = rings(0, 0, X1, Y1, 14, 2.5);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  const rolls = [];
  for (let k = 0; k < N; k++) {
    const x = 4 + k * STEP + 2, y = (Y1 - LEN[k]) / 2, grp = mk("g", {}, g);
    const s = solid(grp), score = mk("path", { class: "nf lo" }, grp);
    rolls.push({ k, x, y, L: LEN[k], s, score, z: tween(k === FAV ? 0.5 : 0), last: NaN });
  }

  // the front wall, painted over the rolls' bottoms
  const fw = run(br, front);
  mk("path", { d: poly(ringAt(P, fw, BZ).concat(ringAt(P, fw, 0).reverse())), class: "sil" }, g);
  mk("path", { d: "M" + ringAt(P, run(bi, front), BZ).map((p) => p.join(",")).join("L"), class: "nf lo" }, g);

  function draw(r, t) {
    if (t === r.last) return;
    r.last = t;
    const z0 = BZ - 8 + LIFT * t, [a, b] = rings(r.x, r.y, r.x + RW, r.y + r.L, 8, 1.6);
    put(r.s, prism(P, front, a, b, z0, z0 + 11));
    let d = "";
    for (const f of [0.3, 0.5, 0.7]) {
      const p = P(r.x + 4, r.y + r.L * f - 3, z0 + 11), q = P(r.x + RW - 4, r.y + r.L * f + 3, z0 + 11);
      d += "M" + p.join(",") + "L" + q.join(",");
    }
    r.score.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const r of rolls) { draw(r, tval(r.z, now)); if (!tdone(r.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = rolls.map((r) => P(r.x + RW / 2, r.y + r.L / 2, BZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    rolls.forEach((r, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? 0.5 : 0) : dd === 0 ? 1 : dd === 1 ? 0.22 : 0;
      tset(r.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      r.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "roll " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "baguettebasket",
  means: "A bread basket of five rolls: the roll under the pointer lifts out, and its neighbours rise a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[145, 137], [200, 165], [255, 193], null],
  mount,
});

blindsroller.code:
/**
 * Roller blind: a window in a wall panel, a roller across its head and a
 * blind hanging from it, with a weighted bar and a pull cord. The pointer's
 * height over the window draws the blind down or lets it roll up, on a
 * spring. At rest the blind hangs a third down, its bar bright. The slider is
 * how far the blind can drop.
 *
 * The pattern: one continuous value read from the pointer (pull).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, clamp, lerp, spring, stepS,
  disposer, mk, pointer, put, register, solid, seg,
} = HL;

const W = 110, H = 140, WY = 6, X0 = 18, X1 = 92, Z0 = 26, Z1 = 118, BY = 10, RZ = 124, REST = 0.36;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value / 100;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[0, 0, 0], [W, 0, 0], [0, 22, 0], [W, 22, 0], [0, 0, H], [W, 0, H], [W, 22, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // wall panel and window opening
  const [wr, wi] = rings(0, 0, W, WY, 3, 1.4);
  put(solid(g), prism(P, front, wr, wi, 0, H));
  const quad = (x0, z0, x1, z1, y) => [P(x0, y, z0), P(x1, y, z0), P(x1, y, z1), P(x0, y, z1)];
  mk("path", { d: poly(quad(X0, Z0, X1, Z1, WY)), class: "nf" }, g);
  mk("path", { d: seg(P((X0 + X1) / 2, WY, Z0), P((X0 + X1) / 2, WY, Z1)) + seg(P(X0, WY, (Z0 + Z1) / 2), P(X1, WY, (Z0 + Z1) / 2)), class: "nf lo" }, g);
  // blind, its bar and cord
  const blind = mk("path", { class: "" }, g);
  const bar = mk("path", { class: "sil" }, g);
  const cord = mk("path", { class: "nf lo" }, g);
  const pull = mk("path", { class: "" }, g);
  // roller head: a rounded box across the window top
  const [rr, ri] = rings(X0 - 6, WY, X1 + 6, WY + 9, 4, 1.2);
  put(solid(g), prism(P, front, rr, ri, RZ - 5, RZ + 5));
  // sill
  const [sr, si] = rings(X0 - 8, 0, X1 + 8, 18, 3, 1.4);
  put(solid(g), prism(P, front, sr, si, Z0 - 6, Z0 - 1));

  const tube = (x0, x1, y, z, r) => {
    const pts = [];
    for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; pts.push(P(x0, y + r * Math.cos(a), z + r * Math.sin(a)), P(x1, y + r * Math.cos(a), z + r * Math.sin(a))); }
    return poly(hull(pts));
  };
  const maxDrop = () => lerp(30, RZ - 5 - Z0 - 6, reach);
  const s = spring(REST);
  let last = NaN;
  function draw(t) {
    const key = t * 1000 + reach;
    if (key === last) return;
    last = key;
    const bz = RZ - 5 - 4 - t * maxDrop();
    blind.setAttribute("d", poly(quad(X0 - 2, bz, X1 + 2, RZ - 4, BY)));
    bar.setAttribute("d", tube(X0 - 3, X1 + 3, BY, bz, 2.4));
    const cx = X1 - 12, cz = bz - 14;
    cord.setAttribute("d", seg(P(cx, BY, bz - 2), P(cx, BY, cz + 2.5)));
    const ring = [];
    for (let i = 0; i < 12; i++) { const a = (i / 12) * Math.PI * 2; ring.push(P(cx + 2.4 * Math.cos(a), BY, cz + 3 * Math.sin(a))); }
    pull.setAttribute("d", poly(hull(ring)));
  }
  const B = register(stage, (dt) => { const m = stepS(s, dt); draw(s.x); return m; });
  bag.add(B.unregister);

  // static hit: the window's rest rectangle on screen
  const top = P((X0 + X1) / 2, WY, RZ)[1], bot = P((X0 + X1) / 2, WY, Z0 - 6)[1];
  const lx = P(X0 - 8, WY, Z1)[0], rx = P(X1 + 8, WY, Z1)[0];
  function move([sx, sy]) {
    const inside = sx > lx - 14 && sx < rx + 14 && sy > top - 20 && sy < bot + 30;
    if (!inside) return leave();
    s.t = clamp((sy - top) / (bot - top), 0.04, 1);
    bar.classList.add("hi");
    read.textContent = Math.round(s.t * 100) + "%";
    B.wake();
  }
  function leave() { s.t = REST; bar.classList.add("hi"); read.textContent = "rest"; B.wake(); }
  leave();
  draw(REST);
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v / 100; last = NaN; B.wake(); }, destroy: bag.dispose };
}

