plugstrip.code:
/**
 * Power strip: a long strip with four sockets in a row, a plug seated in
 * each, a switch at the end. The pointer picks a socket by where it stands:
 * that plug pulls out of its socket, prongs showing, and the plugs beside it
 * ease up a little, staggered from it. At rest one plug is half out, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 30, SZ = 9, PW = 9, PH = 14, LIFT = 26, FAV = 1, X0 = 22;
const REST = [0, 12, 2, 0];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.2);
  const X1 = X0 + (N - 1) * STEP + 34;
  fit(C, [[0, 0, 0], [X1, 28, 0], [X1, 0, 0], [0, 28, 0], [X0, 14, SZ + LIFT + PH + 6], [X1 - 30, 14, SZ + LIFT + PH + 6]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(0, 0, X1, 28, 8, 2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));
  // the switch at the far end of the row
  const [wr, wi] = rings(X1 - 22, 7, X1 - 8, 21, 3, 1);
  const sw = solid(g);
  put(sw, prism(P, front, wr, wi, SZ, SZ + 3));
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP, y = 14;
    // the socket: two slots in the strip's top
    const slots = mk("path", { class: "nf lo", d: seg(P(x - 3, y - 3, SZ), P(x - 3, y + 3, SZ)) + seg(P(x + 3, y - 3, SZ), P(x + 3, y + 3, SZ)) }, g);
    const grp = mk("g", {}, g);
    const prongs = mk("path", { class: "nf" }, grp);
    const body = solid(grp), nub = solid(grp);
    items.push({ k, x, y, slots, prongs, body, nub, z: tween(REST[k]), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const { x, y } = it, b = SZ + lift;
    it.prongs.setAttribute("d", seg(P(x - 3, y, SZ), P(x - 3, y, b + 1)) + seg(P(x + 3, y, SZ), P(x + 3, y, b + 1)));
    const [br, bi] = rings(x - PW, y - PW, x + PW, y + PW, 4, 1.6);
    put(it.body, prism(P, front, br, bi, b, b + PH));
    const [nr, ni] = rings(x - 4, y - 4, x + 4, y + 4, 4, 1);
    put(it.nub, prism(P, front, nr, ni, b + PH, b + PH + 5));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, SZ + PH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? REST[k] : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "socket " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "plugstrip",
  means: "A power strip with four plugs: the plug under the pointer pulls out of its socket, prongs showing, and its neighbours ease up.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[121, 154], [214, 200], [261, 224], null],
  mount,
});

piggyvault.code:
/**
 * Coin dispenser: four coin tubes standing on a dispenser base, each holding
 * a stack of a different height. The pointer picks a tube by where it
 * stands: its top coin springs up out of the stack, and the tubes beside it
 * nudge theirs up a little, staggered from it. At rest one coin is raised,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, prism, proj, ringAt, open, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, rings,
} = HL;

const N = 4, STEP = 30, R = 11, BZ = 8, CH = 3, LIFT = 24, FAV = 1;
const H = [9, 6, 11, 7];
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  const X1 = 2 * R + 8 + (N - 1) * STEP;
  const top = BZ + 11 * CH + LIFT + CH;
  fit(C, [[0, 0, 0], [X1, 30, 0], [X1, 0, 0], [0, 30, 0], [R + 4, 15, top], [X1 - R - 4, 15, top]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, X1, 30, 7, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = R + 4 + k * STEP, y = 15, h = BZ + H[k] * CH;
    const grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, y, R), disc(x, y, R - 1.5), BZ, h));
    // the coin edges down the stack
    let d = "";
    for (let c = 1; c < H[k]; c++) d += open(ringAt(P, disc(x, y, R).filter(front), BZ + c * CH));
    mk("path", { class: "nf lo", d }, grp);
    const coin = solid(grp);
    items.push({ k, x, y, h, coin, z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    put(it.coin, prism(P, front, disc(it.x, it.y, R), disc(it.x, it.y, R - 2.5), it.h + lift, it.h + lift + CH));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, it.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.coin.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tube " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "piggyvault",
  means: "Four coin tubes on a dispenser: the top coin of the tube under the pointer springs up off its stack, and its neighbours nudge up.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[127, 129], [224, 178], [273, 202], null],
  mount,
});

calculatorroll.code:
/**
 * Calculatorroll: an adding machine, a block body with a grid of nine keys
 * and a paper roll at its back, the tape standing up out of it. The pointer
 * picks a key on its rest top: the key presses down and the tape feeds out
 * a little further. At rest one key is half down, bright. The slider is how
 * far a press feeds the tape.
 *
 * The pattern: one of many on a face plane (depositboxes).
 */
const {
  Cam, fit, hull, open, poly, prism, proj, rings, facing, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid, seg,
} = HL;

const BX = 92, BY = 70, BZ = 16, KS = 15, KG = 4, KH = 6, RX = 14, RZ = BZ + 9, RR = 9, FAV = 4;
const KX0 = 32, KY0 = 9;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let feed = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[0, 0, 0], [BX, BY, 0], [BX, 0, 0], [0, BY, 0], [RX, 12, RZ + 74], [RX, BY - 12, RZ + 74]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, BX, BY, 8, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));

  // the tape, then the roll in front of its foot
  const tape = mk("path", { class: "sil" }, g), lines = mk("path", { class: "lo nf" }, g);
  const roll = mk("path", { class: "sil" }, g), rollEnd = mk("path", { class: "nf lo" }, g);
  const circle = (y) => { const pts = []; for (let i = 0; i < 28; i++) { const t = (i / 28) * Math.PI * 2; pts.push(P(RX + RR * Math.cos(t), y, RZ + RR * Math.sin(t))); } return pts; };
  roll.setAttribute("d", poly(hull(circle(10).concat(circle(BY - 10)))));
  rollEnd.setAttribute("d", poly(circle(BY - 10)));
  const tp = tween(20);
  let lastT = NaN;
  function drawTape(h) {
    if (h === lastT) return;
    lastT = h;
    const x = RX + RR - 1, z0 = RZ, z1 = RZ + h, y0 = 13, y1 = BY - 13;
    tape.setAttribute("d", poly([P(x, y0, z0), P(x, y1, z0), P(x, y1, z1), P(x - 3, y0 + (y1 - y0) * 0.5, z1 + 3), P(x, y0, z1)]));
    let d = "";
    for (let zz = z1 - 6; zz > z0 + RR; zz -= 7) d += seg(P(x, y0 + 6, zz), P(x, y1 - 6 - ((zz * 7) % 14), zz));
    lines.setAttribute("d", d);
  }

  const keys = [];
  for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) {
    const x0 = KX0 + i * (KS + KG), y0 = KY0 + j * (KS + KG);
    keys.push({ i, j, x0, y0, s: null, z: tween(0), last: NaN });
  }
  keys.sort((a, b) => a.x0 + a.y0 - (b.x0 + b.y0));
  keys.forEach((k) => { k.s = solid(g); k.n = k.i * 3 + k.j; });
  const [kr, ki] = rings(0, 0, KS, KS, 4, 1.4);
  const shift = (ring, dx, dy) => ring.map((q) => ({ ...q, u: q.u + dx, v: q.v + dy }));
  function drawKey(k, d) {
    if (d === k.last) return;
    k.last = d;
    put(k.s, prism(P, front, shift(kr, k.x0, k.y0), shift(ki, k.x0, k.y0), BZ, BZ + KH - d));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const k of keys) { drawKey(k, tval(k.z, now)); if (!tdone(k.z, now)) moving = true; }
    drawTape(tval(tp, now)); if (!tdone(tp, now)) moving = true;
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, BZ + KH);
    for (const k of keys) if (wx > k.x0 - KG / 2 && wx < k.x0 + KS + KG / 2 && wy > k.y0 - KG / 2 && wy < k.y0 + KS + KG / 2) return k.n;
    return -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    const on = a < 0 ? FAV : a;
    keys.forEach((k) => {
      tset(k.z, k.n === a ? KH - 1.5 : a < 0 && k.n === FAV ? 2.5 : 0, now, 0);
      k.s.sil.classList.toggle("hi", k.n === on);
    });
    tset(tp, a < 0 ? 20 : 26 + feed * (2.5 + (a % 3)) + 5 * Math.floor(a / 3), now, 0);
    read.textContent = a < 0 ? "rest" : "key " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { feed = v; }, destroy: bag.dispose };
}

hairline({
  name: "calculatorroll",
  means: "An adding machine with nine keys and a paper roll: the key under the pointer presses down and the tape feeds out.",
  rules: [1, 4, 5, 8],
  range: [4, 8, 12],
  tour: [[217, 191], [217, 218], [217, 245], null],
  mount,
});

investmentchart.code:
/**
 * Investmentchart: a pie chart built as a thick round cake of five slices of
 * uneven share. The pointer picks a slice by its angle on the rest top: that
 * slice slides out from the centre and rises, and the others close in. At
 * rest the largest share stands a little out, bright. The slider is how far
 * a chosen slice slides out.
 *
 * The pattern: one of many around a centre, picked by angle.
 */
const {
  Cam, fit, fillet, hull, poly, proj, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 62, TH = 12, SH = [0.31, 0.24, 0.19, 0.15, 0.11], A0 = -2.2, FAV = 0;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let out = value;
  const C = Cam(45, 0.5, 2.1);
  const ext = R + 26;
  fit(C, [[-ext, -ext, 0], [ext, ext, 0], [ext, -ext, 0], [-ext, ext, 0], [0, -ext, TH + 10], [-ext, 0, TH + 10]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const guide = [];
  for (let i = 0; i < 48; i++) { const t = (i / 48) * Math.PI * 2; guide.push(P(R * Math.cos(t), R * Math.sin(t), 0)); }
  mk("path", { d: poly(guide), class: "dash nf" }, g);

  const slices = [];
  let a = A0;
  SH.forEach((f, n) => {
    const a0 = a, a1 = a + f * Math.PI * 2, m = (a0 + a1) / 2;
    a = a1;
    slices.push({ n, f, a0, a1, m, s: null, d: tween(0), z: tween(0), last: "" });
  });
  slices.slice().sort((p, q) => Math.cos(p.m) + Math.sin(p.m) - (Math.cos(q.m) + Math.sin(q.m))).forEach((sl) => { sl.s = solid(g); });

  function wedge(sl, r, inset) {
    const cx = inset * Math.cos(sl.m) / Math.sin((sl.a1 - sl.a0) / 2), cy = inset * Math.sin(sl.m) / Math.sin((sl.a1 - sl.a0) / 2);
    const pts = [[cx, cy]], rs = [3];
    const steps = Math.max(4, Math.round((sl.a1 - sl.a0) / 0.09));
    const da = inset / r;
    for (let i = 0; i <= steps; i++) {
      const t = sl.a0 + da + ((sl.a1 - sl.a0 - 2 * da) * i) / steps;
      pts.push([r * Math.cos(t), r * Math.sin(t)]);
      rs.push(i === 0 || i === steps ? 3 : 0);
    }
    return fillet(pts, rs, 3);
  }
  slices.forEach((sl) => { sl.outer = wedge(sl, R, 1.2); sl.inner = wedge(sl, R - 2, 3.2); });

  function draw(sl, d, z) {
    const key = d + "," + z;
    if (key === sl.last) return;
    sl.last = key;
    const ox = d * Math.cos(sl.m), oy = d * Math.sin(sl.m);
    const at = (pts, zz) => pts.map(([x, y]) => P(x + ox, y + oy, zz));
    put(sl.s, { sil: poly(hull(at(sl.outer, z).concat(at(sl.outer, z + TH)))), crease: poly(at(sl.inner, z + TH)) });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const sl of slices) { draw(sl, tval(sl.d, now), tval(sl.z, now)); if (!tdone(sl.d, now) || !tdone(sl.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, TH);
    if (Math.hypot(wx, wy) > R + 14) return -1;
    let t = Math.atan2(wy, wx);
    while (t < A0) t += Math.PI * 2;
    for (const sl of slices) if (t >= sl.a0 && t < sl.a1) return sl.n;
    return -1;
  }

  let act = -2;
  function setActive(i) {
    if (i === act) return;
    const now = performance.now();
    act = i;
    const on = i < 0 ? FAV : i;
    slices.forEach((sl) => {
      const me = sl.n === on;
      tset(sl.d, me ? (i < 0 ? out * 0.45 : out) : 0, now, 0);
      tset(sl.z, me && i >= 0 ? 8 : 0, now, 0);
      sl.s.sil.classList.toggle("hi", me);
    });
    read.textContent = i < 0 ? "rest" : Math.round(SH[i] * 100) + "%";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { out = v; }, destroy: bag.dispose };
}

hairline({
  name: "investmentchart",
  means: "A pie chart of five uneven slices: the slice under the pointer slides out from the centre and rises.",
  rules: [1, 3, 4, 5],
  range: [10, 18, 26],
  tour: [[271, 127], [222, 182], [185, 106], null],
  mount,
});

bunsenrack.code:
/**
 * Funnel stand: a base with a post holding a slotted shelf, three filter
 * funnels sitting in its rings over three beakers. The pointer picks a funnel
 * by where it stands: it lifts out of its ring, and its neighbours rise a
 * little, staggered from it. At rest the middle funnel stands raised, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 34, FR = 13, S0 = 40, LIFT = 20, FAV = 1, Y = 14, BZ = 4;
const X1 = (N - 1) * STEP + 2 * FR;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-14, -4, 0], [X1 + 8, 32, 0], [X1 + 8, -4, 0], [-14, 32, 0], [FR, Y, S0 + LIFT + 18], [X1 - FR, Y, S0 + LIFT + 18]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const cyl = (grp, x, y, r, z0, z1, b = 1.2) => put(solid(grp), prism(P, front, disc(x, y, r), disc(x, y, r - b), z0, z1));
  const [br, bi] = rings(-14, -4, X1 + 8, 32, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  cyl(g, -6, Y, 3, BZ, S0 - 2, 0.8);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = FR + k * STEP, grp = mk("g", {}, g);
    cyl(grp, x, Y, 9, BZ, BZ + 20, 1.4);
    const stemLo = mk("path", { class: "sil" }, grp);
    items.push({ k, x, stemLo, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }
  const [sr, si] = rings(-12, 2, X1 + 2, 26, 4, 1.5);
  put(solid(g), prism(P, front, sr, si, S0 - 2, S0));
  for (const it of items) {
    it.grp = mk("g", {}, g);
    mk("path", { d: poly(ringAt(P, disc(it.x, Y, 3.5), S0)), class: "nf lo" }, it.grp);
    it.stemHi = mk("path", { class: "sil" }, it.grp);
    it.cone = mk("path", { class: "sil" }, it.grp);
    it.rim = mk("path", { class: "nf lo" }, it.grp);
  }

  const tube = (x, z0, z1) => (z1 - z0 < 0.2 ? "" : poly(hull(ringAt(P, disc(x, Y, 1.6, 12), z0).concat(ringAt(P, disc(x, Y, 1.6, 12), z1)))));
  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const lo = S0 - 12 + lift, top = S0 + lift + 17;
    it.stemLo.setAttribute("d", tube(it.x, lo, Math.min(S0 - 2, S0 + lift)));
    it.stemHi.setAttribute("d", tube(it.x, Math.max(S0, lo), S0 + lift));
    it.cone.setAttribute("d", poly(hull(ringAt(P, disc(it.x, Y, 2.2), S0 + lift).concat(ringAt(P, disc(it.x, Y, FR, 40), top)))));
    it.rim.setAttribute("d", poly(ringAt(P, disc(it.x, Y, FR - 1.6, 40), top)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, Y, S0));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.cone.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "funnel " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

