gymlockers.code:
/**
 * Gym bench: an adjustable bench on a steel rail, a seat pad near the foot
 * and a backrest hinged at the seat, held up by a strut. The pointer along
 * the bench sets the incline: toward the head end the backrest rises
 * steeper, toward the hinge it lies flat. At rest it stands at 30°, bright.
 * The slider is the rest incline.
 *
 * The pattern: one part answering the pointer's position (aim).
 */
const {
  Cam, clamp, fit, facing, hull, open, poly, prism, proj, rad, rings, rrect, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const HX = 60, HZ = 34, BL = 58, BW = 13, BT = 7, AMAX = 80;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let restA = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-4, -18, 0], [110, 18, 0], [110, -18, 0], [-4, 18, 0], [HX - BL * Math.cos(rad(AMAX)), 0, HZ + BL * Math.sin(rad(AMAX)) + BT], [HX - BL, -BW, HZ + BT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r, b) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, o, i, z0, z1)); };

  box(0, -17, 9, 17, 0, 6, 3, 1);          // head foot
  box(4, -4, 106, 4, 6, 13, 3, 1);         // rail
  const strut = mk("path", { class: "nf" }, g);
  const back = solid(g), backTop = mk("path", { class: "nf lo" }, g);
  box(76, -3, 84, 3, 13, 30, 2, 0.8);      // seat post
  box(97, -18, 106, 18, 0, 6, 3, 1);       // foot bar
  box(62, -BW, 102, BW, 30, 37, 6, 1.6);   // seat pad

  const outer = rrect(0, -BW, BL, BW, 6, 6), inner = rrect(1.6, -BW + 1.6, BL - 1.6, BW - 1.6, 4.4, 6);
  const at = (s, y, t, a) => { const c = Math.cos(a), n = Math.sin(a); return P(HX - s * c + t * n, y, HZ + s * n + t * c); };
  const ang = spring(restA);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg);
    const pts = outer.map((q) => at(q.u, q.v, 0, a)).concat(outer.map((q) => at(q.u, q.v, BT, a)));
    back.sil.setAttribute("d", poly(hull(pts)));
    back.cr.setAttribute("d", "");
    backTop.setAttribute("d", poly(inner.map((q) => at(q.u, q.v, BT, a))));
    // the strut: from a notch on the rail up under the backrest
    const s = 30, foot = P(HX - 34 + 14 * (deg / AMAX), 0, 13);
    strut.setAttribute("d", open([foot, at(s, 0, 0, a)]) + open([P(HX - 34 + 14 * (deg / AMAX), -3, 13), at(s, -3, 0, a)]));
  }

  const B = register(stage, (dt) => {
    const moving = stepS(ang, dt);
    draw(ang.x);
    return moving;
  });
  bag.add(B.unregister);

  let mode = "rest";
  function aim(p) {
    let deg = null;
    if (p) {
      const [wx, wy] = unproj(C, p[0], p[1], 0);
      if (wx > -25 && wx < 120 && Math.abs(wy) < 45) deg = clamp((HX - wx) / HX, 0, 1) * AMAX;
    }
    ang.t = deg === null ? restA : deg;
    back.sil.classList.add("hi");
    read.textContent = deg === null ? "rest" : Math.round(deg / 5) * 5 + "°";
    mode = deg === null ? "rest" : "aim";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { restA = v; if (mode === "rest") aim(null); }, destroy: bag.dispose };
}

hairline({
  name: "gymlockers",
  means: "An adjustable gym bench: the pointer along the bench sets the backrest's incline, steeper toward the head end, flat at the hinge.",
  rules: [1, 3, 5, 8],
  range: [10, 30, 60],
  tour: [[106, 181], [138, 197], [207, 232], null],
  mount,
});

waterbottles.code:
/**
 * Gym bottles: five water bottles of different sizes standing on a gym
 * shelf, each with a shoulder, a neck and a cap. The pointer picks a bottle
 * by where it stands: it lifts off the shelf, and the bottles beside it rise
 * a little, staggered from it. At rest one bottle is raised, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 28, SZ = 6, LIFT = 26, FAV = 3, D = 30;
const RAD = [10, 8, 11.5, 9, 10.5], HB = [44, 56, 36, 50, 40];
const X1 = (N - 1) * STEP + 2 * 14, Y = D / 2;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-4, -4, 0], [X1 + 4, D + 4, 0], [X1 + 4, -4, 0], [-4, D + 4, 0], [14, Y, SZ + 64 + LIFT], [X1 - 14, Y, SZ + 64]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-4, -4, X1 + 4, D + 4, 4, 1.6);
  put(solid(g), prism(P, front, sr, si, 0, SZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 14 + k * STEP, s = solid(mk("g", {}, g));
    items.push({ k, x, s, z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const r = RAD[it.k], h = HB[it.k], z0 = SZ + 0.4 + lift, x = it.x;
    const prof = [[r, 0], [r, h * 0.72], [r * 0.92, h * 0.8], [r * 0.58, h * 0.9], [r * 0.58, h], [r * 0.66, h], [r * 0.66, h + 8]];
    const pts = [];
    for (const [rr, zz] of prof) pts.push(...ringAt(P, disc(x, Y, rr), z0 + zz));
    it.s.sil.setAttribute("d", poly(hull(pts)));
    const cr = (rr, zz) => open(ringAt(P, run(disc(x, Y, rr), front), z0 + zz));
    it.s.cr.setAttribute("d", cr(r - 0.6, h * 0.72) + " " + cr(r * 0.66 - 0.4, h) + " " + cr(r - 0.6, h * 0.18));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, Y, SZ + HB[it.k] / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bottle " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "waterbottles",
  means: "Five gym bottles stand on a shelf: the bottle under the pointer lifts off, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[125, 148], [162, 166], [275, 223], null],
  mount,
});

harmoniums.code:
/**
 * Harmonium: a box organ with a keyboard along its top and a hand-pumped
 * bellows on its back, a hinged board with pleated sides. The pointer's
 * place across the figure sets how far the bellows board swings open, on a
 * spring; leaving lets it fall back to a slight open. The board is the
 * bright mark. The slider is the widest opening.
 *
 * The pattern: one part following the pointer (swing).
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rad, rings, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 130, D = 52, H = 40, HZ = 8, L = 62, REST = 10;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amax = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, -L, 0], [W, D, 0], [W, 0, H + 6], [0, -L, HZ + L], [W, -L, HZ + L], [0, D, H + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const plate = mk("path", { class: "sil hi" }, g);
  const side = mk("path", { class: "nf lo" }, g);
  const fan = mk("path", {}, g);
  const body = mk("g", {}, g);
  const [br, bi] = rings(0, 0, W, D, 5, 1.8);
  put(solid(body), prism(P, front, br, bi, 0, H));
  const [kr, ki] = rings(8, D - 24, W - 8, D - 5, 2, 1);
  put(solid(body), prism(P, front, kr, ki, H, H + 4));
  let keys = "";
  for (let x = 14; x < W - 10; x += 8) keys += seg(P(x, D - 24, H + 4), P(x, D - 5, H + 4)) + " ";
  mk("path", { d: keys, class: "nf lo" }, body);
  for (let x = 18; x < W - 14; x += 16) {
    const [rr, ri] = rings(x - 2, D - 24, x + 2, D - 14, 1, 0.5);
    put(solid(body), prism(P, front, rr, ri, H + 4, H + 7));
  }

  const ang = spring(REST);
  let last = NaN;
  const at = (x, a, t, off = 0) => P(x, -Math.sin(rad(a)) * t - Math.cos(rad(a)) * off, HZ + Math.cos(rad(a)) * t - Math.sin(rad(a)) * off);
  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = [];
    for (const x of [4, W - 4]) for (const t of [0, L]) for (const o of [0, 3]) pts.push(at(x, a, t, o));
    plate.setAttribute("d", poly(hull(pts)));
    // the pleated side: a fan from the hinge, folding in and out
    const n = 6, zig = [at(W - 6, 0, 0)];
    for (let i = 0; i <= n; i++) zig.push(at(W - 6, (a * i) / n, i % 2 ? L * 0.86 : L));
    fan.setAttribute("d", poly(zig));
    let folds = "";
    for (let i = 1; i < n; i++) folds += seg(at(8, (a * i) / n, i % 2 ? L * 0.86 : L), at(W - 6, (a * i) / n, i % 2 ? L * 0.86 : L)) + " ";
    side.setAttribute("d", folds);
  }
  draw(REST);

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function aim(sx) {
    const a = clamp(((sx - 90) / 220) * amax, 0, amax);
    ang.t = a;
    read.textContent = Math.round(a) + "°";
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, {
    move: ([sx]) => aim(sx),
    leave: () => { ang.t = REST; read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amax = v; }, destroy: bag.dispose };
}

hairline({
  name: "harmoniums",
  means: "A harmonium with a hinged bellows board on its back: the pointer's place across the figure swings the bellows open.",
  rules: [3, 5, 6, 8],
  range: [30, 50, 70],
  tour: [[89, 194], [170, 230], [237, 269], null],
  mount,
});

pianostool.code:
/**
 * Piano stool: a round cushioned seat on a threaded screw column over a
 * four-footed base. The pointer's height over the stage sets the seat's
 * height: the seat winds up or down the screw, turning as it goes, so the
 * buttons on its cushion swing round. At rest the seat sits mid-height,
 * its rim bright. The slider is how far the screw reaches.
 */
const { Cam, circ, clamp, fit, facing, prism, proj, ringAt, rings, spring, stepS, rad, disposer, mk, pointer, put, register, solid, flatDot, place, r2 } = HL;

const SR = 30, CR = 6, FOOT = 5, LO = 30, HI = 66, REST = 44, TURN = 9;
const disc = (r, n = 40) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value / 90;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[-46, -46, 0], [46, 46, 0], [46, -46, 0], [-46, 46, 0], [-SR, -SR, HI + 14], [SR, SR, HI + 14]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // four feet, painted far to near
  const feet = [[-34, 0], [0, -34], [34, 0], [0, 34]].sort((a, b) => a[0] + a[1] - b[0] - b[1]);
  const legs = mk("g", {}, g);
  for (const [fx, fy] of feet) {
    const [r, i] = rings(Math.min(fx, 0) - 4, Math.min(fy, 0) - 4, Math.max(fx, 0) + 4, Math.max(fy, 0) + 4, 4, 1.2);
    put(solid(legs), prism(P, front, r, i, 0, FOOT));
  }
  put(solid(g), prism(P, front, disc(11), disc(9.5), 0, FOOT + 4));
  const col = solid(g), threads = mk("path", { class: "nf lo" }, g);
  const seat = solid(g), dots = [0, 1, 2].map(() => flatDot(g, C, 1.6, "dot off"));
  seat.sil.classList.add("hi");

  const h = spring(REST);
  let last = NaN;
  function draw(z) {
    if (z === last) return;
    last = z;
    put(col, prism(P, front, disc(CR, 24), disc(CR - 1.2, 24), FOOT + 4, z));
    let d = "";
    for (let t = FOOT + 8; t < z - 2; t += 4) d += "M" + ringAt(P, disc(CR, 24), t).filter((_, k) => k >= 3 && k <= 15).map((p) => p.map(r2).join(",")).join("L");
    threads.setAttribute("d", d);
    put(seat, prism(P, front, disc(SR, 48), disc(SR - 2.2, 48), z, z + 12));
    const a = rad(z * TURN);
    dots.forEach((el, k) => { const b = a + (k * 2 * Math.PI) / 3; place(el, P(14 * Math.cos(b), 14 * Math.sin(b), z + 12)); });
  }

  const B = register(stage, (dt) => { const m = stepS(h, dt); draw(h.x); return m; });
  bag.add(B.unregister);

  function aim(t) {
    h.t = t;
    read.textContent = t === REST ? "rest" : "h " + Math.round(t);
    B.wake();
  }
  aim(REST);
  bag.add(pointer(stage, {
    move: ([, sy]) => { const u = clamp((250 - sy) / 170, 0, 1); aim(Math.round(lerpH(u))); },
    leave: () => aim(REST),
  }));
  function lerpH(u) { const lo = REST - (REST - LO) * reach, hi = REST + (HI - REST) * reach; return lo + (hi - lo) * u; }
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v / 90; }, destroy: bag.dispose };
}

hairline({
  name: "pianostool",
  means: "A piano stool on a screw column: the pointer's height winds the seat up or down, and the seat turns as it climbs.",
  rules: [3, 5, 8, 9],
  range: [0, 60, 90],
  tour: [[200, 80], [200, 166], [200, 230], null],
  mount,
});

cameraflash.code:
/**
 * Photo booth: a tall booth with a flash on its roof and a curtain hung on a
 * rail across its doorway. The pointer draws the curtain: its leading edge
 * follows the pointer along the rail, the folds bunching toward the far post
 * and showing the seat inside. At rest the curtain hangs half open and the
 * flash is the bright mark. The slider is how far open it rests.
 *
 * The pattern: one part following the pointer along a track (slide).
 */
const {
  Cam, clamp, fillet, fit, facing, lerp, open, poly, prism, proj, rings, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 40, D = 50, H = 92, Y0 = 6, Y1 = 44, CX = W + 1.5, CT = 2.6, CZ0 = 6, CZ1 = 84, MIN = 9;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let restOpen = value / 100;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[0, 0, 0], [W + 6, D, 0], [W + 6, 0, 0], [0, D, 0], [0, 0, H + 12], [W, D, H + 12]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [br, bi] = rings(0, 0, W, D, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, H));
  // the flash on the roof, with its window on the near face
  const flash = solid(g);
  const [fr, fi] = rings(12, 14, 28, 36, 3, 1.2);
  put(flash, prism(P, front, fr, fi, H, H + 10));
  mk("path", { d: poly(fillet([[28, 18, H + 3], [28, 32, H + 3], [28, 32, H + 8], [28, 18, H + 8]].map((q) => P(...q)), [1.5, 1.5, 1.5, 1.5])), class: "nf lo" }, g);
  // the doorway and the seat inside it, on the near face
  const door = [[W, Y0, 4], [W, Y1, 4], [W, Y1, CZ1], [W, Y0, CZ1]].map((q) => P(...q));
  mk("path", { d: poly(fillet(door, [1, 1, 5, 5])), class: "nf lo" }, g);
  mk("path", { d: open([[W, 12, 30], [W, 38, 30], [W, 38, 26], [W, 12, 26]].map((q) => P(...q))) + seg(P(W, 16, 26), P(W, 16, 4)) + seg(P(W, 34, 26), P(W, 34, 4)), class: "nf lo" }, g);
  // the rail
  mk("path", { d: seg(P(CX, Y0 - 3, CZ1 + 3), P(CX, Y1 + 3, CZ1 + 3)), class: "nf" }, g);

  const cur = solid(g), folds = mk("path", { class: "nf lo" }, g);
  const ring = mk("circle", { r: 2.2, class: "nf" }, g);
  const restEdge = () => lerp(Y0, Y1 - MIN, restOpen);
  const edge = spring(restEdge());
  let last = NaN;
  function draw(e) {
    if (Math.abs(e - last) < 0.01) return;
    last = e;
    const [r, i] = rings(CX - CT / 2, e, CX + CT / 2, Y1 + 1, 1.2, 0.5);
    put(cur, prism(P, front, r, i, CZ0, CZ1));
    let d = "";
    for (let k = 1; k < 5; k++) { const y = lerp(e, Y1 + 1, k / 5); d += seg(P(CX + CT / 2, y, CZ0 + 4), P(CX + CT / 2, y, CZ1 - 3)); }
    folds.setAttribute("d", d);
    const [x, y] = P(CX, e + 1.5, CZ1 + 3);
    ring.setAttribute("cx", x); ring.setAttribute("cy", y);
  }

  const B = register(stage, (dt) => { const m = stepS(edge, dt); draw(edge.x); return m; });
  bag.add(B.unregister);

  // hit against the rest pose: the rail's ends on screen, and the booth's box
  const a = P(CX, Y0, CZ1)[0], b = P(CX, Y1 - MIN, CZ1)[0];
  const top = P(0, 0, H + 10)[1], bot = P(W, D, 0)[1], left = P(0, D, 0)[0] - 10, right = P(W, 0, 0)[0] + 10;
  let act = null;
  function setActive(p) {
    const on = p && p[0] > left && p[0] < right && p[1] > top && p[1] < bot;
    const t = on ? clamp((p[0] - a) / (b - a), 0, 1) : restOpen;
    edge.t = lerp(Y0, Y1 - MIN, t);
    if (on !== act) { act = on; cur.sil.classList.toggle("hi", on); flash.sil.classList.toggle("hi", !on); }
    read.textContent = on ? "open " + Math.round(t * 100) : "rest";
    B.wake();
  }
  setActive(null);
  bag.add(pointer(stage, { move: (p) => setActive(p), leave: () => setActive(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { restOpen = v / 100; if (!act) setActive(null); }, destroy: bag.dispose };
}

hairline({
  name: "cameraflash",
  means: "A photo booth with a flash on its roof: the pointer draws its curtain along the rail, bunching the folds to show the seat.",
  rules: [1, 3, 5, 8],
  range: [0, 12, 100],
  tour: [[260, 151], [213, 216], [236, 183], null],
  mount,
});

printrollers.code:
/**
 * Ink rollers: three brayers resting on an inking slab, each a long roller
 * with a grip on its near end. The pointer picks a roller by where it
 * stands: it lifts off the slab, and the rollers beside it rise a little,
 * staggered from it. At rest the middle roller is raised, bright. The slider
 * is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 30, R = 10, L0 = 4, L1 = 56, G0 = 60, G1 = 76, GR = 4, LIFT = 24, FAV = 1, SZ = 5;
const X1 = (N - 1) * STEP + 2 * R + 8;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-6, -6, 0], [X1 + 6, G1 + 2, 0], [X1 + 6, -6, 0], [-6, G1 + 2, 0], [R, 30, SZ + 2 * R + LIFT], [X1 - R, 30, SZ + 2 * R + LIFT]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-6, -6, X1 + 6, L1 + 6, 6, 2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));
  // a rolled-out patch of ink on the slab
  mk("path", { d: poly([[6, 10], [X1 - 6, 10], [X1 - 6, L1 - 8], [6, L1 - 8]].map(([x, y]) => P(x, y, SZ))), class: "nf lo" }, g);

  const disc = (x, y, z, r, n = 24) => Array.from({ length: n }, (_, i) => { const t = (i / n) * 2 * Math.PI; return P(x + r * Math.cos(t), y, z + r * Math.sin(t)); });
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = R + 4 + k * STEP, grp = mk("g", {}, g);
    const body = mk("path", { class: "sil" }, grp), cap = mk("path", { class: "nf lo" }, grp);
    const stem = mk("path", { class: "nf" }, grp), grip = mk("path", {}, grp), end = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, body, cap, stem, grip, end, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const cz = SZ + R + lift;
    it.body.setAttribute("d", poly(hull(disc(it.x, L0, cz, R).concat(disc(it.x, L1, cz, R)))));
    it.cap.setAttribute("d", poly(disc(it.x, L1 - 1.5, cz, R - 1.5)));
    it.stem.setAttribute("d", seg(P(it.x, L1, cz), P(it.x, G0, cz)));
    it.grip.setAttribute("d", poly(hull(disc(it.x, G0, cz, GR, 16).concat(disc(it.x, G1, cz, GR, 16)))));
    it.end.setAttribute("d", open(disc(it.x, G1 - 1, cz, GR - 1, 16).concat([disc(it.x, G1 - 1, cz, GR - 1, 16)[0]])));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 30, SZ + R));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "roller " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "printrollers",
  means: "Three ink rollers on an inking slab: the roller under the pointer lifts off the ink, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[252,183],[165,140],[209,162], null],
  mount,
});

umbrellas.code:
/**
 * Umbrellas: a long stand holding four closed umbrellas, tip down, each a
 * folded canopy on a shaft with a crook handle. The pointer picks an umbrella
 * by where it stands: it lifts out of the stand, and its neighbours rise a
 * little, staggered from it. At rest one umbrella is half drawn, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 22, W = 26, H = 30, LIFT = 30, FAV = 2, CR = 7;
const X1 = (N - 1) * STEP + 26, LEN = [66, 72, 62, 70];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, 0], [X1, W, 0], [X1, 0, 0], [0, W, 0], [13, W / 2, 6 + 72 + LIFT + 8], [X1 - 13, W / 2, 6 + 72 + LIFT + 8]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(0, 0, X1, W, 8, 2);
  put(solid(g), prism(P, front, sr, si, 0, H));
  // the opening, seen from above, behind the umbrellas
  mk("path", { d: poly(ringAt(P, si, H)), class: "nf lo" }, g);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 13 + k * STEP, y = W / 2, grp = mk("g", {}, g);
    const canopy = mk("path", { class: "sil" }, grp), fold = mk("path", { class: "nf lo" }, grp);
    const shaft = mk("path", { class: "nf" }, grp), hook = mk("path", { class: "nf" }, grp);
    items.push({ k, x, y, len: LEN[k], grp, canopy, fold, shaft, hook, z: tween(k === FAV ? LIFT * 0.55 : 0), last: NaN });
  }
  // the stand's front wall, painted over the umbrellas' feet
  const fr = run(sr, front);
  const wall = ringAt(P, fr, H).concat(ringAt(P, fr, 0).reverse());
  mk("path", { d: poly(wall), class: "" }, g);
  mk("path", { d: open(ringAt(P, run(si, front), H)), class: "nf lo" }, g);
  mk("path", { d: open(ringAt(P, fr, H * 0.35)), class: "nf lo" }, g);

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = 4 + lift, L = it.len, pts = [];
    for (const [r, f] of [[0.6, 0], [CR, 0.28], [CR * 0.8, 0.5], [1.6, 0.8]]) pts.push(...ringAt(P, disc(it.x, it.y, r), z0 + 6 + f * (L - 18)));
    it.canopy.setAttribute("d", poly(hull(pts)));
    const a = P(it.x, it.y, z0), b = P(it.x, it.y, z0 + 6);
    // a seam where the folded panels wrap
    const s0 = P(it.x + CR * 0.3, it.y + CR * 0.3, z0 + 6 + 0.1 * (L - 18)), s1 = P(it.x + CR * 0.55, it.y + CR * 0.55, z0 + 6 + 0.32 * (L - 18)), s2 = P(it.x + 1, it.y + 1, z0 + 6 + 0.8 * (L - 18));
    it.fold.setAttribute("d", open([s0, s1, s2]));
    const t = P(it.x, it.y, z0 + 6 + 0.8 * (L - 18)), h = P(it.x, it.y, z0 + L);
    it.shaft.setAttribute("d", "M" + a.join(",") + "L" + b.join(",") + "M" + t.join(",") + "L" + h.join(","));
    // the crook: a J turning away along +x
    const J = [];
    for (let i = 0; i <= 10; i++) { const q = (i / 10) * Math.PI; J.push(P(it.x + 5 - 5 * Math.cos(q), it.y, z0 + L + 5 * Math.sin(q))); }
    J.push(P(it.x + 10, it.y, z0 + L - 3));
    it.hook.setAttribute("d", open(J));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, 40));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.55 : 0) : dd === 0 ? LIFT : dd === 1 ? 6 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.canopy.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "no. " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

