  name: "gloves",
  means: "Five mittens clipped along a boutique rack: the one under the pointer swings out on its clip, and its neighbours sway a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[126, 103], [201, 141], [277, 179], null],
  mount,
});

