marsrover3.code:
/**
 * Space probe: a boxy bus with two long solar wings and a big dish on a
 * mast. The dish swings round to aim at the pointer, tipped up toward deep
 * space. At rest it looks off to the far left, bright. The slider is how
 * high the dish tips.
 *
 * The pattern: one part turning to face the pointer (aim).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, seg, unproj, rad, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const REST = -150, ZD = 48, RD = 24, DEP = 8;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let tip = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-12, -66, 20], [12, 66, 20], [-26, 0, ZD + 26], [26, 0, ZD - 20], [0, 26, ZD + 26], [0, 0, 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  function wing(y0, y1) {
    const w = mk("g", {}, g), z = 22;
    mk("path", { d: poly([P(-11, y0, z), P(11, y0, z), P(11, y1, z), P(-11, y1, z)]), class: "sil" }, w);
    let d = seg(P(0, y0, z), P(0, y1, z));
    for (let i = 1; i < 4; i++) { const y = y0 + ((y1 - y0) * i) / 4; d += seg(P(-11, y, z), P(11, y, z)); }
    mk("path", { d, class: "lo nf" }, w);
    mk("path", { d: seg(P(0, Math.sign(y0) * 14, z), P(0, y0, z)), class: "nf" }, w);
  }
  wing(-20, -64);
  const [br, bi] = rings(-14, -14, 14, 14, 4, 1.6);
  put(solid(g), prism(P, front, br, bi, 6, 34));
  wing(20, 64);
  mk("path", { d: seg(P(0, 0, 34), P(0, 0, ZD - 4)), class: "sil nf" }, g);
  const feedB = mk("path", { class: "sil nf" }, g), dish = mk("path", { class: "sil hi" }, g);
  const rim = mk("path", { class: "lo nf" }, g), feedF = mk("path", { class: "sil nf" }, g);

  const sp = spring(REST);
  let last = NaN;
  function draw() {
    if (sp.x === last) return;
    last = sp.x;
    const ph = rad(sp.x), el = rad(20 + tip * 0.5);
    const ax = [Math.cos(ph) * Math.cos(el), Math.sin(ph) * Math.cos(el), Math.sin(el)];
    const u = [-Math.sin(ph), Math.cos(ph), 0];
    const w = [ax[1] * u[2] - ax[2] * u[1], ax[2] * u[0] - ax[0] * u[2], ax[0] * u[1] - ax[1] * u[0]];
    const at = (a, b, c) => P(a * u[0] + b * w[0] + c * ax[0], a * u[1] + b * w[1] + c * ax[1], ZD + a * u[2] + b * w[2] + c * ax[2]);
    const ring = [], pts = [];
    for (let i = 0; i < 40; i++) { const t = (i / 40) * 2 * Math.PI; ring.push(at(RD * Math.cos(t), RD * Math.sin(t), DEP)); }
    for (const [r, c] of [[RD * 0.7, DEP * 0.5], [RD * 0.35, DEP * 0.12]]) for (let i = 0; i < 24; i++) { const t = (i / 24) * 2 * Math.PI; pts.push(at(r * Math.cos(t), r * Math.sin(t), c)); }
    dish.setAttribute("d", poly(hull(ring.concat(pts, [at(0, 0, 0)]))));
    rim.setAttribute("d", poly(ring));
    const toward = ax[0] + ax[1] + ax[2] * 0.7 > 0;
    let f = "";
    for (let i = 0; i < 3; i++) { const t = (i / 3) * 2 * Math.PI; f += seg(at(RD * Math.cos(t), RD * Math.sin(t), DEP), at(0, 0, DEP + 18)); }
    f += seg(at(0, 0, DEP + 16), at(0, 0, DEP + 22));
    feedF.setAttribute("d", toward ? f : "");
    feedB.setAttribute("d", toward ? "" : f);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  draw();

  function aim(p) {
    if (!p) { sp.t = REST; read.textContent = "rest"; B.wake(); return; }
    const [x, y] = unproj(C, p[0], p[1], 20);
    let a = (Math.atan2(y, x) * 180) / Math.PI;
    while (a - sp.t > 180) a -= 360;
    while (a - sp.t < -180) a += 360;
    sp.t = a;
    read.textContent = "az " + (((Math.round(a) % 360) + 360) % 360);
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { tip = v; last = NaN; draw(); }, destroy: bag.dispose };
}

hairline({
  name: "marsrover3",
  means: "A deep-space probe with solar wings: its big dish swings round to aim at the pointer, tipped up toward the stars.",
  rules: [1, 3, 5, 8],
  range: [0, 40, 80],
  tour: [[340, 213], [60, 182], [200, 280], null],
  mount,
});

tabletennisrobot.code:
/**
 * Ball machine: a court ball machine on a wheeled base, a hopper of balls on
 * top and a launch barrel out of its front. The barrel turns to aim where the
 * pointer stands on the court, along the front arc, on a spring. At rest it
 * aims a little left of centre, bright. The slider is the barrel's tilt.
 *
 * The pattern: one part turning to face the pointer (officechairs).
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rad, rings, ringAt, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PZ = 30, R = 7, L0 = 10, L1 = 50, REST = 28;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let tilt = value;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[-30, -24, 0], [58, 58, PZ], [30, 24, 0], [-24, 30, 0], [0, 0, 62], [58, 0, PZ + 14], [0, 58, PZ + 14]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // wheels behind the base, then the base, body and hopper
  for (const [x, y] of [[-26, -18], [26, -18], [-26, 18], [26, 18]]) put(solid(g), prism(P, front, disc(x, y, 5, 16), disc(x, y, 3.5, 16), 0, 4));
  const [br, bi] = rings(-30, -22, 30, 22, 8, 2);
  put(solid(g), prism(P, front, br, bi, 4, 10));
  const [mr, mi] = rings(-20, -16, 20, 16, 7, 2);
  put(solid(g), prism(P, front, mr, mi, 10, 40));
  // hopper: wider at the top, with balls heaped in it
  const foot = rings(-14, -11, 14, 11, 5, 1.5)[0], [top, tin] = rings(-19, -15, 19, 15, 6, 2);
  const hs = solid(g);
  put(hs, { sil: poly(hull(ringAt(P, foot, 40).concat(ringAt(P, top, 56)))), crease: poly(ringAt(P, tin, 56)) });
  hs.cr.setAttribute("class", "nf lo");
  for (const [x, y] of [[-9, -6], [0, -7], [9, -5], [-5, 4], [5, 5]]) {
    const b = [];
    for (let i = 0; i <= 4; i++) { const t = (i / 4) * Math.PI; b.push(...ringAt(P, disc(x, y, 4 * Math.sin(t) + 0.3, 14), 53 + 4 * -Math.cos(t))); }
    mk("path", { d: poly(hull(b)), class: "nf lo" }, g);
  }
  // the barrel: a cylinder from the body's front, pivoting on its centre
  const barrel = mk("path", { class: "sil hi" }, g), mouth = mk("path", { class: "nf lo" }, g), ball = mk("circle", { r: 2.4, class: "dot" }, g);
  const yaw = spring(REST);
  let last = NaN, lastT = NaN;
  function draw(a) {
    if (a === last && tilt === lastT) return;
    last = a; lastT = tilt;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a)), tc = Math.cos(rad(tilt)), ts = Math.sin(rad(tilt));
    const ax = [c * tc, s * tc, ts], px = [-s, c, 0], up = [-c * ts, -s * ts, tc];
    const end = (l) => { const o = []; for (let i = 0; i < 24; i++) { const t = (i / 24) * 2 * Math.PI, k = Math.cos(t) * R, m = Math.sin(t) * R; o.push(P(ax[0] * l + px[0] * k + up[0] * m, ax[1] * l + px[1] * k + up[1] * m, PZ + ax[2] * l + up[2] * m)); } return o; };
    barrel.setAttribute("d", poly(hull(end(L0).concat(end(L1)))));
    mouth.setAttribute("d", poly(end(L1)));
    const m = P(ax[0] * L1, ax[1] * L1, PZ + ax[2] * L1);
    ball.setAttribute("cx", m[0]); ball.setAttribute("cy", m[1]);
  }
  const B = register(stage, (dt) => { const mv = stepS(yaw, dt); draw(yaw.x); return mv; });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { yaw.t = REST; read.textContent = "rest"; B.wake(); return; }
    const [x, y] = unproj(C, p[0], p[1], 0);
    const a = clamp((Math.atan2(y, x) * 180) / Math.PI, 0, 90);
    yaw.t = a;
    read.textContent = "aim " + Math.round(a - 45) + "°";
    B.wake();
  }
  read.textContent = "rest";
  draw(REST);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { tilt = v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "tabletennisrobot",
  means: "A court ball machine with a hopper of balls: its barrel turns to aim where the pointer stands on the court.",
  rules: [1, 3, 5, 8],
  range: [0, 12, 30],
  tour: [[310, 225], [205, 262], [95, 225], null],
  mount,
});

lightboard.code:
/**
 * Lightboard: an upright lightbox sign on a low foot, its face carrying three
 * rails of letter tiles set as words. The pointer picks the tile nearest it:
 * that tile slides out of its rail and up, and the tiles beside it in the same
 * word ease out a little, staggered from it. At rest one tile stands out,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many on a face plane.
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 144, D = 12, H = 94, TW = 13, TH = 18, TS = 16, OUT = 22, UP = 11;
const ROWS = [[64, [1, 2, 3, 4, 5]], [39, [0, 1, 2, 4, 5, 6, 7]], [14, [2, 3, 4, 5]]];
const FAV = 7;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.8);
  fit(C, [[-4, -4, 0], [W + 4, D + 8, 0], [W + 4, -4, 0], [-4, D + 8, 0], [0, 0, H + 4], [W, 0, H + 4], [W / 2, D + OUT + 3, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [fr, fi] = rings(-4, -4, W + 4, D + 8, 4, 1.6);
  put(solid(g), prism(P, front, fr, fi, 0, 4));
  const [br, bi] = rings(0, 0, W, D, 4, 2);
  put(solid(g), prism(P, front, br, bi, 4, H));
  // the lit face: an inset frame, and a rail under each row
  const fz = (x, z) => P(x, D, z);
  mk("path", { d: poly([fz(6, 10), fz(W - 6, 10), fz(W - 6, H - 6), fz(6, H - 6)]), class: "nf lo" }, g);
  for (const [z] of ROWS) mk("path", { d: open([fz(6, z - 1), fz(W - 6, z - 1)]), class: "nf lo" }, g);

  const layer = mk("g", {}, g), tiles = [];
  ROWS.forEach(([z, cols], r) => cols.forEach((c, k) => {
    const x = 10 + c * TS, s = solid(layer);
    s.sil.classList.add("sil");
    tiles.push({ r, k, x, z, s, o: tween(tiles.length === FAV ? 0.75 : 0), last: NaN });
  }));

  function draw(t, o) {
    if (o === t.last) return;
    t.last = o;
    const y = D + o * OUT, z = t.z + o * UP;
    const [a, b] = rings(t.x, y, t.x + TW, y + 2.6, 1, 0.6);
    put(t.s, prism(P, front, a, b, z, z + TH));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const t of tiles) { draw(t, tval(t.o, now)); if (!tdone(t.o, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = tiles.map((t) => P(t.x + TW / 2, D + 1, t.z + TH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, i) => { const dd = Math.hypot(m[0] - sx, m[1] - sy); if (dd < bd) { bd = dd; best = i; } });
    return bd < 16 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const on = a < 0 ? FAV : a, A = tiles[on];
    tiles.forEach((t, i) => {
      const dd = t.r === A.r ? Math.abs(t.k - A.k) : 9;
      const o = a < 0 ? (i === FAV ? 0.75 : 0) : dd === 0 ? 1 : dd === 1 ? 0.62 : dd === 2 ? 0.4 : dd === 3 ? 0.2 : 0;
      tset(t.o, o, now, from < 0 ? 0 : Math.min(dd, 6) * stag);
      t.s.sil.classList.toggle("hi", i === on);
    });
    layer.appendChild(A.s.g);
    read.textContent = a < 0 ? "rest" : "r" + (A.r + 1) + "·" + (A.k + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "lightboard",
  means: "A lightbox sign with words of tiles on rails: the tile under the pointer slides out and up, its neighbours ease out.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[189, 127], [141, 183], [261, 202], null],
  mount,
});

tapereels.code:
/**
 * Tapereels: a reel-to-reel tape deck lying on its back, two big reels on
 * their spindles and a head block between them at the front. The pointer
 * picks a reel: it lifts off its spindle and turns a part of a revolution as
 * it rises, and the other settles. At rest one reel is raised, bright. The
 * slider is how far a lifted reel turns.
 *
 * The pattern: one of a few, picked by nearest rest centre.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const DW = 150, DD = 84, DZ = 12, R = 30, RT = 5, LIFT = 24, FAV = 0;
const REELS = [[40, 38], [110, 38]];
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let turn = value;
  const C = Cam(45, 0.5, 1.7);
  fit(C, [[0, 0, 0], [DW, DD, 0], [DW, 0, 0], [0, DD, 0], [40, 38, DZ + LIFT + RT + 4], [110, 38, DZ + LIFT + RT + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [dr, di] = rings(0, 0, DW, DD, 6, 2);
  put(solid(g), prism(P, front, dr, di, 0, DZ));
  // spindles: a short post on the deck under each reel
  for (const [x, y] of REELS) put(solid(g), prism(P, front, disc(x, y, 3, 16), disc(x, y, 2, 16), DZ, DZ + RT + 3));

  const reels = REELS.map(([x, y], k) => {
    const grp = mk("g", {}, g), s = solid(grp);
    s.sil.classList.add("sil");
    const hub = mk("path", { class: "nf lo" }, grp), holes = [0, 1, 2].map(() => mk("path", { class: "nf lo" }, grp));
    return { k, x, y, s, hub, holes, o: tween(k === FAV ? 0.7 : 0), last: NaN };
  });
  // the head block between the reels, at the front edge
  const [hr, hi] = rings(62, 64, 88, 76, 3, 1.2);
  put(solid(g), prism(P, front, hr, hi, DZ, DZ + 10));

  function draw(it, o) {
    const key = o + turn * 1e-3;
    if (key === it.last) return;
    it.last = key;
    const z = DZ + 1 + o * LIFT, top = z + RT, a0 = (o * turn * Math.PI) / 180;
    put(it.s, prism(P, front, disc(it.x, it.y, R), disc(it.x, it.y, R - 2), z, top));
    it.hub.setAttribute("d", poly(ringAt(P, disc(it.x, it.y, 7, 24), top)));
    it.holes.forEach((h, i) => {
      const a = a0 + (i * 2 * Math.PI) / 3, cx = it.x + 17 * Math.cos(a), cy = it.y + 17 * Math.sin(a);
      h.setAttribute("d", poly(ringAt(P, disc(cx, cy, 6.5, 24), top)));
    });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of reels) { draw(it, tval(it.o, now)); if (!tdone(it.o, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = reels.map((it) => P(it.x, it.y, DZ + RT));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, (m[1] - sy) * 1.6); if (dd < bd) { bd = dd; best = k; } });
    return bd < 56 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    const on = a < 0 ? FAV : a;
    reels.forEach((it, k) => {
      tset(it.o, a < 0 ? (k === FAV ? 0.7 : 0) : k === a ? 1 : 0, now, 0);
      it.s.sil.classList.toggle("hi", k === on);
    });
    read.textContent = a < 0 ? "rest" : a === 0 ? "supply" : "take-up";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { turn = v; for (const it of reels) it.last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "tapereels",
  means: "A reel-to-reel tape deck: the reel under the pointer lifts off its spindle, turning as it rises.",
  rules: [1, 5, 6, 8],
  range: [0, 60, 120],
  tour: [[163, 126], [247, 168], [165, 140], null],
  mount,
});

gutter.code:
/**
 * Rain gutter: a house wall under a roof edge, a gutter trough along the
 * eave and a downpipe at one end. The downpipe's hinged foot swings out as
 * the pointer moves to the right, from hanging straight down to lying out
 * over the ground. At rest the gutter is bright and the foot half out.
 *
 * The pattern: one part following a continuous input (spring).
 */
const {
  Cam, fit, facing, prism, proj, rings, clamp, spring, stepS, hull, poly, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const HX = 93, HY = 35, HZ = 31, L = 28, REST = 12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-12, -12, 0], [112, 70, 0], [112, -12, 0], [-12, 70, 0], [50, 12, 64]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1, cls) => {
    const [o, i] = rings(x0, y0, x1, y1, r, b), s = solid(g);
    put(s, prism(P, front, o, i, z0, z1));
    if (cls) s.sil.classList.add(cls);
    return s;
  };
  box(-12, -12, 112, 70, 6, 2, -3, 0);
  box(0, 0, 100, 24, 2, 1.2, 0, 56);
  box(-4, -4, 104, 30, 2, 1, 56, 62);
  const gut = box(-2, 30, 102, 38, 2.5, 1.6, 50, 57);
  box(HX - 4, HY - 4, HX + 4, HY + 4, 3, 1.2, HZ, 50);
  const foot = mk("path", { class: "sil" }, g), lip = mk("path", { class: "nf lo" }, g);

  let last = NaN;
  function draw(a) {
    if (Math.abs(a - last) < 0.05) return;
    last = a;
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    const pts = [];
    const ends = [[HY, HZ], [HY + L * s, HZ - L * c]];
    for (const [y, z] of ends) for (const dx of [-4, 4]) for (const dn of [-4, 4]) pts.push(P(HX + dx, y + dn * c, z + dn * s));
    foot.setAttribute("d", poly(hull(pts)));
    const [ey, ez] = ends[1];
    lip.setAttribute("d", a < 40 ? "" : poly([[-4, -4], [4, -4], [4, 4], [-4, 4]].map(([dx, dn]) => P(HX + dx, ey + dn * c, ez + dn * s))));
  }

  const ang = spring(REST);
  draw(REST);
  let on = false;
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); show(); return m; });
  bag.add(B.unregister);
  function show() { read.textContent = on ? "out " + Math.round(ang.x) + "°" : "rest"; }
  function mark(a) { gut.sil.classList.toggle("hi", !a); foot.classList.toggle("hi", a); }
  mark(false); show();
  bag.add(pointer(stage, {
    move: ([sx]) => { on = true; mark(true); ang.t = clamp((sx - 90) / 140, 0, 1) * 90 * reach; B.wake(); },
    leave: () => { on = false; mark(false); ang.t = REST; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "gutter",
  means: "A rain gutter on a house eave: move the pointer right and the downpipe's hinged foot swings out over the ground.",
  rules: [3, 4, 5, 8],
  range: [0.4, 1, 1],
  tour: [[212, 199], [120, 200], [226, 252], null],
  mount,
