compass.code:
/**
 * Compass: a round hiking compass lying on a base plate, a dial of four dim
 * dots round its rim and a long needle on a pivot. The needle turns to face
 * the pointer and the read-out gives its bearing. At rest the needle points
 * a little off north and the case is bright.
 *
 * The pattern: one part turning to face the pointer (spring).
 */
const {
  Cam, fit, facing, prism, proj, rings, circ, unproj, spring, stepS, poly, rad,
  disposer, mk, pointer, put, register, solid, flatDot, place,
} = HL;

const R = 40, Z = 9, NL = 33, NW = 7, REST = -30;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let snap = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-R - 10, -R - 10, 0], [R + 10, R + 10, 0], [R + 10, -R - 10, 0], [-R - 10, R + 10, 0], [0, 0, Z + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-R - 10, -R - 10, R + 10, R + 10, 10, 2);
  put(solid(g), prism(P, front, pr, pi, -3, 0));
  const cs = solid(g);
  put(cs, prism(P, front, circ(R, 48), circ(R - 4, 48), 0, Z - 1));
  mk("path", { d: poly(circ(R - 9, 48).map((q) => P(q.u, q.v, Z - 1))), class: "nf lo" }, g);
  for (let k = 0; k < 4; k++) { const t = rad(k * 90); place(flatDot(g, C, k === 2 ? 1.8 : 1.3, k === 2 ? "dot m" : "dot off"), P((R - 6) * Math.cos(t), (R - 6) * Math.sin(t), Z - 1)); }
  const south = mk("path", { class: "lo" }, g), north = mk("path", { class: "sil" }, g);
  const pivot = mk("path", { d: poly(circ(2.6, 16).map((q) => P(q.u, q.v, Z + 1.5))) }, g);

  let last = NaN;
  function draw(a) {
    if (Math.abs(a - last) < 0.05) return;
    last = a;
    const t = rad(a), dx = Math.cos(t), dy = Math.sin(t), nx = -dy, ny = dx;
    const at = (l, w) => P(l * dx + w * nx, l * dy + w * ny, Z);
    north.setAttribute("d", poly([at(0, -NW), at(NL, 0), at(0, NW)]));
    south.setAttribute("d", poly([at(0, -NW), at(-NL * 0.8, 0), at(0, NW)]));
  }
  // north on the dial is -x (the far left corner); angles are measured in the ground plane
  const ang = spring(REST - 180);
  draw(ang.x);
  let on = false;
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); show(); return m; });
  bag.add(B.unregister);
  function show() {
    const b = (((ang.x + 180) % 360) + 360) % 360;
    read.textContent = on ? String(Math.round(b)).padStart(3, "0") + "°" : "rest";
  }
  function mark(a) { cs.sil.classList.toggle("hi", !a); north.classList.toggle("hi", a); }
  function aim(target) {
    let d = ((target - ang.t) % 360 + 540) % 360 - 180;
    ang.t += d; B.wake();
  }
  mark(false); show();
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      on = true; mark(true);
      const [x, y] = unproj(C, sx, sy, Z);
      let a = Math.atan2(y, x) * 180 / Math.PI;
      if (snap > 0) a = Math.round(a / snap) * snap;
      aim(a);
    },
    leave: () => { on = false; mark(false); aim(REST - 180); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { snap = v; }, destroy: bag.dispose };
}

hairline({
  name: "compass",
  means: "A hiking compass on a plate: its needle turns on the pivot to face the pointer, and the read-out gives the bearing.",
  rules: [1, 4, 5, 8],
  range: [0, 0, 45],
  tour: [[249, 172], [200, 247], [200, 85], null],
  mount,
});

stackchairs.code:
/**
 * Stacking chairs: five classroom chairs nested in a stack, each a seat on
 * four splayed legs with a backrest panel, each sitting a little forward of
 * the one under it. The pointer picks a chair by its height in the stack:
 * every chair above it lifts off together, staggered from it, and the chosen
 * chair's seat lies open. At rest the stack is a little uneven and the top
 * chair is bright. The slider is how high the chairs lift.
 *
 * The pattern: stepped parts; the hit is the nearest rest seat by screen y,
 * read from the rest pose so a lifted chair never moves its own hit.
 */
const {
  Cam, clamp, fit, proj, rings, prism, seg, tdone, tset, tval, tween, facing,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, W = 24, D = 22, Z0 = 17, DZ = 5, DY = 2, BACK = 16, SPL = 1.6;
const OFF = [0, 1.2, -0.6, 0.9, -0.2], REST = [0, 0, 0, 0, 1.5], FAV = N - 1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 3.45);
  const zTop = Z0 + (N - 1) * DZ;
  fit(C, [[-3, -3, 0], [W + 4, -3, 0], [W + 4, D + N * DY + 3, 0], [-3, D + N * DY + 3, 0],
    [0, (N - 1) * DY, zTop + BACK + 26], [W, (N - 1) * DY, zTop + BACK + 26]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const chairs = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    const backLegs = mk("path", { class: "nf" }, grp);
    const rest = solid(grp), seat = solid(grp);
    const frontLegs = mk("path", { class: "nf" }, grp);
    chairs.push({ k, x0: OFF[k], y0: k * DY, z0: Z0 + k * DZ, backLegs, rest, seat, frontLegs, z: tween(REST[k]), last: NaN });
  }

  function draw(c, up) {
    if (up === c.last) return;
    c.last = up;
    const { x0, y0 } = c, z = c.z0 + up, x1 = x0 + W, y1 = y0 + D;
    const leg = (x, y, sx, sy) => seg(P(x, y, z - 1.6), P(x + sx * SPL, y + sy * SPL, z - Z0));
    c.backLegs.setAttribute("d", leg(x0 + 1, y0 + 1, -1, -1) + leg(x1 - 1, y0 + 1, 1, -1) + leg(x0 + 1, y1 - 1, -1, 1));
    c.frontLegs.setAttribute("d", leg(x1 - 1, y1 - 1, 1, 1));
    // the backrest: a thin panel on two posts at the back edge
    const [br, bi] = rings(x0 + 1.5, y0 - 0.4, x1 - 1.5, y0 + 1.2, 0.7, 0.3);
    const bp = prism(P, front, br, bi, z + 6, z + BACK);
    bp.crease += seg(P(x0 + 3, y0 + 0.4, z), P(x0 + 3, y0 + 0.4, z + 6)) + seg(P(x1 - 3, y0 + 0.4, z), P(x1 - 3, y0 + 0.4, z + 6));
    put(c.rest, bp);
    const [sr, si] = rings(x0, y0, x1, y1, 3, 1);
    put(c.seat, prism(P, front, sr, si, z - 1.6, z));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    chairs.forEach((c) => { draw(c, tval(c.z, now)); if (!tdone(c.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest rest seat by screen y, inside the stack's span on screen
  const cyk = chairs.map((c) => P(c.x0 + W / 2, c.y0 + D / 2, c.z0)[1]);
  const xs = [P(-2, D + N * DY, 0)[0], P(W + 2, 0, 0)[0]];
  const yTop = P(W / 2, (N - 1) * DY, zTop + BACK)[1], yBot = P(W, D, 0)[1];
  function hit([sx, sy]) {
    if (sx < xs[0] || sx > xs[1] || sy < yTop || sy > yBot) return -1;
    let best = 0;
    cyk.forEach((y, k) => { if (Math.abs(sy - y) < Math.abs(sy - cyk[best])) best = k; });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const L = clamp(lift, 8, 26);
    chairs.forEach((c, k) => {
      const up = a < 0 ? REST[k] : k > a ? L : k === a && a === N - 1 ? L * 0.6 : 0;
      tset(c.z, up, now, from < 0 ? 0 : Math.abs(k - from) * 45);
      c.seat.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "chair " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = v; if (act >= 0) { const a = act; act = -2; setActive(a); } }, destroy: bag.dispose };
}

hairline({
  name: "stackchairs",
  means: "A stack of classroom chairs: the chairs above the one under the pointer lift off together, opening its seat.",
  rules: [1, 2, 3, 5],
  range: [8, 18, 26],
  tour: [[209, 214], [207, 192], [205, 165], null],
  mount,
});

parcellockers.code:
/**
 * Parcel lockers: a pickup wall of hinged doors in three sizes, four
 * columns of small, medium and large bays. The pointer picks a bay on the
 * wall's face: its door swings wide on the left hinge and shows the parcel
 * waiting inside, and the doors around it come ajar a little, staggered
 * from it. At rest one door stands half open, bright, and two others sit
 * unevenly ajar. The slider is the stagger.
 *
 * Hit read on the wall's face plane (y = D), which never moves; tweens per door.
 */
const {
  Cam, clamp, facing, fillet, fit, hull, poly, prism, proj, rad, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NC = 4, CW = 24, M = 5, BASE = 7, D = 14, IN = 1, T = 0.9;
const ROWS = [20, 14, 10, 10];                       // bottom to top: large, medium, small, small
const ZB = ROWS.reduce((a, h) => a.concat(a[a.length - 1] + h), [BASE]);
const NR = ROWS.length, W = 2 * M + NC * CW, H = ZB[NR] + M;
const FAV = [2, 1], OPEN = 105;
const REST = (c, r) => (c === FAV[0] && r === FAV[1] ? 58 : c === 0 && r === 2 ? 9 : c === 3 && r === 0 ? 5 : 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D + 24, BASE], [0, 0, H], [W, 0, H], [0, D + 14, H - M]], 200, 166);
  const P = proj(C), front = facing(C);
  const onFace = (y) => (q) => P(q.u, y, q.v);

  const g = mk("g", {}, svg);
  const [wr, wi] = rings(0, 0, W, D, 3, 1.4);
  put(solid(g), prism(P, front, wr, wi, 0, H));
  mk("path", { d: seg(P(1.5, D, BASE - 3), P(W - 1.5, D, BASE - 3)), class: "nf lo" }, g);

  const bays = [];
  for (let c = 0; c < NC; c++) for (let r = 0; r < NR; r++) {
    const x0 = M + c * CW + IN, x1 = M + (c + 1) * CW - IN, z0 = ZB[r] + IN, z1 = ZB[r + 1] - IN;
    // the bay's mouth and the parcel's face inside it, painted before any door swings over them
    mk("path", { d: poly(rrect(x0, z0, x1, z1, 0.8, 2).map(onFace(D))), class: "nf lo" }, g);
    const pw = Math.min(x1 - x0 - 5, (z1 - z0) * 1.6), pz = Math.min(z1 - z0 - 2.5, 12), px = x0 + 2.5;
    mk("path", { d: poly(rrect(px, z0 + 0.6, px + pw, z0 + 0.6 + pz, 0.6, 2).map(onFace(D))) +
      seg(P(px + pw / 2, D, z0 + 0.6 + pz), P(px + pw / 2, D, z0 + 0.6 + pz * 0.55)), class: "nf lo" }, g);
    bays.push({ c, r, x0, x1, z0, z1, rest: REST(c, r) });
  }
  // column by column from the left, bottom to top: an open door only ever falls over bays drawn before it
  for (const b of bays) {
    b.door = mk("path", { class: "sil" }, g);
    b.edge = mk("path", { class: "nf lo" }, g);
    b.s = tween(b.rest);
    b.last = NaN;
  }

  function draw(b, deg) {
    const a = rad(deg), w = b.x1 - b.x0, dx = Math.cos(a), dy = Math.sin(a);
    const fx = b.x0 + w * dx, fy = D + w * dy, nx = -dy * T, ny = dx * T;
    const pts = [];
    for (const z of [b.z0, b.z1]) {
      pts.push(P(b.x0, D, z), P(fx, fy, z), P(b.x0 + nx, D + ny, z), P(fx + nx, fy + ny, z));
    }
    const h = hull(pts);
    b.door.setAttribute("d", poly(fillet(h, h.map(() => 1), 2)));
    // the thickness line and the pull, near the free edge
    const ix = fx - 2.4 * dx + nx, iy = fy - 2.4 * dy + ny, zm = (b.z0 + b.z1) / 2;
    b.edge.setAttribute("d", seg(P(fx + nx, fy + ny, b.z0 + 0.8), P(fx + nx, fy + ny, b.z1 - 0.8)) +
      seg(P(ix, iy, zm - 2), P(ix, iy, zm + 2)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of bays) {
      const s = tval(b.s, now);
      if (s !== b.last) { draw(b, s); b.last = s; }
      if (!tdone(b.s, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  /** The bay under the point, read on the wall's face plane (y = D), which never moves. */
  function hit([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + D * s) / c, Y = x * s + D * c, z = (Y * C.k - (sy - C.oy) / C.S) / zf;
    if (x < M || x > W - M || z < BASE || z > ZB[NR]) return -1;
    let r = 0;
    while (r < NR - 1 && z > ZB[r + 1]) r++;
    return clamp(Math.floor((x - M) / CW), 0, NC - 1) * NR + r;
  }

  let act = -2;
  const favI = FAV[0] * NR + FAV[1];
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const ac = a >= 0 ? bays[a] : null, fc = from >= 0 ? bays[from] : null;
    bays.forEach((b, i) => {
      const dist = ac ? Math.abs(b.c - ac.c) + Math.abs(b.r - ac.r) : 0;
      const s = a < 0 ? b.rest : dist === 0 ? OPEN : dist === 1 ? 12 : dist === 2 ? 4 : 0;
      tset(b.s, s, now, fc ? (Math.abs(b.c - fc.c) + Math.abs(b.r - fc.r)) * stag : 0);
      b.door.classList.toggle("hi", i === (a < 0 ? favI : a));
    });
    read.textContent = a < 0 ? "rest" : `bay ${ac.c + 1}·${ac.r + 1}`;
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "parcellockers",
  means: "A pickup wall of parcel lockers in three sizes: the door under the pointer swings wide to show its parcel, and nearby doors come ajar.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[150, 97], [189, 160], [267, 233], null],
  mount,
});

parcelscale.code:
/**
 * Parcel scale: a low platform scale with a box on its platter and a round
 * dial on a post behind it. The pointer presses on the parcel: the closer
 * to its middle, the deeper the platter sinks into the base and the further
 * the dial's needle swings. At rest the parcel sits a touch proud and the
 * dial is the bright mark; a press hands the bright to the parcel. The
 * slider is how soft the platter is.
 *
 * Hit read on the parcel's rest top (z = TOP), which never moves; one spring.
 */
const {
  Cam, circ, clamp, facing, fit, lerp, poly, prism, proj, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BX0 = -4, BX1 = 64, BY0 = -14, BY1 = 46, BZ = 6, PZ = 3;
const PX0 = 14, PX1 = 44, PY0 = 8, PY1 = 34, PH = 20, TOP = BZ + PZ + PH;
const POST = [27, -11, 33, -7], DR = 10, DZ = 46;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let soft = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[BX0, BY0, 0], [BX1, BY1, 0], [BX1, BY0, 0], [BX0, BY1, 0], [30, -9, DZ + DR], [PX0, PY0, TOP]], 200, 166);
  const P = proj(C), front = facing(C);

  const g = mk("g", {}, svg);
  const [br, bi] = rings(BX0, BY0, BX1, BY1, 6, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  // the post and the dial, behind the platter
  const [pr, pi] = rings(...POST, 2, 0.6);
  put(solid(g), prism(P, front, pr, pi, BZ, DZ - DR + 1));
  const ring = circ(DR, 28), face = circ(DR - 1.6, 28);
  const dial = mk("path", { d: poly(ring.map((q) => P(30 + q.u, -7, DZ + q.v))), class: "sil" }, g);
  mk("path", { d: poly(face.map((q) => P(30 + q.u, -6.6, DZ + q.v))), class: "nf lo" }, g);
  let ticks = "";
  for (let i = 0; i <= 8; i++) {
    const a = Math.PI * (1.15 - i * 0.1625), c = Math.cos(a), s = Math.sin(a);
    ticks += seg(P(30 + c * (DR - 2.4), -6.6, DZ + s * (DR - 2.4)), P(30 + c * (DR - 3.8), -6.6, DZ + s * (DR - 3.8)));
  }
  mk("path", { d: ticks, class: "nf lo" }, g);
  const needle = mk("path", { class: "nf" }, g);
  const hub = mk("circle", { r: 1.3, class: "dot" }, g);
  const hp = P(30, -6.6, DZ);
  hub.setAttribute("cx", hp[0]); hub.setAttribute("cy", hp[1]);

  // the platter and the parcel ride together
  const [lr, li] = rings(0, 0, 60, 42, 4, 1.2);
  const plat = solid(g);
  const [cr, ci] = rings(PX0, PY0, PX1, PY1, 1.6, 1.4);
  const box = solid(g);
  const tape = mk("path", { class: "nf lo" }, g);

  const sp = spring(0.3);
  let last = NaN;
  function draw(s) {
    const z0 = BZ - s;
    put(plat, prism(P, front, lr, li, z0, z0 + PZ));
    put(box, prism(P, front, cr, ci, z0 + PZ, z0 + PZ + PH));
    const t = z0 + PZ + PH, xm = (PX0 + PX1) / 2;
    tape.setAttribute("d", seg(P(xm, PY0 + 1.4, t), P(xm, PY1, t)) + seg(P(xm, PY1, t), P(xm, PY1, t - 6)));
    const a = Math.PI * (1.0 - s * 0.16), c = Math.cos(a), si = Math.sin(a);
    needle.setAttribute("d", seg(P(30, -6.4, DZ), P(30 + c * (DR - 2.6), -6.4, DZ + si * (DR - 2.6))));
    read.textContent = s < 0.32 ? "rest" : `${(1.2 + s * 0.9).toFixed(1)}kg`;
  }

  const B = register(stage, (dt) => {
    const moving = stepS(sp, dt);
    if (sp.x !== last) { draw(sp.x); last = sp.x; }
    return moving;
  });
  bag.add(B.unregister);

  function press(on) {
    dial.classList.toggle("hi", !on);
    box.sil.classList.toggle("hi", on);
  }
  /** The press, read on the parcel's rest top, which never moves. */
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TOP);
    const d = Math.hypot((x - 29) / 15, (y - 21) / 13) / 1.42;
    const on = x > PX0 && x < PX1 && y > PY0 && y < PY1;
    const deep = lerp(2, 5, soft / 100);
    sp.t = on ? 0.3 + deep * clamp(1.1 - d, 0.3, 1) : 0.3;
    press(on);
    B.wake();
  }
  function leave() { sp.t = 0.3; press(false); B.wake(); }
  press(false);
  draw(sp.x); last = sp.x;
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { soft = v; }, destroy: bag.dispose };
}

hairline({
  name: "parcelscale",
  means: "A platform scale weighing a parcel: press on the box and the platter sinks while the dial's needle swings round.",
  rules: [1, 3, 4, 8],
  range: [0, 50, 100],
  tour: [[185, 127], [189, 150], [193, 172], null],
  mount,
});

sandwichboard.code:
/**
 * Sandwich board: an A-frame sidewalk sign, two framed boards hinged along
 * the top, standing on a kerb slab. Where the pointer stands on the ground
 * sets how wide the legs spread: toward the near side the A opens, toward
 * the far side it folds nearly shut. The board on the pointer's side is
 * bright. At rest it stands half open, the front board bright.
 *
 * The pattern: a continuous input on the ground plane (terrain).
 */
const {
  Cam, clamp, fillet, fit, facing, poly, prism, proj, rings, spring, stepS, unproj, open,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = 0, X1 = 64, L = 76, REST = 0.36, MIN = 0.08, MAX = 0.62, SZ = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gain = value / 100;
  const C = Cam(45, 0.5, 2.0);
  const sMax = L * Math.sin(MAX);
  fit(C, [[-10, -sMax - 8, 0], [X1 + 10, sMax + 8, 0], [X1 + 10, -sMax - 8, 0], [-10, sMax + 8, 0], [X0, 0, SZ + L], [X1, 0, SZ + L]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-10, -sMax - 8, X1 + 10, sMax + 8, 6, 2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));

  const mkBoard = () => ({ sil: mk("path", { class: "sil" }, g), edge: mk("path", { class: "nf lo" }, g), pane: mk("path", { class: "nf lo" }, g) });
  const back = mkBoard(), fore = mkBoard();
  const ang = spring(REST);
  let last = NaN;

  function board(b, sgn, a) {
    const s = L * Math.sin(a), h = L * Math.cos(a);
    const pt = (x, t) => P(x, sgn * s * t, SZ + h * (1 - t));
    b.sil.setAttribute("d", poly(fillet([pt(X0, 0), pt(X1, 0), pt(X1, 1), pt(X0, 1)], [2, 2, 2, 2])));
    const th = (x, t) => P(x, sgn * (s * t + 2), SZ + h * (1 - t));
    b.edge.setAttribute("d", open([th(X0, 0.04), th(X0, 1)]) + open([th(X0, 1), th(X1, 1)]));
    b.pane.setAttribute("d", poly(fillet([pt(X0 + 7, 0.12), pt(X1 - 7, 0.12), pt(X1 - 7, 0.86), pt(X0 + 7, 0.86)], [1.5, 1.5, 1.5, 1.5])));
  }
  function draw(a) {
    if (a === last) return;
    last = a;
    board(back, -1, a);
    board(fore, 1, a);
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function setSide(side) {
    back.sil.classList.toggle("hi", side < 0);
    fore.sil.classList.toggle("hi", side >= 0);
  }
  setSide(1);
  read.textContent = "rest";
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const [, y] = unproj(C, sx, sy, 0);
      const t = clamp(y / (sMax + 8), -1, 1);
      ang.t = clamp(REST + t * (MAX - MIN) * 0.5 * (0.4 + gain), MIN, MAX);
      setSide(t < 0 ? -1 : 1);
      read.textContent = Math.round((ang.t * 2 * 180) / Math.PI) + "°";
      B.wake();
    },
    leave: () => { ang.t = REST; setSide(1); read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { gain = v / 100; }, destroy: bag.dispose };
}

hairline({
  name: "sandwichboard",
  means: "An A-frame sidewalk sign: where the pointer stands on the ground opens its legs wide or folds them shut.",
  rules: [1, 3, 5, 8],
  range: [0, 60, 100],
  tour: [[257, 184], [143, 241], [132, 246], null],
  mount,
});

luggagescale.code:
/**
 * Bag drop scale: a check-in belt with its weighing plate, a post behind it
 * with a gauge, and a suitcase on the belt. The pointer slides the suitcase
 * along the belt: the more of it stands on the plate, the lower the plate
 * sits and the higher the gauge reads. At rest the suitcase stands half on
 * the plate, bright. The slider is the plate's give.
 *
 * The pattern: one continuous input (a spring), the hit on the fixed plane of
 * the belt's top, which never moves.
 */
const {
  Cam, clamp, facing, fit, open, poly, prism, proj, rings, rrect, stepS, spring, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const TOP = 6, BL = 30, BW = [6, 24], BH = 22, XMIN = -34, XMAX = 6, REST = -12, PX = [34, 46], PY = [-12, -3], PZ = 48;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let give = value;
  const C = Cam(45, 0.5, 2.8);
  fit(C, [[-42, -2, 0], [42, -2, 0], [42, 32, 0], [-42, 32, 0], [PX[0], PY[0], PZ], [XMIN, BW[0], TOP + BH + 3]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const post = solid(g);
  { const [r, i] = rings(PX[0], PY[0], PX[1], PY[1], 3, 1); put(post, prism(P, front, r, i, 0, PZ)); }
  const face = (x0, z0, x1, z1, r) => poly(rrect(x0, z0, x1, z1, r, 4).map((s) => P(s.u, PY[1], s.v)));
  mk("path", { class: "nf lo", d: face(PX[0] + 2.5, 26, PX[1] - 2.5, 44, 1.5) }, post.g);
  const gauge = mk("path", { class: "nf lo" }, post.g);

  const apron = solid(g);
  { const [r, i] = rings(-42, -2, -1, 32, 3, 1.2); put(apron, prism(P, front, r, i, 0, TOP)); }
  mk("path", { class: "nf lo", d: [8, 16, 24].map((y) => open([P(-40, y, TOP), P(-3, y, TOP)])).join("") }, apron.g);
  const plate = solid(g);
  const [pr, pi] = rings(1, -2, 42, 32, 3, 1.2);

  const suit = solid(g), handle = solid(g);
  const x = spring(REST);
  let last = NaN;

  function draw(bx) {
    if (bx === last) return;
    last = bx;
    const f = clamp((bx + BL - 1) / BL, 0, 1), sink = f * give;
    put(plate, prism(P, front, pr, pi, 0, TOP - sink));
    const z0 = TOP - (bx > 1 ? sink : 0);
    const [r, i] = rings(bx, BW[0], bx + BL, BW[1], 4, 1.4);
    put(suit, prism(P, front, r, i, z0, z0 + BH));
    const [hr, hi] = rings(bx + BL / 2 - 5, 13, bx + BL / 2 + 5, 17, 1.6, 0.6);
    put(handle, prism(P, front, hr, hi, z0 + BH, z0 + BH + 2.6));
    const xm = (PX[0] + PX[1]) / 2;
    gauge.setAttribute("d", open([P(xm, PY[1], 28), P(xm, PY[1], 28 + 14 * f)]));
    read.textContent = active ? "kg " + Math.round(23 * f) : "rest";
  }

  let active = false;
  const B = register(stage, (dt) => { const m = stepS(x, dt); draw(x.x); return m; });
  bag.add(B.unregister);

  // the hit: the pointer on the belt's top plane, which never moves
  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, TOP);
    const on = wx > -46 && wx < 46 && wy > -8 && wy < 38;
    active = on;
    x.t = on ? clamp(wx - BL / 2, XMIN, XMAX) : REST;
    suit.sil.classList.toggle("hi", !on);
    gauge.setAttribute("class", on ? "nf hi" : "nf lo");
    last = NaN;
    B.wake();
  }
  move([-999, -999]);
  bag.add(pointer(stage, { move, leave: () => move([-999, -999]) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { give = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "luggagescale",
  means: "A bag drop scale: the pointer slides the suitcase onto the plate, which sinks as the gauge behind it climbs.",
  rules: [1, 3, 5, 8],
  range: [0, 1.5, 3],
  tour: [[139, 151], [198, 181], [257, 211], null],
  mount,
});

ticketmachine.code:
/**
 * Ticket machine: a station kiosk on a plinth, a screen and a row of four
 * fare buttons on its front, and a ticket slot below them. The pointer picks
 * a fare button by where it is along the row: that button presses in and a
 * ticket feeds out of the slot, longer for a farther zone. At rest the last
 * ticket peeks from the slot, bright. The slider is the feed's delay.
 *
 * The pattern: one of many in a single row; the hit is the nearest resting
 * button centre by screen x, inside the kiosk's screen box.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, ringAt, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 40, Y1 = 26, Z0 = 4, Z1 = 74, BZ = [40, 47], BD = 3, BX0 = 6, BW = 5.5, BS = 7.5, N = 4;
const TZ = 22, TX = [9, 31], REST = 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let delay = value;
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[-3, -3, 0], [X1 + 3, -3, 0], [X1 + 3, Y1 + 3, 0], [-3, Y1 + 3, 0], [0, 0, Z1], [X1, Y1 + 28, TZ]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const plinth = solid(g);
  { const [r, i] = rings(-3, -3, X1 + 3, Y1 + 3, 3, 1.4); put(plinth, prism(P, front, r, i, 0, Z0)); }
  const body = solid(g);
  { const [r, i] = rings(0, 0, X1, Y1, 4, 1.6); put(body, prism(P, front, r, i, Z0, Z1)); }
  // the screen and the ticket slot, drawn on the front face (y = Y1)
  const face = (x0, z0, x1, z1, r) => poly(rrect(x0, z0, x1, z1, r, 4).map((s) => P(s.u, Y1, s.v)));
  mk("path", { class: "nf lo", d: face(6, 52, 34, 68, 2) + face(5, 32, 35, 36, 1) + face(TX[0] - 1, TZ - 1.4, TX[1] + 1, TZ + 1.6, 0.8) }, body.g);

  const buttons = [];
  for (let k = 0; k < N; k++) {
    const x0 = BX0 + k * BS;
    buttons.push({ k, x0, s: solid(g), d: tween(BD), last: NaN, cx: P(x0 + BW / 2, Y1 + BD, (BZ[0] + BZ[1]) / 2)[0] });
  }
  const ticket = solid(g), tl = tween(REST);
  let tLast = NaN;

  function drawButton(b, d) {
    if (d === b.last) return;
    b.last = d;
    const [r, i] = rings(b.x0, Y1 - 0.5, b.x0 + BW, Y1 + d, 1.4, Math.min(0.6, d / 2.5));
    put(b.s, prism(P, front, r, i, BZ[0], BZ[1]));
  }
  function drawTicket(l) {
    if (l === tLast) return;
    tLast = l;
    const [r, i] = rings(TX[0], Y1 - 1, TX[1], Y1 + l, 1, 0.5);
    put(ticket, prism(P, front, r, i, TZ - 0.4, TZ + 0.4));
  }

  const B = register(stage, (_dt, now) => {
    buttons.forEach((b) => drawButton(b, tval(b.d, now)));
    drawTicket(tval(tl, now));
    return buttons.some((b) => !tdone(b.d, now)) || !tdone(tl, now);
  });
  bag.add(B.unregister);

  // the hit: inside the kiosk's screen box, then the nearest resting button by screen x
  const box = [[0, 0, Z1], [X1, 0, Z1], [X1, Y1, Z0], [0, Y1, Z0], [X1, Y1, Z1], [0, Y1, Z1]].map((p) => P(...p));
  const bx = [Math.min(...box.map((p) => p[0])), Math.max(...box.map((p) => p[0]))];
  const by = [Math.min(...box.map((p) => p[1])), Math.max(...box.map((p) => p[1]))];
  function hit([sx, sy]) {
    if (sx < bx[0] || sx > bx[1] || sy < by[0] || sy > by[1]) return -1;
    let best = 0;
    buttons.forEach((b) => { if (Math.abs(b.cx - sx) < Math.abs(buttons[best].cx - sx)) best = b.k; });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    buttons.forEach((b, k) => {
      tset(b.d, k === a ? 0.8 : BD, now, 0);
      b.s.sil.classList.toggle("hi", k === a);
    });
    tset(tl, a < 0 ? REST : 12 + a * 5, now, a < 0 ? 0 : delay);
    ticket.sil.classList.toggle("hi", a < 0);
    read.textContent = a < 0 ? "rest" : "zone " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { delay = v; }, destroy: bag.dispose };
}

hairline({
  name: "ticketmachine",
  means: "A station ticket machine: the fare button under the pointer presses in and a ticket feeds out, longer for a farther zone.",
  rules: [1, 4, 5, 8],
  range: [0, 120, 240],
  tour: [[145, 149], [181, 167], [194, 174], null],
  mount,
});

shopshelves.code:
/**
 * Shop shelving: a shelf board on a back panel with a row of six products of
 * different sizes faced up along it. The pointer picks a product by where it
 * is along the shelf: that one is pulled forward to the shelf edge, the
 * neighbours shift a little after it, staggered from it. At rest the row is
 * faced unevenly, one product already pulled forward, bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single row; the hit is the nearest resting
 * centre by screen x, paint order follows x + y as products move forward.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = [12, 16, 10, 14, 18, 12], H = [22, 30, 16, 26, 20, 34], D = [12, 14, 10, 12, 16, 10];
const N = W.length, GAP = 3, X1 = W.reduce((s, w) => s + w + GAP, GAP), DEPTH = 26, PULL = 9;
const REST = [1, 0, 3, 0, 2, 1], FAV = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[0, -3, 0], [X1, -3, 0], [X1, DEPTH, -4], [0, DEPTH, -4], [0, -3, 48], [X1, -3, 48]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the back panel and the shelf board, a thin plate with a lip
  const back = solid(g);
  { const [r, i] = rings(0, -3, X1, 0, 1.2, 0.6); put(back, prism(P, front, r, i, -4, 48)); }
  const board = solid(g);
  { const [r, i] = rings(0, 0, X1, DEPTH, 2, 1.2); put(board, prism(P, front, r, i, -4, 0)); }
  const lip = solid(g);
  { const [r, i] = rings(1, DEPTH - 1.6, X1 - 1, DEPTH, 0.6, 0.3); put(lip, prism(P, front, r, i, 0, 2.2)); }

  const items = [];
  let x = GAP;
  for (let k = 0; k < N; k++) {
    const s = solid(g);
    items.push({ k, x0: x, x1: x + W[k], s, y: tween(REST[k]), last: NaN, cx: P(x + W[k] / 2, 2 + D[k] / 2, H[k] / 2)[0] });
    x += W[k] + GAP;
  }
  function draw(it, dy) {
    if (dy === it.last) return false;
    it.last = dy;
    const y0 = 2 + dy, [r, i] = rings(it.x0, y0, it.x1, y0 + D[it.k], 2.2, 1);
    put(it.s, prism(P, front, r, i, 0, H[it.k]));
    return true;
  }
  function order() {
    const sorted = items.slice().sort((a, b) => (a.x0 + a.last) - (b.x0 + b.last) || a.k - b.k);
    sorted.forEach((it) => g.appendChild(it.s.g));
    g.appendChild(lip.g);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false, changed = false;
    items.forEach((it) => { if (draw(it, tval(it.y, now))) changed = true; if (!tdone(it.y, now)) moving = true; });
    if (changed) order();
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest resting centre by screen x, inside the shelf's footprint
  function hit([sx, sy]) {
    const [hx, hy] = unproj(C, sx, sy, 14);
    if (hx < -6 || hx > X1 + 6 || hy < -10 || hy > DEPTH + 10) return -1;
    let best = -1, bd = 1e9;
    items.forEach((it) => { const d = Math.abs(it.cx - sx); if (d < bd) { bd = d; best = it.k; } });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const y = a < 0 ? REST[k] : k === a ? clamp(DEPTH - 4 - D[k], 4, PULL) : clamp(2 - Math.abs(k - a), 0, 2);
      tset(it.y, y, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "item " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "shopshelves",
  means: "A shop shelf of six products: the one under the pointer is pulled forward to the edge, its neighbours shift a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[155, 148], [225, 196], [264, 194], null],
  mount,
});

boardgames.code:
/**
 * Board game: a square board ruled into cells, with four pawns standing on
 * it and a die beside them. The pointer picks a pawn by where it stands: that
 * pawn hops up off its cell, and the pawns near it lift a little, staggered
 * by distance. At rest one pawn is mid-hop, bright. The slider is the stagger.
 *
 * The pattern: a few parts on a plane, picked by their own rest pose.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 100, CELLS = 5, CW = W / CELLS, TZ = 5, HOP = 16, FAV = 2;
const SPOTS = [[1, 1], [3, 1], [1, 3], [3, 3]].map(([i, j]) => [(i + 0.5) * CW, (j + 0.5) * CW]);
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  let stag = value;
  const bag = disposer();
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, 0, 0], [W, W, 0], [W, 0, 0], [0, W, 0], [CW * 1.5, CW * 1.5, TZ + HOP + 16], [CW * 3.5, CW * 1.5, TZ + HOP + 16]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, W, 5, 2);
  put(solid(g), prism(P, front, br, bi, 0, TZ));
  let d = "";
  for (let k = 1; k < CELLS; k++) {
    d += seg(P(k * CW, 3, TZ), P(k * CW, W - 3, TZ)) + seg(P(3, k * CW, TZ), P(W - 3, k * CW, TZ));
  }
  mk("path", { d, class: "nf lo" }, g);

  const pawns = SPOTS.map(([x, y], k) => ({ k, x, y, z: tween(k === FAV ? HOP * 0.5 : 0), last: NaN }));
  // the die, at the near free corner of the board, painted with the pawns by depth
  const parts = pawns.map((p) => ({ s: p.x + p.y, p })).concat([{ s: 2 * (W - CW * 0.5) - 1, die: true }]).sort((a, b) => a.s - b.s);
  for (const it of parts) {
    const grp = mk("g", {}, g);
    if (it.die) {
      const x = W - CW * 0.5 + 3, y = W - CW * 0.5 - 2, h = 6;
      const [dr, di] = rings(x - h, y - h, x + h, y + h, 2.4, 1.2);
      put(solid(grp), prism(P, front, dr, di, TZ, TZ + 2 * h));
      continue;
    }
    const p = it.p;
    p.body = mk("path", { class: "sil" }, grp); p.head = mk("path", { class: "sil" }, grp); p.crease = mk("path", { class: "nf lo" }, grp);
  }

  function draw(p, lift) {
    if (lift === p.last) return;
    p.last = lift;
    const z = TZ + lift;
    p.body.setAttribute("d", poly(hull(ringAt(P, disc(p.x, p.y, 6.5), z).concat(ringAt(P, disc(p.x, p.y, 6.5), z + 2), ringAt(P, disc(p.x, p.y, 2.2), z + 11)))));
    const head = [];
    for (let i = 0; i <= 6; i++) { const t = (i / 6) * Math.PI; head.push(...ringAt(P, disc(p.x, p.y, Math.max(0.3, 4.2 * Math.sin(t))), z + 14.5 - 4.2 * Math.cos(t))); }
    p.head.setAttribute("d", poly(hull(head)));
    p.crease.setAttribute("d", poly(ringAt(P, disc(p.x, p.y, 5.2), z + 2)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const p of pawns) { draw(p, tval(p.z, now)); if (!tdone(p.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  // rule 01: each pawn tests the pointer on a plane through its own rest middle
  function hit([sx, sy]) {
    let best = -1, bd = 14;
    for (const p of pawns) {
      const [wx, wy] = unproj(C, sx, sy, TZ + 8);
      const dd = Math.hypot(wx - p.x, wy - p.y);
      if (dd < bd) { bd = dd; best = p.k; }
    }
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const src = from >= 0 ? pawns[from] : null;
    for (const p of pawns) {
      const dist = src ? Math.round(Math.hypot(p.x - src.x, p.y - src.y) / (2 * CW)) : 0;
      const z = a < 0 ? (p.k === FAV ? HOP * 0.5 : 0) : p.k === a ? HOP : dist === 1 ? 4 : 0;
      tset(p.z, z, now, dist * stag);
      const on = p.k === (a < 0 ? FAV : a);
      p.body.classList.toggle("hi", on); p.head.classList.toggle("hi", on);
    }
    read.textContent = a < 0 ? "rest" : "pawn " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "boardgames",
  means: "Four pawns and a die on a ruled board: the pawn under the pointer hops off its cell, and the pawns near it lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[200, 127], [255, 155], [200, 182], null],
