});

pinwheels.code:
/**
 * Prize wheel: a fairground wheel of eight wedges on a post, with a flapper
 * at its top. The pointer picks a wedge by where it sits at rest: the wheel
 * spins forward until that wedge stops under the flapper, and its edge goes
 * bright. At rest the wheel is still, one wedge up top, bright. The slider is
 * how many extra laps a spin takes.
 *
 * The pattern: one dial, turned to a chosen stop.
 */
const {
  Cam, fit, hull, poly, proj, rings, prism, facing, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 8, R = 46, CX = 50, CZ = 70, BY = 20, FY = 25, FAV = 2, TAU = Math.PI * 2;
// uneven wedges, as on a real prize wheel: the narrow one is the jackpot
const WT = [1, 1.6, 0.55, 1.2, 0.9, 1.4, 0.8, 1.3], SUM = WT.reduce((a, b) => a + b, 0);
const SPAN = WT.map((w) => (w / SUM) * TAU), START = [];
SPAN.reduce((a, w, k) => { START[k] = a; return a + w; }, 0);
const OFF = Math.PI / 2 - START[FAV] - SPAN[FAV] / 2;
const MID = SPAN.map((w, k) => OFF + START[k] + w / 2);

function mount({ stage, svg, read }, value) {
  let laps = value;
  const bag = disposer();
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[CX - R, FY, CZ - R], [CX + R, FY, CZ + R], [CX - R, BY, CZ], [CX + R, FY, CZ], [CX, FY, CZ + R + 8], [CX - 26, 4, 0], [CX + 26, 44, 0]], 200, 164);
  const P = proj(C), front = facing(C);
  const W = (r, a, y) => P(CX + r * Math.cos(a), y, CZ + r * Math.sin(a));
  const ring = (r, y, n = 48, a0 = 0) => Array.from({ length: n }, (_, i) => W(r, a0 + (i / n) * TAU, y));
  const g = mk("g", {}, svg);
  const [fr, fi] = rings(CX - 26, 4, CX + 26, 44, 6, 2);
  put(solid(g), prism(P, front, fr, fi, 0, 4));
  const [pr, pi] = rings(CX - 4, BY - 10, CX + 4, BY - 2, 2.5, 1);
  put(solid(g), prism(P, front, pr, pi, 4, CZ));
  mk("path", { d: poly(hull(ring(R, BY).concat(ring(R, FY)))), class: "sil" }, g);
  mk("path", { d: poly(ring(R - 2.5, FY)), class: "nf lo" }, g);
  const wedges = Array.from({ length: N }, () => mk("path", { class: "nf" }, g));
  mk("path", { d: poly(hull(ring(6, FY, 24).concat(ring(6, FY + 3, 24)))), class: "sil" }, g);
  // the flapper: a small tab standing at the top of the rim
  const t = CZ + R;
  mk("path", { d: poly([P(CX - 3, FY + 1, t + 9), P(CX + 3, FY + 1, t + 9), P(CX, FY + 1, t - 4)]), class: "sil" }, g);

  const rot = tween(0);
  let last = NaN;
  function draw(r) {
    if (r === last) return;
    last = r;
    wedges.forEach((w, k) => {
      const a0 = OFF + START[k] + r, A = SPAN[k], pts = [];
      for (let i = 0; i <= 8; i++) pts.push(W(R - 4, a0 + (i / 8) * A, FY));
      pts.push(W(8, a0 + A, FY), W(8, a0, FY));
      w.setAttribute("d", poly(pts));
    });
  }

  const B = register(stage, (_dt, now) => { draw(tval(rot, now)); return !tdone(rot, now); });
  bag.add(B.unregister);

  // rule 01: pick in the wheel's rest frame, by the pointer's angle on its face
  const o = P(CX, FY, CZ), ex = P(CX + 1, FY, CZ), ez = P(CX, FY, CZ + 1);
  const a1 = ex[0] - o[0], b1 = ex[1] - o[1], a2 = ez[0] - o[0], b2 = ez[1] - o[1], det = a1 * b2 - a2 * b1;
  function hit([sx, sy]) {
    const dx = sx - o[0], dy = sy - o[1], u = (dx * b2 - a2 * dy) / det, v = (a1 * dy - dx * b1) / det;
    if (Math.hypot(u, v) > R + 4 || Math.hypot(u, v) < 8) return -1;
    const t = ((Math.atan2(v, u) - OFF) % TAU + TAU) % TAU;
    return START.findIndex((s0, k) => t >= s0 && t < s0 + SPAN[k]);
  }

  let act = -2, goal = 0;
  function setActive(a) {
    if (a === act) return;
    act = a;
    const k = a < 0 ? FAV : a;
    // spin forward (clockwise) to bring wedge k under the flapper, plus extra laps
    let want = Math.PI / 2 - MID[k], d = ((goal - want) % TAU + TAU) % TAU;
    if (a >= 0) d += Math.round(laps) * TAU;
    goal -= d;
    tset(rot, goal, performance.now(), 0);
    wedges.forEach((w, i) => w.classList.toggle("hi", i === k));
    wedges[N - 1].after(wedges[k]);
    read.textContent = a < 0 ? "rest" : "slot " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { laps = v; }, destroy: bag.dispose };
}

hairline({
  name: "pinwheels",
  means: "A prize wheel of eight uneven wedges on a post: point at a wedge and the wheel spins until it stops under the flapper.",
  rules: [1, 3, 5, 6],
  range: [0, 1, 2],
  tour: [[200, 76], [246, 155], [154, 128], null],
  mount,
});

ironingrack.code:
/**
 * Drying rack: a low frame on four legs with five rails, a cloth draped over
 * each rail, every cloth a different width and drop. The pointer picks a
 * rail by where it stands: its cloth lifts off the rail, and the cloths
 * beside it twitch up a little, staggered from it. At rest one cloth is half
 * lifted, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, hull, poly, prism, proj, rings, facing, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, GAP = 22, L = 90, RZ = 46, LIFT = 18, FAV = 2, X1 = (N + 1) * GAP;
const CLOTH = [[14, 70, 24], [8, 62, 32], [20, 76, 20], [12, 56, 28], [18, 72, 22]];

function mount({ stage, svg, read }, value) {
  let stag = value;
  const bag = disposer();
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [X1, L, 0], [X1, 0, 0], [0, L, 0], [GAP, 10, RZ + LIFT + 4], [X1 - GAP, L, RZ + LIFT + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, parent = g) => {
    const [r, i] = rings(x0, y0, x1, y1, Math.min(x1 - x0, y1 - y0) / 2.2, 0.5);
    put(solid(parent), prism(P, front, r, i, z0, z1));
  };
  // far legs and far end bar
  box(0, 0, 3, 3, 0, RZ); box(X1 - 3, 0, X1, 3, 0, RZ);
  box(0, 0, X1, 3, RZ, RZ + 3);
  box(0, L - 3, 3, L, 0, RZ);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = (k + 1) * GAP, grp = mk("g", {}, g);
    box(x - 1.2, 3, x + 1.2, L - 3, RZ + 0.5, RZ + 2.5, grp);
    const [y0, y1, drop] = CLOTH[k];
    const sil = mk("path", { class: "sil" }, grp), fold = mk("path", { class: "nf lo" }, grp);
    items.push({ x, y0, y1, drop, sil, fold, z: tween(k === FAV ? LIFT * 0.5 : 0), last: NaN });
  }
  box(X1 - 3, L - 3, X1, L, 0, RZ);
  box(0, L - 3, X1, L, RZ, RZ + 3);

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const top = RZ + 3 + lift, bot = top - it.drop, { x, y0, y1 } = it;
    const pts = [];
    for (const dx of [-2.5, 2.5]) for (const [y, z] of [[y0, top - 1.5], [y0 + 2, top], [y1 - 2, top], [y1, top - 1.5], [y1, bot + 2], [y1 - 2, bot], [y0 + 2, bot], [y0, bot + 2]]) pts.push(P(x + dx, y, z));
    it.sil.setAttribute("d", poly(hull(pts)));
    it.fold.setAttribute("d", poly([P(x + 2.5, y0 + 2, top - 1), P(x + 2.5, y1 - 2, top - 1)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, (it.y0 + it.y1) / 2, RZ - it.drop / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.5 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "rail " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "ironingrack",
  means: "A drying rack with a cloth on each rail: the cloth under the pointer lifts off its rail, and its neighbours twitch up a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[152, 132], [206, 159], [254, 189], null],
  mount,
});

dogbowl.code:
/**
 * Dog bowls: a raised wooden stand on four legs holding three steel bowls in
 * round cut-outs. The pointer picks a bowl by where it stands: that bowl
 * lifts out of its ring, and the bowls beside it rise a little, staggered
 * from it. At rest the middle bowl sits half out, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 44, BR = 17, BF = 11, BH = 9, LIFT = 16, FAV = 1, LZ = 16, TZ = 21;
const X1 = (N - 1) * STEP + 2 * BR + 12;
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  let stag = value;
  const bag = disposer();
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[0, 0, 0], [X1, 2 * BR + 12, 0], [X1, 0, 0], [0, 2 * BR + 12, 0], [BR + 6, BR + 6, TZ + LIFT + BH], [X1 - BR - 6, BR + 6, TZ + LIFT + BH]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const W = 2 * BR + 12;
  // legs, far to near
  for (const [x, y] of [[4, 4], [X1 - 8, 4], [4, W - 8], [X1 - 8, W - 8]]) {
    const [r, i] = rings(x, y, x + 4, y + 4, 1.6, 0.8);
    put(solid(g), prism(P, front, r, i, 0, LZ));
  }
  const [tr, ti] = rings(0, 0, X1, W, 6, 2);
  put(solid(g), prism(P, front, tr, ti, LZ, TZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = BR + 6 + k * STEP, y = BR + 6, grp = mk("g", {}, g);
    mk("path", { d: poly(ringAt(P, disc(x, y, BR - 2, 40), TZ)), class: "lo" }, grp);
    const body = mk("path", { class: "sil" }, grp), lip = mk("path", { class: "nf lo" }, grp), well = mk("path", { class: "nf lo" }, grp);
    items.push({ x, y, body, lip, well, z: tween(k === FAV ? LIFT * 0.55 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const base = TZ - BH * 0.6 + lift, top = base + BH;
    const foot = ringAt(P, disc(it.x, it.y, BF, 28), Math.max(base, TZ - 0.01)), rim = ringAt(P, disc(it.x, it.y, BR - 0.5, 40), top);
    it.body.setAttribute("d", poly(hull(foot.concat(rim))));
    it.lip.setAttribute("d", poly(ringAt(P, disc(it.x, it.y, BR - 2.5, 40), top)));
    it.well.setAttribute("d", poly(ringAt(P, disc(it.x, it.y, BF - 2, 28), top - BH * 0.7)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, TZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.55 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bowl " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "dogbowl",
  means: "Three steel bowls in a raised stand: the bowl under the pointer lifts out of its ring, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[141, 120], [200, 149], [259, 179], null],
  mount,
