pipetterack.code:
/**
 * Pipette stand: a weighted base, a post at the end and a rail along the
 * back, with five pipettes hanging in front of it, each a grip, a thin tip
 * and a plunger button. The pointer picks a pipette by where it is along the
 * row: it lifts out of the stand, the others rise a little, staggered from
 * it. At rest they hang at uneven heights, one pulled half out, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is each pipette's rest
 * centre on screen x.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 12, X0 = 8, PY = 8, LIFT = 16, BUMP = 5;
const X1 = X0 + (N - 1) * STEP + 8;
const REST = [0, 3, 1, 8, 2], FAV = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-8, -6, 0], [X1, 16, 0], [-8, 16, 0], [X1, -6, 0], [X0, PY, 66 + LIFT], [X1 - 8, PY, 66 + LIFT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (parent, x0, y0, x1, y1, r, b, z0, z1) => {
    const s = solid(parent), [o, i] = rings(x0, y0, x1, y1, r, b);
    put(s, prism(P, front, o, i, z0, z1));
    return s;
  };

  // the stand: base, post and back rail
  box(g, -8, -6, X1, 16, 5, 1.6, 0, 5);
  box(g, -6, -3, 0, 3, 2.5, 0.8, 5, 50);
  box(g, -6, -3, X1 - 2, 3, 2, 0.8, 44, 49);
  // the rest cups on the base, one per pipette
  const cups = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP, cp = [];
    for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; cp.push(P(x + 2.4 * Math.cos(a), PY + 2.4 * Math.sin(a), 5)); }
    cups.push("M" + cp.map((p) => p.map((v) => v.toFixed(2)).join(" ")).join("L") + "Z");
  }
  mk("path", { class: "nf lo", d: cups.join("") }, g);

  const pips = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    pips.push({ k, x: X0 + k * STEP, grp, tip: solid(grp), grip: solid(grp), btn: solid(grp), z: tween(REST[k]), last: NaN });
  }
  function draw(p, lift) {
    if (lift === p.last) return;
    p.last = lift;
    const x = p.x, z = 10 + lift;
    let [o, i] = rings(x - 1.3, PY - 1.3, x + 1.3, PY + 1.3, 1.3, 0.4);
    put(p.tip, prism(P, front, o, i, z, z + 24));
    [o, i] = rings(x - 3.4, PY - 3.4, x + 3.4, PY + 3.4, 3.4, 1);
    put(p.grip, prism(P, front, o, i, z + 22, z + 50));
    [o, i] = rings(x - 2.2, PY - 2.2, x + 2.2, PY + 2.2, 2.2, 0.7);
    put(p.btn, prism(P, front, o, i, z + 50, z + 55));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    pips.forEach((p) => { draw(p, tval(p.z, now)); if (!tdone(p.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest rest centre on screen x, inside the stand's band
  const top = P(X0, PY, 70)[1], bot = P(X1, 16, 0)[1];
  function hit([sx, sy]) {
    if (sy < top - 10 || sy > bot + 6) return -1;
    let best = -1, bd = 1e9;
    pips.forEach((p, k) => { const d = Math.abs(P(p.x, PY, 36)[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 22 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    pips.forEach((p, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : clamp(BUMP - Math.abs(k - a) * 2, 0, BUMP);
      tset(p.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      [p.tip, p.grip, p.btn].forEach((s) => s.sil.classList.toggle("hi", on));
    });
    read.textContent = a < 0 ? "rest" : "pip " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "pipetterack",
  means: "A pipette stand: the pipette under the pointer lifts out of the rack, its neighbours rise a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[158, 139], [202, 161], [246, 183], null],
  mount,
});

notecounter.code:
/**
 * Note counter: a squat machine with a display window and an exit slot on
 * its front, and a hopper on top holding seven banknotes on edge, fanned a
 * little, each with its watermark oval. The pointer picks a note by where it
 * is along the stack: it rises out of the hopper, its neighbours rise a
 * little after it. At rest the stack is uneven, one note half drawn, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is each note's rest
 * centre on screen x.
 */
const {
  Cam, clamp, facing, fillet, fit, hull, open, poly, prism, proj, rings, rrect, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 7, STEP = 4, X0 = 5, TOP = 20, NY0 = 6, NY1 = 30, NH = 13, LIFT = 15, BUMP = 5, T = 0.5;
const X1 = X0 + (N - 1) * STEP + 6;
const REST = [0, 1.5, 0.5, 6, 1, 2, 0], LEAN = [-0.3, -0.2, -0.1, 0, 0.1, 0.2, 0.3], FAV = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 4.2);
  fit(C, [[-2, -2, 0], [X1, 36, 0], [-2, 36, 0], [X1, -2, 0], [X0, NY0, TOP + NH + LIFT], [X1, NY1, TOP + NH + LIFT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the body, its hopper rim, the display window and exit slot on the near face
  const body = solid(g), [o, i] = rings(-2, -2, X1, 36, 6, 1.6);
  put(body, prism(P, front, o, i, 0, TOP));
  const face = (pts) => poly(pts.map(([u, z]) => P(u, 36, z)));
  mk("path", { class: "nf lo", d: poly(ringAt(P, rrect(X0 - 2, NY0 - 2, X1 - 4, NY1 + 2, 2, 4), TOP)) +
    face(fillet([[4, 9], [16, 9], [16, 15], [4, 15]], [1.2, 1.2, 1.2, 1.2], 3)) +
    face(fillet([[20, 4], [X1 - 4, 4], [X1 - 4, 6], [20, 6]], [0.8, 0.8, 0.8, 0.8], 3)) }, body.g);

  const notes = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    notes.push({ k, x: X0 + k * STEP, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), z: tween(REST[k]), last: NaN });
  }
  const outline = fillet([[NY0, 0], [NY1, 0], [NY1, NH], [NY0, NH]], [1, 1, 1, 1], 3);
  const oval = [];
  for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; oval.push([NY0 + 6 + 2.6 * Math.cos(a), NH / 2 + 3.6 * Math.sin(a)]); }
  function draw(s, lift) {
    if (lift === s.last) return;
    s.last = lift;
    const at = (dx) => ([y, z]) => P(s.x + dx + z * LEAN[s.k], y, TOP - 3 + lift + z);
    s.sil.setAttribute("d", poly(hull(outline.map(at(T)).concat(outline.map(at(-T))))));
    s.cr.setAttribute("d", poly(oval.map(at(T))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    notes.forEach((s) => { draw(s, tval(s.z, now)); if (!tdone(s.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest rest centre on screen x, inside the machine's band
  const top = P(X0, NY0, TOP + NH + 8)[1], bot = P(X1, 36, 0)[1];
  function hit([sx, sy]) {
    if (sy < top - 8 || sy > bot) return -1;
    let best = -1, bd = 1e9;
    notes.forEach((s, k) => { const d = Math.abs(P(s.x + 6 * LEAN[k], (NY0 + NY1) / 2, TOP + 6)[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 30 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    notes.forEach((s, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : clamp(BUMP - Math.abs(k - a) * 1.5, 0, BUMP);
      tset(s.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "note " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "notecounter",
  means: "A banknote counter: the note under the pointer rises out of the hopper, its neighbours rise a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[163, 132], [187, 144], [234, 168], null],
  mount,
});

securityarch.code:
/**
 * Security arch: a walk-through scanner on a floor plate, two pillars of
 * stacked detection zones under a beam. The pointer picks a zone by its
 * height on the arch: that zone's panels on both pillars push outward, the
 * zones beside it a little, staggered from it. At rest the zones sit a
 * little uneven, the middle one pushed out, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a stack; the hit is each zone's rest centre on
 * screen y.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, ZH = 10, Z0 = 2, W = 6, GAPX = 34, D = 12, PUSH = 6, BUMP = 2.5;
const ZT = Z0 + N * ZH, XR = GAPX + W;
const REST = [0.5, 1, 3, 1.5, 0], FAV = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[-6 - PUSH, -14, 0], [XR + 6 + PUSH, 26, 0], [-6, 26, 0], [XR + 6, -14, 0], [-PUSH, 0, ZT + 6], [XR + PUSH, D, ZT + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const floor = solid(g), [fo, fi] = rings(-6, -14, XR + 6, 26, 5, 1.6);
  put(floor, prism(P, front, fo, fi, 0, 2));
  // the walkway's line through the arch, on the plate
  mk("path", { class: "nf lo dash", d: "M" + P(GAPX / 2 + 3, -12, 2).join(" ") + "L" + P(GAPX / 2 + 3, 24, 2).join(" ") }, g);

  const gl = mk("g", {}, g), gr = mk("g", {}, g);
  const zones = [];
  for (let k = 0; k < N; k++) zones.push({ k, l: solid(gl), r: solid(gr), off: tween(REST[k]), last: NaN });
  const beam = solid(g), [bo, bi] = rings(-1, -0.5, XR + 1, D + 0.5, 3, 1);
  put(beam, prism(P, front, bo, bi, ZT, ZT + 6));

  function draw(s, off) {
    if (off === s.last) return;
    s.last = off;
    const z0 = Z0 + s.k * ZH + 0.6, z1 = z0 + ZH - 1.2;
    let [o, i] = rings(-off, 0, W - off, D, 2.2, 0.8);
    put(s.l, prism(P, front, o, i, z0, z1));
    [o, i] = rings(GAPX + off, 0, XR + off, D, 2.2, 0.8);
    put(s.r, prism(P, front, o, i, z0, z1));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    zones.forEach((s) => { draw(s, tval(s.off, now)); if (!tdone(s.off, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: inside the arch's screen band, the zone whose rest centre is nearest on screen y
  const xa = Math.min(P(-6, D, 0)[0], P(-6, 0, 0)[0]) - 6, xb = Math.max(P(XR + 6, 0, 0)[0], P(XR + 6, D, 0)[0]) + 6;
  function hit([sx, sy]) {
    if (sx < xa || sx > xb) return -1;
    const t = clamp((sx - P(0, D / 2, 0)[0]) / (P(XR, D / 2, 0)[0] - P(0, D / 2, 0)[0]), 0, 1);
    let best = -1, bd = 1e9;
    zones.forEach((s, k) => { const d = Math.abs(P(t * XR, D / 2, Z0 + (k + 0.5) * ZH)[1] - sy); if (d < bd) { bd = d; best = k; } });
    return bd < ZH * 2.9 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    zones.forEach((s, k) => {
      const z = a < 0 ? REST[k] : k === a ? PUSH : clamp(BUMP - (Math.abs(k - a) - 1) * 1.5, 0, BUMP);
      tset(s.off, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      s.l.sil.classList.toggle("hi", on);
      s.r.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "zone " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "securityarch",
  means: "A walk-through security arch: the detection zone at the pointer's height pushes its panels out, the zones beside it less.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[200, 111], [200, 173], [200, 198], null],
  mount,
});

scoreboard.code:
/**
 * Scoreboard: a board on two legs with four flip panels hinged along their
 * tops on its face. The pointer picks a panel by where it is along the
 * board: it flips up toward the viewer, the panels beside it lift a little,
 * staggered from it. At rest the panels hang a little uneven, one tipped
 * out, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is each panel's rest
 * centre on screen x.
 */
const {
  Cam, clamp, facing, fillet, fit, hull, open, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 15, X0 = 3, PW = 12, BW = X0 * 2 + (N - 1) * STEP + PW, YF = 6.6, ZT = 50, PH = 24, UP = 1.25, BUMP = 0.3;
const REST = [0.05, 0.45, 0, 0.12], FAV = 1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.3);
  fit(C, [[-2, -2, 0], [BW + 2, 8, 0], [0, 0, ZT + 6], [BW, YF + PH, ZT], [0, YF + PH, ZT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1) => { const s = solid(g), [o, i] = rings(x0, y0, x1, y1, r, b); put(s, prism(P, front, o, i, z0, z1)); return s; };
  box(6, 1, 11, 5, 2, 0.7, 0, 24);
  box(BW - 11, 1, BW - 6, 5, 2, 0.7, 0, 24);
  box(0, 0, BW, 6, 2.5, 1, 22, ZT + 4);

  const flaps = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    flaps.push({ k, x: X0 + k * STEP, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), a: tween(REST[k]), last: NaN });
  }
  const shape = fillet([[0, 0], [PW, 0], [PW, PH], [0, PH]], [1.5, 1.5, 1.5, 1.5], 3);
  function draw(s, a) {
    if (a === s.last) return;
    s.last = a;
    const sn = Math.sin(a), cs = Math.cos(a);
    const at = (t) => ([u, v]) => P(s.x + u, YF + v * sn + t * cs, ZT - v * cs + t * sn);
    s.sil.setAttribute("d", poly(hull(shape.map(at(0)).concat(shape.map(at(0.9))))));
    s.cr.setAttribute("d", open([[1.5, PH / 2], [PW - 1.5, PH / 2]].map(at(0.9))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    flaps.forEach((s) => { draw(s, tval(s.a, now)); if (!tdone(s.a, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest rest centre on screen x, inside the board's band
  const top = P(0, 0, ZT + 8)[1], bot = P(BW, YF, 18)[1];
  function hit([sx, sy]) {
    if (sy < top || sy > bot + 10) return -1;
    let best = -1, bd = 1e9;
    flaps.forEach((s, k) => { const d = Math.abs(P(s.x + PW / 2, YF, ZT - PH / 2)[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 30 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    flaps.forEach((s, k) => {
      const t = a < 0 ? REST[k] : k === a ? UP : clamp(BUMP - (Math.abs(k - a) - 1) * 0.15, 0, BUMP);
      tset(s.a, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "flap " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "scoreboard",
  means: "A flip scoreboard: the panel under the pointer flips up toward you, the panels beside it lift a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[174, 114], [244, 149], [279, 166], null],
  mount,
});

wheelchock.code:
/**
 * Wheel chocks: three tyres standing in a row on a garage slab, each with a
 * wedge chock behind it. The pointer picks a tyre by where it stands: its
 * chock slides in snug against the tread, and the other chocks pull back,
 * staggered from it. At rest one chock sits home, bright.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, tdone, tset, tval, tween, fillet,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 64, R = 20, W = 14, CL = 18, CH = 11, FAV = 1;
const REST = [9, 0, 14];
const X0 = CL + 16, X1 = X0 + (N - 1) * STEP + R + 10;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-4, -10, 0], [X1, W + 10, 0], [X1, -10, 0], [-4, W + 10, 0], [X0, 0, 2 * R + 3], [X1 - 10, W, 2 * R + 3]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-4, -10, X1, W + 10, 6, 2);
  put(solid(g), prism(P, front, sr, si, 0, 3));

  const circle = (cx, y, r, n = 40) => { const o = []; for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; o.push(P(cx + r * Math.cos(t), y, 3 + R + r * Math.sin(t))); } return o; };
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP;
    const chock = mk("g", {}, g);
    const sil = mk("path", { class: "sil" }, chock), cr = mk("path", { class: "nf lo" }, chock);
    const tyre = mk("g", {}, g);
    mk("path", { d: poly(hull(circle(x, 0, R).concat(circle(x, W, R)))), class: "sil" }, tyre);
    mk("path", { d: poly(circle(x, W, R - 2)), class: "nf lo" }, tyre);
    mk("path", { d: poly(circle(x, W + 0.5, 8, 24)), class: "nf" }, tyre);
    items.push({ k, x, sil, cr, gap: tween(REST[k]), last: NaN });
  }

  function draw(it, gap) {
    if (gap === it.last) return;
    it.last = gap;
    const b = it.x - Math.sqrt(R * R - (R - 2) * (R - 2)) - gap, a = b - CL;
    const prof = fillet([[a, 0], [b, 0], [a + 4, CH]], [1.5, 1, 1.5]);
    const at = (y) => prof.map(([u, z]) => P(u, y, 3 + z));
    const prof2 = fillet([[a + 1.2, 0.8], [b - 3, 0.8], [a + 4.4, CH - 1.6]], [1, 1, 1]);
    it.sil.setAttribute("d", poly(hull(at(1).concat(at(W - 1)))));
    it.cr.setAttribute("d", poly(prof2.map(([u, z]) => P(u, W - 1, 3 + z))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.gap, now)); if (!tdone(it.gap, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x - R / 2, W / 2, 3 + R / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), v = a < 0 ? REST[k] : dd === 0 ? 0 : 12 + 6 * dd;
      tset(it.gap, v, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "chock " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "wheelchock",
  means: "Three tyres on a slab, each with a wedge chock: the chock behind the tyre under the pointer slides in snug.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[115, 122], [195, 163], [269, 200], null],
  mount,
});

oilchange.code:
/**
 * Oil drain pan: a car's sump hangs overhead with its drain plug, and a round
 * drain pan sits on the floor below. The pan slides to follow the pointer
 * across the floor, clamped to a reach round the plug; a dashed drip falls
 * from the plug to the floor. At rest the pan waits off to one side and the
 * plug is bright.
 *
 * The pattern: one part following the pointer on the ground (terrain).
 */
const {
  Cam, circ, clamp, fit, facing, poly, prism, proj, rings, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid, seg,
} = HL;

const PX = 0, PY = 0, ZS = 58, PR = 22, PH = 7, REACH = 34, RX = 22, RY = -16;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[-REACH - PR, -REACH - PR, 0], [REACH + PR, REACH + PR, 0], [REACH + PR, -REACH - PR, 0], [-REACH - PR, REACH + PR, 0], [-34, -22, ZS + 12], [34, 22, ZS + 12]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the sump: a rounded pan bolted under the engine, and the plug under it
  const [sr, si] = rings(-34, -22, 34, 22, 8, 2);
  put(solid(g), prism(P, front, sr, si, ZS, ZS + 12));
  const plug = solid(g);
  put(plug, prism(P, front, disc(PX, PY, 4, 20), disc(PX, PY, 2.5, 20), ZS - 4, ZS));
  const drip = mk("path", { class: "dash" }, g);
  const pan = mk("g", {}, g);
  const sil = mk("path", { class: "sil" }, pan), cr = mk("path", { class: "nf lo" }, pan), oil = mk("path", { class: "nf lo" }, pan);
  const sx = spring(RX), sy = spring(RY);
  let last = "";

  function draw() {
    const x = sx.x, y = sy.x, key = x.toFixed(2) + "," + y.toFixed(2);
    if (key === last) return;
    last = key;
    // a pan that flares: foot ring smaller than the rim
    const foot = disc(x, y, PR - 4), top = disc(x, y, PR), inner = disc(x, y, PR - 2);
    const pts = foot.map((q) => P(q.u, q.v, 0)).concat(top.map((q) => P(q.u, q.v, PH)));
    sil.setAttribute("d", poly(HL.hull(pts)));
    cr.setAttribute("d", poly(inner.map((q) => P(q.u, q.v, PH))));
    oil.setAttribute("d", poly(disc(x, y, PR - 6).map((q) => P(q.u, q.v, PH - 3))));
    const d = Math.hypot(x - PX, y - PY), land = d < PR - 6 ? PH - 3 : d < PR ? PH : 0;
    drip.setAttribute("d", seg(P(PX, PY, ZS - 5), P(PX, PY, land)));
    if (d >= PR - 2 && d < PR + 1) drip.setAttribute("d", seg(P(PX, PY, ZS - 5), P(PX, PY, PH)));
    // the drip shows in front of the pan only when it lands inside it
    if (d < PR) pan.after(drip); else pan.before(drip);
  }

  const B = register(stage, (dt) => {
    const a = stepS(sx, dt), b = stepS(sy, dt);
    draw();
    return a || b;
  });
  bag.add(B.unregister);

  function aim(on, wx, wy) {
    const d = Math.hypot(wx, wy), s = d > reach ? reach / d : 1;
    sx.t = on ? clamp(wx * s, -REACH, REACH) : RX;
    sy.t = on ? clamp(wy * s, -REACH, REACH) : RY;
    sil.classList.toggle("hi", on);
    plug.sil.classList.toggle("hi", !on);
    const off = Math.round(Math.hypot(sx.t, sy.t));
    read.textContent = on ? (off < 6 ? "under" : "off " + off) : "rest";
    B.wake();
  }
  aim(false, 0, 0);
  bag.add(pointer(stage, {
    move: ([px, py]) => { const [wx, wy] = unproj(C, px, py, 0); aim(true, wx, wy); },
    leave: () => aim(false, 0, 0),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "oilchange",
  means: "A sump and drain plug overhead, a round drain pan on the floor: the pan slides under the pointer to catch the drip.",
  rules: [1, 3, 5, 6],
  range: [10, 34, 34],
  tour: [[150, 189], [200, 208], [150, 239], null],
  mount,
});

airpump.code:
/**
 * Air compressor: a tank lying on its feet with a gauge on top, and a hose
 * running to a tyre standing beside it. The pointer's place along the floor
 * is the pressure: the tyre swells as it moves out, clamped to a full tyre,
 * and the hose lifts with it. At rest the tyre sits soft and the gauge is
 * bright.
 *
 * The pattern: a continuous input driving one part (spring).
 */
const {
  Cam, circ, clamp, fit, facing, hull, lerp, open, poly, prism, proj, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const TL = 56, TR = 15, TX = 96, TW = 14, R0 = 15, R1 = 24, REST = 0.3;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let span = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-4, -TR - 4, 0], [TX + R1, TW + 4, 0], [TX + R1, -TR - 4, 0], [-4, TR + 4, 0], [0, 0, 2 * TR + 14], [TX, TW, 2 * R1 + 2]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  for (const fx of [8, TL - 8]) put(solid(g), prism(P, front, disc(fx, 0, 5), disc(fx, 0, 3.5), 0, 5));
  const ring = (x, r) => { const o = []; for (let i = 0; i < 40; i++) { const t = (i / 40) * Math.PI * 2; o.push(P(x, r * Math.cos(t), 4 + TR + r * Math.sin(t))); } return o; };
  mk("path", { d: poly(hull(ring(0, TR).concat(ring(TL, TR)))), class: "sil" }, g);
  mk("path", { d: poly(ring(TL - 2, TR - 1)), class: "nf lo" }, g);
  const gauge = solid(g);
  put(gauge, prism(P, front, disc(TL / 2, 0, 5.5), disc(TL / 2, 0, 4), 4 + 2 * TR - 1, 4 + 2 * TR + 6));
  const hose = mk("path", { class: "nf" }, g);
  const tyre = mk("g", {}, g);
  const sil = mk("path", { class: "sil" }, tyre), face = mk("path", { class: "nf lo" }, tyre), hub = mk("path", { class: "nf" }, tyre);
  const p = spring(REST);
  let last = NaN;

  const wheel = (y, r, n = 40) => { const o = []; for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; o.push([TX + r * Math.cos(t), y, r * Math.sin(t)]); } return o; };
  function draw() {
    const v = Math.round(p.x * 400) / 400;
    if (v === last) return;
    last = v;
    const R = lerp(R0, R1, v), w = lerp(TW - 3, TW, v), at = (q) => P(q[0], q[1], R + q[2]);
    sil.setAttribute("d", poly(hull(wheel(0, R).concat(wheel(w, R)).map(at))));
    face.setAttribute("d", poly(wheel(w, R - 2.5).map(at)));
    hub.setAttribute("d", poly(wheel(w + 0.5, 7, 24).map(at)));
    const a = [TL / 2 + 6, 0, 4 + 2 * TR + 3], b = [TX - 7 * 0.7, w + 0.5, R + 5], pts = [];
    for (let i = 0; i <= 18; i++) { const u = i / 18; pts.push(P(lerp(a[0], b[0], u), lerp(a[1], b[1], u), lerp(a[2], b[2], u) + Math.sin(Math.PI * u) * (8 + 10 * v))); }
    hose.setAttribute("d", open(pts));
  }

  const B = register(stage, (dt) => { const m = stepS(p, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(on, wx) {
    p.t = on ? clamp((wx + 10) / span, 0, 1) : REST;
    sil.classList.toggle("hi", on);
    gauge.sil.classList.toggle("hi", !on);
    read.textContent = on ? "psi " + Math.round(lerp(12, 36, p.t)) : "rest";
    B.wake();
  }
  aim(false, 0);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => aim(true, unproj(C, sx, sy, 0)[0]),
    leave: () => aim(false, 0),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { span = v; }, destroy: bag.dispose };
}

hairline({
  name: "airpump",
  means: "A compressor tank with a gauge and a hose to a tyre: the pointer's place along the floor sets the pressure and the tyre swells.",
  rules: [1, 3, 5, 8],
  range: [60, 110, 160],
  tour: [[97, 111], [186, 134], [262, 206], null],
  mount,
});

coinroll.code:
/**
 * Coin wrapper: five paper-wrapped coin rolls standing in a shallow tray,
 * each crimped at both ends. The pointer picks a roll by where it stands:
 * it rises out of the tray and the rolls beside it nudge up, staggered from
 * it. At rest one roll stands proud, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, open, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 24, R = 9.5, LIFT = 20, FAV = 2, TZ = 4;
const H = [34, 40, 30, 37, 32];
const X1 = (N - 1) * STEP + 2 * R;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-7, -7, 0], [X1 + 7, 2 * R + 7, 0], [X1 + 7, -7, 0], [-7, 2 * R + 7, 0], [R + STEP, R, TZ + 40 + LIFT], [X1 - R, R, TZ + 37 + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(-7, -7, X1 + 7, 2 * R + 7, 6, 2);
  put(solid(g), prism(P, front, tr, ti, 0, TZ));
  const [wr, wi] = rings(-4, -4, X1 + 4, 2 * R + 4, 4, 1.2);
  mk("path", { d: open(ringAt(P, run(wi, (q) => !front(q)), TZ - 0.01)), class: "nf lo" }, g);
  void wr;

  const rest = (k) => (k === FAV ? 9 : 0);
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = R + k * STEP, y = R, grp = mk("g", {}, g), s = solid(grp);
    const ring = disc(x, y, R), inner = disc(x, y, R - 1.4), fr = run(ring, front);
    const c1 = mk("path", { class: "nf lo" }, grp), c2 = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, y, s, ring, inner, fr, c1, c2, z: tween(rest(k)), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = TZ + lift, z1 = z0 + H[it.k];
    put(it.s, prism(P, front, it.ring, it.inner, z0, z1));
    it.c1.setAttribute("d", open(ringAt(P, it.fr, z0 + 4)));
    it.c2.setAttribute("d", open(ringAt(P, it.fr, z1 - 4)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, TZ + H[it.k] / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? rest(k) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "roll " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "coinroll",
  means: "Five wrapped coin rolls in a tray: the roll under the pointer rises out, and its neighbours nudge up after it.",
  rules: [1, 2, 5, 9],
  range: [0, 40, 80],
  tour: [[130, 136], [165, 153], [270, 205], null],
  mount,
});

receiptspike.code:
/**
 * Receipt spike: a weighted base with a steel spike, five paper slips
 * pierced on it at loose angles. The pointer picks a slip by where it lies:
 * it rides up the spike and turns square, and the slips beside it rise a
 * little, staggered from it. At rest one slip sits proud, bright. The slider
 * is the stagger.
 *
 * The pattern: stepped parts, picked on their own rest tops.
 */
const {
  Cam, circ, fit, facing, poly, prism, proj, rrect, rings, ringAt, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, GAP = 9, Z0 = 10, LIFT = 6, FAV = 2, TIP = Z0 + N * GAP + 10;
const ANG = [-10, 28, -24, 52, 12], OFF = [4, -3, 2, -5, 3];
const disc = (r, n = 32) => circ(r, n);
function slip(th, off) {
  const c = Math.cos(th), s = Math.sin(th);
  return rrect(-17 + off, -11, 17 + off, 11, 1.5, 4).map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.5);
  fit(C, [[-24, -24, 0], [24, 24, 0], [24, -24, 0], [-24, 24, 0], [-20, -20, TIP], [20, 20, TIP], [0, 0, TIP + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(20, 40), disc(18.5, 40), 0, 5));
  const foot = solid(g);
  const rest = (k) => (k === FAV ? 3 : 0);
  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g), paper = mk("path", { class: "sil" }, grp), edge = mk("path", { class: "nf lo" }, grp), post = solid(grp);
    items.push({ k, paper, edge, post, z: tween(rest(k)), th: tween(ANG[k]), last: NaN, lt: NaN });
  }
  const zAt = (k, now) => Z0 + k * GAP + tval(items[k].z, now);

  function draw(now) {
    put(foot, prism(P, front, disc(1.1, 12), disc(0.6, 12), 5, zAt(0, now)));
    items.forEach((it, k) => {
      const z = zAt(k, now), th = tval(it.th, now);
      if (z !== it.last || th !== it.lt) {
        it.last = z; it.lt = th;
        const ring = slip((th * Math.PI) / 180, OFF[k]);
        it.paper.setAttribute("d", poly(ringAt(P, ring, z)));
        it.edge.setAttribute("d", poly(ringAt(P, ring, z - 0.6)));
      }
      const top = k < N - 1 ? zAt(k + 1, now) : TIP;
      put(it.post, prism(P, front, disc(1.1, 12), disc(0.6, 12), z, top));
    });
  }

  const L = register(stage, (_dt, now) => {
    draw(now);
    return items.some((it) => !tdone(it.z, now) || !tdone(it.th, now));
  });
  bag.add(L.unregister);
  items.forEach((it) => it.edge.parentNode.insertBefore(it.edge, it.paper));

  function hit([sx, sy]) {
    for (let k = N - 1; k >= 0; k--) {
      const [x, y] = unproj(C, sx, sy, Z0 + k * GAP);
      if (Math.hypot(x, y) < 17) return k;
    }
    return -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), d = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(it.z, a < 0 ? rest(k) : dd === 0 ? LIFT : dd === 1 ? 2 : 0, now, d);
      tset(it.th, a === k ? 0 : ANG[k], now, d);
      it.paper.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "slip " + (a + 1);
    L.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "receiptspike",
  means: "Paper slips pierced on a spike: the slip under the pointer rides up and turns square, and its neighbours lift after it.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[155, 217], [200, 162], [240, 125], null],
  mount,
});

buffetwarmer.code:
/**
 * Chafing dish: a rounded pan on a low stand with a fuel cup under it and
 * a hinged lid along its back edge. The nearer the pointer comes to the
 * pan's front, the further the lid swings open. At rest the lid stands
 * slightly ajar, bright.
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, rrect, unproj, clamp, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 84, D = 52, Z0 = 14, Z1 = 30, LT = 5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-4, -4, 0], [W + 4, D + 4, 0], [W + 4, -4, 0], [-4, D + 4, 0], [0, -6, Z1 + D + 4], [W, -6, Z1 + D + 4]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-4, -4, W + 4, D + 4, 8, 2);
  put(solid(g), prism(P, front, br, bi, 0, 3));
  // four legs as thin posts, then the fuel cup, then the pan
  for (const [x, y] of [[4, 4], [W - 4, 4], [4, D - 4]]) mk("path", { d: open([P(x, y, 3), P(x, y, Z0)]), class: "nf lo" }, g);
  const [cr, ci] = rings(W / 2 - 9, D / 2 - 9, W / 2 + 9, D / 2 + 9, 9, 1.5);
  put(solid(g), prism(P, front, cr, ci, 3, 9));
  mk("path", { d: open([P(W - 4, D - 4, 3), P(W - 4, D - 4, Z0)]), class: "nf lo" }, g);
  const [pr, pi] = rings(0, 0, W, D, 10, 2);
  put(solid(g), prism(P, front, pr, pi, Z0, Z1));
  const lidG = solid(g);
  const outer = rrect(2, 2, W - 2, D - 2, 9, 6), inner = rrect(5, 5, W - 5, D - 5, 6, 6);

  const ang = spring(0.22);
  let last = NaN;
  function at(ring, a, lift) {
    const c = Math.cos(a), s = Math.sin(a);
    return ring.map((q) => P(q.u, q.v * c - lift * s, Z1 + q.v * s + lift * c));
  }
  function draw() {
    if (ang.x === last) return;
    last = ang.x;
    const a = ang.x * 1.75;
    lidG.sil.setAttribute("d", poly(hull(at(outer, a, 0).concat(at(outer, a, LT), at(inner, a, LT + 3)))));
    lidG.cr.setAttribute("d", open(at(inner, a, LT + 3)) + "Z");
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(); return m; });
  bag.add(B.unregister);
  draw();
  lidG.sil.classList.add("hi");

  function rest() { ang.t = 0.22; read.textContent = "rest"; B.wake(); }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, Z1);
    if (x < -30 || x > W + 30 || y < -20) return rest();
    const d = Math.abs(y - D), R = 30 + reach;
    const t = d > R * 1.5 ? 0.09 : d > R ? 0.31 : 1 - 0.69 * (d / R);
    ang.t = clamp(t, 0.09, 1);
    read.textContent = Math.round(ang.t * 100) + "%";
    B.wake();
  }
  rest();
  bag.add(pointer(stage, { move, leave: rest }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "buffetwarmer",
  means: "A chafing dish on its stand: the nearer the pointer to the pan's front, the wider its hinged lid swings open.",
  rules: [3, 5, 8, 9],
  range: [0, 20, 50],
  tour: [[238, 176], [209, 190], [162, 213], null],
  mount,
});

keycardrack.code:
/**
 * Bell desk: a reception counter with a raised back ledge, a guest book
 * lying open on the top and a call bell beside it. The nearer the pointer
 * to the bell, the further its plunger presses and its dome dips. At rest
 * the plunger stands up, the dome bright.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, unproj, clamp, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 110, D = 40, H = 34, BXc = 78, BYc = 22, BR = 15;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, -10, 0], [W, D, 0], [W, -10, 0], [0, D, 0], [0, -10, H + 14], [W, -10, H + 14], [BXc, BYc, H + 44]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [lr, li] = rings(0, -10, W, 0, 4, 1.2);
  put(solid(g), prism(P, front, lr, li, 0, H + 10));
  const [cr, ci] = rings(0, 0, W, D, 6, 2);
  put(solid(g), prism(P, front, cr, ci, 0, H));
  // a guest book lying open: two thin plates meeting at the spine
  const [kr, ki] = rings(14, 10, 54, 32, 2, 1);
  put(solid(g), prism(P, front, kr, ki, H, H + 2));
  mk("path", { d: open([P(34, 10, H + 2), P(34, 32, H + 2)]), class: "nf lo" }, g);
  put(solid(g), prism(P, front, disc(BXc, BYc, BR + 2), disc(BXc, BYc, BR), H, H + 2.5));
  const dome = solid(g), plunger = mk("path", { class: "nf" }, g);

  const p = spring(0.1);
  let last = NaN;
  function draw() {
    if (p.x === last) return;
    last = p.x;
    const z0 = H + 2.5 + 5 - 5 * p.x, pts = [];
    for (let i = 0; i <= 6; i++) { const t = (i / 6) * Math.PI / 2; pts.push(...ringAt(P, disc(BXc, BYc, BR * Math.cos(t), 28), z0 + BR * 0.85 * Math.sin(t))); }
    dome.sil.setAttribute("d", poly(hull(pts)));
    dome.cr.setAttribute("d", poly(ringAt(P, disc(BXc, BYc, BR - 1.2, 32), z0 + 1)));
    const top = z0 + BR * 0.85, h = 14 - 11 * p.x;
    plunger.setAttribute("d", poly(hull(ringAt(P, disc(BXc, BYc, 1.2, 12), top).concat(ringAt(P, disc(BXc, BYc, 2.8, 16), top + h), ringAt(P, disc(BXc, BYc, 2.8, 16), top + h + 1.5)))));
  }
  const B = register(stage, (dt) => { const m = stepS(p, dt); draw(); return m; });
  bag.add(B.unregister);
  draw();
  dome.sil.classList.add("hi");

  function rest() { p.t = 0.1; read.textContent = "rest"; B.wake(); }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    const d = Math.hypot(x - BXc, y - BYc), R = 24 + reach;
    if (d > R * 2) return rest();
    p.t = clamp(d > R ? 0.31 - 0.22 * (d - R) / R : 1 - 0.69 * d / R, 0.09, 1);
    read.textContent = "ding " + Math.round(p.t * 100);
    B.wake();
  }
  rest();
  bag.add(pointer(stage, { move, leave: rest }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "keycardrack",
  means: "A reception desk with a call bell: the nearer the pointer to the bell, the further its plunger presses and its dome dips.",
  rules: [3, 5, 8, 9],
  range: [0, 16, 40],
  tour: [[131, 124], [186, 151], [222, 172], null],
  mount,
});

menuholder.code:
/**
 * Menu stand: a table top with a round weighted holder and a tall menu card
 * standing in its clip. The card turns on its clip to face the pointer, as
 * far as its stop allows. At rest it stands a little turned, bright.
 */
const {
  Cam, circ, fit, facing, fillet, hull, open, poly, prism, proj, rings, unproj, clamp, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const T = 90, CX = 45, CY = 45, HW = 22, HZ = 64, Z0 = 12;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[0, 0, 0], [T, T, 0], [T, 0, 0], [0, T, 0], [CX - HW, CY + HW, Z0 + HZ], [CX + HW, CY - HW, Z0 + HZ]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(0, 0, T, T, 10, 2);
  put(solid(g), prism(P, front, tr, ti, 0, 4));
  put(solid(g), prism(P, front, disc(CX, CY, 12), disc(CX, CY, 10), 4, 9));
  const back = mk("path", { class: "nf lo" }, g);
  const card = mk("path", { class: "sil hi" }, g), clip = mk("path", { class: "nf" }, g);

  const ang = spring(rad(-20));
  let last = NaN;
  function rad(d) { return d * Math.PI / 180; }
  function face(th, off) {
    const c = Math.cos(th), s = Math.sin(th), nx = -s * off, ny = c * off;
    const pt = (u, z) => P(CX + c * u + nx, CY + s * u + ny, z);
    return [pt(-HW, Z0), pt(HW, Z0), pt(HW, Z0 + HZ), pt(-HW, Z0 + HZ)];
  }
  function draw() {
    if (ang.x === last) return;
    last = ang.x;
    const a = face(ang.x, 1.2), b = face(ang.x, -1.2);
    card.setAttribute("d", poly(hull(fillet(a, [3, 3, 3, 3]).concat(fillet(b, [3, 3, 3, 3])))));
    back.setAttribute("d", poly(fillet(b, [3, 3, 3, 3])));
    const c = Math.cos(ang.x), s = Math.sin(ang.x), q = (u, n, z) => P(CX + c * u - s * n, CY + s * u + c * n, z);
    clip.setAttribute("d", poly(hull([q(-6, -3, 9), q(6, -3, 9), q(6, 3, 9), q(-6, 3, 9), q(-6, -3, 17), q(6, -3, 17), q(6, 3, 17), q(-6, 3, 17)])) + " " + open([q(-6, 3.2, 17), q(6, 3.2, 17)]).replace(/^/, ""));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(); return m; });
  bag.add(B.unregister);
  draw();

  function rest() { ang.t = rad(-20); read.textContent = "rest"; B.wake(); }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    const dx = x - CX, dy = y - CY;
    if (Math.hypot(dx, dy) < 4) return;
    // the card's face normal is (-sin, cos): turn it toward the pointer, clamped to the stop
    let th = Math.atan2(dy, dx) - Math.PI / 2;
    th = Math.atan2(Math.sin(th), Math.cos(th));
    const lim = rad(30 + reach);
    ang.t = clamp(th, -lim, lim);
    read.textContent = Math.round(ang.t * 180 / Math.PI) + "°";
    B.wake();
  }
  rest();
  bag.add(pointer(stage, { move, leave: rest }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "menuholder",
  means: "A menu card standing in a round table holder: the card turns on its clip to face the pointer, up to its stop.",
  rules: [3, 5, 8, 9],
  range: [0, 30, 60],
  tour: [[321, 198], [267, 252], [79, 198], null],
  mount,
});

microphones.code:
/**
 * Mic stand: a round base, a pole, and a boom with a counterweight and a mic
 * on its end. The pointer is the singer: the boom swings round on a spring to
 * aim the mic at it. At rest it is turned a little off-axis, the mic bright.
 * The slider is the boom's reach.
 *
 * The hit is on the ground plane, which never moves; the aim is its angle
 * about the pole. Paint order flips the arm's two ends round the pole.
 */
const {
  Cam, circ, clamp, facing, fit, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const H = 74, RB = 20, REST = -0.6, BACK = 14;
const wrap = (a) => Math.atan2(Math.sin(a), Math.cos(a));
const at = (ring, x, y) => ring.map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const rot = (ring, a) => { const c = Math.cos(a), s = Math.sin(a); return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c })); };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let BL = value, over = null;
  const C = Cam(45, 0.5, 2.5);
  const ext = [];
  for (let k = 0; k < 16; k++) { const a = (k / 16) * Math.PI * 2; ext.push([Math.cos(a) * 66, Math.sin(a) * 62, H + 4], [Math.cos(a) * 62, Math.sin(a) * 62, H - 16], [Math.cos(a) * RB, Math.sin(a) * RB, 0]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const cyl = (el, r, b, x, y, z0, z1) => put(el, prism(P, front, at(circ(r, 24), x, y), at(circ(r - b, 24), x, y), z0, z1));

  cyl(solid(g), RB, 1.6, 0, 0, 0, 3);
  cyl(solid(g), 7, 1, 0, 0, 3, 6);
  const back = mk("g", {}, g), pole = mk("g", {}, g), fore = mk("g", {}, g);
  cyl(solid(pole), 1.7, 0.6, 0, 0, 6, H - 2);
  const weight = solid(back), boom = solid(fore), mic = solid(fore), knob = solid(fore);
  const grille = mk("path", { class: "nf lo" }, mic.g);
  const yaw = spring(REST, { eps: 0.002 });
  let drawn = NaN, len = BL;

  function draw() {
    const a = yaw.x;
    if (a === drawn && len === BL) return;
    drawn = a; len = BL;
    const c = Math.cos(a), s = Math.sin(a);
    const [o, i] = rings(-BACK, -1.3, BL, 1.3, 1.3, 0.5);
    put(boom, prism(P, front, rot(o, a), rot(i, a), H, H + 2.6));
    cyl(weight, 4.2, 0.9, -c * BACK, -s * BACK, H - 2, H + 5);
    cyl(knob, 3, 0.8, 0, 0, H - 3, H + 3.6);
    cyl(mic, 4.6, 1, c * BL, s * BL, H - 15, H + 1);
    const ring = at(circ(4.6, 24), c * BL, s * BL), pts = ring.filter(front).map((q) => P(q.u, q.v, H - 9));
    grille.setAttribute("d", pts.length ? "M" + pts.map((p) => p.join(" ")).join("L") : "");
    // the end nearer the viewer paints over the pole
    if (c + s > 0) g.append(back, pole, fore);
    else g.append(fore, pole, back);
  }
  const B = register(stage, (dt) => { const m = stepS(yaw, dt); draw(); return m; });
  bag.add(B.unregister);

  function retarget() {
    const goal = over ? Math.atan2(over[1], over[0]) : REST;
    yaw.t = yaw.x + wrap(goal - yaw.x);
    mic.sil.classList.toggle("hi", true);
    const deg = Math.round((goal * 180) / Math.PI + 360) % 360;
    read.textContent = over ? "aim " + deg + "°" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      over = r > 6 && r < 120 ? [x, y] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { BL = v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "microphones",
  means: "A mic on a boom stand: the boom swings round its pole to aim the mic at the pointer.",
  rules: [1, 3, 5, 9],
  range: [30, 46, 60],
  tour: [[94, 269], [244, 229], [271, 313], null],
  mount,
});

mixingconsole.code:
/**
 * Fader bank: eight channel faders in a sloped desk. The pointer rides the
 * bank: the fader under it slides to the pointer, its neighbours follow less
 * the farther they are, each on its own spring. At rest the faders sit in an
 * uneven mix, one bright. The slider is the reach, in channels.
 *
 * The hit is on the desk's top plane, which never moves; channel by world x.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 8, W = 13, Y0 = 8, Y1 = 64, L = 72, CW = 4.8, CL = 4, CH = 7;
const X1 = N * W, REST = [44, 30, 36, 22, 50, 40, 28, 46], FAV = 3;
const falloff = (u) => (u <= 0 ? 1 : u <= 1 ? 1 - u * 0.8 : 0.2 * Math.max(0, 1.6 - u));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value, over = null;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-5, -16, -6], [X1 + 5, L + 4, -6], [X1 + 5, -16, -6], [-5, L + 4, -6], [-5, -16, 16], [X1 + 5, -16, 16]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1, el = solid(g)) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(el, prism(P, front, o, i, z0, z1)); return el; };

  // the desk, a meter bridge behind it, and the slots
  const desk = block(-5, -4, X1 + 5, L + 4, 3, 1.4, -6, 0);
  block(-5, -16, X1 + 5, -6, 2.5, 1.2, 0, 16);
  let d = "";
  for (let i = 0; i < N; i++) {
    const cx = i * W + W / 2;
    d += seg(P(cx, Y0 - 2, 0), P(cx, Y1 + 2, 0));
    for (let t = 0; t <= 4; t++) d += seg(P(cx + 4, Y0 + t * 14, 0), P(cx + 5.6, Y0 + t * 14, 0));
  }
  mk("path", { class: "nf lo", d }, desk.g);

  const caps = [];
  for (let i = 0; i < N; i++) caps.push({ i, cx: i * W + W / 2, rest: REST[i], sp: spring(REST[i], { eps: 0.05 }), el: solid(g), drawn: NaN });

  function draw(c) {
    const y = clamp(c.sp.x, Y0, Y1);
    if (y === c.drawn) return;
    c.drawn = y;
    block(c.cx - CW, y - CL, c.cx + CW, y + CL, 1.2, 0.8, 0, CH, c.el);
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const c of caps) { if (stepS(c.sp, dt)) m = true; draw(c); }
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    const a = over ? clamp(Math.floor(over[0] / W), 0, N - 1) : -1;
    for (const c of caps) {
      if (a < 0) c.sp.t = c.rest;
      else c.sp.t = clamp(c.rest + (over[1] - c.rest) * falloff(Math.abs(c.i - a) / RAD), Y0, Y1);
      c.el.sil.classList.toggle("hi", a < 0 ? c.i === FAV : c.i === a);
    }
    read.textContent = a < 0 ? "rest" : "ch " + (a + 1) + " · " + Math.round(100 * (Y1 - clamp(over[1], Y0, Y1)) / (Y1 - Y0));
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      over = x > -4 && x < X1 + 4 && y > -4 && y < L + 4 ? [clamp(x, 0, X1 - 0.01), y] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "mixingconsole",
  means: "A bank of eight faders in a desk: the one under the pointer slides to it, its neighbours follow by distance.",
  rules: [1, 3, 5, 9],
  range: [0.5, 1.5, 4],
  tour: [[103, 165], [214, 158], [284, 191], null],
  mount,
});

volleyball.code:
/**
 * Volleyball net: a beach court with a net strung between two posts and a
 * ball hanging over it. The pointer picks a panel of the net by where it
 * stands: the ball floats over that panel, and the net bows back from it,
 * the bow spreading outward, staggered. At rest the ball hangs over the
 * second panel, bright, and the net sags unevenly. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, spring, stepS, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, open, seg,
} = HL;

const N = 5, X0 = 6, X1 = 114, W = (X1 - X0) / N, NZ0 = 16, NZ1 = 34, R = 6, FAV = 1;
const REST = [0, 1.5, 3, 2, 1, 0];
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-4, -34, 0], [124, 34, 0], [124, -34, 0], [-4, 34, 0], [X0, 0, 62], [X1, 0, 62], [X0, 0, 40], [X1, 0, 40]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-4, -34, 124, 34, 4, 2);
  put(solid(g), prism(P, front, cr, ci, 0, 3));
  // the court line under the net
  mk("path", { d: open([P(-2, 0, 3), P(122, 0, 3)]), class: "dash" }, g);
  const shadow = mk("ellipse", { class: "dot off", rx: 6, ry: 3 }, g);
  for (const x of [X0 - 2, X1 + 2]) {
    const [pr, pi] = rings(x - 1.6, -1.6, x + 1.6, 1.6, 0.6, 0.5);
    put(solid(g), prism(P, front, pr, pi, 3, NZ1 + 3));
  }
  const panels = [];
  for (let k = 0; k < N; k++) {
    const plate = mk("path", {}, g), mesh = mk("path", { class: "nf lo" }, g), tape = mk("path", { class: "nf sil" }, g);
    panels.push({ plate, mesh, tape });
  }
  const bow = REST.map((d) => tween(d));
  const ball = mk("path", { class: "sil" }, g), seams = mk("path", { class: "nf lo" }, g);
  const bx = spring(X0 + W * (FAV + 0.5)), bz = spring(48);
  let lastKey = "";

  function draw(now) {
    const d = bow.map((t) => tval(t, now));
    const key = d.map((v) => v.toFixed(2)).join() + bx.x.toFixed(2) + bz.x.toFixed(2);
    if (key === lastKey) return;
    lastKey = key;
    panels.forEach((p, k) => {
      const xa = X0 + k * W, xb = xa + W, ya = d[k], yb = d[k + 1];
      p.plate.setAttribute("d", poly([P(xa, ya, NZ0), P(xb, yb, NZ0), P(xb, yb, NZ1), P(xa, ya, NZ1)]));
      let m = "";
      for (let i = 1; i < 4; i++) { const t = i / 4, x = xa + W * t, y = ya + (yb - ya) * t; m += seg(P(x, y, NZ0), P(x, y, NZ1 - 3)); }
      for (let j = 1; j < 3; j++) { const z = NZ0 + (NZ1 - 3 - NZ0) * j / 3; m += seg(P(xa, ya, z), P(xb, yb, z)); }
      p.mesh.setAttribute("d", m);
      p.tape.setAttribute("d", poly([P(xa, ya, NZ1 - 3), P(xb, yb, NZ1 - 3), P(xb, yb, NZ1), P(xa, ya, NZ1)]));
    });
    const pts = [];
    for (let i = -3; i <= 3; i++) { const t = (i / 3) * (Math.PI / 2); pts.push(...ringAt(P, disc(bx.x, 0, R * Math.cos(t) + 0.01), bz.x + R * Math.sin(t))); }
    ball.setAttribute("d", poly(hull(pts)));
    seams.setAttribute("d", open(ringAt(P, disc(bx.x, 0, R * 0.98, 20), bz.x).slice(0, 11)) + seg(P(bx.x, 0, bz.x - R * 0.9), P(bx.x, 0, bz.x + R * 0.9)));
    const s = P(bx.x, 0, 3);
    shadow.setAttribute("cx", s[0]); shadow.setAttribute("cy", s[1]);
  }

  const B = register(stage, (dt, now) => {
    const m1 = stepS(bx, dt), m2 = stepS(bz, dt);
    draw(now);
    return m1 || m2 || bow.some((t) => !tdone(t, now));
  });
  bag.add(B.unregister);

  const mids = panels.map((_, k) => P(X0 + W * (k + 0.5), 0, (NZ0 + NZ1) / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    bow.forEach((t, j) => {
      const dd = Math.abs(j - (a + 0.5)), v = a < 0 ? REST[j] : j === 0 || j === N ? 0 : Math.max(1, 7 - dd * 3.5);
      tset(t, v, now, from < 0 ? 0 : Math.abs(j - (from + 0.5)) * stag);
    });
    bx.t = X0 + W * ((a < 0 ? FAV : a) + 0.5);
    bz.t = a < 0 ? 48 : 54;
    ball.classList.toggle("hi", a < 0);
    panels.forEach((p, k) => p.tape.classList.toggle("hi", k === a));
    read.textContent = a < 0 ? "rest" : "panel " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "volleyball",
  means: "A beach volleyball net between two posts: the ball floats over the panel under the pointer, and the net bows back from it.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[235, 180], [130, 127], [270, 197], null],
  mount,
});

roofbox.code:
/**
 * Roof box: a car with two crossbars on its roof and a long luggage box
 * clamped to them. The pointer picks a bag inside by where it stands: the
 * lid lifts and that bag rises out of the box, the bags beside it rise a
 * little, staggered from it. At rest the lid stands ajar and one bag peeks
 * out, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, BZ = 46, BT = 53, LID = 6, FAV = 1;
const BX = [27, 50, 73];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-2, -2, -4], [102, 46, -4], [102, -2, -4], [-2, 46, -4], [14, 8, BT + LID + 26], [86, 36, BT + LID + 26]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const nearY = P(50, 0, 0)[1] > P(50, 44, 0)[1] ? -0.6 : 44.6;
  const wheel = (x) => { const pts = []; for (let i = 0; i < 32; i++) { const a = (i / 32) * 2 * Math.PI; pts.push(P(x + 9 * Math.cos(a), nearY, 5 + 9 * Math.sin(a))); } return pts; };
  const [br, bi] = rings(0, 0, 100, 44, 8, 2);
  put(solid(g), prism(P, front, br, bi, 2, 24));
  for (const x of [22, 78]) { mk("path", { d: poly(wheel(x)) }, g); }
  const [cr, ci] = rings(20, 4, 80, 40, 9, 2);
  put(solid(g), prism(P, front, cr, ci, 24, 40));
  for (const x of [32, 68]) { const [xr, xi] = rings(x - 1.5, 1, x + 1.5, 43, 0.6, 0.5); put(solid(g), prism(P, front, xr, xi, 40, 42.5)); }
  const [sr, si] = rings(12, 8, 88, 36, 12, 2);
  put(solid(g), prism(P, front, sr, si, 42.5, BT));

  const items = BX.map((x, k) => {
    const s = solid(g);
    return { k, x, s, z: tween(k === FAV ? 7 : 0), last: NaN };
  });
  const lid = solid(g);
  const lz = tween(LID);
  let lastLid = NaN;

  function draw(now) {
    for (const it of items) {
      const h = tval(it.z, now);
      if (h === it.last) continue;
      it.last = h;
      if (h < 0.4) { put(it.s, { sil: "", crease: "" }); continue; }
      const [r, i] = rings(it.x - 8, 12, it.x + 8, 32, 3, 1.2);
      put(it.s, prism(P, front, r, i, BT, BT + h));
    }
    const l = tval(lz, now);
    if (l !== lastLid) { lastLid = l; put(lid, prism(P, front, sr, si, BT + l, BT + l + 6)); }
  }

  const B = register(stage, (_dt, now) => {
    draw(now);
    return !tdone(lz, now) || items.some((it) => !tdone(it.z, now));
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 22, BT));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    tset(lz, a < 0 ? LID : 24, now, 0);
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? 7 : 0) : dd === 0 ? 16 : 7;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bag " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "roofbox",
  means: "A luggage box on a car's roof bars: the lid lifts and the bag under the pointer rises out, its neighbours rising a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[236, 152], [164, 116], [200, 134], null],
  mount,
});

bracelets.code:
/**
 * Bangles: a jewellery stand, a rod between two posts on a slab, with five
 * bangles of different sizes hanging from it. The pointer picks a bangle by
 * where it stands: it swings out on the rod, and the bangles beside it swing
 * a little, staggered from it. At rest one bangle hangs swung out, bright,
 * and the others hang unevenly. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, poly, prism, proj, rad, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 12, X = (N + 1) * STEP, RZ = 36, FAV = 2;
const RAD = [11, 12.5, 10, 12, 11.5], REST = [-5, 4, 26, 2, -3];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.2);
  fit(C, [[-6, -18, 0], [X + 6, 18, 0], [X + 6, -18, 0], [-6, 18, 0], [-6, 0, RZ + 3], [X + 6, 0, RZ + 3], [X / 2, 14, RZ - 2], [X / 2, -14, RZ - 2]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-6, -18, X + 6, 18, 5, 2);
  put(solid(g), prism(P, front, br, bi, 0, 4));
  for (const x of [-1, X + 1]) { const [pr, pi] = rings(x - 1.6, -1.6, x + 1.6, 1.6, 0.6, 0.5); put(solid(g), prism(P, front, pr, pi, 4, RZ + 2)); }
  const [rr, ri] = rings(-2, -0.8, X + 2, 0.8, 0.4, 0.3);
  put(solid(g), prism(P, front, rr, ri, RZ - 0.8, RZ + 0.8));
  const items = [];
  for (let k = 0; k < N; k++) items.push({ k, x: (k + 1) * STEP, R: RAD[k], el: mk("path", { class: "sil" }, g), a: tween(REST[k]), last: NaN });

  function draw(now) {
    for (const it of items) {
      const f = tval(it.a, now);
      if (f === it.last) continue;
      it.last = f;
      const p = rad(f), cy = (it.R - 1) * Math.sin(p), cz = RZ - (it.R - 1) * Math.cos(p);
      const outer = [], inner = [];
      for (let i = 0; i < 40; i++) {
        const t = (i / 40) * 2 * Math.PI, c = Math.cos(t), s = Math.sin(t);
        outer.push(P(it.x, cy + it.R * c, cz + it.R * s));
        inner.push(P(it.x, cy + (it.R - 2.2) * c, cz + (it.R - 2.2) * s));
      }
      it.el.setAttribute("d", poly(outer) + poly(inner.reverse()));
    }
  }

  const B = register(stage, (_dt, now) => { draw(now); return items.some((it) => !tdone(it.a, now)); });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 0, RZ - it.R));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), f = a < 0 ? REST[k] : dd === 0 ? 40 : dd === 1 ? 14 : 4;
      tset(it.a, f, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.el.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bangle " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "bracelets",
  means: "Bangles hanging from a jewellery stand's rod: the bangle under the pointer swings out, and the bangles beside it swing a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[227, 153], [146, 115], [254, 170], null],
  mount,
