bongos.code:
/**
 * Bongos: a pair of tapered drums joined by a bridge block, the low drum
 * larger than the high one. The pointer picks a drum by where it stands:
 * it tips up off the ground, its head goes bright and two tone rings spread
 * across the skin toward the rim, while the other drum settles and its rings
 * draw in; the bridge tilts between them. At rest the low drum is a little
 * raised, its head bright. The slider is how far the answer reaches.
 *
 * The pattern: one of a few in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, proj, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const DRUMS = [
  { x: 0, y: 0, R: 22, H: 36, name: "low" },
  { x: 50, y: 0, R: 17, H: 32, name: "high" },
];
const FAV = 0, LIFT = 14;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[-24, -24, 0], [69, 19, 0], [-24, 24, 0], [24, 24, 0], [-24, 24, 36 + LIFT], [69, -19, 32 + LIFT], [-22, -22, 36 + LIFT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  function drum(d, grp) {
    const s = solid(grp), lugs = mk("path", { class: "nf lo" }, grp);
    const head = mk("path", { class: "nf" }, grp);
    const r1 = mk("path", { class: "nf lo" }, grp), r2 = mk("path", { class: "nf lo" }, grp);
    return { ...d, s, lugs, head, r1, r2, a: tween(0), z: 0 };
  }
  function shell(d, z) {
    const foot = disc(d.x, d.y, d.R * 0.72), top = disc(d.x, d.y, d.R), inner = disc(d.x, d.y, d.R - 1.6);
    put(d.s, { sil: poly(hull(ringAt(P, foot, z).concat(ringAt(P, top, z + d.H)))), crease: open(ringAt(P, run(inner, front), z + d.H - 1.4)) });
    // a band of tension lugs round the shell, just under the rim
    let lg = "";
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * Math.PI * 2 + 0.3, ca = Math.cos(a), sa = Math.sin(a);
      if (!front({ nu: ca, nv: sa })) continue;
      const rr = d.R * 0.95;
      lg += open([P(d.x + ca * rr, d.y + sa * rr, z + d.H - 4), P(d.x + ca * rr * 0.86, d.y + sa * rr * 0.86, z + d.H - 15)]);
    }
    d.lugs.setAttribute("d", lg);
    d.head.setAttribute("d", poly(ringAt(P, top, z + d.H)));
  }

  const A = drum(DRUMS[0], mk("g", {}, g));
  // the bridge block between the shells
  const bx0 = 18, bx1 = 37, by = 4;
  const bf = [[bx0, -by], [bx1, -by], [bx1, by], [bx0, by]];
  const bs = solid(mk("g", {}, g));
  function block(za, zb) {
    const zz = (x) => za + ((zb - za) * (x - bx0)) / (bx1 - bx0);
    put(bs, {
      sil: poly(hull(bf.map(([x, y]) => P(x, y, 12 + zz(x))).concat(bf.map(([x, y]) => P(x, y, 22 + zz(x)))))),
      crease: open([P(bx0, by - 1, 21 + za), P(bx1, by - 1, 21 + zb)]),
    });
  }
  const B = drum(DRUMS[1], mk("g", {}, g));
  const items = [A, B];

  let last = "";
  function draw(now) {
    const v = items.map((it) => tval(it.a, now)), key = v.join() + reach;
    if (key === last) return;
    last = key;
    items.forEach((it, k) => {
      const z = LIFT * Math.max(0, v[k] - 0.4) / 0.6 * reach;
      it.z = z;
      shell(it, z);
      const kk = 0.25 + 0.75 * v[k] * reach;
      it.r1.setAttribute("d", poly(ringAt(P, disc(it.x, it.y, (it.R - 3) * kk), z + it.H)));
      it.r2.setAttribute("d", poly(ringAt(P, disc(it.x, it.y, (it.R - 3) * kk * 0.5), z + it.H)));
    });
    block(A.z, B.z);
  }

  const L = register(stage, (_dt, now) => {
    draw(now);
    return items.some((it) => !tdone(it.a, now));
  });
  bag.add(L.unregister);

  const mids = items.map((it) => P(it.x, it.y, it.H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 70 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    items.forEach((it, k) => {
      tset(it.a, a < 0 ? (k === FAV ? 0.6 : 0.1) : k === a ? 1 : 0, now, 0);
      it.head.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : items[a].name;
    L.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; L.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "bongos",
  means: "A pair of bongos: the drum under the pointer tips up with its head lit, tone rings spreading over the skin.",
  rules: [1, 4, 5, 6],
  range: [0.3, 1, 1],
  tour: [[160, 203], [262, 240], [161, 204], null],
  mount,
});

harmonicas.code:
/**
 * Harmonica case: an open case, its lid standing up behind, holding five
 * harmonicas side by side, each with its row of holes along the near side.
 * The pointer picks a harmonica by where it stands: it lifts out of the
 * case and the ones beside it rise a little, staggered from it. At rest one
 * harmonica sits half lifted, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 14, W = 9, LEN = 44, HH = 7, LIFT = 26, FAV = 2, CZ = 5;
const X1 = (N - 1) * STEP + W + 8;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-4, -4, 0], [X1, LEN + 8, 0], [X1, -4, 0], [-4, LEN + 8, 0], [-8, -4, 42], [-8, LEN + 8, 42], [X1 - 8, LEN + 4, CZ + HH + LIFT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the lid, standing up along the back edge
  const [lr, li] = rings(-8, -4, -4, LEN + 8, 1.6, 0.8);
  put(solid(g), prism(P, front, lr, li, 2, 42));
  const [cr, ci] = rings(-4, -4, X1, LEN + 8, 4, 2);
  put(solid(g), prism(P, front, cr, ci, 0, CZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 4 + k * STEP, grp = mk("g", {}, g);
    const s = solid(grp), holes = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, grp, s, holes, z: tween(k === FAV ? LIFT * 0.5 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = CZ + lift, [r, i] = rings(it.x, 2, it.x + W, 2 + LEN, 2, 1);
    put(it.s, prism(P, front, r, i, z0, z0 + HH));
    // the row of holes along the near side
    let d = "";
    for (let h = 0; h < 10; h++) {
      const y = 6 + h * ((LEN - 8) / 9);
      d += open([P(it.x + W, y, z0 + 2.4), P(it.x + W, y + 1.6, z0 + 2.4), P(it.x + W, y + 1.6, z0 + 4.4), P(it.x + W, y, z0 + 4.4), P(it.x + W, y, z0 + 2.4)]);
    }
    it.holes.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + W / 2, 2 + LEN / 2, CZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.5 : 0) : dd === 0 ? LIFT : dd === 1 ? 7 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "key " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "harmonicas",
  means: "An open case of five harmonicas: the one under the pointer lifts out, its neighbours rise a little, staggered.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[158, 164], [232, 201], [257, 214], null],
  mount,
});

ampstack.code:
/**
 * Speaker stack: three cabinets stacked on a low riser, the bottom one
 * widest, each with its cones on the front face. The pointer picks a
 * cabinet by height: it slides out toward the viewer and the cabinets beside
 * it slide a little, staggered from it. At rest the top cabinet stands a
 * little out, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single column (riffle, stood up).
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const CABS = [
  { w: 64, d: 30, h: 30, cones: [[16, 15, 10], [48, 15, 10]] },
  { w: 58, d: 28, h: 26, cones: [[15, 13, 8], [43, 13, 8]] },
  { w: 50, d: 26, h: 22, cones: [[25, 11, 8]] },
];
const OUT = 14, FAV = 2, RZ = 5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-6, -6, 0], [70, -6, 0], [-6, 36 + OUT, 0], [70, 36 + OUT, 0], [0, 0, RZ + 78], [64, 30 + OUT, RZ + 78]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [rr, ri] = rings(-6, -6, 70, 36, 3, 1.5);
  put(solid(g), prism(P, front, rr, ri, 0, RZ));

  let z = RZ;
  const items = CABS.map((c, k) => {
    const x0 = (64 - c.w) / 2, grp = mk("g", {}, g), s = solid(grp), cp = mk("path", { class: "nf lo" }, grp);
    const it = { ...c, k, x0, z0: z, grp, s, cp, o: tween(k === FAV ? OUT * 0.5 : 0), last: NaN };
    z += c.h;
    return it;
  });

  function draw(it, o) {
    if (o === it.last) return;
    it.last = o;
    const y0 = (30 - it.d) / 2 + o, y1 = y0 + it.d, [r, i] = rings(it.x0, y0, it.x0 + it.w, y1, 3, 1.4);
    put(it.s, prism(P, front, r, i, it.z0, it.z0 + it.h));
    // cones on the front face, each a ring and its dust cap
    let d = "";
    for (const [cx, cz, R] of it.cones) {
      for (const rad of [R, R * 0.62, R * 0.2]) {
        const pts = [];
        for (let t = 0; t < 28; t++) { const a = (t / 28) * Math.PI * 2; pts.push(P(it.x0 + cx + rad * Math.cos(a), y1, it.z0 + cz + rad * Math.sin(a))); }
        d += poly(pts);
      }
    }
    it.cp.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.o, now)); if (!tdone(it.o, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x0 + it.w / 2, 30, it.z0 + it.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][0] - sx) < 110 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), o = a < 0 ? (k === FAV ? OUT * 0.5 : 0) : dd === 0 ? OUT : dd === 1 ? 4 : 0;
      tset(it.o, o, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "cab " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "ampstack",
