spicecarousel.code:
/**
 * Spice carousel: a round turntable base, a centre post with a carry knob,
 * and six capped jars standing round it. The pointer picks the jar nearest
 * it on the turntable: that jar lifts clear, its neighbours rise a little,
 * staggered round the ring. At rest the jars sit unevenly, one bright.
 *
 * The pattern: one of many on a ring; the hit is each jar's rest centre on a
 * fixed plane through the jars' middles.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, rrect, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, RB = 30, RJ = 19, JR = 6, JH = 14, CH = 4, BASE = 4, POST = 34, LIFT = 13, BUMP = 4;
const REST = [1, 0, 3, 0.5, 2, 0], FAV = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.6);
  fit(C, [[-RB, -RB, 0], [RB, RB, 0], [RB, -RB, 0], [-RB, RB, 0], [0, 0, POST + 4], [-RJ, 0, BASE + JH + CH + LIFT], [0, -RJ, BASE + JH + CH + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the turntable: a large round, built with more steps
  const base = solid(g);
  put(base, prism(P, front, rrect(-RB, -RB, RB, RB, RB, 14), rrect(-RB + 1.6, -RB + 1.6, RB - 1.6, RB - 1.6, RB - 1.6, 14), 0, BASE));

  const jars = [];
  for (let k = 0; k < N; k++) {
    const a = (k / N) * Math.PI * 2 - Math.PI / 4;
    jars.push({ k, x: RJ * Math.cos(a), y: RJ * Math.sin(a), z: tween(REST[k]), last: NaN });
  }
  // paint order: far jars, then the post, then near jars
  const order = jars.slice().sort((p, q) => p.x + p.y - (q.x + q.y));
  let postDone = false;
  const post = () => {
    const s = solid(g);
    const [r, i] = rings(-2.4, -2.4, 2.4, 2.4, 2.4, 0.8);
    put(s, prism(P, front, r, i, BASE, POST));
    const knob = solid(g);
    const [r2, i2] = rings(-4.5, -4.5, 4.5, 4.5, 4.5, 1);
    put(knob, prism(P, front, r2, i2, POST, POST + 4));
  };
  order.forEach((j) => {
    if (!postDone && j.x + j.y > 0) { post(); postDone = true; }
    const grp = mk("g", {}, g);
    j.body = solid(grp); j.cap = solid(grp);
  });
  if (!postDone) post();

  function draw(j, lift) {
    if (lift === j.last) return;
    j.last = lift;
    const z0 = BASE + lift;
    const [r, i] = rings(j.x - JR, j.y - JR, j.x + JR, j.y + JR, JR, 1);
    put(j.body, prism(P, front, r, i, z0, z0 + JH));
    const c = JR + 0.6;
    const [rc, ic] = rings(j.x - c, j.y - c, j.x + c, j.y + c, c, 0.9);
    put(j.cap, prism(P, front, rc, ic, z0 + JH, z0 + JH + CH));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    jars.forEach((j) => { draw(j, tval(j.z, now)); if (!tdone(j.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: on a fixed plane through the resting jars, nearest jar centre
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, BASE + JH / 2);
    let best = -1, bd = 11;
    jars.forEach((j) => { const d = Math.hypot(x - j.x, y - j.y); if (d < bd) { bd = d; best = j.k; } });
    return best;
  }
  const ring = (k, a) => { const d = Math.abs(k - a); return Math.min(d, N - d); };

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    jars.forEach((j) => {
      const z = a < 0 ? REST[j.k] : j.k === a ? LIFT : clamp(BUMP - 1.5 * ring(j.k, a), 0, BUMP);
      tset(j.z, z, now, from < 0 ? 0 : ring(j.k, from) * stag);
      const on = j.k === (a < 0 ? FAV : a);
      j.body.sil.classList.toggle("hi", on); j.cap.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "jar " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "spicecarousel",
  means: "A spice carousel: the jar under the pointer lifts off the turntable, its neighbours rise a little round the ring.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[200, 134], [248, 191], [152, 191], null],
  mount,
});

blenderjug.code:
/**
 * Blender: a squat motor base with a row of four speed buttons on its front
 * ledge, a jug that widens to its rim, and a lid. The pointer picks a speed
 * by where it is along the buttons: that button sinks, the others spring up
 * staggered from it, and the lid rides up the faster the speed. At rest the
 * lowest speed is held in, bright.
 *
 * The pattern: one of many in a single row; the hit is the nearest button's
 * rest centre by screen x. The jug is a solid whose top is larger than its foot.
 */
const {
  Cam, clamp, facing, fit, hull, open, poly, prism, proj, rings, ringAt, rrect, run, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, BH = 12, BTN = 2.6, J0 = BH + 1, J1 = 46, LH = 3.5, LIFT = 2.2, FAV = 0;
const BX = [-10.5, -4, 2.5, 9];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.8);
  fit(C, [[-15, -15, 0], [15, 21, 0], [15, -15, 0], [-15, 21, 0], [-12, -14, J1 + LH + LIFT * 3], [12, 10, J1 + LH + LIFT * 3]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the motor base, with a front ledge for the buttons
  const base = solid(g);
  const [br, bi] = rings(-15, -15, 15, 21, 6, 1.6);
  put(base, prism(P, front, br, bi, 0, BH));

  // the jug: foot smaller than rim, hull of two rings
  const foot = rrect(-9, -11, 9, 7, 6, 6), top = rrect(-12, -14, 12, 10, 8, 6), inner = rrect(-10.6, -12.6, 10.6, 8.6, 6.6, 6);
  const jug = solid(g);
  jug.sil.setAttribute("d", poly(hull(ringAt(P, foot, J0).concat(ringAt(P, top, J1)))));
  jug.cr.setAttribute("d", open(ringAt(P, run(inner, front), J1)));
  const lid = solid(g), lz = tween(0);
  let lidLast = NaN;

  const btns = BX.map((x, k) => ({ k, x, s: solid(g), z: tween(k === FAV ? 0 : BTN), last: NaN }));

  function drawBtn(b, h) {
    if (h === b.last) return;
    b.last = h;
    const [r, i] = rings(b.x, 13, b.x + 4.6, 18.5, 1.6, 0.6);
    put(b.s, prism(P, front, r, i, BH, BH + 0.6 + h));
  }
  function drawLid(z) {
    if (z === lidLast) return;
    lidLast = z;
    const [r, i] = rings(-12.6, -14.6, 12.6, 10.6, 8.4, 1.4);
    put(lid, prism(P, front, r, i, J1 + z, J1 + z + LH));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    btns.forEach((b) => { drawBtn(b, tval(b.z, now)); if (!tdone(b.z, now)) moving = true; });
    drawLid(tval(lz, now));
    return moving || !tdone(lz, now);
  });
  bag.add(B.unregister);

  // the hit: inside the figure's span on the ledge plane, nearest button by screen x
  const cx = btns.map((b) => P(b.x + 2.3, 15.7, BH)[0]);
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, BH);
    if (x < -40 || x > 24 || y < -40 || y > 26 || x + y < -50) return -1;
    let best = 0;
    cx.forEach((c, k) => { if (Math.abs(c - sx) < Math.abs(cx[best] - sx)) best = k; });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const sel = a < 0 ? FAV : a;
    btns.forEach((b) => {
      tset(b.z, b.k === sel ? 0 : BTN, now, from < 0 ? 0 : Math.abs(b.k - from) * stag);
      b.s.sil.classList.toggle("hi", b.k === sel);
    });
    tset(lz, a < 0 ? 0 : clamp(a + 1, 0, N) * LIFT * 0.75, now, 0);
    read.textContent = a < 0 ? "rest" : "speed " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "blenderjug",
  means: "A blender: the speed button under the pointer sinks in, the others pop up, and the lid rides up as the speed climbs.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[144, 222], [179, 240], [196, 248], null],
  mount,
});

satchels.code:
/**
 * Satchels: a row of school satchels hanging by their straps from the hooks
 * of a cloakroom board. The pointer picks a satchel by where it is along the
 * row: that bag is lifted up to its hook, the others hitch up a little,
 * staggered from it. At rest the bags hang at uneven drops, one bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is the nearest resting
 * centre by screen x, inside the row's fixed band.
 */
const {
  Cam, clamp, facing, fit, open, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 18, X0 = 8, W = 6.5, Y0 = 4, Y1 = 9, H = 17, HOOK = 53;
const REST = [41, 44, 38, 43, 40], FAV = 2, LIFT = 49, BUMP = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const XE = X0 + (N - 1) * STEP;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[-6, -3, 63], [XE + 12, -3, 63], [-6, Y1, 18], [XE + 10, Y1, 18], [XE + 10, Y1, 63]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the cloakroom board, and a hook per peg
  const board = solid(g);
  put(board, prism(P, front, ...rings(-6, -3, XE + 12, 0, 1.4, 0.5), 50, 63));
  for (let k = 0; k < N; k++) {
    const hk = solid(g), x = X0 + k * STEP;
    put(hk, prism(P, front, ...rings(x - 1.5, 0, x + 1.5, 4, 1.2, 0.5), HOOK - 2, HOOK + 1));
  }

  const bags = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    bags.push({
      x: X0 + k * STEP,
      strap: mk("path", { class: "nf lo" }, grp),
      s: solid(grp),
      flap: mk("path", { class: "nf lo" }, grp),
      z: tween(REST[k]),
      last: NaN,
    });
  }

  function draw(b, top) {
    if (top === b.last) return;
    b.last = top;
    const x = b.x, [r, i] = rings(x - W, Y0, x + W, Y1, 3, 1);
    put(b.s, prism(P, front, r, i, top - H, top));
    b.strap.setAttribute("d", seg(P(x - 4, 6.5, top), P(x, 2.5, HOOK)) + seg(P(x + 4, 6.5, top), P(x, 2.5, HOOK)));
    const f = [[-5.5, -0.8], [-5.5, -7], [-3, -9.5], [3, -9.5], [5.5, -7], [5.5, -0.8]].map(([u, v]) => P(x + u, Y1, top + v));
    b.flap.setAttribute("d", open(f) + seg(P(x, Y1, top - 9.5), P(x, Y1, top - 12.5)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    bags.forEach((b) => { draw(b, tval(b.z, now)); if (!tdone(b.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest resting centre by screen x, inside the band the row rests in
  const cx = bags.map((b, k) => P(b.x, 7, REST[k] - H / 2)[0]);
  const yTop = P(0, 0, 63)[1] - 4, yBot = P(XE, Y1, 18)[1] + 6;
  function hit([sx, sy]) {
    if (sx < cx[0] - 22 || sx > cx[N - 1] + 22) return -1;
    const a = P(0, 0, 0)[1], b = P(XE, 0, 0)[1], slope = (b - a) / (cx[N - 1] - cx[0]);
    const off = (sx - cx[0]) * slope;
    if (sy < yTop + off - 30 || sy > yBot - (b - a) + off + 30) return -1;
    let best = 0;
    cx.forEach((c, k) => { if (Math.abs(sx - c) < Math.abs(sx - cx[best])) best = k; });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    bags.forEach((b, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : clamp(REST[k] + BUMP - Math.abs(k - a), REST[k], LIFT - 2);
      tset(b.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      b.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "peg " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "satchels",
  means: "School satchels on a cloakroom board: the bag under the pointer is lifted to its hook, its neighbours hitch up after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[125, 157], [230, 204], [265, 229], null],
  mount,
});

lockpads.code:
/**
 * Lab stools: a row of round lab stools, each a weighted foot, a gas-lift
 * post and a round seat. The pointer picks a stool by where it is along the
 * row: its seat rises on the post, the others lift a little, staggered from
 * it. At rest the seats stand at uneven heights, one bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single row; the hit is the nearest resting
 * centre by screen x, inside the row's fixed band.
 */
const {
  Cam, circ, clamp, facing, fit, prism, proj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 22, X0 = 0, R = 7.5, FOOT = 6;
const REST = [24, 31, 21, 27], FAV = 1, LIFT = 38, BUMP = 3;

function at(ring, x, y) { return ring.map((s) => ({ ...s, u: s.u + x, v: s.v + y })); }

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const XE = X0 + (N - 1) * STEP;
  const C = Cam(45, 0.5, 3.4);
  fit(C, [[-R, -R, 0], [XE + R, R, 0], [-R, R, 0], [XE + R, -R, LIFT + 3], [-R, -R, LIFT + 3]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const stools = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP, grp = mk("g", {}, g);
    const foot = solid(grp), post = solid(grp), ring = solid(grp), seat = solid(grp);
    put(foot, prism(P, front, at(circ(FOOT, 24), x, 0), at(circ(FOOT - 1, 24), x, 0), 0, 1.6));
    stools.push({ x, post, ring, seat, z: tween(REST[k]), last: NaN });
  }

  function draw(s, z) {
    if (z === s.last) return;
    s.last = z;
    put(s.post, prism(P, front, at(circ(1.3, 16), s.x, 0), at(circ(0.7, 16), s.x, 0), 1.6, z));
    const fz = Math.min(12, z - 6);
    put(s.ring, prism(P, front, at(circ(5, 24), s.x, 0), at(circ(4.2, 24), s.x, 0), fz, fz + 0.8));
    put(s.seat, prism(P, front, at(circ(R, 28), s.x, 0), at(circ(R - 1.2, 28), s.x, 0), z, z + 3));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    stools.forEach((s) => { draw(s, tval(s.z, now)); if (!tdone(s.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest resting centre by screen x, inside the band the row rests in
  const cx = stools.map((s, k) => P(s.x, 0, REST[k] / 2)[0]);
  function hit([sx, sy]) {
    let best = 0;
    cx.forEach((c, k) => { if (Math.abs(sx - c) < Math.abs(sx - cx[best])) best = k; });
    const s = stools[best], top = P(s.x, 0, LIFT + 3)[1] - 12, bot = P(s.x, 0, 0)[1] + 16;
    if (Math.abs(sx - cx[best]) > 24 || sy < top || sy > bot) return -1;
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    stools.forEach((s, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : clamp(REST[k] + BUMP - Math.abs(k - a), REST[k], LIFT - 3);
      tset(s.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      s.seat.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "stool " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "lockpads",
  means: "A row of lab stools: the seat under the pointer rises on its post, the neighbouring seats lift a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[121, 128], [226, 181], [279, 207], null],
  mount,
});

bookreturn.code:
/**
 * Book trolley: a library return trolley, a deep tray on a low deck and four
 * castors, with returned books standing in the tray. The pointer picks a book
 * by where it is along the tray: it is drawn up out of the row, the others
 * lift a little, staggered from it. At rest the books stand at uneven heights,
 * one bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is the nearest resting
 * centre by screen x, inside the tray's fixed band. The tray's front lip and
 * end are painted after the books, so they hide the books' feet.
 */
const {
  Cam, circ, clamp, facing, fit, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 7, STEP = 6, X0 = 3, T = 4.2, Z0 = 9, LIP = 19;
const HT = [24, 19, 27, 21, 25, 18, 22], DEP = [11, 9, 12, 10, 11, 9, 10];
const FAV = 2, LIFT = 18, BUMP = 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const XE = X0 + (N - 1) * STEP + 4;
  const C = Cam(45, 0.5, 4.1);
  fit(C, [[-2, -1, 0], [XE + 2, 15, 0], [-2, 15, 0], [XE + 2, -1, 0], [X0, 1, Z0 + 27 + LIFT], [XE, 1, Z0 + 27 + LIFT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // castors, the deck, its posts, then the tray behind the books
  const deck = solid(g);
  [[1, 1], [XE - 1, 1]].forEach(([x, y]) => put(solid(g), prism(P, front, circ(1.6, 12).map((s) => ({ ...s, u: s.u + x, v: s.v + y })), circ(1, 12).map((s) => ({ ...s, u: s.u + x, v: s.v + y })), 0, 2.4)));
  put(deck, prism(P, front, ...rings(-1, -0.5, XE + 1, 14.5, 1.6, 0.6), 2.4, 4.2));
  mk("path", { class: "nf lo", d: seg(P(0.5, 0.5, 4.2), P(0.5, 0.5, Z0)) + seg(P(XE - 0.5, 0.5, 4.2), P(XE - 0.5, 0.5, Z0)) }, g);
  put(solid(g), prism(P, front, ...rings(-2, -1, XE + 2, 15, 1.8, 0.7), Z0, LIP));

  const books = [];
  for (let k = 0; k < N; k++) books.push({ x: X0 + k * STEP, s: solid(g), z: tween(0), last: NaN, k });
  // the tray's near end and front lip, painted over the books' feet
  put(solid(g), prism(P, front, ...rings(XE + 0.6, -1, XE + 2, 15, 0.6, 0.3), Z0, LIP));
  put(solid(g), prism(P, front, ...rings(-2, 13.6, XE + 2, 15, 0.6, 0.3), Z0, LIP));
  [[1, 14], [XE - 1, 14]].forEach(([x, y]) => put(solid(g), prism(P, front, circ(1.6, 12).map((s) => ({ ...s, u: s.u + x, v: s.v + y })), circ(1, 12).map((s) => ({ ...s, u: s.u + x, v: s.v + y })), 0, 2.4)));

  function draw(b, lift) {
    if (lift === b.last) return;
    b.last = lift;
    const z = Z0 + 1 + lift;
    put(b.s, prism(P, front, ...rings(b.x, 13 - DEP[b.k] - 1, b.x + T, 13, 0.8, 0.4), z, z + HT[b.k]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    books.forEach((b) => { draw(b, tval(b.z, now)); if (!tdone(b.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest resting centre by screen x, inside the band the tray rests in
  const cx = books.map((b) => P(b.x + T / 2, 8, Z0 + HT[b.k] / 2)[0]);
  function hit([sx, sy]) {
    let best = 0;
    cx.forEach((c, k) => { if (Math.abs(sx - c) < Math.abs(sx - cx[best])) best = k; });
    const b = books[best], top = P(b.x, 2, Z0 + 1 + HT[best] + LIFT)[1] - 6, bot = P(b.x, 15, 0)[1] + 6;
    if (Math.abs(sx - cx[best]) > 14 || sy < top || sy > bot) return -1;
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    books.forEach((b, k) => {
      const z = a < 0 ? (k === FAV ? 4 : 0) : k === a ? LIFT : clamp(BUMP - Math.abs(k - a), 0, BUMP);
      tset(b.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      b.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "book " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

